INSERT INTO `novels` (`id`, `url`, `title`, `author`, `summary`, `created_at`) VALUES
	(1, 'https://sangtacviet.com/truyen/69shu/1/53962/', 'Quý Hán Lưu Chương', 'Hoa Hoa Gia Thái Tuế', 'Xuyên qua vì cuối thời Đông Hán hoàng thúc, nhưng mà không có một đôi cái lỗ tai lớn, cũng không có đến đầu gối hai tay, chỉ vì ta là Lưu Chương, Lưu Quý ngọc......\nXem như đại hán hoàng thúc, Lưu Chương quyết tâm khai sáng thuộc về mình quý Hán.\nMột cái không giống nhau quý Hán, không có tam quốc đỉnh lập, không có đồ vật Lưỡng Tấn, không có Ngũ Hồ loạn hoa quý Hán.\nTiểu thuyết từ mấu chốt: Quý Hán Lưu Chương không pop-up, quý Hán Lưu Chương txt toàn tập download, quý Hán Lưu Chương chương mới nhất đọc', '2026-09-01T07:18:16.759563+00:00'),
	(7, 'https://sangtacviet.com/truyen/fanqie/1/7639189560613686297/', 'Màn Trời: Quyền Lực Diễn Biến Cùng Truyền Thừa', 'Quất Tọa A', 'Lý Ân phàm: Tại chúng ta mấy ngàn năm trong lịch sử, quyền hạn vốn là như vậy.\nCó lẽ quy định sẽ thành, lại có lẽ những thứ khác đều biết biến, nhưng không đổi, mãi mãi cũng là quyền hạn.', '2026-09-01T08:47:49.488544+00:00'),
	(26, 'https://sangtacviet.com/truyen/fanqie/1/7627737816302111769/', 'Trực Tiếp Mang Cổ Nhân Nhìn Mới Tam Quốc', 'Tửu Thần Bồ Đào Lục', 'Trực tiếp mang cổ nhân nhìn mới Tam quốc, Gia Cát nho nhỏ đại học trực tiếp kiếp sống, chưa có xem tiền văn cũng yên tâm lớn mật đi vào, ta liền cùng một chỗ đi theo chư hướng đám người cùng tới nhìn mới ba, cùng một chỗ chửi bậy!', '2026-09-02T04:27:59.602692+00:00'),
	(84, 'https://sangtacviet.com/truyen/fanqie/1/7399178905703173145/', 'Lịch Sử Trực Tiếp Gian: Ngẫu Nhiên Sáng Tạo Chết Một Vị Lão Tổ Tông', 'Miêu Miêu Nịnh', 'Hệ lịch sử tốt nghiệp tức thất nghiệp Đường Hân hân, quyết định một bên du lịch một bên trực tiếp phổ cập khoa học lịch sử, không nghĩ tới chính mình trực tiếp vậy mà có thể phát ra đến lịch sử vạn giới, bị các lão tổ nhìn thấy.\n【 Hôm nay tới tham quan Tần Thuỷ Hoàng lăng!】\nTần Thuỷ Hoàng: Trẫm lăng mộ!\nTé xỉu.jpg\n【 Tới tới tới, Thái Nguyên công tử Lý Nhị phượng, bị trộm đi khắc đá tuấn mã đồ!】\nĐường Thái Tông: Trẫm táp lộ tím!!\nXuất binh!\nXuất binh!\n【 Ai nha, Hán đại song bích!!\nLưu heo heo không biết xấu hổ cọ nhiệt độ!】\nHán Vũ Đế: Dựa vào cái gì trẫm là heo, cái này không công bằng!\nTrẫm có hai hảo tướng quân, những người khác nghĩ cọ còn không có cách nào cọ đâu!\nĐồ chơi gì? Nước Nhật tiến công Trung Nguyên?\nDiệt quốc!\nLập tức diệt quốc!!', '2026-09-03T15:04:49.265748+00:00'),
	(90, 'https://sangtacviet.com/truyen/69shu/1/87532/', 'Đại Đường Lý Thừa Càn: Thỉnh Bệ Hạ Xưng Vạn Tuế', 'Thái Thanh Yêu Đạo', 'Trinh Quán mười bốn năm, Thái tử lý Thừa Càn xuống ngựa trượt chân, kéo dài trị mà gây nên cà thọt.\nHậu tâm tính chất vặn vẹo, thậm chí đổ sinh hoa mắt ù tai.\nTrinh Quán mười bảy năm, Thái tử lý Thừa Càn mưu phản chưa thoả mãn, sự tình bại lộ, liền bị phế vì thứ dân, lưu vong kiềm châu.\nTrinh Quán 18 năm, tốt tại kiềm châu.\n......\nTrong bóng tối, lý Thừa Càn chậm rãi mở mắt.\nMột cái đến từ tương lai hơn nghìn năm sau đoạt xá thất bại linh hồn, không chỉ có đem hắn mang về đến Trinh Quán mười bốn năm xuống ngựa trượt chân sau đó, còn mang cho hắn tương lai hơn một ngàn năm sau ký ức cùng tri thức.\nLần này, hắn không chỉ có muốn đem chân thương chữa khỏi, còn muốn đem tất cả vốn nên thuộc về mình hết thảy toàn bộ đều đoạt lại.\n......\n“Thừa Càn, ngươi đang làm cái gì?”\n“Thỉnh bệ hạ xưng vạn tuế!”\n“Người tới, tiễn đưa thái thượng hoàng vào võ đức điện!”\nVõ đức, cao tổ hoàng đế Lý Uyên duy nhất niên hiệu.', '2026-09-03T23:54:29.545721+00:00'),
	(92, 'https://sangtacviet.com/truyen/fanqie/1/7481496454264015897/', 'Đại Hán Group Chat: Bắt Đầu Lưu Bang Đối Thoại Gia Cát Lượng', 'Ký Ức Trung Sảo Sảo', 'Đại hán group chat: Bắt đầu Lưu Bang, đối thoại Gia Cát Lượng\n【 Bắt đầu đại hán khai quốc hoàng đế đối thoại Thục Hán thừa tướng!\nVượt thời không group chat mở ra lịch sử nghịch tập!】\nLàm Lưu Bang từ Gia Cát Lượng trong miệng biết được Hán sơ lịch sử.\nLưu Bang trong đêm đạp tỉnh giả bệnh Hàn Tín, nắm chặt ẩn lui Trương Lương, màn sáng hất lên mau mau đứng lên cho chính là giải quyết việc công sống.\nGia Cát Lượng trong đêm chạy đến Tỉ Quy, nói cho Lưu Bị: Bệ hạ chúng ta nên thay đổi cách chơi .\n✓ Lưu Bang giận phun bốn trăm năm sau Lưu Bị không đủ lưu manh\n✓ Tiêu Hà cùng Gia Cát Lượng tại Hán quần giao chảy trị quốc tâm đắc\n✓ Hàn Tín viễn trình dạy quý Hán tướng lĩnh như thế nào đại binh đoàn chiến đấu\n✓ Trương Lương Trần Bình cùng Gia Cát Lượng nghiên cứu thảo luận quý Hán tương lai chiến lược\nLàm Lưu Bang phát hiện có thể kéo càng nhiều Hán triều quân chủ vào nhóm lúc, mỉm cười trực tiếp: @ Toàn thể thành viên Năm nay công trạng người không đạt tiêu chuẩn, đá nhóm!', '2026-09-04T11:55:03.339759+00:00');
INSERT INTO `chapters` (`id`, `novel_id`, `chapter_site_id`, `chapter_number`, `title`, `content`, `mp3_path`, `crawled_at`, `crawl_status`, `tts_status`, `tts_chars_total`, `tts_chars_done`) VALUES
	(1, 1, '34902840', 1, 'Thứ 1 chương Cuối thời Đông Hán', 'Thứ chương Cuối thời Đông Hán\nLưu Chương đánh giá bày ra ở trên bàn Tất Nhĩ Bôi , Do Mộc Thai nghiên cứu chế tạo , trong chén thoa sơn hồng , ly bên ngoài là màu đen , hình dáng trang sức thiết lập tại trong chén cùng miệng xuôi theo cùng trên hai lỗ tai .\nTất Nhĩ Bôi tính chất nhìn qua rất không tệ , nhưng trên thân ly đủ loại hình thái đánh gãy văn cùng vân da biến hóa , im lặng nói rõ cái này Tất Nhĩ Bôi đã là lâu năm lão vật , không biết bán trao tay bao nhiêu nhà . Cho nên lấy đồ sơn quý giá , mới luân lạc tới bị cái này ven đường quán rượu nhỏ lấy ra làm bề ngoài .\nTất Nhĩ Bôi trung chứa rượu là hồi hương rượu gạo , không phải mười phần thanh tịnh trong suốt , hơi vẩn đục .\nHắn cầm lấy Tất Nhĩ Bôi nhẹ nếm một ngụm , cái này rượu gạo độ cồn không cao , tư vị có chút nông cạn .\nSo với hắn cỗ thân thể này đã từng uống qua danh tửu , Trung sơn ‘ Đông Nhưỡng ’ cùng quan bên trong ‘ Bạch Bạc ’, kém hơn không thiếu . Lại cùng hắn kiếp trước đã từng uống qua thế kỷ hai mươi mốt rất nhiều rượu loại , hương vị càng là kém nhiều .\nCảnh còn người mất , uống rượu cũng không đồng dạng , Lưu Chương không còn tế phẩm , mà là uống một hơi cạn sạch .\nRượu bị uống cạn , Tất Nhĩ Bôi để lộ ra , màu đỏ sơn thực chất bên trên vẽ màu đen cuốn vân văn , trung tâm sách “ Quân Hạnh Tửu ” Ba chữ .\n‘ Quân Hạnh Tửu .’ Lưu Chương thưởng thức ba chữ này , không khỏi cảm thán hán đại người thực sự là rất có chủ nghĩa lãng mạn màu sắc , nho nhỏ ven đường tửu quán , đãi tới Tất Nhĩ Bôi để bên trên trả sách lấy như thế văn nhã ba chữ , khuyên khách hàng nhiều uống rượu .\nNghiêng đầu nhìn về phía ngoài tiệm , nấu rượu bán rượu quán rượu nhỏ cũng không có vách tường ngăn cản tầm mắt , tới gần đường cái một bên dùng chính là thấp bé hàng rào gỗ .\nĐây là một chỗ chợ , thành đô thị .\nCó bán rượu , bán sắt cỗ , bán tơ lụa . Vật có ngàn loại , hàng bán Bách gia . Rao hàng hàng hóa âm thanh liên tiếp , tiếng trả giá bên tai không dứt .\nThực sự là một chỗ phồn thịnh chợ , làm thiên hạ loạn lạc khăn vàng quân cũng không có tại Ba Thục đại địa hỗn loạn bao lâu , liền bị Ích châu xử lí Giả Long đã bình định , bởi vậy tại thiên hạ này loạn tung tùng phèo thời điểm , Ba Thục an ổn như Thái Sơn .\nNhìn xem cái này yên ổn tường hòa Hán đại phiên chợ , Lưu Chương ánh mắt có chút mê loạn .\nHắn cũng không phải hán đại người , chính xác điểm là hắn giờ phút này trong thân thể linh hồn cũng không phải hán đại người , hắn đến từ thế kỷ 21 .\nĐời trước của hắn là một tên xã súc , một lần tăng ca đến rạng sáng , tan tầm băng qua đường thời điểm , bị một chiếc hướng tạp xe ben đụng bay , chết tại chỗ .\nThân thể của hắn mặc dù tiêu tan , nhưng mà linh hồn của hắn phụ thân đến cuối thời Đông Hán , Ích Châu Mục Lưu Yên con trai thứ bốn , Lưu Chương , Lưu Quý Ngọc trên thân .\nHắn xuyên qua .\nTùy theo hoàn cảnh tính cách để cho Lưu Chương rất nhanh đón nhận đây hết thảy , hắn xét lại phía dưới tình trạng trước mặt .\nThời gian bây giờ là hưng bình năm đầu .\nTiền nhiệm Ích Châu Mục , tiện nghi của hắn lão cha Lưu Yên vừa mới chết bệnh , Ích châu các trọng thần , châu dưới trướng Tư Mã Triệu Vĩ cùng trị bên trong xử lí Vương Thương bọn người nhìn trúng tính cách mềm yếu Lưu Chương , đề cử Lưu Chương kế thừa Ích Châu Mục vị trí , hợp phái người hướng triều đình phát đi thông tri .\nXem như đại hán mười ba châu một trong Ích Châu Nhân khẩu , đông đảo , sĩ dân giàu có , danh xưng ‘ Kho của nhà trời ’. Tại cái này cuối thời Đông Hán loạn thế , có thể ngồi trên Ích Châu Mục vị trí , có thể nói là chư hầu một phương , đại quyền trong tay .\n‘ Chỉ là , cái này Ích Châu Mục vị trí , không tốt lắm ngồi a .’ Lưu Chương lộ ra một nụ cười khổ , hắn cảm giác mình ngồi ở một cái không biết lúc nào núi lửa bộc phát trên miệng .\nTừ nội bộ giảng , hắn có một cái ca ca Lưu Mạo , dựa theo truyền thống trưởng ấu có thứ tự , leo lên Ích Châu Mục vị trí người hẳn là Lưu Mạo , mà không phải hắn người em trai này .\nTừ bên ngoài giảng , Ích châu các trọng thần đề cử Lưu Chương làm Ích Châu Mục , cũng không phải tâm duyệt thành phục đề cử , mà là bởi vì hắn tiền thân làm người mềm yếu , thuận tiện điều khiển thôi .\nNgoài ra còn có chủ khách mâu thuẫn , phụ thân hắn Lưu Yên nể trọng Đông Châu Nhân , cùng Ích châu người bản thổ mâu thuẫn rất sâu .\nĐông Châu Nhân là Nam Dương cùng quan bên trong tam phụ địa khu người , bọn hắn vì trốn tránh binh tai , chạy nạn đến Ích châu .\nBọn này chạy nạn đến Ích Châu Nhân , bởi vì rời đi cố thổ , chưa quen cuộc sống nơi đây , hoang mang , bị Lưu Yên nhìn trúng , coi là chính mình vây cánh . Đông Châu Nhân vừa vặn không có dựa vào , bây giờ có người nguyện ý thu lưu bọn hắn , bọn hắn một cách tự nhiên hội tụ đến Lưu Yên dưới trướng .\nLưu Yên vì ngồi vững vàng Ích Châu Mục vị trí , lợi dụng Đông Châu Nhân chèn ép Ích châu bản thổ đích sĩ nhân , dẫn đến hai phe quan hệ có thể nói là thế như thủy hỏa .\nLàm một cái Tam quốc mê Lưu Chương , hắn nhớ rõ , tại Kiến An 5 năm thời điểm , Đông Châu Nhân hòa Ích Châu Nhân mâu thuẫn cuối cùng bạo phát , xảy ra một hồi họa loạn toàn bộ Ba Thục đại chiến .\nLưu Chương cảm giác có chút đau răng , Ích châu địa lôi nhiều lắm , nếu muốn ở ở đây vững vững vàng vàng sống sót , cần đem những vấn đề này giải quyết đi , nếu không mình sợ là chết như thế nào cũng không biết .\nMột tiếng có chút non nớt lời nói cắt đứt Lưu Chương suy tư : “ Công tử , cái này hồi hương rượu đế uống có gì ngon , nơi nào so ra mà vượt trong phủ đồ rõ ràng .”\nLưu Chương quay đầu đi , nhìn về phía ngồi ở hắn bên trái Bàng Khuyết , đây là một cái thanh tú thiếu niên , thân phận là châu mục trong phủ chủ sự bàng tĩnh nhi tử , từ Lưu Chương Sơ bình hai năm đến Ích châu sau , cũng là Bàng Khuyết tại phục thị Lưu Chương .\nBàng Khuyết nói tới đồ rõ ràng là Ba Thục danh tửu , thiếu niên uống qua Ba Thục danh tửu , đã không xem trọng cái này hồi hương rượu đế .\nLưu Chương cười lắc đầu , nhẹ nhàng vỗ vỗ Bàng Khuyết đầu , nói : “ Tuổi còn nhỏ , ngươi biết cái gì , công tử ta uống không phải rượu , là nhân tình , là lõi đời .”\nNgồi ở trong tửu phô , một bên phẩm tửu , vừa quan sát thời đại này chúng sinh , đối với Lưu Chương tới nói có một phen đặc biệt tư vị , hắn cần thâm nhập hiểu rõ thời đại này .\nĐối diện buôn bán tơ lụa cửa hàng , sạp hàng tiền trạm lấy hai tên tú khí thiếu nữ , hấp dẫn lấy Lưu Chương chú ý , nhìn qua là một chủ một bộc , làm chủ tử thiếu nữ dường như nhìn trúng một thớt đạm nhã gấm Tứ Xuyên , tại cùng tiểu phiến cò kè mặc cả lấy .\nMua sắm chuyện này , thực sự là từ cổ chí kim cũng là đã hình thành thì không thay đổi , mua bán song phương từ đầu đến cuối cần cò kè mặc cả .\nLúc này quán rượu đi tới hai người , cầm đầu là tên thân mang thanh sắc quan phục tráng hán , dài mặt trắng không râu , khí vũ hiên ngang , to con cơ thể quả thực là đem trên thân thả lỏng thanh y chống đỡ hơi căng cứng .\nLưu Chương không khỏi đáy lòng khen một câu , khá lắm điêu luyện hán tử .\nĐi theo hán tử có chút gầy gò , mặc đoản đả , trên đầu mang theo cái mũ rộng vành .\nHai người này tìm một cái thanh tĩnh vị trí ngồi xuống , Ôn Thượng hai bầu rượu sau , tán gẫu .\nMặc dù cách có chút xa , nhưng trời sinh thính tai Lưu Chương , có thể mơ hồ nghe được hai người nói chuyện đôi câu vài lời , chỉ nghe cái kia hán tử gầy gò dùng khuyên bảo ngữ khí nói .\n“ Cừ soái , các huynh đệ rất là tưởng niệm ngươi .”\n“ Tại Ba Quận khoái hoạt , tốt hơn tại cái này thành cũng làm cái mặc người sai sử quan lại .”\nCừ soái cái từ này , để cho Lưu Chương có chút kinh ngạc , không có nghĩ rằng vị này thanh y tráng hán vẫn là Ba Quận cái nào đó tổ chức vũ trang thủ lĩnh , chỉ là tráng hán không làm đại ca , chạy đến thành đều làm quan .\nĐi theo tên kia hán tử gầy gò giống đang khuyên đạo vị này đã từng đại ca , cởi quan phục , tiếp tục dẫn dắt thủ hạ các huynh đệ phát tài .\nHắn đây là tại cuối thời Đông Hán sao , hai người đối thoại cho Lưu Chương cảm giác , giống như là bến nước Lương Sơn phát sinh cố sự , một đám hảo hán năm lần bảy lượt thỉnh Tống Giang tụ nghĩa .\nCái kia hán tử gầy gò còn tại khuyên bảo , âm thanh đè thấp : “ Tân nhiệm Ích Châu Mục là Lưu Chương , nghe người này nhu nhược vô năng , huynh trưởng ở đây nhất định không thể trở nên nổi bật .”\n“ A Cửu , ngươi nói ta làm sao không biết .” Thanh y tráng hán uống vào một chén rượu , có chút bất đắc dĩ : “ Chỉ là gia mẫu không vui ta du hiệp .” Nói đến đây , thanh y tráng hán ngừng lại , chỉ là uống rượu , không còn trả lời , thần sắc nhưng có chút dao động .\nLưu Chương có chút dở khóc dở cười , ăn dưa ăn đến trên người mình , còn bị người xem như mặt trái tài liệu giảng dạy , hắn không có đi đi vì chính mình biện bạch , mà là lại uống vào một ly rượu gạo , tự hỏi không thể lại treo lên cái nhu nhược vô năng xưng hào , bằng không thì đều không người đi nương nhờ hắn .\nĐột nhiên quán rượu bên ngoài truyền đến rối loạn tưng bừng , một tiếng giống như hoàng oanh thanh thúy giọng cô gái truyền đến : “ Còn xin Đô úy tự trọng .”\nQuán rượu đám người nhao nhao đem ánh mắt nhìn về phía ngoài tiệm trên đường cái .\n5 cái đầu đội Vũ Quan , mặc bên ngoài giáng bào áo mỏng hán tử , ngăn cản vừa mới mua sắm gấm Tứ Xuyên cái kia hai thiếu nữ .\nCầm đầu Đô úy lại là không có chút nào tự trọng , mở miệng khinh bạc nói : “ Tiểu nương âm thanh thực sự là êm tai , không cần gọi ta đều úy , tiếng la tướng quân tới nghe một chút .”\nĐi theo Đô úy 4 cái hán tử tùy theo phát ra vui sướng cười nói .\nĐông Châu Nhân , là từ quan bên trong Đông Châu Nhân , Lưu Chương từ khẩu âm phân biệt ra đám người này tới chỗ , trước mặt mình vừa nghĩ đến liên quan tới Đông Châu Nhân vấn đề , đám người này liền nhảy ra ngoài .\nTiện nghi của hắn lão cha Lưu Yên thực sự là quá mức buông thả Đông Châu Nhân , dẫn đến bọn này Đông Châu binh giữa ban ngày , liền dám ở trên đường cái ngang ngược phạm pháp , khi dễ Ích Châu Nhân .\nKhó trách Kiến An 5 năm thời điểm , Ích châu đại thần triệu vĩ có thể dễ dàng kích động Thục nhân khởi xướng một hồi phản loạn , kém chút để cho Lưu Chương mất mạng .\nNơi đó có áp bách , nơi đó liền có phản kháng , Ích Châu Nhân bị Đông Châu Nhân ức hiếp quá lâu .\nLưu Chương thở dài , chuẩn bị đứng dậy , dự định ngăn cản bọn hắn , không thể tùy ý Đông Châu Nhân tiếp tục như vậy , hắn còn nghĩ an ổn sống lâu 2 năm .\nLúc này lại nghe được phía trước vị kia được xưng là Cừ soái thanh y tráng hán một chưởng vỗ nát bàn rượu , hướng về quán rượu bên ngoài gầm thét một tiếng .\n“ Tặc tử ngươi dám .”\n( Tấu chương xong )', 'output\\mp3\\Quý Hán Lưu Chương\\0001_Thứ 1 chương Cuối thời Đông Hán.mp3', '2026-09-01T07:31:36.760915+00:00', 'completed', 'completed', 10368, 10368),
	(2, 1, '34902841', 2, 'Thứ 2 chương Phách lối Đông Châu binh', 'Thứ chương Phách lối Đông Châu binh\nĐô úy Từ Mãnh bây giờ cảm thấy hắn sáng sớm mới ra cửa doanh thời điểm , nghe được một tiếng kia quạ đen kêu xác thực không rõ .\nHôm nay hắn cùng bình thường một dạng , tại quân doanh nghỉ mộc thời điểm , đến thành đô thị tụ tập thượng du đãng một chút , suy nghĩ mua chút đồ vật , tìm chút việc vui .\nChuyện phát sinh gần đây để cho trong lòng của hắn có chút buồn khổ , hắn là quan bên trong người , vốn là hắn suy nghĩ đi theo phía trước Ích Châu Mục Lưu Yên , Lưu Yên làm người thông minh tháo vát , chí hướng rộng lớn , hắn còn có thể có cơ hội đánh về quan bên trong quay về cố hương .\nNhưng mà Lưu Yên đột nhiên bệnh chết , tân nhiệm Ích Châu Mục là hắn con trai thứ bốn , Lưu Chương , nghe nói Lưu Quý Ngọc cái này người tính cách mềm yếu vô năng , cái này , hắn sợ là đời này đều không trở về được Quan Trung .\nVừa vặn tại thị tập bên trên đụng tới hai cái tú khí muội tử , hắn liền nghĩ mở miệng chiếm chiếm tiện nghi , hài lòng một chút liền đi , không nghĩ tới đầu tiên là nhảy ra một cái thanh y tráng hán , lại cùng nhảy ra một cái cẩm y ngọc phục công tử , đi ra sờ hắn xúi quẩy .\nTừ Mãnh dáng dấp thô cuồng nhưng mà làm người cẩn thận , vị kia thanh y tráng hán hắn cũng không để ý , từ quan phục đến xem , có thể là gánh Thục quận phủ Thái Thú quận thừa , Gia Tào một loại chức quan , bất quá nhà mình là Đô úy , quận thừa , Gia Tào có thể không quản được chính mình , cho nên không cần đến để bụng .\nThế nhưng là vị này ung dung hoa quý , cẩm y ngọc phục công tử sợ là cái nào đó đại tộc xuất thân , trong nhà nói không chừng có 2000 thạch hoặc là trong quân đội tướng tá , nghe thanh âm không phải đất Thục người , bên cạnh đi theo một gã sai vặt cùng 4 cái tùy tùng , 4 cái tùy tùng người người tinh hãn , không phải dễ đối phó , nếu như dây dưa bên trên sợ là không tốt tuột tay .\nTừ Mãnh hướng về phía tên kia công tử áo gấm khuyên : “ Vị công tử này , nghe lời ngươi khẩu âm cũng không phải Ích Châu Nhân , tội gì thay bọn hắn bọn này trong bụng có trùng Thục nhân giương mắt .”\nĐối mặt Từ Mãnh thuyết phục , Lưu Chương một là cảm thấy hắn tiền thân thật là Thái Ôn Nhân mềm yếu rồi , tính tình nội liễm nhanh , đi tới Ích châu sau ít có gặp người , chỉ ở Châu Mục phủ ổ lấy , càng là ở thành phố bờ giếng không người nhận ra thân phận của hắn , trước mặt vị này Đô úy cũng không biết được hắn , bất quá cái này cũng là hắn có can đảm cải trang vi hành , cải trang du lịch nguyên nhân .\nHai là hắn nghe được Từ Mãnh nói Thục nhân trong bụng có trùng , không phải lương nhân , bỗng cảm giác có chút dở khóc dở cười , cái này hán đại địa vực đen thật là đủ hắc , hắn sửa sang một chút mạch suy nghĩ , cao giọng phản bác Từ Mãnh nói : “ Hán gia trộn lẫn vũ nội , vũ nội đều là một nhà , không có cái gì Thục nhân , có chỉ là người Hán , ta không phải là vì Thục nhân giương mắt , là vì người Hán giương mắt .”\n“ Vị công tử này nói hay lắm .” Cường tráng Thanh Y Quận thừa tán dương một câu , hướng về phía Từ Mãnh lên tiếng chất vấn : “ Các ngươi Đông Châu Nhân , từ tha hương chạy nạn đến ta Ích châu , chúng ta hảo tâm thu dưỡng các ngươi , cung cấp các ngươi áo cơm , các ngươi còn dám khi dễ Ích châu phụ nữ trẻ em , thực sự là không làm nhân tử .”\nTừ Mãnh hữu chút đau đầu , vị công tử này khó chơi , nhất định phải vì Ích Châu Nhân ra mặt , cái này Thanh Y Quận thừa cũng là tại cái này hung hăng càn quấy . Vị công tử này ta khó đối phó , trước tiên đối phó tên này Thanh Y Quận thừa , như thế nào cũng không thể để Ích Châu Nhân đè ép một đầu , truyền đi không mặt mũi thấy người .\n“ Chúng ta Đông Châu Nhân không phải là các ngươi Ích Châu Nhân thu lưu , mà là nguyên nhân Lưu Ích Châu ( Lưu Yên ) thu lưu , áo cơm cũng là Lưu Ích Châu phát hạ , không phải các ngươi Ích Châu Nhân , ta nhưng không có chịu các ngươi Ích Châu Nhân ân huệ , ta chịu là Lưu Ích Châu ân huệ , ngươi cái này quận thừa chớ có chiếm tiện nghi ta .”\nNói xong Từ Mãnh quét một vòng chung quanh xông tới ăn dưa quần chúng , người hơi nhiều , không tốt thu tràng , lúc này tuyệt đối không thể cúi đầu , bằng không thì sau này không tốt gặp người .\nThanh Y Quận thừa bị Từ Mãnh đáp lời ngăn chặn , dựa theo quân tử ăn lộc , trung với quân chuyện thuyết pháp , bọn này Đông Châu Nhân đích thật là chịu Lưu Yên ân huệ .\nHắn vẫn là không quá am hiểu ngôn ngữ , một đôi nắm đấm không khỏi nắm chặt , nếu không phải hắn đáp ứng lão mẫu , thật tốt làm một cái quận thừa , không còn vũ đao lộng bổng , dựa theo hắn những ngày qua tính tình , đụng tới loại chuyện này , đâu còn sẽ tiến hành trong lời nói tranh phong , đã sớm xách theo Hoàn Thủ Đao làm .\n“ Lưu Ích Châu phát hạ áo cơm ?” Lưu Chương hỏi ngược một câu , hắn nhìn thấy Thanh Y Quận thừa biểu hiện , biết hắn không thích hợp loại này thi biện luận , thế là đứng dậy , cất cao giọng nói .\n“ Lưu Ích Châu một người có thể cày nhiều như vậy phải địa , một cái có thể dệt nhiều như vậy phải bố , cho các ngươi phát hạ áo cơm .”\nĐến phiên Từ Mãnh bị ngăn chặn miệng , một phương diện hắn sợ ném chuột vỡ bình , không dám cùng vị này công tử áo gấm đối kháng , một phương diện hắn dù sao cũng là một võ nhân , cuối cùng tại trên biện luận rơi xuống tầm thường .\nLưu Chương rèn sắt khi còn nóng , không cho Từ Mãnh cãi cơ hội : “ Các ngươi áo cơm cũng là trong phủ khố phát ở dưới , phủ khố bên trong áo cơm đâu , lại là từ Thục nhân trong tay thượng chước .”\n“ Nói cách khác , Thục trung bách tính chính là ngươi áo cơm phụ mẫu .”\nLưu Chương ngữ điệu chuyển trọng , quát lên : “ Ngươi có biết , khi dễ cha mẹ của mình , là bực nào tội .”\nLưu Chương trực tiếp đóng một đỉnh bất hiếu mũ tại Từ Mãnh trên đầu , tại Hán đại , bất hiếu hành vi tội danh được xưng là “ Thí thân tội ”, là một hạng cực kỳ nghiêm trọng tội ác , thí thân tội trừng phạt có thể bao quát chém đầu , đun nấu , lưu vong chờ cực kỳ tàn khốc xử phạt .\nĐồng thời , Hán luật còn quy định “ Tam Tuyệt ” Quy định , tức đời thứ ba trong vòng thân thuộc , nếu có phạm nhân bất hiếu tội , thì liên đới chế , toàn cả gia tộc đều sẽ bị xử phạt .\nĐây là một hạng cực kỳ nghiêm trọng lên án .\nBên cạnh thân Thanh Y Quận thừa nhãn tình sáng lên , cái tội danh này hắn quen thuộc , tiếp lời nói : “ Khi dễ phụ mẫu , là lớn bất hiếu tội .”\nMột lời đã nói ra , chung quanh quần chúng vây xem lập tức tuôn ra tiếng khen , bọn hắn ngày thường cũng không ít chịu Đông Châu Nhân ức hiếp , giờ phút này phẫn nộ trút xuống , mặc dù ngày thường không dám xuất đầu , nhưng có người ra mặt tình huống phía dưới , đi theo gọi hai tiếng dũng khí vẫn phải có .\n“ Nói rất hay .”\n“ Vị công tử này nói rất hay .”\n“ Vị này quận thừa nói rất hay ”\nNghe đến mấy cái này tiếng khen , Lưu Chương mặt như thường sắc , Thanh Y Quận thừa có chút đắc ý , hắn ưa thích loại này chúng tinh phủng nguyệt không khí .\nĐứng tại đối diện Từ Mãnh sắc mặt hơi khó coi , nửa là xấu hổ nửa là không phục , xấu hổ là bởi vì hắn cảm thấy vị công tử này nói có chút đạo lý , chính mình hành vi theo hắn nói đích thật là để cho người ta hổ thẹn , hắn vẫn là đọc qua chút sách , biết chút ít lễ nghĩa liêm sỉ . Không phục là tại chỗ nhiều người như vậy , hắn là tuyệt đối không thể cúi đầu , người sống một miếng da .\nTừ Mãnh cứng cổ , úng thanh phản bác : “ Nói nhăng nói cuội , tận thả rắm chó .”\nVạch mặt một câu sau , Từ Mãnh Đả tính toán ly khai nơi này , dưới loại tình thế này không dễ động thủ , nói như vậy nói không lại nhân gia , chạy là thượng sách .\nTrước khi đi hắn hỏi một câu : “ Là anh hùng , là hảo hán , liền lưu lại tính danh .”\nTừ Mãnh Đả tính toán trước hỏi rõ sở hai người dòng họ , hỏi thăm lối vào , còn nhiều thời gian , sau này có thể tìm cơ hội thật tốt xử lý một phen .\nLời này hỏi ý vừa ra , còn đắm chìm tại chung quanh bách tính tiếng khen bên trong Thanh Y Quận thừa lập tức mặt lộ vẻ vui mừng , đến hắn thích nhất khâu Làm việc lưu danh , ho nhẹ một tiếng , đem âm thanh đặt lên mấy phần vang dội độ , trước tiên mở miệng : “ Mỗ là Ba Quận người , họ cam tên thà ......”\n“ Cam Hưng Bá .”\nCam Ninh còn chưa báo xong tính danh liền bị Lưu Chương cắt đứt , Lưu Chương giờ phút này có chút mộng nhiên , cái này Thanh Y Quận thừa càng là Cam Hưng Bá , khu vực phía nam Trường Giang chi hổ thần Cam Hưng Bá Trăm kỵ kiếp Tào Doanh Cam Hưng Bá Bị Tôn Quyền tán thưởng vì Mạnh Đức có Trương Liêu , cô có Hưng Bá , đủ tương địch cũng Cam Hưng Bá .\nLưu Chương đi tới nơi này cái thời đại cũng có chừng mười ngày , nhưng mà Tam quốc danh nhân còn không có gặp qua .\nCam Ninh trên mặt vui mừng mạnh hơn : “ Vị công tử này nghe qua mỗ danh tự .” Hắn tại Ba Quận là cái nhân vật nổi tiếng , nhưng mà ra Ba Quận cũng rất ít có người nhận ra hắn , lúc này Lưu Chương một lời nói ra tên của hắn , để cho hắn có chút cao hứng .\nHắn nhìn về phía Lưu Chương , trước mặt vị công tử này hào khí vô song , càng thêm ăn nói khéo léo , quan trọng nhất là , lại biết mình tên , Cam Ninh cảm thấy thực sự là hận gặp nhau trễ , hận không thể tại chỗ kết nghĩa .\n“ Nghe qua Hưng Bá chi danh , chỉ là vô duyên gặp gỡ .” Lưu Chương cũng không phải khách sáo , đây là thật sự trong lòng nói , vị này chính là Cam Ninh , Giang Đông đấu tướng đệ nhất Cam Ninh , người trong lịch sử vật đứng ở trước mặt mình .\nĐang lúc hai người thoải mái ở giữa , một tiếng không thân thiện lời nói truyền đến , “ Ta đạo là nhân vật nào , nguyên lai là cái ba rất .”\nTừ Mãnh trong lời nói có chút khinh thường , lại bắt đầu địa vực đen , hắn cũng không có nghe qua Ba Quận có họ Cam đại tộc , bởi vậy đối với Cam Ninh không để trong lòng , hắn quay đầu vấn đạo Lưu Chương : “ Không biết vị công tử này tính danh .”\nCam Ninh trong lòng tức giận , sắc mặt tăng hồng nhuận , chỉ là không tiện phát tác , trong lòng âm thầm phát thệ , có cơ hội nhất định muốn làm thịt cái này Đông Châu Nhân .\nLưu Chương mỉm cười , chắp tay , hồi đáp : “ Tại hạ Giang Hạ Cánh Lăng người , họ Lưu tên chương , chữ quý ngọc .”\n“ Lưu Quý Ngọc đúng không , chính là công nhớ ......” Từ Mãnh ghi nhớ cái tên này , suy nghĩ thuận miệng đáp lại một câu hắn ghi nhớ danh tự này , sau đó rời đi chỗ thị phi này , nhưng mà nói được nửa câu , hắn tựa hồ nhớ tới cái gì , ngạnh sinh sinh một câu nói còn chưa nói hết .\nTừ Mãnh chỗ sâu trong óc dâng lên một cái ý nghĩ đáng sợ , không chỉ là hắn , bên người hắn mấy người cũng là mặt lộ vẻ vẻ do dự , dằn xuống tâm tình bất an , Từ Mãnh mở miệng , mang theo hơi thanh âm rung động , hắn dò hỏi .\n“ Cái nào Lưu ?”\nTừ Mãnh còn ôm lấy một tia may mắn , hy vọng không phải kim đao Lưu .\n( Tấu chương xong )', 'output\\mp3\\Quý Hán Lưu Chương\\0002_Thứ 2 chương Phách lối Đông Châu binh.mp3', '2026-09-01T07:31:41.507891+00:00', 'completed', 'completed', 10410, 10410),
	(3, 1, '34902842', 3, 'Thứ 3 chương Kim đao Lưu', 'Thứ chương kim đao lưu\nTừ Mãnh không có nghe được hắn mong muốn trả lời , chỉ nghe thấy đối diện vị công tử này nói ra , giống như là mở ra nước đá , tưới lên tâm hỏa của hắn bên trên , rõ ràng hiện tại cũng vào hạ , nhưng hắn cảm giác chính mình một chân bước vào trời đông giá rét thời tiết , rơi xuống cái băng hỏa lưỡng trọng thiên .\n“ Thiên hạ có mấy cái Lưu , Kim Đao Lưu a .”\nLưu Chương đôi câu vài lời , bóp chết Từ Mãnh nội tâm may mắn .\nGiang Hạ Cánh Lăng người , quê quán xứng đáng , Kim Đao Lưu , dòng họ xứng đáng , Lưu Chương Lưu Quý Ngọc , tên cùng chữ đối mặt .\nTừ Mãnh mặt lộ vẻ khổ tâm , sớm biết buổi sáng hôm nay nghe được quạ đen gọi liền không ra khỏi cửa , quá không may mắn , vậy mà cùng mới người lãnh đạo trực tiếp Lưu Chương chống đối . Bây giờ châu mục giống như Xuân Thu Chiến Quốc chư hầu vương , tại nhà mình lãnh địa quyền lợi cực lớn , là tuyệt đối không thể làm tức giận .\nLưu Chương bên cạnh thân Cam Ninh nhưng là trợn to hai mắt , thần sắc có chút kinh ngạc , không nghĩ tới vị này cùng hắn hào khí tương đắc công tử lại là Lưu Quý Ngọc , Lưu sứ quân .\nĐột nhiên Cam Ninh đáy lòng thầm nghĩ không tốt , sắc mặt biến phải co quắp , Lưu Chương biết họ của hắn thị , sẽ không biết hắn tại ba quận làm sự tình a .\nHắn thuở thiếu thời hảo du hiệp , ở địa phương làm không thiếu chuyện hoang đường , vẫn là về sau lão mẫu khuyên nhủ , hắn mới học một chút sách , nghiên cứu chư tử Bách gia mà nói , suy nghĩ có sự khác biệt , liền tiến vào hoạn lộ , từ kế duyện bắt đầu , dần dần lên chức trở thành đất Thục quận thừa .\nNghĩ tới đây , hắn có chút bứt rứt bất an , chỉ mong vị này Lưu sứ quân không biết hắn niên thiếu chuyện , cùng hắn thuở thiếu thời xưng hào Buồm gấm tặc .\nLúc này , một cái nam tử trung niên mang theo một đội hà giáp chấp kích binh lính đẩy ra tụ tập đám người .\nLưu Chương nhận ra được , nam tử trung niên là châu mục trong phủ chủ sự , Bàng Tĩnh , khuôn mặt gầy gò , sắc bén hai mắt , cái cằm có râu quai nón , sợi râu tu bổ ngắn lại ngang bằng .\nBàng Tĩnh nhìn xem Lưu Chương bình yên vô sự , nhẹ nhàng thở ra , Lưu Chương cải trang xuất hành , ngoại trừ thiếp thân đi theo bốn tên thân vệ , hắn còn phái mấy tên tinh tế hán tử đi theo , để phòng bất trắc .\nMột khắc đồng hồ phía trước , có người hồi báo Đông Châu Binh nháo sự , hắn liền lập tức chạy tới .\nChắp tay hướng Lưu Chương sau khi hành lễ , nhìn về phía Từ Mãnh , xem như châu mục trong phủ chủ sự , Trung Bình năm thứ năm liền đã đến Ích châu , hắn tự nhiên nhận ra Từ Mãnh .\nTrung niên nhân phát ra đặc hữu thuần đang tiếng nói , mang theo một chút áp bách : “ Từ Tử ngọc , ngươi thật to gan , dám lăng bách sứ quân .”\nBàng Tĩnh xuất hiện , để cho Từ Mãnh triệt để chắc chắn Lưu Chương thân phận , hắn nhận ra vị này Châu Mục phủ chủ sự .\nThật là Lưu Chương Lưu Quý Ngọc , mới nhậm chức Ích Châu Mục , Từ Mãnh nội tâm cực kỳ sụp đổ , Đông Châu Nhân có thể tại Ích châu lẫn vào , dựa vào chính là Ích Châu Mục đứng tại bọn hắn bên này , buông thả bọn hắn .\nMây trên trời mặc dù nhiều , nhưng Đông Châu Nhân đầu đỉnh chỉ có một đám mây , đó chính là Ích Châu Mục Lưu sứ quân .\nXem như một cái Đông Châu Nhân , trước mặt mọi người đắc tội cấp trên hắn , hạ tràng sợ là rất thảm , chỉ hi vọng có thể bảo trụ người nhà của mình .\nTừ Mãnh nhận mệnh , sửa sang lại dáng vẻ , mang theo sau lưng bốn tên tiểu đệ quỳ lạy tạ tội : “ Đô úy Từ Mãnh , chữ Tử Ngọc , bái kiến Lưu sứ quân , chẳng ngờ hôm nay mạo phạm sứ quân , tội chết , tội chết .”\nLưu Chương hơi kinh ngạc , Tử Ngọc , đối diện cái này râu quai nón đại hán , gọi là Từ Mãnh nam nhân , lại lấy như thế văn nhã chữ .\nCổ ngữ nói , người khiêm tốn , ôn nhuận như ngọc , vị này tính tình có thể một điểm không ôn nhuận .\nSuy tư phút chốc , Lưu Chương lên tiếng nói : “ Ngày xưa ta Thái tổ cao hoàng đế nhập quan bên trong lúc , cùng quan bên trong người ước pháp tam chương , kẻ giết người phải chết , đả thương người cùng trộm đền tội .”\n“ Cho nên từ Đô úy ngươi có tội , nhưng tội không đáng chết , nếu là ở hành quân thời điểm , ngươi làm xằng làm bậy , bản sứ quân làm bằng quân pháp chém ngươi , chỉ là ngày bình thường , ta làm phạt ngươi .”\nLưu Chương cũng không muốn tùy ý giết người , giết người không giải quyết được vấn đề gì , Từ Mãnh tội lỗi cũng không bị chết tội .\nHuống hồ Lưu Chương cũng muốn dựa dẫm Đông Châu Nhân , nhưng mà hắn tuyệt sẽ không cùng Lưu Yên một dạng , thông qua phóng túng Đông Châu Nhân ức hiếp Thục nhân tới lôi kéo nhân tâm , hắn muốn bằng mượn thưởng phạt chế ước Đông Châu Nhân , để cho Đông Châu Nhân quy tâm với hắn .\nĐông Châu Nhân với hắn mà nói , tương lai có tác dụng lớn .\nHơn nữa phía trước hắn nói Ích châu bách tính là Đông Châu Nhân áo cơm phụ mẫu , nhi nữ sao có thể khi dễ phụ mẫu lúc . Bén nhạy phát giác Từ Mãnh trên mặt hổ thẹn sắc , thuyết minh người này cũng không phải không có thuốc nào cứu được .\nLưu Chương cấp ra Từ Mãnh phán quyết , hắn đối với Từ Mãnh đám người nói : “ Các ngươi hồi doanh , các lĩnh ba mươi quân trượng .”\nĐồng thời khuyên bảo Từ Mãnh : “ Sau này không thể vọng sinh sự đoan .”\nloadAdv(7,3);\nTrốn qua một kiếp Từ Mãnh trong lòng đại hỉ , ba mươi quân trượng với hắn mà nói không tính là gì , hắn lập tức bái tạ : “ Từ Mãnh lãnh phạt , sau này tuyệt không tái phạm .”\nĐánh bọn này Đông Châu Nhân một cái tát , Lưu Chương quyết định lại cho cái táo ngọt , cà rốt và cây gậy , mới là có thể dựa nhất .\n“ Đại trượng phu chính là quốc gia hiệu lực , mà không phải khi dễ lão ấu phụ nữ trẻ em . Trở về thật tốt chuyên cần luyện võ nghệ , Từ Tử ngọc , ngươi cũng không muốn cả một đời chờ tại Thục trung a .”\n“ Nếu thời cuộc có biến , ta mang các ngươi trở về quan bên trong .”\nLưu Chương vẽ một bánh nướng , hứa hẹn mang Đông Châu Nhân về nhà bánh nướng , không ai có thể chống cự về nhà dụ hoặc .\nNghe được Lưu Chương những lời này Từ Mãnh hữu chút ngạc nhiên , sau đó hốc mắt có chút đỏ lên .\nThục trung có thượng hạng rượu ngon , có kinh diễm tuyệt thế gấm Tứ Xuyên , nhưng ở trong lòng của hắn , cuối cùng không sánh được quan bên trong , không sánh được cố thổ rượu nhạt cùng áo gai .\nLoạn ly người , thật giống như chó nhà có tang , đồ vật gì cũng không được tư vị , hắn có khi nhìn Thục trung mặt trăng , cảm giác cũng không bằng quan bên trong tròn .\nTừ Mãnh âm thanh nghẹn ngào , xuất phát từ chân tâm bái tạ , đồng thời ưng thuận đại trượng phu hứa hẹn : “ Nếu như thế , mãnh liệt sau này duy sứ quân chi mệnh là từ , không có hai lòng , thiên địa chứng giám .”\nLưu Chương gật đầu , tự tay đem Từ Mãnh đỡ dậy , tiếp nhận hắn đi tới nơi này cuối thời Đông Hán , phần thứ nhất trung thành quy thuận .\nMột bên Cam Ninh nghe Lưu Chương những lời này , hơi híp mắt lại như có điều suy nghĩ .\nGiờ phút này thành đô thị lệnh Điền Chính cũng cuối cùng chạy tới , còn chưa tới Lưu Chương trước mặt âm thanh liền truyền tới , cao giọng nói : “ Sứ quân không có sao chứ , không có sao chứ .”\nĐiền Chính trong lời nói mang theo khẩn trương , xem như thành đô thị lệnh hắn , chủ quản thành đô thị tụ tập , trong chợ phát sinh xung đột cùng mâu thuẫn đều thuộc về hắn quản lý xử trí .\nNghe được Đông Châu Binh nháo sự , hắn lại không có chạy tới , chỉ vì hắn từng cái nho nhỏ thành phố lệnh , nơi nào quản được Đông Châu Binh đám kia đại gia , Đông Châu Binh trượng lấy Lưu Yên phù hộ , hành vi phóng túng , hắn là không quản được , nếu như xông lên phía trước , làm không cẩn thận còn muốn chịu một trận đánh đập .\nCho nên Điền Chính vẫn là tại phủ nha đắc ý uống ít rượu , không đi sờ Đông Châu Binh xúi quẩy , đại gia bình an vô sự , chỉ là đắng một đắng Ích châu bách tính .\nNhưng mà hắn nghe nói cùng Đông Châu Binh phát sinh xung đột là tân nhiệm Lưu sứ quân , lại là lập tức dẫn người chạy tới , đây chính là Lưu sứ quân , hôm nay thiên hạ đại loạn , Lưu sứ quân chính là Ích châu thổ hoàng đế , một lời quyết sinh tử tồn tại .\nĐiền Chính Lai đến Lưu Chương trước mặt , sau khi hành lễ đứng ở một bên chờ đợi xử lý , trên trán đổ mồ hôi không ngừng nhỏ xuống , bàn tay nhỏ nắm phía trước tấm lụa không ngừng tại tròn trịa trên mặt béo lau .\nLưu Chương dò xét dáng người giống như bóng rổ một dạng thành phố lệnh , cách một khoảng cách đều có thể ngửi được trên người hắn hèm rượu vị , Điền Chính tại thành phố lệnh cái này ăn ngon vị trí , đều nhanh ăn thành cầu .\nHắn không khỏi lắc đầu , chẳng ai hoàn mỹ , tham điểm không sao , nhưng cũng không thể nên kiếm sống không làm , việc nằm trong phận sự đều bỏ lại mặc kệ .\nBất quá hắn biết cái này cũng là phụ thân hắn Lưu Yên buông thả Đông Châu Nhân nguyên nhân , cho nên Điền Chính không có để ý , cũng không dám quản chuyện này , nhưng mà duyên cớ này không thể nói , tử vi phụ ẩn , cha làm tử ẩn , thời đại này làm nhi tử , không thể tuyên dương phụ thân sai lầm .\nHắn cho ra Điền Chính xử phạt : “ Ngươi thân là thành phố lệnh , chợ có việc , ngươi lại uống rượu hỏng việc , tiền phi pháp ngươi 3 tháng bổng lộc .”\nĐiền Chính khúm núm , tiếp nhận xử phạt , 3 tháng bổng lộc với hắn mà nói không tính là gì .\nTiễn đưa Từ Mãnh Nhất người đi đường rời đi , Điền Chính cũng đã nhận được xử trí , sự tình giải quyết viên mãn .\n“ Minh sứ quân .”\nCao hứng nhất thuộc về vây xem Ích châu bách tính , mới nhậm chức Ích Châu Mục xem ra là một công bình công chính người , sẽ không tùy ý Đông Châu Nhân khi dễ bọn hắn , mang lòng cám ơn , bọn hắn hô to minh sứ quân , tại sứ quân phía trước tăng thêm Minh tự biểu đạt tôn kính , đồng thời quỳ gối một mảnh .\nLưu Chương nhìn quanh một tuần còn tại tụ lại Ích châu bách tính , cao giọng nói : “ Chư vị phụ lão xin đứng lên .”\nBách tính nghe Lưu Chương lời nói đứng lên , sau đó Lưu Chương hướng một đám Ích châu phụ lão hứa hẹn : “ Chương bất tài , bị nâng vì Ích Châu Mục , tất nhiên là công bằng Nhậm Sự , không có thiên vị , thỉnh chư vị phụ lão yên tâm .”\n“ Minh sứ quân .”\nVây xem Ích châu phụ lão lại hô to minh sứ quân , ô ương ương quỳ lạy xuống .\n( Tấu chương xong )', NULL, '2026-09-01T07:31:48.807233+00:00', 'completed', 'pending', 9838, 0),
	(4, 1, '34902843', 4, 'Thứ 4 chương Vàng đẹp', 'Thứ Chương Hoàng Uyển\nHoàng Uyển không nghĩ tới , vì nàng bênh vực lẽ phải , đứng ra càng là mới nhậm chức Ích Châu Mục , Lưu Chương Lưu Quý Ngọc , nàng nghe qua một chút chợ búa lời đồn đại , cùng với cùng nàng huynh trưởng hàn huyên tới qua vị này mới nhậm chức Ích Châu Mục , đều nói Lưu Chương làm người Ôn Nhân , tính tình có chút nhu nhược .\nNhưng thấy hôm nay Lưu Chương vì nàng ra mặt , bênh vực lẽ phải , có thể nói phải bên trên khí khái hào hùng vô song , bởi vậy có thể thấy được chợ búa lời đồn đại không thể tin , biết người người quen còn phải gặp qua mới biết được .\nChờ sự tình hết thảy đều kết thúc , nàng chậm rãi tiến lên , khom lưng chắp tay , nghiêng người hướng Lưu Chương cùng Cam Ninh phân biệt hành lễ .\n“ Tiểu nữ tử Hoàng thị , ở đây đa tạ Lưu sứ quân cùng Cam Quận Thừa trượng nghĩa ra tay , làm cho tiểu nữ tử miễn ở chịu nhục .”\nThấy không sớm rời đi chủ tớ hai vị , cùng với phụ cận tạ ơn Hoàng Tiểu Nương , hai tám chi niên , nhưng lại đoan trang hào phóng , không lộ một tia e sợ sắc , thủy doanh doanh hướng về Lưu Chương chắp tay đáp tạ .\nBị kiếp trước sinh hoạt kinh nghiệm quấy nhiễu Lưu Chương , thốt ra , “ A , tiểu nương ngươi vì cái gì còn chưa rời đi ?”\nHoàng Uyển nhàn nhạt nở nụ cười , thiếu nữ giờ phút này tiếu yếp như hoa , không chần chờ trả lời Lưu Chương nghi vấn : “ Sự tình chưa giải quyết , tiểu nữ tử sao dễ sớm rời đi , ta nguyên Tưởng Đãi thị lệnh lúc đến , lưu lại làm chứng .”\n“ Không nghĩ càng là sứ quân ở đây , đổ lộ vẻ tiểu nữ tử quá lo lắng .”\nTrước mặt tiểu nương bằng phẳng như thế , tra hỏi Lưu Chương có chút hụt hơi , hắn có chút xấu hổ , hướng về phía chủ sự bàng tĩnh phân phó một tiếng : “ Bàng thúc , ta còn có chút sự tình , làm phiền ngươi thay ta tiễn đưa Hoàng Tiểu Nương về nhà .”\nNói xong hắn nhìn xem hai tay trống trơn chủ tớ hai người , Lưu Chương dường như nghĩ tới điều gì , hắn khoát tay áo thế để cho Hoàng Uyển chờ một chút , sau đó hắn đi tầm mười bước , đến buôn bán gấm Tứ Xuyên cửa hàng phía trước , cầm lấy cái kia thớt đạm nhã gấm Tứ Xuyên , trả tiền , tiếp đó quay đầu đi trở về đem gấm Tứ Xuyên đưa đến Hoàng Uyển trên tay .\nHoàng Uyển hơi kinh ngạc , không rõ Lưu Chương dụng ý , một tay ôm gấm Tứ Xuyên , một tay che khuất bởi vì kinh ngạc mà giương lên miệng anh đào nhỏ , hỏi : “ Sứ quân đây là ý gì .”\n“ Bồi tội chi dụng .”\n“ Bồi tội , sứ quân có tội gì ?”\nLưu Chương áy náy nở nụ cười , giải thích nói : “ Ta vì Ích Châu Mục , lại không thể ước thúc bộ hạ , hôm nay kém chút lệnh tiểu nương chịu nhục , là nguyên nhân bồi tội , xin chớ chối từ .”\nTrên thực tế Lưu Chương là vì hắn âm u tâm lý bồi tội , hắn không nên cầm thế kỷ hai mươi mốt kinh nghiệm , đi bộ cái này cổ đại tiểu thư khuê các .\nĐưa đi Hoàng thị chủ tớ hai người , Lưu Chương một mặt nóng bỏng nhìn về phía Cam Ninh .\nNữ nhân cái gì , hắn không có để ở trong lòng , nữ nhân cái kia có Cam Ninh hương , một trăm cái kim chi ngọc diệp cũng không chống đỡ được một cái Cam Ninh , Hưng Bá thế nhưng là Tam quốc vô song đấu tướng , hôm nay nhất định muốn cầm xuống .\nHắn mở miệng mời : “ Hưng Bá , có muốn Quá phủ một lần .”\nCam Ninh chắp tay : “ Thà nào dám không tòng mệnh .”\nÍch Châu Mục xa giá cũng đến , Lưu Chương lôi kéo hơi chút từ chối Cam Ninh ngồi chung một chiếc xe ngựa .\n“ Giá .” Tại bàng khuyết một tiếng kêu gọi phía dưới , xe ngựa tại bàn đá xanh trên đường chi nha chi nha tiến lên , hà giáp chấp kích giáp sĩ đi theo ở hai bên , giáp trụ va chạm phát ra thanh thúy kim minh thanh .\nCam Ninh ngồi ngay ngắn ở trên xe , không dám vọng động , xa giá hai bên có không ít Ích châu bách tính tại nhìn về phía hắn , chỉ trỏ , để cho hắn không dám lộ ra khinh bạc tư thái , để tránh bại nhà mình danh dự .\nCùng châu mục ngồi chung , là bực nào vinh quang , làm một quận thừa , Cam Ninh chỉ cảm thấy nhân sinh đạt tới đỉnh phong , không cần mấy ngày , tên của hắn hẳn là có thể truyền khắp toàn bộ thành đều , qua một đoạn thời gian nữa , toàn bộ Ba Thục đại địa có thể đều biết lưu truyền tên của hắn .\nDương danh lập vạn , rủ xuống đại danh tại sử sách , là Cam Ninh mộng tưởng .\nCam Ninh hơi nghiêng mặt qua , liếc nhìn ngồi ngay ngắn kiệu xe bên trên , nhìn phía trước Lưu Chương .\nLưu Chương không nói một lời , đoan chính che mặt sắc , trên gương mặt thanh tú lại mang theo chân thật đáng tin uy nghiêm , song mi giống như như lợi kiếm đâm vào Cam Ninh trong lòng .\nGiờ phút này Cam Ninh trong lòng sinh ra một cái ý niệm .\nLưu Chương có thể chính là người hắn muốn tìm .\nHắn Minh công .\nTriệu phủ .\nÍch châu trọng thần dưới trướng Tư Mã Triệu vĩ phủ đệ .\nGiờ phút này đang phát sinh một hồi tranh luận .\n“ Cha , ngươi vì sao muốn đề cử Lưu Chương tên phế vật kia đảm nhiệm Ích Châu Mục .”\nTriệu Vĩ nhi tử Triệu Hi tức giận bất bình mà hỏi : “ Tam công tử Lưu Mạo , làm người khôn khéo tài giỏi , dũng cảm Nhậm Sự , hắn làm Ích Châu Mục không phải tốt hơn .”\n“ Huống hồ trưởng ấu có thứ tự , trước sau rõ ràng , như thế nào cũng không tới phiên Lưu Chương tên hèn nhát đó .”\nloadAdv(7,3);\nTriệu Hi không nghĩ ra , vì cái gì phụ thân của hắn Triệu Vĩ muốn cùng trị bên trong xử lí Vương Thương cùng một chỗ đề cử Lưu Chương làm Ích Châu Mục , tam công tử Lưu Mạo vô luận làm người vẫn là xử lý , so Lưu Chương đều mạnh , cả hai có thể nói là khác nhau một trời một vực .\nHắn không rõ , nhà mình lão cha vì cái gì có trên trời đám mây không chọn , nhất định phải tuyển trên đất một đống bùn nhão .\nThế là mới từ lão gia Ba Quận trở về thành đều Triệu Hi , không cần tắm rửa , dọn dẹp một chút , liền không kịp chờ đợi trực tiếp chạy đến Triệu Vĩ trong thư phòng , hướng về phụ thân của hắn trưng cầu , muốn biết nguyên do .\nĐang đi học Triệu Vĩ , nhìn xem kêu la om sòm , hỉ nộ lộ rõ trên mặt Triệu Hi , không khỏi nhíu mày .\nHay không thành dụng cụ , hắn đối với con của mình cấp ra đánh giá .\nNhìn sự tình chỉ có thể nhìn thấy tầng thứ nhất , không thể nhìn thấy tầng thứ hai .\nTóm lại là con của mình , vẫn là mình con trai độc nhất . Để quyển sách trên tay xuống , Triệu Vĩ mở miệng lấy hỏi lại phương thức giảng giải .\n“ Nguyên nhân sứ quân Lưu Yên cũng là thông minh tháo vát , ngươi ưa thích hắn làm Ích Châu Mục sao ?”\nTriệu Hi lắc đầu , Lưu Yên làm người bá đạo , đến Ích châu sau , vì lập uy , giết Ba Quận Thái Thú vương mặn cùng Ba Quận lớn họ Lý quyền , Triệu gia xem như Ba Quận người địa phương , hào môn ở giữa đều có quan hệ thông gia , nhìn thấy bọn hắn bị giết , không khỏi thỏ tử hồ bi .\n“ Cho nên , tại Lưu Mạo cùng Lưu Chương giữa hai người , vi phụ đương nhiên càng nhìn trúng mềm yếu Lưu Chương , để cho hắn đảm nhiệm Ích Châu Mục , chúng ta Thục nhân có thể ăn ít một chút đắng .”\nTriệu Hi suy tư một chút , nghe xong đi vào , rất nhanh hắn lại bốc lên cái ý nghĩ : “ Cha , liền không thể từ chúng ta đất Thục chính mình người nắm giữ đại quyền sao ?”\n“ Tuy nói có ba lẫn nhau pháp tại , chúng ta đất Thục người không làm được Ích Châu Mục , nhưng chúng ta có thể đề cử một cái đất Thục xuất thân , nhưng không phải Ích châu quê quán người .”\n“ Cần gì phải đề cử những thứ này vào Thục người ngoại bang đảm nhiệm Ích Châu Mục , những người ngoại bang này chưa từng đem chúng ta Thục nhân để vào mắt , thỉnh thoảng liền mắng chúng ta Thục nhân trong bụng có trùng , không phải lương nhân .”\nTriệu Vĩ bất đắc dĩ , thở dài , ngoại trừ Lưu Mạo cùng Lưu Chương hai huynh đệ , bọn hắn nào còn có lựa chọn khác , nào còn dám có lựa chọn khác .\n“ Ngươi có biết , ngày đó , Lưu Yên đột nhiên chết bệnh , không có chỉ phái người kế nhiệm , khi chúng ta đại thần tại nghị sự .”\n“ Đông Châu Binh biết được tin tức , hà giáp chấp kích , mang theo Cung Đái Tiễn , chạy đến chúng ta nghị sự trước viện , đều nhanh vọt tới vũ xuống .”\n“ Đám kia Đông Châu thất phu hô to , nói bọn hắn chịu Lưu ( Chỗ này ) mục trọng ân , hôm nay nếu không lập Lưu Mục dòng dõi kế nhiệm Ích Châu Mục , đại gia liền ngọc thạch câu phần .”\nTriệu Hi im lặng , không nghĩ tới tình huống lúc đó nguy cấp như vậy , dưới tình thế cấp bách , ủng lập Lưu Chương vì Ích Châu Mục là lựa chọn tốt nhất , đối bọn hắn Thục nhân tới nói .\nNói đến đây , Triệu Vĩ nhớ tới quần thần thương nghị kết thúc , thỉnh Lưu Chương tới kế vị thời điểm , cái kia Lưu Chương tiểu nhi vô cùng kinh hoảng , trong miệng lắp bắp nói :‘ Các ngươi , các ngươi hại khổ ta à .’\nTriệu Vĩ hơi híp mắt lại , có chút đắc ý , giống Lưu Chương bực này dung nọa người , vừa vặn xứng với cái này Ích châu chi chủ , bằng không thì hắn như thế nào có cơ hội , Ích Châu Mục vị trí tạm thời để cho Lưu Chương tiểu nhi ngồi trên một đoạn thời gian .\nLúc này Triệu phủ chủ sự tại cửa ra vào xin chỉ thị sau đi đến , hồi báo tại thành đô thị tụ tập thám tử gửi tới tin tức , Đông Châu Binh lại tại nháo sự .\nTriệu Hi nghe vậy lập tức chửi ầm lên : “ Rõ như ban ngày , ban ngày ban mặt , Đông Châu Binh liền dám làm xằng làm bậy , khi dễ chúng ta Thục nhân .”\n“ Cha , ngươi xem như quân Tư Mã , không thể lại để cho bọn này Đông Châu Binh tùy ý vọng vi , nhất định muốn trọng quyền xuất kích , cho bọn hắn điểm màu sắc xem .”\nTriệu Vĩ lại nhẹ vỗ về râu dê , có chút thoải mái , chuyện này không có khốn nhiễu hắn , ngược lại để cho hắn có chút thoải mái dễ chịu : “ Ngươi biết cái gì , Đông Châu Binh đây là đang cấp ngươi ta phụ tử trải đường .”\n“ Trải đường ?” Triệu Hi không rõ ràng cho lắm , không có lý giải phụ thân hắn ý tứ .\nLà tại trải đường , Triệu Vĩ không có cho ra giảng giải , hắn bây giờ nội tâm thông thuận , vui thích tự hỏi , Đông Châu Binh đây là vì hắn leo lên Ích Châu Mục vị trí trải đường .\nHắn chỉ muốn nói , náo a , náo a , nháo đến có một ngày không thể kết thúc , nháo đến Thục nhân không muốn lại chịu đựng ức hiếp , nháo đến toàn bộ Ba Thục dân tâm thời điểm như lửa , hắn cơ hội liền đến .\nKhi đó Ích châu trở thành hắn cái này Ích châu người Ích châu .\nCầu Like ! Cầu đề cử !\n( Tấu chương xong )', NULL, '2026-09-01T07:31:54.612087+00:00', 'completed', 'pending', 9753, 0),
	(5, 1, '34902844', 5, 'Thứ 5 chương Cam Ninh tiếc nuối', 'Thứ chương Cam Ninh tiếc nuối\n“ Hưng Bá , thỉnh .”\n“ Sứ quân , thỉnh .”\nLưu Chương cùng Cam Ninh tất cả uống vào một chén rượu sau , hai tay duỗi thẳng , chén rượu hướng về phía trước xoay chuyển , đem đáy chén bày ra cho đối phương , cho thấy đã uống cạn một ly .\nQua ba lần rượu , không khí hoà thuận .\nLưu Chương dẫn đầu mở miệng trước , nói ra nghi vấn của hắn : “ Hưng Bá , ta nhớ được ngươi là dùng võ dũng nổi tiếng Ba Quận , làm thế nào Thục quận quận thừa , vũ văn lộng mặc .”\n“ Là gia mẫu khuyên nhủ , vũ phu cuối cùng không phải chính đồ , cho nên bỏ võ theo văn , lập chí tại hoạn lộ .” Cam Ninh không có bất kỳ cái gì giấu diếm , thẳng thắn trả lời .\nLưu Chương điểm một chút biểu thị đồng ý , thời đại này đối với võ nhân cách nhìn là mang theo khinh bỉ ánh mắt , cũng tỷ như Kinh Sở danh sĩ Lưu Ba đối với Trương Phi thái độ , Trương Phi đáo Lưu Ba chỗ tá túc , Lưu Ba lại một câu nói đều không cùng hắn nói , đem Mãnh Trương Phi tức giận không nhẹ .\nCoi như đằng sau Gia Cát Lượng đi khuyến cáo Lưu Ba nói : “ Trương Phi tuy là võ nhân , nhưng hắn vô cùng ngưỡng mộ tiên sinh ngươi . Chúa công đang triệu tập văn võ nhân tài , lấy thành tựu một sự nghiệp lẫy lừng . Tiên sinh ngươi mặc dù thiên tính thanh cao , nhưng cũng cần phải hạ thấp một chút phong cách .”\nLưu Ba hay không khách khí hồi đáp : “ Đại trượng phu xử thế , khi giao tứ hải anh hùng , sao có thể dạy ta đi cùng một kẻ vũ phu nói chuyện với nhau ?”\nTrương Phi nhân vật bậc nào , cộng thêm Gia Cát Lượng đều đi khuyên bảo , kết quả Lưu Ba vẫn là biểu thị chướng mắt Trương Phi cái này vũ phu , cũng khó trách Cam Ninh mẫu thân có ý nghĩ như vậy .\nVõ nhân tuy nói có thể bằng quân công Phong Hầu , nhưng ở kinh học gia truyền thế gia trong mắt , bất quá là binh tử thôi , con em thế gia càng là hổ thẹn lấy quân công phát tích , giống như Tấn Vũ Đế bị Hồ Quý Tần mắng ‘ Bắc phạt Công Tôn , tây cách Gia Cát , không phải đem loại mà gì ’ lúc , đối với đem loại một từ , Tấn Vũ Đế mặt có nét hổ thẹn .\nLưu Chương đặt chén rượu xuống , đoan chính tư thái hướng về phía Cam Ninh nói : “ Nếu như là thái bình thời tiết , cố làm bỏ võ theo văn , tinh nghiên điển tịch , mới có thể có hành động .”\n“ Chỉ là hiện nay vũ nội đại loạn , thiên hạ phân tranh không ngừng , chính là ngã Văn Hành Vũ , thả xuống văn giáo , chấn hưng võ bị thời điểm .”\n“ Lấy Hưng Bá vũ dũng , chẳng lẽ không muốn làm một phen sự nghiệp , lấy chương quan chi , Hưng Bá vì vạn hộ hầu không khó .”\n“ Vạn hộ hầu .” Cam Ninh lẩm bẩm mấy chữ này , ánh mắt hơi lấp lóe , Hán Cao Tổ Lưu Bang cùng quần thần giết bạch mã vì thề , không phải Lưu thị không vương , không phải công thần không hầu . Cho nên không phải họ Lưu người chỉ có thể ngồi vào công hầu vị trí , vạn hộ hầu chính là cao cấp nhất .\nCam Ninh đoan chính tư thế ngồi , hướng Lưu Chương dò hỏi : “ Vừa rồi tại trên chợ , nghe sứ quân đối với Đông Châu Nhân hứa hẹn , thời cuộc có biến , sẽ dẫn bọn hắn trở về quê cũ , sứ quân tựa hồ có xa đồ .”\n“ Bởi vậy Ninh Mạo Muội , xin hỏi sứ quân chí hướng .”\nNghe được câu này hỏi ý , Lưu Chương biết món chính đi lên , chim khôn biết chọn cây mà đậu , lương thần chọn chủ mà chuyện . Cuối thời Đông Hán , làm thần tử chính là sẽ chọn lựa chúa công , giống như Trương Tùng cảm thấy Lưu Chương nhu nhược vô năng , cho nên đi nương nhờ Lưu Bị , đây đều là chuyện rất tầm thường .\nHắn mở miệng trả lời Cam Ninh khảo đề , đối với thi cho sử dụng tài liệu hắn tới nói vấn đề này không khó : “ Hán thất sụp đổ , gian thần trộm mệnh , chủ thượng bị long đong . Chương không lượng đức lượng tài , muốn tin đại nghĩa khắp thiên hạ .”\nLưu Chương hai mắt sáng ngời có thần , nhìn thẳng Cam Ninh , tiếp tục cho thấy tâm ý : “ Lý Giác , Quách Tỷ mấy người quần tặc đạo chích , sôi trào thiên hạ , chương vì Hán thất dòng họ , tự nhiên vượt mọi chông gai , vì Hán thất trừ tàn phế khứ uế .”\n“ Không biết Hưng Bá phải chăng nguyện trợ chương một chút sức lực , vì ta đi đầu .”\nCam Ninh nghe nói chỉ cảm thấy nhiệt huyết sôi trào , phảng phất nhiệt huyết sau một khắc liền muốn bắn ra , Lưu Chương lại có chí hướng như thế , khí phách như thế , đây mới là hắn muốn đi theo minh chủ .\nHắn đứng dậy đi đến Lưu Chương ngay phía trước , quỳ lạy , hướng Lưu Chương biểu đạt lòng trung thành của mình : “ Ninh Bất Tài , nguyện chịu Minh công điều động , máu chảy đầu rơi .”\nNghe gọi hắn Minh công , ca tụng xuống thần phục Cam Ninh , Lưu Chương cũng không có vui sướng , cũng không có cảm thấy bất ngờ , hắn nhớ tới trong lịch sử Cam Ninh hết thảy .\nTrong lịch sử Cam Ninh là cái có đại chí hướng người , cũng là bạc mệnh người . Tại Lưu Chương kế nhiệm Ích Châu Mục sau , hắn không muốn chịu đựng Đông Châu Nhân ức hiếp , khởi binh phản loạn Lưu Chương , nhưng mà thất bại , thất bại cũng chỉ có thể rời đi Ba Thục , rời đi hắn cố thổ .\nHắn chạy trốn tới Kinh châu , tại Hoàng Tổ thủ hạ làm việc , Hoàng Tổ coi hắn là làm phàm nhân súc dưỡng , đối với hắn công lao cũng không khen thưởng , hắn vì thế rầu rĩ không vui , rời đi Hoàng Tổ đi Giang Đông .\nThật vất vả đi Giang Đông , gặp được Tôn Quyền , hơn nữa dâng lên chiếm đoạt Kinh Sở , dần dần quy Ba Thục kế sách , Cam Ninh cho là hắn cuối cùng gặp được minh chủ .\nThế nhưng là Tôn Quyền là mặt hàng gì , Giang Đông lại là cái gì địa phương , Cam Ninh tài cán vẫn là không có nhận được trọn vẹn phát huy .\nHắn chỉ có thể thông qua không ngừng bày ra bản thân vũ dũng , tính toán bước về phía trước , mở ra trong lồng ngực khát vọng .\nThế là có Cam Ninh mang theo vài trăm người trông coi Di Lăng , chống cự Tào Nhân sáu ngàn người công kích không sợ .\nCó Cam Ninh thủ hạ chỉ có ba trăm binh lúc , đối với Lỗ Túc nói lại cho ta năm trăm , ta có thể ngăn cản quan vũ ba vạn người hào ngôn .\nCó Cam Ninh cầm trong tay luyện , tự mình leo lên thành tường , vì lại sĩ trước tiên , giành trước đánh hạ Hoàn thành hành động vĩ đại .\nCuối cùng cũng là tối oanh liệt trăm kỵ kiếp Tào doanh .\nThế nhưng là Cam Ninh làm nhiều chuyện như vậy , cũng bất quá được một cái tạp hào Chiết Xung tướng quân , tại Đông Ngô ngay cả một cái hầu tước cũng không có cầm tới , chỉ vì hắn không phải Đông Ngô cựu thần .\nSau khi hắn chết , Tôn Quyền cũng bất quá là thương tiếc , thương tiếc mất đi hắn tốt như vậy tay chân , con của hắn cam côi phạm tội liền bị đày đi Hội Kê , không lâu liền chết đi , không có bởi vì công lao của hắn nhận được một tia ưu đãi quan tâm .\nloadAdv(7,3);\nTrong lịch sử Cam Ninh tiếc nuối nhiều lắm .\nCam Ninh một đời đều tại phiêu bạt , từ Ba Thục đại địa đến Kinh Sở , từ Kinh Sở đến Giang Đông .\nMột đời đều nghĩ kiến công lập nghiệp , Phong Hầu thưởng tước , nhưng cuối cùng vẫn không có bắt được hầu tước .\nNhư thế có mưu trí , thức mơ hồ , đấu tướng vô song nhân tài , thực sự là bị Tôn Quyền cái loại mặt hàng này làm nhục không nhẹ .\nNghĩ tới đây , Lưu Chương ánh mắt trở nên nhu thuận , một thế này , hắn tuyệt sẽ không để cho Cam Ninh lưu lại tiếc nuối .\nLưu Chương muốn để cái này thuở thiếu thời vung lên buồm gấm , gió nổi lên lúc vang lên dễ nghe chuông đồng âm thanh , uy đi ba mà cam Hưng Bá , vĩnh viễn có thể vung lên buồm gấm , ngang ngược tứ hải .\nHắn đi ra phía trước , đỡ dậy Cam Ninh , nắm Cam Ninh tay , chân tình tràn đầy nói : “ Hưng Bá , ngươi ta quân thần , vĩnh viễn không cùng nhau phụ .”\n“ Vĩnh viễn không cùng nhau phụ .” Cam Ninh nắm chặt Lưu Chương đưa tới tay , lớn tiếng đáp lại nói .\nLưu Chương mỉm cười , trêu ghẹo nói : “ Mặt khác , Hưng Bá , ta không cần ngươi máu chảy đầu rơi .” Nhìn xem Cam Ninh lộ ra ánh mắt nghi hoặc , hắn tiếp tục nói : “ Ta muốn Hưng Bá cùng ta cùng một chỗ , vì thiên hạ mở thái bình , cứu lê dân ở tại thủy hỏa , cùng một chỗ chứng kiến thiên hạ an khang .”\n“ Ừm .” Cam Ninh vang dội đáp lại Lưu Chương yêu cầu .\n“ Hưng Bá , quận thừa cũng không cần làm , những thứ này vũ văn lộng mặc sự tình không thích hợp ngươi .”\n“ Ta muốn cho ngươi trước tiên làm một cái giáo úy , không biết ngươi có hay không ý nguyện .”\nLưu Chương nói thẳng ra ý nghĩ của hắn , Cam Ninh dạng này người thả tại quận thừa vị trí quá lãng phí , lãng phí là đáng xấu hổ .\nChỉ có quân đội , mới là Cam Ninh chốn trở về , mới là Cam Ninh có thể mở ra trong lồng ngực khát vọng địa phương .\nHắn cho ra một cái giáo úy chức quan , một cái bây giờ rất quý giá chức quan .\nCó thể có người sẽ cảm thấy giáo úy chức vị quá thấp , đó là bởi vì tại trải qua cuối thời Đông Hán võ tướng chức quan lớn tưới , võ tướng chức quan bị giảm giá trị tình huống đưa đến cứng nhắc ấn tượng .\nPhải biết Hán Linh Đế vì hết sức Thích đại tướng quân gì tiến binh quyền , tại Trung Bình năm thứ năm tháng tám , tại kinh đô Lạc Dương tây viên chiêu mộ tráng đinh thiết lập một chi tổ chức quân sự Tây viên bát hiệu úy , cái này 8 vị giáo úy bên trong , thế nhưng là có sau này ưng dương Hà Sóc chi địa Viên Thiệu cùng Ngụy Vũ Đế Tào Tháo , bởi vậy có thể thấy được giáo úy trọng lượng .\nDưới tình huống bây giờ võ tướng chức quan còn không có bị giảm giá trị , giáo úy là Lưu Chương có khả năng cho ra cao nhất quân chức .\n‘ Giáo Úy .’ Cam Ninh nghe được hai cái này có chút hoảng hốt , giáo úy , Quan Trật so hai ngàn thạch , hắn bây giờ làm quận thừa , Quan Trật bất quá 600 thạch , một cái chớp mắt , bổng lộc lật ra gấp ba bốn lần .\nBất quá bổng lộc không tính là cái gì , đáng quý chính là giáo úy cái này chức quan , Cam Ninh vốn cho rằng Lưu Chương sẽ cho ra Đô úy võ chức , không nghĩ tới Lưu Chương vừa ra tay chính là giáo úy .\nCàng là bực này hào khí .\nLại có bực này hào hùng .\nThực sự quá đối với hắn cái này du hiệp khẩu vị .\n“ Hưng Bá .” Lưu Chương nhìn thấy Cam Ninh thật lâu không nói , nhắc nhở .\n“ Tạ Minh Công .” Cam Ninh không kìm được vui mừng , không có tới trở về chối từ , trực tiếp hướng Lưu Chương nói lời cảm tạ .\nLại đối ẩm mấy chén , Lưu Chương rèn sắt khi còn nóng , quyết định dựa theo hán đại tập tục , thật tốt chiêu đãi Cam Ninh .\nMặc dù cái này phong tục hắn không quá ưa thích , nhưng nhập gia tùy tục , nên làm vẫn là phải làm .\nHắn mở miệng .\n“ Không biết Hưng Bá đêm nay nguyện cùng ta cùng bàn chung gối không .”\n“ A .”\n“ Ừm .”\nCầu đề cử ! Cầu Like !\n( Tấu chương xong )', NULL, '2026-09-01T07:31:59.409691+00:00', 'completed', 'pending', 10025, 0),
	(6, 7, '7639189635888841241', 1, 'Thứ 1 chương Minh thành tổ?', 'Thứ chương Minh thành tổ ?\n( Chú : Quyển sách tất cả đều là hàng lậu , tác giả cá nhân chi ngôn .)\n( Chú : Quyển sách tất cả đều là hàng lậu , tác giả cá nhân chi ngôn .)\n( Chú : Quyển sách tất cả đều là hàng lậu , tác giả cá nhân chi ngôn .)\nCông nguyên năm nguyệt .\nKinh thành lớn quần cộc .\n“ Lý lão sư , ngươi rõ ràng sao ?”\nMột vị nhân viên công tác , đang cẩn thận cho Lý Ân Phàm giới thiệu cái gì .\nHệ thống , cái tiết mục này cũng có thể a ?】\nLý Ân Phàm cau mày gật đầu một cái , giả bộ lấy đang suy tư điều gì , kì thực trong đầu hỏi đến cái này mấy tháng trước bỗng nhiên xuất hiện hệ thống .\nLeng keng , có thể .】\nVậy là tốt rồi .】\n“ Không có vấn đề , cứ như vậy đi .”\nBỗng nhiên , Lý Ân Phàm nghĩ tới điều gì , liền hướng về phía nhân viên công tác lại nói :\n“ Đem tiết mục tên đổi một chút đi , tên bây giờ cảm giác không tốt .”\nNhân viên công tác nghe nói như thế , chăm chú nhìn Lý Ân Phàm .\n“ Đổi thành : 《 Lịch sử mặt đối mặt 》 a .”\n“ Lịch sử mặt đối mặt ?”\nNhân viên công tác hơi nhíu mày lại , sau đó cầm bút lên , trên giấy viết xuống cái tên này .\n“ Hảo , Lý lão sư , ta sẽ cho chúng ta chủ quản nói .”\n“ Ân , những thứ khác đều không cần sửa lại . Trên sân khấu thêm ta , hết thảy bốn người , dạng này sẽ không lộ ra ầm ĩ , cũng sẽ không lộ ra chen chúc .”\n...\nCuối thời Đông Hán .\nKiến An 8 năm .\n“ Tư Không ! Tư Không !”\nNgồi ở bên trong nhà Tào Thao nghe được thanh âm này , ngẩng đầu nhìn phương hướng âm thanh truyền tới .\n“ Trọng khang , thế nào ?”\nHứa Chử lúc này vọt tới Tào Thao trước mặt , vội vàng nói :\n“ Tư Không , bầu trời màn trời bắt đầu xuất hiện chữ .”\n“ A ?!”\nTào Thao nghe vậy hơi kinh ngạc , sau đó nội tâm lại thở dài một hơi .\nTùng khẩu khí này , là bởi vì tại mấy tháng trước , màn trời lúc mới xuất hiện , trì hạ các nơi liền có bất hảo âm thanh truyền ra .\nNếu như không phải là bởi vì chính mình cưỡng chế , hơn nữa những địa phương khác cũng có thể nhìn thấy cái này màn trời mà nói , các nơi đã sớm loạn lên .\nTại cổ đại , sấm lời là phi thường có thị trường .\nViên Thuật cũng là bởi vì lời sấm , rơi vào kết quả như vậy .\n“ Đi , đi xem một chút .”\nTào Thao đầu lĩnh , bước nhanh đi ra phòng ốc , sau đó ngẩng đầu nhìn bầu trời .\nNơi xa , Quách Gia , Tuân Úc , Tào Nhân bọn người tại hướng về Tào Thao phương hướng chạy đến .\n“ Tần triều ( Doanh họ Triệu thị ), trước công nguyên năm Phía trước năm , quốc phúc năm ?”\nNhìn xem trên thiên mạc hiện ra chữ , Tào Thao rõ ràng có thể cảm giác được có chút chữ chính mình rõ ràng không biết , lại biết là có ý gì , có thể hiểu được .\nNhỏ giọng niệm xong một nhóm , Tào Thao sửng sốt một chút , nháy nháy mắt ,\n“ Đây là ?”\nTào Thao mang theo hỏi thăm ánh mắt nhìn một chút bên cạnh , lúc này mới phát hiện bên cạnh mình chỉ có Hứa Chử một người .\nMà Hứa Chử đâu ? Gặp Tư Không nhìn về phía chính mình , lập loè ánh mắt trong suốt , sờ lên đầu , nghi ngờ hỏi :\n“ Tư Không ?”\n“ Không có việc gì .”\nTào Thao thấy thế , cũng cảm thấy chính mình có chút hồ đồ rồi , vậy mà muốn hỏi Hứa Chử ?\nLập tức lắc đầu , một lần nữa nhìn về phía màn trời .\nMà đúng lúc này .\n“ Tư Không !”\nQuách Gia chạy vào , hướng về Tư Không Tào Thao thi lễ một cái .\n“ Phụng Hiếu , nhanh , xem cái này màn trời là ý gì ?”\nGặp Quách Gia đi vào , Tào Thao tiến lên lôi kéo Quách Gia , để cho hắn nhìn về phía màn trời .\n“ Hán triều ( Lưu thị ) trước công nguyên năm năm , quốc phúc năm .”\n“ Tây Hán , Hán Cao Tổ Lưu Bang sở kiến , truyền mười một đời mười hai đế , cuối cùng năm , Sử Xưng vì “ Tây Hán ”.\n“ Đông Hán , tôn thất Lưu Tú thừa cơ dựng lên , đồng thời kéo dài “ Hán ” Làm quốc hiệu , định đô Lạc Dương , Sử Xưng Đông Hán , đệ bát chung mười bốn đế , Hưởng quốc một trăm chín mươi năm năm , cùng Tây Hán gọi chung Lưỡng Hán .”\nQuách Gia nhìn xem màn trời , theo bản năng đọc , chờ niệm xong màn trời hiện ra chữ sau đó , mới hồi phục tinh thần lại .\n“ Tư Không , đây cũng là chúng ta trước đây thời kì .”\nTào Thao có chút ngây người gật đầu một cái , sau đó bỗng nhiên nói :\n“ Hẳn là không đi ?”\n“ Hẳn là không ...”\nQuách Gia biết Tào Thao muốn hỏi cái gì , nhưng hắn làm sao có thể biết màn trời đăm chiêu suy nghĩ ? Chỉ có thể theo Tào Thao lời nói tiếp một câu .\nNhưng sau đó , bọn hắn chỉ thấy màn trời lại bắt đầu xuất hiện mới chữ .\n“ Ngụy ( Tào thị năm nguyệt ngày năm , quốc phúc năm .”\n“ Thời kỳ tam quốc cát cứ chính quyền một trong năm , Tào Phi bức bách Hán Hiến Đế nhường ngôi , chính thức xưng đế thiết lập Tào Ngụy , cải nguyên hoàng sơ . Tào Ngụy chung kinh nghiệm năm vị thực tế tại vị hoàng đế , nếu đưa vào truy tôn Tào Thao thì chung sáu đế .”\nThanh âm này ?\nTào Thao cùng Quách Gia hai người nhìn nhau một cái , phát hiện không phải hai người phát ra âm thanh , sau đó liền theo phương hướng âm thanh truyền tới nhìn lại .\nChỉ thấy Tuân Úc sắc mặt trắng hếu nhìn xem màn trời , đứng tại chỗ .\n“ Tư Không ?”\nQuách Gia thấy thế , chắp tay lui về phía sau mấy bước , sau đó lại nhìn xem màn trời .\n“ Ngô ( Tôn thị năm năm , quốc phúc năm .”\n“ Thời kỳ tam quốc cát cứ chính quyền một trong , là Tôn Quyền tại đông nam bộ thiết lập chính quyền , quốc hiệu vì “ Ngô ”, Sử Xưng Tôn Ngô .”\n“ Hán ( Lưu thị năm nguyệt ngày năm , quốc phúc năm .”\n“ Thời kỳ tam quốc cát cứ chính quyền một trong . Công nguyên năm , Lưu Bị tại thành đều xưng đế , quốc hiệu “ Hán ”, hậu thế xưng “ Thục Hán ”, “ Quý Hán ”, “ Thục ” mấy người .”\nNhìn thấy cái này thời điểm , Quách Gia mới phát hiện trong sân đã đứng đầy người , tất cả mọi người tại ngẩng đầu nhìn màn trời .\n“ Ai , thế cục cuối cùng vẫn là hướng về xấu nhất tình huống phát triển tiếp .”\nCó người thở dài một hơi , không biết nên nói cái gì .\nMàn trời dạng này hiện ra , tất cả mọi người đã biết là cái gì tình huống .\nBước kế tiếp , thì nhìn là ai thống nhất .\n“ Không đúng !”\nQuách Gia kinh hô lên một tiếng , nhíu chặt lông mày , tựa hồ phát hiện cái gì .\nMà nghe được Quách Gia một tiếng này , tất cả mọi người ở đây đều nhìn về Quách Gia .\n“ Các ngươi cũng không phát hiện có vấn đề gì không ?”\nVấn đề gì ?\nTất cả mọi người ở đây lúc này nội tâm đều bị cực lớn tin tức tương lai đánh thẳng vào , nào còn có khoảng không suy tư điều gì ?\n“ Ngụy , quốc phúc năm , Ngô , quốc phúc năm , Hán , quốc phúc năm ...”\n“ Cũng là màn trời nói tới Tam quốc thời kì cát cứ chính quyền một trong .”\nNói đến đây , Quách Gia nhìn chung quanh một vòng tất cả mọi người ở đây , sau đó mặt lộ nghiêm túc nói :\n“ Cái kia cuối cùng , là ai thống nhất ?!”\nNghe nói như thế , tất cả mọi người tại chỗ đều ngẩn ra .\nĐúng vậy a , cuối cùng là ai thống nhất ?\nCái này 3 cái , cũng là màn trời nói tới Tam quốc cát cứ chính quyền một trong .\nCái kia vấn đề tới , là ai thống nhất ?\nTất cả mọi người đều đồng loạt liếc mắt nhìn Tào Thao .\nMà Tào Thao nghe được vấn đề này , não hải cũng trống rỗng .\nSau đó , Tào Thao theo bản năng nhìn về phía phương bắc .\n“ Không thể nào ?”\nTại chỗ có người tựa hồ biết Tào Thao nhìn về phía phương bắc ý vị như thế nào .\nNếu như đây nếu là thật sự , vậy thì thật sự quá bất khả tư nghị .\nTại chỗ những người khác tựa hồ cũng nghĩ đến cái gì , mặt lộ vẻ hung quang nhìn về phía phương bắc .\n“ Chờ đã , màn trời lại xuất hiện mới chữ .”\nLời này vừa ra , tất cả mọi người đều đồng loạt ngẩng đầu nhìn màn trời .\n“ Triều Tấn ( Tư Mã thị năm năm , quốc phúc năm .”\nnăm nguyệt năm nguyệt ) Tư Mã Viêm Soán Ngụy , đổi quốc hiệu vì tấn , định đô Lạc Dương , tức Tây Tấn năm , Tây Tấn diệt Đông Ngô , hoàn thành thống nhất .”\n“ Chú : Thục Hán tại Công nguyên năm Bị Tào Ngụy diệt vong\nNhìn thấy cái này , tất cả mọi người tại chỗ theo bản năng nhìn về phía Tào Thao .\nMà ở trong đó , cũng bao gồm Tuân Úc ở bên trong .\nMuốn nói tất cả mọi người tại chỗ bên trong , ai tâm tình chập chờn lớn nhất ? Chỉ sợ không phải Tuân Úc không ai có thể hơn .\nVốn là nhìn xem Tào Phi bức bách Hán Hiến Đế nhường ngôi , nội tâm của hắn liền tuôn ra một cỗ cực lớn phẫn hận .\nNhưng nhìn đến cuối cùng cư nhiên bị cái gọi là triều Tấn , Tư Mã thị thống nhất thiên hạ .\nTuân Úc lập tức cũng không biết nên nói những gì .\n“ Tư Mã thị ... Tư Mã thị ...”\nTào Thao trong miệng một mực nhắc tới Tư Mã thị tên .\n...\nHán triều .\nNguyên thú 4 năm .\n“ Quốc phúc năm sao ?”\nVị Ương Cung phía trước , Lưu Triệt sờ một cái sợi râu , gật đầu một cái .\n“ Vẫn được .”\n“ Nhưng cái này Đông Hán , Tây Hán là có ý gì ?”\n“ Vì cái gì thật tốt một tên đại hán , còn phân làm Đông Hán Tây Hán ?”\nNghĩ tới đây , Lưu Triệt nhíu chặt lông mày , không biết nên nói cái gì .\n“ Bệ hạ ...”\nVệ Thanh thận trọng ngẩng đầu nhìn một mắt Lưu Triệt .\n“ Ân ? Trọng Khanh ?”\nThấy là Vệ Thanh phát ra âm thanh , Lưu Triệt mặt lộ vẻ ôn hòa thần sắc nói :\n“ Trọng Khanh , có cái gì nói chính là .”\n“ Bệ hạ , màn trời có một câu nói , tôn thất Lưu Tú thừa cơ dựng lên ...”\nNói xong , Vệ Thanh ngồi về tại chỗ , cúi đầu không nói thêm gì nữa .\nMà Lưu Triệt , thì lập tức có chút ngây người .\nThừa cơ ? Gì tình huống mới cần thừa cơ ?\nHắn đã biết Vệ Thanh muốn nói là cái gì .\n“ Ai ...”\n...\nTần triều .\nThủy Hoàng ba mươi năm .\nChương Đài cung .\nLúc này Chương Đài cung bên ngoài , rậm rạp chằng chịt phủ phục vài trăm người , tất cả mọi người đều nơm nớp lo sợ nằm rạp trên mặt đất , không dám ngẩng đầu .\n“ Quốc phúc mười lăm năm ?!”\nTần Thuỷ Hoàng Doanh Chính mặt không thay đổi nhìn xem màn trời , một lần lại một lần nhắc tới quốc phúc mười lăm năm năm chữ này .\nMà dưới đáy thần tử , nghe cái này lặp lại một lần lại một lần lời nói , nội tâm thì càng ngày càng nặng .\nCó người đều sợ hãi sự tình hướng về xấu nhất phương hướng phát triển .\n“ Báo !!!”\n“ Bệ hạ , Hàm Dương nội thành bỗng nhiên truyền ra đại quy mô lời đồn đại ...”\nDoanh Chính đưa tay ngăn lại lời của người vừa tới , nhìn về phía phía dưới thần tử , lãnh đạm nói :\n“ Đều đứng lên đi .”\n“ Lý Tư , đi xử lý một chút .”\nLúc này truyền ra lời đồn đại còn có thể là cái gì ? Doanh Chính không cần nghe đều biết .\n“ Ừm , bệ hạ !”\nLý Tư thở dài một hơi , đứng lên , chắp tay thối lui ra khỏi Chương Đài cung .\n...\nĐường triều .\nTrinh Quán bảy năm .\n“ Đường triều ( Lý thị năm năm , quốc phúc năm .”\n“ Từ Đường quốc công Lý Uyên tại năm thiết lập , định đô Trường An .”\nnăm sao ?\nLý Thế Dân đứng tại cam lộ ngoài điện , nhẹ nhàng nhíu mày một cái , chậm rãi gật đầu một cái .\nPhía dưới rất nhiều thần tử , liếc mắt nhìn bệ hạ biểu lộ , đều nhìn nhau một cái , sau đó ngậm chặt miệng .\nLúc này , ai cũng không dám nói chuyện , bao quát Trình Tri Tiết ở bên trong .\nNói cái gì ? Chúc mừng bệ hạ , Đại Đường Hưởng quốc năm ?\nNhư thế nào ? Ngươi đây là cho rằng Đại Đường không nên vạn thế truyền thừa ?\nnăm ...”\nLý Thế Dân ở sâu trong nội tâm , bỗng nhiên toát ra rất lâu trước đây đêm khuya , chính mình một cái ý nghĩ .\n“ Hán triều năm , Chu triều năm ...”\n“ Nhưng triều Tấn năm ...”\nLý Thế Dân nghĩ tới đây , lại đem sâu trong nội tâm ý nghĩ kia ấn trở về .\n“ Chờ đã , bệ hạ ! Nhìn bầu trời màn ! Màn trời !!”\nTrình Tri Tiết trợn mắt hốc mồm nhìn xem màn trời , bị mới xuất hiện tin tức dọa đến có chút nói năng lộn xộn .\nBên cạnh Ngụy Chinh vốn định quát lớn một tiếng , cũng thấy một mắt màn trời hắn , cũng tương tự trong nháy mắt ngốc trệ ngay tại chỗ .\nNgười chung quanh thấy thế , lập tức nhìn về phía màn trời .\nLần này , tất cả mọi người đều bị trên thiên mạc mới xuất hiện chữ dọa đến không biết làm sao , đờ đẫn nhìn xem màn trời .\n“ Chu ( Vũ thị năm năm , quốc phúc năm .”\n“ Võ Tắc Thiên thiết lập triều đại , vì khác biệt với trong lịch sử Tiên Tần thời kỳ Chu triều mà xưng là Võ Chu .”\n“ Chú : Võ Tắc Thiên là trong lịch sử duy nhất chính thống nữ hoàng đế , chính thức cầm quyền 23 năm . Nên chính quyền bên trên nhận Trinh Quán chi trị , phía dưới mở ra nguyên thịnh thế , Sử Xưng Võ Chu chi trị\nLúc này Đại Đường , 8-9-10% người đều bị cái này mới xuất hiện tin tức đánh thẳng vào , đờ đẫn nhìn xem màn trời .\n“ Võ Chu ? Nữ hoàng đế ?”\nLý Thế Dân não hải trống không , mờ mịt nhìn về phía phía dưới các thần tử .\nMà tại chỗ tất cả thần tử , cũng đều thần sắc mờ mịt nhìn về phía Lý Thế Dân .\nGiờ khắc này , tất cả mọi người hệ thống ngôn ngữ đều rất giống mất cân đối .\nNhư Ngụy Chinh , há to miệng , lại mờ mịt đóng lại , sau đó lại mờ mịt nhìn về phía Phòng Huyền Linh bọn người .\nKhoa trương nhất là những cái kia võ tướng , như Trình Tri Tiết cùng Uất Trì Kính Đức bọn người , đặt mông ngồi dưới đất , mờ mịt nhìn đối phương .\n“ Cái này màn trời hẳn không phải là thật sao ?”\n“ Ta hẳn là còn ở trong mộng ?”\nTrình Tri Tiết nhỏ giọng nhắc tới .\nBỗng nhiên , Trình Tri Tiết đưa tay ra ba một cái đánh vào trên mặt của mình .\n“ Đau ?! Không phải là mộng ?”\nMà tất cả mọi người ở đây , nghe được thanh âm này , đều hồi phục thần trí .\nTất cả mọi người đều nhìn xem Lý Thế Dân .\nMà Lý Thế Dân thì đặt mông ngồi trên mặt đất .\n“ Bệ hạ !”\n“ Bệ hạ ...”\nTrưởng Tôn Vô Kỵ cùng Phòng Huyền Linh bọn người vội vàng vọt tới Lý Thế Dân bên cạnh , đem hắn dìu dắt đứng lên .\nLý Thế Dân tựa như lúc này đều không có lấy lại tinh thần , trong miệng nhắc tới :\n“ Cầm quyền năm , quốc phúc năm ?”\n“ Nữ hoàng đế ? Đại Đường xuất ra một cái nữ hoàng đế ?”\n...\nMinh triều .\nHồng Vũ mười năm .\n“ Minh triều ( Chu thị năm năm , quốc phúc năm .”\nNhìn thấy cái này , Chu Nguyên Chương dường như hài lòng , lại như là không hài lòng , gật đầu lại lắc đầu .\n“ Ai , vẫn là không có truyền vạn thế .”\n“ Phụ thân , thiên hạ ở đâu ra vạn thế chi vương triều ?”\nBên cạnh Chu Tiêu nghe nói như thế , rất là bất đắc dĩ nói .\n“ Mặc dù là dạng này , nhưng ta vẫn còn có chút không cam tâm .”\nNói đến đây , Chu Nguyên Chương lại cảm khái lắc đầu , sau đó lại nhìn về phía màn trời .\nNhưng là cái nhìn này , để cho Chu Nguyên Chương trực tiếp sững sờ tại chỗ .\n“ Chú : Minh triều từ minh Thái tổ Chu Nguyên Chương sở kiến , sơ kỳ đóng đô Nam Kinh , minh thành tổ Chu Lệ thời kì dời đô Bắc Kinh , chung truyền mười sáu đế .”\nChu Nguyên Chương nhìn thấy cái này , tràn đầy không dám tin thần sắc nhìn về phía bên cạnh Chu Tiêu .\nMà Chu Tiêu , nhưng là dùng thần sắc mờ mịt nhìn về phía Chu Nguyên Chương .\n“ Chu Lệ ?!”\n“ Minh thành tổ ?”\nLúc này lớn ngày mai phía dưới , dân chúng có lẽ còn không biết ý vị như thế nào , nhưng những cái kia người làm quan , cũng không dám tin nhìn xem màn trời .\nChu Lệ cũng coi như , có thể rõ thành Tổ ?!\n...\nMinh triều .\nVĩnh Lạc bảy năm .\n“ Phanh !”\nChu Lệ ly trà trên tay rơi trên mặt đất , nhưng hắn tựa như không có phát hiện , đáy lòng tuôn ra một cỗ hung ác cảm xúc , quay đầu dùng hung ác ánh mắt nhìn về phía bên cạnh Chu Cao Sí .\n“ Thành Tổ ?!”\nMà Chu Cao Sí nhưng là một mặt mộng nhìn cha của mình Chu Lệ .\n“ Ha ha , thành Tổ ...”\n“ Thành Tổ ...”\n“ Tổ ...”\nChu Lệ lập tức xụi lơ ở trên ghế , hai mắt vô thần nhìn xem màn trời .\n“ Phụ thân ?!”\nChu Cao Sí thấy thế , vội vàng đi đến Chu Lệ bên cạnh , lo lắng nhìn xem hắn .\n“ Lão đại , ngươi có biết hay không minh thành tổ đến cùng ý vị như thế nào ?”\n“ Phụ thân , tuyệt đối không phải ta !”\nChu Cao Sí nghe nói như thế , sau đó vội vàng ngữ khí kiên định nói .\nMà lúc này Chu Lệ tựa như hồi thần lại , nhíu chặt lông mày thì thào nói :\n“ Đúng , tuyệt đối không phải là ngươi , ngươi đương nhiên biết đem ta đổi thành minh thành tổ đến cùng ý vị như thế nào .”\n“ Ngươi sẽ không đổi .”\n“ Con cháu của ngươi cũng sẽ không đổi .”\n“ Chỉ cần là một cái bình thường tử tôn , bọn hắn cũng sẽ không đổi .”\nNghĩ tới đây , Chu Lệ ngẩng đầu nhìn Chu Cao Sí , mà Chu Cao Sí cũng tương tự nhìn xem Chu Lệ .\nHai người tựa hồ cũng nghĩ tới điều gì , trên mặt lộ ra thần sắc bất khả tư nghị .\n“ Chúng ta mạch này , tuyệt tự ?!”\nChỉ có chủ mạch tuyệt tự mới nói thông , bằng không thì , chủ mạch tử tôn ai dám cho Chu Lệ đổi thành minh thành tổ ?\nTổ ? Người nào không biết ý vị như thế nào ?\n...', 'output\\mp3\\Màn Trời Quyền Lực Diễn Biến Cùng Truyền Thừa\\0001_Thứ 1 chương Minh thành tổ.mp3', '2026-09-01T08:54:10.037116+00:00', 'completed', 'completed', 15511, 15511),
	(7, 7, '7639603255114203672', 2, 'Thứ 2 chương Quyền lực diễn biến cùng truyền thừa', 'Thứ chương Quyền lực diễn biến cùng truyền thừa\nHiện đại thời không .\n“ Hệ thống , màn trời đã đem lịch sử hướng đại biểu phóng xong a ?”\nVề đến nhà , Lý Ân Phàm trước tiên hỏi thăm trong đầu hệ thống .\nBa lần đã phát ra hoàn tất .】\n“ Vậy là tốt rồi .”\nLý Ân Phàm nói xong lời này , đem trên người ba lô ném ở một bên , đặt mông ngồi ở trên ghế sa lon , toàn thân trầm tĩnh lại .\n“ Mỗi khi quay tiết mục , liền sẽ để một vị hoàng đế đến hiện đại tới là sao ?”\nĐúng vậy .】\n“ Có thể đợi mấy ngày ?”\nBa ngày thời gian .】\nLý Ân Phàm nghe được cái này , gật đầu một cái , sau đó trầm ngâm một hồi sau lại nói :\n“ Nói thật , hệ thống , ta xem ra tiểu thuyết kinh nghiệm , ta thực sự không biết ngươi đến cùng muốn làm cái gì .”\n“ Thu thập nguyện lực ? Vẫn là tín ngưỡng ? Lại có lẽ là những thứ khác đồ vật gì ?”\n“ Kiếp trước ta biết , ta là bị đại vận đưa tiễn .”\n“ Ta biết ta không nên hỏi , có thể dạng này một mực hồ đồ tiếp .”\n“ Dù sao cũng là ở dị thế giới nhặt được một cái mạng đi .”\n“ Nhưng con người của ta , chính ta biết , vô luận dạng chuyện gì , đều thích hướng về xấu nhất phát triển suy nghĩ .”\n“ Nếu như không biết ngọn nguồn , chính ta rất lo lắng ta về sau sẽ làm ra cái gì tới .”\nNói xong , Lý Ân Phàm không nói gì , đi đến máy đun nước bên cạnh rót một chén nước , sau đó lại lần nữa ngồi trở lại ghế sô pha .\nTrong đầu hệ thống không có trước tiên hồi phục Lý Ân Phàm mà nói , tựa hồ là đang kiểm tra lấy cái gì .\nCó thể nói cho ngươi .】\n“ A ? Dễ nói chuyện như vậy ?”\nLý Ân Phàm có chút kinh ngạc , cái hệ thống này tựa hồ có chút dễ nói chuyện quá mức .\nKiếp trước thế giới của ngươi chạy tới năm , đường sau này , chính các ngươi đã tìm được chưa ?】\nLý Ân Phàm nghe vậy sững sờ , cau mày nói :\n“ Hệ thống , ngươi đây là ý gì ?”\nHệ thống từ mấy ngàn năm sau Hạ quốc mấy tỉ người , cử quốc chi lực sáng tạo .】\nNghe được cái này , Lý Ân Phàm tựa hồ đã đoán được cái gì , nhẹ giọng hỏi :\n“ Con đường của các ngươi , chạy tới cuối cùng rồi ?”\nHệ thống chưa hồi phục , tựa hồ đã ngầm thừa nhận .\n“ Ta đã biết .”\nLý Ân Phàm khẽ gật đầu một cái , sau đó lại nói :\n“ Kỳ thực chính ta nghĩ tới , nếu có một ngày đường dưới chân , đi đến cuối con đường , nên làm cái gì ?”\n“ Xuyên qua thời không , để cho trong lịch sử cùng một huyết mạch chính mình người , lấy chế độ của bọn hắn hoàn cảnh các loại , một lần nữa phát triển một lần khoa học kỹ thuật , đi tìm tòi , đi tìm .”\n“ Đây đúng là một biện pháp rất tốt .”\nNói đến đây , Lý Ân Phàm cũng không biết nên nói những gì , sau đó cầm điện thoại lên , bấm ra ngoài .\nĐiện thoại trong ống nghe âm thanh chỉ vang lên ba tiếng liền bị tiếp .\n“ Uy ? Phong ca ?”\n“ Phàm ca ?”\n“ Đúng , là ta , hỏi ngươi một chuyện .”\n“ Ngươi nói .”\n“ Kế tiếp thời gian nửa năm thứ bảy cuối tuần ngươi hẳn là không chuyện gì a ?”\n“ Thứ bảy ? Cuối tuần ?”\nThanh âm bên đầu điện thoại kia trầm mặc mấy giây sau , lại vang lên :\n“ Có chuyện gì không ?”\n“ Ta cái này tiếp một cái tiết mục , liên quan tới lịch sử loại , Đại Khố Xái nơi đó thu , mời ngươi tới thu tiết mục .”\n“ Ta phải suy tính một chút .”\nNghe được phải suy tính một chút , Lý Ân Phàm rất lý giải , nếu như là chính mình chợt nghe được cái này tin tức , cũng là nhất định muốn suy tính một chút .\n“ Ta có thể hỏi một chút còn có ai sao ?”\n“ Cái này không có gì không thể nói , ngươi , duy gia , còn có trong đám cái kia ẩn tàng nhị đại .”\n“ Ngươi đây là ...”\nĐiện thoại bên kia nghe được là ba người này , lập tức liền biết Lý Ân Phàm đánh chính là ý định gì .\nLương Phong , một cái bình thường kẻ làm thuê .\nNgụy Gia , một chỗ bên trên tiểu lão bản .\nĐến nỗi cái kia tại bọn hắn lịch sử thảo luận trong đám cái kia ẩn tàng nhị đại , tên là : Trần Xuyên Phú .\n“ Ba ngày sau ta tới tìm ngươi , nói kĩ càng một chút a .”\nBên đầu điện thoại kia Lương Phong lần này thật sự hứng thú .\n“ Hảo .”\n...\nBa ngày sau , một nhà trong nông gia nhạc .\nTrừ Lý Ân Phàm bên ngoài 3 người đều chăm chú nhìn trong tay trù tính .\n“ Cho nên nói , trừ ngươi ở ngoài , ba người chúng ta , nếu là có muốn nói cái gì , cũng có thể đứng tại trên sân khấu đi giảng , đi trả lời hiện trường người xem vấn đề ?”\nNghe được vấn đề này , Lý Ân Phàm gật đầu một cái , nghiêm túc hồi đáp :\n“ Nghiêm chỉnh mà nói , người chủ trì là một người , cũng chính là ta .”\n“ Ta phụ trách mỗi lần tiết mục chủ đề , hơn nữa chưởng khống tiết mục tiết tấu .”\n“ Nhưng , chủ giảng người là bốn người , chính là chúng ta 4 cái .”\n“ Cũng không chỉ là chủ giảng , chúng ta có đôi khi muốn thảo luận , cũng có thể ở phía trên thảo luận , cũng không chỉ là vô cùng khô khan một người ở trên vũ đài đứng giảng giải .”\nKhác ba người đều lý giải đến Lý Ân Phàm ý tứ .\nSau đó 3 người nhìn nhau một cái , Lương Phong dẫn đầu hỏi :\n“ Các ngươi thì sao ? Có hứng thú không ?”\nTrần Xuyên Phú không nói chuyện , mà là nhìn về phía Lý Ân Phàm chăm chú hỏi :\n“ Tiết mục chủ mạch lạc ngươi nghĩ kỹ sao ? Có khả năng sẽ bị phong .”\n“ Nghĩ kỹ , liền 《 Quyền lực diễn biến cùng truyền thừa 》.”\nLý Ân Phàm hết sức chăm chú gật đầu một cái rồi nói ra :\n“ Cái này ta cũng đưa ra đến Đại Khố Xái bên kia , bọn hắn không có phản đối .”\n“ Bọn hắn đương nhiên sẽ không phản đối , dù sao cái kéo lớn là bọn hắn định đoạt , có cái gì thứ không tốt , bọn hắn một đao cắt lại thả ra là được .”\nBên cạnh Ngụy Gia nhún nhún , rất là sao cũng được nói .\n“ Ngươi có thể đem ta mời đến , ta biết ngươi đánh chính là ý định gì .”\nTrần Xuyên Phú thả xuống trong tay trù tính , đốt một điếu thuốc .\n“ Nói thật , ta cảm thấy hứng thú vô cùng , dù sao có thể cùng rất nhiều người hết thảy thảo luận lịch sử .”\n“ Nhưng có mấy lời muốn nói ở phía trước , có chút ta biết nói , nhưng có một chút ta sẽ không nói .”\n“ Còn có một số , ta nói sau đó , sẽ để cho bên kia cắt bỏ .”\nLý Ân Phàm đương nhiên biết hắn nói cái gì , có chút dính đến điểm mẫn cảm , đừng nói hắn , Đại Khố Xái bên kia cũng sẽ không buông ra ngoài .\n“ Yên tâm , không có vấn đề , Đại Khố Xái bên kia lại so với ngươi còn để tâm .”\nSau đó 3 người nhìn lẫn nhau một cái , đều gật đầu một cái .\n“ Đi , vậy cứ như thế quyết định .”\n...\nMà liền tại Lý Ân Phàm bốn người bọn họ tại nông trại thương nghị thời điểm .\nHiện đại bản thời không quyền hạn chỗ cao nhất .\nMột đám người chăm chú nhìn phía trước màn hình to lớn , trên màn hình , rõ ràng là Lý Ân Phàm 4 người thân ảnh .\n“ Hết thảy đều sắp xếp xong xuôi .”\nNgồi ở phía trước bảy người đều lẫn nhau gật đầu một cái .\n“ Cứ như vậy , chúng ta không đi làm liên quan ?”\n“ Bên kia không cần , nếu như muốn can thiệp , bọn hắn bên kia đã sớm can thiệp , căn bản sẽ không tìm được hắn .”\nPhía trước nhất một người chỉ chỉ trên màn hình Lý Ân Phàm .\n“ Mặc kệ là chúng ta , vẫn là bọn hắn , nếu như can thiệp đi vào , vậy sẽ chỉ để cho trong lịch sử những cái kia vương triều trở thành cái tiếp theo chúng ta , hay là cái tiếp theo bọn hắn .”\n“ Đây không phải bọn hắn mong muốn , đồng dạng , đây cũng không phải là chúng ta mong muốn .”\n“ Muốn để những trong lịch sử vương triều bọn hắn kia chủ đạo chính mình , mà chúng ta chỉ có thể là xách một chút đề nghị .”\n“ Như vậy thì là kết quả tốt nhất .”\n“ Nhưng nếu như chúng ta an bài xong xuôi ...”\nNói chuyện người kia không có tiếp tục nói nữa .\nTại chỗ đều biết , đến bọn hắn cái thân phận này , bọn hắn an bài xong xuôi sự tình , nhất định sẽ trở thành người chủ đạo thân phận .\nDù là trong hiệp nghị không có viết .\nCó thể lặn dời mặc hóa phía dưới , cuối cùng sẽ dựa sát vào .\nMà như vậy thì rất tốt , dù là Đế Vương đi tới hiện đại , nhưng tại bản thân Đế Vương tư tưởng phía dưới , bọn hắn nhất định sẽ không bỏ rơi đi người chủ đạo thân phận .\nCái này cũng là bọn hắn , còn có tất cả mọi người ở đây mong muốn !\nĐể cho trong lịch sử những cái kia vương triều , một lần nữa đi một đầu con đường hoàn toàn khác .\nMà màn trời , giống như một cái hoa trong gương trăng trong nước , ngoại trừ Đế Vương , ai cũng tiếp xúc không đến , nhưng đối với sự vật tốt đẹp hướng tới , sẽ để cho cổ đại rất nhiều nhìn thấy màn trời người đi truy đuổi .\n“ Nói thật , ta thật sự là nghĩ không ra , mấy ngàn năm sau , chúng ta con đường vậy mà đến cuối cùng rồi .”\nLời này vừa ra , tất cả mọi người ở đây đều rơi vào trầm mặc .\n“ Không nói cái này , vị thứ nhất Đế Vương đến chính là ai , đã xác định a ?”\nPhía trước nhất người kia hỏi hướng đang tại thao tác dụng cụ nhân viên công tác .\n“ Lãnh đạo , bên kia đã phát tới .”\n“ Vị thứ nhất Đế Vương , Tần Thuỷ Hoàng Doanh Chính , cùng với ...”\n“ Ân , đến lúc đó bên kia phát tới tin tức , đem thân phận tin tức đưa qua .”\n...', 'output\\mp3\\Màn Trời Quyền Lực Diễn Biến Cùng Truyền Thừa\\0002_Thứ 2 chương Quyền lực diễn biến cùng truyền thừa.mp3', '2026-09-01T08:54:14.998956+00:00', 'completed', 'completed', 8444, 8444),
	(8, 7, '7639603876089299480', 3, 'Thứ 3 chương Vị thứ nhất', 'Thứ chương Vị thứ nhất\nHiện đại thời không .\n5:00 chiều .\nLý Ân Phàm cáo biệt Trần Xuyên giàu mấy người sau đó , trực tiếp đã về đến trong nhà , không có ở trên đường dừng lại .\n“ Hệ thống , ta chuẩn bị xong .”\nMàn trời chuẩn bị , đếm ngược\nLý Ân Phàm nghe đếm ngược âm thanh , hít vào một hơi thật sâu .\nHắn chuẩn bị tại màn trời phía trên , cùng các triều đại đổi thay những nhân vật kia chào hỏi , thuận tiện mời vị thứ nhất nhân vật lịch sử đi tới hiện đại thời không .\n...\nHán triều .\nNguyên thú 4 năm .\n“ Bệ hạ ! Bệ hạ !”\nVị Ương Cung bên ngoài , hoạn quan bước nhanh đi đến Lưu Triệt bên cạnh nhỏ giọng nói :\n“ Bệ hạ , màn trời một lần nữa sáng lên !”\n“ A ?”\nLưu Triệt nghe , chậm rãi đứng lên , để cho bên cạnh hoạn quan sửa sang lại một cái quần áo , tiếp đó hướng về ngoài cung đi đến .\n“ Ân ?”\nNhìn xem trên thiên mạc hình ảnh xuất hiện , Lưu Triệt nhíu mày một cái .\nTrên tấm hình , rất rõ ràng có thể nhìn ra là một tên nam tử , tóc ngắn , cùng bây giờ Hán triều có chút không hợp nhau .\nCác vị các triều đại đổi thay , thời kỳ Xuân Thu , Tần triều , Hán triều , Ngụy Thục Ngô , triều Tấn , Tùy triều , Đường triều , Tống triều cùng với nguyên minh xong các vị Đế Vương cùng với dân chúng , các ngươi khỏe a .】\nNghe được màn trời truyền đến câu nói này , Lưu Triệt cau mày liếc mắt nhìn bên cạnh chạy tới Vệ Thanh .\n“ Trọng khanh , hắn ý của lời này ?”\nVệ Thanh suy tư một chút , ngẩng đầu nhìn một mắt màn trời , sau đó dùng có chút không thể tưởng tượng nổi ngữ khí nói :\n“ Bệ hạ , ý của người kia , tựa hồ muốn nói , cao tổ bây giờ tựa hồ cũng có thể nhìn thấy hắn bộ dáng bây giờ .”\nCao tổ ?\nLưu Triệt có chút mộng .\n“ Thật là dạng này ?”\n...\nĐường triều .\nTrinh Quán bảy năm .\n“ Này ... Này ... Cái này ...”\nLý Thế Dân lúc này cũng nghĩ đến điểm này , bằng không thì trên thiên mạc người kia , tại sao có thể như vậy chào hỏi ?\nCơ hồ đem phía trước truyền tất cả triều đại đều chào hỏi một lần .\nCó thể các ngươi nghĩ tới , đúng vậy , ta hiện tại là tại cùng các triều đại đổi thay tất cả Đế Vương , cùng với dân chúng chào hỏi .】\nNói đến đây , Lý Ân Phàm cúi đầu nhìn một chút cái gì , sau đó ngẩng đầu lại nhìn xem màn trời nói :\nDùng các ngươi có thể hiểu được lời nói , chính là Hồng Vũ mười năm Chu Nguyên Chương , Vĩnh Lạc bảy năm Chu Lệ , bây giờ có thể đồng thời nghe được lời ta nói .】\nTrinh Quán bảy năm Đường Hoàng Lý Thế Dân , mở hoàng mười hai năm Tùy Đế Dương Kiên , các ngươi cũng là đồng thời có thể nghe được ta bây giờ lời nói .】\nBây giờ , các triều đại đổi thay , tất cả thời kì , đại gia , đều có thể nghe được lời ta nói .】\nCam lộ điện hạ phương , Ngụy Chinh , Trình Tri Tiết , Uất Trì Kính Đức bọn người , đều là trợn mắt hốc mồm nhìn xem màn trời .\nCái này đã hoàn toàn vượt ra khỏi bọn hắn có thể hiểu được phạm trù .\nLý Thế Dân càng là cố nén nội tâm kinh hãi , chuyên chú nhìn xem màn trời .\n...\nMinh triều .\nVĩnh Lạc bảy năm .\n“ A ?!!”\nChu Lệ nghe được màn trời phía trên người kia nêu ví dụ , lập tức cả kinh đứng lên .\n“ Hắn ... Hắn ... Hắn ... Nói gì ?!”\nChu Lệ quay đầu nhìn xem Chu Cao Sí , nghĩ xác nhận mình rốt cuộc có phải hay không còn chưa tỉnh ngủ , còn đang nằm mơ .\nCái gì gọi là bây giờ Hồng Vũ mười năm Chu Nguyên Chương , cũng có thể nhìn thấy ? Nghe được ?\n“ Cha , ngươi không nghe lầm .”\nChu Cao Sí chỉ là khẽ gật đầu một cái .\n“ Cha ....”\nChu Lệ xụi lơ trên ghế , nhẹ nhàng nỉ non một tiếng .\n...\nMinh triều .\nHồng Vũ mười năm .\nChu Nguyên Chương mặc dù có chút kinh ngạc màn trời lời nói , nhưng bây giờ trọng yếu nhất , vẫn là trước mặt người kia .\nMà lúc này , bao quát Chu Tiêu mười mấy vị huynh đệ ở bên trong , tất cả mọi người cũng đều không có quan tâm màn trời , đều tại nhìn trước mặt người kia .\nNgười kia , chính là Hồng Vũ mười năm Chu Lệ .\n“ Tứ ca , ngươi thực sự là một kẻ hung ác a !”\nChu Thu chẹp chẹp miệng , rất là cảm khái nhìn xem trước mặt chính mình vị này tứ ca .\n“ Lão tứ , thật là không có nghĩ đến a , ngươi vậy mà về sau trở thành hoàng đế .”\n“ Hơn nữa ...”\n“ Vẫn là tổ ?!”\nChung quanh mấy cái huynh đệ , đều là tại Chu Lệ bên cạnh đi tới đi lui , đánh giá Chu Lệ .\nMà Chu Lệ , lúc này đứng tại giữa đại điện , một cử động cũng không dám .\n“ Đi , đều cho ta đứng vững .”\nNghe nói như thế , ngoại trừ Chu Lệ , tất cả mọi người đều đứng ở Chu Nguyên Chương đằng sau .\n“ Lão tứ , ngươi tốt nhất mong đợi ngươi về sau không có tạo phản !”\nChu Nguyên Chương cau mày liếc mắt nhìn run lẩy bẩy Chu Lệ .\nTại ban đầu biết Chu Lệ xưng đế thời điểm , nói thật , Chu Nguyên Chương là có chút sinh khí .\nNhưng tại trải qua Mã hoàng hậu cùng Chu Tiêu phân tích cùng với an ủi sau đó , đã không có tức giận như vậy .\nBởi vì Chu Nguyên Chương đúng là từng có dạng này dự đoán !\nTại rất lâu phía trước , hắn liền đem ý nghĩ của mình , cho ngựa hoàng hậu còn có Chu Tiêu nói qua .\nBằng không thì hắn sẽ không phân đất phong hầu các con của mình .\nBây giờ duy nhất không thể chịu được , là Chu Lệ về sau xưng đế , là tạo Chu Tiêu phản .\nNhững thứ khác ?\nTin tưởng các ngươi hiện tại cũng có thể hiểu .】\nLúc này màn trời phía trên , âm thanh lại truyền tiếp , Chu Nguyên Chương bọn người cẩn thận nhìn xem màn trời .\n...\nHiện đại thời không .\n“ Ta bây giờ vị trí thời gian , là Công Nguyên năm , theo lý thuyết , tại các ngươi hậu thế .”\n“ Cách Tần triều hơn hai nghìn năm , cách Hán triều , trên dưới hai ngàn năm , cách Đường triều hơn 1,400 năm ...”\n“ Cũng liền Minh triều cách ta thời gian bây giờ tương đối gần , chỉ có mấy trăm năm .”\nLý Ân Phàm uống một ngụm đặt ở bên cạnh thủy , mới dùng tiếp tục nói tiếp :\n“ Các ngươi bây giờ có thể đang suy nghĩ , ta đến cùng có mục đích gì ? Tại sao sẽ như vậy làm ?”\nNói đến đây , Lý Ân Phàm trầm ngâm một chút rồi nói ra :\n“ Là có một chút không cam lòng a .”\n“ Đến nỗi cụ thể có cái nào không cam lòng ? Về sau tại màn trời truyền thời điểm , các ngươi sẽ biết .”\n...\nTần triều .\nThủy Hoàng ba mươi năm .\nChương Đài cung .\nTần Thuỷ Hoàng Doanh Chính thần sắc lãnh đạm nhìn xem màn trời , trong lòng không biết suy nghĩ cái gì .\nBên cạnh trên đất trống , một đám hoạn quan còn có quan viên , đều đang nắm chặt vẽ lấy , khắc lấy đồ vật gì .\nBây giờ nói nói chuyện chủ yếu nhất chuyện .】\nĐợi lát nữa chúng ta sẽ rút phần thưởng , sẽ ở trong lịch sử tất cả Đế Vương , tuyển một vị Đế Vương , đi tới ta chỗ này .】\nNghe nói như thế , Doanh Chính trong ánh mắt con ngươi co rụt lại , gắt gao nhìn xem màn trời .\nĐể các ngươi nhìn một chút hậu thế , cái này Trung Nguyên đại địa , đến cùng đã biến thành bộ dáng gì .】\nCũng biết giải đáp giải đáp các ngươi một chút nghi vấn .】\nĐương nhiên , đây hết thảy đều biết để cho màn trời phát ra tại các triều đại đổi thay màn trời phía trên .】\nCoi như thù lao , ta sẽ đưa tặng các ngươi một chút cao sản thu hoạch , cùng với trọn vẹn ghi chép lịch sử hoàn chỉnh sách sử .】\nNếu như còn có những thứ khác yêu cầu gì , ta cũng đều sẽ tận lực từng cái thỏa mãn .】\nTiếng nói rơi xuống , trong Chương Đài cung tất cả mọi người đều để đồ trong tay xuống , gắt gao nhìn xem màn trời .\nVề phía sau thế ? Cao sản thu hoạch ? Sách sử ?!\nTất cả mọi người ở đây , nội tâm đều tuôn ra một cỗ cực lớn khát vọng .\nĐặc biệt là sách sử , bây giờ Tần triều , có người quá nhiều muốn biết , đến cùng xảy ra chuyện gì ? để cho một cái cực lớn đế quốc , vẻn vẹn chỉ tồn tại mười lăm năm ?\nCác ngươi không cần lo lắng vấn đề an toàn , đi tới ta chỗ này , sẽ không đối với các ngươi tạo thành bất kỳ tổn thương .】\nHơn nữa , thời gian cũng chỉ có ba ngày , cũng chính là mặt trời lên mặt trời lặn ba lần , các ngươi liền sẽ trở lại các ngươi triều đại .】\nNhư vậy , bây giờ , rút ra thứ nhất .】\nMàn trời phía trên , Lý Ân Phàm âm thanh rơi xuống , Doanh Chính liền thấy màn trời bên cạnh xuất hiện một cái bàn quay , phía trên rậm rạp chằng chịt viết đầy tên .\nHảo , bắt đầu .】\nBàn quay bắt đầu điên cuồng chuyển động , các triều đại đổi thay , tất cả mọi người đều chăm chú nhìn chằm chằm bàn quay .\nNgừng !】\nChúc mừng vị thứ nhất Đế Vương , đến từ Thủy Hoàng ba mươi năm , Tần Thuỷ Hoàng Doanh Chính .】\nTiếng nói rơi xuống , lúc này trong Chương Đài cung , tất cả mọi người đều đang điên cuồng reo hò .\nMà Doanh Chính , lúc này nội tâm cũng đã tuôn ra một cỗ cuồng hỉ !\nCuồng hỉ đi qua , Doanh Chính sững sờ , sau đó trên mặt lộ ra mỉm cười nói :\n“ Thực sự là rất lâu đều không dạng này vui sướng qua .”\nĐến nỗi Doanh Chính có thể hay không lo lắng cho mình an nguy ?\nTại vừa rồi , Doanh Chính có lẽ còn lo lắng .\nNhưng bây giờ ? Nhìn xem trước mặt cái này đột nhiên xuất hiện một cánh cửa ánh sáng .\nDoanh Chính lập tức thì để xuống lo lắng của mình .\nDù sao loại thủ đoạn này , cùng trong truyền thuyết tiên nhân khác nhau ở chỗ nào ?\nNếu quả thật muốn hại chính mình ?\nDoanh Chính ngẩng đầu nhìn trời một chút màn , bật cười lắc đầu .\nTùy tiện tại màn trời phía trên phóng chút gì , cái kia Đại Tần rất nhanh liền xong .\n...', 'output\\mp3\\Màn Trời Quyền Lực Diễn Biến Cùng Truyền Thừa\\0003_Thứ 3 chương Vị thứ nhất.mp3', '2026-09-01T08:54:20.624488+00:00', 'completed', 'completed', 8768, 8768),
	(9, 7, '7639967826777735704', 4, 'Thứ 4 chương Hôm trước', 'Thứ chương Hôm trước\nHán triều .\nNguyên thú 4 năm .\nKhi nghe đến màn trời nói là Tần Thủy Hoàng Doanh Chính .\nLưu Triệt trong lòng tuôn ra một cỗ thất lạc cảm xúc , nhưng cùng lúc , lại bốc lên một vòng may mắn .\nMay mắn không phải mình ?\nCó một chút .\nLưu Triệt vẫn tương đối lo lắng đi hậu thế sẽ có cái gì phong hiểm , dù sao bây giờ đại hán không có Tần triều vội vã như vậy .\n“ Xem trước xem xét cũng tốt .”\nLưu Triệt nhẹ thở ra một hơi , sau đó vuốt vuốt trán của mình .\nBên cạnh Vệ Thanh ngược lại là vô cùng may mắn cái này màn trời vị thứ nhất Đế Vương không có chọn được bệ hạ của mình .\nXem như thống soái , hắn lúc nào cũng đối với hết thảy không biết phong hiểm ôm lấy mãnh liệt cảnh giác .\nBây giờ xem trước xem xét trong truyền thuyết này Tần Thủy Hoàng Doanh Chính đi trước , cũng rất tốt .\n“ Tần Thủy Hoàng Doanh Chính ?”\nVệ Thanh bỗng nhiên nhìn thấy bệ hạ nhẹ giọng thì thầm vài câu .\n...\nHán triều .\nHán bảy năm .\n“ Ân ?!”\nNgồi ở trên giường vốn đang tương đối tùy ý Lưu Bang , nghe được màn trời chọn là Tần Thủy Hoàng Doanh Chính , cả người đều lập tức trở nên hoạt bát .\n“ Thủy Hoàng ?”\nTại chỗ rất nhiều đại thần , đều nhìn nhau một cái , nháy nháy mắt .\nLưu Bang ngồi thẳng người , ánh mắt chuyên chú nhìn xem màn trời .\n“ Thủy Hoàng ba mươi năm Doanh Chính ? Cũng không biết cùng lúc đó ta thấy hắn có cái gì khác biệt .”\n...\nĐường triều .\nTrinh Quán bảy năm .\n“ Tần Thủy Hoàng Doanh Chính ?”\nLý Thế Dân nhớ tới sách sử phía trên đối với Doanh Chính ghi chép , trong lòng tuôn ra một cỗ hiếu kỳ .\nTrước kia hắn đối với Tần Thủy Hoàng Doanh Chính vẫn còn tương đối chán ghét , có thể ...\nChờ hắn ngồi lên vị trí này , hắn liền phát hiện một sự kiện .\nSách sử ? Tin hết , không bằng không tin .\nChung quy là người viết , mà chỉ cần là người , cái kia liền sẽ nhất định sẽ có lập trường của mình .\nĐơn giản tới nói , giống như là hắn hiện tại , trong mắt thế gia , đến cùng là dạng gì ?\nChính hắn đều nói không tốt .\n...\nTần triều .\nThủy Hoàng ba mươi năm .\nThủy Hoàng , ngươi có trong một đêm thời gian chuẩn bị , hơn nữa có thể mang theo một vị tùy tùng .】\nNgày thứ hai giờ Thìn một khắc , trước mặt ngươi cánh cửa ánh sáng sẽ đúng giờ mở ra .】\nChương Đài cung trước cửa Doanh Chính nghe nói như thế , có chút khẩn trương tâm tình lập tức buông lỏng xuống .\nHắn còn tưởng rằng quang môn xuất hiện , chính mình lập tức đã sắp qua đi .\nNếu như không an bài hảo , thời gian ba ngày , ai biết sẽ phát sinh cái gì ?\nTrước kia hắn cũng không lo lắng , nhưng tại nghe được Đại Tần quốc phúc chỉ có mười lăm năm thời điểm , hắn cũng đã bắt đầu nghĩ lại , toàn bộ Đại Tần bên trong , có phải hay không còn có cái gì chính mình không có chú ý tới ?\n“ Lý Tư , Mông Điềm theo quả nhân đi vào .”\n“ Những người khác , đều trở về đi .”\nGặp màn trời đã đóng lại , Tần Thủy Hoàng Doanh Chính quay đầu nhìn một chút rất nhiều đại thần , điểm Lý Tư cùng Mông Điềm hai người .\n“ Bệ hạ .”\nTiến vào Chương Đài cung , Lý Tư cùng Mông Điềm hai người cung kính hướng về phía Doanh Chính thi lễ một cái .\n“ Chờ quả nhân sau khi đi , Lý Tư , ngươi cùng Phù Tô cùng một chỗ xem trọng Đại Tần .”\n“ Ừm .”\nLý Tư cung kính trả lời .\n“ Mông Điềm , ngày mai ngươi theo quả nhân cùng một chỗ .”\nNghe nói như thế , Mông Điềm trong lòng tuôn ra một hồi cuồng hỉ , sau đó cố nén cỗ này vui sướng , lập tức trả lời :\n“ Ừm , bệ hạ .”\n“ Ân ...”\nDoanh Chính chậm rãi ngồi xuống thân thể , gật đầu một cái , sau đó nhíu chặt lông mày đang suy tư điều gì .\nLý Tư thấy thế , suy tư một chút , sau đó nhẹ nói :\n“ Bệ hạ , thế nhưng là đang suy tư tiễn đưa cái gì ?”\nThủy Hoàng Đế Doanh Chính cau mày khẽ gật đầu một cái nói đến :\n“ Nói không sai , quả nhân đúng là suy tư dùng cái gì tiễn đưa người hậu thế .”\n“ Dù sao , quả nhân thế nhưng là có sở cầu .”\nLời này vừa ra , tại chỗ 3 người đều trầm mặc xuống .\nMột lát sau , Mông Điềm khóe mắt quét nhìn bỗng nhiên liếc đến cái gì , trong đầu linh quang lóe lên .\n“ Bệ hạ , thần biết nên tiễn đưa cái gì .”\nNghe nói như thế , Lý Tư cùng Doanh Chính hai người đều nhìn về Mông Điềm .\nChỉ thấy Mông Điềm con mắt chăm chú nhìn chằm chằm treo ở một bên bảo kiếm .\n“ Ân ?!”\nDoanh Chính đứng lên , đi đến mang theo bảo kiếm phía trước , cầm lấy kiếm , cẩn thận vuốt nhẹ một hồi .\n“ Dùng kiếm này sao ? Chính xác rất tốt .”\n...\nNgày thứ hai .\nMinh triều .\nHồng Vũ mười năm .\n“ Muội tử , màn trời hiện ra sao ?”\nNắm chặt lên xong hướng Chu Nguyên Chương đang tại Mã hoàng hậu vị trí Khôn Ninh cung ăn hướng ăn .\nMã hoàng hậu nghe nói như thế , bất đắc dĩ liếc Chu Nguyên Chương một cái , nhẹ nói :\n“ Bây giờ còn chưa đến giờ Thìn , gấp cái gì .”\n“ Hắc hắc , ta không phải muốn nhìn một chút Thủy Hoàng Đế Doanh Chính đến cùng dài cái dạng gì đi .”\nMấy ngụm ăn xong trên tay bánh hấp , lại uống một ngụm cháo , Chu Nguyên Chương hài lòng gật đầu một cái .\n“ Bệ hạ , thái tử điện hạ xin gặp .”\nLúc này , một vị cung nữ đi đến Chu Nguyên Chương trước mặt cung kính nói .\n“ Xin gặp ? Hắn là không có chân dài ? Không biết mình đi vào ?”\nNghe thấy xin gặp hai chữ , Chu Nguyên Chương vốn là thật tốt tâm tình lập tức bị phá hư , tức giận nói .\n“ Ngươi cùng cung nữ đưa cái gì khí ?”\nMã hoàng hậu đưa tay đánh một cái Chu Nguyên Chương , sau đó hướng về phía cung nữ nói :\n“ Để cho tiêu nhi vào đi .”\n“ Ừm .”\nCung nữ vội vàng lui ra .\nKhông đầy một lát , Thái tử Chu Tiêu cung kính đi đến , đầu tiên là hướng về phía Chu Nguyên Chương thi lễ một cái , lại đối Mã hoàng hậu thi lễ một cái .\n“ Bệ hạ ...”\n“ Ân ?”\nChu Nguyên Chương nghe được bệ hạ hai chữ , trừng tròng mắt nhìn xem Chu Tiêu .\n“ Cha ...”\nChu Tiêu bất đắc dĩ hô một tiếng .\n“ Ân !”\nChu Nguyên Chương lúc này mới hài lòng gật đầu một cái .\nBên cạnh Mã hoàng hậu thấy một màn này , cảm thấy hết sức buồn cười .\nTình hình như vậy đã xảy ra vô số lần , nhưng mỗi cái sáng sớm , y nguyên vẫn là sẽ phát sinh .\n“ Tiêu nhi , ăn qua hướng đã ăn sao ?”\nMã hoàng hậu để cho Chu Tiêu ngồi vào bên cạnh mình , nhẹ giọng hỏi .\n“ Còn không có .”\n“ Còn không có không nhanh chút ăn ?”\nBên cạnh Chu Nguyên Chương lại trừng Chu Tiêu một mắt , tức giận nói .\n“ Đừng để ý tới cha ngươi .”\nMã hoàng hậu trừng trở về , để cho Chu Nguyên Chương cổ co rụt lại .\nLần này , để cho Chu Tiêu cố nén nội tâm ý cười , vội vàng cầm lấy bánh hấp bắt đầu ăn .\n“ Bệ hạ , mấy vị hoàng tử xin gặp .”\nLại là vừa rồi cung nữ , đi đến , cung kính hướng về phía Chu Nguyên Chương nói .\n“ Ân , để bọn hắn vào a .”\nChu Nguyên Chương bình tĩnh gật đầu một cái .\nMột bên Mã hoàng hậu dừng một chút , lại khôi phục nguyên trạng , không hề nói gì .\nMã hoàng hậu biết rõ dạng này đối đãi khác biệt , nhất định sẽ làm cho bọn nhỏ phát hiện .\nNhưng ở nàng nhìn lại , dạng này không có gì không tốt .\nTừ căn nguyên xử trảm Đoạn mỗ chút hài tử tưởng niệm , để tránh về sau phát sinh huyết tinh .\nDù sao từ nhỏ đến lớn , nàng thấy qua quá nhiều chuyện như vậy .\n...\nHiện đại thời không .\nLý Ân Phàm thật sớm rời khỏi giường , đem gian phòng một lần nữa lại quét dọn một lần .\nTần Thủy Hoàng Doanh Chính , Mông Điềm chứng minh thân phận đã đưa tới .】\n“ Ân ?”\nĐang tại rửa mặt Lý Ân Phàm nháy nháy mắt , nhẹ giọng hỏi :\n“ Doanh Chính mang chính là Mông Điềm ? Ta còn tưởng rằng sẽ mang Phù Tô .”\n“ Hơn nữa , bọn hắn còn có chứng minh thân phận ?”\nLý Ân Phàm vội vàng rửa mặt xong , xoa xoa tay .\n“ Hệ thống , hai người bọn họ chứng minh thân phận ở đâu ?”\nMở cửa phòng .】\nLý Ân Phàm theo âm thanh của hệ thống , mở cửa phòng , lập tức liền phát hiện đặt ở cửa ra vào một cái bao .\n“ A ? Chuyển phát nhanh ?”\nLần này , để cho Lý Ân Phàm đối với hệ thống năng lực tò mò .\nNhặt lên chuyển phát nhanh , Lý Ân Phàm đầu tiên là cẩn thận nhìn một chút chuyển phát nhanh bên trên địa chỉ .\n“ Cái này ?!”\nChuyển phát nhanh là từ Tây An một bộ xuất xứ phát ra .\nNhưng phía trên thời gian , Lý Ân Phàm tử cẩn thận nhỏ nhìn mười mấy lần .\n“ Hôm trước ?”\nThấy mình không nhìn lầm , Lý Ân Phàm sững sờ tại chỗ .\n...\nHiện đại thời không .\nMột chỗ không biết tên núi lớn nội bộ .\n“ Cứ như vậy từng bước một dẫn đạo hắn .”\n“ Quen thuộc lịch sử , hơn nữa còn là một cái người xuyên việt , hẳn là một cái người thông minh .”\n“ Chúng ta cũng không muốn hắn giống trong tiểu thuyết người xuyên việt , mua một cái đồ vật , bán thứ gì còn cẩn thận từng li từng tí trong lòng run sợ .”\n“ Tiếp tục như vậy , có thể thay đổi cái gì lịch sử ?”\n“ Cho dù có hoàng đế nguyện ý thay đổi , thế nhưng cũng chỉ là cực thiểu số , thậm chí có thể không có .”\n“ Những hoàng đế kia , chỉ sợ tới một chuyến hiện đại , mang về đồ vật cũng chỉ sẽ phong bế trong hoàng cung tự ngu tự nhạc .”\n“ Muốn làm liền muốn đại quy mô làm ! Đem hắn lòng can đảm , bồi dưỡng lên .”\n“ Đem những hoàng đế kia dã tâm , cũng muốn bồi dưỡng lên !”\n“ Chờ hắn phát hiện , chính là chúng ta cùng hắn sinh ra ăn ý thời điểm .”\nNói xong lời này , dẫn đầu một người , tiếp tục đối với bên cạnh nói :\n“ Diễn viên chuẩn bị vào sân , hơn một năm chuẩn bị , bây giờ tại hắn 1 km phạm vi bên trong , bây giờ tất cả đều là người của chúng ta a ?”\nĐứng tại bên cạnh hắn người kia trọng trọng gật đầu một cái nói :\n“ Đã tất cả đều là chúng ta người .”\n“ Hảo , còn có ô tô các thứ cũng muốn chuẩn bị kỹ càng .”\n“ Có thể lặp lại , để cho hắn chậm rãi phát hiện , nhưng không cần làm quá rõ ràng .”\n“ Lâu như vậy chuẩn bị , cũng nên đến kiểm nghiệm thời điểm !”\n......', 'output\\mp3\\Màn Trời Quyền Lực Diễn Biến Cùng Truyền Thừa\\0004_Thứ 4 chương Hôm trước.mp3', '2026-09-01T08:54:26.276917+00:00', 'completed', 'completed', 9217, 9217),
	(10, 7, '7639968454010749464', 5, 'Thứ 5 chương Tây Bắc đại hán', 'Thứ chương Tây Bắc đại hán\nHiện đại thời không .\n“ Hôm trước ?”\nLý Ân Phàm hoài nghi có phải hay không có vấn đề gì , tại sao có hôm trước ?\nHôm qua mới chọn được Thủy Hoàng Đế Doanh Chính , vì cái gì hôm trước chứa Doanh Chính chứng minh thân phận chuyển phát nhanh liền phát đi ra ?\n“ Hệ thống ?”\nMột chút thủ đoạn nhỏ .】\n“ Phải không ?”\nLý Ân Phàm đột nhiên cảm giác được có chỗ nào không thích hợp , nhưng cũng nói không ra có cái gì không đúng .\nQuan trọng nhất là cũng không người có thể cùng chính mình thương nghị , cùng một chỗ đối với chuyện như vậy thảo luận .\nThời gian đã đến .】\nLý Ân Phàm suy nghĩ bị hệ thống đánh gãy , chỉ thấy bên trong phòng của mình , một cánh cửa ánh sáng bỗng nhiên xuất hiện .\n...\nĐường triều .\nTrinh Quán bảy năm .\nLý Thế Dân mang theo rất nhiều đại thần , lẳng lặng mà ngồi tại Cam Lộ điện bên ngoài .\n“ Đây là Thủy Hoàng Đế ?”\nLý Thế Dân chỉ thấy màn trời phía trên , một vị mặc hắc long bào , thân hình cao lớn nam tử đứng tại một chỗ địa phương trống trải .\nTên nam tử kia sợi râu dài , toàn thân để lộ ra một cỗ không giận tự uy khí chất .\nMà sau lưng thì đi theo một cái cùng hắn chiều cao không sai biệt lắm nam tử , nam tử kia trong tay cung kính nâng một thanh kiếm .\n“ Không nghĩ tới , đây chính là Thủy Hoàng Đế .”\nPhía dưới có đại thần xì xào bàn tán , số nhiều đều hết sức kinh ngạc .\nMà cách đám đại thần khá xa chỗ , mấy vị sử quan vừa nhìn màn trời , bên cạnh cầm bút lên đang bận việc .\n“ Cùng trẫm nghĩ bộ dáng , ngược lại có chút xuất nhập .”\nLý Thế Dân bình tĩnh gật đầu một cái .\n“ Ngược lại là một cái tiêu chuẩn Tây Bắc đại hán .”\n...\nMinh triều .\nVĩnh Lạc bảy năm .\n“ Đây là hậu thế nhà bộ dáng ?”\nGặp được Doanh Chính , Chu Lệ không chút kinh ngạc , ngược lại là đối với màn trời phía trên hiện ra hậu thế phòng ốc mười phần chấn kinh .\n“ Quá sáng ...”\n“ Hơn nữa , đó là lưu ly sao ?”\nChu Lệ chỉ vào trên thiên mạc hiện ra phòng ốc cửa sổ pha lê .\n“ Hẳn là lưu ly a , phụ thân .”\nChu Cao Sí cũng tương tự vô cùng chấn kinh , hậu thế vậy mà dùng lưu ly làm cửa sổ ?\nHơn nữa , cái này lưu ly lại cũng hết sức trong suốt .\nNhìn một chút , Chu Lệ nhíu mày một cái , nhẹ nói :\n“ Đây là đời sau lễ tiết ?”\nChỉ thấy màn trời phía trên , Lý Ân Phàm đưa tay ra , cùng Doanh Chính còn có Mông Điềm lẫn nhau nắm chặt lại , sau đó mời hai người bọn họ ngồi ở trên ghế sa lon .\n“ Lão đại , nhớ kỹ , vạn nhất có một ngày chúng ta được thỉnh mời đi , đừng để người hậu thế cảm thấy không hiểu lễ tiết .”\n“ Ân ?”\nChu Cao Sí nghe nói như thế có chút kinh ngạc hỏi :\n“ Cha , ngươi vậy mà không có sinh khí ?”\n“ Ta sinh khí cái gì ?”\nChu Lệ nghe vậy sững sờ , cau mày nhìn xem Chu Cao Sí .\n“ Cha , ta cho là ngươi thân là hoàng đế , sẽ đối với lễ tiết cái gì coi trọng , sẽ cảm thấy người hậu thế không hiểu lễ đâu .”\nChu Cao Sí vội vàng nói .\n“ Nhập gia tùy tục , tất nhiên đến hậu thế , đó là đương nhiên liền muốn sau đó thế lễ tiết .”\n“ Bằng không thì Tần triều Thủy Hoàng Đế đi , hậu thế chuẩn bị một cái Tần triều lễ tiết ?”\n“ Chúng ta Minh triều hoàng đế đi , hậu thế lại chuẩn bị một cái Minh triều lễ tiết ?”\nNói xong lời này , Chu Lệ liếc mắt nhìn bên cạnh Chu Cao Sí , nhẹ nói :\n“ Yên tâm , cầu người phải có một cái cầu người dáng vẻ , ta biết .”\n“ Từ màn trời chỗ hiện ra đến xem , chúng ta cầu hắn sẽ phi thường nhiều , mà hắn , hẳn là , hoặc có lẽ là không có sẽ cầu chúng ta .”\nPhía trước Chu Lệ liền nghĩ qua chuyện như vậy .\nChính mình nếu là đến Tần triều , Hán triều , hoặc có lẽ là Đường triều , chính mình có cái gì cầu đối phương đi ?\nKhông có !\nMà đối phương , ngược lại sẽ cầu chính mình .\nĐơn giản nhất một cái , chính là sách sử !\nNếu là dạng này , cái kia cầu người đương nhiên phải có một cái cầu người dáng vẻ .\nNgươi cầu đối phương , còn muốn để cho đối phương tuân theo ngươi lễ tiết yêu cầu các loại ? Dựa vào cái gì ?\nBằng ngươi là hoàng đế ?\nTừ Chu Lệ cùng Chu Cao Sí khoảng thời gian này phân tích đến xem , màn trời phía trên , người kia căn bản không có đối với hoàng đế một tơ một hào tôn kính hoặc có lẽ là kính sợ .\nNói hoàng đế thời điểm , cũng đều là hô to tên của bọn hắn .\nTừ chi tiết chỗ vào tay , Chu Lệ cùng Chu Cao Sí liền đã phân tích ra rất nhiều chuyện .\nMà dạng này phân tích , tại các triều đại đổi thay , có sự khác biệt hoàng đế trước mặt , đều bày có .\n...\nCho dù là những cái kia ngu ngốc hoàng đế , cũng đều bị thủ hạ thần tử hảo ngôn khuyên bảo lấy .\nVạn nhất bị quất đến , đến hậu thế , cũng làm cho bọn hắn không cần tùy hứng .\nDù là quả thật có chút hoàng đế đối với hậu thế không có sở cầu , chỉ muốn qua tốt chính mình một mẫu ba phần đất .\nCó thể , vạn nhất chính mình khai quốc hoàng đế đến hậu thế , bị màn trời phía trên người kia nói chuyện ...\nCái kia tính hợp pháp , sẽ phải đánh dấu hỏi .\nTại Trung Nguyên bên trên mảnh đất này , khai quốc hoàng đế hướng về phía màn trời , phủ nhận ngươi tính hợp pháp ?\nHoặc , bị chút hiểu biết lịch sử người , hướng về phía khắp thiên hạ tất cả bách tính , tới phủ định ngươi tính hợp pháp ? Đem ngươi hành động khắp thiên hạ cáo tri ?\nNhững cái kia thông minh hoàng đế , cơ hồ đều đã nghĩ đến điểm này .\nMàn trời , bản thân liền là một cái đại sát khí !!!\nNhư Lý Thế Dân , Chu Nguyên Chương , Lưu Bang , Lưu Triệt chờ ở trong lịch sử vô cùng lợi hại hoàng đế , đều vô cùng rõ ràng , từ màn trời xuất hiện bắt đầu , hoặc có lẽ là , từ màn trời phía trên , người kia xuất hiện nói chuyện bắt đầu .\nTrên đỉnh đầu bọn họ , cũng bắt đầu treo một thanh kiếm .\nĐến nỗi Lý Ân Phàm có biết hay không điểm này ?\nBây giờ , hắn là không biết .\n...\nHiện đại thời không .\nMột năm trước .\n“ Chuyện này tốt nhất chờ hắn chính mình ý thức được .”\n“ Để cho bên kia cũng thông qua hệ thống nói cho hắn biết , không cần lo lắng điểm này .”\n“ Bản thân liền là phải cải biến lịch sử , nếu như hắn biết , bắt đầu thận trọng từ lời nói đến việc làm , còn thế nào thay đổi ?”\nDài mảnh bàn chung quanh , hơn mười người học giả đều đang nghiêm túc thảo luận .\n“ Nói không sai , bên kia tuyển hắn cũng chính là coi trọng điểm này .”\n“ Bằng không thì tại sao không đi tuyển một chút quan viên hoặc có lẽ là học giả ?”\n“ Tháp ngà bên trong , học sinh có lẽ nhìn sự tình tương đối cực đoan , nhưng lão sư lại là vừa vặn .”\n“ Nội tâm còn có một số hận đời , không có bị xã hội san bằng góc cạnh .”\n“ Không quen nhìn trong xã hội một ít chuyện , mới lựa chọn đi làm lão sư , dạng này người , nhìn hắn nói chuyện phiếm ghi chép , đối với lịch sử cách nhìn , cũng đúng lúc biểu lộ điểm này .”\n“ Không thích trong lịch sử bất luận một vị nào hoàng đế , sẽ không thiên hướng một cái nào đó triều đại .”\n“ Các triều đại đổi thay vương triều , tốt , hư , hắn phần lớn đều phân tích ra được .”\nMột đám người hướng về phía Lý Ân Phàm tại lịch sử thảo luận trong đám đó nói chuyện phiếm ghi chép , từng điểm từng điểm phân tích tính cách của hắn .\n“ Đúng , để cho bên kia ngàn vạn không muốn đi nhắc nhở hắn điểm này , bằng không thì rất dễ dàng liền trượt về cực đoan một mặt .”\n“ Tháp ngà bên trong , loại tình huống này vô cùng dễ dàng xuất hiện .”\n“ Được nhắc nhở , hoặc có lẽ là bị chèn ép một chút , nên cái gì cũng không dám lại nói , hoặc cái gì cũng dám nói .”\n“ Cái này đều không tốt .”\nDài mảnh bàn tít ngoài rìa chỗ , một cái nhân viên công tác gật đầu một cái , sau đó nghiêm túc ghi chép các học giả nói lời .\n“ Cho nên , biện pháp tốt nhất , vẫn là không muốn đi tiếp xúc hắn ?”\nGhi chép xong các học giả lời nói , tên kia nhân viên công tác rất là chăm chú hỏi .\n“ Ý kiến của ta là như thế này .”\n“ Nếu như chúng ta đi tiếp xúc hắn , vậy hắn khó tránh khỏi sẽ phải chịu một chút gò bó .”\n“ Trên thân thể không có chịu đến gò bó , nhưng tâm lý bên trên , là nhất định sẽ .”\n“ Tiếp xúc về sau , hắn mặc kệ nói là lời còn là làm việc , đều biết cân nhắc đến , chúng ta sẽ ra sao ?”\nLời này vừa ra , tại chỗ tất cả học giả đều nhẹ nhàng gật đầu biểu thị đồng ý .\n“ Biện pháp tốt nhất , chính là từ từ sinh ra ăn ý , cho hắn biết , chúng ta kỳ thực biết tất cả mọi chuyện , nhưng quốc gia sẽ không ngăn cản hắn , cũng sẽ không gò bó hắn , chỉ làm cho hắn cung cấp trợ giúp .”\n“ Hắn muốn làm cái gì , vậy thì đi làm ! Coi như làm sai , thì thế nào ?”\nNói xong người này , nhìn chung quanh một mắt tại chỗ hết thảy mọi người .\n“ Hậu thế đã chứng minh chúng ta đi con đường đều sai .”\n“ Vậy liệu rằng hắn ban đầu đi nhầm lộ , đến cuối cùng , ngược lại sẽ là chính xác đây này ?”\n“ Bây giờ chúng ta có vô số thử lỗi cơ hội , trong lịch sử vô số vương triều đều biết cho hắn thử lỗi cơ hội .”\n“ Chúng ta không cần lo lắng .”\nNhân viên công tác nghiêm túc ghi chép lại lời hắn nói , sau đó lại hỏi một vấn đề :\n“ Vậy hắn có thể hay không sinh ra bành trướng tâm lý , muốn đi trong lịch sử những cái kia vương triều bên trong làm mưa làm gió ?”\nHơn mười vị học giả nhìn nhau một cái , miệng đồng thanh nói :\n“ Sẽ không ! Hắn là một cái người xuyên việt !”\nNói xong câu đó , một người trong đó ngay sau đó nói tiếp :\n“ Bên kia tuyển người xuyên việt cũng là bởi vì nguyên nhân này .”\n“ Người xuyên việt chỉ có thể ý nghĩ nghĩ cách đi thay đổi lịch sử , mà không phải làm mưa làm gió .”\n“ Trong lòng bọn họ chỗ sâu , tại xuyên qua một khắc này , liền đã kèm theo thay đổi thế giới ý nghĩ !”\n“ Chỉ là , trước đó không có cơ hội thôi , bây giờ , đem cơ hội bày tại trước mặt hắn ...”\n...', 'output\\mp3\\Màn Trời Quyền Lực Diễn Biến Cùng Truyền Thừa\\0005_Thứ 5 chương Tây Bắc đại hán.mp3', '2026-09-01T08:54:54.021888+00:00', 'completed', 'completed', 9216, 9216),
	(11, 7, '7640341652703298072', 6, 'Thứ 6 chương Sử ký', 'Thứ chương Sử Ký\nHiện đại thời không .\nLý Ân Phàm cùng Doanh Chính cùng Mông Điềm chào hỏi bắt chuyện xong , mời hai người ngồi xuống .\n“ Mông Điềm ...”\nDoanh Chính hơi quay đầu , nhẹ giọng la lên một tiếng Mông Điềm .\n“ Tiên sinh , đây là bệ hạ chúng ta đưa cho ngươi lễ vật .”\nMông Điềm cung kính đi đến Doanh Chính bên cạnh , đem trong tay bảo kiếm nhẹ nhàng đặt ở trên bàn trà .\n“ Ân ?”\nLý Ân Phàm nghe vậy sững sờ , hắn vẫn thật không nghĩ tới , tới Đế Vương sẽ cho mình tặng quà .\nSau đó , Lý Ân Phàm phản ứng đầu tiên chính là cự tuyệt .\nNhưng mới vừa há miệng miệng , Mông Điềm liền ngay sau đó nói tiếp :\n“ Tiên sinh , thu cất đi , dù sao , chúng ta cũng có cầu ở ngài .”\n“ Cái này ...”\nLý Ân Phàm liếc mắt nhìn Mông Điềm , sau đó lại liếc mắt nhìn Doanh Chính .\nDoanh Chính lúc này sắc mặt biểu lộ thoáng có chút âm trầm .\nLý Ân Phàm thấy thế , lập tức liền biết hai người bọn họ sở cầu vì cái gì .\nLiếc mắt nhìn để ở trên bàn bảo kiếm , Lý Ân Phàm đứng dậy , từ xó xỉnh chỗ , không có mở hộp sách trong đống lấy ra một quyển sách .\n“ Thủy Hoàng , đây là Hán triều Tư Mã Thiên viết 《 Sử Ký 》, bên trong ghi lại có quan hệ với Tần triều lịch sử .”\nLý Ân Phàm còn chuyên môn dùng máy tính phần mềm đem toàn bộ kiểu chữ chuyển đổi trở thành chữ tiểu triện .\nSau đó , Lý Ân Phàm đem sách nhẹ đặt ở trước mặt Doanh Chính .\nMông Điềm thấy thế , có chút nóng nảy nhìn xem Doanh Chính .\nMà Doanh Chính lúc này nội tâm mặc dù đồng dạng vội vàng , nhưng trên mặt vẫn là không hoảng hốt không vội vàng .\n“ Tiên sinh , xem trước một chút kiếm .”\nLý Ân Phàm cầm lấy bảo kiếm , phát hiện không biết , chưa thấy qua .\n“ Đây là cái gì kiếm ?”\n“ Lộc Lư .”\nDoanh Chính nhẹ thở ra hai chữ .\nMà Lý Ân Phàm nghe được hai chữ này , lập tức mộng ngay tại chỗ .\nLộc Lư ? Trong truyền thuyết Tần Thủy Hoàng Doanh Chính mang bên mình đeo bảo kiếm , lịch đại Tần Vương vương quyền tượng trưng ?!\nHiện đại có rất nhiều người cho là Tần Thủy Hoàng Doanh Chính bảo kiếm tùy thân là Định Tần , hoặc giả thuyết là Thái A .\nNhưng tại chính sử trong ghi chép , duy nhất có thể xác nhận kiếm , là Lộc Lư .\nCăn cứ 《 Sử Ký Thích khách liệt truyện 》 ghi chép , Kinh Kha giết Tần lúc , Tần Vương Doanh Chính nhổ chi kiếm tức là “ lộc lư kiếm ”, kỳ danh bắt nguồn từ chỗ chuôi kiếm hình cái vòng kết cấu ( Lộc Lư ), dễ dàng cho đeo cùng rút ra\nĐịnh Tần , tên này thấy nhiều ở phía sau gia truyền nói hoặc văn học diễn dịch , khuyết thiếu vô cùng xác thực tư liệu lịch sử ủng hộ , có thể vì tượng trưng xưng hô\nĐến nỗi Thái A , nhưng là Lý Tư 《 Gián Trục Khách Thư 》 viết “ phục thái a chi kiếm ”, nhưng nói vậy cũng thuộc phỏng đoán , không phải kết luận\n“ Đây có phải hay không là quá quý trọng .”\nLý Ân Phàm thận trọng đem lộc lư kiếm đặt ở trên bàn trà .\n“ Vô sự , tiên sinh , so với ngươi đối với chúng ta trợ giúp , không bằng vạn nhất .”\nDoanh Chính nói xong câu đó , mới chậm rãi cầm lấy 《 Sử Ký 》 cẩn thận nhìn lại .\nĐối diện Lý Ân Phàm thấy thế , bắt đầu cho hai người từng cái châm trà .\n...\nHán triều .\nNguyên thú 4 năm .\n“ Hán triều ? Tư Mã Thiên ?《 Sử Ký 》?”\n“ Tư Mã ?”\nLưu Triệt từ màn trời chỗ nghe được cái tên này , nhíu mày , quay đầu nhìn sau lưng Vệ Thanh hỏi :\n“ Trọng khanh , ngươi nghe chưa từng nghe qua cái tên này ?”\nVệ Thanh suy tư một phen , nghiêm túc hồi đáp :\n“ Bệ hạ , Tư Mã đàm luận ...”\n“ Tư Mã đàm luận ...”\nLưu Triệt như có điều suy nghĩ gật đầu một cái , hướng về phía bên cạnh chờ lấy hoạn quan nhẹ nói :\n“ Đi thăm dò một chút , Tư Mã nói hài tử tên gọi là gì .”\n...\nĐường triều .\nTrinh Quán bảy năm .\nLý Thế Dân lúc này trong tay đồng dạng để một bản 《 Sử Ký 》.\n“ Chậc chậc , cũng không biết Thủy Hoàng Đế nhìn thấy phía trên này ghi chép , lại là phản ứng gì .”\nPhía dưới Ngụy Chinh bọn người lại là vô cùng bất đắc dĩ nhìn xem Lý Thế Dân .\nXem náo nhiệt không ngại chuyện lớn ?\nBệ hạ , ngươi liền không sợ ngươi thấy được ghi chép Đại Đường sách sử , sẽ lộ ra phản ứng gì sao ?\nĐương nhiên , lời này , phía dưới đám đại thần là không dám nói .\nDù sao bây giờ tất cả mọi người , bao quát Lý Thế Dân ở bên trong , đều cố ý không để ý đến Đại Đường ra một cái nữ hoàng đế loại sự tình này .\nHơn nữa , còn đem Đại Đường chặn ngang chặt đứt , ở giữa ra một cái Võ Chu .\nAi cũng không dám nhắc lại loại sự tình này .\n...\nMinh triều .\nHồng Vũ mười năm .\n“ Tiêu nhi , ngươi hẳn là đọc thuộc lòng 《 Sử Ký 》 a ?”\nĐang đợi Doanh Chính nhìn 《 Sử Ký 》 thời điểm , Chu Nguyên Chương nhìn về phía bên cạnh Chu Tiêu , nhẹ giọng hỏi .\n“ Phụ thân ?”\nChu Tiêu đầu tiên là sững sờ , sau đó nặng nề gật đầu .\n“ Cái kia ta kiểm tra một chút ngươi , ngươi nói , Lý Tư là một cái dạng gì người ?”\n“ Lý Tư ?”\nChu Tiêu cau mày , rất là nghiêm túc suy tư .\nMột lát sau , Chu Tiêu mới chậm rãi nói :\n“ Trước đó ngược lại cho là bởi vì hắn là gian thần ...”\n“ A ?”\nChu Nguyên Chương đến gần Chu Tiêu một điểm , nghe hắn nói tiếp .\n...\nHiện đại thời không .\nLý Ân Phàm vốn cho rằng Doanh Chính sẽ phi thường phẫn nộ , hoặc có lẽ là chửi ầm lên một ít người .\nNhưng Doanh Chính nhìn xem lại vô cùng bình tĩnh .\nKhông chút hoang mang chậm rãi lật sách , trên mặt nhìn không ra một điểm phẫn nộ .\nBên cạnh Mông Điềm vốn có chút vội vàng tâm lý , cũng từ từ hòa hoãn lại , an tĩnh ngồi ở Doanh Chính bên cạnh .\n“ Tiên sinh , liên quan tới Đại Tần ghi chép , cũng chỉ có quyển này 《 Sử Ký 》 sao ?”\nLý Ân Phàm nghe vậy , thả xuống trong tay chén trà , nhẹ nói :\n“ Cặn kẽ , liền quyển này 《 Sử Ký 》, có vấn đề gì sao ?”\nThủy Hoàng Doanh Chính cầm trong tay 《 Sử Ký 》 thỉnh đặt ở trên bàn trà , học Lý Ân Phàm dáng vẻ , uống một ngụm trà .\nNước trà cửa vào , Doanh Chính cảm giác rõ ràng đã có một chút đắng , cũng không có bao lâu , liền lại cảm giác được một cỗ trở về cam , làm cho người dư vị vô cùng .\n“ Vấn đề chính là ở quá cặn kẽ .”\nDoanh Chính đem chén trà nhẹ đặt ở trên bàn trà , nhìn xem Lý Ân Phàm tiếp tục hỏi :\n“ Tiên sinh , cái này Hán triều Tư Mã Thiên là lúc nào viết 《 Sử Ký 》?”\n“ Trước công nguyên năm , Tư Mã Thiên bắt đầu sáng tác 《 Sử Ký 》, lúc đó là Hán Vũ Đế Lưu Triệt thời kì .”\n“ Lúc này khoảng cách Tần triều diệt vong , đã chín mươi bảy năm .”\nDoanh Chính khẽ gật đầu , bình tĩnh nói :\n“ Đây chính là vấn đề chỗ .”\n“ Một ít chuyện ghi lại chính xác không tệ , như Kinh Kha giết Tần ...”\n“ Thật có chút sự tình sao ?”\nNói đến đây , Doanh Chính lắc đầu , tiếp tục nói :\n“ Lý Tư ghi lại liền có chỗ mâu thuẫn .”\n“ Ân ?”\n...\nTần triều .\nChương Đài cung .\nLúc này Chương Đài cung bên ngoài , tất cả đại thần đều nhìn về Lý Tư .\nMà Lý Tư bản thân , lại lập tức sững sờ tại chỗ .\nDoanh Chính : Lý Tư ghi lại liền có rất rõ ràng chỗ mâu thuẫn .《 Sử Ký 》 ghi chép , hắn đi qua Triệu Cao thuyết phục , hai người hợp mưu , bí không phát tang , đổi chiếu soán vị , ủng lập Hồ Hợi là đế .】\nSử Ký 》 ghi lại là Triệu Cao vừa đấm vừa xoa , một phương diện cường điệu ngoan ngoãn theo lúc biến mới là Thánh Nhân làm , một phương diện khác lấy gây họa tới tử tôn cùng nhau uy hiếp , mới khiến cho Lý Tư cuối cùng ngửa mặt lên trời thở dài , rơi lệ đón nhận Triệu Cao an bài .】\nCái kia Lý Tư , làm sao lại rơi vào kết quả như vậy ?】\nMàn trời âm thanh truyền đến , trong Chương Đài cung , tất cả mọi người nhìn một chút Lý Tư , sau đó , lại nhìn một chút Triệu Cao .\nLý Tư cùng Triệu Cao hai người , mờ mịt đứng tại chỗ nhìn xem màn trời .\n“ Người tới !”\nMông Nghị trước tiên lên tiếng , lập tức kêu gọi ngoài cung hộ vệ .\n“ Đem Triệu Cao cầm xuống !”\n“ Lý Tư ...”\nNgồi ở phía trên Phù Tô lắc đầu .\nChờ đem Triệu Cao cầm xuống , Triệu Cao bản thân còn gương mặt mờ mịt .\n...', 'output\\mp3\\Màn Trời Quyền Lực Diễn Biến Cùng Truyền Thừa\\0006_Thứ 6 chương Sử ký.mp3', '2026-09-01T08:54:59.323150+00:00', 'completed', 'completed', 7470, 7470),
	(12, 7, '7640342092803211800', 7, 'Thứ 7 chương Quá bình thường', 'Thứ chương Quá bình thường\nHiện đại thời không .\n“ Huống chi , 3 người hợp mưu , đó là ai ghi chép xuống đâu ?”\nLý Ân Phàm nghe được cái này , rơi vào trầm tư .\nKỳ thực càng là hiểu rõ lịch sử , hắn liền phát hiện chính mình hiểu rõ càng ít .\nCó đôi khi thật là ấn chứng câu nói kia , hiểu càng nhiều , mới phát hiện chính mình hiểu càng ít .\nDoanh Chính nói có đạo lý sao ? Đương nhiên là có đạo lý .\nĐơn giản nhất một điểm , Triệu Cao , Lý Tư , Hồ Hợi , 3 người hợp mưu xuyên tạc di chiếu , đó là ai ghi chép xuống ?\nĐến nỗi khác tương đối phức tạp , liên quan tới Lý Tư bản thân .\n“ Ngươi nói đúng , Thủy Hoàng .”\n“ Trước đó ta kỳ thực liền có loại nghi vấn này .”\n“ Lý Tư tất nhiên bị Triệu Cao thuyết phục , hoặc có lẽ là bị Triệu Cao uy hiếp .”\n“ Vậy hắn cả người , kỳ thực là đã khuất phục Triệu Cao .”\n“ Hơn nữa , 3 người hợp mưu xuyên tạc di chiếu , vậy bọn hắn 3 người , liền hẳn là thiên nhiên chính trị minh hữu .”\nLý Ân Phàm nói đến đây , uống một hớp nước trà , mới dùng tiếp tục nói :\n“ Mặc kệ là bởi vì hậu thế suy đoán , bởi vì Phù Tô thượng vị , chính mình không chiếm được trọng dụng , pháp gia sẽ xuống dốc .”\n“ Còn là bởi vì khuất phục Triệu Cao .”\n“ Lý Tư sau cùng ghi chép chính xác vô cùng mâu thuẫn .”\nHợp mưu đổi chiếu thư soán vị .\nGián ngôn Hồ Hợi .\nBởi vì lý do nguyên nhân , a dua phụ họa Tần Nhị Thế tâm ý , muốn dùng cái này cầu được khoan dung .\nTrên viết thổi phồng “ Đốc Trách chi thuật ” ( Gặp 《 Hành Đốc Trách Thư 》), xưng hiền chủ làm chuyên quyền độc đoán , làm cho thiên hạ phục tùng tại bản thân tư dục .\nDâng thư vạch tội Triệu Cao tự ý Quyền Nguy Quốc , so với tử hi hữu kiếp Tống , Điền Thường Thí cùng ( Gặp 《 Thượng Thư Ngôn Triệu Cao 》).\nTả thừa tướng Lý Tư , Hữu thừa tướng Phùng Khứ Tật , tướng quân Phùng Kiếp trên viết trình lên khuyên ngăn , chỉ ra trộm loạn căn nguyên ở chỗ đóng giữ dịch nặng nề , thuế má hà khắc bạo , thỉnh cầu ngừng xây cung A phòng , giảm miễn bên cạnh đóng giữ chuyển thâu .\nBị vu oan giá hoạ .\nCuối cùng , bị di diệt tam tộc .\n“ Cái này kỳ thực chính là ta nghi ngờ điểm .”\nLý Ân Phàm đem chính mình nhận thấy đến nghi ngờ điểm từng cái liệt cử đi ra .\n“ Lý Tư tại cuối cùng ghi lại hành vi , quá mức mâu thuẫn .”\n“ Cái này hoàn toàn không giống như là hợp mưu tham dự qua xuyên tạc chiếu thư người .”\nNói xong những thứ này , Lý Ân Phàm dừng lại một hồi , mới dùng tiếp tục nói :\n“ Hơn nữa điểm trọng yếu nhất .”\n“ Cái này cũng là ta hoài nghi trong này nhất định có vấn đề một điểm .”\nMông Điềm cùng Doanh Chính hai người nhìn về phía Lý Ân Phàm .\n“《 Sử Ký 》 ghi chép , Thủy Hoàng bệnh tình nguy kịch lúc , trong mệnh lệnh xe phủ lệnh kiêm phù tỉ lệnh Triệu Cao , viết xong một phong cho trưởng tử Phù Tô chiếu thư , nội dung là để cho Phù Tô đem binh quyền giao cho Mông Điềm , cấp tốc trở về Hàm Dương chủ trì tang sự đồng thời an táng hắn .”\n“ Chiếu thư đã phong hảo cũng thêm đóng hoàng đế tỳ ấn , nhưng còn lưu lại trong tay Triệu Cao , chưa giao cho sứ giả đưa ra , Thủy Hoàng ngay tại cồn cát bình đài qua đời .”\nLý Ân Phàm nói xong liên quan tới 《 Sử Ký 》 bên trong ghi chép sau đó , mới dùng tiếp tục nói :\n“ Chúng ta trước hết không thảo luận đây rốt cuộc là ai biết cặn kẽ như vậy , nói cho Tư Mã Thiên .”\n“ Liền nói để cho ta nghi ngờ một điểm .”\n“ Thủy Hoàng là để cho Triệu Cao viết cho trưởng tử Phù Tô chiếu thư , hơn nữa , cũng là để cho Triệu Cao xây thêm hoàng đế tỳ ấn .”\n“ Vậy cái này bên trong quan Lý Tư chuyện gì ?”\n“ Nếu như dựa theo 《 Sử Ký 》 bên trong ghi chép , là bởi vì lúc đó vừa vặn Lý Tư , Hồ Hợi , Triệu Cao 3 người tại chỗ , Triệu Cao mới sẽ đi thuyết phục Lý Tư .”\n“ Mà Lý Tư là bởi vì chiếu thư là hắn thảo ra .”\n“ Cho nên Triệu Cao mới dùng là uy hiếp , lại là thuyết phục .”\n“ Lý Tư đầu tiên là cự tuyệt , tiếp đó lại là cự tuyệt , cuối cùng bất đắc dĩ mới đồng ý .”\n...\nMinh triều .\nHoằng Trị mười năm .\nChu Hậu Chiếu đứng tại Hoằng Trị hoàng đế Chu Hữu Đường bên cạnh , nghi ngờ hỏi phụ thân của mình :\n“ Phụ thân , trong này cũng có vấn đề gì sao ?”\nChu Hữu Đường nhìn xem khuôn mặt Chu Hậu Chiếu , nhẹ nói :\n“ Nếu như yếu mật mưu làm một chuyện xấu , ba người các ngươi bên trong , có hai người cũng đã đồng ý , một người khác chết sống không đồng ý .”\n“ Ngươi sẽ làm sao ?”\nĐương nhiên là giết hắn , bảo thủ bí mật !\nChu Hậu Chiếu trong đầu trong nháy mắt liền đụng tới ý nghĩ này .\n“ Thì ra là thế .”\nChu Hậu Chiếu rốt cuộc biết trong này không đúng chỗ nào .\nMột cái đều quyết tâm xuyên tạc chiếu thư người , vậy mà lại “ Nhân từ ” Thuyết phục cùng uy hiếp ?\nTriệu Cao chính mình cũng có thể viết chiếu thư , hơn nữa đóng dấu chồng hoàng đế ấn tỉ , lại bởi vì Lý Tư không đồng ý , ngược lại đi thuyết phục cùng uy hiếp Lý Tư ?\nHơn nữa , cái này còn không phải là chủ yếu nhất .\nChủ yếu nhất chuyện , dù là đến đằng sau , Triệu Cao lại còn là dùng chính trị tranh đấu thủ đoạn tới để cho Lý Tư xuống đài .\n...\nGiờ khắc này , các triều đại đổi thay vô số đại thần cũng đều nghĩ tới điểm này .\n3 người hợp mưu tham dự xuyên tạc di chiếu , hai người cũng đã đồng ý tình huống phía dưới , hoàn “ Nhân từ ” Buông tha người cuối cùng .\nBuông tha cũng coi như , Lý Tư là bức bách tại bất đắc dĩ tình huống như trên ý , Triệu Cao về sau cũng còn buông tha Lý Tư ?\nVậy mà không có nhường Lý Tư “ Tự sát ”?\nCòn cần đấu tranh chính trị thủ đoạn , tới “ Mưu hại ” Lý Tư .\nCái này chẳng lẽ không phải đảo ngược đã chứng minh một ít chuyện căn bản không tồn tại sao ?\nĐừng nói Triệu Cao .\nGiờ phút này , các triều đại đổi thay rất nhiều người , Hán triều , Tùy triều , Đường triều , Tống triều , Minh triều những đại thần kia , đều ở trong nội tâm bắt chước một lần .\nNếu như mình là Triệu Cao , tại thuyết phục Hồ Hợi sau đó .\nSẽ như thế nào đối đãi Lý Tư ?\nPhản ứng đầu tiên , đều sẽ giết hắn .\nDù là thật sự ban đầu thiếu hắn không thể , cần Lý Tư đồng ý .\nNhưng tại Hồ Hợi thượng vị sau đó , cũng chắc chắn sẽ để Lý Tư chết bởi “ Ngoài ý muốn ”.\nDù sao , ba người đều biết bí mật , vậy thật là bí mật sao ?\nLý Tư lại còn là hoàn toàn bất đắc dĩ đồng ý .\nChỉ một điểm này , tại trong lòng của bọn hắn , nếu như mình là Triệu Cao , cái kia Lý Tư liền chắc chắn phải chết .\nKhông có người sẽ cho mình lưu lại tai hoạ ngầm .\nĐây tuyệt đối lại là dùng ám sát các loại thủ đoạn tới giải quyết vấn đề .\nĐặc biệt là đối bọn hắn những thứ này sừng sững triều đình thật lâu đại thần tới nói , càng là như vậy .\nVì độc tài đại quyền , còn thiết kế hãm hại Lý Tư ?\nCái nào cần phiền toái như vậy ?\nThật không sợ tiết lộ bí mật ?\n...\nHiện đại thời không .\n“ Sự tình quá lớn , có thể xử lý thủ đoạn , là quá bình thường .”\nThủy Hoàng Đế Doanh Chính chỉ là nhàn nhạt nói một câu như vậy .\nDoanh Chính hiểu rõ Lý Tư , đồng dạng , cũng vô cùng hiểu rõ Triệu Cao , nếu như hai người bọn họ , thật sự có loại ý nghĩ này .\nĐặc biệt là Triệu Cao .\nVậy hắn tuyệt đối sẽ trực tiếp giết chết Lý Tư .\nCòn có thể để cho Lý Tư nhảy nhót lâu như vậy ?\n“ Trong lịch sử kỳ thực đã ghi lại vô số chuyện như vậy .”\n“ Tại dạng này chuyện đại sự trước mặt , không có người sẽ “ Nhân từ ”, cũng không có ai sẽ đi thường quy chương trình .”\n“ Dù là ban đầu sẽ thỏa hiệp , nhưng kết cục sau cùng ...”\n“ Nhất định sẽ là ám sát , hạ độc , để cho người ta “ Bị tự sát ” chờ đã .”\nLý Ân Phàm gật đầu một cái , vô cùng đồng ý Doanh Chính lời nói .\n...\nTần triều .\nChương Đài cung .\nLúc này Triệu Cao đã bị áp ra ngoài .\nLý Tư , nhưng là đờ đẫn nhìn xem màn trời , không biết suy nghĩ cái gì .\nPhù Tô nhưng là thở dài một hơi , tiếp tục xem màn trời .\nChung quanh đám đại thần , đều vô tình hay cố ý xem Lý Tư , tiếp đó lại nhìn một chút Phù Tô .\nMà Mông Nghị mấy người võ tướng , nhưng là vô tình hay cố ý làm thành một vòng tròn , đem rất nhiều đại thần vây quanh ở bên trong .\n......', 'output\\mp3\\Màn Trời Quyền Lực Diễn Biến Cùng Truyền Thừa\\0007_Thứ 7 chương Quá bình thường.mp3', '2026-09-01T08:55:04.661683+00:00', 'completed', 'completed', 7673, 7673),
	(13, 7, '7640715578214203928', 8, 'Thứ 8 chương Đất Thục', 'Thứ chương Đất Thục\nHiện đại thời không .\n“ Thủy Hoàng , Mông tướng quân , y phục này như thế nào ?”\nLập tức gần tới trưa , Lý Ân Phàm chuẩn bị mang Doanh Chính cùng Mông Điềm hai người đi ra ngoài .\nĐang cấp hai người đổi một bộ quần áo sau , Lý Ân Phàm nhìn xem hai người đứng tại toàn thân trước gương .\n“ Có điểm quái dị , nhưng có một loại nói không nên lời cảm giác thoải mái .”\nDoanh Chính giật giật áo sơ mi trên người , nhẹ nói .\n“ Bệ hạ nói rất đúng , có điểm lạ , nhưng cũng có một điểm thoải mái .”\nLý Ân Phàm đi lên trước , đem hai người áo sơmi kéo thẳng , tiếp đó ra hiệu hai người học chính mình , đem áo sơmi vào dây lưng quần bên trong .\nĐể cho tiện , Lý Ân Phàm cũng cùng bọn hắn mặc quần áo giống nhau quần .\n“ Dạng này ...”\nLý Ân Phàm ra hiệu hai người lại nhìn về phía toàn thân kính .\n“ Ân ?”\nHai người lần này nhìn lại , lập tức cũng cảm giác chính mình có cái gì bất đồng rồi .\nDoanh Chính rất rõ ràng có thể nhìn ra trên người mình để lộ ra cái kia cỗ uy nghiêm khí chất .\nMà Mông Điềm , nhưng là cho người ta một loại ngay ngắn cảm giác .\nĐặc biệt là hai người đứng thẳng người , tóc dài cuộn tại sau đầu , nhìn không chính diện , liền có thể nhìn ra đã cùng người hiện đại không có gì lớn khác biệt .\n“ Chờ đã .”\nLý Ân Phàm lại từ bên cạnh cầm một kiện âu phục .\nĐể cho Doanh Chính đem âu phục mặc lên , Lý Ân Phàm trái xem phải xem , cảm thấy có cái gì không đúng .\nSau khi suy nghĩ một chút , Lý Ân Phàm bỗng nhiên nghĩ đến trên TV cái nào đó tràng cảnh .\n“ Cái này .”\n“ Thủy Hoàng , ngươi mặc bên trên cái này thử xem .”\nLý Ân Phàm lại từ bên cạnh lấy ra một kiện kiểu áo Tôn Trung Sơn .\nChờ Doanh Chính một lần nữa mặc vào kiểu áo Tôn Trung Sơn sau đó , Lý Ân Phàm hai mắt tỏa sáng .\nBên cạnh Mông Điềm , đồng dạng cũng là hai mắt tỏa sáng .\nVốn là mặc áo sơmi Doanh Chính còn có thể để cho người ta nhìn ra uy nghiêm , hoặc có lẽ là có chút tài năng lộ rõ cảm giác .\nNhưng mặc vào kiểu áo Tôn Trung Sơn sau đó , rất rõ ràng liền có thể nhìn ra nội liễm .\n“ Bệ hạ , như vậy thì tốt nhiều .”\nDoanh Chính phủi một mắt trên TV đang phát hình bản tin thời sự , học người ở bên trong , đem hai tay chắp sau lưng .\n“ Ai ?”\nLý Ân Phàm sững sờ , lập tức trên mặt cười khẽ đi ra .\n“ Thủy Hoàng , ngươi lần này giống như về hưu cán bộ kỳ cựu .”\n“ Mông tướng quân mà nói , một mực đi theo Thủy Hoàng sau lưng , đồng dạng mặc bộ này kiểu áo Tôn Trung Sơn tốt nhất .”\nLý Ân Phàm lại cho Mông Điềm cầm một kiện kiểu áo Tôn Trung Sơn .\nKỳ thực Lý Ân Phàm vốn muốn cho hai người mặc y phục của mình .\nNhưng vì để tránh cho phiền phức , vẫn là để hai người đổi quần áo .\nMặc dù Lý Ân Phàm biết , sẽ không để cho người đoán được hai người là từ Tần triều xuyên qua mà đến .\nNhưng thỉnh thoảng chụp ảnh , chắc chắn sẽ để hai người phiền phức vô cùng .\nĐặc biệt là Doanh Chính .\nMặc hắc long bào , còn kèm theo uy nghiêm khí chất .\nVậy thật là sẽ cho người nghĩ chụp ảnh chung một phen .\nĐến lúc đó chắc chắn là lít nha lít nhít cầu chụp ảnh chung người .\n“ Tốt , cứ như vậy đi , Thủy Hoàng , Mông tướng quân , chúng ta đi ra ngoài .”\n...\nĐại Đường .\nTrinh Quán bảy năm .\nLý Thế Dân nhìn xem trong hình vẽ vẽ vẽ , lại nhìn một chút trên thiên mạc 3 người mặc quần áo .\n“ Để cho dệt nhiễm thự người , đêm nay nắm chặt làm ra mấy bộ dạng này quần áo đi ra .”\nCầm trên tay bức hoạ giao cho bên cạnh chờ lấy hoạn quan , Lý Thế Dân phân phó nói .\n“ Ừm .”\nHoạn quan cung kính tiếp nhận bức hoạ , lui ra ngoài .\n...\nCuối thời Đông Hán .\nKiến An 8 năm .\n“ Đây là ?!!”\nTào Tháo , Quách Gia , Tuân Úc bọn người nhìn xem Lý Ân Phàm mang theo Doanh Chính hai người đi ra ngoài , trên thiên mạc hiện ra tràng cảnh , đều là trợn mắt hốc mồm .\n“ Đây là phòng ốc ?!”\nTào Tháo lên tiếng kinh hô .\nCái kia hoàn toàn không nhìn thấy đầu nóc nhà , còn có xử bắn cái kia trong suốt lưu ly , này làm sao có thể để cho Tào Tháo tin tưởng đây là phòng ốc ?\n“ Còn có đường này ...”\nQuách Gia nhíu chặt lông mày nhìn xem trên thiên mạc 3 người đạp lộ , hoàn toàn không nghĩ ra , hậu thế đây là như thế nào tu cái nhìn này không nhìn thấy đầu lộ ?\nHơn nữa , tất cả đều là con đường như vậy ?\n“ Hậu thế a ... Hậu thế ...”\nTuân Úc không biết vì cái gì , nhìn thấy cái này đời sau tràng cảnh , trong lòng không có do một cỗ sa sút cảm giác .\nVương Tá chi tài ?\nGiống Tuân Úc thông minh như vậy người , nghĩ cũng quá nhiều nhiều lắm .\nTừ con đường , bọn hắn liền có thể rất rõ ràng nhìn ra một cái vương triều cường thịnh .\nNgay cả lộ đều có thể sửa thành cái dạng này , vương triều còn phải nói gì nữa sao ?\nĐặc biệt là hai bên đường phòng ốc , những cái kia tràn đầy lưu ly , nhìn không thấy cuối nóc nhà , càng là bằng chứng điểm này .\n“ Cái này hậu thế , còn có nhàn tâm tân trang một chút ven đường hoa hoa thảo thảo ?”\nQuách Gia bỗng nhiên chú ý tới một chi tiết , hai bên đường cây cối , còn có hoa thảo , hoàn toàn có thể nhìn ra chú tâm sửa chữa qua .\nToàn bộ đều giống nhau như đúc , cái này còn có thể là tự nhiên sinh trưởng ?\n“ Cái này đời sau vương triều , quốc lực đến cùng là bực nào cường thịnh ?!”\n...\nTam quốc thời kì .\nThục Hán .\nChương Vũ Nguyên năm .\n“ Chờ đã , Khổng Minh , màn trời phía trên , người kia nói , đây là đất Thục ?!”\nLưu Bị giống như nghe được cái gì đồ vật ghê gớm , dùng sức móc móc lỗ tai , hoài nghi mình nghe lầm .\n“ Bệ hạ , chính là đất Thục .”\nGia Cát Lượng đồng dạng cảm giác hết sức rung động .\nBọn hắn có thể không biết đất Thục là cái dạng gì sao ?\n“ Cái nhìn này không nhìn thấy đầu con đường , càng là đất Thục ?”\n...\nHiện đại thời không .\n“ Đây đúng là đất Thục , Thủy Hoàng .”\n“ Nhưng cùng trong lịch sử đất Thục , có sự bất đồng rất lớn .”\n“ Hán Trung bị phân chia ra ngoài , tuân nghĩa cũng đồng dạng bị phân chia ra ngoài .”\n“ Khác bị phân ra đi , còn có Trùng Khánh , chiêu thông , vạn châu , kiềm sông , phù lăng .”\nLý Ân Phàm từ phía sau sau lưng bên trong , lấy ra tấm phẳng , đưa cho bên cạnh Thủy Hoàng .\n“ Bây giờ đất Thục gọi : Tứ Xuyên .”\n“ Đã rất nhỏ .”\nDoanh Chính tiếp nhận Lý Ân Phàm đưa tới tấm phẳng , chăm chú nhìn trên bản đồ địa danh .\n...\nHồng Vũ mười năm .\nChu Nguyên Chương nhìn xem màn trời bên cạnh hiện ra địa đồ , cả người đều rơi vào trầm tư .\n“ Phụ thân , cái này đất Thục giống như chính xác quá lớn .”\n“ Màn trời không nói , ta còn không có phát hiện , bây giờ quay đầu tưởng tượng , Tam quốc thời kì , Gia Cát Lượng vậy mà có thể chỉ dựa vào Ích châu cái này Nhất Thục chi địa , bắc phạt Tào Ngụy .”\nChu Nguyên Chương nghe được âm thanh Chu Tiêu , quay đầu nhìn hắn , nhẹ nói :\n“ Cái kia tiêu nhi , ngươi thử tưởng tượng , ta vì cái gì không đem đất Thục , giống màn trời phía trên như thế phân đi ra ?”\n“ Ân ?”\nChu Tiêu nghe vậy sững sờ .\nĐúng a , phụ thân của mình chắc chắn là biết ở trong đó cất giấu nguy hiểm .\nĐất Thục đã như vậy khổng lồ , vậy vì sao phụ thân của mình , còn có trong lịch sử những cái kia Đế Vương , đều không đem đất Thục phân đi ra ?\n“ Nguyên triều thời kì , Hán Trung đúng là bị phân ra ngoài .”\n“ Nhưng đó là bởi vì nguyên nhân gì ?”\nChu Nguyên Chương chậm rãi dẫn dắt đến Chu Tiêu .\n“ Trong lịch sử , đất Thục chính xác thường xuyên phát sinh phản loạn .”\n“ Nhưng có chân chính thành công qua sao ?”\nChu Tiêu nội tâm tỉ mỉ nghĩ lại , phát hiện thật đúng là không có .\nCông Tôn thuật thành gia chính quyền thất bại .\nLưu Bị Thục Hán chính quyền thất bại .\nPhía trước Thục cùng sau Thục cũng thất bại .\nLý Thuận lớn Thục chính quyền cũng tương tự thất bại .\n“ Cái này , phụ thân , tại sao lại như thế ?!”\nChu Tiêu nghi hoặc nhìn Chu Nguyên Chương .\nChu Nguyên Chương không nói chuyện , chỉ là ra hiệu Chu Tiêu nhìn về phía màn trời .\nMà màn trời lúc này , vừa vặn giảng đến nơi này cái sự tình .\n......', 'output\\mp3\\Màn Trời Quyền Lực Diễn Biến Cùng Truyền Thừa\\0008_Thứ 8 chương Đất Thục.mp3', '2026-09-01T08:55:10.237490+00:00', 'completed', 'completed', 7607, 7607),
	(14, 7, '7640715834729431576', 9, 'Thứ 9 chương Thất phu vô tội', 'Thứ chương Thất phu vô tội\nHiện đại thời không .\n“ Đất Thục chính xác có thể làm một cái hậu phương lớn .”\n“ Nhưng , nhất định không thể làm một chính quyền trung tâm .”\nLý Ân Phàm xem như người địa phương , rất rõ ràng nguyên nhân trong đó .\nKiếp trước , bao quát hắn hiện tại , kỳ thực ra xã hội lâu , quay đầu nhìn về phía lịch sử , liền tinh tường vì cái gì đất Thục phản loạn , toàn bộ cũng không thể thành công .\n“ Địa lý nguyên nhân là lớn nhất một cái nhân tố .”\n“ Bị quần sơn vây quanh , rất khó ra ngoài , cái kia nội tâm rất dễ dàng liền sẽ lâm vào hưởng thụ cảm xúc .”\n“ Ra một chuyến xuyên , đều như vậy khó khăn , ai còn suy nghĩ ra ngoài ?”\n“ Toàn bộ đất Thục , đều cho ta một loại Tiểu Hình vương quốc cảm giác .”\n“ Chỉ cần thống hợp toàn bộ đất Thục , cảm giác kia thật giống như đã phản loạn thành công .”\n“ Cái này cũng là trong lịch sử , bao quát bây giờ , đất Thục người cùng Trung Nguyên người có rất lớn khác biệt nguyên nhân .”\n“ Đất Thục người thật sự vô cùng dễ dàng thỏa mãn , thỏa mãn sau đó liền bắt đầu hưởng thụ .”\n“ Sau đó thì sao ? Liền bắt đầu tự ngu tự nhạc .”\nNói xong địa lý nhân tố , Lý Ân Phàm vừa đi , bên cạnh lại tiếp tục nói :\n“ Còn có chính là tư tưởng đạo gia cũng vô cùng nồng hậu dày đặc .”\n“ Tứ Xuyên Đạo giáo là Đông Hán thời kì tại tư tưởng đạo gia cùng Ba Thục văn hóa chung cùng ảnh hưởng dưới hình thành tông giáo , phát nguyên tại cổ đại Ba Thục khu vực , thành đều xem như đạo giáo trọng yếu cái nôi , hắn truyền thừa kéo dài đến nay .”\n“ Dân chúng một cách tự nhiên liền nhận lấy tư tưởng đạo gia ảnh hưởng , đối với nho gia những cái kia lý niệm , tán đồng , nhưng không có cố chấp như vậy .”\nNói xong điểm này , Lý Ân Phàm lại nói :\n“ Còn có chính là chung quanh thổ ty .”\n“ Ngươi muốn đánh ra ngoài , cái này rất bình thường .”\n“ Nhưng chung quanh thổ ty , bọn hắn lại không nghĩ !”\n“ Bọn hắn chỉ muốn qua tốt chính mình một mẫu ba phần đất .”\n“ Hơn nữa , bọn hắn cũng sẽ không tín nhiệm ngươi .”\n“ Cái này đồng dạng là vì cái gì đất Thục khổng lồ như thế , cũng rất khó khăn phản loạn thành công nguyên nhân .”\n“ Chung quanh quần sơn rừng rậm , thổ ty đông đảo , ngươi đánh đi ra , chẳng lẽ không lo lắng thổ ty thu đến triều đình chỗ tốt tới đánh ngươi ?”\n“ Dù sao , không phải ai cũng là Gia Cát Lượng , để cho rất nhiều thổ ty có thể thành thành thật thật .”\n“ Tại những cái kia quần sơn trong rừng rậm , rất khó là những cái kia thổ ty đối thủ .”\nCái này cũng là Lý Ân Phàm cho rằng vô cùng trọng yếu một cái nguyên nhân .\nCái này cũng là vì cái gì đất Thục tại chống cự ngoại địch thời điểm , có thể bộc phát ra năng lượng kinh người .\nNội loạn thời điểm , lại giống như trò đùa của trẻ con .\n...\nMinh triều .\nHồng Vũ mười năm .\n“ Lần này biết đi ? Tiêu nhi .”\nChu Nguyên Chương khẽ gật đầu một cái , tán đồng màn trời lời nói .\n“ Biết phụ thân .”\n“ Kỳ thực hắn nói còn chưa đủ kỹ càng .”\nChu Nguyên Chương tiếp tục dạy Chu Tiêu .\n“ Đất Thục cho người ta một loại Tiểu Hình Vương Triều cảm giác .”\n“ Màn trời nói rất đúng , nhưng cặn kẽ không nói tinh tường .”\n“ Khi thống hợp toàn bộ đất Thục , trong triều đình hao tổn liền sẽ bắt đầu .”\n“ Bọn hắn rất dễ dàng thỏa mãn , thỏa mãn sau đó , liền sẽ bắt đầu tranh quyền đoạt lợi .”\n“ Mà ở trong đó , không phải ai cũng là Lưu Bang !”\nNói đến đây , Chu Nguyên Chương khoanh tay , nhìn xem màn trời nhẹ nhàng nói :\n“ Hơn nữa , phải biết , Lưu Bang , cũng không phải đất Thục người .”\n“ Trương Lương , Tiêu Hà các loại , bọn hắn cũng không phải đất Thục người ...”\n...\nHiện đại thời không .\n“ Đất Thục người chính là quá an nhàn rồi .”\n“ Hơn nữa cũng hưởng thụ an nhàn , cho nên đối với rất nhiều chuyện đều không có hứng thú .”\n“ Cho nên trong lịch sử rất nhiều vương triều đều rất yên tâm đất Thục .”\n“ Lần thứ nhất đem Hán Trung vẽ đi ra Nguyên triều , cũng là bởi vì tại đất Thục bị thiệt lớn .”\n“ Phía sau Thanh triều , cũng giống như thế , tại đất Thục bị thiệt lớn , mới suy nghĩ đem đất Thục tách rời ra ngoài .”\nDoanh Chính cùng Mông Điềm hai người đều như có điều suy nghĩ gật đầu một cái .\nLúc này , Mông Điềm đột nhiên hỏi :\n“ Vậy vì sao bây giờ lại đem đất Thục vạch ra đi nhiều như vậy chứ ?”\nLý Ân Phàm hai tay chắp sau lưng , chậm rãi đi tới .\n“ Bởi vì hiện đại thương nghiệp , chiến tranh các loại đều cùng cổ đại bất đồng rồi .”\n“ Các ngươi nhìn kỹ bản đồ một chút , bị phân ra đi phần lớn cũng là địa phương nào .”\nMông Điềm xích lại gần Doanh Chính bên cạnh , nghiêm túc nhìn một chút .\n“ Thì ra là thế .”\nQuen thuộc chiến tranh Mông Điềm lập tức liền biết tại sao lại đem những địa phương này vạch ra đi .\nDù là hắn không hiểu hiện đại rất nhiều đồ vật , nhưng chỉ cần xem xét vạch ra đi địa phương , liền biết là vì cái gì bị vạch ra đi .\n“ Nếu như những địa phương này còn thuộc về đất Thục , còn thuộc về Tứ Xuyên ...”\n“ Cái kia Tứ Xuyên liền thật là cái gì cũng không thiếu ...”\nLý Ân Phàm ý vị thâm trường nói một câu nói như vậy .\nLấy hiện đại giáo dục , còn có giao thông , cùng với thương nghiệp kinh tế các loại , nếu như những địa phương này đều thuộc về Tứ Xuyên .\nCái kia Tứ Xuyên không hề nghi ngờ , tuyệt đối sẽ trở thành đệ nhất tỉnh lớn .\nMột số thời khắc , dù là ngươi không có những tâm tư đó .\nCó thể vì chặt đứt tương lai cất giấu nguy hiểm , phía trên cũng sẽ làm như vậy .\nThất phu vô tội hoài bích kỳ tội , có đôi khi không chỉ nói là người !\nDù sao , thế kỷ trước cuối cùng , lúc đó đều nhanh thế kỷ hai mươi mốt , Thục nơi này , vậy mà đều còn có người xưng đế ...\nCái này để người ta nói thế nào ?!\nHơn nữa liền hiện đại loại tin tức này giao lưu tốc độ ...\nLý Ân Phàm nghĩ tới đây , cũng không biết làm như thế nào đi đánh giá .\nNgược lại nếu như mình là phía trên , cũng nhất định sẽ đem toàn bộ đất Thục tách rời .\nDù sao coi rất nhiều vấn đề cũng sẽ không tiếp tục là vấn đề , vậy ngươi bản thân , liền sẽ trở thành một vấn đề .\n...\nĐường triều .\nTrinh Quán bảy năm .\n“ Kho của nhà trời ....”\nLý Thế Dân nhìn xem trước mặt , đám hoạn quan khiêng ra tới dư đồ , khẽ gật đầu .\n“ Quốc ...”\n“ Xem ra vẫn là đánh giá rất nhiều có đạo lý ...”\n“ Hơn nữa , Ích châu hiểm tắc , ốc dã ngàn dặm Thiên phủ chi thổ\n“ Trẫm nhớ kỹ tựa như là Gia Cát Lượng đối với Ích châu , cũng chính là đối với đất Thục đánh giá .”\n“ Thiên phủ chi thổ ...”\nNhững đánh giá này , cũng đã nói rõ đất Thục , chỉ có thể xem như hậu phương lớn , không thể xem như trong chính quyền tâm .\n“ Trong lịch sử những cái kia đem đất Thục đương triều đình trung tâm đều thất bại .”\n“ Lưu Bang đem đất Thục xem như hậu phương lớn , lại thành công , vừa vặn đồng dạng nói rõ vấn đề .”\nLý Thế Dân trọng trọng tại dư đồ phía trên một chút một chút đất Thục chỗ .\n...\nĐại hán .\nHán bảy năm .\n“ Xem ra đời sau tất cả mọi người đều nhận thức được Ba Thục cái địa phương này hạn chế .”\nLưu Bang còn nhớ mình lấy Ba Thục sau đó , vì cái gì trước tiên liền nhảy ra cái chỗ kia .\nBa Thục chi địa thật sự có một cỗ ma lực , nếu như không phải trước tiên nhảy ra cái chỗ kia , Lưu Bang thật sự hoài nghi , chính mình sẽ trầm luân ở nơi đó .\nVòng quanh quần sơn trùng điệp , không chỉ là sẽ hạn chế người phát triển .\nCó đôi khi , chính ngươi nội tâm , cũng biết bởi vì quần sơn vờn quanh , bị hạn chế lại .\nLòng dạ loại vật này , nếu như không có tại trước tiên xông phá lồng giam đó .\nVậy thì thật sự sẽ cả một đời lâm vào nơi đó .\nTừ từ liền sẽ lâm vào bên trong hao tổn , tiếp đó lâm vào vĩnh viễn nội đấu .\n...\nTam quốc thời kì .\nThục Hán .\nChương Vũ Nguyên năm .\nLưu Bị nhíu chặt lông mày nhìn xem màn trời , bên cạnh Gia Cát Lượng bọn người , cũng đồng dạng cau mày .\n“ Trong lịch sử , tất cả đất Thục chính quyền , cũng không có lấy được thành công ?”\nNghe tới câu nói này , Lưu Bị lập tức lâm vào mờ mịt .\n“ Bệ hạ , chúng ta nhất định muốn trước tiên nhảy ra ngoài !”\nTại chỗ rất nhiều người thông minh đều biết mình không để ý đến địa phương nào .\nBọn hắn quá tự tin đất Thục địa phương này .\nNgược lại vừa vặn không để ý đến nhân tính , không để ý đến trong nhân tính truy cầu hưởng thụ một mặt kia .\n......', 'output\\mp3\\Màn Trời Quyền Lực Diễn Biến Cùng Truyền Thừa\\0009_Thứ 9 chương Thất phu vô tội.mp3', '2026-09-01T08:55:22.279292+00:00', 'completed', 'completed', 7942, 7942),
	(15, 7, '7641119505086677528', 10, 'Thứ 10 chương Căn cơ', 'Thứ chương Căn cơ\nHiện đại thời không .\n“ Giữa trưa chúng ta tùy tiện ăn một điểm cơm trung , buổi tối chúng ta đi ăn đất Thục đặc sắc nồi lẩu .”\nLý Ân Phàm mang theo Doanh Chính cùng Mông Điềm hai người đi vào quán ăn Trung Quốc .\n“ Lão bản , ăn cơm .”\nĐi vào cửa , Lý Ân Phàm hướng về phía bên cạnh chơi điện thoại di động lão bản hô một tiếng .\n“ Lúc này mới khoảng 11h , còn sớm , không có người nào .”\nLý Ân Phàm mang theo hai người đi vào một cái gian phòng , vừa đi vừa nói .\nTiến vào phòng , phục vụ viên cầm thực đơn cùng ấm trà đi đến .\nTiếp nhận menu , Lý Ân Phàm nhanh chóng điểm ba món ăn một món canh .\nĐến nỗi nói để cho Thủy Hoàng cùng Mông Điềm hai người gọi món ăn ?\nCách nhau hơn hai nghìn năm , hai người đoán chừng liền rất nhiều đồ ăn cũng chưa từng thấy .\nMà phục vụ viên tại Lý Ân Phàm gọi món ăn thời điểm , liếc Thủy Hoàng một cái , lại nhìn Mông Điềm một mắt , sau đó điều chỉnh một chút đặt ở cổ áo vi hình camera .\n“ Chỉ những thứ này a .”\nLý Ân Phàm đem menu đưa cho phục vụ viên .\n“ Tốt .”\nPhục vụ viên tùy ý tiếp nhận menu , chậm rãi đi ra ngoài , ra cửa đồng thời , còn thuận tay đóng cửa lại .\nChờ xác nhận cửa đóng kỹ sau đó , Lý Ân Phàm mới lên tiếng :\n“ Muốn uống chút rượu sao ? Thủy Hoàng , Mông tướng quân .”\n“ Rượu ?”\nThủy Hoàng không nói chuyện , Mông Điềm lại liếc mắt nhìn Thủy Hoàng .\n“ Rượu hiện đại cùng Tần triều lúc rượu có sự bất đồng rất lớn .”\n“ Nếu như muốn uống rượu mà nói , buổi tối hôm nay trong nhà , các ngươi trước tiên có thể thử một lần .”\n“ Hảo .”\nMông Điềm gật đầu một cái , hắn chính xác muốn thử xem rượu hiện đại .\nĐến nỗi Thủy Hoàng , thì đối với rượu không có hứng thú gì .\n“ Tiệm này nên tính là chung quanh tất cả trong tiệm , cơm trung ăn ngon nhất .”\n“ Từ một năm trước bắt đầu , cơ hồ mỗi ngày giữa trưa , lúc không có chuyện gì làm , ta đều sẽ đến ăn .”\nLý Ân Phàm cầm bình trà lên , từng cái cho hai người châm trà .\n“ Hơn nữa lão bản này rất lợi hại , cả nước các nơi đồ ăn đều biết .”\n“ Còn làm đều ăn rất ngon .”\nĐổ xong trà , Lý Ân Phàm một lần nữa ngồi trở lại vị trí của mình .\nBầu không khí yên lặng một hồi , Lý Ân Phàm gặp Thủy Hoàng vẫn như cũ cau mày , nhẹ nói :\n“ Thủy Hoàng , còn đang suy nghĩ 《 Sử Ký 》 bên trong liên quan tới Tần triều ghi chép ?”\nMông Điềm lúc này cũng nhìn về phía bệ hạ .\n“ Ân ...”\n“《 Sử Ký 》 bên trong mặc dù có rất nhiều sai lầm , nhưng bên trong chính xác cũng nói Tần triều tồn tại rất nhiều vấn đề .”\nMông Điềm nghe được cái này , nhìn về phía Lý Ân Phàm , nhẹ giọng dò hỏi :\n“ Tiên sinh , ngươi cảm thấy Tần triều lúc đó tồn tại cái nào vấn đề ?”\nLý Ân Phàm trầm tư , tinh tế suy tư một hồi sau , nhấp một ngụm trà , mới lên tiếng :\n“ Ta liền nói một chút cái nhìn của cá nhân ta a , đương nhiên , đây cũng chỉ là ta đứng tại lịch sử hạ du thái độ .”\n“ Thái độ cũng không hoàn toàn , dù sao ta cũng không hiểu lúc đó Tần triều cụ thể đến cùng là gì tình huống .”\nThủy Hoàng cùng Mông Điềm hai người đều gật đầu một cái , Mông Điềm nói :\n“ Vô sự , tiên sinh mời nói .”\nLý Ân Phàm khoanh tay , cõng nằm ở trên ghế dựa , nhẹ nói :\n“ Trong mắt của ta , Tần triều vấn đề lớn nhất , chính là không có căn cơ !”\n“ Căn cơ ?”\nThủy Hoàng nhíu nhíu mày , có chút không hiểu .\n“ Tiên sinh , căn cơ là có ý gì ?”\nMông Điềm trước tiên đưa ra nghi vấn của mình .\n“ Cây cối , các ngươi đã từng gặp .”\n“ Càng cao to hơn cây cối , nó dưới đáy căn , lại càng khổng lồ .”\n“ Mà chỉ có căn khổng lồ , cây cối mới có thể càng ngày càng cao lớn .”\n“ Cái kia vấn đề tới , Tần triều thiết lập sau đó , thuộc về Tần triều căn , ở nơi nào ?”\nThủy Hoàng hai người đều là cau mày .\n“ Tiên sinh , chúng ta không phải sao ?”\nMông Điềm nghe hiểu Lý Ân Phàm lời nói , nhưng hắn có chút không phục .\nNếu như nói Tần triều không có căn cơ , cái kia tính toán chuyện gì xảy ra ? Mông gia , Vương gia các loại đây tính toán là cái gì ?\n“ Ngươi có thể là , cũng có thể không phải .”\nLý Ân Phàm nhìn thẳng Mông Điềm nói ra một câu nói như vậy , sau đó nhìn về phía Thủy Hoàng Doanh Chính nói :\n“ Thủy Hoàng hẳn phải biết ta là có ý gì .”\n“ Có một chút lý giải .”\nLý Ân Phàm thấy thế , đem hai người chén trà cầm tới , tiếp đó lại đem bên cạnh mấy cái khoảng không chén trà cũng cầm tới .\nSau đó , Lý Ân Phàm đem mấy cái chén trà chồng chất ở tại cùng một chỗ .\n“ Mông tướng quân , tại cái này một chồng trong chén trà , quan trọng nhất là cái nào chén trà ?”\nTừ dưới lên trên , xếp xong chén trà sau đó , Lý Ân Phàm nhìn xem Mông Điềm hỏi .\n“ Cái này ...”\nMông Điềm tựa hồ biết Lý Ân Phàm muốn nói cái gì .\nMà Lý Ân Phàm gặp Mông Điềm nói không ra lời , lập tức liền biết hắn hiểu được .\n“ Xem ra Mông tướng quân đã biết .”\n“ Tại cái này một chồng trong chén trà , trọng yếu nhất , là tầng dưới chót cái này một cái chén trà .”\nLý Ân Phàm chỉ vào phía dưới cùng một cái kia chén trà .\n“ Nếu như cái này một cái chén trà , có chỗ nào hỏng , phía trên kia tất cả chén trà , đều biết bởi vì cái này một cái chén trà hư mất mà toàn bộ ném hỏng .”\n“ Tần triều , cái này tầng dưới chót chén trà hư rồi sao ? Ta không biết .”\n“ Nhưng ta biết một sự kiện .”\nLý Ân Phàm lúc này đem tất cả chén trà toàn bộ một lần nữa buông ra , tiếp đó , đem ấm trà bỏ vào một cái trên chén trà .\nTại đem ấm trà để lên thời điểm , Lý Ân Phàm lo lắng ném hỏng , liền lấy tay một mực xách theo ấm trà .\n“ Tần triều thiết lập sau đó , căn cơ của nó , y nguyên vẫn là tầng thấp nhất cái này một cái chén trà .”\n“ Nhưng nó thể lượng , đã từ vừa rồi chén trà đã biến thành bây giờ ấm trà , theo lý thuyết , từ Tần quốc đã biến thành Tần triều .”\n“ Căn cơ của nó , tựa hồ vẫn luôn không thay đổi !”\nLý Ân Phàm một cái tay khác , chỉ chỉ ấm trà phía dưới chén trà .\n“ Mà làm cái gì Thủy Hoàng chết về sau , Tần triều sẽ nhanh chóng sụp đổ ?”\n“ Bởi vì Thủy Hoàng chính là ta bây giờ xách theo ấm trà một cái tay này !”\nLý Ân Phàm vừa chỉ chỉ chính mình chính mình xách theo ấm trà tay kia .\nChờ nói xong vừa rồi một phen , Lý Ân Phàm xách theo ấm trà cái tay kia , thận trọng đem ấm trà đặt ở trên chén trà , sau đó buông lỏng tay ra .\nChỉ thấy ấm trà cong vẹo , tại sắp nghiêng đổ thời điểm , Lý Ân Phàm một lần nữa đem ấm trà xách hảo , tiếp đó đặt ở trên mặt bàn .\n“ Lần này , xem hiểu sao ? Mông tướng quân .”\n“ Các ngươi , hoặc có lẽ là ngươi , Vương Tiễn tướng quân Vương gia , cùng với Lý Tư bọn hắn , có lẽ tại Tần triều thiết lập sau đó , có thể đại biểu Tần triều .”\n“ Nhưng , các ngươi không đại biểu được Tần triều tầng dưới chót .”\n“ Không đại biểu được , cái này một cái chén trà !!!”\n“ Càng đại biểu không được Tần triều căn cơ ...”\nLý Ân Phàm vừa chỉ chỉ tầng thấp nhất một cái kia chén trà .\n“ Cây cối càng phồn vinh , vậy lại càng cần bộ rễ cường đại .”\n“ Bởi vì chỉ có bộ rễ cường đại , mới có thể hấp thu đầy đủ dinh dưỡng mới khiến cho đầu phồn vinh .”\n“ Nhưng đầu vượt ra khỏi bộ rễ cực hạn chịu đựng phồn vinh , sẽ chỉ làm cây cối khuynh đảo càng nhanh .”\nChờ Lý Ân Phàm sau khi nói xong , Doanh Chính cùng Mông Điềm hai người đều rơi vào trầm tư .\nMông Điềm nhớ tới phía trước rất nhiều chết ở thống nhất lục quốc trung binh lính .\nMà Thủy Hoàng Doanh Chính , thì nhớ tới lão Tần người ...\n“ Ngươi nói là lão Tần người ?”\nMông Điềm nhìn về phía Lý Ân Phàm , nhẹ giọng hỏi .\nMà Lý Ân Phàm thì lắc đầu , lại gật đầu một cái .\n“ Ngươi có chút nhỏ hẹp , Mông tướng quân .”\n“ Lão Tần người chính xác có thể đại biểu Tần triều căn cơ .”\n“ Nhưng ...”\nLý Ân Phàm lại đem ấm trà nhấc lên , tại ấm trà phía dưới , nhiều đặt một cái cái chén .\n“ Nếu như nói lão Tần người đại biểu lấy Tần triều căn cơ , vậy cái này đơn giản cũng liền nhiều một cái cái chén .”\n“ Có thể cải biến cái gì không ?”\nLý Ân Phàm đem chén trà thả phía trên , lần này , ấm trà kiên trì lâu một chút , nhưng theo trong ấm trà thủy lắc lư , y nguyên vẫn là nghiêng đổ .\nLý Ân Phàm tại ấm trà khuynh đảo trước tiên lấy được ấm trà .\n“ Trước đó ta cũng cho rằng lão Tần người là Tần triều căn cơ .”\n“ Nếu như Tần triều tại kiến lập sau đó , thiện đãi lão Tần người , đem bọn hắn thật chặt đoàn kết lại với nhau , Tần triều có lẽ sẽ giống trong lịch sử rất nhiều Trường Mệnh Vương Triều , tồn tại tiếp .”\n“ Nhưng ta tại so sánh trong lịch sử rất nhiều Trường Mệnh Vương Triều , cùng với Đoản Mệnh Vương Triều , đặc biệt là Tần triều cùng Tùy triều , liền có thể rất rõ ràng phát hiện vấn đề .”\nLý Ân Phàm nhấc lên ấm trà , một lần nữa cho hai người rót một chén trà .\n“ Hán triều thiết lập thứ trong lúc nhất thời , là nghỉ ngơi lấy lại sức .”\n“ Đường triều thiết lập sau đó thứ trong lúc nhất thời , làm lợi hại nhất , đồng dạng là nghỉ ngơi lấy lại sức .”\n“ Mà nghỉ ngơi lấy lại sức đầu này chính sách , thông suốt đầu thời nhà Đường thời kỳ Đường Cao Tổ , Đường Thái Tông , Đường Cao Tông .”\n“ Tống triều , cũng giống như thế ...”\n“ Triệu Khuông Dận đệ đệ , Triệu Quang Nghĩa tại sau khi thất bại , lập tức lại bắt đầu nghỉ ngơi lấy lại sức .”\n“ Đến nỗi Minh triều , lại càng không cần phải nói , sau khi đem Nguyên triều từ Trung Nguyên đuổi đi ra , Hồng Vũ hai mươi mốt năm , mới tại bắt cá hải tiêu diệt Bắc Nguyên tôn thất .”\nCó thể có người biết nói , Tùy triều không đúng sao ? Tùy triều không phải cũng nghỉ ngơi lấy lại sức sao ?\nNếu như biết Tùy Văn Đế Dương Kiên tại nhiệm trong lúc đó làm cái gì , cũng sẽ không nói như vậy .\nĐương nhiên , sau đó Lý Ân Phàm đang giảng đến Tùy triều thời điểm sẽ cặn kẽ nói Tùy triều .\n......', 'output\\mp3\\Màn Trời Quyền Lực Diễn Biến Cùng Truyền Thừa\\0010_Thứ 10 chương Căn cơ.mp3', '2026-09-01T08:55:27.750934+00:00', 'completed', 'completed', 9282, 9282),
	(16, 7, '7641121322973544984', 11, 'Thứ 11 chương Người vấn đề', 'Thứ chương Người vấn đề\nHiện đại thời không .\n“ Kỳ thực chính là đơn giản nhất một điểm , Thủy Hoàng , Mông tướng quân .”\n“ Tần triều thống nhất sau đó , cùng thống nhất trước đây khác biệt , thật sự lớn sao ?”\nLý Ân Phàm nhìn xem hai người , hỏi một cái vấn đề như vậy .\n“ Mấy trăm năm chiến loạn đi qua , sau khi Tần triều thiết lập , đối với tầng dưới chót tới nói , cùng lúc trước có cái gì khác biệt ?”\n“ Lao dịch , trưng binh các loại vẫn như cũ thông suốt tại tầng dưới chót .”\nKỳ thực chính là như vậy đơn giản một chuyện .\nMãi mới chờ đến lúc đến Tần triều thiết lập , tầng dưới chót nghĩ thầm , cuối cùng có thể nghỉ ngơi thật khỏe một chút .\nNhưng cùng trước đây thời gian , có cái gì không giống nhau địa phương ?\n“ Kỳ thực giống Trần Thắng Ngô Quảng khởi nghĩa Trần Thắng Ngô Quảng , trước đó ta còn có thể nghĩ rất nhiều rất nhiều thứ .”\nLý Ân Phàm thở dài một hơi , tiếp tục nói :\n“ Nghĩ Trần Thắng Ngô Quảng hai người này cũng là có danh tiếng , hai người chắc chắn là quý tộc , đây chính là lừa gạt tầng dưới chót .”\n“ Tần triều những năm cuối , có lẽ không có như vậy không chịu nổi , trước kia Lục quốc quý tộc , chắc chắn là một mực tại lừa gạt tầng dưới chót .”\n“ Mặc dù sự thật cũng chứng minh , lấy ngay lúc đó luật pháp tới nói , Trần Thắng Ngô Quảng cũng chính xác lừa gạt tầng dưới chót .”\n“ Nhưng vì cái gì hiện đại , chúng ta trong sách giáo khoa , đối với Trần Thắng Ngô Quảng khởi nghĩa Trần Thắng Ngô Quảng , như vậy tán thưởng ?”\nKhởi nghĩa ?\nThủy Hoàng cùng Mông Điềm hai người nghe được hai người kia , nhìn lẫn nhau một cái , không cắt đứt Lý Ân Phàm lời nói .\n“ Cho nên , ta về sau vẫn nghĩ , ở trong đó có phải hay không có cái gì ta không thấy khắc sâu mâu thuẫn ?”\n“ Về sau , ta đem liên quan tới Tần triều những năm cuối ghi chép nhìn rất nhiều lần .”\n“ Lại nghiêm túc nhìn một chút cận đại lịch sử , mới rốt cục phát hiện vấn đề .”\nNói đến đây , Lý Ân Phàm nhìn xem hai người ánh mắt , nói rất là nghiêm túc nói :\n“ Vì cái gì Trần Thắng Ngô Quảng hai người có thể dễ dàng như vậy lừa gạt tầng dưới chót dân chúng ?”\n“ Vì cái gì Lưu Bang có thể đơn giản như vậy tụ tập nhiều người như vậy ?”\n“ Vì cái gì Tần triều những năm cuối , nhiều như vậy tầng dưới chót sẽ hưởng ứng , đi theo ở phía sau bọn họ ?”\n“ Cái này , chỉ sợ không chỉ đơn giản là Lục quốc quý tộc tàn dư vấn đề .”\nLý Ân Phàm vì cái gì có thể nghĩ tới chỗ này ? Kỳ thực cũng là bởi vì trước đó Lý Ân Phàm nhìn lịch sử , quá mức phiến diện vấn đề .\nSau khi khắc sâu đọc một ít sách , Lý Ân Phàm nhìn một chút cận đại lịch sử , quay đầu đi xem Phong Kiến Vương Triều lịch sử , mới chợt nghĩ tới điểm này .\nLịch sử mâu thuẫn là khắc sâu , cũng là nhiều góc độ .\nMột số thời khắc , nếu như không hiểu rõ một vài thứ , thật là dù thế nào suy nghĩ đi suy xét , cũng biết chệch hướng con đường chính xác .\nMà có đôi khi , kỳ thực câu trả lời chính xác liền đặt ở chỗ đó , từ vừa mới bắt đầu , cũng đều đem câu trả lời chính xác cho ngươi .\nChỉ là ngươi cảm thấy quá đơn giản , có được quá mức dễ dàng , một mực không để ý đến nó .\nGiống như Lý Ân Phàm chính mình , quanh đi quẩn lại , có được đáp án , kỳ thực từ vừa mới bắt đầu liền bày ra ở trước mắt .\n“ Tần triều luật pháp , tại lúc đó là tốt .”\n“ Về sau Hán triều , cũng nhận Tần Luật .”\n“ Cái này cũng chính xác đã chứng minh Tần Luật tại lúc đó là không có vấn đề .”\n“ Nhưng tầng tầng tăng giá cả , không phải một người nào đó chuyên chúc , cũng không phải một cái nào đó triều đại chuyên chúc .”\n“ Đơn giản cho rằng Tần triều pháp luật cũng không khắc nghiệt , tầng dưới chót còn sống xuống , vì sao lại tạo phản ?”\nCái kia Lý Ân Phàm chỉ có thể nói rõ , cho là như vậy người , nếu không phải là còn không có ra xã hội , nếu không phải là một mực tại xã hội tầng dưới chót quay tròn .\nKỳ thực càng hẳn là suy tính , là Tần Luật tại Hán triều vì cái gì không có việc gì ? Mà tại Tần triều , lại làm cho Tần triều nhanh chóng sụp đổ ?\nGiống như là cộng hòa dân chủ các loại tại quốc gia khác không có việc gì .\nTại đầu trọc trong tay lại người người oán trách ?\nCó đôi khi thật không phải là quy định luật pháp vấn đề , là người vấn đề , là thi hành người vấn đề .\n“ Ngươi nói không sai .”\nTần Thuỷ Hoàng Doanh Chính trầm tư rất lâu mới rốt cục gật đầu một cái nói ra một câu nói như vậy .\nMông Điềm lúc này nhìn một chút Doanh Chính , không hề nói gì , an tĩnh chờ ở một bên .\n...\nĐường triều .\nTrinh Quán bảy năm .\n“ Tầng tầng tăng giá cả ?”\nLý Thế Dân nghiêm túc suy tư một phen bốn chữ này .\n“ Nói không sai , lao dịch có lẽ không có vấn đề gì , nhưng sợ nhất chính là như vậy tầng tầng tăng giá cả .”\n“ Luật pháp quy định , giao tiền thì có thể làm cho ngươi không cần lao dịch .”\n“ Luật pháp bên trên có lẽ sẽ chỉ làm ngươi giao một tiền .”\n“ Nhưng đến phía dưới cùng nhất , chính là nhường ngươi giao mười tiền !”\n“ Tầng dưới chót bách tính , không biết chữ , phía trên nói bao nhiêu , vậy cũng chỉ có thể giao bao nhiêu .”\n“ Luật pháp , lại có mấy người hiểu ?”\n“ Nếu như không phải cùng luật pháp tương quan quan viên , chỉ sợ cũng không biết cụ thể luật pháp chi tiết .”\nLý Thế Dân thở dài một hơi , không biết nên nói gì .\nChuyện như vậy , tại Tùy mạt thời kì , hắn thấy được nhiều lắm .\nHơn nữa chính mình cái kia di tổ phụ , thủ đoạn ác hơn , chính mình dẫn đầu ngồi nhìn , coi thường một ít chuyện phát sinh .\nThậm chí còn cổ vũ ...\nLý Thế Dân mặc dù đen Dương Quảng , nhưng không thể không nói , chờ hắn ngồi xuống vị trí này , mới phát hiện chính mình cái kia di tổ phụ , đối với Tùy triều thương tổn tới thực chất lớn đến mức nào .\nNếu như không phải mình cái kia di tổ phụ một chút thủ đoạn , Dương Quảng có lẽ thật đúng là có thể chống đỡ lâu một chút .\n“ Tùy Chi Phú ? Ngắn ngủi hơn ba mươi năm ở giữa liền tích lũy tài sản kết sù ?”\nLý Ân Phàm lúc này nghĩ đến có ít người tán thưởng Tùy Chi giàu , liền không nhịn được muốn cười .\n...\nHiện đại thời không .\n“ Tùy triều kỳ thực cũng cùng Tần triều là không sai biệt lắm .”\n“ Đều là đối với tầng dưới chót tổn thương quá lớn , cho nên rất đơn giản , tầng dưới chót sống không nổi nữa , cái kia chỉ có một lần nữa tìm một con đường , tới để cho chính mình sống sót .”\nLý Ân Phàm vừa ăn cơm , bên cạnh đối với Tần Thuỷ Hoàng Doanh Chính cùng Mông Điềm hai người nói .\nDoanh Chính cùng Mông Điềm hai người khẽ gật đầu .\nNhanh chóng ăn cơm , Lý Ân Phàm cầm chén đặt lên bàn sau đó , mới dùng tiếp tục nói :\n“ Kỳ thực ta rất ưa thích một cái tỷ dụ , là ta trước đó tại một nơi nào đó nhìn thấy .”\nLý Ân Phàm nói một chút , lại lần nữa đựng một điểm cơm tại trong bát của mình .\n“ Nếu như một cái nhà ba người , bọn hắn một năm sáng tạo tài phú , chính là cái này một bát cơm .”\nLý Ân Phàm chỉ chỉ vừa rồi thịnh tại chính mình trong chén cơm .\n“ Cái này một bát cơm , vừa vặn có thể làm cho chính mình nhà ba người ăn no , hơn nữa còn có thể lưu lại một chút lương thực dư , năm sau nếu có tai hại , liền có thể dùng để vượt qua nan quan .”\n“ Nhưng cái này một bát lương thực , bên trong tất cả đều là chính mình sao ?”\n“ Dĩ nhiên không phải , triều đình sẽ thu một chút thuế .”\n“ Dẹp xong thuế sau đó , còn lại , mới là chính mình .”\n“ Nhưng nếu như gặp phải một cái tốt hoàng đế , có thể hay không thiếu thu một chút ? Sẽ không !”\nCó thể có nhân tâm nghĩ , gặp phải một vị hoàng đế tốt , làm sao còn không thể khá hơn một chút ?\nĐây thật ra là sai lầm !\n“ Đối với tầng dưới chót tới nói , ngươi nhất thiết phải gặp phải một cái quan tốt , mới có thể thiếu thu một chút thuế !”\nRất nhiều người nhìn TV hay là tiểu thuyết , ngây thơ cho là gặp phải một cái tốt hoàng đế , liền có thể để cho tầng dưới chót bách tính qua hảo .\nĐây thật ra là sai lầm , đối với bách tính tới nói , ngươi chỉ có gặp phải một cái quan tốt , mới có thể nghiêm khắc dựa theo hoàng đế tốt tiêu chuẩn , đi thiếu thu thuế !\nMà ở trong đó lôgic , Doanh Chính cùng Mông Điềm hai người đều có thể lý giải .\n“ Nhưng nếu như gặp phải ngu ngốc hoàng đế đâu ? Vậy thì qua càng thêm thê thảm .”\n“ Dù là ngươi gặp phải quan tốt , cũng không thiếu được nhiều nộp thuế .”\nLý Ân Phàm nói đến đây , chỉ vào bát nói :\n“ Cho nên , dân chúng có thể làm sao ?”\n“ Thổ địa sản xuất là cố định , vì ăn cơm no , vậy cũng chỉ có vất vả cần cù trồng trọt .”\n“ Nhưng cái này thời điểm , triều đình lao dịch tới , nhường ngươi giao số ít tiền tài , liền có thể miễn đi lao dịch .”\n“ Nhưng lúc này , vẫn là cùng chúng ta mới vừa nói thuế một dạng , ngươi chỉ có gặp phải một cái quan tốt , mới có thể giao số ít tiền tài , miễn đi lao dịch .”\nLý Ân Phàm một lần nữa ở bên cạnh cầm một cái bát , đem chính mình trong chén cơm , đổ một điểm té ở một lần nữa cầm trong chén .\n“ Cái này chính là thuế .”\n“ Mà cái này , chính là lao dịch .”\nLý Ân Phàm nói , lại ngược một điểm , té ở trong chén .\n“ Đây là tình huống lý tưởng nhất ! Ngươi gặp một vị hoàng đế tốt , tiếp đó , lại gặp một cái quan tốt !”\n“ Vậy ngươi trong chén , vừa vặn còn lại nhà ba người khẩu phần lương thực vượt qua một năm .”\n“ Nhưng nếu như nhất định phải đi một người lao dịch đâu ?”\nLý Ân Phàm lại cầm một cái bát , đem cơm trong đó 1⁄3 đổ ra ngoài .\n“ Hai người trồng trọt , chuyện đương nhiên , sản lượng nhất định sẽ giảm xuống !”\n“ Mà cái này , kỳ thực là lý tưởng nhất nhà ba người .”\n“ Kỳ thực , tại cổ đại , tuyệt đại đa số , cũng là bảy, tám chín khẩu nhà .”\n“ Bọn hắn ăn nhà ba người mới có thể ăn no cơm , tới để cho bảy người , hoặc chín miệng ăn sống sót .”\n“ Đi một hai người lao dịch , có lẽ không có cái gì .”\n“ Nhưng ta vừa rồi cũng đã nói , đây là tình huống lý tưởng nhất , ngươi gặp một vị hoàng đế tốt , lại gặp một cái quan tốt , mới có thể tiếp tục như vậy .”\n“ Nhưng , thường thường tình huống lại là , khẩu phần lương thực bị càng nhiều lấy đi , người , lại chỉ đi một người .”\nLý Ân Phàm đem chính mình trong chén cơm , đổ càng nhiều tại thuế suất cái kia trong chén , cũng đổ càng nhiều tại lao dịch cái kia trong chén .\n“ Quan tốt có bao nhiêu ? Hoàng đế tốt lại có bao nhiêu ?”\nLý Ân Phàm cho Thủy Hoàng cùng Mông Điềm hai người , phô bày chính mình trong chén còn sót lại một chút cơm .\n“ Mà những thứ này khẩu phần lương thực , muốn để bảy, tám chín miệng ăn , sống qua một năm ?!”\nCổ đại lao dịch tổn thương , lớn liền lớn ở đây !\nThuế suất có đôi khi là cố định , nhưng miễn đi lao dịch phải giao bao nhiêu ? Quan viên định đoạt !\nĐó là ngoài ra chi tiêu !\nCòn đối với tầng dưới chót bách tính tới nói , ngoài ra chi tiêu , vậy thì đại biểu cho sự không chắc chắn .\nNhưng thổ địa sản xuất lương thực , lại là cố định !!!\n“ Có thể các ngươi còn cảm thấy không có gì , nhưng cái này một bát cơm , là khắp thiên hạ tất cả mọi người ăn khẩu phần lương thực đâu ?”\n“ Thuộc về tầng dưới chót chỉ còn dư bao nhiêu ?”\nLý Ân Phàm gõ gõ trong chén còn sót lại một chút khẩu phần lương thực .\nDoanh Chính nhíu chặt lấy lông mày , nhìn xem Lý Ân Phàm bát .\nMà Mông Điềm , nhưng là hoảng sợ quay đầu nhìn về phía Doanh Chính .\nMông Điềm nghe hiểu , cũng chính bởi vì nghe hiểu , hắn lúc này mới phát hiện , lúc này Tần triều lao dịch , đối với tầng dưới chót tổn thương lớn bao nhiêu .\n“ Hơn nữa , Tần triều luật pháp chính xác quy định có thể giao tiền tài tới miễn đi lao dịch .”\n“ Nhưng luật pháp , cuối cùng chỉ là tình huống lý tưởng nhất .”\n“ Nhất thiết phải nhường ngươi giao tiền tài tới miễn đi lao dịch , có thể hay không phát sinh ?”\n“ Không để ngươi giao tiền tài , phải đi lao dịch tình huống có thể hay không phát sinh ?”\n“ Hoàng đế quy định , nhất thiết phải 30 vạn người đi một chỗ phục lao dịch .”\n“ Vậy làm sao đi phân phối cái này 30 vạn người ? Là mỗi huyện cố định bao nhiêu người ? Vẫn là nhiều người huyện ra nhiều người ? Ít người huyện ra ít người ?”\n“ Nếu như giao tiền tài nhiều người , để cho tự mình tới miễn đi lao dịch .”\n“ Vậy cái này lao dịch , lại gánh chịu ở ai trên thân ?”\n“ Huống hồ , vốn là không có tiền tài , còn để cho một nhà miệng bên trong nam nhân đi lao dịch ?”\n“ Để cho bản thân liền không nộp ra tiền tài một gia đình , ra một cái trụ cột , đi phục lao dịch ?”\nLý Ân Phàm nói đến đây , nhẹ nhàng lắc đầu , nhìn xem hai người tiếp tục nói :\n“ Hơn nữa , lao dịch phần lớn thời gian , còn nhất thiết phải kèm theo khẩu phần lương thực , kèm theo quần áo .”\nTại Tần triều thời kì , thú binh cần tự chuẩn bị áo cơm , Vân Mộng Tần giản trung sĩ binh gia sách nhiều lần thúc giục người nhà gửi tiền , gửi lương\nHán đại phục dịch giả “ Từ tất mà bổ , ở giữa đạo áo tệ ”.\nTừ Tần Hán đến Tùy Đường , đại quy mô lao dịch ( Như xây Trường Thành , khai vận sông , xây lăng mộ ) bình thường từ bách tính không ràng buộc gánh chịu , không chỉ có không thù lao , còn thường cần Kèm theo lương thực , công cụ thậm chí quần áo .\n“ Cho nên kỳ thực rất đơn giản , mỗi một lần lao dịch , thì tương đương với ...”\nLý Ân Phàm đem chính mình trong chén cơm , lại ngược một điểm đến vừa rồi đại biểu lao dịch trong chén .\n“ Mỗi một lần lao dịch kỳ thực cũng đều là đối với tầng dưới chót một loại tổn thương .”\n“ Hậu thế , Hán triều cùng với Đường , Tống , minh đều đã chứng minh lao dịch có lẽ không có gì , chỉ cần chắc chắn hảo trong đó độ , liền sẽ không để vương triều sụp đổ .”\n“ Nhưng , đã trải qua nhiều năm chiến loạn , lại một mực tại phục lao dịch , ngoại trừ lao dịch , còn có nghĩa vụ quân sự .”\n“ Tần triều thiết lập sau đó , tất cả những điều này , vậy mà đều vẫn không thay đổi ?”\nNgươi không thay đổi ? Vậy cũng chỉ có chúng ta thay đổi !!!\nMột câu nói kia , Lý Ân Phàm cũng không nói ra miệng .\n......', 'output\\mp3\\Màn Trời Quyền Lực Diễn Biến Cùng Truyền Thừa\\0011_Thứ 11 chương Người vấn đề.mp3', '2026-09-01T11:20:39.555284+00:00', 'completed', 'completed', 13319, 13319),
	(17, 7, '7641509368726307352', 12, 'Thứ 12 chương Công bằng sao?', 'Thứ chương Công bằng sao ?\nĐường triều .\nTrinh Quán bảy năm .\n“ Nước có thể nâng thuyền cũng có thể lật thuyền ...”\nLý Thế Dân tại sao lại coi trọng như thế một câu nói kia ? Bởi vì hắn biết , Tùy triều đến tột cùng là như thế nào sụp đổ !\nTuy là thế gia đại tộc xuất thân , nhưng Lý Thế Dân không bao lâu liền tòng quân , thấy tận mắt , chính tai nghe được , rất rất nhiều .\n“ Tần triều cùng Tùy triều giống nhau như vậy ...”\n“ Xem ra , có nhiều thứ đúng là một dạng , không có gì khác biệt ...”\nLý Thế Dân giơ tay lên bên trong sách sử lật qua lật lại , sau đó lại đem nó đặt ở chính mình bên cạnh .\n...\nTùy triều .\nMở hoàng mười lăm năm .\nGiờ khắc này , nhân thọ cung nội yên tĩnh vô cùng , tất cả hoạn quan cùng cung nữ đều bị hù nằm rạp trên mặt đất , đầu cũng không dám giơ lên .\n“ Tùy triều , cùng Tần triều không có gì khác biệt ?”\nDương Kiên mặt như phủ băng nhìn xem trong tay sách sử , sau đó tức giận quăng ra .\n“ Không có gì khác biệt ?!”\n“ Cũng là Đoản Mệnh Vương Triều ?!!”\n“ Ha ha ha ...”\n...\nHiện đại thời không .\nLý Ân Phàm đem mấy cái trong chén cơm ăn hết tất cả , thoải mái uống một hớp nước trà .\n“ Kỳ thực muốn để ta cho Tần triều một cái đề nghị .”\nDoanh Chính cùng Mông Điềm hai người nhìn xem Lý Ân Phàm , chờ đợi hắn lời kế tiếp .\n“ Đó chính là chậm xuống tới ...”\nCó thể trực tiếp dừng lại sao ? Đương nhiên không được !\nHọc qua khoa học hiện đại đều biết , vận động dữ dội sau đó , có thể hay không lập tức dừng lại ?\nĐương nhiên không được !\nLập tức dừng lại , là có xác suất sẽ tạo thành tim đột nhiên ngừng .\nMột cái vương triều đâu ? Cũng giống như thế .\n“ Vì cái gì ta không nói lập tức dừng lại ? Mà là chậm xuống tới ?”\n“ Bởi vì ta chính xác không có cách nào phủ nhận , đại đa số tầng dưới chót , có thể nghĩ là sống những ngày hạnh phúc , đây hết thảy có thể dừng lại .”\n“ Nhưng còn sẽ có người không muốn !”\n“ Tần triều quân công tước chế , liền đã quyết định rất nhiều thứ .”\nLý Ân Phàm nói đến đây , nhìn xem Mông Điềm , nhẹ nói :\n“ Ta vì cái gì không thể biến thành giống Mông tướng quân dạng này ?”\n“ Mông Điềm tướng quân có thể , ta vì cái gì không được ?”\nNói đến đây , Lý Ân Phàm một lần nữa đem 3 cái chén trà chồng lên nhau , chỉ chỉ ở giữa cái kia chén trà nhẹ nói :\n“ Đây chính là rất nhiều ở giữa cái này chén trà nghĩ .”\n“ Bọn hắn không có sinh tồn sầu lo , cho nên muốn nếu không phải là vơ vét tầng dưới chót , nếu không phải là trèo lên trên .”\nNói xong câu đó , Lý Ân Phàm sử một điểm kình , lung lay 3 cái chén trà , chậm rãi nói :\n“ Ngay lúc đó Tần triều , cho ta cảm giác , ngay tại lúc này dạng này lay động chén trà .”\n“ Tầng dưới chót lưu động , trung tầng cũng đồng dạng xốc nổi , cao tầng có lẽ bị bất đắc dĩ , nhưng theo trung tầng cùng tầng dưới chót lay động .”\n“ Chính mình cũng không thể không động .”\n“ Hơn nữa , cao tầng cứ như vậy đơn thuần , không muốn đến leo lên ?”\nLý Ân Phàm dừng lại lay động chén trà , nhìn xem Thủy Hoàng Doanh Chính cùng Mông Điềm hai người , nói nghiêm túc :\n“ Các ngươi có lẽ đứng đã quá cao , không có cái gì ý tưởng dư thừa .”\n“ Nhưng có thời điểm , thật muốn đứng tại tầng dưới chót còn có trung tầng đi suy tính một chút ...”\nCái này cũng là Lý Ân Phàm một mực ưa thích , hơn nữa đề xướng .\nChính là thay vào đối phương lập trường , đi suy xét vấn đề .\nVì cái gì hiện đại rất nhiều người đứng đầu , nhất định phải từ tầng dưới chót lý lịch rõ ràng từng bước từng bước đi lên ?\nChính là như thế !\n“ Hô ...”\nDoanh Chính bình tĩnh hít sâu một hơi , gật đầu một cái .\nMông Điềm nhíu chặt lông mày , nhìn chằm chằm màu trắng vách tường , nghiêm túc suy tư .\n...\nĐại hán .\nNguyên thú 4 năm .\n“ Thay vào đối phương lập trường đi suy xét sao ?”\n“ Hoặc có lẽ là , thay vào thân phận của đối phương ?”\nLưu Triệt nhíu chặt lông mày , dùng bút , tại trên trước mặt sách lụa nghiêm túc viết xuống những lời này .\nSau lưng Vệ Thanh , cũng đồng dạng nghiêm túc đem những lời này nhớ kỹ trong lòng .\n‘ Chiến tranh , có đôi khi không phải liền là muốn thay vào thân phận của đối phương suy nghĩ sao ?’\n‘ Tình báo càng kỹ càng , thì càng gần sát ...’\nVệ Thanh ở trong lòng nhắc tới , nghiêm túc đem những lời này khắc vào nội tâm của mình .\n...\nMinh triều .\nHồng Vũ mười năm .\nChu Nguyên Chương lúc này nhíu chặt lông mày , trên mặt tựa hồ mang theo trọng trọng tâm sự nhìn xem trên đất gạch .\n“ Phụ thân ?”\nChu Tiêu phát giác phụ thân của mình Chu Nguyên Chương có lẽ xuất hiện vấn đề gì .\n“ Tiêu nhi ...”\nChu Nguyên Chương liếc Chu Tiêu một cái , ngay sau đó tiếp tục nói :\n“ Ta nhưng có thể có chút địa phương sai .”\nÂn ?\nNghe được câu này , Chu Tiêu mắt trợn tròn nhìn xem Chu Nguyên Chương .\nPhụ thân vậy mà thừa nhận mình sai ?\nSau lưng , mấy vị hoàng tử ngươi nhìn một chút ta , ta xem một chút ngươi .\nBọn hắn cũng hoài nghi lỗ tai của mình có phải hay không xuất hiện vấn đề .\nLuôn cố chấp phụ thân , cái này một vị thiết huyết Đế Vương , vậy mà thừa nhận mình sai lầm ?\n“ Ta chính xác sai rất nhiều .”\n“ Bây giờ nghĩ kỹ lại , có chút chính sách chính xác sai thái quá ...”\nChu Nguyên Chương vì cái gì phát giác sai lầm của mình ?\nBởi vì làm hắn học màn trời lời nói , thay vào một chút thân phận đi xem chính mình ban bố chính sách .\nChính mình cũng có chút không nhìn nổi .\n“ Ai ...”\nChu Nguyên Chương thở dài một hơi .\n...\nHiện đại thời không .\nLý Ân Phàm quét mã đưa tiền , cùng Thủy Hoàng Doanh Chính cùng Mông Điềm hai người đi ra tiệm ăn trung quốc .\n“ Thủy Hoàng , ta có một cái vấn đề .”\nLý Ân Phàm lúc này chợt nhớ tới một chuyện , một cái chính mình một mực tại truy tìm đáp án .\nCũng chỉ có nhận được đáp án này , mới có thể vuốt thuận Tần triều thời kỳ quyền hạn kết cấu .\nBên cạnh Doanh Chính cùng Mông Điềm hai người , liếc mắt nhìn Lý Ân Phàm .\n“ Tiên sinh , mời nói .”\n“ Phù Tô , từ nhỏ học tập chính là nho gia , vẫn là pháp gia ?”\nNghe được vấn đề này , Doanh Chính dừng bước lại , nhìn xem Lý Ân Phàm .\nBên cạnh Mông Điềm lúc này trên mặt vô cùng nghi hoặc không hiểu .\n“ Tiên sinh , ngươi vì cái gì cho rằng Phù Tô công tử học tập là nho gia ?”\nMông Điềm nghi hoặc nhìn Lý Ân Phàm nhẹ giọng hỏi .\n“ Các ngươi đều nhìn qua 《 Sử Ký 》 ghi chép , hậu thế rất nhiều người dưới đây phỏng đoán , Phù Tô từ nhỏ bị ngươi bồi dưỡng học tập nho gia .”\nLý Ân Phàm nhìn chằm chằm Doanh Chính ánh mắt , chậm rãi nói .\nDoanh Chính không nói chuyện , bên cạnh Mông Điềm nghe được Lý Ân Phàm trả lời , lắc đầu nói :\n“ Tiên sinh , Phù Tô công tử từ nhỏ đã là học tập pháp gia .”\nDoanh Chính khẽ gật đầu một cái , biểu thị đồng ý Mông Điềm mà nói , sau đó theo sát lấy nói một câu .\n“ Bọn hắn sẽ không cho phép Phù Tô đi học tập nho gia .”\n“ Chỉ có thể là pháp gia , cũng nhất định phải là pháp gia .”\nLý Ân Phàm nghe được cái này , khẽ gật đầu một cái .\nCùng mình đoán không sai .\nHiện đại rất nhiều người đều cho rằng Phù Tô từ nhỏ bị Doanh Chính bồi dưỡng học tập nho gia .\nNhưng ở Lý Ân Phàm xem ra , đây tuyệt không khả năng !\nLiền không nói từ thương ưởng biến pháp sau đó , trong lịch sử rất nhiều Tần Vương , có ai học qua nho gia .\nLiền vẻn vẹn là ngay lúc đó pháp gia hoàn cảnh , chung quanh những người kia , liền tuyệt sẽ không cho phép Phù Tô đi học tập cái gì nho gia .\n“ Nhưng cứ như vậy , Thủy Hoàng , có một số việc , đối với đỡ Tô công tử , công bằng sao ...”\nDoanh Chính dừng bước lại , an tĩnh đứng sửng ở tại chỗ .\nLúc này Doanh Chính biết , hậu thế có ít người đã đoán được hắn vì sao không lập Phù Tô vì Thái tử .\nKhông lập Phù Tô vì minh xác thái tử .\nBên cạnh Mông Điềm có một chút mộng , không biết vì cái gì chủ đề bỗng nhiên chuyển đến ở đây .\nCái gì đối với Phù Tô công tử có công bình hay không ? Nói thế nào đến cái này ?\nMông Điềm hoài nghi chính mình có phải hay không bỏ lỡ cái gì .\nNhưng chính mình cũng không ngây người a .\n...', 'output\\mp3\\Màn Trời Quyền Lực Diễn Biến Cùng Truyền Thừa\\0012_Thứ 12 chương Công bằng sao.mp3', '2026-09-01T11:20:46.221160+00:00', 'completed', 'completed', 7675, 7675),
	(18, 7, '7641510311907820056', 13, 'Thứ 13 chương Vừa vặn chính là quá hoàn mỹ', 'Thứ chương Vừa vặn chính là quá hoàn mỹ\nHiện đại thời không .\nLý Ân Phàm đi đến bên cạnh phố hàng rong , mua mấy bình nước khoáng .\nSau đó đi trở về Doanh Chính cùng Mông Điềm hai người bên cạnh , đem thủy đưa cho hai người .\n“ Các ngươi có chút hoàng đế cách làm , ta quả thật có thể lý giải , cũng biết bên trong đạo lý .”\n“ Nhưng nói thật , ta trải qua hiện đại giáo dục , từ hậu thế nhìn về phía trước , vẫn luôn không đành lòng .”\n“ Cảm thấy đối bọn hắn quá tàn nhẫn .”\nLý Ân Phàm mang theo hai người ngồi vào trên đường trên ghế .\n“ Một cái ngươi , Thủy Hoàng .”\n“ Còn có Hán Vũ Đế Lưu Triệt , Đường Thái Tông Lý Thế Dân , Vĩnh Lạc đế Chu Lệ .”\n“ Cái này coi như nổi danh nhất hoàng đế , không còn nổi danh hoàng đế , thì càng nhiều .”\n“ Các ngươi đối với Thái tử một chút hành vi , nói thật ...”\n“ Còn như vậy tiểu ...”\nLý Ân Phàm đưa tay so đo , không sai biệt lắm liền 1m dáng vẻ .\n“ Ở trong đó , chỉ có Vĩnh Lạc đế Chu Lệ Thái Tử Chu cháy lớn , hơi hảo như vậy một chút .”\nNói đến đây , Lý Ân Phàm duỗi ra ngón tay , từng cái từng cái đếm một chút .\n“ Tần Thuỷ Hoàng Thái tử Phù Tô , Hán Vũ Đế Thái tử Lưu Cư , Đường Thái Tông Thái tử Lý Thừa Càn , minh Thái tổ Chu Nguyên Chương Thái Tử Chu tiêu , Vĩnh Lạc đế Thái Tử Chu cháy lớn .”\n“ A , đúng , còn có Tống thái tổ nhi tử Triệu Đức Chiêu cùng Triệu Đức Phương ...”\n“ Các ngươi những hoàng đế này , thật là góp không ra một cái hoàn chỉnh Thái tử .”\n“ Ngoại trừ Chu Cao Sí làm mười tháng hoàng đế , những người khác , không có một cái làm hoàng đế , đều tại làm Thái tử thời điểm chết .”\nNói đến đây , Lý Ân Phàm khẽ thở dài một hơi , nhìn xem Doanh Chính nói :\n“ Các ngươi thật sự đem Thái tử trở thành một cái công cụ ...”\n“ Giống như là một cái nguyền rủa .”\n“ Phù Tô cuối cùng , là bị ngươi bức tử .”\n“ Hán Vũ Đế Lưu Triệt Thái tử Lưu Cư , đồng dạng cũng là bị Lưu Triệt bức tử .”\n“ Đường Thái Tông Lý Thế Dân Thái tử Lý Thừa Càn , y nguyên vẫn là bị Lý Thế Dân bức tử .”\n“ Trong này , liền Chu Nguyên Chương Thái Tử Chu tiêu hảo một chút như vậy , không có bị làm thành công cụ , nhưng tại ta xem tới , liền lấy bây giờ tư liệu lịch sử ghi chép , Chu Tiêu bị cha mình Chu Nguyên Chương bức tử xác suất càng thêm lớn .”\nLiên quan tới Thái Tử Chu ngọn vấn đề , Lý Ân Phàm trước đó cũng cho rằng là chết bởi ngoài ý muốn .\nNhưng về sau , đổi một góc độ đi suy xét , hắn mới phát hiện vấn đề chỗ .\nChu Tiêu khả năng rất lớn , là bị Chu Nguyên Chương một thân phận khác , bức tử .\n“ Chu Cao Sí may mắn , tình huống lúc đó đã chú định hắn nhất định phải là Thái tử .”\n“ Vì thế hắn cũng nhận thức được điểm này , mới không có bị phụ thân của mình Chu Lệ đùa chơi chết .”\n...\nHán triều .\nNguyên thú 4 năm .\nGiờ khắc này , trong Vị Ương Cung , tất cả mọi người đều câm như hến đứng tại chỗ , đầu cũng không dám giơ lên .\nVệ Thanh thật chặt đem đầu chôn ở lồng ngực của mình .\nChỉ có Lưu Triệt , nhíu chặt lông mày nhìn xem màn trời , không biết suy nghĩ cái gì .\n“ Thái tử , cuối cùng không có thượng vị hoàng đế ?”\nLúc này Lưu Triệt nội tâm nghi hoặc lớn hơn phẫn nộ .\nHắn nghi hoặc ở phía sau tới mình rốt cuộc làm cái gì , mới có thể bức tử Lưu Cư ?\nLúc đó đến cùng xảy ra chuyện gì , chính mình lại biến thành như thế ?\nLưu Triệt nhíu chặt lông mày nhìn xem màn trời , hắn lúc này vô cùng hy vọng trên thiên mạc liên quan tới Doanh Chính bên trong kết thúc , tiếp đó rút đến Hán triều hoàng đế .\n...\nĐường triều .\nTrinh Quán bảy năm .\nLý Thế Dân mờ mịt nhìn xem màn trời .\n“ Thừa Càn , là bị ta bức tử ?”\nLý Thế Dân lẩm bẩm niệm một câu như vậy .\nPhía dưới rất nhiều thần tử cúi đầu , không dám nói lời nào .\nCho dù là Ngụy Chinh , lúc này cũng không dám nói nhiều một câu , an tĩnh ngồi ở tại chỗ .\nTrình Tri Tiết cũng giống như thế , dùng sức hướng về Uất Trì Kính Đức sau lưng góp , cố gắng để cho chính mình ẩn thân .\nLúc này đám đại thần , thật sự sợ Lý Thế Dân để cho bọn hắn đột nhiên nói hai câu .\nCòn tốt , Lý Thế Dân không có ý nghĩ này .\n“ Bệ hạ ...”\nTrưởng Tôn hoàng hậu bỗng nhiên từ bên cạnh xuất hiện .\n“ Quan Âm tỳ ...”\nLý Thế Dân máy móc quay đầu nhìn bỗng nhiên xuất hiện Trưởng Tôn hoàng hậu .\n...\nTống triều .\nMở bảo sáu năm .\nTriệu Khuông Dận nghe được trên thiên mạc truyền đến âm thanh , trực tiếp một mộng .\n“ Cái gì gọi là chúng ta những hoàng đế này góp không ra một cái hoàn chỉnh Thái tử ?”\nBỗng nhiên , Triệu Khuông Dận nghĩ tới điều gì , vụt một chút đứng lên .\n“ Lại là trước đây loại tình huống kia ?”\nNgũ Đại Thập Quốc chuyện như vậy kinh nghiệm nhiều lắm .\nCó thể nói trên cơ bản chỉ có cực ít Thái tử có thể hoàn chỉnh kế thừa hoàng vị .\nSố nhiều tình huống là gì tình huống ?\nTriệu Khuông Dận chính mình đoạt quyền cái chủng loại kia tình huống !\n...\nMinh triều .\nHồng Vũ mười năm .\nChu Nguyên Chương cùng Chu Tiêu sau lưng mấy vị hoàng tử kinh hãi nhìn cha mình Chu Nguyên Chương bóng lưng .\nBọn hắn nghe được cái gì ?\nPhụ thân của mình , bức tử đại ca của mình ?!\nLúc này Chu Nguyên Chương nhíu chặt lông mày , trong miệng nhắc tới :\n“ Làm sao lại ? Làm sao lại ? Làm sao lại ?!!”\nBên cạnh Chu Tiêu mờ mịt liếc mắt nhìn bên cạnh mình phụ thân .\nTừ nghe được tin tức này bắt đầu , Chu Tiêu não hải lại đột nhiên một chút lâm vào trống không .\nChính mình làm sao sẽ bị phụ thân bức tử ?!\nBây giờ không cũng còn tốt tốt sao ?\nTại sao sẽ như vậy ?\n“ Chu Trùng Bát !”\nMã hoàng hậu bỗng nhiên xuất hiện đang lúc mọi người trước mặt , thần sắc bình tĩnh nhìn xem Chu Nguyên Chương .\n“ Muội tử ...”\nNhìn thấy Mã hoàng hậu xuất hiện , Chu Nguyên Chương theo bản năng hô một tiếng .\n“ Chu Trùng Bát ...”\nMã hoàng hậu từng bước từng bước hướng đi Chu Nguyên Chương , nhìn hắn con mắt .\n“ Muội tử , muội tử ...”\nChu Nguyên Chương nhìn xem Mã hoàng hậu bình tĩnh gương mặt , bỗng nhiên nội tâm lập tức cực lớn ủy khuất dâng lên .\nMuội tử cũng không tin mình ?\n“ Ai ...”\nMã hoàng hậu đi đến Chu Nguyên Chương trước mặt , nhìn xem hắn , bỗng nhiên thở dài một hơi .\nNàng kỳ thực đã biết , vì cái gì màn trời biết nói Chu Tiêu sẽ bị Chu Nguyên Chương bức tử .\nTừ màn trời nói , Chu Tiêu không có giống trong lịch sử những hoàng đế kia , bị xem như một cái công cụ .\nMã hoàng hậu liền biết .\nBởi vì có một số việc , xuất thân gia tộc quyền thế đại gia nàng , kỳ thực đã thấy qua rất nhiều .\n“ Màn trời nói , ngươi không đem tiêu nhi xem như một cái công cụ , kỳ thực ta liền đã đoán được về sau vì cái gì tiêu nhi sẽ bị ngươi bức tử .”\n“ Cái này cũng không trách ngươi , trọng tám , nhưng cũng nhất thiết phải trách ngươi .”\nMã hoàng hậu nhẹ nhàng vuốt ve một chút Chu Nguyên Chương gương mặt .\nMã hoàng hậu hối hận gả cho Chu Nguyên Chương sao ? Không hối hận .\nCho dù là bây giờ , biết Chu Tiêu là bị Chu Nguyên Chương bắt buộc chết , nàng kỳ thực cũng không hối hận .\nKỳ thực lúc này , Mã hoàng hậu nội tâm vẫn có một ít vui mừng .\nBởi vì Chu Nguyên Chương cuối cùng vẫn là không có đem Chu Tiêu xem như một cái chính trị công cụ , tới cân bằng triều chính thế lực .\nNày liền đã so trong lịch sử tuyệt đại đa số hoàng đế đều phải thật tốt hơn nhiều .\nTừ nơi này đi xem .\nChu Nguyên Chương kỳ thực đã hoàn mỹ thực hiện một cái trượng phu , một người cha thân phận .\nCó thể ...\nVừa vặn chính là quá hoàn mỹ ...\n......', 'output\\mp3\\Màn Trời Quyền Lực Diễn Biến Cùng Truyền Thừa\\0013_Thứ 13 chương Vừa vặn chính là quá hoàn mỹ.mp3', '2026-09-01T11:20:52.889129+00:00', 'completed', 'completed', 7117, 7117),
	(19, 7, '7641511308415730200', 14, 'Thứ 14 chương Thái tử môn', 'Thứ chương Thái tử môn\nMinh triều .\nVĩnh Lạc bảy năm .\n“ Đại ca , là bị phụ thân bức tử ?”\nChu Lệ có chút nghi hoặc nhìn màn trời , hắn rất không minh bạch , vì cái gì màn trời có thể như vậy nói .\nPhụ thân của mình Chu Nguyên Chương đối với đại ca Chu Tiêu được không ?\nPhi thường tốt .\nChu Lệ đọc thuộc lòng lịch sử , liền không có gặp qua trong lịch sử có hoàng đế nào là như thế này đối đãi mình Thái tử .\nCùng là Mã hoàng hậu hài tử , Chu Lệ về sau một tơ một hào ghen tỵ tâm đều sinh không nổi tới .\nCó thể tưởng tượng được Chu Nguyên Chương đối với Chu Tiêu có thật tốt , hoàn toàn để cho Chu Lệ cùng mấy vị khác Mã hoàng hậu hài tử trực tiếp buông tha một ít không thiết thực ý nghĩ .\nChờ đã ...\nChu Lệ bỗng nhiên ngẩng đầu nhìn màn trời .\n“ Được không ?”\nChu Lệ đột nhiên hỏi chính mình một câu như vậy .\n“ Đương nhiên được , quá tốt rồi , dễ đến mức độ khó mà tin nổi .”\nThì thầm một câu như vậy , Chu Lệ bỗng nhiên biết màn trời tại sao lại nói đại ca Chu Tiêu là bị phụ thân bắt buộc chết .\nBởi vì hắn nhớ tới một số việc , một chút mình tại đất phong thời điểm , nghe được việc nhỏ .\n“ Dễ đến , chúng ta ghen ghét cũng không dám ghen ghét ...”\n“ Vậy đại ca sẽ ra sao ?”\nChu Lệ bỗng nhiên lại nói một câu như vậy .\n“ Cái kia ôn hòa đại ca , đọc thuộc lòng lịch sử đại ca , luôn luôn chiếu cố đại ca của chúng ta , hắn sẽ ra sao ?”\n“ Nhìn thấy tình huống như vậy , đại ca sẽ chuyện đương nhiên tiếp nhận sao ?”\nChu Lệ lắc đầu , cho rằng Chu Tiêu sẽ không như vậy .\nGiờ khắc này , Chu Lệ cuối cùng vuốt rõ ràng màn trời lời nói .\n“ Thì ra là thế ...”\n“ Đại ca , đúng là bị phụ thân bức tử ...”\n“ Nhưng , cũng là bị chính mình bức tử ...”\nChu Lệ nghĩ tới đây , lắc đầu , nhẹ giọng thở dài một hơi .\nBên cạnh Chu Cao Sí một mặt mộng nhìn xem Chu Lệ biểu diễn .\nCũng không biết phụ thân của mình đến cùng là thế nào .\nBỗng nhiên ngẩng đầu cúi đầu , tiếp đó lại ngẩng đầu cúi đầu .\n“ Lão đại , ngươi làm cái gì ?”\nChu Lệ nhìn xem bỗng nhiên xuất hiện ở trước mặt mình cái kia mập mạp khuôn mặt , sợ hết hồn .\n“ Không có gì ...”\nChu Cao Sí gặp Chu Lệ hồi thần lại , an vị trở về vị trí của mình .\n“ Không có gì ? Ngươi có phải hay không quên màn trời nói tới , ngươi mới làm mười tháng hoàng đế ?”\nChu Lệ thấy thế , lập tức khí không đánh vừa ra .\n“ Đoán chừng lúc đó tuổi già thôi ...”\nChu Cao Sí lúc này ngược lại là không quan trọng , nhìn xem Chu Lệ nói :\n“ Ngươi nghĩ a , phụ thân , ngươi ngồi hoàng đế ngồi cái ba, bốn mươi năm , cái kia chờ ta ngồi lên , ta đều bao nhiêu tuổi ?”\nChu Lệ ngạc nhiên nhìn xem Chu Cao Sí .\n“ Có thể sống đến lúc kia , còn ngồi mười tháng hoàng đế , ta đã rất thỏa mãn .”\nKỳ thực Chu Cao Sí bây giờ cũng rất thỏa mãn .\nBởi vì tại Chu Lệ ra ngoài đánh giặc thời điểm , hắn cùng hoàng đế khác nhau ở chỗ nào ?\nChỉ là không có hoàng đế cái kia tên .\nNhưng thực quyền , lại là không có chút nào kém !\nTrong lịch sử tất cả Thái tử , có thể nói , không có một cái nào có thể so sánh được với Chu Cao Sí lúc đó làm Thái tử quyền hạn !\nVậy thật là đã thi hành quyền lực của hoàng đế !\nĐương nhiên , trong này chắc chắn là muốn bài trừ Thái tử Lý Thế Dân cùng Thái tử Lý Long Cơ mấy cái kia Thái tử , dù sao mấy cái này cũng không phải đường đường chính chính Thái tử .\nDù sao ngay lúc đó hoàng đế đều không phải đường đường chính chính hoàng đế .\n...\nTần triều .\nThủy Hoàng ba mươi năm .\nChương Đài cung .\nPhù Tô lúc này bình tĩnh nhìn màn trời , nội tâm không biết suy nghĩ cái gì .\nCó một số việc , kỳ thực hắn là biết đến .\nVô cùng rõ ràng bên trong đến cùng là vì cái gì .\nNhưng hắn hay không lý giải , phụ thân của mình Doanh Chính , tại sao muốn làm như vậy ?\nRõ ràng là sai sự tình , vì cái gì y nguyên vẫn là muốn đi làm ?\n“ Công tử ...”\nBên cạnh chờ lấy hoạn quan , có chút lo lắng nhìn xem Phù Tô .\nNhững thứ này đám hoạn quan , bọn hắn không quan tâm màn trời đến cùng nói cái gì .\nDù sao bọn hắn rất nhiều cũng là Từ nhỏ xem lấy Phù Tô lớn lên , vẫn luôn đang chiếu cố Phù Tô .\n“ Vô sự ...”\nPhù Tô lắc đầu , nhìn một chút đặt ở trên bàn thẻ tre , hít sâu một hơi .\nPhía dưới đám đại thần , ngươi nhìn ta , ta nhìn ngươi , đều không nói chuyện .\nDù sao lúc này bệ hạ cũng không ở , nói cái gì ? Vẫn là nói lên đi an ủi một chút công tử Phù Tô ?\nNhư thế nào ? Ngươi là chuẩn bị đi nương nhờ vị kế tiếp hoàng đế ?\nCoi như bọn hắn nghĩ như thế , nhưng màn trời nói lời còn tại não hải đâu .\nCông tử Phù Tô , cũng không có lên làm hoàng đế !\nPhía dưới trong đại thần , chỉ có Mông Nghị lo lắng nhìn xem công tử Phù Tô .\n...\nHiện đại thời không .\nDoanh Chính nghe xong Lý Ân Phàm lời nói , trầm mặc rất lâu .\nChờ hắn mở miệng thời điểm , Lý Ân Phàm đã đem trong tay nước khoáng uống xong .\n“ Tiên sinh , đã ngươi có thể hiểu được nguyên nhân trong đó .”\n“ Vậy thì hẳn phải biết , đây là bọn hắn thân là công tử , vốn là phải làm .”\nLý Ân Phàm nghe nói như thế , trầm mặc gật đầu một cái , qua một hồi lâu , mới thở dài một hơi nói :\n“ Chính xác , đây là bọn hắn thân là công tử , thân là Thái tử , phải làm .”\n“ Dù sao bọn hắn tất nhiên hưởng thụ công tử thân phận , Thái tử thân phận mang đến chỗ tốt , vậy thì trốn không thoát một ít chuyện .”\nLý Ân Phàm kỳ thực không phải đáng thương thân là Thái tử chính bọn họ .\nChỉ là có đôi khi nhìn sách sử thời điểm , thật là thương hại như Thái tử Lý Thừa Càn hài tử như vậy .\nTại trong rất nhiều Thái tử , chỉ có cực thiểu số , như Chu Cao Sí dạng này Thái tử ý thức được .\nRất rất nhiều Thái tử , cũng không có ý thức được , bọn hắn từ nhỏ đã sẽ đối mặt cái gì .\nCho nên , cũng chỉ có như Chu Cao Sí dạng này Thái tử , nhận thức được , hơn nữa an ổn làm tốt một cái chính trị công cụ .\nNhững thứ khác Thái tử môn , có chút là ý thức được , nhưng không cam tâm .\nNhưng càng nhiều , là không có ý thức được , phẫn nộ với mình phụ thân mang đến kiềm chế .\nGiống như là Lý Thừa Càn ...\nCuối cùng từ từ biến thái .\n“ Cái này ...”\nMông Điềm lúc này tựa hồ cũng ý thức được Lý Ân Phàm cùng Doanh Chính đang nói cái gì .\nHồi tưởng dĩ vãng đủ loại , hắn lúc này , bỗng nhiên nghĩ tới bệ hạ vì cái gì không lập công tử Phù Tô vì Thái tử .\n‘ Thì ra , là như thế này sao ?’\nMông Điềm lúc này , nghĩ tới một chút trong đại tộc tình huống .\nBiết bao chi tượng ?\n“ Để cho một đứa bé , một cái tam quan đều không hoàn chỉnh hài tử đi tiếp xúc triều đình , tiếp xúc chính trị ...”\nLý Ân Phàm nói một phen như vậy , lắc đầu , không biết nên nói cái gì .\nCó thể có người sẽ nhớ , Lý Ân Phàm tại sao không đi hỏi , Doanh Chính thật sự nghĩ lập công tử Phù Tô vì đời tiếp theo thái tử sao ?\nCái này kỳ thực tại Lý Ân Phàm xem ra , căn bản không có hỏi tất yếu .\nVấn đề này , trước đó Lý Ân Phàm còn có thể nghĩ , Thủy Hoàng Doanh Chính như vậy sủng ái công tử Hồ Hợi , có thể hay không cuối cùng kỳ thực nghĩ lập chính là Hồ Hợi ?\nNhưng về sau Lý Ân Phàm ra xã hội , thấy được một ít chuyện sau đó , mới phát hiện vấn đề này kỳ thực có một chút ngu xuẩn .\nVì cái gì ?\nBởi vì tại Thủy Hoàng Doanh Chính tất cả trong hài tử , chỉ có công tử Phù Tô là tham chính !\nChỉ vẻn vẹn có một mình hắn , là có thể trên triều đình đối với Thủy Hoàng Doanh Chính đưa ra gián ngôn .\nCái này kỳ thực đã nói rõ vấn đề .\nGiống như là hiện đại , một cái tư nhân công ty , ngươi xem như công ty tổng giám đốc , ngươi muốn đem công ty truyền cho chính mình đại nhi tử .\nNgươi sẽ để cho nhị nhi tử , còn có tam nhi tử đi công ty lịch luyện sao ?\nĐương nhiên sẽ không !\nSẽ chỉ làm chính mình đại nhi tử đi công ty lịch luyện .\nCho nên , đạo lý kỳ thực là rất đơn giản , không có phức tạp như vậy .\nKhi ngươi muốn truyền cho mình cái nào nhi tử , tự nhiên sẽ để cho hắn đi vào lịch luyện , từng bước từng bước nắm giữ quyền lực , kế thừa chính mình hết thảy .\nĐến nỗi những hài tử khác ? Sủng ái là một chuyện , bồi dưỡng người nối nghiệp , chính là một chuyện khác .\n......', 'output\\mp3\\Màn Trời Quyền Lực Diễn Biến Cùng Truyền Thừa\\0014_Thứ 14 chương Thái tử môn.mp3', '2026-09-01T11:20:57.943654+00:00', 'completed', 'completed', 7726, 7726),
	(20, 7, '7641901509273207358', 15, 'Thứ 15 chương Tinh thần thất thường', 'Thứ chương Tinh thần thất thường\nHiện đại thời không .\n“ Kỳ thực trong mắt của ta , cổ đại Phong Kiến Vương Triều , tối hình quái dị chức vị , không nên nhất tồn tại chức vị , là cái nào chức vị ?”\nThủy Hoàng Doanh Chính cùng Mông Điềm hai người an tĩnh nhìn xem Lý Ân Phàm .\n“ Chính là “ Thái tử ” Cái này một cái chức vị .”\n“ Hỗn hợp quá nhiều thuộc tính ...”\nLý Ân Phàm nói đến đây , dừng lại , xấp xếp lời nói một chút , mới dùng tiếp tục nói :\n“ Phụ thân hài tử , vương triều người thừa kế ...”\n“ Đây là đứng mũi chịu sào làm Thái tử người , nhất thiết phải đối mặt .”\n“ Mà như thế nào cân bằng giữa hai cái này quan hệ , lại là Thái tử nhất định gặp phải .”\nLý Ân Phàm nói đến đây , liếc mắt nhìn Thủy Hoàng Doanh Chính , lại nói :\n“ Nhưng , làm như thế nào cân bằng giữa hai cái này quan hệ , là Thái tử quyết định sao ?”\n“ Không phải .”\n“ Là phụ thân , là hoàng đế quyết định !”\nDoanh Chính nghe được cái này , hơi nhíu một chút lông mày , hắn nghe hiểu Lý Ân Phàm lời nói .\nBiết Lý Ân Phàm vì sao lại nói , trong này không phải Thái tử bản thân mình quyết định , ngược lại cần hoàng đế tới quyết định .\nLý Ân Phàm gặp Mông Điềm tựa hồ có một chút nghi hoặc không hiểu , suy nghĩ màn trời bây giờ đang tại trực tiếp , các triều đại đổi thay chắc chắn còn có một số hoàng đế cùng bây giờ Mông Điềm giống nhau là nghi ngờ , cho nên giải thích nói :\n“ Dùng lời đơn giản để giải thích , hoàng đế tâm tình tốt thời điểm , hắn sẽ dùng phụ thân thân phận tới đối mặt Thái tử .”\n“ Lúc này , Thái tử cần lộ ra , là Thái tử “ Uy nghiêm ” Sao ?”\n“ Không phải , là nhi tử “ Hiếu thuận ”.”\n“ Hoàng đế tâm tình không tốt thời điểm , hắn liền sẽ dùng hoàng đế cái thân phận này tới đối mặt Thái tử .”\n“ Vậy cái này thời điểm , Thái tử muốn lộ ra , là nhi tử “ Hiếu thuận ” Sao ?”\n“ Không phải , là Thái tử “ Uy nghiêm ”.”\n“ Trong lịch sử , có một cái Thái tử là rất có thể nói rõ vấn đề này .”\n“ Bởi vì hoàng đế quan hệ , mơ hồ thân phận của mình , cuối cùng tinh thần từ từ thất thường , hướng đi biến thái .”\nLý Ân Phàm nói đến đây , thở dài một hơi , nói ra cái tên đó :\n“ Cái này Thái tử , chính là Đường Thái Tông Thái tử , Lý Thừa Càn .”\n“ Hắn cũng không biết làm như thế nào cân bằng “ Thái tử ” Cùng “ Nhi tử ” Giữa hai cái này vị trí .”\n“ Hắn có đôi khi khát vọng , là phụ thân đối với nhi tử mong đợi .”\n“ Nhưng , hắn thường thường gặp phải , ngược lại là hoàng đế đối với Thái tử một cái thân phận này mong đợi .”\n“ Lúc này , hoàng đế cần nhìn thấy chính là Thái tử trưởng thành .”\n“ Ngươi có thể biểu hiện ra nhi tử đối với phụ thân ỷ lại sao ?”\n“ Đương nhiên không được ! Hoàng đế chỉ có thể cảm thấy ngươi không đủ thành thục , chuyện đương nhiên , sẽ trách cứ ngươi .”\n“ Mà vì nhường ngươi trưởng thành , hoàng đế sẽ làm như thế nào ?”\nNgười bình thường lúc này nhất định sẽ nghĩ đến Chu Nguyên Chương .\nCảm thấy lúc này , hoàng đế vì Thái tử trưởng thành , sẽ giống Chu Nguyên Chương đối với Chu Tiêu như thế .\nKỳ thực Chu Nguyên Chương đối với Chu Tiêu thái độ như vậy , là trong lịch sử cực ít .\nĐại đa số tình huống là như thế nào ?\nĐương nhiên là chọn một cái công cụ , để chèn ép Thái tử , để cho Thái tử mau sớm thành thục .\nĐây mới là trong lịch sử số đông hoàng đế làm !\n“ Hoàng đế chuyện đương nhiên , hoặc có lẽ là theo thói quen , sẽ dùng đối với quan viên phương thức , mà đối đãi Thái tử .”\n“ Đối với quan viên là như thế nào ? Cân bằng thế lực của hắn , chọn một người , tới cùng hắn đánh lôi đài .”\n“ Cái này làm sai sao ? Đương nhiên không tệ .”\n“ Bởi vì hoàng đế lúc này cần , là Thái tử trưởng thành , mà không phải nhi tử trưởng thành .”\n“ Cái kia nếu là Thái tử trưởng thành , dùng đúng quan viên phương thức , đương nhiên dễ hiểu .”\n“ Nhưng là giống ta vừa rồi nói .”\n“ Thái tử một cái thân phận này , lại là một đứa con trai , lại là một cái vương triều người thừa kế quan phương công khai một cái thân phận này .”\n“ Thái tử nếu như không thể trước tiên ý thức được hai người này hoàn toàn khác biệt thân phận quan hệ .”\n“ Theo thói quen dùng nhi tử thân phận , tới đối mặt hoàng đế đối với Thái tử mong đợi .”\n“ Vậy thì nhất định sẽ đau đớn không chịu nổi .”\nLý Ân Phàm nói đến đây , ngữ khí dần dần chậm lại , nhìn xem Doanh Chính cùng Mông Điềm hai người .\n“ Nhưng ngươi có thể nói hoàng đế sai sao ?”\n“ Đương nhiên cũng không được , bởi vì đối với hoàng đế tới nói , tất nhiên ta muốn một đứa con trai “ Hiếu thuận ”, vậy ta không có những hài tử khác sao ?”\n“ Ta nghĩ thỏa mãn cha mình một cái thân phận này .”\n“ Ta tìm những hài tử khác không được sao ?”\nCó thể có người nghĩ tới , Tần Thuỷ Hoàng đối với Hồ Hợi , chính là cái này một loại tình huống .\nĐối với Hồ Hợi sủng ái , đơn thuần chính là thỏa mãn cha mình một cái thân phận này ,\n“ Có thể có người sẽ nhớ , vậy tại sao lại muốn nói Thái tử đối với hoàng đế , lại là nhi tử đối với phụ thân ?”\n“ Cho nên ta mới có thể nói , đây hết thảy cũng là hoàng đế quyết định !”\n“ Hoàng đế hứng thú tới , hoặc có lẽ là xúc cảnh sinh tình , đột nhiên nghĩ xem Thái tử cái này một đứa con trai , đối với mình còn có không có thân tình ...”\n“ Đây cũng chính là vì cái gì Thái tử một cái thân phận này , sẽ như vậy dị dạng ...”\nNói đến đây , Lý Ân Phàm lắc đầu , nói tiếp lên Lý Thừa Càn .\n“ Nhưng nói thật , cái này có thể trách Đường Thái Tông Thái tử Lý Thừa Càn sao ?”\n“ Lý Thừa Càn vì cái gì không thể cân bằng hảo quan hệ giữa hai cái ?”\nLý Ân Phàm khoanh tay , nhìn xem phương xa vũ trụ , chậm rãi nói :\n“ Bởi vì Đường Thái Tông Lý Thế Dân , cái này một hoàng đế bản thân liền đã mơ hồ cha mình và hoàng đế thân phận .”\n“ Lý Thế Dân kinh nghiệm , thượng vị hoàng đế kinh nghiệm , để cho hắn cũng không còn cách nào bình thường đối đãi phụ thân , nhi tử , hoàng đế , Thái tử .”\n“ Ta xem chừng , Lý Thế Dân chỉ cần nghĩ đến đây 4 cái từ mấu chốt , đều biết nghĩ đến vậy trước kia phát sinh hết thảy .”\n“ Chỉ sợ Lý Thừa Càn ban đầu là rõ ràng , bình thường đối mặt một người cha đối với nhi tử mong đợi .”\n“ Nhưng ở trong đó xen lẫn hoàng đế đối với Thái tử xem kỹ .”\nLý Ân Phàm nghĩ tới chỗ này thời điểm , có đối với Lý Thừa Càn thương hại , cũng có đối với Lý Thế Dân thương hại .\nCái kia đã từng phát sinh hết thảy , nhất định sẽ thời khắc vờn quanh tại Lý Thế Dân nội tâm .\nKhi hắn muốn dùng phụ thân một cái thân phận này , tới đối mặt nhi tử thời điểm .\nNhất định sẽ không tự chủ liền nghĩ tới chính mình làm con trai , đối với phụ thân Lý Uyên làm hết thảy .\nLại cao hứng tâm tình , nghĩ tới chỗ này , chỉ sợ đều cao hứng không nổi .\nBởi vì cứ như vậy , Lý Thế Dân nhất định sẽ nghĩ , Lý Thừa Càn có thể hay không giống như ta ? Giống ta đối với phụ thân làm như thế , đến đúng ta ?\nLúc này , Lý Thừa Càn biểu hiện càng bình thường , Lý Thế Dân nội tâm cũng liền từ từ vặn vẹo .\nHắn có phải là ngụy trang hay không ? Có phải hay không là vì lừa gạt ta ?\nGiống như ta lúc đó lừa gạt mình phụ thân Lý Uyên ?\nĐiều này cũng làm cho để cho Lý Thừa Càn vô luận như thế nào , đều sẽ lâm vào một vùng đất chết ...\nLúc này , ngươi biểu hiện càng như chính mình phụ thân Lý Thế Dân , vậy thì càng thêm tăng thêm cái này một cái hoài nghi .\nNhưng làm ngươi biểu hiện không giống , như vậy sẽ cảm thấy ngươi là ngụy trang , không loại mình .\nĐường triều sơ kỳ thời điểm , Lý Thế Dân đối với chính mình Thái tử Lý Thừa Càn , tại Lý Ân Phàm xem ra , chính là như vậy một loại vặn vẹo tâm lý .\nLý Thừa Càn tinh thần từ từ thất thường , đến sau cùng biến thái , cũng đã rất bình thường .\nDù sao , Lý Thế Dân tinh thần , kỳ thực cũng đã thất thường .\n......', 'output\\mp3\\Màn Trời Quyền Lực Diễn Biến Cùng Truyền Thừa\\0015_Thứ 15 chương Tinh thần thất thường.mp3', '2026-09-01T11:21:02.849934+00:00', 'completed', 'completed', 7439, 7439),
	(21, 7, '7641902247881736766', 16, 'Thứ 16 chương Trưởng Tôn hoàng hậu', 'Thứ chương Trưởng Tôn hoàng hậu\nĐường triều .\nTrinh Quán bảy năm .\nLúc này bầu không khí yên tĩnh vô cùng , đám đại thần , các cung nữ , quan lại nhóm , đều đem đầu của mình chôn ở ngực .\nTrong mọi người , chỉ có Lý Thế Dân cùng Trưởng Tôn hoàng hậu hai người còn nhìn lên bầu trời .\nLý Thế Dân từ nghe được màn trời nói lên Thái tử Lý Thừa Càn , biểu lộ từ lúc mới bắt đầu nhíu mày , bình tĩnh , đau đớn , bình tĩnh , hờ hững , từ từ biến ảo ...\nTrưởng Tôn hoàng hậu thì không hề nói gì , chỉ là tựa ở Lý Thế Dân bên cạnh .\nNàng cũng đồng dạng hờ hững nhìn xem màn trời .\nTrưởng Tôn hoàng hậu biết Lý Thế Dân từ leo lên hoàng vị sau đó , nội tâm biến hóa sao ?\nLà biết đến !\nBởi vì nàng liền không có ngăn cản qua Lý Thế Dân đối với Ngụy Vương Lý Thái sủng ái , đồng dạng cũng không có nhúng tay qua Lý Thế Dân đối với Lý Thừa Càn làm hết thảy .\nKỳ thực Trưởng Tôn hoàng hậu lúc này nhìn xem màn trời , cảm thấy trên thiên mạc Lý Ân Phàm nói không đúng .\nHắn chỉ nói hoàng đế , Thái tử , phụ thân , nhi tử ...\nKhông để ý đến một loại khác quan hệ .\nMẫu thân , nhi tử , hoàng hậu , Thái tử ...\nTrong hoàng cung , không chỉ là Thái tử cần đối mặt hoàng đế .\nHoàng hậu , cũng đồng dạng là cần đối mặt hoàng đế .\nCó đôi khi , cần cân bằng quan hệ giữa hai người , cũng không chỉ là Thái tử , đồng dạng còn có hoàng hậu .\nHoàng hậu , hoàng đế , thê tử , trượng phu ...\n“ Tất cả giải tán đi ...”\nLý Thế Dân liếc mắt nhìn phía dưới đại thần , hờ hững nói một câu như vậy .\nPhía dưới đám đại thần , nghe được một câu nói kia , giống như đại xá , đều tại nội tâm thở nhẹ thở ra một hơi , sau đó đứng lên , nhanh chóng thối lui ra khỏi ở đây .\n“ Các ngươi cũng đều đi xuống đi .”\nLý Thế Dân liếc mắt nhìn bên cạnh hoạn quan các cung nữ .\nMột câu nói kia vừa ra , hoạn quan các cung nữ nội tâm cuồng hỉ , lập tức theo đám đại thần thối lui ra khỏi ở đây .\n“ Hoàng hậu ...”\nLý Thế Dân an tĩnh rất lâu , mới nhìn hướng mình bên cạnh Trưởng Tôn hoàng hậu .\n“ Bệ hạ ...”\nTrưởng Tôn hoàng hậu cung kính nhìn xem Lý Thế Dân .\n“ Ai ...”\nLý Thế Dân lúc này , cuối cùng phát giác chính mình vấn đề .\nNhìn thấy Trưởng Tôn hoàng hậu cung kính một khắc này , hắn hồi tưởng màn trời lời nói , mới rốt cục phát hiện mình tinh thần có lẽ thật sự xuất hiện một chút thất thường .\n“ Ta cần yên lặng một chút ...”\nLý Thế Dân nhu hòa liếc mắt nhìn Trưởng Tôn hoàng hậu .\n“ Bệ hạ ...”\nTrưởng Tôn hoàng hậu lo lắng liếc mắt nhìn Lý Thế Dân , nhưng vẫn là lui ra ngoài .\nLúc này , Trưởng Tôn hoàng hậu tinh tường , Lý Thế Dân cần chính là thật tốt suy tính một chút .\n...\nLúc này , có thể có người sẽ nhớ , vì cái gì Trưởng Tôn hoàng hậu không nhúng tay vào Lý Thế Dân đối với Lý Thừa Càn làm hết thảy , đối với Ngụy Vương Lý Thái làm hết thảy ?\nNàng chẳng lẽ không nhìn thấy bên trong ẩn núp tai hoạ ngầm sao ?\nCái này nhất định là vô số người , nhìn sách sử thời điểm chỗ toát ra nghi vấn .\nNếu như nói Trưởng Tôn hoàng hậu thật là hiền sau , nàng như thế nào có thể nhìn không ra trong này ẩn giấu nguy hiểm ?\nTại Lý Ân Phàm xem ra , rất nhiều người kỳ thực không để ý đến một chuyện .\nLý Thừa Càn , có phải hay không Trưởng Tôn hoàng hậu hài tử ?\nLý Thái , có phải hay không Trưởng Tôn hoàng hậu hài tử ?\nĐáp án dĩ nhiên là không nghi ngờ chút nào , hai người này , cũng là Trưởng Tôn hoàng hậu Thái tử .\nVậy dạng này vừa tới , nàng tại sao muốn đi ngăn cản ?\nTrợ giúp Lý Thừa Càn , vậy cái này tổn thương là ai ?\nTrợ giúp Lý Thái , tổn thương là ai ?\nLúc này , khẳng định có người sẽ nhớ , ngươi là hoàng hậu , chẳng lẽ còn sợ con của mình , trả thù ngươi hay sao ?\nTrưởng Tôn hoàng hậu đúng là hoàng hậu .\nNhưng nàng , không phải Tống Minh sau đó , không có chút nào căn cơ hoàng hậu !\nTrưởng Tôn hoàng hậu , nàng họ trưởng tôn , sau lưng còn có Trường Tôn gia tộc , dùng nghiêm khắc lời nói , nàng chính là ngoại thích .\nNàng liền đại biểu cho ngay lúc đó Trường Tôn gia tộc .\nTrưởng Tôn Vô Kỵ tại lúc đó , là không đại biểu được Trường Tôn gia tộc !\nNếu như nàng nhúng tay vào đi , mặc kệ là trợ giúp cái nào , đó chính là ngoại thích quan hệ hoàng vị kế thừa .\nDù sao ngươi Trưởng Tôn hoàng hậu xuống đài , cái kia Trưởng Tôn Vô Kỵ có thể không dưới đài sao ?\nĐối với Lý Thế Dân cường thế như vậy hoàng đế tới nói , ngoại thích quan hệ hoàng vị kế thừa là muốn làm cái gì ?\nKhông phải trong miệng ngươi hô hào ta là ngoại thích , ta muốn can thiệp hoàng vị kế thừa , mới là ngoại thích tham gia vào chính sự .\nKhi ngươi xuống đài , trợ giúp một phương nào , đó chính là sự thật phương diện bên trên ngoại thích tham gia vào chính sự .\nMà từ hoàng đế góc độ đi xem , đây không phải ngoại thích tham gia vào chính sự , là cái gì ?\nĐiều này cũng làm cho giải đáp vì cái gì đầu thời nhà Đường thời kì , Lý Thế Dân cùng Trưởng Tôn hoàng hậu dạng này phu thê tình thâm .\nBởi vì Trưởng Tôn hoàng hậu hiểu phân tấc .\nNàng biết , mặc kệ chính mình thay ai nói chuyện , Lý Thừa Càn vẫn là Lý Thái , mặc kệ nàng thay phương nào nói chuyện , cũng là ngoại thích can thiệp hoàng vị kế thừa .\nVậy vì sao Trưởng Tôn hoàng hậu , không thể giống Mã hoàng hậu như thế đâu ?\nGiống như vừa rồi nói , Trưởng Tôn hoàng hậu là có căn cơ hoàng hậu , phía sau nàng là có Trường Tôn gia tộc .\nCho nên , cái này kỳ thực cũng là cổ đại phong kiến thời kì , đại gia tộc xuất thân nữ tử muốn gặp phải đồ vật .\nĐại gia tộc xuất thân nữ tử , hoặc có lẽ là , mặc kệ là nam tử vẫn là nữ tử .\nBọn hắn nghĩ cũng là gia tộc của mình .\nCá nhân vinh nhục , vào lúc đó có rất ít người quan tâm .\nTại Tống triều phía trước , gia tộc cùng cá nhân , giữa hai cái này , lựa chọn ai ? Đương nhiên không hề nghi ngờ .\nCho nên cứ như vậy , Lý Thừa Càn thượng vị , đối với Trường Tôn gia tộc là như thế nào ?\nLý Thái thượng vị , lại đối Trường Tôn gia tộc là như thế nào ?\nNhưng , nếu như mình hạ tràng , trợ giúp Lý Thừa Càn , nhưng cuối cùng là Lý Thái thượng vị , Lý Thái sẽ như thế nào đối với Trường Tôn gia tộc ?\nTrái lại cũng thế , hạ tràng trợ giúp Lý Thái , Lý Thừa Càn cuối cùng sẽ như thế nào đối với Trường Tôn gia tộc ?\nBản thân liền là cả hai cùng có lợi , mặc kệ là Lý Thừa Càn thượng vị , vẫn là Lý Thái thượng vị , xem ở mẫu thân phân thượng , đối với Trường Tôn gia tộc đều biết ưu đãi .\nVậy tại sao phải hạ tràng ?\nCho nên , mặc kệ là công tâm , vẫn là tư tâm , Trưởng Tôn hoàng hậu cũng không có kết quả lý do .\nTừ hậu thế đi xem , Trưởng Tôn hoàng hậu thân là một cái mẫu thân , bỏ mặc Lý Thế Dân dạng này đối với Lý Thừa Càn , quả thật làm cho người không thoải mái , hay là rất kỳ quái .\nNhưng , Trưởng Tôn hoàng hậu thân ở ngay lúc đó Đường triều , lấy nàng góc nhìn đi xem , chính mình làm , đương nhiên không có bất kỳ cái gì vấn đề .\nDù sao Ngụy Tấn Nam Bắc triều thời kì còn có Hán triều thời kì , hoàng hậu hạ tràng trợ giúp Thái tử , lại làm cho một cái khác hoàng tử thượng vị , diệt trừ gia tộc của mình tình huống , là phát sinh qua .\nCho dù là Thái tử thượng vị , diệt trừ trợ giúp Thái tử gia tộc tình huống , cũng không phải không có phát sinh .\nHán triều đều thường xuyên phát sinh !\nCho nên đối với Trưởng Tôn hoàng hậu tới nói ...\nHoàng hậu , hoàng đế , thê tử , trượng phu ...\nCùng với ...\nHoàng hậu , Thái tử , mẫu thân , nhi tử ...\nĐồng dạng cũng là các nàng thường xuyên gặp phải lựa chọn .\nCuối cùng , từ Trưởng Tôn hoàng hậu góc độ đi xem , một cái cường thế vô cùng , tự tay mình giết huynh đệ mình , nhốt cha mình , tuổi xuân đang độ thời kì chỗ leo lên ngôi vị hoàng đế hoàng đế .\nDạng này hoàng đế , để cho chính mình can thiệp ngôi vị hoàng đế kế thừa ?\nThân huynh đệ đều tự tay mình giết , cha ruột đều nhốt .\nThê tử ?!!\nAi biết có thể hay không thứ nào chuyện chạm đến Lý Thế Dân cái này một cường thế hoàng đế vảy ngược ?\nChỗ cho dù là từ cá nhân góc độ đi xem , Lý Thế Dân thân là Trưởng Tôn hoàng hậu trượng phu .\nTrưởng Tôn hoàng hậu làm sao dám can thiệp hoàng vị kế thừa ?\nCho nên , từ xưa đến nay , nào có cái gì đúng sai ? Có vẻn vẹn chỉ là lập trường .\n......', 'output\\mp3\\Màn Trời Quyền Lực Diễn Biến Cùng Truyền Thừa\\0016_Thứ 16 chương Trưởng Tôn hoàng hậu.mp3', '2026-09-01T11:21:08.029043+00:00', 'completed', 'completed', 7870, 7870),
	(22, 7, '7641902478740439614', 17, 'Thứ 17 chương Chu Cao Hú', 'Thứ chương Chu Cao Hú\nHiện đại thời không .\n“ Ai ...”\nThủy Hoàng Doanh Chính lúc này nhìn xem màn trời , phát ra khẽ than thở một tiếng .\nBởi vì đi qua Lý Ân Phàm kiểu nói này , hắn cũng phát hiện chính mình vấn đề .\nCó đôi khi hắn cũng biết mang theo một người cha đối với nhi tử mong đợi , tới yêu cầu Phù Tô trưởng thành .\nCứ như vậy , chính xác vô cùng quái dị .\nPhù Tô có đôi khi cố chấp , hoặc có lẽ là cố chấp , đúng là chính mình chỗ một tay tạo thành .\nMông Điềm trầm mặc đứng tại Thủy Hoàng bên cạnh , cái gì cũng không nói .\nLý Ân Phàm vừa rồi lại đi mua mấy bình nước khoáng .\nNói nhiều như vậy mà nói , quả thật có chút khô miệng khô lưỡi .\n“ Cho nên trong mắt của ta , liền đơn thuần quá giờ tý kỳ một thời kỳ này , lợi hại nhất Thái tử là ai ? Vĩnh Lạc Hoàng Đế Chu Lệ Thái tử , Chu Cao Sí .”\n“ Hắn thật sự đầu não quá rõ ràng , biết mình làm như thế nào đối mặt phụ thân của mình Chu Lệ .”\n“ Lúc nào đối mặt bộ dáng gì Chu Lệ , hắn đều vô cùng tinh tường .”\n“ Hơn nữa , hắn cũng biết biết ngay lúc đó thế cục .”\n“ Tinh tường Chu Lệ vô luận như thế nào cũng sẽ không đổi Thái tử .”\n“ Cho nên dù là Chu Lệ đối với Nhị hoàng tử Chu Cao Hú như thế nào đi nữa , hắn cũng vô cùng rõ ràng Chu Lệ là muốn làm cái gì .”\n“ Thành thành thật thật trợ giúp Chu Lệ tới cân bằng triều đình thế lực ”\nNói đến đây , Lý Ân Phàm đột nhiên nở nụ cười , sau đó lại tiếp tục nói :\n“ Đồng dạng , Chu Lệ cũng vô cùng rõ ràng Chu Cao Sí là dạng gì , đối với Chu Cao Sí vô cùng yên tâm .”\n“ Trong lịch sử liền Thái tử quyền hạn , ngoại trừ mấy cái kia không bình thường Thái tử , không có người so Chu Cao Sí cái này Thái tử quyền hạn còn lớn .”\n...\nMinh triều .\nVĩnh Lạc bảy năm .\nChu Lệ phủi một mắt Chu Cao Sí , lời gì cũng không nói .\nChu Cao Sí đâu ? Gãi gãi đầu của mình , cũng tương tự không nói gì .\n“ Cha !!!”\nLúc này , Chu Cao Hú đột nhiên xuất hiện tại trước mặt hai người , tức giận nhìn xem Chu Lệ .\nThấy vậy tình huống , Chu Cao Sí liếc mắt nhìn Chu Lệ , sau đó đứng lên , lui ra phía sau mấy bước , cố gắng muốn cho chính mình ẩn thân .\n“ Nói đi , lão nhị , thì thế nào ?”\nChu Lệ nằm ở trên ghế , phủi một mắt Chu Cao Hú .\n“ Cha , thật sự như màn trời nói tới , ngươi chưa từng nghĩ qua đổi Thái tử ?!”\nChu Cao Hú lúc này cảm thấy chính mình thật sự vô cùng ngu xuẩn , làm sao sẽ tin tưởng cha mình Chu Lệ nói tới hết thảy ?\n“ Ngươi không phải biết chưa ?”\n“ Vậy ngươi vì cái gì đã từng nói với ta : Thế tử nhiều bệnh , ngươi làm động viên chi ?”\nChu Cao Hú phẫn hận nhìn xem Chu Lệ .\nỞ đây rất nhiều người có thể cho là “ Thế tử nhiều bệnh , ngươi làm động viên chi ”, câu này Chu Lệ đối với Chu Cao Hú lời nói , là hiện đại truyền hình điện ảnh hoặc trong tiểu thuyết xuất hiện .\nKỳ thực một câu nói kia là tại trên Minh triều chính sử xuất hiện qua .\nTrích lời sớm nhất thấy ở 《 Minh sử Chư vương truyền 》 cùng 《 Minh Thái Tông Thực Lục 》 liên quan ghi chép .\nTa bệnh rồi , ngươi cố gắng , thế tử nhiều tật\nThế tử nhiều bệnh , ngươi làm động viên chi\nĐây đều là Chu Lệ đã từng đối với Chu Cao Hú lời nói .\n“ Ai ...”\nChu Lệ lúc này thật cảm thấy vô cùng đau đầu , chính mình đã từng tại sao phải nhiều như vậy đầy miệng .\nĐợi đến chính mình leo lên hoàng vị , mới phát hiện đối với lão nhị vô cùng áy náy .\nBởi vì sau khi hắn leo lên hoàng vị mới phát hiện , vô luận chính mình có nhiều yêu thích lão nhị Chu Cao Hú , chính mình cũng không có khả năng đổi Thái tử , để cho lão nhị Chu Cao Hú đi làm Thái tử .\nDù là , lão đại Chu Cao Sí thật sự tráng niên mất sớm , chính mình cũng không khả năng để cho lão nhị Chu Cao Hú đi làm Thái tử .\nChính mình chỉ có thể học được từ mình phụ thân Chu Nguyên Chương , hắn là thế nào làm , cái kia liền sẽ làm như thế nào .\nTheo lý thuyết , dù là Chu Cao Sí thật sự tráng niên mất sớm , chính mình cũng chỉ sẽ để cho Chu Chiêm Cơ thượng vị , mà không phải lão nhị Chu Cao Hú .\nTại sao sẽ như vậy ?\nBởi vì khai quốc hoàng đế Chu Nguyên Chương là làm như thế , cái kia nhất định phải làm như vậy .\nDạng này mới là chính thống .\nMà không phải để cho chính mình thật sự trở thành “ Tổ ”, trở thành khai quốc hoàng đế .\nĐạo lý chính là đơn giản như vậy , cũng chính là tàn khốc như vậy .\nChu Lệ nhất định phải chứng minh chính mình chính thống , tới để cho Đại Minh bình thường kéo dài tiếp .\n“ Lão nhị ...”\nChu Lệ đứng lên , đi đến Chu Cao Hú trước mặt , bình tĩnh nhìn hắn .\n“ Bởi vì ta không thể để cho Tĩnh Nan xuất hiện lần nữa .”\nChu Lệ vốn định dùng lời vớ vẫn , nói cái gì chính mình lúc ấy nói là thế tử , cũng không phải Thái tử cái gì lừa gạt Chu Cao Hú .\nNhưng khi hắn nhìn thấy Chu Cao Hú cái kia tức giận ẩn tàng cực lớn ủy khuất , vẫn là nói ra chân tướng .\n“ Nếu như ta đổi Thái tử , nhường ngươi leo lên hoàng vị .”\n“ Từ nay về sau , Thái tử một cái thân phận này , liền không còn là cam đoan .”\n“ Chúng ta Đại Minh , cũng sẽ biến thành Đại Đường .”\n“ Ngươi ưa thích đánh trận , rất thích binh thư , hẳn là tinh tường , Đại Đường về sau là dạng gì a ?”\nNhìn xem Chu Cao Hú , Chu Lệ lại dùng giọng bình thản nói :\n“ Khi tình huống như vậy phát sinh , Tĩnh Nan có thể hay không xuất hiện lần nữa ?”\n“ Loạn An Sử sau Đại Đường , có thể hay không biến thành Đại Minh ngày mai ?”\nNghe được cái này , Chu Cao Hú vốn là cảm xúc phẫn nộ , lập tức chậm lại .\nTheo Chu Lệ mà nói , Chu Cao Hú nhớ tới trên sử sách liên quan tới Đại Đường ghi chép , thân thể không khỏi mềm nhũn tiếp .\nChu Cao Hú mặc dù không thích đọc sách , ưa thích đánh trận .\nCó thể quen thuộc trong lịch sử đủ loại chiến dịch hắn , vẫn là vô cùng rõ ràng Đại Đường tại loạn An Sử sau hạ tràng .\nChu Lệ nói có đạo lý sao ?\nChu Cao Hú rất muốn nói không có !\nNhưng hắn nội tâm tinh tường , Đường Thái Tông Lý Thế Dân ra một cái Huyền Vũ môn thay đổi , ảnh hưởng tới về sau Đại Đường .\nLý Thế Dân đối với chính mình người thừa kế thái độ , cũng tương tự ảnh hưởng về sau Đại Đường .\nMà phụ thân của mình , là đi qua Tĩnh Nan lên chức .\nCho nên ...\nChu Cao Hú nghĩ tới đây , liền nghĩ đến phụ thân của mình vì cái gì tuyệt sẽ không thay đổi Thái tử .\nVì để tránh cho Đại Đường tình huống như vậy phát sinh , phụ thân của mình nhất thiết phải kiên định người thừa kế lựa chọn , tới ảnh hưởng đời sau Đại Minh .\n“ Hu hu ...”\nNghĩ tới đây , Chu Cao Hú nội tâm cực lớn ủy khuất lập tức bộc phát , ngồi xổm người xuống , khóc ồ lên .\n“ Lão nhị ...”\nChu Lệ khẽ thở dài một hơi , cũng tương tự ngồi xổm người xuống , trấn an Chu Cao Hú .\n“ Vậy ngươi vì sao muốn gạt ta ?”\nChu Cao Hú ngẩng đầu , lệ rơi đầy mặt nhìn xem Chu Lệ .\n“ Bởi vì lúc đó ta cũng không rõ ràng có thể hay không thành công .”\n“ Hơn nữa , ta cũng không rõ ràng , ngồi trên vị trí này sau đó , đối mặt tình huống .”\nChu Lệ thành khẩn nhìn xem Chu Cao Hú .\nHắn cũng không muốn lại lừa gạt Chu Cao Hú , cho nên dứt khoát tất cả đều nói hết :\n“ Hơn nữa , phía sau ngươi những võ tướng kia , cũng nhất thiết phải có một cái người dẫn đầu .”\n“ Người này , không thể là những cái kia võ tướng , nhất định phải là ngươi , cũng chỉ có thể là ngươi .”\n“ Dù sao ngươi khi xưa kinh nghiệm , để cho những võ tướng kia , đối với ngươi vô cùng tín nhiệm .”\n“ Lão đại là quan văn , ngươi là võ tướng .”\n“ Lần này , ngươi hiểu không ?”\nChu Cao Hú tình nguyện chính mình không có hiểu !\nNhưng hắn , thân là con trai trưởng , cuối cùng vẫn là nghe hiểu .\nCũng chính bởi vì nghe hiểu , Chu Cao Hú lập tức cả người đều hỏng mất .\n...', 'output\\mp3\\Màn Trời Quyền Lực Diễn Biến Cùng Truyền Thừa\\0017_Thứ 17 chương Chu Cao Hú.mp3', '2026-09-01T11:21:51.353121+00:00', 'completed', 'completed', 7298, 7298),
	(23, 7, '7641935739374010904', 18, 'Thứ 18 chương Giáo dục bắt buộc', 'Thứ chương Giáo dục bắt buộc\nHiện đại thời không .\n“ Ôi , chỉ ta nói a , Tần Thuỷ Hoàng Doanh Chính , hắn nên sớm lập Thái tử , tại lên chức thứ trong lúc nhất thời , liền đem Phù Tô lập làm Thái tử , Tần triều liền không khả năng hai thế mà chết !”\nTrong công viên , Thủy Hoàng Doanh Chính cùng Mông Điềm an tĩnh đứng ở một bên , nghe mấy ông lão chuyện phiếm .\nLý Ân Phàm cũng đứng ở một bên nhìn xem bọn hắn .\n“ Không đúng , muốn ta nói , Mông Điềm nếu không chết , Tần triều cũng không nhanh như vậy diệt vong .”\n“ Đặc biệt là những nhà quân sự kia tộc , rất nhiều đều bị Triệu Cao giết .”\n“ Nếu không phải là cuối cùng chỉ còn dư một cái Chương Hàm , Hạng Vũ cùng Lưu Bang có thể đánh tiến Hàm Dương ?”\nMột lão nhân khác phản bác , cho rằng Phù Tô không quan trọng , trọng yếu là những nhà quân sự kia tộc .\nMột cái công tử , có thể thay đổi cái gì ? Cái gì cũng không cải biến được !\n“ Hậu thế , đều như thế ưa thích thảo luận lịch sử sao ?”\nThủy Hoàng Doanh Chính nhìn xem Lý Ân Phàm , nhỏ giọng hỏi .\n“ Dù sao nhàn rỗi nhàm chán đi , nhàn rỗi nhàn rỗi liền thảo luận .”\nLý Ân Phàm cũng không kỳ quái .\nHắn cùng mình bằng hữu liền thường xuyên nói một chút đột nhiên nhảy đến lịch sử kênh .\nTiếp đó , lại nhảy đến quân sự kênh .\nNhảy tới nhảy lui , cuối cùng nói một chút chính là một câu nói : Ta cảm thấy không nên là như thế này ...\nLý Ân Phàm nghĩ tới đây , hội tâm nở nụ cười .\nBên cạnh Mông Điềm mặt không thay đổi chờ đợi tại Doanh Chính bên cạnh , liếc mắt nhìn Thủy Hoàng , lại nhìn vài lần tranh luận lão nhân .\n“ Không phải , ngươi đánh yêu gà a ! Đánh như thế nào bảy đầu ?”\n“ Yêu gà năm đầu , không đánh phải gặp , ngươi không biết được đi ?!”\nDoanh Chính lại đi đến trong công viên mấy bàn chơi mạt chược bên cạnh , tò mò nhìn .\n“ Đây là cái gì ? Tiên sinh .”\nDoanh Chính quay đầu nhìn Lý Ân Phàm , tò mò hỏi một câu .\n“ Mạt chược , xem như một loại phương thức giải trí a .”\n“ Đất Thục , cũng chính là bây giờ chúng ta Tứ Xuyên , vô cùng yêu thích một loại phương thức giải trí .”\n“ Ăn xong cơm trưa , không có việc gì , trên cơ bản liền bắt đầu ngồi trên bàn mạt chược đánh mạt chược .”\nLý Ân Phàm nhẹ giọng tại Doanh Chính bên cạnh nói .\n“ Phương thức giải trí sao ?”\nDoanh Chính nhìn một hồi , phát hiện mình hoàn toàn xem không hiểu , nhưng có thể nhìn ra rất nhiều thứ .\nNhững dân chúng này trên mặt không có cái gì vội vàng xao động hoặc có lẽ là thần tình nóng nảy .\nKhông lo lắng ngày mai nên ăn cái gì .\nCũng không lo nghĩ lương thực có thể hay không vượt qua năm thứ hai .\nTrên mặt cơ hồ cũng là phát ra từ nội tâm nụ cười .\nHơn nữa có thể nhìn ra , cơ hồ tất cả mọi người đều là thích thú .\nCho dù là dọc theo đường , cũng cơ hồ không có người đem đầu chôn ở ngực cẩn thận từng li từng tí , đều là ngẩng đầu ưỡn ngực nhìn về phía trước .\nMặc dù còn có một vài người đi đường lúc , cầm điện thoại di động một mực tại nhìn , không có chú ý mình dưới chân .\nĐúng , điện thoại vật này , cũng là Lý Ân Phàm nói cho Doanh Chính .\nMà cái này một buổi chiều , Doanh Chính chạy rất nhiều nơi .\nCông viên , quán net , quán trà , phòng tập thể thao các loại ...\nMỗi một cái địa phương , hắn đều sẽ ngừng chân mười mấy phút , an tĩnh nhìn xem .\nHỏi nhiều nhất hỏi một chút Lý Ân Phàm , đây là làm cái gì , vì sao lại có nhiều người như vậy .\n...\nHán triều .\nNguyên thú 4 năm .\n“ Đây chính là hai ngàn năm sau hậu thế sao ?”\nLưu Triệt nhìn xem màn trời , càng xem càng trầm mặc .\nHắn biết vì sao Doanh Chính sẽ chạy nhiều địa phương như vậy .\nCũng chính là bởi vì biết , cho nên Lưu Triệt nhìn xem màn trời hình ảnh , mới có thể càng xem càng trầm mặc .\n“ Thực sự là không biết nên như thế nào đi nói a ...”\nLưu Triệt thở dài một hơi , đứng lên , đi đến Vị Ương Cung phía trước bậc thang chỗ , nhìn về phía phương xa .\n“ Ai ...”\n...\nHiện đại thời không .\n“ Tiên sinh , nơi đây lại là địa phương nào ?”\nLúc này thời gian chạy tới buổi chiều năm, sáu điểm .\nDoanh Chính vốn còn muốn nhiều đi một chút , nhưng nhìn lấy người trước mắt lưu , lập tức không biết nên như thế nào đặt chân .\nChung quanh rậm rạp chằng chịt bọn nhỏ , cơ hồ đem bọn hắn đều bao vây .\nBên cạnh Mông Điềm cảnh giác nhìn xem những hài tử này .\nLý Ân Phàm quay đầu liếc mắt nhìn sau lưng tên tiệm .\n“ Đi lên phía trước vừa đi liền tốt , bây giờ là tiểu học bọn nhỏ ra về .”\n“ Những hài tử này đều vây quanh đây , chuẩn bị mua đồ ăn .”\nLý Ân Phàm mang theo Doanh Chính cùng Mông Điềm hai người đi ra một mảng lớn , mới dừng lại cước bộ , quay đầu nhìn lại .\n“ Tan học ?”\nDoanh Chính nghi hoặc nhìn Lý Ân Phàm .\n“ Ân , đúng vậy . Bọn nhỏ đều ra về .”\n“ Bây giờ quốc gia thực hành chính là 9 năm giáo dục bắt buộc .”\n“ Theo lý thuyết , mỗi cái hài tử , đến nhất định niên linh , đều nhất định muốn đi đến trường tiếp thụ giáo dục .”\n“ Thời gian này chính là 9 năm .”\n“ Vì cái gì còn nói là giáo dục bắt buộc đâu ? Đơn giản điểm tới nói , chính là quốc gia quy định , không chấp nhận cái này giáo dục bắt buộc , đó chính là phạm pháp !”\nLý Ân Phàm không có đem 9 năm giáo dục bắt buộc nói quá kỹ càng .\nDù sao muốn thật sự cặn kẽ nói một chút , vậy thật là mấy ngày mấy đêm đều nói không hết .\n“ Dạng này sao ?”\nDoanh Chính nghe phía trước bọn nhỏ ríu rít tiếng ồn ào , cứ như vậy an tĩnh nhìn xem .\nLúc này , Lý Ân Phàm chợt thấy Doanh Chính thần sắc có chút không đúng ?\nLý Ân Phàm hơi suy nghĩ một hồi , Doanh Chính nghĩ đến chính mình hồi nhỏ ?\n“ Tiên sinh , đây là triều đình toàn bộ gánh chịu sao ?”\nDoanh Chính đột nhiên hỏi .\n“ Đúng vậy , 9 năm giáo dục bắt buộc tất cả phí tổn , đều do quốc gia toàn lực gánh chịu .”\n“ Có chút tương đối nghèo khổ địa phương , quốc gia còn có thể bao một trận cơm trưa .”\nDoanh Chính khẽ gật đầu .\n“ Ta cũng là chịu đến dạng này ân huệ .”\n“ Không phải tại tiểu học , là tại sơ trung .”\nLý Ân Phàm nói đến chính mình khi còn bé kinh nghiệm .\n“ Ta học tiểu học thời điểm , quốc gia còn không có toàn diện thực hành giáo dục bắt buộc , thời điểm đó quốc gia cũng nghèo , căn bản bất lực toàn bộ gánh chịu .”\n“ Cho nên , khi đó ta nhớ được ta còn giao qua tiền học phí .”\n“ Nhưng đến lúc sơ trung , liền không có . Học phí rất rất ít .”\n“ Hai mươi khối tiền , vẫn là mười lăm khối tiền tới ?”\nLý Ân Phàm có chút nhớ không rõ ràng , ngược lại hắn liền nhớ kỹ là hai cái này con số .\n“ Trường học lúc đó cũng không có gánh chịu cơm trưa , là bao hết một trận bữa ăn khuya .”\n“ Ta còn nhớ rõ khi đó , ta mong đợi nhất , là xuống tự học buổi tối sau đó , trường học phát ăn .”\n“ Mỗi ngày đều sẽ đoán sẽ phát ăn cái gì .”\n“ Có đôi khi là bánh mì thêm sữa bò , có đôi khi là trứng gà thêm sữa bò .”\n“ Sữa bò là không đổi .”\n“ Những thứ khác đồ ăn đều biết đổi tới đổi lui .”\nNói đến đây , Lý Ân Phàm rất là cảm khái .\nTừng ấy năm tới nay như vậy , hắn có thể rất rõ ràng cảm thấy quốc gia đang từ từ thay đổi xong .\nCho nên Lý Ân Phàm trong nội tâm , kỳ thực là rất cảm kích quốc gia .\nNếu như không phải miễn trừ tất cả phí tổn , hắn đều hoài nghi mình có thể hay không đọc xong sơ trung .\nDù sao hồi nhỏ từ tiểu học bắt đầu , hắn liền ở tại gửi nuôi gia đình , một mực ở tại nhà khác .\nKhi đó nộp học phí , đối với Lý Ân Phàm tới nói , thật là rất khó bước đi một đạo khảm .\nChớ nói chi là ngoại trừ học phí , còn có tiền học phí , cái kia lại là một bút khổng lồ chi tiêu .\nNhưng từ trên sơ trung sau đó , học phí một chút thì thay đổi , trở nên rất rất ít .\nNhiều nhất , dù sao cũng là phí ăn ở .\nMột tháng ba trăm khối tiền , bao trùm , bao ba trận đồ ăn .\nLúc kia , thật là choai choai tiểu tử .\nMột tháng liền vẻn vẹn chỉ giao ba trăm khối tiền , bên trong quốc gia bổ thiếp bao nhiêu liền có thể nghĩ mà biết .\nHơn nữa mặc dù nói là 9 năm giáo dục bắt buộc , nhưng đọc qua việc công cao trung liền chắc chắn biết , kỳ thực giáo dục bắt buộc , rất sớm đã đã phổ cập đến cao trung .\nChỉ là không còn là cưỡng chế tính chất phải đi học trung học .\n“ Tiên sinh , có thể nhìn ra ngươi rất cảm kích triều đình .”\nMông Điềm nhìn xem Lý Ân Phàm , nói nghiêm túc một câu như vậy .\n“ Ta chính xác rất cảm kích .”\nLý Ân Phàm quả quyết thừa nhận xuống , nói tiếp :\n“ Hồi nhỏ không hiểu , trở nên dài lớn quay đầu hồi tưởng kinh nghiệm của mình mới phát hiện , mình rốt cuộc thụ quốc gia bao nhiêu ân huệ .”\n“ Còn có những lão sư kia , ta đồng dạng cũng là cảm kích .”\n“ Mặc dù nói lúc đó chính xác không có học tập cho giỏi , cùng lão sư đối nghịch .”\n“ Nhưng chờ thêm đại học , mới phát hiện trước kia các lão sư , rốt cuộc có bao nhiêu hảo .”\nLý Ân Phàm khoanh tay , đứng tại chỗ , nhìn phía trước bọn nhỏ nói :\n“ Ta ấn tượng sâu nhất , là ta sơ trung một cái lão sư , nàng là chủ nhiệm lớp của ta .”\n“ Nàng là một nữ tử , đọc lúc sơ trung , ta lúc nào cũng cảm thấy nàng rất xấu , không giống như là một cái lão sư , quản cái này quản kia , cái gì đều quản .”\n“ Tiểu học lão sư , cũng không có nàng như vậy sẽ quản .”\n“ Đây là ta đọc lúc sơ trung , đối với cái kia chủ nhiệm lớp sâu nhất ấn tượng .”\n“ Nhưng chờ thêm cao trung , cùng mình đồng học nói chuyện phiếm lúc mới phát hiện , nàng vẫn luôn đang yên lặng trả giá .”\n“ Có mấy chuyện , là bạn học ta nói cho ta , đã nhiều năm như vậy , ta lập tức cũng sắp ba mươi tuổi , nhưng mấy món này chuyện , một mực khắc ở trong đầu của ta .”\nLý Ân Phàm dừng lại một chút , xấp xếp lời nói một chút , mang theo vẻ hồi ức nói :\n“ Chuyện thứ nhất , ta còn nhớ rõ , lúc đó chúng ta tại sơ trung thường xuyên khi dễ một cái nữ đồng học .”\n“ Trong nhà của nàng bởi vì là thu phế phẩm , trên thân vẫn luôn như có như không mang theo một cỗ mùi thối , cho nên chúng ta lúc đó thường xuyên chế giễu nàng .”\nRất nhiều người nhìn thấy cái này , sẽ nhớ , thu phế phẩm ? Đó là ngươi không biết thu phế phẩm kiếm nhiều tiền .\nNhưng lúc đó cái kia nữ đồng học , là bị sữa của mình nãi nuôi , mà trong nhà nàng , là bà nội nàng thu phế phẩm .\nNói thu phế phẩm , là đã hướng về dễ nghe phương hướng nói , kỳ thực chính là nhặt đồ bỏ đi .\n“ Khi đó , cái kia chủ nhiệm lớp , cũng thường xuyên mắng nàng , coi nàng là điển hình tới nói .”\n“ Bởi vì cái kia nữ đồng học thành tích , đúng là toàn lớp kém nhất .”\n“ Cho nên bị chửi liền thành quen thuộc .”\nNói đến đây , Lý Ân Phàm lắc đầu tiếp tục nói :\n“ Về sau lên cao trung , có một ngày ta cùng mấy cái đồng học nói chuyện phiếm .”\n“ Hắn liền nói cho ta biết , Lý Ân Phàm , ngươi còn nhớ rõ sơ trung cái kia nữ đồng học a ?”\n“ Ta nói ta nhớ được , hắn nói , ngươi biết không , nàng cũng đã kết hôn rồi , hài tử đều biết đánh xì dầu .”\n“ Ta lúc đó đơn giản khiếp sợ không gì sánh nổi , cái gì ? Ta còn tại lên cấp ba , nàng vậy mà hài tử đều biết đánh xì dầu ?”\n“ Chờ ta sợ hãi thán phục cho tới khi nào xong thôi , hắn liền thở dài một hơi nói : Đây hết thảy chỉ có thể trách chính nàng .”\n“ Lúc đó lớp chúng ta chủ nhiệm như thế trợ giúp nàng , nhưng nàng đâu ? Tình nguyện một mực cứ như vậy xuống , tất cả chỗ tốt toàn bộ ăn , nhưng vẫn như thế , không muốn thay đổi .”\n“ Ta lúc nghe đến đó , mặt mũi tràn đầy nghi hoặc nhìn hắn .”\nLý Ân Phàm đến bây giờ đều nhớ kỹ chính mình lúc ấy mộng bức thần sắc .\n...', 'output\\mp3\\Màn Trời Quyền Lực Diễn Biến Cùng Truyền Thừa\\0018_Thứ 18 chương Giáo dục bắt buộc.mp3', '2026-09-01T11:21:56.378152+00:00', 'completed', 'completed', 10932, 10932),
	(24, 7, '7641935882890510872', 19, 'Thứ 19 chương Lão sư', 'Thứ chương Lão sư\n“ Ngươi không biết sao ?”\n“ Ta biết cái gì ?”\n“ Ngươi còn nhớ rõ , chúng ta lúc đó , một tháng phải giao ba trăm đồng tiền phí ăn ở , còn có thỉnh thoảng bài thi phí cái gì .”\n“ Mấy chục mấy chục cái chủng loại kia , ngươi cũng còn nhớ chứ ?”\n“ Ta đương nhiên nhớ kỹ .”\nLý Ân Phàm vì cái gì đối với ba trăm cái số này vẫn nhớ vô cùng sâu ? Bởi vì lúc đó trong nhà chính xác rất nghèo , hơn nữa tình huống gia đình của mình cũng vô cùng phức tạp , cho nên mới sẽ vô cùng quen thuộc .\n“ Cái kia nữ đồng học , từ mùng một bắt đầu , đến sơ tam , tất cả phí ăn ở , học phí , tiền học phí ...”\n“ Tất cả đều là chúng ta ngay lúc đó chủ nhiệm lớp nàng cho .”\n“ A ?!!”\nLý Ân Phàm thật sự , chính mình mãi mãi cũng quên không được ngày đó , chính mình cái kia kinh hãi nội tâm .\nTừ nhỏ đến lớn , chuyện như vậy , hắn một mực chỉ ở trong sách gặp qua .\nNhưng làm thời điểm ở bên cạnh xảy ra chuyện như vậy , hắn mới phát hiện chuyện như vậy có bao nhiêu khoa trương .\n“ Không chỉ là dạng này , ngươi cũng nhớ kỹ cái kia nữ đồng học trên thân luôn có một cỗ như có như không mùi thối a ?”\n“ Đúng , ta nhớ được .”\n“ Vậy ngươi còn nhớ rõ , cái kia nữ đồng học ngẫu nhiên đổi quần áo mới a ?”\n“ Ngươi nói là ?”\n“ Còn có , tự học buổi tối thời điểm , ngẫu nhiên nói là đem nàng kéo đi văn phòng bị mắng .”\n“ Chủ nhiệm lớp mua cho nàng , nói là đi bị mắng , kỳ thực là đưa đến trong nhà mình đi cho nàng tắm rửa .”\nNói đến đây thời điểm , Lý Ân Phàm còn nhớ rõ lúc đó bạn học kia sâu đậm thở dài một hơi .\n“ Chủ nhiệm lớp một mực nói cho nàng , không nên đem chuyện này nói ra .”\n“ Không cần cho bất luận kẻ nào nói , cho dù là người nhà của mình .”\nTrước đó Lý Ân Phàm không hiểu tại sao muốn nói như vậy , nhưng chờ hắn sau khi trưởng thành , liền biết tại sao .\nGhen ghét ...\n“ Chủ nhiệm lớp thường xuyên mắng nàng , cũng là bởi vì chỉ tiếc rèn sắt không thành thép .”\n“ Đều nói cho nàng , có khó khăn gì đi tìm nàng , nàng chỉ cần học tập cho thật giỏi là được rồi .”\n“ Thế nhưng là ...”\nNói đến đây , vị bạn học kia không có tiếp tục nói nữa .\n“ Từ mùng một đến sơ tam , thành tích vẫn luôn là kém nhất .”\n“ Vì để cho nàng không bị chúng ta khi dễ , đều nói cho nàng , không muốn đi nhặt đồ bỏ đi , đòi tiền , liền đi tìm nàng .”\n“ Coi như là nàng cấp cho vị nữ bạn học kia , lớn lên có tiền , lại cho nàng liền tốt .”\nLý Ân Phàm lúc đó lúc nghe đến đó , cũng không biết nên nói cái gì cho phải .\nĐây quả thật là lật đổ chính mình đối với sơ trung chủ nhiệm lớp ấn tượng .\n“ Vậy làm sao ngươi biết ?”\n“ Bạn gái của ta nói cho ta , nói là vị nữ bạn học kia tự giác có lỗi với chủ nhiệm lớp , đem mọi chuyện cần thiết nói ra .”\n“ Cuối cùng , cũng không có đi gặp chủ nhiệm lớp .”\n“ Thi cấp ba sau khi xong , biết mình thi không đậu cao trung , ngoan ngoãn theo phụ thân an bài , đi kết hôn , gả cho trên trấn một cái hơn 40 tuổi giết heo .”\nNói đến đây , Lý Ân Phàm còn nhớ rõ vị bạn học kia đưa tay dựng lên một cái bốn .\n“ 4 vạn lễ hỏi .”\n“ 4 vạn ?!”\n“ Đúng , liền 4 vạn .”\nLý Ân Phàm còn nhớ rõ lúc đó bầu không khí yên lặng rất lâu .\n“ Ngươi cũng biết , sơ trung là tại trên trấn , cho nên , đến mỗi thứ sáu cùng chủ nhật , vị nữ bạn học kia cũng không dám ra đường .”\n“ Sợ nhìn thấy chủ nhiệm lớp .”\n“ Dù sao trấn lại không lớn .”\n“ Mấy năm , một mực là dạng này .”\n“ Không dám gặp phải chủ nhiệm lớp ?”\n“ Đúng vậy , nghe ta bạn gái nói , nàng sợ chủ nhiệm lớp chất vấn chính mình , cũng sợ chủ nhiệm lớp bình tĩnh hỏi nàng gần nhất như thế nào .”\n“ Nàng cũng không biết trả lời như thế nào .”\n“ Thi xong , vẫn không có gặp lại chủ nhiệm lớp .”\n...\n“ Chờ thêm sau đại học , ta lại biết một chuyện .”\nLý Ân Phàm cùng Thủy Hoàng Doanh Chính còn có Mông Điềm 3 người , tìm một chỗ ngồi xuống .\n“ Sơ trung , cao trung thời điểm , ta cùng một cái đồng học chơi vô cùng muốn hảo .”\n“ Trong nhà của hắn nói như thế nào đây ? Kỳ thực ta đến bây giờ đều không có vuốt rõ ràng , trong nhà hắn đến cùng gì tình huống .”\n“ Ngược lại hắn cho chúng ta nói là , trong nhà phụ thân không cần hắn nữa , hắn tự mình chạy đi ra , buổi tối một người ngủ ở trạm xe buýt .”\n“ Lúc đó trong nhà của ta tình huống cũng không tốt , nhưng chính là dạng này , ta vẫn đang trợ giúp hắn .”\n“ Ta cùng mấy cái bằng hữu , từ sơ trung , mãi cho đến cao trung , cũng đang giúp trợ hắn .”\n“ Ta thường xuyên dẫn hắn ăn cơm , ta người bạn kia , liền để hắn ngủ ở nhà mình .”\n“ Ta lúc đó mỗi tuần tiền sinh hoạt ta còn nhớ rõ ba trăm khối tiền .”\n“ Đây là ta một tuần tiền ăn .”\n“ Nhưng cứ như vậy , ta còn có thể cầm một trăm đi ra , cho hắn .”\n“ Bởi vì thường xuyên cùng một chỗ đi , có đôi khi lúc tán gẫu , sẽ hàn huyên tới sơ trung , hắn liền thường cho chúng ta nói , sơ trung chủ nhiệm lớp cỡ nào cỡ nào không tốt , bởi vì là nữ chủ nhiệm lớp đi , cho nên còn thường xuyên tạo nàng Hoàng Dao .”\n“ Nói chủ nhiệm lớp trong ngăn kéo , có mấy phần nạo thai chứng minh cái gì .”\nCũng chính là chuyện này , để cho Lý Ân Phàm biết rõ cái gì là nhân tính .\n“ Chúng ta cứ như vậy một mực trợ giúp hắn .”\n“ Đến cao tam thời kì cuối bỗng dưng một ngày , bởi vì là học ngoại trú , chính là tự học buổi tối kết thúc , không trọ ở trường , về nhà ngủ .”\n“ Ta cùng hắn đều là học ngoại trú , cho nên thường xuyên đi ra trường học .”\n“ Một ngày kia ta nhớ được rất rõ ràng , ta tại chỗ khúc quanh chờ hắn , chờ hắn đến đây thời điểm , ta theo thói quen hỏi nàng , trên thân có còn tiền hay không ?”\n“ Hắn nói không còn .”\n“ Tiếp đó ta liền cho hắn rút hai mươi khối .”\n“ Lúc đó trên người của ta , tổng cộng mới ba mươi khối tiền !”\n“ Cứ như vậy cho hắn rút hai mươi .”\n“ Đem tiền cho hắn sau đó , ta liền nói cho hắn , cái này hai mươi ngươi cầm , đi quán net mở máy móc , chấp nhận ngủ một đêm .”\n“ Hắn liền nói hảo .”\n“ Chờ hắn đi sau đó , ta liền cho một cái khác trợ giúp hắn người gọi điện thoại .”\n“ Ta chất vấn hắn , từ đi , ngươi không cho hắn lấy tiền ? Trên người của ta tổng cộng liền ba mươi , chỉ có thể cho hắn hai người , để cho hắn ngủ quán net .”\n“ Lúc đó , trong điện thoại liền truyền đến một hồi tiếng mắng : Con mẹ nó ngươi đánh rắm , lão tử mới từ cùng phòng cái kia cho mượn năm mươi cho hắn .”\n“ Lời này vừa ra , ta cùng hắn đều mộng .”\nLý Ân Phàm hiện tại cũng còn nhớ mình lúc đó nghe được một câu nói này mộng bức .\nThật sự mộng bức .\nCũng là lần thứ nhất cảm nhận được cái gì là mộng bức .\n“ Chờ đến cuối tuần thời điểm , ta cùng hắn đối với sổ sách , mới phát hiện rất nhiều vấn đề .”\n“ Người kia , hắn là vừa ở ta cái này đòi tiền , lại tại hắn cái kia đòi tiền ...”\n“ Tiền cầm , không phải đi chơi , chính là đi ăn .”\n“ Ăn so ta còn tốt , chơi cũng so tất cả mọi người đều hảo , cuối tuần còn mang mấy nữ nhân du sơn ngoạn thủy ...”\nLý Ân Phàm nhớ kỹ mình biết rồi sau đó rất bình tĩnh .\nTrực tiếp không có sẽ liên lạc lại người kia .\n“ Mà để cho người cảm thấy chán ghét là cái gì ?”\n“ Hắn ở ta cái này tạo sơ trung chủ nhiệm lớp Hoàng Dao .”\n“ Tại một người khác nơi đó , nói sơ trung chủ nhiệm lớp đối với hắn cỡ nào hảo .”\n“ Tại hắn sơ trung không có chỗ ở thời điểm , bị đuổi ra ngoài thời điểm , sơ trung chủ nhiệm lớp đem mình tại trên trấn vừa mua thời điểm , chính mình cũng không có nổi , để cho hắn đi ở .”\n“ Trong nhà không cho hắn lấy tiền nhà được phân túc phí , học phí , tiền học phí , vẫn là sơ trung chủ nhiệm lớp cho .”\nLý Ân Phàm nói đến đây , sâu đậm thở dài một hơi .\n“ Cũng chính là chuyện này , để cho ta đã biết cái gì là nhân tính .”\n“ Dù là đều đến bây giờ , đều nhanh đi qua mười mấy năm , sau khi tốt nghiệp trung học , hắn đều cho tới bây giờ không cùng chúng ta liên hệ .”\n“ Dù là giảng giải cũng không có giảng giải một câu , trực tiếp biến mất .”\nNói là bằng hữu , nói là đồng học , nhưng lúc sơ trung , vì chơi vui , cũng vì giảng nghĩa khí .\nLý Ân Phàm còn cùng bọn hắn sáu người kết nghĩa .\nThật sự kết bái !\nSơ trung khi đó liền lưu hành loại này .\nKết nghĩa sau đó , cảm thấy cũng là huynh đệ , cho nên để nghĩa khí , vẫn trợ giúp người kia .\n“ Đến bây giờ , kỳ thực ta nghĩ tới đây một sự kiện đều cảm thấy hết sức phức tạp .”\n...\nHiện đại thời không .\n“ Đây chính là đời sau lão sư sao ?”\nThủy Hoàng Doanh Chính nghiêm túc nghe xong Lý Ân Phàm thời gian dài như vậy giảng thuật .\n“ Hơn nữa , vẫn là một nữ tử .”\nDoanh Chính lại sâu hơn đối với đời sau một chút ấn tượng .\nMột cái lão sư , một nữ tử , yên lặng đối với học sinh trả giá , có thể nói thật sự hoàn toàn không cầu hồi báo .\n“ Ta gặp lão sư , bây giờ quay đầu xem xét , đều rất tốt .”\n“ Giáo viên tiểu học , sơ trung lão sư , cao trung lão sư , cũng là tận chức tận trách .”\n“ Đặc biệt là ba lớp này chủ nhiệm , vậy càng là vượt ra khỏi hiện đại đối với lão sư tiêu chuẩn .”\n“ Cho nên ta đối với ba vị này lão sư vẫn luôn vô cùng cảm kích .”\nLý Ân Phàm nhìn chăm chú lên tiểu học cửa ra vào bọn nhỏ từ từ tiêu thất , nhẹ nói :\n“ Cũng chính bởi vì có bọn hắn dạng này yên lặng trả giá , quốc gia mới có thể từng bước một thay đổi xong .”\nBên cạnh Mông Điềm há to miệng , cũng thấy một mắt bệ hạ , lại ngậm miệng lại .\nCó một số việc , không nên hắn đi nói , cũng không nên hắn đi hỏi .\nBệ hạ nếu như muốn biết , vậy tất nhiên là biết hỏi thăm .\nNhưng tất nhiên không có hỏi thăm , ở trong đó liền nhất định còn có chính mình không có chú ý tới địa phương .\n...\nXuân Thu Chiến Quốc thời kì .\nLỗ Ai Công mười hai năm .\n“ Đây chính là hậu thế ?”\n“ Đây chính là đời sau lão sư ?”\nChờ màn trời kể xong , Khổng Tử mặt mỉm cười nhìn xem màn trời .\nLúc này Khổng Tử , nội tâm vô cùng thỏa mãn .\nHắn cảm giác chính mình cuối cùng gặp được theo đuổi hết thảy , gặp được chính mình trong giấc mộng thiên hạ đại đồng .\n“ Lão sư , cũng là một cái lão sư tốt ...”\n...\nPhía trên cũng là tác giả chân thực kinh nghiệm .\nBiểu lộ cảm xúc a , bây giờ quay đầu hồi tưởng lại sơ trung chủ nhiệm lớp , ấn tượng càng thêm khắc sâu , rất nhiều trong sách xuất hiện tình huống , vậy mà thật sự xuất hiện ở bên cạnh mình .\nPhía trên nói hai chuyện , cũng đều là chân thực phát sinh , tác giả không có bất kỳ cái gì nghệ thuật gia công .\n......', 'output\\mp3\\Màn Trời Quyền Lực Diễn Biến Cùng Truyền Thừa\\0019_Thứ 19 chương Lão sư.mp3', '2026-09-01T11:22:01.508336+00:00', 'completed', 'completed', 9925, 9925),
	(25, 7, '7642328161773945368', 20, 'Thứ 20 chương Rượu văn hóa', 'Thứ chương Rượu Văn Hóa\nHiện đại thời không .\n“ Chúng ta ăn đẹp Oa Ngư đầu a .”\nChạng vạng tối sáu, bảy giờ dáng vẻ , Lý Ân Phàm mang theo Doanh Chính cùng Mông Điềm hai người đi vào một nhà tiệm lẩu .\n“ Vẫn là ăn đẹp con ếch tốt một chút , đầu cá nói như thế nào đây , ta cảm giác ăn không quá ngon .”\n“ Tiên sinh , ngươi làm chủ liền tốt .”\nMông Điềm cười đối với Lý Ân Phàm nói .\n“ Đi .”\nỞ quê hương , Lý Ân Phàm thích ăn nhất chính là đẹp Oa Ngư đầu , kỳ thực nói là đẹp Oa Ngư đầu , đầu cá bán đi rất ít , phần lớn là đẹp con ếch .\nMột là thuận tiện , thứ hai là đầu cá thịt rất ít , ngoại trừ đặc biệt thích ăn đầu cá , bây giờ người địa phương ăn đẹp Oa Ngư đầu , trên cơ bản cũng là chỉ chọn đẹp con ếch .\nMang theo hai người đi vào phòng , Lý Ân Phàm tiếp nhận phục vụ viên đưa tới menu .\n“ Tới chín cân đẹp con ếch ...”\n“ Sẽ tiễn đưa ba cân đúng không ?”\nLý Ân Phàm cầm bút lên , tại menu đẹp con ếch cân đếm phía trước viết lên chín cân .\n“ Đúng , mỗi ba cân tiễn đưa một cân , hết thảy mười hai cân .”\n“ Đi .”\nLý Ân Phàm lại điểm một chút thức ăn chay , thức ăn chay phần lớn là hiện đại một chút phổ biến đồ ăn , như thổ đậu , súp lơ các loại .\n“ Lại đến một bình đều có thể nhạc , một bình Mao Đài .”\nPhục vụ viên ngẩng đầu nhìn Lý Ân Phàm một mắt , sau đó gật đầu một cái .\n“ Chỉ những thứ này a .”\nLý Ân Phàm đem menu đưa cho phục vụ viên .\nChờ phục vụ viên sau khi ra ngoài , Lý Ân Phàm đem trên bàn bát đũa mở ra , cầm bát đứng dậy .\n“ Mông tướng quân , ngươi đem Thủy Hoàng bát cầm , cùng đi với ta đánh gia vị .”\n“ Không cần , ta cũng cùng các ngươi cùng đi .”\nDoanh Chính cự tuyệt Lý Ân Phàm đề nghị , học Lý Ân Phàm dáng vẻ mở ra bát đũa , cầm bát .\n“ Đây là rau thơm , đây là Chiết Nhĩ Căn , đây là hao xăng ...”\nLý Ân Phàm mang theo hai người đi đến đánh gia vị địa phương , từng cái cho mấy người thuyết minh .\n“ Các ngươi trước tiên không cần đánh rau thơm cùng Chiết Nhĩ Căn , ăn không quen người , là rất chán ghét ăn hai thứ đồ này .”\nThủy Hoàng Doanh Chính cùng Mông Điềm rất nghe khuyên , chỉ đánh một chút vật gì khác .\nĐặc biệt là Chiết Nhĩ Căn thứ này , Tây Nam bên ngoài địa phương , trên cơ bản đều ăn không quen thứ này .\nTây Nam bên trong đâu ? Yêu thích phi thường yêu thích , cũng tỷ như Lý Ân Phàm .\nHắn liền phi thường yêu thích ăn Chiết Nhĩ Căn .\nRau trộn Chiết Nhĩ Căn , ăn lẩu nấu Chiết Nhĩ Căn , còn hữu dụng Chiết Nhĩ Căn bao lấy thịt bò nổ chuỗi chiên .\nHắn đều thích ăn .\nNhưng không thích , trên cơ bản là ăn một miếng liền phun .\nĐợi đến đánh hảo gia vị , Lý Ân Phàm lại đi ra ngoài tại quầy thu ngân để cho phục vụ viên cho hắn cầm một cái bát .\nLấy được cái này bát , Lý Ân Phàm đi đến đánh gia vị địa phương , đánh một chút Chiết Nhĩ Căn cùng rau thơm .\n“ Các ngươi thử xem , xem cái mùi này các ngươi có thể hay không tiếp nhận .”\nLý Ân Phàm đi vào phòng , đem trong tay bát đặt ở trước mặt Doanh Chính .\nMông Điềm trước tiên cầm đũa lên , vê thành một điểm Chiết Nhĩ Căn bỏ vào trong miệng .\n“ Ân ?!!”\nChỉ là nhẹ nhàng nhai rồi một lần , Mông Điềm sắc mặt lập tức thì thay đổi .\n“ Ọe !!!”\nMông Điềm vội vàng đem trong miệng Chiết Nhĩ Căn phun ra .\nDoanh Chính tò mò nhìn Mông Điềm , hắn rõ ràng trông thấy Mông Điềm chỉ là vê thành từng chút một Chiết Nhĩ Căn , vì sao lại có phản ứng lớn như vậy ?\n“ Bệ hạ , thứ này ...”\n“ Thối , đắng , còn có một chút tanh ...”\nMông Điềm nhìn xem cái kia trong chén Chiết Nhĩ Căn , thần sắc thật sự không nói được chán ghét .\nHắn thật sự là không nghĩ tới , cứ như vậy một điểm Chiết Nhĩ Căn , bên trong ẩn chứa hương vị , vậy mà phức tạp như thế .\n“ Ân ...”\nDoanh Chính gật đầu một cái , quyết định vẫn là tự mình thử một chút .\n“ Mùi vị kia ...”\n“ Cảm giác tựa hồ vẫn được ?”\nDoanh Chính lập lại trong miệng tai căn , cau mày nói .\n“ Là có một chút tanh đắng , nhưng không có đến không thể để cho người ta tiếp nhận trình độ .”\nNói xong , Doanh Chính lại cầm đũa lên , vê thành một chút rau thơm .\n“ Ọe ... Phi ...”\nDoanh Chính vừa đem rau thơm bỏ vào trong miệng , cũng có chút chịu không được , đem rau thơm phun ra .\nBên cạnh Mông Điềm đâu ? Nhưng là lập lại rau thơm , cảm giác vẫn rất có mùi vị .\n“ Đây chính là rau thơm cùng tai căn ...”\n“ Yêu thích , rất nhiều nơi đều không ít bọn chúng .”\n“ Không thích , giống như các ngươi dạng này ...”\nLý Ân Phàm thấy dáng vẻ của hai người , khẽ cười nói .\n“ Còn tốt trong chén này không có tai căn ...”\nMông Điềm có chút may mắn nhìn một chút chính mình gia vị bát .\n“ Thử lại lần nữa cái này rượu đế ...”\nLý Ân Phàm mở ra Mao Đài , cho hai người ly rượu trước mặt bên trong rót đầy ly .\n“ Tiên sinh , đây là rượu ?”\nMông Điềm ngạc nhiên liếc mắt nhìn ly rượu trước mặt , lại nhìn một chút Lý Ân Phàm trong tay bình rượu .\n“ Ân , đây chính là rượu , chỉ là đây là hiện đại vô cùng độ cao đếm được chưng cất rượu .”\n“ Tống , nguyên phía trước , trên cơ bản cũng là lên men rượu , tỉ như nói hoàng tửu , rượu gạo các loại .”\n“ Nguyên triều sau đó , chưng cất kỹ thuật xuất hiện , độ cao đếm được rượu liền bắt đầu xuất hiện , chỉ là khi đó gọi rượu trắng .”\n“ Các ngươi uống lên men rượu , số độ trên cơ bản tại độ dáng vẻ .”\nLý Ân Phàm giơ tay lên bên trong chén rượu , xa kính hai người một chút , nhấp một miếng .\nMông Điềm đầu tiên là kính Doanh Chính , sau đó lại kính Lý Ân Phàm , tài học lấy bộ dáng của hắn nhấp một miếng .\n“ Tê a ...”\nMông Điềm dùng sức lắc đầu một cái .\n“ Rượu này , rất không quen ...”\nHương vị tự nhiên là cực tốt , nhưng đối ẩm quen thuộc lên men rượu Tần triều mà nói , lần thứ nhất uống như thế cao độ đếm được rượu , thực sự có chút không tốt nuốt xuống .\n“ Ân ... Quả thật là như thế , quá mức cay độc ”\nDoanh Chính cũng nhấp một miếng , nhẹ nói .\nNgay ở chỗ này , phòng cửa mở ra .\n“ Cẩn thận rồi , đều để một a ...”\nPhục vụ viên bưng oa đi đến , đem oa đặt lên bàn ở giữa sau , nhẹ nói :\n“ Cần đánh liệu sao ?”\n“ Chính chúng ta tới liền tốt ...”\n“ Tốt .”\nPhục vụ viên nghe được Lý Ân Phàm lời nói , lui ra ngoài .\n“ Ăn trước , xem có hợp hay không khẩu vị của các ngươi , nếu như cần hương vị trọng một chút , ta lại cho các ngươi gia vị ...”\nLý Ân Phàm trực tiếp cầm đũa lên , kẹp một cái ếch trâu , chuẩn bị bắt đầu ăn .\nDoanh Chính Mông Điềm hai người , cũng riêng phần mình kẹp lên một cái ếch trâu .\n“ Đây chính là ếch trâu ?”\n“ Ân ...”\nLý Ân Phàm đầu tiên là lắm điều một chút , tiếp đó cắn một nửa , ở trong miệng từ từ đem thịt nhấp xuống .\nChờ trong miệng chỉ còn dư xương , tiếp đó liền phun đi ra .\n“ Mùi vị không biết như thế nào ? Còn cần hương vị trọng một chút sao ?”\n“ Như vậy thì rất tốt .”\nDoanh Chính ăn rất chậm .\nBởi vì là lần thứ nhất ăn , cho nên ăn vô cùng cẩn thận .\nBên cạnh Mông Điềm cũng giống như thế .\n“ Tới , Thủy Hoàng , Mông tướng quân , chúng ta uống một ngụm ...”\nLý Ân Phàm cầm chén rượu lên , kính hai người một chút .\nDoanh Chính cùng Mông Điềm để đũa xuống , bưng chén rượu lên , đồng dạng kính Lý Ân Phàm .\n“ Lần này mùi ngon nhiều .”\nMông Điềm cảm khái nói .\nĂn ếch trâu , lại uống một ngụm rượu đế , như vậy thì cảm giác không có khó như thế phía dưới nuốt .\n“ Chính xác như thế .”\nNói đến đây , Doanh Chính rất là tò mò nhìn Lý Ân Phàm nói :\n“ Bây giờ mở tiệc chiêu đãi khách mời thời điểm , cũng muốn mời rượu sao ?”\n“ Đương nhiên như thế .”\n“ Dù sao cái này cũng là “ Lễ ”.”\nHiện đại rất nhiều người chán ghét rượu Văn Hóa , cho rằng rượu Văn Hóa là thế kỷ trước Đại Hùng mang tới .\nKỳ thực rất rất ít có người biết , rượu Văn Hóa tại chúng ta cổ đại , rất sớm đã bắt đầu .\nCó sớm bao nhiêu ?\nTây Chu thời kì Chu Công Chế lễ làm vui , đem uống rượu đặt vào 《 Chu Lễ 》 thể hệ , “ Hương uống rượu lễ ” “ Ba tước chi lễ ” ( Hiến , tạc , thù ) xác lập chủ khách mời rượu hoàn chỉnh quá trình , cường điệu tôn ti có thứ tự , nơi hạn định , tiêu chí Nhân tế mời rượu lễ nghi quy định tan ra bưng\nKhông tệ , chính là sớm như vậy !\n“ Ăn cơm buổi trưa như vậy tùy ý , ta đã cho là không còn .”\nDoanh Chính nở nụ cười nói .\n“ Cái này nói như thế nào đây ?”\nLý Ân Phàm để đũa xuống , nhấp một miếng rượu đế .\n“ Hiện đại rất nhiều người cho là rượu Văn Hóa là cặn bã .”\n“ Kỳ thực trong mắt của ta , rượu Văn Hóa bản thân không phải cặn bã , cặn bã chính là cái gì ? Những cái kia không tiết chế mời rượu người .”\n“ Người khác không thể uống , ngươi còn dùng sức khuyên người khác uống rượu , này liền có chút ...”\nThủy Hoàng cùng Mông Điềm nghe được cái này , cũng là nhíu mày một cái .\n“ Hiện đại rất nhiều người không thích uống rượu , thì ra là vì vậy .”\n“ Ta trước đó cũng không thích uống rượu , bởi vì một đời trước người , bọn hắn uống rượu thật sự không có chút nào tiết chế .”\n“ Người khác không thể uống , còn dùng sức khuyên , cứ như vậy , chúng ta trên hương trấn , hàng năm đều phải uống chết mấy cái .”\nLý Ân Phàm quê hương , trước đó kỳ thực rượu Văn Hóa vô cùng nồng đậm .\nCó nhiều nồng đậm ? Trên cơ bản cách mười mấy mét , chính là một cái bán rượu cửa hàng .\nTrên đường cái , cả ngày cũng là mùi rượu .\nChỉ là bây giờ tốt hơn rất nhiều , bến tàu đóng lại sau đó , những thứ này bán rượu cửa hàng , cũng đã biến mất rất nhiều .\n“ Nhưng nói thật , rượu này Văn Hóa muốn nói là cặn bã ?”\nLý Ân Phàm trầm tư một hồi sau , nhìn hai người nói :\n“ Cũng đúng là cặn bã .”\n“ Vì cái gì nói như vậy ?”\n“ Thủy Hoàng , Mông tướng quân , các ngươi hẳn là nhớ kỹ , cái này uống rượu là nhét vào 《 Chu Lễ 》 a ?”\n“ Thật là như thế .”\nMông Điềm gật đầu một cái .\n“ Cái này kỳ thực liền tạo thành một cửa ải .”\n“ Rất nhiều người chỉ cần nhìn ngươi có thể hay không mở tiệc chiêu đãi khách mời , liền biết ngươi có phải hay không “ Quý tộc ”.”\nTại cổ đại , uống rượu nhét vào 《 Chu Lễ 》, vậy thì rất đơn giản , chỉ cần nhìn ngươi biết uống rượu hay không , người khác liền có thể rất đơn giản định nghĩa xuất thân của ngươi .\nCái này kỳ thực chính là một đạo vô hình cánh cửa .\nKhông có người dạy ngươi ? Ngươi không có địa phương học ? Vậy ngươi chính là không hiểu lễ tầng dưới chót !\nQuý tộc và nhà giàu mới nổi , chính là đơn giản như vậy dễ dàng phân chia !\nTri thức , không chỉ là học thức bên trên , sinh hoạt mọi mặt cũng là như thế !\nMà kỳ thực không chỉ là cổ đại , cho dù là hiện đại .\nVì cái gì bây giờ càng ngày càng nhiều người chán ghét rượu Văn Hóa , nhưng ở bên trong cao tầng , rượu Văn Hóa một mực vẫn tồn tại ?\nMột cái là cánh cửa , hai chính là loại bỏ hết người ngu .\nHai cái này là chủ yếu nhất !\nĐặc biệt là bài trừ người ngu .\nRất nhiều vòng tròn , đang chuẩn bị tiếp nhận ngươi , đều biết mở tiệc chiêu đãi ngươi uống rượu .\nMà cũng chính là bữa nhậu này , liền có thể nhìn ra ngươi đến cùng là người thông minh , vẫn là người ngu .\nRất nhiều người có thể sẽ nghĩ , liền một bữa rượu , sao có thể nhìn ra được ?\nUống say phát ngôn bừa bãi cái gì cũng dám nói , cùng uống say vẫn như cũ giữ vững tỉnh táo .\nNếu như là ngươi , ngươi sẽ tiếp nhận cái nào ?\nĐây chỉ là đơn giản nhất khác nhau ! Nhưng như vậy thì có thể đem tự đại ngu xuẩn , cùng đầu não tỉnh táo người thông minh phân chia ra .\nĐây chính là hiện tại vì cái gì rượu Văn Hóa một mực tồn tại nguyên nhân .\nĐương nhiên , chủ yếu nhất là , bên trong cao tầng người , kỳ thực không có thời gian trong lúc làm việc , hoặc có lẽ là tại bình thường khảo hạch ngươi quan sát ngươi .\nHơn nữa , trong lúc làm việc , tại trong sinh hoạt , người đều sẽ ngụy trang .\nNhưng như thế nào để cho hắn bại lộ bản tính đâu ?\nRượu liền có thể !\nHơn nữa , là đơn giản nhất một loại .\nVì cái gì nói rượu phẩm vừa nhân phẩm ? Đây chính là nguyên nhân .\n...', 'output\\mp3\\Màn Trời Quyền Lực Diễn Biến Cùng Truyền Thừa\\0020_Thứ 20 chương Rượu văn hóa.mp3', '2026-09-01T11:22:06.829014+00:00', 'completed', 'completed', 11347, 11347),
	(26, 7, '7642328320008258072', 21, 'Thứ 21 chương Mỹ thực lịch sử? Nạn đói lịch sử...', 'Thứ chương Mỹ thực lịch sử ? Nạn đói lịch sử ...\nHiện đại thời không .\n“ Giống như , quả thật là như thế .”\nMông Điềm nghe xong Lý Ân Phàm giảng thuật , suy tư một hồi sau , khẽ gật đầu một cái .\n“ Bình thường , uống rượu thời điểm , quả thật có thể rất đơn giản nhìn ra một người xuất thân .”\nThủy Hoàng đối với chuyện này là rất có quyền lên tiếng .\nMở tiệc chiêu đãi đại thần thời điểm , nếu là cái nào đại thần , lễ tiết sai lầm , liền có thể nhìn ra hắn một vài vấn đề .\n“ Tiên sinh , các ngươi hiện đại người , đều ăn loại này sao ?”\nMông Điềm lúc này chỉ chỉ trong chén ếch trâu nói .\n“ Bình thường là không ăn , chỉ là ngẫu nhiên .”\n“ Món chính vẫn là cơm còn một chút đồ ăn thường ngày .”\nMông Điềm gật đầu một cái , lại nói tiếp :\n“ Hôm nay trên đường , ta chính xác thấy được rất nhiều loại này cửa hàng .”\n“ Giống như cũng không giống nhau ?”\n“ Ân , cũng không giống nhau , hiện đại kỳ thực có rất nhiều ăn .”\n“ Trước đó có một chuyện cười , nói là người nước ngoài đi tới nơi này , lập chí mỗi ngày ăn một loại khác biệt mỹ thực , kết quả 3 năm , còn chưa đi ra Tứ Xuyên .”\nLý Ân Phàm nói đến đây thời điểm , trên mặt rất là bình tĩnh .\nKỳ thực , trước đó hắn đối với phương diện này , còn có thể cười ra tiếng .\nNhưng đợi giải lịch sử sau đó , nói như thế nào đây ? Rất khó cười ra tiếng .\nQuốc nội mỹ thực đúng là nhiều , trên bầu trời bay , bò dưới đất , trong nước du ngoạn , rất rất ít là quốc nội dân chúng không dám ăn .\nNhưng có rất ít người đi tìm hiểu tại sao lại như thế ?\nĐây quả thật là một loại kiêu ngạo sao ?\nTại Lý Ân Phàm xem ra , bên trong nội hạch , kỳ thực là một cái bi kịch .\nNếu như trong lịch sử , món chính đủ , tầng dưới chót có thể ăn cơm no , cái kia còn có thể nghĩ trăm phương ngàn kế tìm ăn sao ?\nCho nên , mỹ thực lịch sử , tại Lý Ân Phàm xem ra , kỳ thực chính là một bộ nạn đói lịch sử .\nBằng vào chúng ta hiện đại góc nhìn đến xem , rất nhiều thứ , đúng là mỹ thực .\nNhưng đó là bởi vì hiện đại rất nhiều thứ quá đầy đủ , gia vị , dầu , củi lửa các loại , đây đều là cổ đại tầng dưới chót , khó có thể tưởng tượng .\nNếu như không phải cùng đường mạt lộ , không có người nguyện ý đi ăn những vật kia .\nChỉ có tại trong tuyệt lộ , mới có thể lên núi kiếm ăn , xuống sông uống nước .\nCó đi qua Vân Nam tiểu đồng bọn hẳn biết rất rõ , vì cái gì Vân Nam bên kia ăn vặt , có rất nhiều côn trùng ?\nThật sự cho rằng cổ nhân nguyện ý ăn côn trùng ?\nNếu như không phải hiện đại dầu mazut nặng trọng muối , hiện đại người thật có thể ăn nổi ?\nVì sao là nạn đói lịch sử ? Chính là như thế .\nCho nên , tại Lý Ân Phàm xem ra , cái gọi là mỹ thực lịch sử , bằng vào chúng ta hiện đại góc nhìn đi xem , suy nghĩ , đúng là một bộ hùng vĩ mỹ thực lịch sử .\nNhưng nội hạch , kỳ thực chính là bao quanh hiện đại vỏ bọc đường nạn đói lịch sử .\n...\nHán triều .\nNguyên thú 4 năm .\n“ Nhạt nhẽo vô vị ...”\nMàn trời phía dưới , Lưu Triệt cùng Vệ Thanh mấy người , đồng dạng đang ăn nấu cơm canh .\nTrước đó hắn còn không có cảm thấy có cái gì , nhưng nhìn lấy trên thiên mạc Doanh Chính cùng Mông Điềm hai người ăn nồng nhiệt thần sắc , lại ăn trước kia đồ ăn , lập tức liền có một loại nhạt nhẽo cảm giác .\nĐặc biệt là nhìn xem màn trời phía trên , Doanh Chính cùng Mông Điềm trong chén những cái kia gia vị .\nNhìn lại mình một chút trước mặt , cái kia lau một chút muối thô ăn thịt .\n“ Ai ...”\nLưu Triệt gắp thịt lên , dùng sức nhai nhai nhấm nuốt mấy lần .\nPhía dưới Vệ Thanh liếc mắt nhìn màn trời , yên lặng tiếp tục ăn trước mặt cơm canh .\n...\nTần triều .\nThủy Hoàng ba mươi năm .\nChương Đài cung .\nPhù Tô giờ phút này bỗng nhiên vô cùng hâm mộ Mông Điềm .\nSo sánh trước mặt mình thô nhạt ăn thịt , nhìn lại một chút màn trời phía trên trước mặt bọn hắn cơm canh .\nCó đôi khi không so sánh , thật sự không biết tổn thương lớn bao nhiêu .\n“ Cho nên a cha làm cái gì không để ta đi ?”\nPhù Tô trong đầu , bỗng nhiên bốc lên một cái ý nghĩ như vậy .\n...\nĐường triều .\nTrinh Quán bảy năm .\n“ Có đôi khi người này a , có sợ so sánh .”\nLý Thế Dân nhìn xem trước mặt mấy tiểu chỉ khó mà nuốt xuống thần sắc , cười lắc đầu .\nHắn ngược lại là cái gì đều ăn xuống , dù sao lúc đó trong quân đội , cái gì chưa ăn qua ?\nLại khó mà nuốt xuống đồ vật , vì đánh thắng trận , đều buộc chính mình ăn qua , ngay bây giờ điểm ấy tình huống ?\nĐối với Lý Thế Dân tới nói , chỉ là trò trẻ con .\nNhưng chính là khổ mấy tiểu chỉ .\nĐặc biệt là còn nhỏ mấy cái kia , lớn cái kia hai cái , ở trước mặt mình , đã không dám làm ra hành động như vậy .\n“ A a , chúng ta cũng đi ăn đồ ăn ngon , có hay không hảo ?”\nNho nhỏ Tấn Dương công chúa leo đến Lý Thế Dân chân bên cạnh , chỉ vào màn trời nãi thanh nãi khí nói .\n“ Hảo , nếu như màn trời rút đến a a , a a nhất định mang Hủy Tử đi .”\nLý Thế Dân cười ha ha , sau đó dùng sợi râu đâm đâm Tấn Dương công chúa .\n“ Tấn Dương , mau tới đây ăn cơm thật ngon .”\nTrưởng Tôn hoàng hậu bất đắc dĩ mắt nhìn Lý Thế Dân , giả vờ tức giận bộ dạng , đối với Tấn Dương công chúa nói .\n“ Ai nha , Tấn Dương tới rồi , mẹ không nên đánh Tấn Dương ...”\nTấn Dương công chúa co lại phía dưới Lý Thế Dân trong ngực , lập tức bước nhỏ chạy đến dài Nhạc Công Chủ bên cạnh .\n“ A tỷ , Tấn Dương muốn ăn cơm cơm rồi .”\nDài Nhạc Công Chủ che miệng cười cười , ôm lấy Tấn Dương , bắt đầu cho nàng cho ăn cơm .\nTrên bàn cơm , tất cả mọi người đều không để ý đến ban ngày màn trời lời nói .\nLý Thế Dân không có mở miệng nói chuyện này , tất cả mọi người đều không có trước tiên lên tiếng .\nMà Lý Thế Dân vì cái gì không nói đâu ? Bởi vì còn chưa tới thời điểm .\nMặc dù ban ngày màn trời nói rất nhiều , nhưng vẫn là có chút không đầu không đuôi .\nLý Thế Dân chuẩn bị mấy người màn trời nói đến Đường triều thời điểm , lại đến thật tốt đàm luận chuyện này .\n“ Thừa Càn ...”\nLúc này , Lý Thế Dân nhìn xem lo lắng Thái tử Lý Thừa Càn .\n“ A a ?”\nLý Thừa Càn lập tức đứng lên , cung kính nhìn xem Lý Thế Dân .\nMà trên bàn những người khác , ngoại trừ dài Nhạc Công Chủ đang đút Tấn Dương , tất cả mọi người đều để đũa xuống , an tĩnh nhìn xem hai người .\nLý Thế Dân thấy thế , nội tâm bỗng nhiên thở dài một hơi .\nTrước đó còn không có cảm thấy có cái gì , nhưng hôm nay màn trời nói sau đó , hắn lúc này mới phát hiện rất nhiều vấn đề .\nNgười nhà không giống người nhà , Hoàng gia không giống Hoàng gia .\nVốn là gia yến , nhưng ở trong đó ?\nAi ...】\n“ Trong khoảng thời gian này , ngươi tốt nhất dưỡng tốt cơ thể .”\n“ Không muốn làm , liền không đi làm ...”\nLý Thế Dân chưa hề nói những thứ khác , chỉ là để cho Lý Thừa Càn trong khoảng thời gian này muốn làm cái gì thì làm cái đó .\n“ Cái này ? Nhị Lang ...”\nTrưởng Tôn hoàng hậu tựa hồ nghĩ tới điều gì , trên mặt vội vàng nhìn xem Lý Thế Dân .\n“ Yên tâm , Quan Âm Tỳ , ta không có ý nghĩ kia .”\nLý Thế Dân trấn an được Trưởng Tôn hoàng hậu , tiếp đó lại nhìn xem rõ ràng mang theo vui mừng Lý Thái .\nCau mày , Lý Thế Dân nhìn xem Lý Thái nói :\n“ Đến nỗi thanh tước , ngươi trong khoảng thời gian này hảo hảo ở tại trong nhà , nơi nào cũng không muốn đi .”\n“ A a ?”\nLý Thái mộng bức nhìn xem Lý Thế Dân .\n“ Hôm nay trước tiên là nói về nhiều như vậy , các ngươi đều trở về đi .”\nLý Thế Dân không có lại nói những thứ khác , vẫy tay để cho Lý Thừa Càn cùng Lý Thái rời đi .\nChờ sau khi hai người đi , Lý Thế Dân thở dài một hơi , nhìn xem Trưởng Tôn hoàng hậu nói :\n“ Quan Âm Tỳ , trước đó ta còn không có phát giác được , nhưng ban ngày màn trời nói sau đó , mới phát hiện , cái này gia yến cũng không phải cái gì gia yến .”\n“ Nhị Lang ...”\nTrưởng Tôn hoàng hậu cũng không biết nên cái gì nói .\nNàng có thể nói cái gì ? Nàng chỉ là một cái hoàng hậu , một người mẹ , có thể nói cái gì đâu ?\n“ A a , Đại huynh cùng Nhị huynh vì cái gì đều đi a ?”\nTấn Dương công chúa một mặt mộng nhìn xem Lý Thế Dân .\n“ Ha ha , đại huynh của ngươi bọn hắn đều có việc trở về !”\nLý Thế Dân đi đến Tấn Dương công chúa bên cạnh , từng thanh từng thanh nàng ôm lấy .\nDài Nhạc Công Chủ yên lặng nhìn xem cái này phát sinh hết thảy , cũng không nói gì .\n...\nMinh triều .\nHồng Vũ mười năm .\n“ Cho nên , thật là ta bức tử tiêu nhi ?”\nTrong Khôn Ninh cung , Chu Nguyên Chương cùng Mã hoàng hậu hai người ngồi cùng một chỗ , Mã hoàng hậu từng cái cặn kẽ cho Chu Nguyên Chương nói trắng ra mỗi ngày màn ý tứ .\n“ Ai , trọng tám , ngươi rõ ràng áp lực quá lớn .”\n“ Tiêu nhi chính xác được sủng ái , lão nhị , lão tam bọn hắn , cũng đều không dám cùng tiêu nhi tranh .”\n“ Có thể , cứ như vậy , tiêu nhi chính hắn sẽ như thế nào nghĩ ?”\nChu Nguyên Chương không nói chuyện , an tĩnh nhìn xem Mã hoàng hậu .\n“ Sách sử để ở nơi đó .”\n“ Tiêu nhi lại là đọc thuộc lòng sách sử , hắn gặp trên sử sách Thái tử , cùng mình so sánh một chút , rất rõ ràng liền có thể phát hiện vấn đề .”\n“ Hắn biết mình được sủng ái , cũng đều biết vì cái gì lão nhị , lão tam bọn hắn không dám cùng chính mình tranh .”\n“ Cũng tương tự biết đến , hắn gánh chịu lấy chúng ta đối với hắn mong đợi .”\n“ Nhưng cứ như vậy ...”\nMã hoàng hậu nói đến đây , khe khẽ lắc đầu .\nXuất thân nhà giàu Mã hoàng hậu , kỳ thực gặp qua xảy ra chuyện như vậy , chịu tải không được gia tộc đối với chính mình mong đợi , tự sát , điên mất , nàng cũng gặp qua .\n“ Ai ... Dạng này sao ?”\nChu Nguyên Chương trong lòng lúc này kỳ thật vẫn là có một chút may mắn .\nBởi vì hắn thực sự không tiếp thụ được , là chính mình bức tử chính mình Thái tử .\nMã hoàng hậu lúc này tựa hồ cũng phát giác Chu Nguyên Chương may mắn .\nNhưng nàng không nói gì thêm , bởi vì đây đều là nhân chi thường tình , rất bình thường .\nChờ màn trời giảng đến lúc Minh triều , tự nhiên hết thảy đều sẽ được phơi bày .\n...\nMinh triều .\nVĩnh Lạc bảy năm .\n“ Ai ...”\nChu Lệ nhìn xem trong cung điện , đứng tại xó xỉnh chỗ , thất thần lão nhị Chu Cao Hú , thở dài một hơi .\nTừ hắn cho lão nhị thẳng thắn hết thảy sau đó , Chu Cao Hú vẫn thất thần đứng ở nơi đó .\nCái này đã đứng có mấy cái canh giờ .\n“ Hoàng hậu a , nếu là ngươi còn tại , liền tốt .”\nChu Lệ lúc này vô cùng nhớ tới Từ hoàng hậu .\nChỉ cần Từ hoàng hậu tại , hắn trên cơ bản đều không cần lo lắng chuyện như vậy .\nTừ hoàng hậu tất nhiên là sẽ trấn an hảo Chu Cao Hú .\nNhưng tại Vĩnh Lạc năm thứ năm tháng bảy , Từ hoàng hậu liền bởi vậy chết bệnh ở Tây Cung .\n“ Phụ thân ...”\nChu Cao Sí đi đến Chu Lệ bên cạnh , đồng dạng lo lắng nhìn xem lão nhị .\n“ Giao cho ngươi .”\nChu Lệ xoa trán một cái , hướng về phía Chu Cao Sí nói .\n“ A ?!”\nChu Cao Sí mộng bức nhìn xem Chu Lệ , chỉ chỉ chính mình .\n“ Phụ thân , ngươi cảm thấy lão nhị không biết đánh ta ? Phải biết , nếu như không phải là bởi vì ta tại , hắn nghĩ đều có thể thực hiện .”\nChu Lệ trầm mặc một hồi , nhìn xem Chu Cao Sí nói :\n“ Đừng quên mẫu thân ngươi , lúc lâm chung nói với ngươi lời nói .”\nLời này vừa ra , Chu Cao Sí lập tức liền yên tĩnh trở lại , mắt nhìn Chu Lệ , sau đó thở dài một hơi sau , yên lặng đi đến Chu Cao Hú bên cạnh .\n“ Lão nhị ...”\nChu Cao Sí đi đến Chu Cao Hú bên cạnh , khẽ gọi một tiếng .\nChu Cao Hú vẫn như cũ ở vào trạng thái thất thần , không để ý tới Chu Cao Sí .\nThấy thế , Chu Cao Sí trầm mặc một hồi , nhìn xem Chu Cao Hú ánh mắt , gằn từng chữ nói :\n“ Muốn đánh ta , ngươi có thể đánh ta .”\nNghe nói như thế , Chu Cao Hú tựa hồ cuối cùng hồi thần lại , thế nhưng chỉ là liếc mắt nhìn Chu Cao Sí .\n“ Chu Cao Hú ! Ngươi bây giờ dạng này , xứng đáng mẫu thân sao ?!!”\nChu Cao Sí đột nhiên lập tức liền bạo phát .\n“ Ta có lỗi với mẫu thân ?! Ta như thế nào có lỗi với mẫu thân ?”\nNghe được mẫu thân , Chu Cao Hú lập tức lấy lại tinh thần , một phát bắt được Chu Cao Sí quần áo .\n“ Mẫu thân nhường ngươi sống khỏe mạnh , không cần tranh ...”\nChu Cao Hú con ngươi co rụt lại , cắn răng nghiến lợi nhìn xem Chu Cao Sí nói :\n“ Ngươi nghe lén mẫu thân nói với ta lời nói ?”\nChu Cao Sí chỉ là khe khẽ lắc đầu , bình tĩnh nhìn hắn nói :\n“ Mẫu thân nói với ta , nàng cái gì đều nói cho ta biết , để cho ta nhất định thật tốt chiếu cố ngươi cùng lão tam .”\n“ Để cho ta nhất định không nên học trong lịch sử những cái kia Thái tử .”\n“ Đây là mẫu thân một lần duy nhất khẩn cầu ta ...”\nChu Cao Sí hốc mắt lập tức liền đỏ lên .\nHắn đã nghĩ tới mẫu thân lúc lâm chung không yên lòng Chu Cao Hú cùng Chu Cao Toại , sợ bọn họ hạ tràng , sẽ như trong lịch sử những hoàng tử kia kết quả giống nhau .\nCho nên khẩn cầu chính mình , nhất định muốn chiếu cố tốt hai người bọn họ .\nTại lâm chung , lấy thân phận của mẫu thân , khẩn cầu nhi tử .\n“ Mẫu thân ...”\nChu Cao Hú thân thể lập tức xụi lơ trên mặt đất .\nXa xa Chu Lệ thấy thế , thở dài một hơi , nhưng nội tâm cũng cuối cùng buông lỏng xuống .\nHắn rốt cuộc không cần lo lắng huynh đệ tương tàn tình huống sẽ xuất hiện trước mặt mình .\n......', 'output\\mp3\\Màn Trời Quyền Lực Diễn Biến Cùng Truyền Thừa\\0021_Thứ 21 chương Mỹ thực lịch sử Nạn đói lịch sử....mp3', '2026-09-01T12:10:08.944250+00:00', 'completed', 'completed', 12490, 12490),
	(27, 7, '7642703883378115096', 22, 'Thứ 22 chương Tổ địa tình tiết', 'Thứ chương Tổ địa tình tiết\nHiện đại thời không .\nBan đêm .\nNằm ở trên giường Doanh Chính như thế nào cũng ngủ không được lấy , ban ngày từng màn một mực hiện lên ở trong đầu của mình .\nTrong công viên những cái kia tóc bạc hoa râm lão nhân ...\nTiểu học cửa ra vào không buồn không lo hài tử ...\nTừng cảnh tượng ấy thời khắc đánh thẳng vào Doanh Chính nhận thức .\n“ Ai ...”\nDoanh Chính chậm rãi rời giường , sau đó đi đến bên cửa sổ , nhìn về phía ngoài cửa sổ , cái này xem xét , lại để cho hắn sửng sốt .\n“ Đây là ban đêm ?”\nNgoài cửa sổ đèn đuốc sáng trưng , Doanh Chính hướng về đi , chỉ phát hiện nơi xa mới có bôi đen ám .\n‘ Tần triều vì sao lại diệt vong ? Bởi vì không có căn cơ .’\nLý Ân Phàm mà nói , lại hiện lên ở Doanh Chính não hải .\n“ Căn cơ sao ?”\nDoanh Chính có chút hoảng hốt , hắn giờ phút này nhìn lại Tần quốc lịch sử , mới chợt phát hiện , Tần triều thật không có căn cơ .\nHắn vẫn cho là này căn cơ là lão Tần người .\nCó thể , lão Tần người , Tần quốc liền bảo vệ rất tốt sao ?\nDoanh Chính biết , Lý Ân Phàm còn có rất nhiều lời không nói , rất nhiều chuyện chính hắn đều liên tưởng đến .\nLão Tần người , tại thống nhất Lục quốc trong chuyện này , ăn vào tiền lãi sao ?\nKhông có !\nChỉ có cực ít người , hoặc có lẽ là người của quân đội , mới ăn vào tiền lãi .\nHơn nữa ...\nDoanh Chính hồi tưởng lại thương ưởng biến pháp sau lịch sử , mới bỗng nhiên phát hiện , đi đến trước mặt mình , còn có bao nhiêu lão Tần người ?\nTừ nuôi thả ngựa thời đại , đi tới lão Tần người ...\n“ Ai ...”\nThùng thùng !\nÂn ?\n“ Tiến !”\nDoanh Chính hơi nghi hoặc một chút , thời gian này , còn người nào ra tìm chính mình ?\nMông Điềm vẫn là Lý Ân Phàm ?\n“ Bệ hạ !”\nMông Điềm cung kính đi vào gian phòng , hướng Doanh Chính thi lễ một cái .\n“ Mông Điềm ?”\n“ Bệ hạ , ngươi còn chưa ngủ ?”\nMông Điềm chậm rãi đi đến Doanh Chính bên cạnh , tiếp tục nhẹ nói :\n“ Ta ở bên cạnh gian phòng , nghe được có chút vang động , tìm tưởng nhớ lấy tới xem một chút .”\n“ Ân ...”\nDoanh Chính chậm rãi gật đầu , sau đó lại nhìn về phía ngoài cửa sổ .\nBầu không khí cứ như vậy trầm mặc một hồi , Mông Điềm bỗng nhiên mở miệng nói ra :\n“ Bệ hạ ...”\nDoanh Chính quay đầu nhìn về phía Mông Điềm , chờ đợi hắn lời kế tiếp .\n“ Có mấy lời có lẽ không nên ta nói , nhưng bây giờ , lại nhất thiết phải từ ta nói ra .”\nDoanh Chính lẳng lặng nhìn Mông Điềm .\n“ Bệ hạ , chúng ta Mông gia , là tại tổ phụ Mông Ngao thời điểm , mới từ Tề quốc đi nương nhờ Tần quốc ...”\nMông Điềm nói đến đây , liền không có tiếp tục nói nữa .\nVì cái gì Mông Điềm biết nói lời này ? Bởi vì tại Lý Ân Phàm hôm nay nói nhiều như vậy sau đó , hắn mới phát hiện chuyện này triều đình có bao nhiêu cực độ không công bằng .\nNhìn như đã tạo thành văn võ đối lập cách cục .\nNhưng , cấp độ sâu , lại cực độ không hợp lý !\nĐông đông đông !\n“ Tiến !”\nDoanh Chính cùng Mông Điềm quay đầu nhìn về phía cửa phòng vị trí .\n“ Ta liền đoán được các ngươi còn chưa ngủ , Thủy Hoàng , Mông tướng quân !”\nLý Ân Phàm giương lên trong tay đồ nướng .\n“ Đi ra ăn vặt a .”\nLúc này thời gian đã tiếp cận 12h .\nLiền thời gian này , bình thường Lý Ân Phàm còn tại trên mạng cùng người khác cùng một chỗ nói chuyện phiếm .\nSuy nghĩ Thủy Hoàng Doanh Chính cùng Mông Điềm lần thứ nhất đến hiện đại , nhất định sẽ ngủ không được , cho nên hắn mới chạy đến dưới lầu mua thật nhiều đồ nướng .\n“ Thủy Hoàng , Mông tướng quân , ngủ không được a ?”\nTrong phòng khách , Lý Ân Phàm cho hai người rót một chén đồ uống , sau đó vừa cười vừa nói .\n“ Ân , đang suy nghĩ một ít chuyện .”\nDoanh Chính gật đầu một cái , cầm ly lên , uống một ngụm Cocacola .\n“ Ngượng ngùng , Mông tướng quân , lời mới vừa nói , ta kỳ thực mơ hồ nghe được một chút .”\nPhòng này không quá cách âm , Lý Ân Phàm mới vừa vào cửa , liền nghe được Mông Điềm nói lời .\n“ Vô sự , tiên sinh , không có gì không nhưng đối với nhân ngôn .”\nMông Điềm không thèm để ý chút nào , nói những lời này thời điểm , hắn liền có loại tâm lý này chuẩn bị .\n“ Thủy Hoàng ...”\nLý Ân Phàm thở dài một hơi , nhìn xem Doanh Chính nói :\n“ Ta biết ngươi đang suy nghĩ gì , không chỉ là nuôi thả ngựa thời đại đi tới lão Tần người .”\n“ Ngươi suy nghĩ cẩn thận nghĩ , liền lão Tần người sang tộc , sau khi Tần triều thành lập , còn thừa lại bao nhiêu ?”\n“ Trắng ...”\nLý Ân Phàm nói chỉ là một chữ , Doanh Chính lập tức trầm mặc lại .\nBên cạnh Mông Điềm lặng yên không tiếng động thở dài một hơi .\nHắn đương nhiên biết Lý Ân Phàm nói tới ai , Bạch Khởi , hoặc có lẽ là Công Tôn lên .\nNhưng nói chỉ là Bạch Khởi sao ? Không phải , nói là toàn bộ lão Tần người sang tộc .\n“ Phấn lục thế Dư Liệt , chấn thượng sách tại ngự vũ nội , nuốt hai tuần mà chết chư hầu .”\n“ Đây là Tây Hán thời kì Giả Nghị 《 Quá Tần Luận 》 bên trong một câu nói .”\n“ Nói rất hay , nhưng lão Tần người sang tộc , còn có lão Tần người , bọn họ đâu ?”\nNói đến đây , Lý Ân Phàm áy náy liếc mắt nhìn Mông Điềm , sau đó lại nói :\n“ Trên triều đình , văn võ đại thần , có bao nhiêu vẫn là lúc trước lão Tần người ?”\n“ Kỳ thực Tần triều những năm cuối , ta cảm thấy tối không thể tưởng tượng nổi chính là cái gì , ngươi biết không ? Thủy Hoàng .”\nLý Ân Phàm nhìn về phía Doanh Chính , Doanh Chính nhưng là lẳng lặng nghe .\n“ Tần quốc phấn lục thế ngoài liệt , thống nhất thiên hạ , nhưng chỉ vẻn vẹn tại mười lăm năm sau đó , liền ầm vang sụp đổ .”\n“ Sụp đổ sau đó , ngay cả mình tổ địa , vậy mà cũng thủ không được .”\n“ Theo lý mà nói , liền vẻn vẹn đi qua mười lăm năm !”\n“ Tần triều vậy mà không có người suy nghĩ lui về Tần quốc tại chỗ , ngồi xem thiên hạ đại loạn sau đó , một lần nữa vừa thống nhất thiên .”\n“ Mười lăm năm ...”\n“ Một thế hệ cũng không có ...”\n“ Bọn hắn thật sự quên rồi sao ?”\n“ Vẫn là nói , bọn hắn không muốn lại trở lại quá khứ ?”\nCái này cũng là Lý Ân Phàm cảm thấy tối không thể tưởng tượng nổi một điểm .\nTần quốc lợi hại sao ? Đương nhiên lợi hại ! Thời gian ngắn ngủi liền thống nhất thiên hạ .\nCó thể nói Tần quốc thật sự lợi hại ? Tần triều sụp đổ sau đó , vậy mà không có người suy nghĩ lui giữ ải Hàm Cốc , một lần nữa trở lại Đại Tần tổ địa .\nCho nên rất rõ ràng liền có thể nhìn ra , Tần quốc cùng Tần triều ở giữa , có bao nhiêu cắt đứt .\nVẻn vẹn mười lăm năm , liền để bọn hắn quên ?\nMột thế hệ chưa từng qua được , làm sao có thể quên ?\n“ Hoặc có lẽ là , nhớ lại đến quá khứ người , lui giữ ải Hàm Cốc người , bọn hắn không có quyền lực ...”\n“ Hay là , bọn hắn căn bản quyết định không được !”\nCó người nói Mông Điềm Mông gia , Vương Tiễn Vương gia , Lý Tư Lý gia , bọn hắn không tính là lão Tần người sao ?\nĐương nhiên không tính !\nBọn họ đều là thương ưởng biến pháp sau đó , mới đi đến Tần quốc .\nNói không dễ nghe một điểm , bọn hắn , thật sự nguyện ý một lần nữa lại đánh một lần thiên hạ ?\nĐây chính là “ Tổ địa ” Tình tiết !\nRất nhiều người có thể không hiểu vì sao lại có loại tình tiết này .\nKỳ thực loại tình tiết này là phi thường phổ biến .\nTừ bóng đá góc độ , liền có thể rất đơn giản lý giải .\nThanh huấn tình tiết , chính là như thế !\nCòn có , vì cái gì nước ngoài rất nhiều fan bóng đá , bọn hắn thề sống chết thủ vệ bọn hắn địa phương đội bóng ?\nTừ xuất sinh đến chết , dù là đội bóng một mực tại tầng dưới chót thi đấu vòng tròn hòa với , cũng yêu thích lấy đội bóng ?\nĐây chính là “ Tổ địa tình tiết ”.\nHiện đại kỳ thực có rất nhiều ví dụ như vậy , tỉ như nói lão Mỹ hồng cổ .\nBọn hắn kỳ thực chính là lão Mỹ “ Lão Tần người ”.\nDù là lão Mỹ thật sự hủy diệt , những thứ này hồng cổ , vẫn là lão Mỹ người ủng hộ , chân chính phục quốc giả .\nTừ hướng này đi xem , có phải hay không liền phát hiện Tần triều diệt vong cực lớn không hợp lý ?\nTần quốc lão Tần người đâu ?\nKhông biết !\nNhưng , Tần triều diệt vong sau đó , không có người suy nghĩ phục quốc , lại là sự thật .\nLý Tư Lý gia , mặc dù bởi vì Lý Tư mưu phản tội danh tan vỡ .\nNhưng nếu là Lý gia vẫn như cũ vẫn tồn tại , Lý gia sẽ nghĩ đến phục quốc sao ?\nKhông biết , nhưng Vương gia ví dụ , nhưng cũng là sự thật !\nKỳ thực phương diện này là rất dễ dàng lý giải , cũng là rất dễ dàng nghĩ thông suốt .\nLão Mỹ nếu quả thật tan vỡ , những cái kia nhà tư bản , bọn hắn sẽ nghĩ đến phục quốc sao ?\nNghĩ thông suốt điểm này , liền có thể rất dễ dàng nghĩ thông suốt kẻ ngoại lai , cùng người địa phương , đến cùng có cái gì cụ thể khác nhau .\n“ Ai ...”\nMông Điềm kỳ thực cũng là ý tứ này .\nHắn là không muốn nhất Tần triều diệt vong , cho nên dù là nói toạc chính mình là “ Kẻ ngoại lai ”, hắn cũng thật sự một lòng hệ tại Tần triều .\nNhưng hắn không thể cam đoan chính mình Mông gia , cũng là nghĩ như vậy .\n“ Ý của các ngươi , ta đã biết .”\nDoanh Chính khẽ gật đầu một cái , trên gương mặt bình tĩnh không có bất kỳ cái gì gợn sóng .\n...\nTần triều vấn đề phức tạp sao ? Đúng là phức tạp .\nNhưng thật sự phức tạp sao ? Kỳ thực cũng không phức tạp !\nCó một câu nói , kỳ thực nói rất hay , ngươi đem dân chúng để ở trong lòng , dân chúng liền sẽ đem ngươi giơ lên cao cao .\nCho nên , hiện đại rất nhiều người cho Tần triều diệt vong tìm đủ loại lý do , kỳ thực đều quá hợp với mặt ngoài .\nNếu như nói Tần triều là đã thành lập mấy trăm năm Đại Nhất Thống Vương Triều , vậy nó những năm cuối , chính xác có thể tìm đủ loại lý do .\nNhưng Tần triều , vẻn vẹn chỉ là thành lập mười lăm năm !\nMười lăm năm , một thế hệ đều không đi đến !\nNhưng vì cái gì Tần triều liền lập tức đến những năm cuối ?\nTại Lý Ân Phàm xem ra , đạo lý kỳ thực rất đơn giản , tầng dưới chót vô số người , cảm thấy bọn hắn so thời kỳ chiến quốc qua còn không hảo .\nBọn hắn tình nguyện trở lại hỗn loạn thời kỳ chiến quốc , cũng không muốn tại Tần triều phía dưới tiếp tục sinh sống .\nĐây mới là Lý Ân Phàm cảm thấy Tần triều diệt vong nguyên nhân chủ yếu nhất .\nGiống như là vậy mà không có người suy nghĩ Tần triều một lần nữa trở lại Tần quốc , không có người nguyện ý cho nó phục quốc .\nĐây rốt cuộc là Tần Nhị Thế Hồ Hợi làm hết thảy ? Còn là bởi vì các triều đại đổi thay Tần Vương , bọn hắn rét lạnh chân chính lão Tần người tâm ?\nĐáp án kỳ thực là không cần nói cũng biết .\n......', 'output\\mp3\\Màn Trời Quyền Lực Diễn Biến Cùng Truyền Thừa\\0022_Thứ 22 chương Tổ địa tình tiết.mp3', '2026-09-01T12:10:13.979618+00:00', 'completed', 'completed', 9901, 9901),
	(28, 7, '7642704082301370904', 23, 'Thứ 23 chương Thời đại trước cùng thời đại mới', 'Thứ chương Thời đại trước cùng thời đại mới\nKỳ thực nhìn chung trong lịch sử phía dưới năm ngàn năm , tất cả đại nhất thống Trường Mệnh Vương Triều , bọn hắn đều có thuộc về mình căn cơ .\nDạng này căn cơ , phía trên hoàng đế , chỉ cần là người thông minh , mặc kệ là đổi ai , bọn họ đều là sẽ không động .\nMà động căn cơ ? Trên cơ bản liền có thể rất rõ ràng nhìn thấy vương triều bắt đầu đi về phía hỗn loạn .\nHán triều căn cơ là ai ? Bái huyện người của tập đoàn .\nĐông Hán căn cơ là ai ? Địa chủ hào cường , thế gia đại tộc người .\nTào Ngụy căn cơ là ai ? Dĩnh Xuyên thế gia ? Hà Bắc thế gia ? Kỳ thực đều không phải là , là Tào gia cùng với Hạ Hầu gia nhân .\nTào Ngụy về sau bước vào như vậy hoàn cảnh , cũng là bởi vì bọn hắn đối đãi Tào gia cùng với Hạ Hầu gia rơi xuống hạ tràng .\nTriều Tấn ? Triều Tấn kỳ thực dưới tay không có người ! Bọn hắn suy nghĩ tôn thất có thể trở thành căn cơ của bọn họ , nhưng triều Tấn hạ tràng đã nói rõ hết thảy .\nỞ trong đó cực kỳ có đại biểu tính chất , kỳ thực là Tống triều cùng Minh triều .\nTống triều là như thế vương triều , vì cái gì còn có thể tồn tại mấy trăm năm ? Hơn nữa tính bền dẻo là như vậy cường đại ?\nBởi vì cùng sĩ phu cộng trị thiên hạ .\nCái kia Minh triều đâu ? Tiền kỳ là Hoài Tây tập đoàn , nhưng đến trung kỳ bắt đầu , liền có thể rất rõ ràng nhìn ra vấn đề .\nĐến cuối cùng ?\nMinh triều cùng Đường triều , là hai cái rất rõ ràng liền có thể nhìn ra , bọn chúng căn cơ xảy ra chuyển biến , tiếp đó từng bước bắt đầu đi xuống dốc .\nĐường triều là kịch liệt , căn cơ vừa phát sinh biến hóa , lập tức liền xuất hiện vấn đề .\nMà Minh triều , nhưng là chậm rãi , nếu như không kỹ lưỡng , có thể đến cuối cùng đều không nhìn ra .\n...\nHiện đại .\n“ Tiên sinh , vì cái gì cảm giác chúng ta Tần triều cùng những thứ khác vương triều cũng không giống nhau ?”\nMông Điềm khi nghe đến Lý Ân Phàm giảng thuật nhiều như vậy sau đó , lập tức đưa ra nghi hoặc .\nMông Điềm có chút nói không rõ ràng bên trong quan hệ , nhưng hắn nhìn sách sử , vẫn cảm thấy bên trong có chỗ nào không đúng .\nNhưng Lý Ân Phàm nghe xong , liền biết Mông Điềm đến cùng đang nói cái gì , sau đó liền giải thích nói :\n“ Không chỉ là các ngươi cùng với những cái khác vương triều không giống nhau , Tùy triều cũng cùng khác vương triều không giống nhau .”\n“ Tại sao lại như thế ?”\n“ Bởi vì các ngươi Tần quốc cùng Tùy triều , sớm tại thống nhất phía trước , đã lập quốc mấy trăm năm !”\nLý Ân Phàm cầm ly lên , uống một ngụm Cocacola sau đó , mới dùng chậm rãi nói :\n“ Cũng không chỉ là các ngươi không để ý đến quan hệ trong này , hiện đại cũng có tuyệt đại đa số người không để ý đến .”\n“ Giống như là Tần quốc , đối với Tần quốc lão Tần người tới nói , các ngươi là tới đi nương nhờ Tần quốc .”\n“ Chúng ta bản thân Tần quốc cường đại , các ngươi mới đến đi nương nhờ chúng ta !”\n“ Mà khác vương triều đâu ? Tỉ như nói Hán triều cùng với Đường triều còn có Minh triều ?”\n“ Tại thống nhất phía trước , bọn hắn một mực tại đánh thiên hạ , ở trong quá trình này , bất kể là ai tới , cho dù là người đến sau , bọn hắn cũng có một phần tòng long chi công .”\n“ Bên trong nội bộ người , cũng đều sẽ cảm thấy , chúng ta là chân chân chính chính đánh toàn bộ thiên hạ , không có người nào “ Đi nương nhờ ” Ai thuyết pháp .”\n“ Lập không có lập quốc , khác nhau là rất lớn , hơn nữa là phi thường lớn !”\nLý Ân Phàm dừng một chút , chuẩn bị thay cái thuyết pháp .\n“ Vẫn là như vậy nói đi , Mông tướng quân , nếu ngươi là nuôi thả ngựa thời đại liền lưu lại lão Tần người , đi theo Tần quốc đánh rớt tổ địa , sau đó thì sao ? Quật khởi qua , cũng không rơi qua .”\n“ Đến thương ưởng biến pháp , các ngươi mặc dù phản đối , nhưng mà cũng chấp nhận .”\n“ Về sau , địa vị của các ngươi lại vừa giảm lại rơi nữa , ngoại lai Mông gia , Vương gia , Lý gia các loại , bọn hắn đều đi tới trên đầu của ngươi .”\n“ Nếu như là ngươi , ngươi sẽ ra sao ?!”\n“ Đây chính là về sau , Chu Nguyên Chương đánh thiên hạ thời điểm , cao tường , Quảng Tích Lương , hoãn xưng vương bên trong hoãn xưng vương , một nguyên nhân khác !”\n“ Đương lập quốc , tất cả cũng sẽ không tiếp tục một dạng , giống như là tại lúc đó , đạo lý cũng là giống nhau .”\n“ Bằng không thì các ngươi làm sao lại mắng người nước Sở , Triệu quốc người , người nước Tề đâu ?”\n“ Bọn hắn cũng vì cái gì sẽ mắng Tần quốc người đâu ?”\n“ Đại sự quốc gia , ở chỗ tế tự cùng chiến tranh .”\n“ Tự vì sao lại tại nhung phía trước ? Thì ra là vì nguyên nhân này , đạo lý này .”\n“ Đương lập quốc , tế tự sau đó , không chỉ là phía trên , từ trên xuống dưới , từ cao tầng đến cùng tầng , tất cả cũng không giống nhau .”\n“ Tại sau cái này ? Mặc kệ các ngươi cố gắng thế nào , các ngươi theo bọn hắn nghĩ , cũng chỉ là kẻ ngoại lai !”\n“ Là bởi vì chúng ta Tần quốc cường đại , mới chạy tới kẻ ngoại lai !”\nLý Ân Phàm nói đến đây , nhìn xem Doanh Chính , chậm rãi nói :\n“ Mà cũng chính là bởi vì dạng này , tại ta suy đoán xem ra , đây chính là vì cái gì không có người phục quốc Tần quốc một cái nguyên nhân .”\n“ Coi như lão Tần người thật sự nghĩ tới phục quốc ? nhưng phục quốc sau đó đâu ? Người ngoại lai , có phải hay không còn muốn leo đến trên đầu của chúng ta ?”\n“ Chúng ta tổ tiên đi theo Tần Vương thành lập Tần quốc , mấy trăm năm sau đó , rơi vào như vậy hạ tràng .”\n“ Ai biết về sau Tần Vương , vẫn sẽ hay không tiếp tục chèn ép chúng ta ?”\n“ Cho nên , vì cái gì không một lần nữa tìm kiếm một phần tòng long chi công đâu ? Tất cả mọi người đều là khởi đầu mới .”\nMà nói đến ở đây , có thể có người không nghĩ tới , nhưng có người cũng chắc chắn nghĩ tới .\nĐây chính là vì cái gì Lưu Bang sẽ thành công một nguyên nhân quan trọng .\nTại toàn bộ cuối Tần , có vô số người , đánh vô số khẩu hiệu .\nNhưng trên cơ bản cũng là đánh “ Phục quốc ”, phục Sở quốc , hay là phục những thứ khác cái gì quốc .\nLưu Bang , hắn về sau từ đó đến giờ không có đánh qua khẩu hiệu như vậy .\nPhục Sở quốc ? Cái này tại trong lúc vô hình , liền kẹt chết vô số người .\nGiống như là Hàn Tín , Hàn Tín vì cái gì ngay từ đầu , chạy tới Hạng Vũ nơi đó ?\nBởi vì Hàn Tín xuất sinh Sở quốc Đông Hải quận Hoài Âm huyện hắn tự nhận là chính mình là người nước Sở , cho nên mới chạy tới Hạng Vũ nơi đó .\nVề sau vì sao lại chạy tới Lưu Bang nơi đó ? Bởi vì Lưu Bang thật là người nào đều tiếp nhận .\nKhông quan tâm trước ngươi đến cùng là người nước nào !\nCho dù là Lưu Bang , sớm nhất thời điểm , hắn bởi vì cũng là người nước Sở , cho nên chạy tới đầu phục Hạng Vũ .\nMà tại ở trong đó , những cái được gọi là đánh phục quốc khẩu hiệu quý tộc , bọn hắn trọng dụng là người nào ?\nGiống như là Hạng Vũ , dưới tay hắn đại tướng .\nLong Thả , trước kia lệ thuộc sở đem Hạng Lương , tại trong Sở quân đảm nhiệm Tư Mã .\nQuý Bố , Sở Địa Nhân .\nChuông cách mạt , Đông Hải quận Cù huyện y lư dân làng , Sở Địa Nhân .\nAnh Bố , sáu huyện người , sáu huyện là Tần Thuỷ Hoàng hai mươi bốn năm ( Phía trước năm ) diệt Sở sau thiết trí huyện cấp khu hành chính hoạch , lệ thuộc Cửu Giang quận .\nĐến nỗi Hạng Lương bọn người cũng không cần nói , nhìn tên liền biết .\nCho nên , lần này biết vì cái gì Lưu Bang sẽ thành công đi ?\nĐây chính là một bộ phận rất lớn nguyên nhân !\nCái này cũng là vì cái gì về sau rất nhiều tướng lĩnh , sẽ chuyện đương nhiên phản loạn , đi nương nhờ Lưu Bang nguyên nhân .\nKhi ngươi đánh cái gì cờ hiệu , liền đã biểu lộ lập trường của ngươi .\nRất nhiều người cho rằng , Hồng Môn yến thời điểm , Hạng Vũ nếu là giết Lưu Bang , Lưu Bang nhất định sẽ thất bại .\nQuả thật là như thế , Lưu Bang chính xác sẽ thất bại .\nNhưng Hạng Vũ đâu ? Cuối cùng vẫn như cũ sẽ thất bại .\nHạng Vũ cũng đã phân đất phong hầu mười tám chư hầu , cuối cùng đều thất bại .\nMà Tần quốc thống nhất thiên hạ chuyện , liền phát sinh ở không xa phía trước .\nNhững người khác , liền không có người suy nghĩ thống nhất thiên hạ ?\nLưu Bang chết , Lưu Bang dưới tay nhiều người như vậy , đều là không chết !\nGiống như là Hàn Tín , Lưu Bang chết , hắn còn đi đầu quân Hạng Vũ ?\nTrần Bình cùng Trương Lương bọn người đâu ? Thì càng không cần nói .\nĐã có sự tình , sau nhất định lại có , khi Hạng Vũ vẫn như cũ ôm phân đất phong hầu ý nghĩ , cái kia cuối cùng ngăn không được thời đại dòng lũ .\nMà từ Tần quốc thống nhất thiên hạ sau đó , dòng lũ liền đã dâng lên .\nTần Hán lúc , tuy nói là Hạng Vũ cùng Lưu Bang đối kháng .\nNhưng kỳ thực , là thời đại trước cùng thời đại mới đối kháng .\nThời đại trước có lẽ sẽ chiếm giữ nhất định thượng phong , nhưng thời đại mới , lại cuối cùng sẽ đến .\nĐúng vậy , thời đại mới , cuối cùng sẽ đến !\n...', 'output\\mp3\\Màn Trời Quyền Lực Diễn Biến Cùng Truyền Thừa\\0023_Thứ 23 chương Thời đại trước cùng thời đại mới.mp3', '2026-09-01T12:10:20.349601+00:00', 'completed', 'completed', 8456, 8456),
	(29, 7, '7643078472054620696', 24, 'Thứ 24 chương Gián trục khách sách', 'Thứ chương Gián trục khách sách\nHiện đại thời không .\n“ Kỳ thực ta rất sớm đã phát giác vấn đề này .”\n“ Nhưng ở lúc đó , ta cũng chỉ là cho rằng đây là vấn đề nhỏ .”\nThủy Hoàng Doanh Chính bưng chén lên , hét lớn một ngụm Cocacola , chẹp chẹp miệng sau đó , tiếp tục nói :\n“ Thống nhất sau đó , ta càng cho rằng đây không phải vấn đề , cho nên cũng không có đi quan tâm .”\nLý Ân Phàm khẽ gật đầu một cái , đáp lại nói :\n“ Kỳ thực tại bình thường , vấn đề như vậy , đúng là vấn đề nhỏ .”\n“ Coi như không có xảy ra chuyện gì , tất cả mọi người , cho dù là chính mình người , cũng nhìn không ra bọn hắn đến cùng có ích lợi gì .”\n“ Nhưng đợi đến phá diệt thời điểm , mới phát hiện , không có bọn hắn , vậy thì thật không có lại tới một lần nữa tư bản .”\nNói đến đây , Lý Ân Phàm tử suy nghĩ tỉ mỉ thi một chút sau , nhìn xem Doanh Chính hỏi :\n“ Lý Tư 《 Gián Trục Khách Thư 》 phải không ?”\nNghe được 《 Gián Trục Khách Thư 》 bốn chữ này , Doanh Chính khẽ thở dài một tiếng , sau đó gật đầu một cái nói :\n“ Đúng vậy , 《 Gián Trục Khách Thư 》.”\nLý Ân Phàm để ly xuống , dựa vào ghế , cẩn thận nhớ lại một chút 《 Gián Trục Khách Thư 》 nội dung bên trong .\n“ Đây quả thật là không thể nói Lý Tư là sai , nhưng cái này cũng vẻn vẹn chỉ là từ lập trường của hắn đi viết .”\n《 Gián Trục Khách Thư 》 cụ thể viết cái gì ?\nĐơn giản tới nói , chính là Thủy Hoàng Doanh Chính thượng vị sau đó , cho rằng ngoại lai khách khanh quá nhiều , tất cả muốn khu trục một chút .\nMà tại ở trong đó , liền có Lý Tư .\nCho nên , Lý Tư liền viết 《 Gián Trục Khách Thư 》 cho Thủy Hoàng Doanh Chính .\nNội dung bên trong , đại khái chính là :\nĐầu tiên là cho rằng trục khách không đúng .\nNhưng vì cái gì không đúng ? Liền đem từ Tần Mục công thời kì bắt đầu , Tần quốc trở nên mạnh mẽ cùng khách bên ngoài khanh sâu đậm khóa lại lại với nhau .\nLúc trước Mục Công sưu tầm hiền sĩ , phía tây từ Tây Nhung lấy được từ còn lại , phía đông từ uyển mà lấy được Bách Lý Hề , từ Tống quốc nghênh đón kiển thúc , từ Tấn quốc phải đến phi báo , Công Tôn Chi .\nCái này năm vị nhân vật , không sinh ra tại Tần quốc , nhưng Mục Công trọng dụng bọn hắn , gồm thâu hai mươi cái các nước chư hầu , thế là xưng bá Tây Nhung .\nTiếp đó , chính là thương ưởng biến pháp , ở trong đó , trọng yếu chính là Vệ Ưởng .\nSau đó đâu ? Tần Huệ Vương trọng dụng Trương Nghi , chiêu vương nhận được Phạm Sư .\n《 Gián Trục Khách Thư 》 bên trong liền tổng kết , bốn vị này quốc quân , cũng là dựa vào khách khanh công lao .\nCho nên , khách khanh có cái gì có lỗi với Tần quốc đây này ? Giả sử bốn vị quốc quân cự tuyệt khách khanh mà không tiếp nhận , xa lánh hiền sĩ mà không trọng dụng , này lại làm cho Tần quốc không có giàu có chi thực cùng cường đại tên .\n“ Nói tóm lại , kỳ thực Lý Tư nói không có vấn đề , nhưng có một cái tiền đề , đó chính là đứng tại Lý Tư lập trường , cái này nói đúng là không có vấn đề .”\nLý Ân Phàm nói đến đây , quay đầu nhìn về phía Mông Điềm , nhẹ giọng hỏi :\n“ Mông tướng quân , nếu , ngươi là lão Tần người , ngươi thấy 《 Gián Trục Khách Thư 》 sẽ ra sao ?”\nMông Điềm nghe được vấn đề này , trầm tư một hồi , quay đầu nhìn một chút Doanh Chính sau nhẹ nói :\n“ Sẽ hận , biết phẫn nộ ...”\n“ Nếu như Tần quốc giàu có cùng cường đại , đều dựa vào chính là khách khanh , vậy chúng ta lão Tần người tính là gì ?”\nLý Ân Phàm khẽ gật đầu một cái , sau đó nhìn về phía Thủy Hoàng Doanh Chính nói :\n“ Đây chính là không thể điều hòa một điểm ...”\n“ Bạch Khởi , Ti Mã Thác vân vân người , gia tộc của bọn hắn , lại sẽ ra sao ?”\nNói đến đây , Lý Ân Phàm thở dài một hơi sau , nhẹ giọng tiếp tục nói :\n“ Đây chính là ta vì sao lại nói , Lý Tư 《 Gián Trục Khách Thư 》 từ lập trường của hắn , góc độ của hắn đi suy xét , cái này đều không có vấn đề .”\n“ Nhưng 《 Gián Trục Khách Thư 》 lại đem Tần quốc nội bộ mâu thuẫn , trọn vẹn lộ ra ngoài .”\n“ Tần quốc giàu có cùng cường đại , toàn bộ nhờ chính là bọn ngươi khách khanh ? Vậy chúng ta lão Tần người liền đáng đời ?”\n“ Vẫn là nói , chúng ta lão Tần người , liền nên làm bàn đạp ?”\n“ Mà Thủy Hoàng , ngươi tiếp nhận 《 Gián Trục Khách Thư 》, đáp án kia cũng rất đơn giản .”\n“ Từ lão Tần người cùng kẻ ngoại lai ở giữa , ngươi lựa chọn kẻ ngoại lai .”\nSau đó , Lý Ân Phàm nhìn xem Thủy Hoàng cùng Mông Điềm hai người , tiếp tục nhẹ nói :\n“ Mà ở trong đó tàn khốc nhất là cái gì ? Các ngươi biết không ?”\n“ Lý Tư , là không có vấn đề , bởi vì hắn là kẻ ngoại lai , lập trường của hắn , hắn nhìn vấn đề góc độ , cũng là người ngoại lai góc độ .”\n“ Thủy Hoàng ngươi đây ? Cũng là không có vấn đề , bởi vì ngươi nhìn vấn đề lập trường và góc độ , là cả Tần quốc .”\n“ Chỉ cần có thể cường đại toàn bộ Tần quốc , ngươi là không quan trọng có phải hay không người ngoại lai .”\n“ Lịch đại Tần Vương , cũng đều là hợp cách quân chủ , cho nên , bọn hắn nhìn vấn đề góc độ , cũng đều là như thế .”\n“ Mà lão Tần người đâu ? Bọn hắn cũng không có sai , bọn họ đứng tại lập trường của mình cùng góc độ , đi xem ngươi cùng người ngoại lai hành động , chuyện đương nhiên nản lòng thoái chí .”\n“ Tại ở trong đó , tất cả mọi người , cũng là không sai ...”\nĐây chính là chính trị !\nKhông có cái gọi là toàn bộ đều được lợi , chỉ có một phương bị hao tổn , một phương được lợi sự tình phát sinh !\nTất nhiên lựa chọn trong đó một phương , cái kia một phương khác , nhất định sẽ thiệt hại .\n“ Ai ...”\nThủy Hoàng Doanh Chính thở dài một tiếng .\nBên cạnh Mông Điềm cũng đồng dạng khẽ thở dài một tiếng .\n“ Cho nên đây chính là lúc đó Tần quốc trong chính trị tàn khốc thế cục .”\n“ Mặc dù Tần quốc toàn thân là tại phát triển không ngừng , nhưng Tần quốc căn cơ , lại tại lặng yên không tiếng động sụp đổ .”\n“《 Gián Trục Khách Thư 》 cái này phong dâng sớ tất nhiên có thể lưu truyền tới nay , cái kia không hề nghi ngờ , truyền bá nhất định sẽ rộng .”\n“ Lão Tần người , nản lòng thoái chí liền chuyện đương nhiên .”\nCái này cũng là lúc trước Lý Ân Phàm vì sao lại nói lập không có lập quốc khác nhau chỗ .\nChớ nói chi là , Tần quốc đã tồn tại mấy trăm năm .\nTại trong mấy trăm năm này , Tần quốc có bao nhiêu quý tộc ? Tần quốc lại có bao nhiêu như Bạch Khởi , Ti Mã Thác dạng này người ?\nVẫn là câu nói kia , gia tộc của bọn hắn nhìn thấy 《 Gián Trục Khách Thư 》 sẽ ra sao ?\nMà cái này , chính là lập trường khác biệt , nhìn vấn đề suy xét khác biệt .\nLập trường quyết định góc nhìn , góc nhìn ảnh hưởng tới kết luận\n......\nHán triều .\nNguyên thú 4 năm .\n“ Đây chính là hậu thế nhìn vấn đề phương pháp sao ?”\nLưu Triệt vuốt vuốt chòm râu , thần sắc nghiêm túc cầm bút lên , tại trên vải lụa viết xuống .\nĐây là hắn hôm nay nghe xong màn trời , cảm thấy có lợi nhất một điểm .\nLập trường khác biệt , nhìn thấy vấn đề suy xét khác biệt .\n“ Chính xác rất có đạo lý .”\n“ Giống như trẫm vừa đăng cơ thời điểm ...”\nLưu Triệt nhớ tới chính mình vừa đăng cơ thời điểm , khắp nơi chịu cản tay cục diện .\nTừ tình huống lúc đó đến xem , ai cũng không có vấn đề .\nThái hậu không có vấn đề , chính mình đâu ? Cũng là không có vấn đề .\nNhưng mâu thuẫn lại cũng không hoà giải .\nLưu Triệt lúc đó đã thân là Đế Vương , là không thể nào từ bỏ quyền hạn , ngồi xem ngoại thích thế lực diệu võ dương oai .\nMà lúc đó ngoại thích thế lực đâu ? Cũng không khả năng từ bỏ đã tới tay quyền hạn , trả lại cho Lưu Triệt .\nDù sao , muốn để người thả vứt bỏ tới tay quyền hạn ? Cái này không thua gì để cho mãnh hổ phun ra đến miệng con mồi , hoặc để cho người chết chìm buông ra duy nhất gỗ nổi .\n“ Cho nên , ngay lúc đó ngoại thích thế lực , chỉ có một cái hạ tràng ...”\n.....', 'output\\mp3\\Màn Trời Quyền Lực Diễn Biến Cùng Truyền Thừa\\0024_Thứ 24 chương Gián trục khách sách.mp3', '2026-09-01T12:10:27.185371+00:00', 'completed', 'completed', 7432, 7432),
	(30, 7, '7643078581869871640', 25, 'Thứ 25 chương Sáu quốc dư nghiệt? Không!', 'Thứ Chương Lục Quốc Dư Nghiệt ? Không !\nHiện đại thời không .\n“ Tiên sinh , liền không có biện pháp giải quyết sao ?”\nMông Điềm nhìn xem Lý Ân Phàm , trong lòng có chút khẩn cấp mà hỏi .\nLý Ân Phàm trầm tư một hồi sau , khe khẽ lắc đầu nói :\n“ Tại lúc đó , đây chính là thuộc về Bản Thổ phái cùng người ngoại lai mâu thuẫn .”\n“ Mâu thuẫn thứ này .”\n“ Có chút mâu thuẫn là có thể điều hòa , nhưng đại đa số mâu thuẫn , là vĩnh viễn không cách nào điều hòa .”\n“ Có thể điều hòa có cái nào ? Nhiều bắt nguồn từ lợi ích , câu thông hoặc nhận thức khác biệt .”\n“ Không thể điều hòa đây này ? Đề cập tới căn bản giá trị quan xung đột , nguyên tắc tính chất đối lập , kết cấu tính chất áp bách .”\nLý Ân Phàm nói đến đây , giải thích một chút ở trong đó khác nhau .\n“ Trong mắt của ta , quyền hạn thứ này , chính là căn bản không thể điều hòa một loại mâu thuẫn .”\n“ Rất nhiều người cho rằng , lúc đó Bản Thổ phái cùng kẻ ngoại lai , thuộc về lợi ích phương diện mâu thuẫn .”\n“ Nhưng kỳ thật là thuộc về quyền hạn phân phối mâu thuẫn .”\n“ Mâu thuẫn như vậy có thể hoà giải sao ? Vĩnh viễn không cách nào hoà giải !”\n“ Bởi vì không có ai sẽ ghét bỏ quyền lực của mình không đủ !”\n“ Dù là thật sự Bản Thổ phái chiếm cứ thượng phong , cũng chính là lão Tần người chiếm cứ thượng phong , bọn hắn sẽ dừng lại sao ?”\n“ Sẽ không , chính bọn hắn nội bộ quyền hạn đều không đủ phân , làm sao lại dừng lại đâu ?”\n“ Bọn hắn sẽ nhớ , vì cái gì không đem ở hạ phong kẻ ngoại lai , toàn bộ đuổi đi ra đâu ?”\n“ Toàn bộ Tần quốc quyền hạn , từ người chúng ta phân phối , không tốt sao ?”\n“ Cho nên , tại trong chính trị , không có cái gì tìm chỗ khoan dung mà độ lượng .”\n“ Đây là vĩnh viễn không thể nào !”\nTrong lịch sử , kỳ thực có rất nhiều ví dụ như vậy , cho là mình buông tha đối phương liền tốt .\nĐây chính là không thấy rõ ràng trong đó căn bản tính mâu thuẫn .\nCó chút mâu thuẫn , là vĩnh viễn không cách nào điều hòa !\n“ Mặc dù phía trước Tần quốc lịch đại quân chủ hòa hoãn loại mâu thuẫn này .”\n“ Tỉ như nói Tần Mục công thời kỳ Vệ Ưởng ...”\n“ Kết cục của hắn , chính là vì hòa hoãn lúc đó Tần quốc nội bộ mâu thuẫn , không có triệt để trở nên gay gắt .”\n“ Về sau Tần Vương , bọn hắn đều hiểu đạo lý này , cho nên cuối cùng sẽ hòa hoãn mâu thuẫn .”\n“ Cũng chính là bản thổ cùng người ngoại lai mâu thuẫn .”\n“ Nhưng lúc đó có thể hòa hoãn là bởi vì cái gì ? Là bởi vì thống nhất thiên hạ mục tiêu ở nơi đó .”\n“ Bản Thổ phái có thể thỏa hiệp , cũng là bởi vì cái này !”\n“ Bọn hắn không ngốc , bọn hắn có thể nhìn thấy bánh gatô phát triển an toàn sau đó , mình có thể phân chỗ tốt .”\n“ Có thể thống nhất sau đó đâu ? Mâu thuẫn còn có thể hoà giải sao ?”\n“ Trước đây Bản Thổ phái , còn cam tâm bị áp chế sao ?”\n“ Bọn hắn thật sự cam tâm bị áp chế ? Vẫn là nói đã nản lòng thoái chí , thờ ơ lạnh nhạt ?”\nCam tâm bị áp chế ? Không , là bởi vì tâm ý nguội lạnh .\nMông Điềm rất dễ dàng phải ra cái kết luận này .\nNếu như là chính mình , nhìn xem trước đây Tần Vương Doanh Chính làm hết thảy , hơn nữa còn có sau đó thế cục , đều biết nản lòng thoái chí .\nChờ đã !\nMông Điềm lúc này nội tâm bỗng nhiên toát ra một cái vô cùng ý tưởng đáng sợ .\nCái này một số người , bọn hắn thật sự tâm ý nguội lạnh sao ?\nMông Điềm tựa hồ nghĩ tới điều gì , kinh hãi ngẩng đầu , nhìn xem Lý Ân Phàm .\n“ Xem ra ngươi nghĩ ra , Mông tướng quân .”\nLý Ân Phàm mặt mỉm cười nhìn xem Mông Điềm .\nLý Ân Phàm vô cùng rõ ràng , lúc này Mông Điềm đến cùng nghĩ tới điều gì , bởi vì bản thân cái này chính là hắn dẫn dắt kết quả .\n“ Rất nhiều người cho là , Tần quốc thống nhất , thiết lập Tần triều sau đó , tai hoạ ngầm chính là Lục quốc Dư Nghiệt ...”\nNói đến đây , Lý Ân Phàm cười khẽ một tiếng sau , chậm rãi nói :\n“ Trong mắt của ta , ở trong đó kỳ thực có một chút sai lầm , không phải Lục quốc Dư Nghiệt , là Thất quốc Dư Nghiệt !”\n“ Trong đó , còn có Tần quốc Dư Nghiệt !”\n“ Từ lập trường của bọn hắn cùng góc nhìn đi xem , bọn hắn thật sự cam tâm , thắng lợi trái cây bị cướp ?”\nLời này vừa ra , bầu không khí tựa hồ lâm vào ngưng kết .\nDoanh Chính bình tĩnh nhìn trước mắt cái chén , không nói gì .\nBởi vì lúc trước hắn ẩn ẩn liền có loại suy đoán này .\nLoại suy đoán này đến từ đâu ?\n“ Triệu Cao !”\nThủy Hoàng Doanh Chính nhìn xem Lý Ân Phàm , nhẹ giọng phun ra hai chữ này .\n“ Đúng vậy ...”\nLý Ân Phàm khẽ gật đầu một cái .\n“ Ta phía trước vẫn luôn nói , căn cơ căn cơ .”\n“ Một quốc gia , một cái vương triều , muốn lâu dài truyền thừa xuống , thì nhất định phải có chính mình căn cơ .”\n“ Một cái kia đại thần , một cái sừng sững triều đình đại nhân vật , hắn sẽ có chính mình căn cơ sao ? Không hề nghi ngờ , đương nhiên sẽ có .”\n“ Vậy cái này thời điểm vấn đề tới .”\n“ Nếu như người viết sử tái không có vấn đề , Triệu Cao soán cải Thủy Hoàng di chiếu , ủng dựng lên Hồ Hợi thượng vị .”\n“ Hơn nữa , ở trên triều đình , chỉ hươu bảo ngựa , một tay che trời .”\n“ Dựa vào là vẻn vẹn chỉ là Hồ Hợi ?”\nĐây là hiện đại có rất ít người chú ý tới vấn đề .\nTriệu Cao dựa vào cái gì cho là mình ủng dựng lên Hồ Hợi sau đó , chính mình liền có thể một tay che trời ?\nMột kẻ hoạn quan , vẻn vẹn liền dựa vào ủng lập hoàng đế , liền có thể ở trên triều đình một tay che trời sao ?\nNói đùa cái gì ?\nNếu là như vậy , về sau xuất hiện tất cả vương triều , tất cả mọi người đi làm hoạn quan tốt .\nNgược lại chỉ cần làm hoạn quan , ủng lập hoàng đế , xuyên tạc di chiếu , liền có thể ở trên triều đình chỉ hươu bảo ngựa , một tay che trời .\nThật là sẽ xuất hiện tình huống như vậy sao ?\n“ Nếu như là tình huống như vậy , cái kia về sau tuyệt đối sẽ không lại xuất hiện hoạn quan cái này một cái chức vị .”\n“ Dù sao Triệu Cao sự tích liền đặt tại phía trước , về sau hoàng đế lại không ngốc .”\n“ Cho nên , tuyệt đại đa số người , đều không để ý đến , hoặc có lẽ là không có chú ý tới vấn đề này .”\n“ Triệu Cao sau lưng , cùng với Hồ Hợi sau lưng , nhất định là có một cỗ thế lực to lớn .”\n“ Cũng chính là dạng này , mới có thể chống đỡ lấy Triệu Cao trên triều đình điên cuồng như vậy , chỉ hươu bảo ngựa !”\nNói đến đây , Lý Ân Phàm cầm ly lên , uống một ngụm Cocacola , sau đó lại nói :\n“ Mà cứ như vậy , Triệu Cao làm những chuyện như vậy , cũng liền có giải thích ...”\nMông Điềm khẽ thở dài một hơi , tiếp nhận Lý Ân Phàm mà nói , nhẹ nói :\n“ Bản Thổ phái bài trừ đối lập , đồ sát kẻ ngoại lai ...”\nLý Ân Phàm nhẹ nhàng gật đầu , đáp lại nói :\n“ trong mắt của ta này , là giải thích hợp lý nhất , cũng là vì cái gì Tần quốc sẽ sụp đổ như thế bên ngoài nguyên nhân .”\n“ Dù sao , từ Hán triều bắt đầu , trong lịch sử không có bất kì người nào , tại có thể thao túng triều đình , một tay che trời tình huống phía dưới , sau lưng của mình là không có thế lực to lớn ủng hộ .”\n“ Hán triều không có ! Triều Tấn không có ! Tùy triều không có ! Đường triều không có ! Tống triều không có ! Nguyên triều không có ! Minh triều y nguyên vẫn là không có !”\n“ Không có bất kì người nào , trong tình huống không có bất kỳ thế lực nào , chỉ dựa vào lấy ủng lập hoàng đế , liền có thể một tay che trời .”\n“ Cái kia Triệu Cao , dựa vào cái gì có thể chỉ hươu bảo ngựa , một tay che trời đâu ?”\n“ Đây chính là ta về sau nhận ra được vấn đề .”\n“ Triệu Cao , thật sự liền có thể dựa vào xuyên tạc di chiếu , thao tác triều đình sao ?”\n“ Những người khác thật không sẽ phản kháng ? Vẫn là nói , mắt lạnh nhìn Triệu Cao đứng tại trên đầu của mình diễu võ giương oai ?”\n“ Đây chính là cực lớn không hợp lý chỗ .”\nNói đến đây , Lý Ân Phàm nhìn xem Mông Điềm , nhẹ giọng tiếp tục nói :\n“ Hơn nữa , Triệu Cao lại còn có thể để cho ngay lúc đó quân đội nghe lời ?”\n“ Cầm tù đồng thời giết chết Mông Nghị , lại phái người đi tới dương chu đi giết ngươi Mông Điềm , nhường ngươi nuốt thuốc tự sát .”\n“ Ngay lúc đó quân đội , vậy mà không có phản kháng , ngồi xem rất nhiều quân đội cao tầng đi chết ?”\nNghe được cái này , Mông Điềm tựa hồ nghĩ tới điều gì , nhìn xem Lý Ân Phàm hỏi :\n“ Cái kia vương cách đâu ?”\nLý Ân Phàm nhẹ giọng trả lời :\n“ Trần Thắng , Ngô Quảng khởi nghĩa bộc phát sau đó , Tần Nhị Thế mệnh vương cách xuất binh công Triệu quốc , vây Triệu vương cực kỳ đem Trương Nhĩ tại Cự Lộc ( Nay tỉnh Hà Bắc bình hương huyện Tây Nam ).”\n“ Sở Tương Hạng Vũ lãnh binh Bắc thượng cứu triệu , đại bại Tần quân , vương cách bị bắt , vương cách quân đội đầu hàng .”\nNói đến đây , Lý Ân Phàm cười một cái nói :\n“ Hồ Hợi đem triều chính đại sự giao cho Triệu Cao đại diện , thế là không còn vào triều , một mực tầm hoan tác nhạc , quyết đoán quyền lực đại bộ lạc đến Triệu Cao trong tay .”\n“ Tần Nhị Thế mệnh vương cách xuất binh công Triệu quốc ...”\nNói đến đây , Lý Ân Phàm không có tiếp tục nói nữa .\nỞ trong đó vấn đề , chỉ cần người sáng suốt , liền có thể rất đơn giản đã nhìn ra .\n“ Đến lúc này , bọn hắn còn tại bài trừ đối lập ...”\nMông Điềm cười khổ một cái , lập tức không biết nên nói cái gì .\nChính giữa này vấn đề , hắn có thể nhìn ra sao ? Đương nhiên cũng có thể rất đơn giản nhìn ra .\nDù sao , ở trong đó thủ pháp , quá thô tháo .\nSau đó , Mông Điềm nhìn xem Lý Ân Phàm , lại hỏi :\n“ Cho nên , phản quân cũng có bọn hắn để mặc cho nguyên nhân ?”\nLý Ân Phàm không nói gì gật đầu một cái , cười khẽ một tiếng rồi nói ra :\n“ Bằng không thì Tần triều thật có thể nhanh như vậy sụp đổ sao ?”\n“ Hơn nữa , kẻ ngoại lai phát giác nguy cơ , bọn hắn sẽ thúc thủ chịu trói ?”\n“ Sẽ mắt lạnh nhìn những người khác bị tàn sát ?”\n“ Bài trừ đối lập , liền ngươi sẽ ? Chúng ta sẽ không ?”\n“ Phải biết , Chương Hàm suất lĩnh Ly Sơn quân đều có thể lần lượt công diệt quân khởi nghĩa khổ tâm , Điền Tang , lý về , đặng nói , ngũ từ chờ bộ .”\n“ Còn giết Sở quốc Trụ quốc Thái ban thưởng , tướng lĩnh Trương Hạ , ép Sở vương Trần Thắng bỏ chạy .”\n“ Lại đánh bại Tề Ngụy liên quân , tuần tự bức giết Tề vương Điền Đam , Ngụy Vương Ngụy tội trạng , Ngụy tướng Chu Phất , Sở Tương hạng lương .”\n“ Tại cuối cùng , Chương Hàm còn Bắc thượng đại phá Triệu Quân , công phá triệu đều Hàm Đan .”\n“ Cuối cùng binh vây Triệu vương tại Cự Lộc thành , mới tại cự lộc bị Hạng Vũ quân đánh bại .”\nNói đến đây , Lý Ân Phàm cảm thấy hết sức buồn cười , nhìn xem Mông Điềm nói :\n“ Ly Sơn quân là cái gì quân ? Tạm thời xây dựng một chi Hình Đồ cùng nô lệ quân đội\n“ Thống nhất sáu nhân tài của đất nước mười lăm năm ...”\n“ Mười lăm năm a , vẫn là câu nói kia , một thế hệ đều chưa từng có đi .”\n“ Quét ngang thiên hạ Đại Tần quân đội , còn không có một chi tạm thời xây dựng Hình Đồ cùng nô lệ quân đội có thể đánh ?”\n“ Đây là đang nói đùa gì vậy ?”\nỞ trong đó còn có một cái vấn đề , Lý Ân Phàm không nói .\nChính là hậu thế cho rằng , lúc đó Đại Tần quân đội cơ hồ đều tại biên quân .\nTại Thủy Hoàng khi còn sống hạ lệnh , quốc nội rối loạn , cũng không thể dời biên quân .\nĐây là hiện đại rất nhiều người cho là .\nNhưng kỳ thật đây là bịa đặt , căn bản không có cái gì người viết sử tái , chính sử ghi chép .\nCho nên lúc này , vấn đề lập tức liền xuất hiện .\nQuân đội đâu ? Chi kia quét ngang thiên hạ , thống nhất Lục quốc quân đội đâu ?\nBọn hắn có có lẽ biến mất , sách sử không có ghi chép .\nNhưng nhất định sẽ có đi bình định .\nCòn không sánh bằng những cái kia Hình Đồ cùng nô lệ xây dựng quân đội ? Bại một lần lại bại ?\n“ Quét ngang thiên hạ Đại Tần quân đội , lại là lấy phương thức như vậy kết thúc ?”\nMông Điềm đột nhiên cười ha ha , nhìn xem Lý Ân Phàm nói :.\n“ Cuối cùng ở trên sách sử lưu lại ghi chép , lại còn không sánh bằng một chi Hình Đồ cùng nô lệ tạo thành quân đội ?”\nNghĩ tới đây , Mông Điềm nước mắt tựa hồ cũng muốn cười đi ra .\nNhưng mặc dù đang cười , Mông Điềm nội tâm cảm thấy vô cùng bi ai , nước mắt bắt đầu từng giọt từng giọt trượt xuống .\n“ Đè lên quân đội bất động , ngồi xem thiên hạ đại loạn .”\n“ Bài trừ đối lập , tiễn đưa quân đội đi chết .”\n“ Cản , dây dưa hậu cần ...”\nMông Điềm từng cái kể rõ những thứ này vô cùng có khả năng phát sinh sự tình .\n“ Dù sao có một số việc , tại thống nhất thiên hạ thời điểm , liền có người đã làm .”\nLàm sao lại đi đến một bước này đâu ?\nMông Điềm trong lòng giờ khắc này thật sự vô cùng hoang mang .\nLúc này hắn , thật sự không biết nên đi như thế nào cứu vớt Đại Tần , cứu vớt cái này chính mình hệ tại một lòng vương triều .\n“ Ai ...”\nLý Ân Phàm cái gì cũng không có gì , chỉ là khẽ thở dài một hơi .\nTại thời gian rất sớm , hắn liền phát giác trong này vấn đề .\nMặc kệ hậu thế nói dễ nghe đi nữa , nói cái gì Thủy Hoàng hạ lệnh , biên quân không thể động .\nNgười viết sử tái , Thủy Hoàng còn phía dưới di chiếu , truyền vị cho Phù Tô đâu .\nHữu dụng không ? Dù là thật sự Thủy Hoàng hạ lệnh , biên quân không thể động , nhưng khi đó hoàng đế là ai ?\nKhông cho ngươi biên quân phát hậu cần , ngươi biên quân còn có thể không nghe điều lệnh ?\nCho nên , cuối Tần mâu thuẫn , thật sự so với trong tưởng tượng , còn lớn hơn hơn .\nĐại bộ phận quân đội dĩ nhiên cũng liền như vậy mắt lạnh nhìn , liền có thể rất rõ ràng thuyết minh vấn đề .\n“ Bệ hạ ...”\nMông Điềm quay đầu , nhìn xem Doanh Chính , thở nhẹ một tiếng .\n“ Nhìn sách sử thời điểm , ta cũng đã nghĩ đến điểm này .”\nDoanh Chính trên mặt rất là bình tĩnh , tựa hồ hết thảy đều ở trong lòng bàn tay .\nThấy cảnh này , Mông Điềm nội tâm cũng bình tĩnh lại .\nNhưng Thủy Hoàng Doanh Chính thật sự rất bình tĩnh sao ?\nNghĩ đến chính mình vị trí thời đại thế cục , Doanh Chính càng ngày càng cảm thấy vô cùng đau đầu .\nQuân đội , quan trường , địa phương các loại , tất cả đều là mâu thuẫn , hơn nữa , so trước đó bất kỳ một cái nào thời kỳ mâu thuẫn đều phải khổng lồ .\nTần triều mặc dù thống nhất , cũng thành công thành lập .\nNhưng lúc này hắn mới phát hiện , cái này cũng đem nội bộ tất cả mâu thuẫn đều triệt để bày tại trên mặt bàn .\nPhía trước còn có thể có thống nhất thiên hạ cái mục tiêu này đè ở phía trên , đem tất cả mâu thuẫn đều chế trụ .\nNhưng thống nhất thiên hạ sau đó đâu ?\n‘ Ai ...’\nDoanh Chính nội tâm , lại dài thở dài một hơi .\nLúc này hắn , mới phát hiện trách nhiệm của mình , có bao nhiêu khổng lồ .\n‘ Cho nên , đây mới là ta vì cái gì muốn trường sinh nguyên nhân sao ?’\nDoanh Chính bỗng nhiên toát ra ý nghĩ này .\nLúc này hắn thấy rõ ràng tất cả mâu thuẫn sau đó , mới phát hiện tại sao mình muốn trường sinh .\nMà lúc này Lý Ân Phàm , cũng là như có điều suy nghĩ gật đầu một cái .\nBởi vì lúc này Lý Ân Phàm , bỗng nhiên cũng hiểu vì cái gì trong lịch sử Tần Thuỷ Hoàng Doanh Chính vô cùng khát vọng muốn trường sinh .\nNgười kế nhiệm ? Người kế nhiệm thật có thể áp chế lại ngay lúc đó Tần triều mâu thuẫn ?\nLý Ân Phàm đem chính mình thay vào đến Tần Thuỷ Hoàng Doanh Chính góc nhìn đi xem , mới phát hiện nếu như mình thật sự biết có nhiều như vậy mâu thuẫn , chính mình thật sự không cách nào tín nhiệm về sau người kế nhiệm .\nHoàn toàn không thể yên tâm người kế nhiệm có thể hoàn mỹ giải quyết những thứ này mâu thuẫn .\nMình tại , còn có thể hơi đè lên , nhưng chờ mình sau khi đi đâu ?\nNhớ tới sách sử phía trên Phù Tô biểu hiện , Lý Ân Phàm lắc đầu .\nĐây quả thật là không có cách nào quái trong lịch sử Doanh Chính không hài lòng Phù Tô .\nDù là liền hôm nay nói những thứ này mâu thuẫn , lấy lúc đó Phù Tô biểu hiện , để cho Doanh Chính như thế nào hài lòng ?\n......', 'output\\mp3\\Màn Trời Quyền Lực Diễn Biến Cùng Truyền Thừa\\0025_Thứ 25 chương Sáu quốc dư nghiệt Không!.mp3', '2026-09-01T12:10:32.288587+00:00', 'completed', 'completed', 14955, 14955),
	(31, 7, '7643437985685324312', 26, 'Thứ 26 chương Còn tại tại chỗ', 'Thứ chương Còn tại tại chỗ\nĐường triều .\nTrinh Quán bảy năm .\n“ Bản Thổ phái , cùng người ngoại lai mâu thuẫn ?”\nDưới ánh trăng , Lý Thế Dân trầm tư rất lâu . Hắn nghĩ rất nhiều , từ màn trời nói bản thổ cùng người ngoại lai mâu thuẫn bắt đầu , hắn liền nghĩ đến bây giờ chính mình đối mặt hết thảy .\n“ Phủ Tần Vương cùng thế gia ?”\n“ Hàn môn cùng thế gia ?”\n“ Quân đội cùng văn nhân ?”\nTại cái này ban đêm , Lý Thế Dân suy nghĩ rất nhiều , nhưng cũng học tập rất nhiều .\n“ Mâu thuẫn ... Mâu thuẫn ...”\n“ Ta lúc ban đầu , cùng huynh trưởng không phải cũng là chuyện này sao ?”\n...\nMinh triều .\nVĩnh Lạc bảy năm .\n“ Văn ... Võ ...”\nChu Lệ nghĩ tới chỗ này , cũng không khỏi phải sâu thở dài một hơi .\nNếu như không phải cần áp chế cái này hai mâu thuẫn , Chu Lệ sẽ để cho Chu Cao Sí cùng Chu Cao Hú đánh lôi đài sao ?\nSẽ không .\nDù nói thế nào bọn họ đều là Từ hoàng hậu cùng mình hài tử .\nMà lão Chu gia , có lẽ những khuyết điểm khác rất nhiều , nhưng có một cái rất lớn điểm tốt , chính là thân tình .\nNhưng khá hơn nữa thân tình , cũng không sánh được trong hiện thực mâu thuẫn .\n“ Lão nhị , hy vọng ngươi chớ có trách ta ...”\nMặc dù đem rất nhiều chuyện đều cùng Chu Cao Hú nói rõ , nhưng nên làm , Chu Lệ y nguyên vẫn là muốn làm tiếp .\nCái này không quan hệ thân tình , cũng không quan khác bất luận cái gì .\nĐây là trách nhiệm của hắn , cũng là Thái tử , hoàng tử , bọn hắn cũng nhất định phải đối mặt trách nhiệm .\nDù sao Tĩnh Nan mặc dù thành công .\nThế nhưng lưu lại cho mình một cái trong lịch sử chưa bao giờ có mâu thuẫn .\nNếu như không phải thấy rõ ràng cái này mâu thuẫn .\nChu Lệ sẽ để cho chính mình mệt mỏi như vậy sao ?\nSẽ không !\n“ Cũng không biết về sau lớn minh xuống dốc , cùng cái này có quan hệ hay không ...”\nChu Lệ trên mặt , lộ ra một vẻ ưu sầu .\n...\nTống triều .\nMở bảo sáu năm .\n“ Ta cũng giống vậy gặp phải cục diện như vậy ...”\nTriệu Khuông Dận chắp hai tay sau lưng , đứng tại dưới ánh trăng , nhìn xem phương xa .\n“ Mỗi một cái triều đại , đều biết gặp phải khốn cảnh sao ?”\nNghĩ tới chỗ này , Triệu Khuông Dận hít một tiếng , không biết nên nói cái gì .\nHắn cho là liền tự mình gặp phải trong lịch sử chưa bao giờ có khốn cảnh .\nThật không nghĩ đến , mỗi một cái triều đại đều biết gặp phải dạng này vô cùng khó khăn cục diện .\n“ Lão tam ...”\nTriệu Khuông Dận hồi tưởng lại ban ngày màn trời nói Triệu Quang Nghĩa , hắn kỳ thực rất đơn giản liền có thể đoán được là Triệu Quang Nghĩa kế vị .\nBởi vì cái này cũng là hắn bây giờ hi vọng .\nTrước mặt mấy chục năm , để cho Triệu Khuông Dận căn bản là không có cách đi bồi dưỡng Thái tử , chỉ có thể bồi dưỡng đệ đệ .\nDù sao nhi tử là thân nhi tử , đệ đệ cũng không phải là thân đệ đệ sao ?\nĐến nỗi nói bồi dưỡng nhi tử , bồi dưỡng một cái Thái tử , để cho hắn tới kế thừa chính mình vị trí ?\nTrước đó Triệu Khuông Dận nghĩ tới , nhưng thứ nhất không có thời gian , thứ hai kinh nghiệm của mình để cho chính mình lo nghĩ , ba , nhưng là trước mặt mấy chục năm , có bao nhiêu là Thái tử kế vị ?\nThời đại để cho Triệu Khuông Dận nhất thiết phải dạng này lựa chọn , cũng chỉ có thể dạng này lựa chọn .\nNếu như không muốn sau đó lại xuất một cái “ Triệu Khuông Dận ”, vậy hắn chỉ có thể bồi dưỡng mình thân đệ đệ .\nÍt nhất , cũng là lão Triệu gia , không phải sao ?\n“ Lão tam , ngươi giải quyết sao ?”\nTriệu Khuông Dận ngẩng đầu nhìn về phía Yên Vân mười sáu châu vị trí .\n...\nHiện đại thời không .\n“ Kỳ thực trong mắt của ta , có một số việc nói là Bản Thổ phái cùng người ngoại lai mâu thuẫn .”\n“ Nhưng cuối cùng ...”\nLý Ân Phàm dừng một chút , sau đó tiếp tục nói :\n“ Là thời đại trước cùng thời đại mới mâu thuẫn .”\n“ trong mắt của ta này , là chủ yếu nhất .”\nThời đại trước cùng thời đại mới mâu thuẫn ?\nMông Điềm nghi ngờ nhìn về phía Lý Ân Phàm , bên cạnh Thủy Hoàng Doanh Chính cũng đồng dạng bình tĩnh nhìn hướng Lý Ân Phàm .\n“ Tần quốc giống như là thời đại trước tàn đảng , bên trong lão Tần người cũng cơ hồ đều nghĩ trở lại thương ưởng biến pháp trước đây thời kì .”\n“ Cái kia để cho bọn hắn lão Tần người sang tộc định đoạt thời kì .”\n“ Nhưng thương ưởng biến pháp sau đó , thời đại mới từ từ tới , đến thống nhất Lục quốc , Tần triều thiết lập .”\n“ Những thứ này lão Tần người sang tộc , nếu như cẩn thận đi suy xét , liền sẽ phát hiện cùng ngay lúc đó Tần triều không hợp nhau .”\n“ Cho nên , trong mắt của ta , cái này y nguyên vẫn là thời đại trước thời đại mới xung đột cùng mâu thuẫn .”\nNói đến đây , Lý Ân Phàm cầm ly lên , uống một ngụm Cocacola , sau đó nhẹ nhàng để ly xuống , tiếp tục nói :\n“ Lục quốc Dư Nghiệt , bọn hắn khao khát là cái gì ? Là muốn về đến thời kỳ chiến quốc , trở lại trên cái chỗ kia , là bọn hắn quý tộc định đoạt thời kì .”\n“ Những cái kia lão Tần người sang tộc , bọn hắn khát cầu , cùng Lục quốc Dư Nghiệt , có cái gì lớn khác biệt sao ?”\n“ Cho nên , ta mới nói , cái gì Lục quốc Dư Nghiệt ? Kỳ thực là Thất quốc Dư Nghiệt .”\n“ Nhưng muốn nói sai ? Giống như ta phía trước nói , ai cũng không có sai , chỉ có lập trường khác biệt .”\n“ Từ lão Tần người lập trường đi xem , bọn hắn khát cầu đích xác thực không có vấn đề .”\n“ Chỉ có thể nói , theo không kịp thời đại ...”\nCái này cũng là Lý Ân Phàm nhìn lượt lịch sử , phát hiện vĩnh viễn không thể điều hòa mâu thuẫn .\nThời đại trước cùng thời đại mới va chạm .\nMâu thuẫn như vậy , kỳ thực tại cận đại cũng xuất hiện qua .\nNếu như cẩn thận hiểu qua dân quốc bằng hữu , kỳ thực rất đơn giản liền có thể nghĩ rõ ràng đạo lý này trong đó .\nDân quốc sau đó hướng đi , có thể nói là “ Lão Tần người ” Thắng lợi , thời đại trước thắng lợi .\nỞ trong đó mâu thuẫn , là tương thông ! Tại Lý Ân Phàm xem ra , có cái gì lớn khác biệt sao ? Không có cái gì lớn khác biệt .\nTrong lịch sử rất nhiều đại sự phát triển mạch lạc , kỳ thực cũng là một mực tại lặp lại .\nKhi một cái nào đó thời đại mới sắp xảy ra lúc , thời đại trước tàn đảng , tổng hội nhảy ra ngăn cản , tiếp đó thu được nhất thời thắng lợi .\nNhưng cuối cùng ? Vẫn sẽ bị thời đại mới ép qua .\nMà cái này bị nghiền nát cặn bã ? Bọn hắn lại sẽ ngoan cố bám vào đến thời đại mới cường đại trên thân thể đi .\nVì thích ứng thời đại mới , cùng với kéo dài gia tộc , bọn hắn liền sẽ vô cùng phối hợp , nghiên cứu thời đại mới hết thảy .\nChờ nghiên cứu triệt để , liền bắt đầu ghé vào thời đại mới trên người , bắt đầu hút máu , dần dần tạo thành thời đại mới đặc hữu một vài thứ .\nHán triều môn phiệt là như thế này ! Đường triều thế gia là dạng này ! Tống triều sĩ phu là như thế này ! Minh triều đảng phái , y nguyên vẫn là dạng này !\nĐem bọn hắn đổi thành Tiên Tần thời kỳ quý tộc Dư Nghiệt , từ lớn góc độ đi xem , có cái gì khác biệt sao ?\nChỉ là thủ pháp thay đổi , trở nên thích ứng thời đại mới mà thôi .\nCho nên nói , lịch sử có đôi khi thật sự rất thú vị .\nTừ góc độ Macro đi xem , thời đại trước những người kia , bọn hắn tổng hội lặp lại chuyện như vậy , tựa hồ làm không biết mệt .\nLịch sử cũng đều giống như là một vòng tròn , lặp lại lặp lại , cuối cùng ? Y nguyên vẫn là lặp lại ...\n‘ Cho nên đây chính là vì cái gì hệ thống đến nguyên nhân ?’\nLý Ân Phàm lẩm bẩm ở trong lòng lấy .\nKhoa học kỹ thuật lại phát triển , thời đại lại biến dời , thật có chút đồ vật không thay đổi , thật giống như từ đầu đến cuối dậm chân tại chỗ\n‘ Đi một vòng , có thể sẽ đột nhiên phát hiện , chính mình vậy mà y nguyên còn tại tại chỗ ...’\nLý Ân Phàm nghĩ tới đây , lắc đầu khẽ cười một cái .\n......', 'output\\mp3\\Màn Trời Quyền Lực Diễn Biến Cùng Truyền Thừa\\0026_Thứ 26 chương Còn tại tại chỗ.mp3', '2026-09-01T12:10:37.521611+00:00', 'completed', 'completed', 7350, 7350),
	(32, 7, '7643438102677045784', 27, 'Thứ 27 chương Bảo trì ăn ý', 'Thứ chương Bảo trì ăn ý\nHiện đại thời không .\nNgày thứ hai .\n“ Thủy Hoàng , Mông tướng quân , chờ ăn điểm tâm , chúng ta liền chuẩn bị xuất phát .”\nLý Ân Phàm mở cửa phòng , đem mua được bữa sáng đặt lên bàn .\n“ Đây là ?”\nMông Điềm đưa tay cầm lên một cái tựa hồ giống bánh mì đồ ăn .\n“ Đó là bánh bao , đây là sữa đậu nành ...”\nLý Ân Phàm đem sữa đậu nành đẩy lên Mông Điềm trước mặt .\n“ Tiên sinh , hôm nay chúng ta đi nơi nào ?”\nThủy Hoàng Doanh Chính nhanh chóng đem thuộc về mình bữa sáng ăn xong , sau đó hướng về phía Lý Ân Phàm hỏi .\n“ Kế hoạch của ta , là dẫn ngươi đi tượng binh mã xem ...”\n“ Tượng binh mã ?”\nMông Điềm ngẩng đầu , nghi hoặc nhìn Lý Ân Phàm .\nLý Ân Phàm không nói chuyện , chỉ là nhìn về phía Doanh Chính .\n“ Các ngươi moi ra ?”\nDoanh Chính có chút nói không rõ ràng mình lúc này nội tâm đến cùng là gì tình huống .\nPhẫn nộ có không ? Có một chút , nhưng càng nhiều , lại là hiếu kỳ , hiếu kỳ cái này hai ngàn năm sau đó , chính mình mộ , đến cùng là gì tình huống .\n“ Chỉ là moi ra một chút chôn cùng hố , ở vào Ly Sơn chủ mộ , vẫn luôn không nhúc nhích .”\nNghe được cái này , Doanh Chính gật đầu một cái , sau đó không nói gì .\nDù sao nói cái gì đó ? Chính mình cũng không quản được hậu thế , mặc dù nói bên trong lòng có một chút phẫn nộ , nhưng cuối cùng vẫn là tiêu tán .\nNgồi ở bên cạnh Mông Điềm há to miệng , muốn nói gì , nhưng mình bệ hạ đều không nói cái gì , chính mình có gì có thể xen vào ?\n“ Vậy chúng ta liền xuất phát a !”\nLý Ân Phàm mang theo Doanh Chính cùng Mông Điềm thẻ căn cước , lái xe ra cửa .\nVé xe là ngày hôm qua buổi tối chính mình liền mua tốt .\n“ Bất kể thế nào nhìn , đều vẫn là cảm thấy có chút không thể tưởng tượng nổi ...”\nMông Điềm ngồi ở vị trí kế bên tài xế , sợ hãi than nhìn xem bốn phía nhanh chóng lóe lên cảnh sắc .\n“ Đây vẫn là tương đối chậm , đợi lát nữa lên đường sắt cao tốc , các ngươi liền sẽ phát hiện cái gì là nhanh .”\nMặc dù nói nhanh nhất vẫn là máy bay .\nNhưng đối với người bình thường tới nói , đi máy bay thật sự không cảm giác được cái gì gọi là nhanh .\nLuôn cảm giác máy bay một mực tại tại chỗ , không hề động một dạng .\nMà đường sắt cao tốc thì bất đồng , ngồi ở đường sắt cao tốc phía trên , nhìn về phía ngoài cửa sổ , rất rõ ràng liền có thể cảm nhận được đường sắt cao tốc nhanh .\nMấy chục phút sau , Lý Ân Phàm đem xe dừng ở trạm cao tốc bãi đỗ xe , mang theo hai người xuống xe .\nĐi vào trạm cao tốc , Lý Ân Phàm đi trước lấy đường sắt cao tốc phiếu .\n“ Cái này hai tấm phiếu lấy được .”\n“ Kỳ thực có thể không cần cầm phiếu , nhưng ta nghĩ , các ngươi lần thứ nhất ngồi , có thể sẽ muốn lưu cái kỷ niệm , cho nên vẫn là đem phiếu cho các ngươi lấy .”\nTừ rất sớm bắt đầu , ngồi đường sắt cao tốc kỳ thực cũng không cần lấy phiếu .\nỞ trên mạng mua phiếu , mang theo thẻ căn cước , vào trạm thời điểm , xoát thẻ căn cước là được rồi .\nNâng tay trái , Lý Ân Phàm nhìn đồng hồ , phát hiện còn có nửa giờ mới lên xe , sau đó liền mang theo Thủy Hoàng Doanh Chính cùng Mông Điềm ngồi ở trong đại sảnh , chờ đợi lên xe .\n“ Các ngươi tại cái này ngồi một hồi , ta đi mua mấy bình thủy .”\n“ Hảo !”\nThủy Hoàng Doanh Chính học người hiện đại phương thức hướng về Lý Ân Phàm gật đầu một cái .\nBên cạnh Mông Điềm cũng cố gắng khắc chế nội tâm mình không thoải mái .\nDù sao đi đến một cái hoàn cảnh xa lạ , đối với Mông Điềm dạng này mà nói , thật sự là có chút không thể nào hữu hảo .\n“ Cho ...”\nChờ Lý Ân Phàm trở về , đem nước khoáng đưa cho hai người .\n“ Tiên sinh , có một cái vấn đề ...”\n“ Ân ?”\nMông Điềm chỉ chỉ đám người chung quanh , sau đó dùng vô cùng giọng nghi ngờ nhẹ nói :\n“ Ngươi còn nhớ rõ những người kia sao ?”\nLý Ân Phàm nháy nháy mắt , hướng về Mông Điềm chỉ phương hướng nhìn mấy lần .\n“ Có mấy người hôm qua một mực đi theo chúng ta , ta cho là cái này tại hiện đại rất phổ biến .”\n“ Nhưng vì cái gì hôm nay , còn đi theo chúng ta ?”\nChờ Mông Điềm tiếng nói rơi xuống , Lý Ân Phàm một chút sững sờ tại chỗ , sau đó cố gắng khắc chế nội tâm mình bối rối .\nHệ thống , ngươi có cái gì muốn nói ?】\nQuen thuộc liền tốt .】\nNghe được một câu nói kia , Lý Ân Phàm não hải trong nháy mắt nhớ tới ở giữa đủ loại không hợp lý chỗ .\nTỉ như để cho Lý Ân Phàm lần thứ nhất phát giác được chỗ không đúng .\nThủy Hoàng Doanh Chính cùng Mông Điềm thẻ căn cước của hai người .\nChính mình vừa rút đến Thủy Hoàng , vừa vặn phân bưu kiện bao khỏa lại tại mấy ngày phía trước liền từ Tây An phát ra .\nCó thể có người cảm thấy rất bình thường .\nNhưng , Lý Ân Phàm tại Tứ Xuyên , tại miên dương nơi này .\nVì cái gì thẻ căn cước sẽ theo Tây An phát ra ? Hơn nữa , vẫn là mấy ngày phía trước ?\nNghĩ tới đây , Lý Ân Phàm ngồi xuống thân thể , trầm mặc rất lâu .\nBỗng nhiên , Lý Ân Phàm nở nụ cười , trong đầu đối với hệ thống nói :\nHệ thống , Lộc Lư Kiếm có thể đổi lấy tiền tài sao ?】\nCó thể .】\nCái kia giúp ta đổi a .】\nKhông đầy một lát , Lý Ân Phàm thẻ ngân hàng liền đến trương mục mấy ức\nHệ thống , kiếm bị lấy đi đi ?】\nĐúng vậy .】\nLý Ân Phàm không nói bị ai lấy đi , hệ thống cũng đồng dạng không có nói rõ Lộc Lư Kiếm đến cùng là bị chính mình lấy đi vẫn là bị người khác lấy đi .\n“ Thì ra là thế ...”\nLý Ân Phàm đứng lên , duỗi cái lưng mệt mỏi , theo phía sau lộ vẻ cười ý hướng về Mông Điềm chỉ những người kia phất phất tay .\n...\n“ Tổng bộ , tổng bộ , hắn giống như phát hiện !”\nTên nam tử kia nhìn thấy Lý Ân Phàm hướng tự chỉ huy tay , nháy nháy mắt , sau đó vội vàng nén tai nghe , hướng về phía mạch nói .\n“ Nhanh như vậy sao ?”\n“ Mông tướng quân vừa rồi chỉ chỉ chúng ta bên này .”\n“ Không hổ là có thể tại sách sử phía trên lưu danh người , vậy ngươi cũng hướng hắn phất tay a , đoán được liền đoán được , đây vốn chính là chúng ta mong muốn .”\n“ Là !”\nSau đó , tên nam tử kia cũng hướng về Lý Ân Phàm phất phất tay .\n...\nNhìn xem hướng tự chỉ huy tay người , Lý Ân Phàm cười cười , không nói gì , lại ngồi xuống thân thể .\n“ Tiên sinh ?”\nThủy Hoàng Doanh Chính cùng Mông Điềm nghi hoặc nhìn Lý Ân Phàm .\n“ Không có việc gì , đây đều là bảo hộ chúng ta người .”\nLý Ân Phàm lúc này , đem trước đây rất nhiều chuyện đều nghĩ rõ ràng .\nCái kia ăn ngon không hợp lý cơm trung , chung quanh một năm lục tục ngo ngoe dọn nhà người , cùng với đêm qua chính mình mang Thủy Hoàng cùng Mông Điềm đi ăn đẹp Oa Ngư đầu .\nNgồi một đêm , nhưng trong tiệm , trừ mình ra bọn người , vậy mà không có những người khác ?\nChính mình phía trước đi ăn thời điểm , đều là chật ních .\nDĩ vãng bị chính mình bỏ quên rất nhiều tình huống , từ từ nổi lên não hải .\n“ Sớm như vậy lại bắt đầu sao ?”\nSau đó , Lý Ân Phàm nghĩ tới chính mình sẽ phải đi thu tiết mục .\n“ Ta nói ra , cứ như vậy tiết mục , bên kia làm sao lại đồng ý .”\n“ Hơn nữa , như thế nào lại tìm ta ?”\n“ Dạng này cũng rất tốt , duy trì một loại ăn ý ...”\nLý Ân Phàm nghĩ một hồi , lập tức liền biết bọn hắn muốn làm cái gì , dù sao không cùng chính mình tiếp xúc , vẫn còn bảo hộ lấy chính mình .\n...\nHiện đại thời không .\nMột chỗ không biết tên đại sơn .\n“ Hắn đã vậy còn quá nhanh liền đoán được .”\nVài tên nam tử chắp hai tay sau lưng , nhìn xem trên màn hình lớn , Lý Ân Phàm cùng Doanh Chính còn có Mông Điềm .\n“ Không kỳ quái , chúng ta cố ý lưu lại rất nhiều sơ hở .”\n“ Chỉ cần một cái có thể xâu chuỗi tiếp đi ra việc nhỏ , liền có thể để cho hắn rất dễ dàng phát hiện .”\n“ Duy nhất để cho ta không nghĩ tới , phát hiện trước nhất không hợp lý chỗ , lại là mới đi đến một ngày Mông tướng quân .”\n“ Dù sao cũng là Tần triều danh tướng ...”\nMặc dù nói có chút ngoài ý muốn là Mông Điềm trước tiên phát hiện , nhưng mọi người cẩn thận nghĩ nghĩ , tựa hồ cũng không kỳ quái .\nNghĩ lại , nếu là không có phát hiện , có thể mới khiến cho người tương đối kỳ quái a .\n“ Đúng , Lộc Lư Kiếm tại đưa tới trên đường .”\n“ Ân ...”\n“ Cái này cũng là hắn vừa rồi tại hệ thống nơi đó bán .”\n“ Xác định chính mình suy đoán sao ?”\n......', 'output\\mp3\\Màn Trời Quyền Lực Diễn Biến Cùng Truyền Thừa\\0027_Thứ 27 chương Bảo trì ăn ý.mp3', '2026-09-01T12:11:04.774573+00:00', 'completed', 'completed', 7774, 7774),
	(33, 7, '7643738704518857240', 28, 'Thứ 28 chương Mười ba triều cố đô', 'Thứ chương Mười ba triều cố đô\nHiện đại thời không .\n“ Chúng ta đã đến .”\nMang theo Thủy Hoàng Doanh Chính cùng Mông Điềm hai người xuống đường sắt cao tốc , ra trạm cao tốc sau đó , Lý Ân Phàm nhìn xem phương xa thành thị , nhẹ nói .\n“ Đây chính là Tây An ?”\n“ Ân , Tây An ...”\n“ Mười ba triều cố đô , cũng là Tần triều lúc , Hàm Dương địa điểm .”\nThủy Hoàng Doanh Chính cùng Mông Điềm , hai người nhìn xem phương xa cảnh sắc , đều cảm giác được nội tâm có chút hoảng hốt .\nHai ngày trước chính bọn họ , còn ở chỗ này địa , chỉ là lúc kia gọi Hàm Dương .\nHôm nay , cũng tại nơi đây , chỉ là tên đổi , đã biến thành Tây An .\n“ Từ Tây Chu bắt đầu , mãi cho đến Đường triều , Tây An bị mười ba triều coi như thủ đô .”\n“ Tây Chu , Tần , Tây Hán , Đông Hán , mới , Tây Tấn ( Mẫn đế ), phía trước triệu , tiền tần , sau Tần , Tây Ngụy , Bắc Chu , Tùy , Đường ...”\n“ Đường triều sau đó , Tây An liền không còn là thủ đô .”\nNghe nói như thế , Mông Điềm quay đầu nhìn về phía Lý Ân Phàm , nhẹ giọng hỏi :\n“ Vì cái gì , tiên sinh ?”\nLý Ân Phàm khoanh tay , mang theo Thủy Hoàng Doanh Chính cùng Mông Điềm hai người vừa đi vừa nói chuyện :\n“ Có mấy cái nguyên nhân a .”\n“ Một , là trung tâm kinh tế nam dời , phương bắc từ Tùy Đường Đại Vận Hà quán thông , Giang Nam thành “ Thiên hạ kho lúa ”, mà Tây An rời xa kênh đào đại lộ Từ Lạc Dương đến Trường An cần nghịch Hoàng Hà ba môn hạp nơi hiểm yếu , thuỷ vận chi phí cực cao ( “ Đấu tiền đấu gạo ” ), năm đời sau càng không hữu hiệu thay thế con đường , không cách nào chèo chống trăm vạn cấp kinh thành tiêu hao .”\n“ Hai , là bởi vì Quốc phòng trọng tâm đông dời Đường triều trung kỳ sau đó , xâm phạm biên giới từ Tây Bắc ( Thổ Phiên , Đột Quyết ) chuyển thành Đông Bắc ( Khiết Đan , Nữ Chân , Mông Cổ , Mãn Châu ), thủ đô cần phụ cận tuyến ( Như Bắc Kinh ) hoặc khống Trung Nguyên đầu mối then chốt ( Như mở ra , Nam Kinh ), Tây An lại chỗ Tây Bắc , điều hành chậm chạp , ngoài tầm tay với .”\n“ Ba , quan trung sinh thái đã sụp đổ ngàn năm qua quá độ khai khẩn gây nên rừng rậm mất hết , đất màu bị trôi , Trịnh quốc mương chờ thuỷ lợi hoang phế , lương thực tự cấp tỷ lệ sụt giảm , Đường mạt Trường An bị Chu Ôn triệt để thiêu huỷ năm ), “ Cung thất hủy hết , một triệu người dời ”, thành thị vật lý cơ sở tan rã .”\n“ Bốn , thế lực chính trị kết cấu biến thiên Quan Lũng quý tộc tập đoàn tại Đường trung hậu kỳ tiêu vong , sau này vương triều ( Tống , nguyên , minh , rõ ràng ) căn cơ không tại trong quan , khai quốc giả nhiều dựa vào đông bộ / bắc bộ quân sự Kinh Tế tập đoàn ( Như Chu Nguyên Chương dựa Giang Hoài , Chu Lệ dựa Bắc Bình ), không dời đô Tây An động lực\nMinh sơ sơ kỳ , Chu Tiêu Tuy xem xét Tây An , nhưng mất sớm gây nên kế hoạch hủy bỏ .”\n“ Mà tại ở trong đó , trọng yếu nhất , chính là Tống triều , lúc đó Nam Tống tình huống ...”\n“ Năm , giao thông cách cục tái tạo hải vận cùng Đại Vận Hà chủ đạo nguyên minh rõ ràng vật tư di động , Tây An biến thành đất liền đầu cuối , mất đi “ Thiên hạ bên trong ” Đầu mối then chốt địa vị Bắc Bình kiêm khống Bắc Cương , liên thông thuỷ vận , gần long hưng chi địa ( Rõ ràng ), trở thành càng có ưu thế giải .”\n“ Cho nên , nói tóm lại , sau này triều đại , không phải “ Không muốn ”, thực “ Không thể ”.”\n“ Tây An từ ban đầu , “ Có thể tự kiềm chế đế quốc trái tim ” Lui vì “ Cần bên ngoài truyền máu khu vực trọng trấn ”, tại cổ đại kỹ thuật cùng vận chuyển dưới điều kiện , đã không hợp Đại Nhất Thống Vương Triều đối với Lương bổng thông suốt , binh viện binh mau lẹ , chính lệnh trung khu Tuyệt đối cương tính nhu cầu .”\nNghe được cái này , Thủy Hoàng Doanh Chính cùng Mông Điềm đều là gật đầu một cái .\n“ Thì ra là thế , nói như vậy , Tây An chính xác không thể lại xem như một buổi sáng chi đô thành .”\nLý Ân Phàm suy tư một hồi sau , tiếp tục nói :\n“ Kỳ thực Tây An không thể lại xem như đô thành , từ Tùy Đường thời kì , liền đã có dấu hiệu .”\n“ Tùy Đường thời kì , có rất nhiều vị hoàng đế , đều làm “ Trục lương thiên tử ”.”\n“ Cái gì là “ Trục lương thiên tử ”?”\n“ Chính là vì hoà dịu quan bên trong khu vực lương thực nguy cơ mà chọn lựa chính trị cử động .”\n“ Tại lúc đó , bởi vì Trường An , cũng chính là Tây An , nhân khẩu tăng vọt , thổ địa trôi đi cùng thuỷ vận khó khăn dẫn đến lương thực thiếu , Tùy Văn Đế Dương Kiên , Đường Cao Tông Lý Trị , Đường Huyền Tông Lý Long Cơ mấy người nhiều lần tỷ lệ triều đình dời đến Lạc Dương “ Liền ăn ”.”\n“ Hiện tượng này tại Đường đại càng thường xuyên , Đường Cao Tông từng bảy lần dời đô Lạc Dương , Đường Huyền Tông cũng 5 lần đông dời .”\nTrục lương thiên tử ?\nThủy Hoàng nghĩ tới đây bốn chữ , nở nụ cười .\n“ Mặc dù nói đến Đường hậu kỳ , thuỷ vận phát triển , đã không còn loại tình huống này ...”\n“ Thế nhưng là thật sự không còn loại tình huống này , còn là bởi vì một ít nguyên nhân , không cần lại “ Liền ăn ”?”\nLý Ân Phàm nói đến đây , chỉ là cười cười , không có lại cụ thể nói tiếp .\nBởi vì phương diện này tình huống rất rõ ràng , Tống triều cùng với sau đó triều đại , đều không lại đem Tây An cùng với Lạc Dương xem như đô thành , cũng rất có thể nói rõ vấn đề .\nCho nên , đến cùng là thuỷ vận phát triển , không còn loại tình huống này , không cần “ Liền ăn ”, vẫn là ngay lúc đó sinh lương , đã thỏa mãn ngay lúc đó số lượng nhân khẩu ?\nChỉ có thể nói khó mà nói .\n“ Tây An phát triển bây giờ cũng không tệ lắm .”\n“ Chính là có một chút không tốt ...”\nLý Ân Phàm đi ở ven đường , nhìn xem phương xa tựa hồ đang tại thi công công trường .\nBên cạnh Thủy Hoàng Doanh Chính cùng sự chú ý của Mông Điềm một lần nữa chú ý Lý Ân Phàm .\n“ Tây An xem như văn hóa lịch sử , chính xác rất dày nặng , nhưng là cái này phát triển ...”\nLý Ân Phàm chỉ chỉ nơi xa thi công công trường nói :\n“ Thỉnh thoảng đều biết dừng lại , vì cái gì ? Bởi vì rất dễ dàng không cẩn thận liền đào được ai mộ ...”\n“ Dù sao xem như mười ba triều cố đô , phía dưới chôn người , quả thực là rất rất nhiều .”\nNói đến đây , Lý Ân Phàm khóe miệng không tự chủ liền muốn cười .\nBởi vì hắn chính xác nhìn thấy trên mạng rất nhiều Tây An người địa phương đều đang oán trách , tu một đầu tàu điện ngầm , thật sự quá khó khăn .\nĐầu thứ nhất tàu điện ngầm , lịch sử hẹn năm .\nTừ năm bắt đầu , khởi động quỹ đạo giao thông kế hoạch , chỉnh thể trù bị xây dựng khoảng cách gần năm\nNghe nói phía sau đường số đường số , bởi vì văn vật đông đúc hoặc công trình phức tạp , bộ phận tiêu đoạn đình công cần nghiên cứu thêm cổ , lại kém không nhiều tu năm .\n...\nMà liền tại Lý Ân Phàm nói như thế một phen sau đó .\nNhững cái kia trong lịch sử , đem Tây An xem như thủ đô triều đại , lập tức cũng không biết nên nói cái gì cho phải .\n“ Cho nên , cái này còn trách chúng ta rồi ?”\n“ Cái này .. Hậu thế ... Thật làm cho không biết nên nói thế nào ...”\n“ Ân ... Về sau vẫn là chôn xa một chút a , nhìn tình huống này , dù là không có bị trộm mộ , có thể cản trở hậu thế phát triển , vẫn sẽ bị móc ra .”\n“ Cũng không biết có bao nhiêu người mộ đều bị moi ra ...”\n“ Khảo cổ sao ? Đây là đời sau một cái mới học khoa ?”\n“ Khảo cổ , khảo cổ , khảo sát cổ mộ ? Là ý tứ này sao ?”\nMặc dù có một số người vẫn vô cùng phẫn nộ , cũng mặc kệ như thế nào , cũng chỉ có thể phẫn nộ một chút .\nDù sao bọn hắn lại không quản được hậu thế , bằng không thì còn có thể làm sao đâu ?\nCó ý tưởng , cũng chỉ là đang suy nghĩ , có phải hay không nên đem chính mình mộ chôn đến rừng sâu núi thẳm bên trong , không để hậu nhân quấy rầy .\n......', 'output\\mp3\\Màn Trời Quyền Lực Diễn Biến Cùng Truyền Thừa\\0028_Thứ 28 chương Mười ba triều cố đô.mp3', '2026-09-01T12:11:09.688219+00:00', 'completed', 'completed', 7344, 7344),
	(34, 7, '7643738852070261272', 29, 'Thứ 29 chương Lương thực', 'Thứ chương Lương thực\nHiện đại thời không .\n“ Đây là ...”\nĐi vào Tần Thuỷ Hoàng tượng binh mã số một hố , Doanh Chính nhìn xem cảnh tượng trước mắt , lập tức giật mình tại chỗ .\nBên cạnh Mông Điềm cũng cảm giác một trận hoảng hốt .\nGiờ khắc này , hai người đều cảm giác tựa như Đại Tần lại xuất hiện ở trước mắt của mình .\nĐặc biệt là Mông Điềm , nhìn xem trong hầm cảnh tượng , không tự chủ ở trong miệng liền nhắc tới :\n“ Đại Tần ... Đại Tần ...”\nĐợi một hồi lâu , Thủy Hoàng Doanh Chính cùng Mông Điềm hai người mới hồi thần lại .\n“ Đây chính là số một hố , cũng là khám phá lớn nhất hố .”\nNhìn xem số một hố , Lý Ân Phàm thở dài một hơi sau , nhìn chằm chằm Doanh Chính nói :\n“ Thủy Hoàng , ngươi hẳn là phát hiện xảy ra vấn đề a ?”\n“ Ân ... Bên trên những tượng này màu sắc , cũng bị mất ...”\nCái này cũng là vì sao Thủy Hoàng Doanh Chính cùng Mông Điềm có thể nhanh chóng lấy lại tinh thần nguyên nhân .\nBởi vì tượng bên trên màu sắc rơi xuống , rất rõ ràng liền có thể nhìn ra khác biệt .\n“ Dù sao chôn dưới đất hơn hai nghìn năm , tượng bên trên màu sắc , cơ hồ đều rụng cùng oxi hoá ...”\n“ Ở phương diện này , quốc gia chúng ta ăn thiệt thòi rất lớn ...”\n“ Cho nên , sau đó khảo cổ , đều chỉ sẽ tiến hành bảo hộ tính chất cứu giúp khai quật , mà không còn tự động tiến hành khai quật khảo cổ .”\n“ Cái này cũng là bây giờ rất nhiều Đế Lăng có thể tồn tại một cái nguyên nhân a .”\nNói xong điểm ấy , thời gian sau đó , Lý Ân Phàm lại dẫn hai người đi khác hố đi nhìn nhìn .\n“ Ai ...”\nChờ xuất binh Mã Dũng nhà bảo tàng , Thủy Hoàng Doanh Chính thở dài một tiếng .\nĐi ở Doanh Chính bên cạnh Mông Điềm , tâm tình cũng có một chút rơi xuống .\n“ Đại Tần , cuối cùng liền còn lại điểm này sao ?”\nMông Điềm quay đầu , lại nhìn về phía tượng binh mã nhà bảo tàng , lúc này tâm tình của hắn , cũng không biết nên như thế nào đi thuyết minh .\n“ Đại Tần ...”\nThủy Hoàng Doanh Chính liếc mắt nhìn phương xa Tây An , vừa quay đầu liếc mắt nhìn tượng binh mã nhà bảo tàng , cuối cùng , hít vào một hơi thật sâu .\n“ Đi thôi , tiên sinh ...”\n“ Ân ...”\nLý Ân Phàm không nói gì thêm , cũng không có an ủi bọn hắn , chỉ là mang theo hai người đi ra nhà bảo tàng .\nTùy tiện tìm một cái nhà hàng , ăn một chút đồ vật .\n“ Tối nay chúng ta lại trở về , đợi chút nữa trời tối thời điểm , chúng ta đi Đại Đường Bất Dạ Thành chơi đùa ...”\n“ Đại Đường Bất Dạ Thành ?”\n“ Ân , tại Đại Nhạn tháp dưới chân , lấy Thịnh Đường văn hóa làm bối cảnh cỡ lớn phảng phất Đường khu kiến trúc phố đi bộ , vì Tây An tiêu chí tính chất cảnh khu .”\n...\nĐường triều .\nTrinh Quán bảy năm .\n“ Đại Đường Bất Dạ Thành ?”\nLý Thế Dân đột nhiên ngẩng đầu nhìn màn trời .\n“ Cái này nói chúng ta Đại Đường ?”\nChung quanh rất nhiều đại thần , cũng đều tò mò nhìn màn trời .\n...\nHiện đại thời không .\nBan đêm .\n“ Cái này ?!!”\nMông Điềm trợn mắt hốc mồm nhìn xem cảnh tượng trước mắt .\n“ Tiên sinh , đây chính là Đại Đường Bất Dạ Thành ?”\n“ Đúng vậy ...”\n“ Đây thật là ... Thực sự là ...”\nGiờ khắc này Mông Điềm , hoàn toàn không biết nên dùng cái gì từ để hình dung xuất hiện tại trước mắt mình cảnh tượng .\n“ Đi thôi , chúng ta đi dạo .”\nLý Ân Phàm mang theo Thủy Hoàng Doanh Chính cùng Mông Điềm hai người đi vào .\n“ Tiên sinh , đó là đang làm cái gì ?”\nMông Điềm dừng ở một cái cảnh điểm phía trước , chỉ chỉ trên đài một mực tại tương tác nói chuyện hai người .\n“ Phòng Huyền Linh , Đỗ Như Hối ...”\nLý Ân Phàm nhìn thấy hai người , nở nụ cười sau , tiếp tục nói :\n“ Đương nhiên , chắc chắn không phải Đại Đường Trinh Quán trong năm Phòng Huyền Linh cùng Đỗ Như Hối , là nhân viên công tác vai trò .”\n...\nĐại Đường .\nTrinh Quán bảy năm .\n“ Phòng Huyền Linh ?! Đỗ Như Hối ?!!”\nNghe được màn trời âm thanh , cam lộ trước điện , tất cả đại thần , đều vụt một cái nhìn về phía trước Phòng Huyền Linh .\nLý Thế Dân cũng có chút sửng sốt , sau đó nhìn về phía Phòng Huyền Linh .\nMà Phòng Huyền Linh bản thân đâu ? Nhưng là một mặt mộng đứng tại chỗ .\n“ Ta ?!”\n...\nHiện đại thời không .\n“ Tiên sinh , chúng ta đi ra ngoài đi ...”\nThủy Hoàng Doanh Chính vốn định nhiều hơn nữa nhìn một chút thời gian , nhưng đám người chung quanh chen chính mình thực sự khó chịu .\nMặc dù có Mông Điềm một mực dán tại bên cạnh mình bảo hộ lấy chính mình , nhưng chưa từng có qua loại kinh nghiệm này Doanh Chính , trong nội tâm vẫn còn có chút khó chịu .\n“ Đi ...”\nLý Ân Phàm cũng nhìn ra Doanh Chính nội tâm khó chịu , lập tức mang theo hai người đi ra Đại Đường Bất Dạ Thành .\n“ Đây quả thật là không có cách nào , Đại Đường Bất Dạ Thành ở đây , đến buổi tối mới bắt đầu , mà đám người trên cơ bản cũng là nhiều như thế .”\n“ Đã rất thỏa mãn ...”\nMặc dù vẫn có một ít tiếc nuối , nhưng Doanh Chính quả thực không muốn lại chen vào .\nDạng này mang theo một điểm tiếc nuối , cũng rất tốt .\n“ Vậy chúng ta tìm khách sạn chuẩn bị nghỉ ngơi đi , ngày mai , chúng ta thì đi thủ đô ...”\nLý Ân Phàm nâng tay trái , nhìn thời gian một cái , sau đó nhẹ giọng đối với hai người nói .\n“ Hảo , tiên sinh .”\nThủy Hoàng Doanh Chính cùng Mông Điềm hai người đều là gật đầu một cái .\nỞ chung quanh tùy tiện tìm một cái khách sạn , Lý Ân Phàm tại trước đài , cầm thẻ căn cước của hai người cùng với thẻ căn cước của mình , mở 3 cái phòng một người .\n“ Đây là thẻ phòng , chen vào ở đây liền có điện ...”\nMang theo hai người đi vào phòng khách sạn , Lý Ân Phàm từng cái dạy hai người .\n“ Nếu có đặc thù gì tình huống , trực tiếp ở bên cạnh tìm ta liền tốt .”\nLý Ân Phàm vì để tránh cho hai người tìm không thấy chính mình , chuyên môn mở 3 cái liền với số gian phòng , mà gian phòng của mình , ngay tại 3 cái số ở giữa .\n“ Trước nghỉ ngơi một chút đi ...”\n“ Đúng , Thủy Hoàng , ta đợi chút nữa tìm ngươi có việc .”\n“ Hảo ...”\nThủy Hoàng Doanh Chính bình tĩnh gật đầu một cái .\nNửa giờ sau , Lý Ân Phàm trong phòng tắm một cái , đem mồ hôi trên người vị khu trừ , tùy tiện xuyên qua một kiện trong bọc mang theo ngắn tay cùng quần đùi .\nSau đó , Lý Ân Phàm đem chính mình bên trong túi khinh bạc máy vi tính xách tay (bút kí) lấy ra .\nGõ gõ !\n“ Tiến !”\nNghe được thanh âm này , Lý Ân Phàm mới mở ra cửa phòng đi vào .\n“ Tiên sinh ?”\nDoanh Chính mang theo ánh mắt nghi hoặc nhìn xem Lý Ân Phàm , có chút hiếu kỳ , là chuyện gì .\nỞ bên cạnh hắn , Mông Điềm đoan chính ngồi ở một bên .\n“ Thủy Hoàng , ngươi xem một chút , Tần triều có cần đồ vật gì sao ?”\nÂn ?\nThủy Hoàng Doanh Chính nghi hoặc nhìn Lý Ân Phàm đem máy vi tính xách tay (bút kí) đặt ở trước mặt mình .\n“ Nếu có cái gì cần , chúng ta buổi tối hôm nay liền có thể đặt hàng , tối mai , các ngươi trở về thời Tần triều , liền có thể cùng nhau mang về ...”\nThủy Hoàng Doanh Chính cùng Mông Điềm nhìn xem cái kia máy vi tính xách tay (bút kí) , nhìn một lúc lâu , phát hiện mình hoàn toàn xem không hiểu .\n“ Tiên sinh , có cái gì đề cử sao ?”\nMông Điềm nhìn xem Lý Ân Phàm , trước tiên hỏi âm thanh .\n“ Ta đề cử sao ?”\nLý Ân Phàm tại máy vi tính xách tay (bút kí) Touchpad phía trên một chút trong chốc lát , đem chính mình phía trước liền viết xong mục lục điểm ra .\nPhía trước hắn liền có cân nhắc qua tình huống như vậy .\nNhưng vì cái gì không trước tiên lấy ra ?\nBởi vì để cho chính mình trước tiên lên tiếng an bài ? Lý Ân Phàm còn không có thấp như vậy EQ .\nLoại sự tình này , chỉ có đối phương thỉnh cầu chính mình , Lý Ân Phàm mới dễ làm .\n“ Đầu tiên điểm thứ nhất , sách !”\n“ Trọng yếu nhất , tạo giấy thuật ( Giấy trúc giản dị bản ), in chữ rời hình thức ban đầu ( Khắc gỗ ), trục bánh đà / tổ hợp ròng rọc bản vẽ , giản dị sức nước máy móc ( Cối đá giã gạo bằng sức nước / thủy sắp xếp ), vôi / xi măng phối trộn ( Trợ xây con đường / Trường thành ), cơ sở vệ sinh phòng dịch sổ tay ( Rửa tay , cách ly , xử lý rác thải\nNói đến sách , Lý Ân Phàm mở ra trên sách kết nối .\nTrong máy vi tính xách tay , lập tức bắn ra tới một cái video .\n“ Cái gì là tạo giấy thuật ?...”\n“ Giản dị sức nước máy móc có ích lợi gì ? Làm như thế nào đi làm ?...”\nTrong video nhất nhất giới thiệu Lý Ân Phàm đề cử những điều kia sách .\nChờ video phát ra sau khi xong , Lý Ân Phàm quay đầu nhìn về phía Thủy Hoàng Doanh Chính cùng Mông Điềm hai người .\nMông Điềm mở to con mắt , khát vọng nhìn xem máy vi tính màn hình .\nMà Doanh Chính , nhưng là cố nén nội tâm kích động , hướng về Lý Ân Phàm gật đầu một cái .\n“ Tiên sinh , chỉ những thứ này sách a .”\n“ Hảo ...”\nSau đó , Lý Ân Phàm lại ấn mở thứ hai cái mục lục .\n“ Điểm thứ hai , nông nghiệp cùng điều trị Hạt giống ( Cao sản cây lúa / mạch ), giản dị thiết bị chưng cất ( Chế nước lọc / rượu cồn ), cơ sở chất kháng sinh ( Như Penicilin nguyên thủy khuẩn loại hoặc hoàng án loại viên thuốc ), muối cùng i-ốt tề Có thể tăng lên trên diện rộng nhân khẩu chịu tải lực cùng bách tính tỉ lệ sống sót .”\nNói xong , Lý Ân Phàm ấn mở kết nối .\n“ Hiện nay có thể lưu chủng , không thi phân hóa học lương thực hạt giống , cao nhất mẫu sinh là bao nhiêu ?”\n“ Bắp ngô ( Thông thường giữ lại cho mình loại ): Mẫu sinh cân ).”\n“ Lúa nước ( Thông thường giữ lại cho mình loại ): Mẫu sinh cân ).”\n“ Lúa mì ( Thông thường giữ lại cho mình loại ): Mẫu sinh cân ).”\n“ Đậu nành ( Thông thường loại ): Mẫu sinh\nLý Ân Phàm vì hai người thuận tiện lý giải , còn tại màn hình trên phụ đề , chuyển đổi rồi một lần , cái này mẫu sinh tại Tần triều có thể tới bao nhiêu cân .\nMà cái này , cũng liền tạo thành Doanh Chính cùng Mông Điềm hai người , trợn mắt hốc mồm nhìn màn ảnh .\n“ Trước tiên ... Sinh ... Tiên sinh ...”\nTrong miệng Mông Điềm có chút run run nhìn xem Lý Ân Phàm .\n“ Phía trên này ... Nói .. Đều là thật ?!”\nLý Ân Phàm rất là nghiêm túc hướng về phía Mông Điềm gật đầu một cái nói :\n“ Đều là thật , dạng này mẫu sinh kỳ thực thấp , bởi vì đây không phải tạp giao , cũng không có thi phân hóa học .”\n“ Nếu như là tạp giao chủng loại , làm phân hóa học , mẫu sinh còn có thể lật mấy phen .”\n“ Nhưng tạp giao chủng loại , rất nhiều cũng là không thể lưu chủng , cho nên ta liền không có cân nhắc .”\n“ Mà phân hóa học , cần hóa công nghiệp phát triển , ta cũng không có cân nhắc .”\n“ Cái này mẫu sinh ...”\nLý Ân Phàm chỉ chỉ màn ảnh máy vi tính nói :\n“ Cái này mẫu sinh , không có thi cái gì mập ! Cho nên , tại Tần triều , cái này mẫu sinh kỳ thực còn có thể đề cao một chút , bởi vì có phân xanh ...”\nDoanh Chính chỉ cảm thấy tay của mình có chút run rẩy .\nHắn rất muốn cưỡng ép nhẫn nại xuống , có thể nghĩ đến vừa rồi trên notebook phóng video , như thế nào cũng nhẫn nại không tới .\nMà giờ khắc này , không chỉ là Doanh Chính ...\n...\nĐại Đường .\nTrinh Quán bảy năm .\nCam lộ trước điện , tất cả mọi người đều trừng trừng nhìn chằm chằm màn trời .\n“ Này ... Cái này ...”\nLý Thế Dân giờ phút này vô cùng khát vọng đi đến hậu thế , có thể cầm tới này đối cổ đại tới nói , mẫu sinh khoa trương lương thực .\n“ Bệ hạ ...”\nNgụy Chinh quay đầu nhìn chằm chằm Lý Thế Dân .\nChung quanh đám đại thần nghe được một tiếng này , cũng đều nhìn về phía Lý Thế Dân .\n“ Ngươi nhất định muốn cầm tới danh ngạch , đi đến hậu thế !!!”\nNgụy Chinh âm thanh chém đinh chặt sắt .\n“ Đúng , bệ hạ , ngươi nhất định muốn cầm tới danh ngạch .”\nBên cạnh đám đại thần , cũng đều phụ họa .\n“ Trẫm cũng nghĩ ....”\nLý Thế Dân bất đắc dĩ nhìn rất nhiều đại thần một mắt , sau đó lại dùng ánh mắt khát vọng nhìn về phía màn trời .\n“ Cầm tới cái này , liền có thể rửa sạch trên người ta tất cả vết nhơ đi ...”\nTrong nội tâm , Lý Thế Dân yếu ớt thở dài .\n“ Cho nên , nhất định muốn cầm tới ...”\nThân là quân chủ Lý Thế Dân , rất rõ ràng cái gì chiến công có thể để cho đời sau tất cả mọi người đều bỏ qua trên người mình vết nhơ .\nĐặc biệt là thân ở thời kỳ này , Lý Thế Dân càng là vô cùng tinh tường .\n...\nĐại hán .\nNguyên thú 4 năm .\n“ Lương thực ... Lương thực ... Lương thực ...”\nLưu Triệt vụt một cái đứng lên , đi qua đi lại , trong miệng một mực nhắc tới :\n“ Lương thực ...”\n“ Có những lương thực này , trẫm có thể một mực đánh , một mực đánh , không ngừng đánh !!!”\nNghĩ tới đây , Lưu Triệt đột nhiên dừng lại , quay đầu nhìn về phía màn trời , nhìn trừng trừng lấy màn trời phía trên , cái kia trong Notebook truyền video .\n“ Trẫm nhất định phải đi hậu thế ...”\n“ Cứ như vậy , dù là trẫm đánh lợi hại hơn nữa , hậu thế cũng chỉ sẽ xưng trẫm vì Thánh Quân ...”\n“ Cho nên , trẫm nhất định muốn cầm tới !!”\n...\nĐại Minh .\nVĩnh Lạc bảy năm .\n“ Lão đại !!!”\n“ Trẫm nhất định phải đi hậu thế !”\nNhìn xem màn trời , Chu Lệ vô cùng nói nghiêm túc .\n“ Phụ thân , ta cũng nghĩ đi ...”\nChu Cao Sí quay đầu liếc mắt nhìn Chu Lệ , sau đó rất là bất đắc dĩ nói .\n“ Trẫm nhất định phải đi !”\nChu Lệ lại lập lại một câu , sau đó quay đầu nhìn về phía Chu Cao Sí , nói nghiêm túc :\n“ Lấy được cái này lương thực , trẫm có hay không có thể không cố kỵ chút nào đánh ?”\nA ?\nChu Cao Sí nghe được một câu nói kia , sửng sốt một hồi , sau đó nghiêm túc nghĩ nghĩ rồi nói ra :\n“ Cũng không thể nói không hề cố kỵ , nên hạt giống thu lương thời điểm , không thể đánh ...”\n“ Đủ !!!”\n...\nĐại Minh .\nHồng Vũ mười năm .\n“ Muội ... Muội tử ... Muội tử ...”\nChu Nguyên Chương có chút run run nhìn về phía bên cạnh Mã hoàng hậu .\n“ Ngươi nghe rõ ràng ... Nghe rõ ràng màn trời nói ... Mẫu sinh ... Mẫu sinh bao nhiêu sao ?”\nMã hoàng hậu chăm chú nhìn màn trời , nghe được Chu Nguyên Chương âm thanh , cũng không quay đầu lại gật đầu một cái nói :\n“ Trọng tám , ngươi không nghe lầm ...”\n“ Không nghe lầm ?!”\nBầu không khí lập tức trở nên yên lặng , Chu Nguyên Chương nhìn chòng chọc vào màn trời .\n“ Ta nhất định muốn cầm tới ! Nhất định muốn cầm tới ! Muội tử !”\n“ Ân , nhất định muốn cầm tới !”\nTrong lịch sử tất cả hoàng đế bên trong , không có người nào so Chu Nguyên Chương càng hiểu , cái này mẫu sinh đến cùng ý vị như thế nào .\nNếu như lúc đó tại cuối thời nhà Nguyên thời kì , có dạng này mẫu sinh ra lương thực , Chu Nguyên Chương có thể căn bản đi không bên trên con đường kia .\nĐương nhiên , cũng có khả năng vẫn sẽ đi lên con đường kia .\nDù sao , mẫu sinh đúng là tăng lên , nhưng thu thuế thứ này , đều theo tỉ lệ cắt .\nHuống chi , ai cũng không nói chắc được , vẫn sẽ hay không tăng thêm càng nhiều thuế .\n...\nHiện đại thời không .\n“ Sau đó chính là , tiền tệ cùng quản lý loại Chuẩn hoá đo lường khuôn đúc ( Tần Dĩ thống nhất , nhưng địa phương vẫn có sai lầm ), 《 Vải vàng Luật 》 bổ sung đề nghị ( Phòng tư đúc ), dịch trạm hệ thống ưu hóa phương án chờ đã ...”\nLý Ân Phàm nói xong một điểm cuối cùng , tiếp đó chăm chú nhìn Thủy Hoàng Doanh Chính cùng Mông Điềm hai người .\n“ Những vật này , nhất định muốn chậm , Thủy Hoàng ...”\n“ Bây giờ Đại Tần , rất nhiều vấn đề chủ yếu nhất , không tại lương thực này một ít địa phương , chủ yếu là nhân tâm ...”\n“ Đương nhiên , ta tin tưởng , mang về nhiều đồ như vậy , sau này nhân tâm cũng nhất định sẽ hướng về Đại Tần ...”\n“ Nhưng những này đồ vật thi triển ra , nhất định không cần quá nhanh ...”\n“ Trước hết để cho Đại Tần , chậm lại ...”\n......', 'output\\mp3\\Màn Trời Quyền Lực Diễn Biến Cùng Truyền Thừa\\0029_Thứ 29 chương Lương thực.mp3', '2026-09-01T12:11:14.998545+00:00', 'completed', 'completed', 14685, 14685),
	(35, 7, '7644000977774707224', 30, 'Thứ 30 chương Dài thành', 'Thứ Chương Trường Thành\nHiện đại thời không .\n“ Đây chính là Trường thành sao ?”\nĐi ở bát đạt lĩnh phía trên Trường thành , Thủy Hoàng Doanh Chính cùng Mông Điềm nhìn xem phương xa một mắt trông không đến uốn lượn Trường thành , trong lòng có một loại không hiểu xúc động .\n“ Đây không phải Tần Trường Thành , đây là Minh triều Hoằng Trị trong năm khởi công Minh Trường thành .”\n“ Hiện có Trường thành , 99% , cũng là Minh triều xây dựng .”\n“ Dù sao , thời kỳ Xuân Thu , còn có Tần Hán lúc Tu Trường thành , thời gian quá lâu , một hai ngàn năm thời gian , bảo tồn không được lâu như vậy .”\nLý Ân Phàm chắp hai tay sau lưng , chậm rãi đi ở Doanh Chính bên cạnh .\n“ Hiện đại rất nhiều người cho là Trường thành liền Tần triều cùng Minh triều tu kiến qua .”\n“ Kỳ thực trong lịch sử , có hơn 20 cái các nước chư hầu cùng triều đại đều tu kiến qua trường thành .”\n“ Sớm nhất , ta nhớ được sở , yến , Ngụy , triệu bao gồm hầu quốc , đều tu kiến qua trường thành a ...”\nNói đến đây thời điểm , Lý Ân Phàm nhìn về phía Thủy Hoàng Doanh Chính , trong mắt lộ ra một vẻ hỏi thăm .\n“ Đúng , bọn hắn đều tu kiến qua .”\nNghe nói như thế , Lý Ân Phàm liền tiếp tục nói :\n“ Sau đó chính là Tần triều , Hán triều .”\n“ Mà Hán triều tu kiến Trường thành , chủ yếu chính là vì bảo hộ con đường tơ lụa .”\nSau đó , Lý Ân Phàm dừng bước lại , tay chống đỡ bức tường , nhìn xem bầu trời bên ngoài , nhẹ nói :\n“ Trong lịch sử căn bản cũng không có không có sửa qua Trường thành triều đại .”\n“ Hiện đại rất nhiều người cho rằng Tống triều không có sửa qua Trường thành ...”\n“ Nhưng kỳ thật Tống triều cũng sửa qua Trường thành Xây dựng Trường thành , chủ yếu phân bố tại Sơn Tây , bên trong Mông Cổ , Ninh Hạ các vùng , là phòng ngự Liêu cùng Tây Hạ xây lên .”\n“ Không có đại quy mô xây dựng triều đại rất ít , Đường triều tính toán một cái .”\n“ Nhưng Đường triều là tu sửa qua thành cũ cùng tháp đèn hiệu .”\nNghe được cái này , bên cạnh Mông Điềm nhìn về phía Lý Ân Phàm , nhẹ giọng dò hỏi :\n“ Tiên sinh , bây giờ còn sửa qua Trường thành sao ?”\n“ Sửa qua , nhưng chỉ là tu sửa , vì xem như cảnh điểm ...”\n“ Không còn là vì chống cự phương bắc dị tộc .”\nLý Ân Phàm nhìn xem Mông Điềm , nhẹ giọng trả lời , sau đó tiếp lấy lại tiếp tục nói :\n“ Hiện đại chiến tranh hình thức đã thay đổi , từ trong đốt cơ xuất hiện bắt đầu , kỵ binh liền thối lui ra khỏi võ đài lịch sử .”\n“ Mà kỵ binh thối lui ra khỏi lịch sử võ đài , phương bắc ...”\nLý Ân Phàm nói đến đây , không có tiếp tục nói nữa .\nKỳ thực nơi này có một cái điểm rất nhiều người không biết .\nBây giờ trên internet , có một câu nói : Mark thấm xuất hiện , dân tộc du mục bắt đầu trở nên năng ca thiện vũ .\nNày làm sao nói ra ? Chỉ có thể nói là trêu chọc .\nKỳ thực là động cơ đốt trong xuất hiện , hơn nữa đại quy mô ứng dụng sau đó , kỵ binh liền đã không còn thích ứng lịch sử võ đài .\nThế kỷ trước một trận chiến , thế chiến thứ hai , mặc kệ là Châu Âu đại lục , vẫn là Châu Á đại lục , bộ đội kỵ binh kỳ thực đều đại quy mô tồn tại .\nTại lúc đó , bộ đội kỵ binh chỉ có thể nói là chiến thuật địa vị hạ xuống .\nNhưng về sau xe tăng , xe bọc thép các loại trang bị đổi mới thay đổi tốc độ tăng tốc , cơ giới hoá trang bị thay thế , kỵ binh mới từ từ xuống dốc .\nDù sao hiện đại hoá trong chiến tranh , chăn ngựa chi phí cao lại huấn luyện chu kỳ dài , không bằng cơ giới hoá trang bị dễ dàng giữ gìn cùng đại quy mô sinh sản , chi phí - hiệu quả cực thấp .\nĐơn giản điểm tới nói , chính là chiến mã không chạy nổi ô tô , ngăn không được súng máy , dưỡng vẫn còn so sánh xe tăng quý .\n“ Vậy bây giờ còn có bộ đội kỵ binh sao ?”\nMông Điềm tiếp lấy Lý Ân Phàm mà hỏi .\n“ Còn có ...”\nLý Ân Phàm gật đầu một cái , sau đó lại nói :\n“ Bộ phận quốc gia vẫn giữ lại chút ít kỵ binh dùng Biên cảnh tuần tra Hoặc Lễ nghi tiếp đãi .”\n“ Mà quốc gia chúng ta , cũng giữ lại có số ít bộ đội kỵ binh , nhưng những kỵ binh này binh sĩ , trên cơ bản cũng là tại con đường tổn hại , cỗ xe khó mà qua lại hoặc mùa đông tuyết đọng thâm hậu “ Sinh mệnh cấm khu ”.”\nDạng này sao ?\nMông Điềm lúc này nội tâm có một vệt không nói được thương cảm .\nBộ đội kỵ binh , ở đời sau , vậy mà đã thối lui ra khỏi võ đài lịch sử .\n“ Cái kia phương bắc đâu ?”\nThủy Hoàng Doanh Chính phát giác một cái điểm mấu chốt .\nTất nhiên bộ đội kỵ binh vô dụng , Trường thành cũng vô ích , cái kia phương bắc ?\n“ Đây là các ngươi thẻ căn cước .”\nLý Ân Phàm tựa hồ biết Doanh Chính sẽ hỏi vấn đề này , đem thẻ căn cước đưa cho Thủy Hoàng Doanh Chính cùng Mông Điềm .\n“ Nhìn thấy phía trên dân tộc phân chia sao ?”\n“ Hán tộc .”\n“ Bây giờ quốc gia , chúng ta gọi chung là dân tộc Trung Hoa , mà dân tộc Trung Hoa , thì từ năm mươi sáu cái dân tộc tạo thành .”\nCâu nói kế tiếp , Lý Ân Phàm không nói , nhưng Thủy Hoàng Doanh Chính cùng Mông Điềm đã hiểu .\nPhương bắc dị tộc , đã trở thành dân tộc Trung Hoa năm mươi sáu cái dân tộc một trong .\nNghĩ tới đây , Thủy Hoàng Doanh Chính cùng Mông Điềm hai người nhìn lẫn nhau một cái , bất đắc dĩ cười cười .\nKhông nghĩ tới , tại bọn hắn thời không đả sinh đả tử phương bắc dị tộc , ở đời sau , vậy mà trở thành chính mình người .\n...\nLớn minh .\nVĩnh Lạc bảy năm .\n“ Ân ?!”\nChu Lệ một mặt mộng nhìn xem màn trời .\n“ Cái này ?! Trở thành người mình ?”\nBên cạnh Chu Cao Sí cũng có một chút mộng , nhưng quen thuộc chính trị hắn , rất nhanh liền đổi qua cong .\n“ Phụ thân , không kỳ quái ...”\n“ Dù sao , trong lịch sử Ngũ Hồ thời kì , còn có thời Ngũ Đại kỳ , đều có ví dụ như vậy ...”\nChu Cao Sí bình tĩnh lại , sau đó tiếp tục cho Chu Lệ phân tích nói :\n“ Khi phương bắc dị tộc không còn là uy hiếp , vì phương bắc lâu dài yên ổn , người đời sau , nhất định sẽ đem phương bắc đặt vào bản đồ .”\nNghe nói như thế , Chu Lệ cũng tỉnh táo suy tư .\n“ Quả thật là như thế ...”\n“ Đến nỗi chúng ta bây giờ sao ? Nên đánh y nguyên vẫn là phải đánh , dù sao ...”\nChu Cao Sí gương mặt đồng ý , không có phản đối Chu Lệ .\nTuy nói hậu thế dung hợp , nhưng lúc này ? Nên đánh , y nguyên vẫn là sẽ đánh .\nDù sao đối với hậu thế tới nói , phương bắc dị tộc kỵ binh không phải uy hiếp , không đại biểu hiện tại phương bắc dị tộc kỵ binh không phải uy hiếp .\n...\nĐại Đường .\nTrinh Quán bảy năm .\n“ Dung hợp sao ?”\nLý Thế Dân nghe màn trời giảng thuật , không chút nào cảm thấy kỳ quái , bởi vì tại bọn hắn phía trước , hiếu Văn Đế liền làm qua chuyện như vậy .\n“ Nhưng , vì cái gì ta cảm giác có một chút không đúng ?”\nTại nghe xong màn trời phía trên , Lý Ân Phàm giảng thuật sau đó , Lý Thế Dân xem như hoàng đế , kỳ thực bản năng cảm thấy có chỗ nào không đúng .\nGiống như có đồ vật gì ngạnh ở trong lòng .\n“ Huyền linh , ngươi cảm thấy màn trời nói lời , có chỗ nào không đúng sao ?”\nPhòng Huyền Linh lắc đầu , sau đó trầm tư một hồi nói :\n“ Bệ hạ , thần mặc dù cũng phát giác được có chỗ nào không đúng , nhưng chính là nói không nên lời .”\nBên cạnh mấy vị đại thần , cũng đều gật đầu một cái .\nBọn hắn nghe xong Lý Ân Phàm giảng thuật , cũng cảm giác có chỗ nào không đúng , nhưng chính là nói không tốt , là nơi nào không đúng .\n“ Không nên nha , tất nhiên chúng ta đều có thể phát giác được không đúng , vậy vì sao hơn một ngàn năm sau đó hậu thế , bọn hắn không có phát giác được đâu ?”\n“ Đây là bởi vì cái gì ?”\nLý Thế Dân mặc dù nói không tốt là nơi nào không đúng , nhưng ở hắn xem ra , tất nhiên bọn hắn đều có thể phát giác được , vì cái gì hậu thế , không phát hiện được ?\nNghĩ tới đây , Lý Thế Dân có một loại dự cảm rất xấu , có thể lại không biết dự cảm kia kết quả thế nào mà đến .\n...\nHán triều .\nNguyên thú 4 năm .\n“ Cái này ...”\nLưu Triệt cùng Vệ Thanh hai người nhìn nhau không nói gì , không biết nên nói cái gì .\nTại bọn hắn cái này thời đại đả sinh đả tử phương bắc dị tộc , ngươi nói cho bọn hắn , hậu thế vậy mà dung hợp ?\nVậy mà trở thành chính mình người ?\n“ Bệ hạ , còn đánh sao ?”\nVệ Thanh nhìn xem Lưu Triệt , thận trọng hỏi .\n“ Đánh , vì cái gì không đánh ?”\n“ Nếu như bọn hắn lúc này nguyện ý chủ động xuống ngựa đầu hàng , để cho vương đình bên trong người , toàn bộ ở đến Trường An bên trong tới , trẫm sẽ bỏ qua bọn hắn .”\n“ Nhưng ngươi cho rằng , đám kia sợ uy mà không có đức dị tộc , sẽ làm như vậy sao ?”\nVệ Thanh rất là quả quyết lắc đầu .\n......', 'output\\mp3\\Màn Trời Quyền Lực Diễn Biến Cùng Truyền Thừa\\0030_Thứ 30 chương Dài thành.mp3', '2026-09-01T12:11:20.028103+00:00', 'completed', 'completed', 8117, 8117),
	(36, 7, '7644001483154801176', 31, 'Thứ 31 chương Tần quốc hậu cung', 'Thứ chương Tần quốc hậu cung\nHiện đại thời không .\n“ Chênh lệch thời gian không nhiều lắm .”\nGần tới trưa , Lý Ân Phàm mang theo Thủy Hoàng Doanh Chính cùng Mông Điềm tùy tiện ăn một điểm cơm trung , sau đó đánh liền một cái xe , đến Đại Khố Xái .\n“ Lý lão sư , ngươi đã đến , bên trong không sai biệt lắm đã chuẩn bị xong .”\n“ Đây là hai tấm studio phiếu , ngươi cầm .”\nĐến Đại Khố Xái , một vị nhân viên công tác trực tiếp đi tới , đem hai tấm phiếu đưa cho Lý Ân Phàm .\n“ Tốt , cảm tạ ...”\nTiếp nhận phiếu , Lý Ân Phàm ở trong nội tâm , cho cái kia biên điểm một cái khen , hắn vốn đang tại buồn rầu , làm như thế nào mang Thủy Hoàng Doanh Chính cùng Mông Điềm hai người đi vào đâu .\n“ Chúng ta đi vào ngồi một hồi , tiếp đó liền bắt đầu quay tiết mục .”\nMang theo hai người đi vào một công việc ở giữa , Lý Ân Phàm lấy điện thoại cầm tay ra .\n“ Các ngươi đến chưa ?”\nLý Ân Phàm trước tiên cho Trần Xuyên Phú gọi điện thoại .\n“ Sắp tới , ta mang theo Ngụy Gia cùng Lương Phong hai người đâu .”\n“ Hảo .”\n...\nHiện đại thời không .\n“ Cái này !”\nLý Ân Phàm tại Đại Khố Xái cửa ra vào nhận được 3 người , sau đó mang theo 3 người đi vào phòng làm việc .\n“ Chúng ta cần trước tiên đối với vừa xuống đài bản sao ?”\nĐi vào phòng làm việc , chờ 3 người ngồi xuống về sau , Lý Ân Phàm nhìn xem 3 người hỏi .\n“ Đối với kịch bản sao ?”\n3 người nhìn nhau một cái , sau đó Trần Xuyên Phú trước khi nói ra :\n“ Xác định một chút chủ thể mạch lạc a , những thứ khác chúng ta giống như nói chuyện phiếm , tự do phát huy , muốn nói cái gì , nâng một chút tay là được .”\nLời này vừa ra , ba người khác đều gật đầu một cái , biểu thị tán đồng .\n“ Tiết mục nếu là 《 Quyền lực diễn biến cùng truyền thừa 》, vậy chúng ta ban đầu , trước hết đem quyền lực sinh ra nói rõ a .”\n“ Tiếp đó một mực giảng đến Tần triều thời kì cuối , đến Tần triều sụp đổ liền vừa vặn kết thúc .”\n“ Đi !”\nLý Ân Phàm không có ý kiến gì , chỉ cần xác định rõ chủ thể dàn khung cùng mạch lạc , giống loại này tiết mục , giải quyết rất dễ .\nDù sao Lý Ân Phàm biết , tiết mục này căn bản cũng không phải là cho người hiện đại nhìn , là cho Cổ Nhân nhìn .\nBên kia tất nhiên tìm được hắn , Lý Ân Phàm xem chừng , cũng là ý nghĩ như vậy .\nCho nên ...\n“ Đến trên đài , có cái gì thì nói cái đó là được rồi , không cần che lấp ...”\nLý Ân Phàm nhìn xem 3 người , nghiêm túc nói bổ sung .\n“ Có cái gì thì nói cái đó ?”\nLương Phong một mặt kinh ngạc nhìn Lý Ân Phàm , hai người khác , Ngụy Gia cùng Trần Xuyên Phú cũng là như thế .\n“ Ân , có cái gì thì nói cái đó , cái kéo lớn có thể giải quyết .”\nVì tiêu trừ 3 người nỗi lo về sau , Lý Ân Phàm nói thẳng ra cái kéo lớn .\n“ Đi , vậy chúng ta không có ý kiến gì .”\n3 người đều là gật đầu một cái .\n“ Đúng , giới thiệu cho các ngươi một chút , đây là cùng ta cùng tới hai cái bằng hữu .”\nLý Ân Phàm đi đến Thủy Hoàng Doanh Chính cùng Mông Điềm trước mặt hai người , cho 3 người giới thiệu nói .\n“ Vị này , Triệu Chính , chính trực đang .”\n“ Vị này , Cơ Điềm .”\n“ Các ngươi tốt !”\nThủy Hoàng Doanh Chính cùng Mông Điềm hai người học mấy ngày nay xem ra chào hỏi phương thức , hướng về 3 người chào hỏi .\n“ Ách ... Các ngươi tốt .”\n“ Trần Xuyên Phú ” “ Lương Phong Ngụy ” “ gia ”\n3 người từng cái tự giới thiệu tên của mình .\nChờ giới thiệu xong , đám người lần nữa ngồi xuống .\nNgồi xuống về sau , Trần Xuyên Phú trước tiên phát giác vấn đề .\n‘ Cái này không phải là hắn có thể nhận biết a ?’\nQuen thuộc quan trường Trần Xuyên Phú rất dễ dàng liền nhìn ra Thủy Hoàng Doanh Chính cùng Mông Điềm trên thân hai người kèm theo một cỗ uy nghiêm khí chất .\nĐặc biệt là tự giới thiệu vì Triệu Chính tên nam tử kia .\nPhải biết , Trần Xuyên Phú nhận biết Lý Ân Phàm lâu như vậy đến nay , đã rất quen thuộc Lý Ân Phàm , biết hắn là người nào .\nLàm việc ở đâu , trong nhà có người nào , cũng đã rất rõ ràng .\nNhưng là Triệu Chính nam tử như vậy , Trần Xuyên Phú chính mình , cũng chỉ là tại đã từng , theo bậc cha chú xa xa nhìn thấy qua mang theo dạng này khí chất người .\nSau đó , Trần Xuyên Phú dùng mang theo ánh mắt kinh ngạc liếc mắt nhìn Lý Ân Phàm .\n‘ Hơn nữa , bên cạnh cái kia tên là Cơ Điềm nam tử , cũng ẩn ẩn vì Triệu Chính cầm đầu ...’\nNghĩ tới đây , Trần Xuyên Phú đột nhiên tại nội tâm lắc đầu nói :\n“ Quen thuộc lại tới , bọn hắn là người nào , quản ta chuyện gì ?”\nTrần Xuyên Phú nội tâm cảm thấy hết sức buồn cười , chính mình cuối cùng sẽ theo thói quen sẽ đi đoán đối phương xuất thân cái gì .\n“ Quen thuộc thật không tốt ...”\nTrong nội tâm , Trần Xuyên Phú cảnh cáo chính mình một chút .\n“ Mấy vị lão sư , đã chuẩn bị xong .”\nĐúng lúc này , phòng làm việc cửa phòng mở ra , một cái nhân viên công tác , đi đến , nhìn xem Lý Ân Phàm nhẹ nói .\n“ Hảo , chúng ta cái này liền đến .”\n...\nHiện đại thời không .\nLý Ân Phàm đứng tại trên sân khấu , chờ Trần Xuyên Phú , Ngụy Gia , Lương Phong 3 người ngồi xuống sau đó , đi đến bọn hắn bên cạnh nói chuyện một hồi .\nBa người bọn họ vị trí tại trên võ đài .\nBởi vì tiết mục này là nói chuyện phiếm , cho nên liền không có khác lịch sử loại tiết mục nghiêm túc như vậy .\nCùng 3 người nói chuyện một hồi sau đó , Lý Ân Phàm lại tìm đến dưới đài , Thủy Hoàng Doanh Chính cùng Mông Điềm bên cạnh hai người , cùng bọn hắn hai người nói một hồi .\n“ Tiên sinh , đây là ?”\nMông Điềm nhìn xem Lý Ân Phàm , hơi nghi hoặc một chút không hiểu .\n“ Đây là hậu thế quay tiết mục , các ngươi có thể lý giải thành , màn trời như thế .”\nNghe nói như thế , Thủy Hoàng Doanh Chính cùng Mông Điềm hai người đều là gật đầu một cái .\nNói màn trời loại kia , hai người liền đã hiểu .\nLý Ân Phàm sớm nhất ý nghĩ , kỳ thực trên đài là năm người hay là 6 người .\nTrong đó một hai người , có thể để Cổ Nhân đi lên .\nNhưng cuối cùng lại suy nghĩ một chút , Cổ Nhân đi lên nói cái gì đó ? Cùng hiện đại người thảo luận ?\nNgười hiện đại thỉnh thoảng bốc lên một chút hiện đại từ ngữ , còn có bọn hắn không hiểu rõ hậu thế triều đại , bọn hắn như thế nào đi đón ?\nDạng này tiết mục truyền ra đi , sợ là sẽ phải bị chửi tìm một hai cái mù chữ đến đây đi ?\nDù là cũng chỉ là màn trời dạng này thả ra , đời sau triều đại chỉ sợ đều biết chế giễu một phen .\nCho nên Lý Ân Phàm cuối cùng liền từ bỏ ý nghĩ này , chỉ chuẩn bị để cho Cổ Nhân mở rộng một chút tầm mắt .\nChờ Lý Ân Phàm cùng Thủy Hoàng Doanh Chính cùng Mông Điềm nói chuyện phiếm xong sau , nhìn chung quanh một vòng .\nGhi âm trong sảnh , ngoại trừ nhân viên công tác , chỉ có mấy người bọn họ , dưới đài không có cái gì người xem .\n“ Như vậy cũng tốt ...”\nLý Ân Phàm gật đầu một cái , sau đó đi lên đài .\nMà đúng lúc này , một cái nhân viên công tác đi đến Lý Ân Phàm trước mặt , nhẹ nói :\n“ Lý lão sư , thiết bị điều chỉnh xong .”\nLý Ân Phàm gật đầu một cái , đi đến Trần Xuyên Phú 3 người trước mặt , đối bọn hắn nói :\n“ Chuẩn bị bắt đầu quay tiết mục .”\n“ Hảo .”\n3 người đều là gật đầu một cái .\nSau đó , Lý Ân Phàm nhìn về phía camera vị trí , hiện trường đạo diễn hướng về phía Lý Ân Phàm đánh một cái động tác .\n“ Hảo ...”\n“ Người xem các bằng hữu , hoan nghênh xem 《 Lịch Sử mặt đối mặt 》”\n......\nHiện đại thời không .\n“ Đây là một cái lịch sử phổ cập khoa học loại tiết mục , đang tán gẫu bên trong , phổ cập lịch sử , nhìn lại lịch sử , học tập lịch sử .”\n“ Ta là người chủ trì Lý Ân Phàm .”\n“ Hiện trường 3 người , là ta mời đến cùng một chỗ nói chuyện phiếm lịch sử bằng hữu .”\n“ Trần Xuyên Phú .”\nTrần Xuyên Phú đứng lên , hướng về camera vẫy vẫy tay .\n“ Lương Phong .”\nTiếng nói rơi xuống , Lương Phong cũng đứng lên , hướng về phía camera lên tiếng chào hỏi .\n“ Ngụy Gia .”\nSau đó , Ngụy Gia đứng lên , nhìn xem camera , lên tiếng chào hỏi .\n“ Đây là một cái không còn nghiêm túc lịch sử phổ cập khoa học loại tiết mục , cho nên , chúng ta không có dĩ vãng cái chủng loại kia lễ nghi phiền phức .”\nNói xong , Lý Ân Phàm đặt mông ngồi ở trên 3 người cái ghế bên cạnh .\n“ Chúng ta tiết mục chủ mạch lạc , là quyền lực diễn biến cùng truyền thừa .”\n“ Dùng người như vậy mạch lạc , đến phân tích cổ đại mỗi hoàng đế lịch sử .”\n“ Mà nói đến hoàng đế , thì không khỏi không xách chúng ta lịch sử thượng đệ nhất vị hoàng đế .”\n“ Tần Thủy Hoàng Doanh Chính !”\nLý Ân Phàm nói đến đây , nhìn xem Trần Xuyên Phú 3 người , cười hỏi :\n“ Như vậy , ta có một cái vấn đề , trong lịch sử Tần Thủy Hoàng Doanh Chính , quyền lực của hắn , thật sự như chúng ta trong tưởng tượng nói như vậy một không hai , quyền hạn dị thường khổng lồ sao ?”\nNghe nói như thế , dưới đài Thủy Hoàng Doanh Chính híp mắt , sau đó nghiêm túc .\nBên cạnh Mông Điềm cũng tò mò nhìn xem trên đài Lý Ân Phàm bọn người .\nTrần Xuyên Phú 3 người nhưng là nhìn nhau một cái , sau đó , từ Trần Xuyên Phú cầm lấy đặt ở trước mặt microphone , nhẹ nói :\n“ Nó thực hiện đại rất nhiều người có một loại hiểu sai .”\n“ Cho rằng cổ đại hoàng đế , bọn hắn tựa hồ thật sự miệng ngậm thiên hiến , nói một không hai , một câu nói ra ngoài , khắp thiên hạ tất cả mọi người đều sẽ dựa theo ý chí của bọn hắn làm việc .”\n“ Đây là sai lầm !”\n“ Mỗi một cái hoàng đế , chúng ta muốn nhìn bọn hắn vị trí thời kì , mới có thể phán đoán quyền lực của bọn hắn phải chăng khổng lồ .”\n“ Giống như chúng ta bây giờ thảo luận Tần Thủy Hoàng Doanh Chính .”\n“ Chúng ta có thể nói , lúc còn trẻ hắn , quyền hạn , cùng tuổi già hắn , có thể giống nhau sao ?”\nTrần Xuyên Phú nói đến đây , lắc đầu nói :\n“ Chắc chắn là không được !”\nBên cạnh Lương Phong cùng Ngụy Gia hai người đều gật đầu một cái .\n“ Kỳ thực tại rất nhiều người xem ra , Tần Thủy Hoàng Doanh Chính thượng vị , đã chứng minh hắn dường như là thiên mệnh sở quy , hắn thượng vị sau đó , quyền hạn liền nhất định phi thường lớn .”\n“ Cái này kỳ thực cũng là sai lầm .”\nLương Phong cầm ống nói lên , tiếp lấy Trần Xuyên Phú lời nói tiếp tục nói .\n“ Đầu tiên điểm thứ nhất , rất nhiều người không để ý đến vì cái gì lúc đó là Doanh Chính thượng vị ? Mà không phải những người khác ?”\n“ Tại sao có hắn thượng vị đâu ?”\n“ Ở đây rất nhiều người trong ấn tượng , đã cảm thấy là Doanh Chính thân là ngay lúc đó Thái tử , vì cái gì không phải hắn thượng vị ?”\n“ Ý nghĩ này kỳ thực là sai lầm , Doanh Chính , chưa bao giờ được lập làm Thái tử !”\nLời này vừa ra , tất cả mọi người tại chỗ đều gật đầu một cái .\n“ Doanh Chính mặc dù tại lúc đó là trưởng tử , nhưng ở phụ thân hắn , Tần Trang Tương vương thắng dị nhân thượng vị sau đó , chưa bao giờ bị lập qua Thái tử .”\n“ Đến nỗi nói thực tế hành sử Thái tử quyền năng ? Doanh Chính thượng vị lúc , còn chưa đầy mười ba tuổi , như thế nào đi hành sử Thái tử quyền năng ?”\n“ Có thể có người sẽ nhớ , tất nhiên Doanh Chính thân là trưởng tử , cũng cần phải nhất định là hắn thượng vị a ?”\nLương Phong nói đến đây , lắc đầu nói :\n“ Tần Trang Tương vương , cũng chính là Doanh Chính phụ thân , thắng dị nhân , hắn là làm qua Thái tử !”\n“ Ngươi có thể nói Doanh Chính là người thừa kế hợp pháp thứ nhất , nhưng ngươi không thể nói nhất định là hắn thượng vị .”\n“ Nếu như có thể đơn giản hiểu như vậy , vậy vì sao về sau Phù Tô cùng Hồ Hợi ...”\nĐiểm này , tại chỗ những người khác , bao quát Lý Ân Phàm cũng là gật đầu tán đồng .\nBởi vì cái này rất dễ lý giải , có làm hay không Thái tử , tại cổ đại , là phi thường mấu chốt .\nĐiểm này rất nhiều người kỳ thực không để ý đến , cho rằng trưởng tử liền chắc chắn có thể kế thừa thượng vị , nhất định nên kế thừa thượng vị .\nCũng không nói về sau thời kì , chỉ nói Xuân Thu Chiến Quốc thời kì , trưởng tử thuận vị kế thừa người , kỳ thực cũng không nhiều .\nVề sau Đại Nhất Thống Vương Triều bắt đầu xuất hiện , trưởng tử có thể thuận vị kế thừa , thì càng ít .\n“ Chúng ta lại nhìn , thắng dị nhân phụ thân , An quốc quân , cũng chính là về sau Tần Hiếu Văn Vương , con của hắn có bao nhiêu cái ? Hơn 20 cái !”\n“ Nhưng vì sao là không được sủng ái hắn thượng vị ? Bởi vì Tần Hiếu Văn Vương ngay lúc đó vương hậu Hoa Dương phu nhân , không có dòng dõi ! Doanh dị nhân nhận Hoa Dương phu nhân vì mẫu , cho nên mới thượng vị Thái tử .”\n“ Thượng vị Thái tử sau đó , tại Tần Hiếu Văn Vương khi chết , thắng dị nhân , mới có thể danh chính ngôn thuận kế thừa vương vị .”\nNói đến đây , Lương Phong nhìn xem mấy người , nhẹ giọng hỏi :\n“ Vậy cái này thời điểm , vấn đề liền đến , thắng dị nhân thượng vị sau đó , vì cái gì không đem Doanh Chính lập làm Thái tử ?”\n“ Nếu như nói thắng dị nhân , hắn vương hậu là Triệu Cơ , chỉ có Doanh Chính một cái dòng dõi , một cái danh chính ngôn thuận hài tử , hắn vì cái gì không đem Doanh Chính lập làm Thái tử ?”\n“ Có thể có người nghĩ tới , về sau thành kiểu phản loạn , đã chứng minh một sự kiện , Tần Trang Tương vương , thắng dị nhân , con của hắn không chỉ một !”\n“ Không chỉ Doanh Chính , một đứa bé này .”\n“ Hơn nữa , rất nhiều người tại ở trong đó , còn không để ý đến một sự kiện !”\n“ Doanh Chính mẫu thân , Triệu Cơ , cũng không có làm qua vương hậu , cũng chính là thắng dị nhân vương hậu !”\nĐiểm này bị Lương Phong đưa ra , tại chỗ như Lý Ân Phàm bọn người , đều như có điều suy nghĩ .\n“ Cho nên , ở đây chúng ta lại có một vấn đề , thắng dị nhân vương hậu , lại đến cùng là ai ?”\n“ Mà liền vấn đề này , kỳ thực là có thể giải đáp .”\n“ Thắng dị nhân vương hậu , nhất định là Sở quốc nữ tử , đây là không nghi ngờ chút nào .”\n“ Vì cái gì ?”\n“ Quen thuộc Tần quốc lịch sử bằng hữu hẳn phải biết , từ mị Bát Tử , cũng chính là Tần Quốc Tuyên Thái hậu sau đó , Tần quốc hậu cung , vẫn luôn từ Sở Hệ thế lực độc quyền .”\n“ Mị Bát Tử , cũng chính là tuyên Thái hậu , Sở quốc Đan Dương người , Sở quốc quý tộc chi nữ .”\n“ Kế tiếp , Diệp Dương sau , tính danh không rõ , Sở quốc tôn thất nữ , Tần chiêu Tương Vương vương hậu .”\n“ Hoa Dương phu nhân , Sở quốc quý tộc , Hùng tính Mễ thị .”\nNói xong điểm này sau đó , Lương Phong Thần bí nhìn xem camera cười một cái nói :\n“ Đại gia đoán một chút , Sở quốc thế lực , tại Tần quốc hậu cung , thế lực có nhiều khổng lồ ?”\nKhông đợi bao lâu , Lương Phong trực tiếp cử ra ví dụ .\n“ Tần Hiếu Văn Vương , thắng trụ , hắn chân chính mẫu thân là Đường Thái hậu , không phải Diệp Dương sau .”\n“ Tần Trang Tương vương , hắn chân chính mẫu thân , là Hạ Cơ , không phải Hoa Dương phu nhân .”\nCái này , liên tục hai vị quốc quân , đều không phải là con trai trưởng xuất sinh , đều có thể kế thừa vương vị ?\nCái này Tần quốc hậu cung sở hệ thế lực , rốt cuộc lớn bao nhiêu ?\nTại chỗ Lý Ân Phàm cùng Ngụy Gia bọn người , đều toát ra ý nghĩ này .\n“ Cho nên , Hoa Dương phu nhân có thể hay không cho thắng dị nhân an bài một cái Sở quốc nữ tử ? Nhất định sẽ !”\n“ Đây tuyệt đối là không nghi ngờ chút nào !”\n“ Sở hệ thế lực , không có khả năng đem hậu cung khổng lồ như vậy quyền hạn nhường cho những người khác !”\n“ Thời điểm đó hậu cung thế lực , nhưng là chân chính có thể trên triều đình đặt chân , còn không có về sau ngoại thích không thể tham gia vào chính sự một thuyết này .”\n“ Cho nên , cứ như vậy , Triệu Cơ cũng rất có thuyết pháp !”\n“ Ngoại trừ Triệu Cơ có thuyết pháp , còn có ai ? Doanh Chính !”\n......', 'output\\mp3\\Màn Trời Quyền Lực Diễn Biến Cùng Truyền Thừa\\0031_Thứ 31 chương Tần quốc hậu cung.mp3', '2026-09-01T13:12:48.309930+00:00', 'completed', 'completed', 14758, 14758),
	(37, 7, '7644747819827331608', 32, 'Thứ 32 chương Thắng dị nhân, thắng tử sở', 'Thứ chương Thắng dị nhân , thắng Tử Sở\nHiện đại thời không .\n“ Chúng ta từ một điểm này đi phân tích , có thể biết cái gì ? Liền có thể rất đơn giản biết , lúc đó thắng dị nhân thượng vị sau đó , nhất định có một cái vương hậu , Sở Hệ nữ tử .”\n“ Dù sao giống như phía trước nói , nếu như Triệu Cơ là vương hậu , cái kia Doanh Chính nhất định là sẽ bị lập làm Thái tử .”\n“ Mà tất nhiên thắng dị nhân thượng vị 3 năm , Doanh Chính cũng không có được lập làm Thái tử , cái kia ngay lúc đó thắng dị nhân đang chờ cái gì đâu ?”\nLương Phong dừng một chút , nhìn xem mấy người , nhẹ nói :\n“ Đang chờ cái kia Sở Hệ vương hậu , sinh con !”\n“ Bao quát lúc đó hậu cung Sở Hệ thế lực , các nàng đều đang đợi cái này Sở Hệ vương hậu sinh con .”\n“ Nhưng chúng ta biết , thắng dị nhân , cũng chính là Tần Trang Tương vương , chỉ nhậm chức hơn ba năm một điểm thời gian .”\n“ Tại Trang Tương Vương 3 năm ( Phía trước năm ) tháng năm , chết bệnh , hưởng thọ ba mươi lăm tuổi .”\n“ Tần Trang Tương vương thắng dị nhân chết bệnh sau đó , Doanh Chính thượng vị .”\nNói đến đây , Lương Phong điều chỉnh một chút tư thế , nhẹ giọng hỏi :\n“ Ở đây , chúng ta liền trở về lại vấn đề kia , tại sao là Doanh Chính thượng vị ?”\n“ Nếu như có thể vuốt rõ ràng trong này lôgic , hẳn là có thể biết tại sao là Doanh Chính thượng vị .”\nSau đó , Lương Phong nhìn về phía máy quay phim , nhẹ nói :\n“ Nhưng , rất nhiều người bây giờ trong đầu có thể còn rất hỗn loạn , vuốt mơ hồ quan hệ trong đó .”\n“ Vậy chúng ta hỏi lại một vấn đề , đại gia liền biết tại sao là Doanh Chính thượng vị .”\n“ Vấn đề này là cái gì ? Tần Hiếu Văn Vương thắng trụ , nhiều hài tử như vậy , tại sao là thắng dị nhân thượng vị ?”\n“ Có người nhất định sẽ nói , là thắng dị nhân nhận Hoa Dương phu nhân làm mẫu thân , mà Hoa Dương phu nhân lại không có dòng dõi , cho nên mới để cho thắng dị nhân làm Thái tử .”\n“ Thật là có đơn giản như vậy sao ?”\nLý Ân Phàm đối với cái này nhưng là lắc đầu , hồi đáp :\n“ Nếu quả thật đơn giản như vậy , cái kia Tần Hiếu Văn Vương , cũng chính là thắng trụ những hài tử khác , vì cái gì không nhận Hoa Dương phu nhân làm mẫu thân ?”\n“ Là không muốn ? Hay là thế nào ? Hoa Dương phu nhân lúc đó thế nhưng là Tần quốc vương hậu , ai cũng biết nhận Hoa Dương phu nhân làm mẫu thân , liền có thể thượng vị làm Thái tử .”\n“ Trong cái này hơn 20 đứa bé này , liền không có một cái có ý nghĩ này ?”\nMọi người ở đây đều là gật đầu , tán đồng điểm này .\nSau đó , Lương Phong nói tiếp :\n“ Doanh Dị Nhân là thế nào lên chức ? Chúng ta nhìn sách sử là thế nào ghi lại .”\n“ Nói là thắng dị nhân tại làm hạt nhân trong lúc đó , làm quen Lữ Bất Vi .”\n“ Lúc đó thân là vệ quốc đại thương nhân Lữ Bất Vi , tại Hàm Đan làm ăn , biết dị nhân tình huống , cho là hắn “ Đầu cơ kiếm lợi ”, cho nên quyết định tiến hành một lần chính trị đánh bạc .”\n“ Lữ Bất Vi thế là lấy ra năm trăm kim đưa cho dị nhân , xem như sinh hoạt hàng ngày cùng kết giao khách mời chi dụng .”\n“ Sau đó đâu ? Lại lấy ra năm trăm kim mua quý hiếm đồ chơi , chính mình mang theo đồ vật đi Tần quốc du thuyết , trước tiên bái kiến Hoa Dương phu nhân đệ đệ Dương Tuyền Quân cùng tỷ tỷ , đem mang tới đồ vật hết thảy hiến tặng cho Hoa Dương phu nhân .”\n“ Lữ Bất Vi thuận tiện nói về dị nhân thông minh hiền năng , kết giao chư hầu khách mời , khắp thiên hạ , thường thường nói “ Ta dị nhân đem phu nhân nhìn thành thân mẫu đồng dạng , ngày đêm thút thít tưởng niệm Thái tử cùng phu nhân .”\n“ Hoa Dương phu nhân cao hứng phi thường . Sau đó Lữ Bất Vi thừa cơ lại để cho Hoa Dương phu nhân đệ đệ thuyết phục Hoa Dương phu nhân nhận dị nhân vì con nuôi .”\n“ Cuối cùng , Hoa Dương phu nhân liền thừa dịp An Quốc Quân thuận tiện thời điểm , uyển chuyển nói tới tại Triệu quốc làm con tin dị nhân vô cùng có tài năng , người lui tới đều khen ngợi hắn . Tiếp lấy sẽ khóc nói : “ Ta may mắn có thể bổ khuyết hậu cung , nhưng vô cùng tiếc nuối là không có nhi tử , ta hi vọng có thể lập dị nhân vì người thừa kế , để ngày sau ta có cái dựa vào .”\n“ An Quốc Quân , cũng chính là thắng trụ đáp ứng , liền cùng phu nhân khắc xuống ngọc phù , quyết định lập dị nhân vì người thừa kế , An Quốc Quân cùng Hoa Dương phu nhân ban thưởng tiễn đưa hậu lễ cho dị nhân , đồng thời thỉnh Lữ Bất Vi làm lão sư của hắn , bởi vậy dị nhân danh tiếng tại trong chư hầu càng lúc càng lớn .”\nNói xong những thứ này , Lương Phong lại nói tiếp :\n“ Tần Chiêu Tương vương năm mươi năm , Tần Quốc phái đại tướng Vương Nghĩ tỷ lệ sư vây công Triệu quốc đô thành Hàm Đan , xem như trả thù , triệu Hiếu Thành vương muốn giết chết dị nhân cho hả giận .”\n“ Dị nhân cùng Lữ Bất Vi mưu đồ bí mật , lấy ra 300 kg kim hối lộ thủ thành quan lại chạy ra Triệu quốc , thông qua xuất chinh Tần quân trở về Tần quốc .”\n“ Bởi vì Hoa Dương phu nhân là người nước Sở , Lữ Bất Vi trước đó gọi về quốc sau dị nhân xuyên Sở quốc trang phục gặp mặt phu nhân . Hoa Dương phu nhân quả nhiên rất là xúc động , chính thức thu dị nhân làm nghĩa tử , đồng thời đổi tên Tử Sở .”\n“ Thắng dị nhân , cũng liền đổi tên là chúng ta hậu thế quen thuộc thắng Tử Sở .”\nNói đến đây , Lương Phong nhìn xem camera , ý vị thâm trường nói :\n“ Thắng dị nhân thượng vị , liền thật sự như trên sử sách ghi lại đơn giản như vậy sao ?”\n“ Lữ Bất Vi du thuyết Hoa Dương phu nhân , Hoa Dương phu nhân cao hứng phi thường , tiếp đó cũng đồng ý ?”\n“ Chúng ta lại cẩn thận suy tính một chút , Lữ Bất Vi nhìn thấy Hoa Dương phu nhân , là thế nào nói ?”\n“ Ta dị nhân đem phu nhân nhìn thành thân mẫu đồng dạng , ngày đêm thút thít tưởng niệm Thái tử cùng phu nhân .”\nTrần Xuyên Phú lúc này gật đầu một cái , bắt đầu nói tiếp nói :\n“ Ở đây , kỳ thực chính là cho chính trị hứa hẹn .”\n“ Ta thắng dị nhân nếu như thượng vị , sẽ tôn Hoa Dương phu nhân , tôn sở hệ thế lực .”\n“ Mà Hoa Dương phu nhân vì cái gì cao hứng phi thường ?”\n“ Bởi vì , ngay lúc đó thắng dị nhân , thân là hạt nhân , phía sau hắn , không có bất kỳ cái gì thuộc về Tần quốc thế lực .”\n“ Lữ Bất Vi cũng chính là coi trọng điểm này , cho nên mới cho rằng thắng dị nhân “ Đầu cơ kiếm lợi ”!”\n“ Tần quốc vương hậu Hoa Dương phu nhân không có dòng dõi .”\n“ Thắng dị nhân thân là thắng trụ hài tử , là hạt nhân , sau lưng không có bất kỳ cái gì thế lực .”\nNói đến đây , Trần Xuyên Phú vỗ vỗ hai tay , nhún vai một cái nói :\n“ Đây chính là “ Đầu cơ kiếm lợi ”!”\n“ Cái này cũng là vì cái gì thắng trụ khác hơn 20 đứa bé , Hoa Dương phu nhân một cái đều không coi trọng nguyên nhân !”\n“ Bởi vì những hài tử khác , đều tại Tần quốc lớn lên , sau lưng hoặc nhiều hoặc ít đều có Tần quốc bản thổ thế lực .”\n“ Mà thắng dị nhân , vì cái gì vừa về tới Tần quốc , trực tiếp xuyên Sở quốc trang phục gặp mặt Hoa Dương phu nhân .”\n“ Ý tứ trong này , chính là ta thắng dị nhân , không có quên lời hứa của ta , phu nhân kia đâu ? Ngươi quên rồi sao ?”\n“ Hoa Dương phu nhân đương nhiên chưa quên , cho nên trực tiếp thu thắng dị nhân làm nghĩa tử , trực tiếp đem Doanh Dị Nhân tên đổi thành thắng Tử Sở !”\n“ Tử Sở ...”\n“ Sở ...”\nTrần Xuyên Phú nói đến đây , cười cười sau , tiếp tục nói :\n“ Ý tứ trong này , kỳ thực cũng rất rõ ràng .”\nBên cạnh Lương Phong , tiếp lấy Trần Xuyên Phú mà nói , nhẹ nói :\n“ Đúng vậy , trong này hết sức rõ ràng , cũng đã chứng minh Lữ Bất Vi chính xác lợi hại , thấy rõ ràng trong này cục thế chính trị .”\n“ Biết Hoa Dương phu nhân không có dòng dõi , lo lắng sau đó sở hệ thế lực sẽ ở Tần quốc hướng phía trên xuống dốc .”\n“ Cho nên , nhìn thấy Doanh Dị Nhân sau đó , lập tức liền nghĩ đến Doanh Dị Nhân lại có lớn vô cùng ưu thế .”\n“ Đây chính là có đôi khi trong chính trị vô cùng làm cho người ta bất đắc dĩ địa phương .”\n“ Ngươi có rất nhiều thời điểm , ngược lại là ngươi không có gì cả thời điểm .”\n“ Mà ngươi không có gì cả thời điểm , lại vừa vặn là ngươi nhận được nhiều nhất thời điểm .”\nLương Phong nói đến đây , nhảy chuyển rồi một lần chủ đề nói :\n“ Trong lịch sử có bao nhiêu hoàng đế , là như thế này lên chức ?”\n“ Chúng ta quen thuộc Hán Linh Đế Lưu Hoành , Gia Tĩnh Đế Chu Hậu Thông , tại sao có bọn hắn thượng vị ? Bởi vì bọn hắn sau lưng không có bất kỳ cái gì thế lực !”\nNói xong điểm này , Lương Phong quay đầu nhìn về phía máy quay phim , nhẹ giọng hỏi :\n“ Cho nên , chúng ta hẳn phải biết , vì cái gì tại lúc đó , là Doanh Chính thượng vị a ?”\n......', 'output\\mp3\\Màn Trời Quyền Lực Diễn Biến Cùng Truyền Thừa\\0032_Thứ 32 chương Thắng dị nhân, thắng tử sở.mp3', '2026-09-01T13:12:54.049348+00:00', 'completed', 'completed', 8186, 8186),
	(38, 7, '7644747962475627032', 33, 'Thứ 33 chương Cơ thiếp', 'Thứ chương Cơ thiếp\nHiện đại thời không .\n“ Đến nỗi bây giờ rất nhiều người nói , thắng dị nhân vô cùng yêu thích Doanh Chính ? Vô cùng yêu thích Triệu Cơ ?”\n“ Sách sử phía trên thế nhưng là một điểm không có cho thấy chuyện này .”\n“ Thắng dị nhân trốn về Tần quốc thời điểm , hắn quản không để ý Triệu Cơ cùng Doanh Chính ?”\n“ Không có !”\n“ Bị che giấu sau đó , mẫu tử hai người mới có thể mạng sống .”\n“ Sau đó đâu ? Nhận Hoa Dương phu nhân vì mẫu sau đó , suy nghĩ biện pháp để cho Doanh Chính mẫu tử hai người trở về Tần quốc sao ? Cũng không có !”\n“ Tần Chiêu Tương vương năm mươi sáu năm ( Phía trước năm ), chiêu Tương Vương qua đời , Thái tử An quốc quân kế vị làm vương , là vì Tần Hiếu Văn Vương , Hoa Dương phu nhân là hoàng hậu , Tử Sở vì Thái tử , Triệu quốc hộ tống Tử Sở phu nhân cùng nhi tử Doanh Chính trở lại Tần quốc .”\n“ Trong lúc này thời gian sáu năm , thắng dị nhân , cũng chính là Doanh Tử sở , nhưng một điểm không có để ý Triệu Cơ cùng Doanh Chính .”\nLương Phong nói đến đây , dừng lại một hồi , cầm lấy trước mặt nước khoáng uống một ngụm .\n“ Cho nên , bây giờ rất nhiều người nói doanh dị nhân vô cùng yêu thích Triệu Cơ , yêu thích Doanh Chính , đây chính là cái gì ? Lời nói vô căn cứ .”\nLý Ân Phàm kỳ thực cũng cho là như vậy , muốn nói thắng dị nhân yêu thích Doanh Chính ? Nghĩ gì thế ? Nếu như yêu thích , cũng sẽ không lưu Triệu Cơ cùng Doanh Chính mẫu tử một mực tại Triệu quốc đông đóa tây tàng .\nNé bao lâu ? Thời gian sáu năm ! Từ Tần Chiêu Tương vương năm mươi năm , thắng dị nhân trốn về Tần quốc bắt đầu , mãi cho đến Tần Chiêu Tương vương năm mươi sáu năm .\nRòng rã thời gian sáu năm , thắng dị nhân quản đều không quản .\n“ Có thể có người sẽ nhớ , thắng dị nhân vì cái gì mặc kệ Triệu Cơ cùng Doanh Chính mẫu tử ? Vì cái gì mặc kệ ?”\n“ Kỳ thực trong mắt của ta rất đơn giản , Triệu Cơ là thân phận gì ? Lữ Bất Vi đưa cho thắng dị nhân cơ thiếp .”\n“ Nếu như là ngươi , đang trốn về Tần quốc sau đó , biết mình sẽ bên trên Nhậm Thái Tử , sau đó bên trên Nhậm Quốc Quân .”\n“ Ngươi sẽ đi quản cái này không danh phận cơ thiếp sao ?”\n“ Vì sao lại nói không danh phận ?”\nLý Ân Phàm lắc đầu cười nói :\n“ Bởi vì Triệu Cơ , chỉ là Lữ Bất Vi đưa cho thắng dị nhân cơ thiếp a ...”\n“ Dạng này cơ thiếp , có cái gì danh phận ?”\nTiếng nói rơi xuống , trên đài tất cả mọi người đều lắc đầu .\nMà dưới đài Doanh Chính , thì dường như là nghĩ tới cái kia sáu năm trốn đông trốn tây kiếp sống , thần sắc càng ngày càng hờ hững .\nBên cạnh Mông Điềm cẩn thận từng li từng tí , cũng không dám thở mạnh một tiếng .\n“ Nhưng vẫn là câu nói kia , họa này phúc chỗ dựa , phúc hề họa chỗ phục .”\n“ Giống như thắng dị nhân lên chức cấp độ sâu nguyên nhân , Doanh Chính thượng vị , vẫn là như thế .”\n“ Chỉ có thể nói , may Tần Trang Tương vương thắng Tử Sở , cũng chính là Doanh Chính phụ thân chết sớm , bằng không thì thật làm cho hắn Sở Hệ vương hậu sinh ra hài tử , Doanh Chính căn bản không có một chút xíu cơ hội .”\n“ Nhưng cũng chính là dạng này , Doanh Chính mới có thể thượng vị .”\nChỉ có thể nói lịch sử có tương tự kinh người tính chất .\nThắng dị nhân , cũng chính là Doanh Tử sở thượng vị là như thế . Doanh Chính , hắn thượng vị vẫn là như thế .\n“ Biết Doanh Chính vì cái gì thượng vị , vậy chúng ta liền biết được một sự kiện , Doanh Chính lên chức thời điểm , quyền lực lớn sao ?”\n“ Bởi vì tuổi nhỏ , hắn lúc đó có thể nói , không một chút quyền hạn .”\nLý Ân Phàm tổng kết một chút .\nSau đó , Trần Xuyên Phú tiếp lấy Lý Ân Phàm mà nói nói :\n“ Đang phân tích đằng sau Tần quốc lịch sử thời điểm , chúng ta phải biết một sự kiện .”\n“ Bây giờ rất nhiều người cho rằng , Doanh Chính lên chức thời điểm , Lữ Bất Vi cầm giữ triều chính , cho nên Lữ Bất Vi thế lực tại lúc đó là thế lực lớn nhất .”\n“ Cái này kỳ thực có một chút sai lầm ! Lúc đó thế lực lớn nhất , không hề nghi ngờ , nhất định là Sở Hệ thế lực !”\n“ Liên tiếp mấy đời quốc quân , đều do Sở Hệ gật đầu mới có thể thượng vị , liền đã rất có thể nói rõ vấn đề .”\n“ Vậy cái này thời điểm rất nhiều người trong lòng liền có nghi hoặc , Tần quốc ngay lúc đó thế lực , có cái nào ?”\n“ Một , Bản Thổ phái , cũng chính là Tần quốc quý tộc , những cái kia lão Tần người , còn có Doanh tính tôn thất .”\n“ Hai , Sở Hệ thế lực , cũng có thể xưng là Sở Hệ hậu cung thế lực , hậu cung cơ hồ bị bọn hắn cầm giữ !”\n“ Ba , kẻ ngoại lai , thương ưởng biến pháp sau đó , từ chư hầu khác quốc đi tới Tần quốc người .”\n“ Nơi này có một cái vấn đề rất trọng yếu , đó chính là tại lúc đó , những người ngoại lai này bị ai lãnh đạo ?”\n“ Có thể có người nghĩ tới , không tệ ! Những người ngoại lai này , là bị Lữ Bất Vi lãnh đạo .”\n“ Cái này cũng là vì cái gì nhìn qua , Lữ Bất Vi thế lực tựa như là lúc đó khổng lồ nhất thế lực .”\nGiải thích xong điểm này sau đó , Trần Xuyên Phú lại nói :\n“ Vậy tại sao Doanh Chính thượng vị sau đó , vì nắm giữ quyền lực , trước tiên đả kích là những người ngoại lai này thế lực đâu ?”\n“ Vì cái gì không đả kích Sở Hệ thế lực ? Không đả kích bản thổ thế lực ?”\n“ Bởi vì lúc đó Tần quốc mâu thuẫn vô cùng sắc bén !”\n“ Lữ Bất Vi ngay lúc đó hành động đưa tới Sở Hệ thế lực , còn có Bản Thổ phái bất mãn .”\n“ Chính hắn độc quyền triều chính coi như xong , còn để cho ai đi lên ? Lao Ái !”\n“ Hai người bọn họ làm hết thảy bạo lộ ra sau đó , Sở Hệ thế lực là nhất định muốn đả kích bọn hắn .”\n“ Bởi vì bọn hắn đụng phải Sở Hệ thế lực cấm kỵ , đem bàn tay hướng về phía hậu cung !”\n“ Mà Bản Thổ phái vì cái gì cũng muốn đả kích bọn hắn ? Tần quốc trên triều đình vị trí thì nhiều như vậy , ngươi Lữ Bất Vi coi như xong , nhưng ngươi lại đem Lao Ái lấy tới ? Lao Ái sau khi đi lên , hắn lại muốn đề bạt hắn người phía dưới .”\n“ Vậy dạng này vừa tới , không đả kích ngươi Lữ Bất Vi , đả kích ai ?”\n“ Cho nên , cái này cũng là vì sao Doanh Chính trưởng thành bắt đầu cầm quyền sau đó , trước tiên đả kích là kẻ ngoại lai thế lực .”\n“ Trong cái này tại trong chính trị , gọi tá lực đả lực !”\nSau đó , Trần Xuyên Phú lại tiếp tục nói :\n“ Rất nhiều người có thể có nghi hoặc , từ nơi nào có thể nhìn ra đây là Bản Thổ phái đả kích những người ngoại lai này ?”\n“《 Gián Trục Khách Thư 》 là lúc nào Lý Tư viết cho lúc đó thân là Tần Vương Doanh Chính ?”\n“ Là Lữ Bất Vi uống rượu tự sát sau khi chết , Tần Vương Doanh Chính nghe theo Tần quốc quý tộc lời nói , xuống “ Trục khách chi lệnh ”, trục xuất Lục quốc thực khách .”\n“ Đây là 《 Gián Trục Khách Thư 》 từ đâu tới .”\nNói xong 《 Gián Trục Khách Thư 》 sau đó , Trần Xuyên Phú nhìn về phía máy quay phim , hỏi một vấn đề .\n“ Hỏi đại gia một vấn đề , chúng ta mới vừa nói , Tần Vương Doanh Chính nghe theo Tần quốc quý tộc lời nói , xuống “ Trục khách chi lệnh ”.”\n“ Lại nói Bản Thổ phái , còn có kẻ ngoại lai thế lực , cùng với Sở Hệ thế lực .”\n“ Đại gia nghĩ một hồi , tại ở trong đó , có phải hay không còn có một cái thế lực , chúng ta vẫn luôn không nói ?”\nKhi Trần Xuyên Phú hỏi ra cái vấn đề này , dưới đài Doanh Chính nhắm mắt lại .\nHắn biết trên đài người kia nói là thế lực gì , nhưng muốn nói Doanh Chính hối hận sao ?\nDoanh Chính cũng không biết .\nCho dù là bây giờ , biết Tần triều cuối cùng phá diệt , hắn y nguyên vẫn là không biết .\nNhưng ở lúc đó , hắn lại nhất thiết phải làm như vậy , bằng không thì Tần quốc bất ổn .\n......', 'output\\mp3\\Màn Trời Quyền Lực Diễn Biến Cùng Truyền Thừa\\0033_Thứ 33 chương Cơ thiếp.mp3', '2026-09-01T13:12:59.128471+00:00', 'completed', 'completed', 7185, 7185),
	(39, 7, '7644748152246911512', 34, 'Thứ 34 chương Tôn thất', 'Thứ chương Tôn thất\nHiện đại thời không .\n“ Cái này một thế lực là thế lực gì ? Tần quốc bản thổ tôn thất thế lực !”\n“ Có thể có bằng hữu nghi hoặc , Tần quốc bản thổ tôn thất thế lực ? Có dạng này một thế lực sao ?”\n“ Giống như cái này tôn thất thế lực , tại Tần quốc Tần Vương Doanh Chính thời kì , không có cái gì tồn tại cảm .”\n“ Sau đó thì sao ? Tại Tần triều thời kì , vẫn không có cảm giác tồn tại gì .”\n“ Nhưng một cái các nước chư hầu , cùng với một cái vương triều , sẽ không có tôn thất thế lực sao ? Đương nhiên không có khả năng !”\n“ Nhất định sẽ có tôn thất thế lực !”\n“ Nhưng chúng ta vẫn là vấn đề kia , Tần quốc tôn thất thế lực , chạy đi nơi nào ?”\nLúc này , Ngụy Gia cầm ống nói lên , đón lấy Trần Xuyên Phú mà nói , hồi đáp :\n“ Tần quốc tôn thất thế lực , tại cuối cùng , bị Doanh Chính diệt trừ a ?”\n“ Không đúng , không thể nói diệt trừ , tôn thất thế lực diệt trừ không được , phải nói , ngay lúc đó thế lực , bị Doanh Chính chèn ép đến triệt để không đứng dậy nổi .”\n“ Có người nhất định sẽ hỏi , vì cái gì nói như vậy ? Vì cái gì nói là Doanh Chính chèn ép tôn thất thế lực ?”\nNgụy Gia lúc này nói ra một cái khác chuyện .\n“ Còn nhớ rõ Hồ Hợi thượng vị sau đó làm cái gì không ?”\n“ Đem mười hai cái huynh đệ xử tử . Một lần khác tại Đỗ Bưu ( Nay Thiểm Tây Hàm Dương đông ) lại đem 6 cái huynh đệ cùng 10 cái tỷ muội nghiền chết , pháp trường vô cùng thê thảm .”\n“ Đem lư ba người cũng là Hồ Hợi huynh đệ , cuối cùng cũng bị bức tự vận .”\n“ Ba người bọn họ so các huynh đệ khác đều trầm ổn , Hồ Hợi tìm không ra tội danh gì hãm hại , liền nhốt ở cung nội . Các cái khác rất nhiều huynh đệ bị giết sau , Triệu Cao phái người buộc bọn họ tự vận .”\nNói xong Hồ Hợi giết huynh đệ chuyện này sau đó , Ngụy Gia nhẹ giọng hỏi :\n“ Tại Hồ Hợi làm đây hết thảy thời điểm , tôn thất đi ra sao ?”\n“ Rất nhiều người có thể sẽ nghĩ , Hồ Hợi lúc đó là hoàng đế , tôn thất như thế nào lên tiếng ? Tôn thất dựa vào cái gì lên tiếng ?”\n“ Nhưng đây đều là ngươi tôn thất nên làm ! Bằng không thì ngươi dựa vào cái gì gọi tôn thất ?”\n“ Hoàng đế đồ sát huynh đệ , lúc này ngươi tôn thất liền đi ra nói một tiếng cũng không dám ?”\n“ Hơn nữa , hoàng đế này tàn sát huynh đệ , vẫn là Tần Thủy Hoàng Doanh Chính hài tử !”\n“ Cho nên , ở đây chúng ta liền đạt được hai cái kết luận .”\n“ Thứ nhất kết luận , tôn thất thế lực triệt để xuống dốc ! Cũng chính là tôn thất thế lực , đã triệt để không có cách nào lên tiếng !”\n“ Thứ hai cái kết luận , tôn thất thờ ơ lạnh nhạt Hồ Hợi làm hết thảy ! Tôn thất không thèm chú ý đến Hồ Hợi làm hết thảy !”\n“ Hai cái này kết luận cái nào là chính xác ? Đều chính xác , kỳ thực hai cái kết luận không xung đột !”\nNgụy Gia sau khi nói đến đây , uống một hớp nước , sau đó lại tiếp tục nói :\n“ Nếu như nghiêm túc nghe xong vừa rồi tất cả mọi chuyện bằng hữu , hẳn là phát giác một vấn đề .”\n“ Đó chính là , Tần Vương thượng vị , tại sao là Sở Hệ thế lực định đoạt ? Hơn nữa ở trong đó , còn có người ngoại lai thế lực cũng tham dự .”\n“ Cái kia bản thổ thế lực đâu ? Tôn thất thế lực đâu ?”\n“ Đặc biệt là tôn thất thế lực , cái gọi là Tần Vương thượng vị , hẳn là nên bọn hắn quản a ?”\n“ Cho nên , từ nơi này đi xem , chúng ta liền biết một sự kiện , tôn thất thế lực , thuộc về bọn hắn quyền hạn , chính bọn hắn cũng không quản được .”\n“ Theo lý thuyết , tại rất sớm phía trước , tôn thất thế lực , cũng đã bắt đầu sa sút .”\nSau đó , Ngụy Gia lại nói tiếp :\n“ Nhưng triệt để xuống dốc ? Vẫn còn không tính là .”\n“ Lúc nào triệt để sa sút ?”\n“ Không biết đại gia có còn nhớ hay không một sự kiện , Thủy Hoàng Đế 8 năm ( Phía trước năm ), Vương đệ Trường An Quân Thành kiểu suất lĩnh đại quân tiến đánh Triệu quốc , nửa đường mưu phản .”\n“ Vì cái gì Trường An Quân Thành kiểu sẽ mưu phản ?”\n“ Tại sao cảm thấy chính mình có hi vọng mưu phản thành công ?”\n“ Lúc này , vấn đề tới , vì cái gì hắn sẽ cảm thấy chính mình mưu phản thành công ?”\n“ Tần quân công chiếm Truân Lưu sau , thành kiểu bộ hạ tất cả bởi vì liên đới bị chém đầu xử tử , Truân Lưu bách tính bị lưu đày tới Lâm Thao .”\n“ Sau đó thì sao ? Chuyện này liền kết thúc !”\n“ Nhưng chúng ta vẫn là vấn đề kia , vì cái gì Trường An Quân Thành kiểu tiến đánh Triệu quốc thật tốt , đột nhiên nửa đường liền mưu phản ?”\n“ Mặt sau này khẳng định có người , hoặc có lẽ là có thế lực cho hứa hẹn .”\n“ Bằng không thì Trường An Quân Thành kiểu tiến đánh Triệu quốc , nửa đường đột nhiên não rút ? Liền quyết định mưu phản ?”\n“ Tất nhiên quyết định mưu phản , đó nhất định là có người nào cho Trường An Quân Thành kiểu hứa hẹn , để cho hắn thấy được hy vọng .”\n“ Mà cái này hy vọng ai cho ?”\n“ Phương pháp bài trừ !”\n“ Thủy Hoàng Đế 8 năm , Lữ Bất Vi còn tại , Tần Vương Chính còn không có cử hành quan lễ .”\nNgụy Gia bắt đầu từng cái giảng thuật lúc đó Tần triều thế lực .\n“ Kẻ ngoại lai thế lực ? Lúc đó không có bị đả kích , Lữ Bất Vi còn tại .”\n“ Sở Hệ thế lực đâu ? Cũng còn tại , không có bị đả kích .”\n“ Tần quốc quý tộc đâu ? Sau đó lại còn tham dự đả kích kẻ ngoại lai thế lực .”\n“ Cho nên đáp án cũng rất đơn giản , cho Trường An Quân Thành kiểu cam kết , là thế lực gì ? Tần quốc tôn thất thế lực .”\n“ Lúc này , có người chắc chắn liền có nghi ngờ , vì cái gì Tần quốc tôn thất thế lực , sẽ liên hợp Trường An Quân Thành kiểu mưu phản ?”\n“ Bởi vì Thủy Hoàng Đế 9 năm , Tần Vương Chính tại Ung Thành kỳ năm cung cử hành quan lễ !”\nNói xong điểm này sau đó , Ngụy Gia lại sau đó tiếp tục nói :\n“ Ngoại trừ Doanh Chính lúc đó còn không có cử hành quan lễ đâu ? Còn có ...”\n“ Tần Thủy Hoàng Doanh Chính thượng vị , tôn thất thế lực , không có ra một điểm lực .”\n“ Doanh Chính thượng vị ai xuất lực ? Kẻ ngoại lai thế lực cùng Sở Hệ thế lực .”\n“ Sau đó thì sao ? Bởi vì ngay lúc đó thế cục để cho tôn thất thế lực thấy rõ ràng , thật sự nếu không thượng vị , vậy thật là không có một chút ăn !”\n“ Cũng lại không có cách nào xoay người !”\n“ Tần Hiếu Văn Vương thắng trụ hơn 20 đứa bé , cuối cùng là ai thượng vị ? Thân là hạt nhân thắng dị nhân ! Hơn nữa , hắn thượng vị phía trước nói , là nhận Hoa Dương phu nhân làm mẫu thân .”\n“ Doanh Chính thượng vị đâu ? Cùng thắng dị nhân gần như giống nhau ! Ngoại trừ không có nhận Hoa Dương phu nhân làm mẫu thân .”\n“ Nhưng mà , đây là Sở Hệ thế lực cùng kẻ ngoại lai thế lực , đều có thể tiếp nhận ! Đặc biệt là Lữ Bất Vi bọn người .”\n“ Cho nên , từ cái này rậm rạp chằng chịt tin tức rất đơn giản liền có thể nhìn ra .”\n“ Trường An Quân Thành kiểu , phía sau hắn , nhất định là Tần quốc tôn thất thế lực .”\nNgụy Gia nói xong điểm này , lại nói tiếp :\n“ Có thể có người sẽ nhớ , vì cái gì Doanh Chính muốn đả kích tôn thất thế lực ? Dù là tôn thất thế lực đúng là ủng hộ Trường An Quân Thành kiểu mưu phản , cũng không nên đem tôn thất thế lực đả kích về sau không có bất kỳ cái gì thanh âm a ?”\n“ Phải biết , tôn thất thế lực , thế nhưng là quốc quân , hoặc có lẽ là hoàng đế trung thành nhất thế lực .”\n“ Kỳ thực đáp án phía trước chúng ta đã nói qua , nếu như nghiêm túc nghe xong bằng hữu , hẳn là rất dễ dàng vuốt tinh tường .”\n“ Từ Doanh Chính lập trường đi xem , chính mình thượng vị , là ai xuất lực ? Mình tại Triệu quốc trốn đông trốn tây thời điểm , ngươi tôn thất thế lực ở nơi nào ?”\n“ Chính mình trở lại Tần quốc thời điểm , ngươi tôn thất thế lực lại ở nơi nào ?”\n“ Ta lập tức cập quan , bắt đầu nắm giữ quyền lực , ngươi tôn thất thế lực lại mưu phản ?”\nSau đó , Ngụy Gia điều chỉnh một chút tư thế ngồi , rất nghiêm túc nhìn về phía camera nói :\n“ Mà cái này , cũng là rất nhiều người bỏ quên một cái đạo lý đơn giản nhất .”\n“ Quyền hạn đối với quyền lực nơi phát ra phụ trách !!!”\n......', 'output\\mp3\\Màn Trời Quyền Lực Diễn Biến Cùng Truyền Thừa\\0034_Thứ 34 chương Tôn thất.mp3', '2026-09-01T13:13:05.018864+00:00', 'completed', 'completed', 7540, 7540),
	(40, 7, '7644941000435040792', 35, 'Thứ 35 chương 《 Gián trục khách sách 》 bên trong lưu trắng', 'Thứ chương 《 Gián Trục Khách Thư 》 bên trong Lưu Bạch\nHiện đại thời không .\n“ Đúng vậy , quyền hạn chỉ có thể đối với quyền lực nơi phát ra phụ trách ! Nó sẽ không đối với những khác bất luận kẻ nào phụ trách !”\n“ Đây chính là vì khi nào lúc Tần Vương Doanh Chính muốn đả kích tôn thất thế lực nguyên nhân lớn nhất .”\nTrần Xuyên Phú nhận lấy câu chuyện , nhìn xem mấy người , tiếp tục nhẹ nói :\n“ Đây là một câu vô cùng trọng yếu mà nói , đại gia nhất định muốn nhớ rõ ràng .”\n“ Bởi vì nếu như vuốt rõ ràng một câu nói kia , chúng ta lại đi quay đầu nhìn mấy ngàn năm lịch sử , liền có thể rất rõ ràng thấy rõ ràng rất nhiều lịch sử sự kiện trong đó lôgic quan hệ .”\n“ Giống như chúng ta mới vừa nói , vì cái gì thân là quốc vương Doanh Chính muốn đả kích tôn thất thế lực ? Bởi vì Doanh Chính thượng vị , còn có lúc trước hắn trải qua hết thảy , ngay lúc đó Doanh tính tôn thất , không có ra một điểm âm thanh .”\n“ Cái kia đã như vậy , không đả kích ngươi , đả kích ai đây ?”\n“ Nếu như ngươi không nhảy còn tốt , nhưng ngươi cũng nhảy ra ngoài , liên hợp người mưu phản , vậy thì không thể không đả kích ngươi .”\nSau đó , Trần Xuyên Phú dừng một chút , uống một hớp nước , lại nói :\n“ Hơn nữa , sự đả kích này thời điểm cũng vô cùng xảo diệu .”\n“ Tần Thủy Hoàng 8 năm ! Qua một năm nữa , Tần Thủy Hoàng Doanh Chính mới cập quan .”\n“ Lúc này , dù là ngay lúc đó Doanh Chính nghĩ bảo trụ tôn thất ? Cũng là không thể nào !”\n“ Ngay lúc đó Sở Hệ thế lực , còn có Lữ Bất Vi lãnh đạo kẻ ngoại lai thế lực , nhất định sẽ đả kích tôn thất thế lực .”\n“ Đặc biệt là Sở Hệ thế lực ! Đả kích Doanh tính tôn thất thế lực ? Bọn hắn tuyệt đối vô cùng nguyện ý !”\nChờ Trần Xuyên Phú nói xong sau đó , Lý Ân Phàm cầm ống nói lên , nói tiếp :\n“ Có thể có người sẽ hỏi , lúc đó nhất định là tôn thất thế lực sao ? Có khả năng hay không , là những thế lực khác ?”\nNói đến đây , Lý Ân Phàm nhìn xem máy quay phim , nói rất chân thành :\n“ Không có khả năng ! Nhất định là tôn thất thế lực ! Bởi vì cái thời điểm này , có lại chỉ có tôn thất thế lực , mới có thể đối với quốc quân ra tay !”\n“ Cho dù là về sau Lao Ái , hắn vì cái gì không tại Thủy Hoàng Đế 8 năm cái thời điểm này đối với Doanh Chính ra tay ? Phải chờ tới Thủy Hoàng Đế 9 năm ?”\n“ Bởi vì Thủy Hoàng Đế 9 năm , Doanh Chính cập quan , bắt đầu cầm quyền !”\n“ Ngươi không có chính thức lúc ta cầm quyền , ai cũng nhìn không ra uy hiếp của ngươi , ngoại trừ có ý định quốc quân vị trí người , thế lực khác , không có người sẽ lý tới ngươi !”\n“ Cho nên , nhất định là tôn thất thế lực , đối với quốc quân vị trí có ý tưởng người , có thể lên vị trí kia người , mới có thể tại cái kia thời gian điểm ra tay .”\n“ Ở đây , liền có một đầu vô cùng ẩn hình lôgic dây xích ở đây .”\nChờ Lý Ân Phàm nói xong sau đó , Lương Phong cầm ống nói lên , tiếp tục nói :\n“ Nơi này có người nhất định sẽ hỏi một vấn đề , vì cái gì Doanh Chính tại Thủy Hoàng Đế mười năm , để cho Lữ Bất Vi uống rượu tự sát sau đó , đầu tiên là nghe theo Tần quốc quý tộc lời nói , xuống “ Trục khách chi lệnh ”, trục xuất Lục quốc thực khách .”\n“ Nhưng lại bị Lý Tư 《 Gián Trục Khách Thư 》 chỗ khuyên can , phía sau hắn vẫn là trọng dụng úy quấn , Lý Tư bọn người ?”\n“ Khẳng định có người sẽ nhớ , liền Lý Tư một mình hắn , lên 《 Gián Trục Khách Thư 》, chẳng lẽ liền để Doanh Chính hồi tâm chuyển ý sao ?”\nLương Phong khẽ gật đầu một cái sau , chậm rãi nói :\n“ Vậy chúng ta liền đứng tại Doanh Chính góc độ đi xem , đi suy xét .”\n“ Còn nhớ rõ chúng ta phía trước nói , lúc đó Tần quốc nội bộ , có mấy thế lực lớn sao ?”\n“ Tam đại thế lực ! Tần quốc bản thổ thế lực , kẻ ngoại lai thế lực , Sở Hệ hậu cung thế lực !”\n“ Mà tại ở trong đó , Tần quốc bản thổ trong thế lực tôn thất thế lực , phía trước liền đã bị triệt để chèn ép .”\n“ Tần quốc bản thổ thế lực , bên trong liền còn sót lại Tần quốc quý tộc thế lực , cũng chính là những cái kia lão Tần người .”\n“ Vì cái gì Lý Tư một mình hắn lên 《 Gián Trục Khách Thư 》, liền để Doanh Chính hồi tâm chuyển ý ?”\n“ Đáp án rất đơn giản , nếu như triệt để đuổi kẻ ngoại lai thế lực , cái kia ngay lúc đó trên triều đình , chỉ còn dư mấy cái thế lực ?”\n“ Có thể có người sẽ nhớ , hai cái a ? Đây thật ra là sai lầm .”\n“ Chỉ còn dư một cái ! Bởi vì Sở Hệ thế lực , bọn hắn vẻn vẹn cầm giữ hậu cung , dùng hậu cung đến đúng triều đình làm áp lực !”\n“ Mà tại không có Doanh tính tôn thất thế lực sau đó , chân chính thuộc về trên triều đình thế lực , chỉ còn dư cái nào ?”\n“ Chỉ còn dư Tần quốc quý tộc thế lực !”\n“ Đây chính là vì sao Doanh Chính hồi tâm chuyển ý nguyên nhân lớn nhất một trong !”\nNói xong cái này nguyên nhân lớn nhất , Lương Phong lại tiếp tục nói tiếp :\n“ Cái kia còn có hay không nguyên nhân khác ? Có !”\n“ Còn nhớ rõ chúng ta phía trước nói sao ? Quyền hạn đối với quyền lực nơi phát ra phụ trách .”\n“ Một câu nói kia vì cái gì chúng ta biết nói trọng yếu như vậy ? Bởi vì quyền hạn không chỉ có thể đối với quyền lực nơi phát ra phụ trách , nó cũng thường xuyên sẽ nhớ quyền lực của mình vì cái gì mà đến !”\n“ Doanh Chính quyền hạn , phía trước chúng ta nói qua , là thế nào tới ? Lữ Bất Vi lãnh đạo ngoại lai thế lực , còn có Sở Hệ thế lực , là bọn hắn hai người , đem Doanh Chính đỡ lên chức !”\n“ Vậy cái này thời điểm vấn đề tới , nếu như ngươi là Doanh Chính , ngươi có thể hay không nghĩ , những quý tộc này thế lực , là có hay không giá trị đến tín nhiệm ?”\n“ Đối với ngươi mà nói , là kẻ ngoại lai thế lực cùng Sở Hệ thế lực đáng giá tín nhiệm , vẫn là bản thổ những quý tộc này thế lực đáng giá tín nhiệm ?”\n“ Đáp án này rõ ràng !”\nĐúng vậy , đáp án này đúng là rõ ràng , mấy người tại chỗ đều gật đầu một cái .\nDù sao tại chính mình thượng vị lúc chưa từng đi quá lực , còn thế nào đi tín nhiệm bọn họ ? Cả hai so sánh , rất dễ dàng ra kết luận .\n“ Ngoại trừ phía trên hai điểm đâu ? Vẫn là vừa rồi nguyên nhân kia !”\n“ Ngươi Tần quốc quý tộc , là bản thổ thế lực ! Mà kẻ ngoại lai đâu ? Bọn hắn là thế lực ngoại lai ! Không có căn cơ !”\n“ Một cái là có căn cơ ! Một cái khác đâu ? Nhưng là không có căn cơ !”\n“ Doanh Chính thanh trừ Lữ Bất Vi sau đó , cũng có thể khu trục kẻ ngoại lai thế lực , nếu như ngươi là Doanh Chính , ngươi sẽ ra sao ?”\nLương Phong sau khi nói đến đây , ý vị thâm trường nhìn xem camera , tiếp tục nói :\n“ Có phải hay không sẽ nhớ , ta hoàn toàn có thể nắm giữ cái này một thế lực ?”\n“ Mà Lý Tư đâu ? Hắn cũng thấy rõ ràng điểm này , cấp ra nhập đội !”\n“ Đây chính là Lý Tư có thể thuyết phục Doanh Chính nguyên nhân lớn nhất .”\n“ Nếu như cẩn thận nhìn qua 《 Gián Trục Khách Thư 》 tiểu đồng bọn , hẳn là nhớ kỹ nội dung bên trong .”\nLúc này , Lý Ân Phàm đứng lên , hướng về nhân viên công tác đánh một cái động tác , không đợi một hồi , studio phía sau trên màn hình , liền xuất hiện 《 Gián Trục Khách Thư 》 nguyên văn .\nSau đó , Lương Phong gật đầu một cái , đứng lên , chỉ vào đoạn thứ nhất cùng đoạn thứ hai nói :\n“ Lý Tư vô cùng thông minh , nhìn hắn như thế nào miêu tả đoạn thứ nhất cùng đoạn thứ hai ?”\n“ Đoạn thứ nhất , hắn nêu ví dụ dùng ai ? Thương Ưởng ! Trương Nghi ! Phạm Sư !”\n“ Mà đoạn thứ hai đâu ? Lý Tư bỗng nhiên liền bắt đầu dùng mỹ ngọc , Tùy Hầu Châu , Hòa Thị Bích vân vân bảo vật bắt đầu hình dung nêu ví dụ .”\n“ Lý Tư tại sao lại nói như vậy ?”\nTrần Xuyên Phú cầm ống nói lên , tiếp nhận Lương Phong chủ đề , bắt đầu giảng giải nói :\n“ Đây chính là Lý Tư vô cùng thông minh địa phương ! Hắn nêu ví dụ cái này một số người .”\n“ Thương Ưởng là thế nào chết ? Kế nhiệm chi tân quân vì hoà dịu mâu thuẫn , đem Thương Ưởng ngũ xa phanh thây .”\n“ Trương Nghi là thế nào chết ? Tần Vũ Vương vào chỗ , cùng Trương Nghi không cùng . Trương Nghi sợ bị tru sát , thế là chạy trốn tới Ngụy quốc . Trương Nghi Nhậm Ngụy Quốc tướng quốc một năm về sau , tại phía trước năm tốt tại Ngụy quốc .”\n“ Phạm Sư đâu ? Hắn lại là chết như thế nào ? Trước công nguyên năm đề cử Thái Trạch thay thế mình tướng vị , từ về đất phong , không bệnh lâu chết .”\n“ Vì sao lại đề cử Thái Trạch thay thế mình tướng vị ? Bởi vì Tần Chiêu Vương một phen , để cho Phạm Sư sợ hãi . Cho là Tần Chiêu Vương không vui chính mình .”\n“ Đây là cái gì ?”\n“ Đây chính là Lưu Bạch ! Chỉ nói bọn hắn công , nhưng hạ tràng đâu ? Hạ tràng không nói , mà là trực tiếp nhảy đến đoạn thứ hai .”\n“ Bắt đầu nói đến mỹ ngọc , thái a kiếm các loại .”\n“ Đây chính là Lý Tư vô cùng thông minh địa phương , cũng đúng 《 Gián Trục Khách Thư 》 bên trong rất nhiều người không có ý thức được địa phương .”\nSau đó , Trần Xuyên Phú nói nghiêm túc :\n“《 Gián Trục Khách Thư 》 thông minh ở nơi nào ?”\n“ Rõ rành rành nói cho ngay lúc đó Tần Vương Doanh Chính .”\n“ Chúng ta những người ngoại lai này , chỉ có thể trở thành trên người ngươi giống Tùy Hầu Châu dạng này châu báu , đẹp như vậy ngọc , tới trang trí ngươi .”\n“ Chúng ta không có căn cơ ! Sẽ không đối ngươi vị trí , sẽ không đối với Tần quốc , tạo thành một chút xíu uy hiếp !”\n“ Giống Thương Ưởng , Trương Nghi , Phạm Sư , bọn hắn lợi hại như vậy , nhưng vẫn là bị ngay lúc đó Tần Vương một câu nói liền tứ tử .”\n“ Cho nên , ngươi tại sao không dùng chúng ta ? Mà là phải dùng đối với ngươi tạo thành uy hiếp Tần quốc quý tộc đâu ?”\n“ Đây chính là Lý Tư 《 Gián Trục Khách Thư 》 bên trong cấp độ sâu hàm nghĩa .”\n“ Cái này cũng là vì cái gì Doanh Chính nhìn 《 Gián Trục Khách Thư 》 sau đó , lập tức hồi tâm chuyển ý nguyên nhân lớn nhất một trong !”\n“ Ở đây nhìn 《 Gián Trục Khách Thư 》 tiểu đồng bọn , có thể sẽ nghĩ , đây không phải là còn có từ còn lại , Bách Lý Hề , kiển thúc , phi báo , Công Tôn Chi , cái này tại Tần Mục công thời kỳ năm người sao ?”\n“ Đúng vậy a , còn có năm người này , nhưng ở lúc đó , cũng chính là Doanh Chính thời kì , năm người này gia tộc , ở nơi nào ?”\n“ Lý Tư vì cái gì đem cái này một số người lấy ra viết tại 《 Gián Trục Khách Thư 》 bên trong ?”\n“ Đây cũng chính là nguyên nhân lớn nhất ! cũng đúng 《 Gián Trục Khách Thư 》 bên trong Lưu Bạch !”\n...', 'output\\mp3\\Màn Trời Quyền Lực Diễn Biến Cùng Truyền Thừa\\0035_Thứ 35 chương 《 Gián trục khách sách 》 bên trong lưu trắng.mp3', '2026-09-01T13:13:28.669294+00:00', 'completed', 'completed', 9809, 9809),
	(41, 7, '7644941193305932312', 36, 'Thứ 36 chương Có lẽ có đạo lí riêng của nó?', 'Thứ chương Có lẽ có nhất định đạo lý ?\nHiện đại thời không .\nLý Ân Phàm nghe được cái này , có chút lớn khai nhãn giới , hắn chính xác không nghĩ tới còn có điểm này .\nNhưng có đạo lý hay không ? Đương nhiên là có đạo lý , bằng không thì thật sự chỉ dựa vào 《 Gián Trục Khách Thư 》 bên trong viết , liền để Tần Thủy Hoàng Doanh Chính hồi tâm chuyển ý ?\nGiống như phía trước Lý Ân Phàm đối với Doanh Chính nói , Ti Mã Thác , Bạch Khởi bọn họ đâu ? Những cái kia vì Tần quốc lớn mạnh lão Tần người đâu ?\n‘ Thì ra Doanh Chính là nghĩ như vậy sao ?’\nLý Ân Phàm ở trong nội tâm nói thầm một chút , sau đó nhìn về phía Doanh Chính .\nLại phát hiện Doanh Chính ánh mắt yên tĩnh nhìn về phía trên đài .\n“ Dứt bỏ đi đằng sau Tần triều lịch sử , liền lấy lúc đó Doanh Chính góc độ đi xem .”\n“ Đây quả thật là làm không có vấn đề .”\n“ Mặc kệ trong lịch sử hoàng đế nào tới , cũng sẽ như vậy lựa chọn ...”\n“ Lý Tư cũng tại 《 Gián Trục Khách Thư 》 bên trong nói rất hiểu rồi , dù là về sau Tần Vương thượng vị , kẻ ngoại lai thế lực , cũng sẽ không đối với Tần quốc tạo thành một chút xíu uy hiếp .”\nLý Ân Phàm lúc này mở miệng nhẹ nói .\nCái này kỳ thực ngược lại không phải vì Doanh Chính giải thích , dù sao từ mỗi góc độ đi xem , Doanh Chính lúc đó làm đều không mao bệnh .\n“ Hơn nữa , Doanh Chính lúc đó mới sơ thượng vị , cũng cần triệt để chưởng khống một thế lực , đến đúng triều đình thực hiện ảnh hưởng .”\n“ Lý Tư 《 Gián Trục Khách Thư 》, chính là như vậy một phần nhập đội , rõ ràng biểu lộ , nhóm người mình sẽ hoàn toàn nghe Doanh Chính .”\nBên cạnh Lương Phong gật đầu một cái , cầm ống nói lên nhẹ nói :\n“ Kỳ thực các ngươi còn không để ý đến một điểm .”\nNghe được câu này , Lý Ân Phàm cùng Trần Xuyên Phú , còn có Ngụy Gia 3 người nhìn xem hắn .\n“ Trần Xuyên Phú vừa mới chính xác nói không sai , Lý Tư 《 Gián Trục Khách Thư 》 bên trong , viết Thương Ưởng , Trương Nghi bọn người , quả thật có hắn nói ý tứ kia .”\n“ Nhưng bên trong , kỳ thực còn có một tầng ý tứ .”\n“ Tại Thương Ưởng , Trương Nghi , Phạm Sư bọn người , vì Tần quốc suy nghĩ , mở rộng Tần quốc thời điểm , Tần quốc bản thổ những quý tộc kia , những cái kia lão Tần người , bọn hắn đang làm cái gì ?”\n“ Cái này cũng là vì sao Lý Tư 《 Gián Trục Khách Thư 》 không có viết Tần quốc lão Tần người nguyên nhân , cái này cũng là Lưu Bạch .”\n“ Cố ý để cho ngay lúc đó Tần Vương Doanh Chính suy nghĩ !”\n“《 Gián Trục Khách Thư 》 đoạn thứ nhất câu nói sau cùng : Bởi vậy quan chi , khách gì dựa vào Tần Tai ! Giả sử bốn Quân Khước Khách mà không bên trong , sơ sĩ mà không cần , là Sử quốc không Phú Lợi Chi thực , mà Tần Vô cường đại chi danh a .”\n“ Phiên dịch tới ý là : Theo như cái này thì , khách khanh có cái gì có lỗi với Tần quốc đây này ? Giả sử bốn vị quốc quân cự tuyệt khách khanh mà không tiếp nhận , xa lánh hiền sĩ mà không trọng dụng , này lại làm cho Tần quốc không có giàu có chi thực cùng cường đại tên .”\n“ Một câu nói kia , chỉ cần người bình thường nhìn , liền sẽ nghĩ , Tần quốc cường đại , dựa vào là các ngươi khách khanh ? Cái kia bản thổ những người kia đâu ?”\n“ Tiếp đó , nhìn cái này văn chương người , đặc biệt là thân ở chỗ cao người , nhìn liền sẽ tư duy phát tán .”\nSau đó , Lương Phong lắc đầu , sau đó tiếp tục nói :\n“ Hơn nữa , Gián Trục Khách Thư bên trong còn có một tầng ý tứ .”\n“ Tần Mục công thời kì bắt đầu , Công Tôn Chi bọn người ngay tại trợ giúp Tần quốc , cái kia từ Tần Mục công thời kì , đến bây giờ , những cái kia cũng tại Tần quốc gia tộc , có phải hay không kẻ ngoại lai ?”\n“ Cái này một số người , cũng tại Tần quốc định cư người , bọn họ có phải hay không khách khanh ?”\n“ Khu trục chúng ta , bước kế tiếp có phải hay không muốn khu trục bọn hắn ?”\n“ Phải biết , Mông Điềm Mông gia , Vương Tiễn Vương gia những gia tộc này , đều là về sau đến Tần quốc .”\n“ Nếu như đem chúng ta những người ngoại lai này đuổi , những người kia sẽ ra sao ?”\n“ Đặc biệt là có một cái trọng yếu nhất thế lực ...”\n“ Sở Hệ thế lực , bọn họ có phải hay không kẻ ngoại lai ?”\n“ Khu trục Lục quốc thực khách , thế nhưng là ngoại trừ Tần quốc , sáu quốc khác đều phải đuổi !”\nLương Phong nói đến đây , không có tiếp tục nói nữa , tổng kết một chút :\n“ Cho nên , cứ như vậy tổng hợp đến xem , nếu như ngươi là lúc ấy Tần Vương Doanh Chính , ngươi sẽ ra sao ?”\n“ Một cái không có chút nào căn cơ , có thể bị Tần Vương tùy ý giết chết , hơn nữa còn là một cỗ thế lực khổng lồ , có thể để ngươi triệt để nắm giữ thế lực , ngươi còn cam lòng để cho bọn hắn rời đi sao ?”\n“ Lý Tư 《 Gián Trục Khách Thư 》 đã nói rất hiểu rồi , chúng ta , chỉ có thể trở thành ngươi mỹ ngọc !”\n“ Bên trong thế nhưng là nói vô cùng rõ ràng !”\n...\nLớn minh .\nVĩnh Lạc bảy năm .\n“ Không hổ là Lý Tư ...”\nChu Lệ cảm khái một tiếng , sau đó rất là nghiêm túc nghĩ nghĩ , nếu như mình là lúc ấy Tần Vương Doanh Chính , sẽ hồi tâm chuyển ý sao ?\nSau đó Chu Lệ gật đầu một cái , nói rất là nghiêm túc nói :\n“ Sẽ !”\n“ Cái này dụ hoặc thật sự là quá lớn , một cỗ thế lực khổng lồ , hoàn toàn nghe theo mệnh lệnh của mình .”\n“ Có thể chống lại bản thổ thế lực , còn có Sở Hệ thế lực , ai cũng không có khả năng cứ như vậy tùy ý bọn hắn từ đầu ngón tay trượt đi .”\n“ Hơn nữa , từ nơi này đến xem , Doanh Chính đã có đối phó Sở Hệ thế lực ý nghĩ .”\nBên cạnh Chu Cao Sí tán đồng gật đầu một cái sau , nhẹ nói :\n“ Phụ thân , dù sao ngồi trên vị trí kia , làm sao có thể còn tùy ý người khác bài bố ?”\n“ Hơn nữa , ta có chút hoài nghi , ngay lúc đó Tần Vương Doanh Chính , là cố ý nghe theo Tần quốc quý tộc ý nghĩ , khu trục Lục quốc thực khách .”\nÂn ?\nChu Lệ quay đầu nhìn về phía chính mình đại nhi , chờ lấy hắn nói tiếp .\n“ Bằng không thì Doanh Chính làm sao có thể duy nhất một lần khu trục Lục quốc thực khách đâu ? Còn có Lý Tư một thiên 《 Gián Trục Khách Thư 》 liền để Doanh Chính hồi tâm chuyển ý ?”\n“ Hơn nữa , từ Tần quốc lịch sử đến xem , Tần Thủy Hoàng Doanh Chính thích dùng nhất , chính là tá lực đả lực .”\n“ Mượn Tần quốc quý tộc tay , tới đả kích những người ngoại lai này thế lực .”\n“ Sau đó , để cho kẻ ngoại lai thế lực giao ra nhập đội , triệt để chưởng khống cỗ này kẻ ngoại lai thế lực .”\n“ Ngay lúc đó Tần Vương Doanh Chính , hẳn là vô cùng rõ ràng những người ngoại lai này thế lực có bao nhiêu yếu ớt , không có bất kỳ cái gì căn cơ .”\n“ Tại Lữ Bất Vi sau khi chết , lập tức liền nghĩ triệt để chưởng khống cái này một cỗ thế lực khổng lồ .”\nChờ Chu Cao Sí nói xong , Chu Lệ rất là nghiêm túc nghĩ nghĩ .\n“ Quả thật có loại khả năng này , nếu như ta là lúc ấy Doanh Chính , ta cũng biết làm như vậy .”\nLúc này Chu Lệ thân là hoàng đế , rất dễ dàng liền làm rõ lúc đó Doanh Chính ý nghĩ .\n“ Nhưng cứ như vậy , chính xác giống phía trước nói , lưu lại tai họa ngầm rất lớn ...”\nChu Lệ nhíu nhíu mày , nhẹ nói .\n“ Này đối ngay lúc đó Doanh Chính tới nói , là giải pháp tốt nhất , phụ thân .”\n“ Tần quốc bản thổ thế lực , Doanh Chính không có cách nào trước tiên nắm giữ .”\n“ Tôn thất thế lực , Doanh Chính không tín nhiệm ! Quý tộc thế lực đâu ? Bọn hắn vĩnh viễn nghĩ chỉ có chính mình một mẫu ba phần đất .”\n“ Lý Tư 《 Gián Trục Khách Thư 》 bên trong Lưu Bạch bộ phận , chính là cố ý bốc lên Doanh Chính ý nghĩ như vậy .”\n“ Đến nỗi Sở Hệ thế lực ? Phụ thân , đừng quên Phù Tô mẫu thân .”\nChu Lệ nghe được cái này , khẽ gật đầu một cái .\n“ Núi có Phù Tô ...”\n“ Doanh Chính ngay lúc đó vương hậu , xem ra cũng là Sở quốc nữ tử .”\nChu Cao Sí không nói gì nói :\n“ Dù sao ngay lúc đó Hoa Dương phu nhân còn không có qua đời , Sở Hệ người dẫn đầu còn tại , Doanh Chính như thế nào lên chức ? Từ Phù Tô liền có thể nhìn ra .”\n“ Giống như là ngay lúc đó thắng dị nhân đổi tên : Thắng Tử Sở .”\n“ Doanh Chính đứa bé thứ nhất , Phù Tô ...”\nChu Lệ nâng chung trà lên , khẽ nhấp một miếng nước trà , chậm rãi nói :\n“《 Sử Ký 》 ghi chép , Phù Tô không nhận Doanh Chính yêu thích , như vậy xem ra , quả thật có nhất định đạo lý .”\n“ Tư Mã Thiên đoán chừng lúc đó cũng là từ một điểm này đoán .”\n“ Hơn nữa , cái này khiến ta nghĩ tới một cái khác hoàng đế .”\nChu Lệ nhìn về phía Chu Cao Sí , nhìn hắn có thể hay không đoán được , chính mình nói chính là cái nào hoàng đế .\n“ Phụ thân , ngươi nói là Hán Vũ Đế Lưu Triệt a ?”\nChu Cao Sí nở nụ cười sau , hồi đáp .\n“ Lão đại , ngươi nói không sai , đúng là Hán Vũ Đế Lưu Triệt .”\n“ Lưu Triệt kinh nghiệm , còn có điều tưởng nhớ suy nghĩ , hoàn toàn có thể bộ đến Doanh Chính ý nghĩ đi lên .”\n“ Bọn hắn thượng vị sau đó một chút kinh nghiệm , cũng là giống nhau như thế .”\n......', 'output\\mp3\\Màn Trời Quyền Lực Diễn Biến Cùng Truyền Thừa\\0036_Thứ 36 chương Có lẽ có đạo lí riêng của nó.mp3', '2026-09-01T13:13:34.227262+00:00', 'completed', 'completed', 8381, 8381),
	(42, 7, '7645513775872754200', 37, 'Thứ 37 chương Giải quyết mâu thuẫn phương thức tốt nhất', 'Thứ chương giải quyết mâu thuẫn phương thức tốt nhất\nHiện đại thời không .\n“ Nói thật , nghe được cái này , có chút ra dự liệu của ta .”\n“ Ta phía trước vẫn cho rằng , Tần Thủy Hoàng Doanh Chính làm sai nhất đích sự tình , chính là đem Tần triều căn cơ , tại Tần quốc thời kì , liền tự mình tiêu trừ .”\n“ Kết quả đây ? Liền đưa đến cuối Tần sau đó , Tần triều nhìn , không một chút căn cơ , ầm vang ở giữa trực tiếp sụp đổ .”\n“ Nhưng thật sự là không nghĩ tới , ngay lúc đó thế cục , kỳ thực là đến khó lường không để Doanh Chính nhất thiết phải đi một bước này .”\nNgụy Gia lúc này cầm lên microphone , hơi xúc động nói .\nTrước đó hắn cùng Lý Ân Phàm bọn hắn thảo luận phương diện này lịch sử thời điểm , chính mình chỉ chú ý tới Tần triều đoạn thời kỳ kia .\nKhông có đi chú ý Tần triều thiết lập phía trước , Tần quốc thời kì .\nĐặc biệt là Doanh Chính thượng vị sau đó kinh nghiệm .\n“ Cho nên ta rất sớm phía trước ngay tại nói , ở phương diện này , không có người nào đối với người nào sai , có vẻn vẹn chỉ là lập trường khác biệt .”\n“ Doanh Chính nghĩ triệt để cầm quyền , vậy thì nhất định phải đi đến một bước này !”\n“ Đến nỗi rất nhiều người có thể sẽ nghĩ , vì sao Doanh Chính lúc đó không đi thử đồ nắm giữ bản thổ quý tộc thế lực đâu ?”\n“ Nếu như bản thổ quý tộc thế lực thật sự như thế hảo chưởng khống , cái kia Tần Mục công sau đó , lịch đại Tần Vương , làm sao lại ngược lại dân địa phương quý tộc thế lực làm ra thỏa hiệp ?”\n“ Khi đó Doanh Chính sơ thượng vị , nghĩ cầm quyền , vậy cũng chỉ có thể cầm những người ngoại lai này thế lực khai đao .”\nLý Ân Phàm mở miệng , nhẹ giọng kể rõ chính mình lý giải .\nNgồi bên cạnh Trần Xuyên Phú khẽ gật đầu một cái , đồng ý Lý Ân Phàm mà nói , chờ Lý Ân Phàm sau khi nói xong , hắn lại cầm ống nói lên nói :\n“ Không chỉ là Tần Vương , các ngươi nếu như cẩn thận nhìn qua Tần Mục công sau đó Tần quốc lịch sử , liền sẽ phát hiện một sự kiện .”\n“ Lịch đại Tần Vương , bọn hắn lên chức thứ trong lúc nhất thời , vì cầm quyền , cũng là cầm kẻ ngoại lai thế lực khai đao .”\n“ Tần quốc quý tộc thế lực ? Bọn hắn đúng là Tần quốc căn cơ , nhưng cũng chính vì như thế , bọn hắn đối với Tần Vương tới nói , mới khó mà nắm giữ .”\n“ Nghĩ triệt để chưởng khống bổn quốc quý tộc thế lực ? Thời kỳ chiến quốc bao quát Tần quốc ở bên trong Thất quốc , cũng không có làm đến chuyện như vậy .”\nĐang ngồi rất nhiều người đối với cái này rất tán thành .\nNếu như bổn quốc quý tộc thế lực thật sự tốt như vậy chưởng khống , cái kia những thứ khác các nước chư hầu , sẽ khó như vậy lấy cải cách sao ?\n“ Nói đến đây , nói một kiện ta hiểu chuyện a .”\n“ Tại các ngươi xem ra , vì cái gì Tần quốc cải cách có thể như vậy thành công ?”\nNghe nói như thế , Lý Ân Phàm cùng Ngụy Gia bọn người chăm chú nhìn Trần Xuyên Phú .\n“ Nếu như các ngươi cẩn thận nhìn qua Tần quốc lịch sử , liền sẽ phát hiện đáp án này thật sự rất đơn giản .”\n“ Bởi vì Tần quốc từ Tần Mục công sau đó , Tần quốc kẻ ngoại lai thế lực , là lớn hơn bản thổ thế lực !”\n“ Đặc biệt là cái gì ? Hậu cung còn có Sở Hệ thế lực , cái này cũng là kẻ ngoại lai thế lực ! Bọn hắn chế trụ tôn thất !”\n“ Tần Quốc Tuyên Thái hậu , cũng chính là mị Bát Tử sau đó , Sở Hệ thế lực triệt để chế trụ tôn thất thế lực .”\n“ Bản thổ trong thế lực , tôn thất thế lực suy thoái , kẻ ngoại lai thế lực cùng quý tộc thế lực lẫn nhau chống lại .”\n“ Cái kia tính quyết định thế lực , là ai ? Có phải hay không Sở Hệ thế lực ?”\n“ Đây chính là vì cái gì Tần quốc cải cách có thể như vậy thành công .”\n“ Cũng chính là từ khi đó bắt đầu , Sở Hệ thế lực cùng kẻ ngoại lai thế lực , muốn áp chế lại bản thổ thế lực , bọn hắn nhất thiết phải làm chính là cái gì ?”\n“ Là kéo dài , không ngừng từ bên ngoài Lục quốc , dẫn tới nhân tài , áp chế lại bản thổ những cái kia thế lực .”\n“ Từ cái này đi xem , có phải hay không vô cùng có thể hiểu được , vì cái gì thắng trụ có hơn 20 đứa bé , Hoa Dương phu nhân không chọn trong Tần quốc bất kỳ một cái nào , ngược lại đi chọn lựa một cái trường kỳ bên ngoài , cùng bản thổ cơ hồ không có bất cứ liên hệ gì thắng dị nhân .”\n“ Sau đó , lại chọn lựa Doanh Chính , cái này cơ thiếp sở sinh hài tử ? Vì sao muốn chọn lựa hắn ? Bởi vì Doanh Chính cũng là , không cùng bản thổ bất kỳ thế lực nào sinh ra quan hệ !”\nTrần Xuyên Phú nói đến đây , ngữ khí bắt đầu hết sức chăm chú :\n“ Từ Tần Quốc Tuyên Thái hậu bắt đầu , Sở Hệ thế lực có thể nói đã đạt thành chung nhận thức .”\n“ Bọn hắn nhất thiết phải cam đoan một sự kiện , Tần quốc hậu cung , nhất định phải là Sở Hệ , không thể trộn lẫn bất luận cái gì một điểm những thế lực khác .”\n“ Dù là sau lưng của ngươi , phi thường nhỏ bé bản thổ quý tộc thế lực , bọn hắn cũng không cần !”\n“ Bằng không thì chờ Tần Vương thượng vị sau đó , Tần Vương đem sau lưng mình quý tộc thế lực kéo lên , cùng Sở Hệ thế lực tại hậu cung đánh lôi đài ?”\n“ Cho nên lịch đại Tần Vương , dù là không muốn , bọn hắn vương hậu , cũng nhất định phải là Sở Hệ .”\n“ Ở trong đó , điển hình nhất là ai ? Chính là thắng trụ !”\n“ Tần Hiếu Văn Vương thắng trụ , có hơn 20 đứa bé , Hoa Dương phu nhân , một đứa bé cũng không có ! Nhưng cuối cùng , ngược lại là Hoa Dương phu nhân nhận một cái con nuôi .”\n“ Liền cái này con nuôi , cũng chính là thắng dị nhân , cuối cùng leo lên Thái tử , ngồi lên Tần quốc quốc vương vị trí .”\n“ Cái này từ phía sau triều đại lịch sử đi xem , đây là phi thường không thể tưởng tượng nổi một sự kiện .”\n“ Nhưng cũng chính là chuyện như vậy , hoàn toàn có thể thấy được , Sở Hệ thế lực tại lúc đó rốt cuộc có bao nhiêu khổng lồ !”\n“ Đặc biệt là tại trong Tần quốc , Sở Hệ rốt cuộc có bao nhiêu lớn tính quyết định sức mạnh .”\n“ Vậy mà hoàn toàn có thể quyết định Tần quốc quốc quân vị trí !”\nTại Trần Xuyên Phú xem ra , tại lúc đó , Sở Hệ thế lực , có thể nói so rất nhiều người tưởng tượng còn lớn hơn .\nLiền chỉ từ thắng dị nhân thượng vị , còn có Doanh Chính thượng vị , liền hoàn toàn có thể nhìn ra .\n“ Cho nên cái này cũng là vì cái gì về sau Doanh Chính muốn triệt để đả kích hết Sở Hệ thế lực ?”\nNgụy Gia lúc này mở miệng hỏi hướng Trần Xuyên Phú .\n“ Ở đây kỳ thực có một chút sai lầm .”\nTrần Xuyên Phú khe khẽ lắc đầu , sau đó chậm rãi nói :\n“ Ngay lúc đó Tần Vương Doanh Chính , ban đầu căn bản không muốn đả kích Sở Hệ thế lực .”\n“ Doanh Chính cầm quyền sau đó , trước hết nhất đả kích là ai ? Là bản thổ quý tộc thế lực !”\n“ Đây là rất dễ dàng lý giải .”\n“ Sau khi ngươi thượng vị , khu trừ Lữ Bất Vi , tiếp đó triệt để nắm trong tay kẻ ngoại lai thế lực , vậy ngươi xem lấy trên triều đình thế cục , ngươi sẽ nghĩ đến trước đả kích ai ? Có phải hay không ngoài ra bản thổ thế lực ?”\n“ Mới nắm giữ kẻ ngoại lai thế lực , liền nghĩ đi đả kích lúc đó lớn nhất Sở Hệ thế lực sao ?”\n“ Chỉ cần là người bình thường , đều sẽ không làm như vậy !”\nSau đó , Trần Xuyên Phú dừng một chút , cẩn thận suy tư một hồi sau , nhìn xem mấy người , lại tiếp tục nói :\n“ Ở đây hỏi các ngươi một vấn đề , nếu như các ngươi nghĩ cầm quyền , sẽ làm như thế nào ?”\n“ Đời sau hoàng đế bên trong , có chơi chính trị thủ đoạn , cũng có chơi âm mưu , đúng hay không ?”\n“ Nhưng ở thời kỳ chiến quốc , đơn giản nhất thủ đoạn là cái gì ? Rất đơn giản , phát động chiến tranh !”\n“ Bây giờ có một câu nói , hết thảy nội bộ mâu thuẫn , cũng có thể hướng ra phía ngoài thay đổi vị trí !”\n“ Ngược lại nhìn đâu ? khi ngươi nghĩ lúc ta cầm quyền , cái kia phát động chiến tranh , chính là thủ đoạn tốt nhất !”\n“ Từ xưa đến nay , đều là như thế !”\n“ Nếu như các ngươi biết trong lịch sử rất nhiều hoàng đế , các ngươi liền sẽ phát hiện một sự kiện .”\n“ Trong lịch sử quyền hạn lớn nhất hoàng đế , cơ hồ tất cả đều là chiến tranh lập nghiệp , hay là dùng chiến tranh thủ đoạn tới thu quyền !”\nLời này vừa ra , Lương Phong cùng Ngụy Gia cùng với Lý Ân Phàm đều nghiêm túc suy tư .\nCuối cùng phát hiện quả thật là như thế , trong lịch sử quyền hạn lớn nhất hoàng đế , cơ hồ cũng là lấy chiến tranh lên , hay là dùng chiến tranh thủ đoạn tới thu quyền .\n“ Cái này tại thời kỳ chiến quốc , vô cùng phổ biến !”\n“ Nhưng tại sao lại như thế ?”\n“ Bởi vì chiến tranh thứ này , được là được , không được là không được ! Lúc này quốc quân , hoàn toàn liền có thể làm một cái trọng tài , lai tài quyết mấy phe thế lực tranh đấu .”\n“ Cho dù là hậu cung thế lực ? Cũng hoàn toàn có thể đem ngươi lôi vào ! Đặc biệt là những cái kia hậu cung xếp vào trên triều đình quân cờ .”\n“ Này đối một cái quốc quân tới nói , hoàn toàn là quá có lợi !”\n“ Cái này cũng là vì cái gì chiến tranh lập nghiệp hoàng đế , quyền lực của bọn hắn to lớn như thế nguyên nhân lớn nhất .”\n“ Thắng ? Cái kia phe thắng mở rộng quyền hạn , phản đối một phương , tự nhiên quyền hạn liền tiểu .”\n“ Mà thua đâu ? Phe thua thu nhỏ quyền hạn , phe thắng , mở rộng quyền hạn .”\n“ Này đối quốc quân tới nói , có bất kỳ thiệt hại sao ?”\nTrần Xuyên Phú nói đến đây , cười nhẹ lắc đầu nói :\n“ Không có bất kỳ cái gì thiệt hại ! Mà tại ở trong đó , hoàn toàn liền có thể xếp vào thân tín của mình !”\n“ Đến nỗi nói hiện đại những cái kia chiến tranh thua , dưới sự lãnh đạo đài vấn đề ?”\n“ Tại thời điểm này , nhưng hoàn toàn không có vấn đề như vậy !”\n......', 'output\\mp3\\Màn Trời Quyền Lực Diễn Biến Cùng Truyền Thừa\\0037_Thứ 37 chương Giải quyết mâu thuẫn phương thức tốt nhất.mp3', '2026-09-01T13:13:38.620136+00:00', 'completed', 'completed', 9039, 9039),
	(43, 7, '7645513981175530008', 38, 'Thứ 38 chương Xác suất nhỏ', 'Thứ chương Xác suất nhỏ\nHiện đại thời không .\n“ Cho dù là thua , thủ hạ cõng nồi , sau đó thì sao ? Tiếp đó lại cất nhắc lên một vị thân tín của mình .”\n“ Dạng này thế cục , đối với ngay lúc đó quốc quân tới nói , không phải có lợi nhất cục diện sao ?”\n“ Cho nên , thời kỳ chiến quốc , rất nhiều các nước chư hầu thường xuyên phát động chiến tranh , nguyên nhân lớn nhất một trong , kỳ thực ngay ở chỗ này !”\nSau đó , Trần Xuyên Phú trầm mặc một hồi sau , nhàn nhạt mở miệng nói ra :\n“ Kỳ thực ta biết , hiện đại rất nhiều người ưa thích Tần Thủy Hoàng Doanh Chính , cho rằng ngay lúc đó Doanh Chính thống nhất Lục quốc , chiều hướng phát triển .”\n“ Nhưng rất đáng tiếc , càng ngày càng nhiều tư liệu lịch sử , bắt đầu đã chứng minh một sự kiện .”\n“ Tần Diệt Lục quốc , kỳ thực là siêu cấp xác suất nhỏ một sự kiện .”\nNói đến đây , Trần Xuyên Phú dừng một chút , sau đó tiếp tục mở miệng nói :\n“ Nói như vậy , nếu như ngay lúc đó Tần quốc quốc quân , không phải Tần Vương Doanh Chính , mà là đổi thành hắn Vương đệ , Trường An quân thành kiểu .”\n“ Tần quốc lớn vô cùng xác suất , là không diệt được Lục quốc .”\n“ Vì cái gì ?”\n“ Còn nhớ rõ vừa rồi chúng ta nói nhiều như vậy thắng dị nhân cùng Doanh Chính lên chức chuyện sao ?”\n“ Nếu như Tần Thủy Hoàng không phải vừa lúc là một cái giới quý tộc người ngoài cuộc , cùng sáu quốc đô không có thân thích gì quan hệ , khả năng cao là không tâm tình động một chút lại diệt quốc .”\n“ Không đúng , phải nói cùng Thất quốc quý tộc cũng không có thân thích gì quan hệ .”\n“ Bởi vì cho dù là Tần quốc nội bộ quý tộc , hắn đều không có thân thích gì quan hệ .”\n“ Tôn thất thế lực ? Tôn thất thế lực đều bị hắn đả kích không có âm thanh !”\nNói đến đây , Trần Xuyên Phú lại bắt đầu nói đến phía trước nói lời đề .\n“ Hơn nữa , Doanh Chính nếu như không phải là vì cầm quyền , có thể hay không như thế thường xuyên phát động chiến tranh ?”\n“ Không biết ! Nhưng khả năng cao thì sẽ không !”\n“ Tại ở trong đó , Doanh Chính hùng tâm tráng chí , vì cầm quyền , thường xuyên phát động chiến tranh , lại là trong đó mấu chốt một vòng .”\nLý Ân Phàm lúc này tiếp lời đề , cầm ống nói lên , nhẹ nói :\n“ Trong đó còn có mấu chốt một vòng , đó chính là Hoa Dương phu nhân qua đời .”\n“ Hoa Dương phu nhân qua đời thời gian , cũng là phi thường mấu chốt , Thủy Hoàng Đế mười bảy năm , Hoa Dương phu nhân qua đời .”\n“ Tại cái này trước khi qua đời , Doanh Chính đã dựa vào thủ đoạn của chiến tranh , thu hẹp rất lớn một bộ phận quyền hạn .”\nSau đó , Lý Ân Phàm bắt đầu từng cái kể rõ phía trước Doanh Chính phát động qua chiến tranh .\n“ Thủy Hoàng Đế mười một năm ( Phía trước năm ), triệu , yến hai nước phát sinh chiến tranh . Triệu quốc xuất binh công yến , mà Tần quốc cứu yến làm tên phái Vương Tiễn mấy người đem xuất binh phân biệt giáp công Triệu quốc , tuần tự đánh chiếm Triệu Át cùng , lao dương ( Nam Dương Tây Bắc ), Hà Gian ( Tỉnh Hà Bắc hiến huyện Đông Nam ), An Dương ( Hà Bắc dương nguyên huyện Đông Nam ) các loại ấp , Chương Thủy lưu vực đã vì Tần chiếm hữu .”\n“ Thủy Hoàng Đế mười ba năm ( Phía trước năm ), Tần quốc lại quy mô lớn hướng Triệu quốc tiến công , lấy lấy triệu mà thiết lập Nhạn Môn quận cùng trong mây quận .”\n“ Thủy Hoàng Đế mười sáu năm ( Phía trước năm ), Ngụy quốc bị thúc ép đem bộ phận thổ địa hiến Tần , Hàn Quốc cũng bị thúc ép đem Nam Dương mà hiến tặng cho Tần . Trong Tần phái Sử Đằng làm Nam Dương giả phòng thủ .”\n“ Thủy Hoàng Đế mười bảy năm ( Phía trước năm ), trong Tần phái Sử Đằng công Hàn , bắt làm tù binh Hàn vương sao , tại Hàn mà kiến trí Dĩnh Xuyên quận , Hàn Quốc diệt vong .”\nNói đến đây , Lý Ân Phàm nhìn xem máy quay phim , chậm rãi tiếp tục nói :\n“ Cũng chính là một năm này , Tần quốc tiêu diệt lục quốc trung thứ nhất các nước chư hầu , Hàn Quốc .”\n“ Giống như mới vừa nói , nếu như Doanh Chính không phải Lục quốc giới quý tộc bên ngoài , thật sự xác suất rất lớn sẽ không thống nhất Lục quốc .”\n“ Đằng sau diệt Sở thời điểm , nội bộ Sở quốc thế lực liền nhảy ra điên cuồng ngăn cản .”\n“ Cái kia diệt Hàn đâu ?”\n“ Ai biết nội bộ Sở quốc thế lực , có thể hay không bởi vì một chút nguyên nhân , ngăn cản diệt Hàn ?”\nLý Ân Phàm nghĩ tới chỗ này thời điểm , cũng là có chút do dự chính mình suy đoán .\n“ Hoa Dương phu nhân ở ngay lúc đó Tần quốc , quá mấu chốt .”\n“ Nàng tại , Sở quốc người dẫn đầu ngay tại , Sở Hệ thế lực , chính là Tần quốc nội bộ thế lực lớn nhất .”\n“ Mà đợi nàng sau khi qua đời , Tần quốc nội bộ thế lực lớn nhất đã biến thành ai ? Doanh Chính !”\n“ Doanh Chính khi đó vừa vặn thu hẹp một bộ phận quyền hạn , mà Sở Hệ thế lực , là bởi vì Hoa Dương phu nhân qua đời , không có chỗ dựa , dần dần đi xuống dốc .”\n“ Ai biết Hoa Dương phu nhân nếu như còn ở đó , có thể hay không bởi vì quý tộc quan hệ thân thích , ngăn cản diệt Hàn ?”\n“ Dù sao nói thật , đứng tại Hoa Dương phu nhân góc độ đi xem , ngươi Doanh Chính diệt Hàn , có phải hay không còn muốn diệt Sở ?”\n“ Mà diệt sở , vậy chúng ta nội bộ Sở Hệ thế lực , liền sẽ bị ngươi triệt để tiêu diệt ?”\n“ Về sau Sở quốc nội bộ thế lực , ngăn cản diệt Sở , cũng là bởi vì nguyên nhân này , cho nên , Hoa Dương phu nhân ...”\nCái này cũng là Lý Ân Phàm nhìn lịch sử thời điểm , cảm thấy không tốt có kết luận một cái điểm .\nHoa Dương phu nhân , tại Tần quốc trong lịch sử , quá mấu chốt .\n“ Nhìn Châu Âu bên kia lịch sử , nói như thế nào đây ? Quả thật là như thế .”\nLương Phong lúc này cũng gật đầu công nhận Lý Ân Phàm quan điểm .\n“ Thủy Hoàng mười bảy năm , cái thời điểm này , quá mấu chốt , Hoa Dương phu nhân vừa vặn qua đời , cũng chính là một năm này , sáu trong nước thứ nhất quốc gia , Hàn Quốc diệt vong .”\nNgụy Gia bỗng nhiên mở miệng , nhìn về phía Trần Xuyên Phú hỏi :\n“ Ta có một cái vấn đề , Tần quốc nội bộ Sở Hệ phản loạn , là lúc nào bắt đầu ?”\nKhi nào thì bắt đầu ?\nTrần Xuyên Phú nghe được vấn đề này , nhíu nhíu mày , rất là nghiêm túc suy tư một hồi .\n“ Khả năng cao , tại Hoa Dương phu nhân sau khi qua đời , Hàn Quốc diệt vong lại bắt đầu .”\n“ Bọn hắn muốn lần nữa nắm giữ quyền lực địa vị , vậy cái này thời điểm liền nhất định sẽ bắt đầu , nhưng lúc này chỉ có thể nói bắt đầu chính trị đấu tranh .”\n“ Phản loạn ? Vẫn còn không tính là .”\nSau đó , Trần Xuyên Phú dừng một chút , như có điều suy nghĩ nói :\n“ Ngược lại , nếu là ta là người thế lực Sở Hệ , tại Hoa Dương phu nhân sau khi qua đời , nhất định sẽ vì một lần nữa trở thành thế lực lớn nhất bắt đầu chính trị tranh đấu .”\n“ Đặc biệt là chính mình là Sở quốc quý tộc , sau khi Hàn Quốc diệt vong , có khả năng hay không có thỏ tử hồ bi cảm giác ?”\nTrần Xuyên Phú nghĩ tới đây , rất là nghiêm túc suy tư một hồi sau , chậm rãi nói :\n“ Không biết , tin tức quá ít .”\n“ Hiện có tư liệu lịch sử , nói chỉ là Sở quốc thế lực , tại Doanh Chính để cho Lý Tín diệt Sở thời điểm , phát động phản loạn .”\n“ Lúc khác sao ?”\n“ Chiến tranh phát động càng ngày càng thường xuyên , này ngược lại là thật sự !”\nLý Ân Phàm lúc này bắt đầu tiếp lời đề , cầm ống nói lên , nhẹ nói :\n“ Thủy Hoàng 18 năm , Tần Tương Vương Tiễn suất lĩnh binh sĩ thẳng xuống dưới Tỉnh Hình ( Tỉnh Hà Bắc Tỉnh Hình huyện tây ), Tần Tương dương đoan hòa suất lĩnh trong sông binh tiến vây triệu đều Hàm Đan .”\n“ Thủy Hoàng Đế 19 năm ( Phía trước năm ), đại phá Triệu Quân , Vương Tiễn , Khương hối tận định triệu địa , tù binh Triệu vương .”\n“ Thủy Hoàng Đế hai mươi năm ( Phía trước năm ), Tần Vương chính phái đại tướng Vương Tiễn , tân thắng công Yến quốc .”\n“ Thủy Hoàng Đế hai mươi mốt năm ( Phía trước năm ), Hàn Quốc đô thành phát sinh phản loạn , Tần quốc xuất binh bình định Hàn phản loạn , thừa cơ xử tử Hàn vương sao .”\n“ Thủy Hoàng Đế hai mươi hai năm ( Phía trước năm ), Tần Vương chính phái tướng quân Vương Bí công Ngụy .”\nNói xong cái này , trên đài mấy người đều gật đầu một cái .\n“ Càng lúc càng nhanh ...”\nNgụy Gia cảm khái một tiếng , sau đó lại hỏi một vấn đề .\n“ Ở đây ta có một cái vấn đề , ngay lúc đó Tần Vương Doanh Chính , là thế nào đả kích bản thổ quý tộc thế lực ?”\nTrần Xuyên Phú nhận lấy cái đề tài này , cầm ống nói lên , nhìn xem hắn nói :\n“ Đánh như thế nào kích ? Tần Diệt Lục quốc , những tướng lãnh này , có người nào là lão Tần người ?”\nNghe được vấn đề này , Ngụy Gia nháy nháy mắt , hơi nghi hoặc một chút nhẹ giọng hỏi :\n“ Lý Tín không phải sao ?”\n“ Lý Tín không phải , Lý Tín tiên tổ , Lý Tông là Ngụy quốc đại phu .”\n“ Tằng tổ Lý Đàm thời điểm , đi tới Tần quốc , làm Tần quốc ngự sử đại phu .”\nSau đó , Trần Xuyên Phú tiếp tục nói :\n“ Toàn bộ Tần quốc lục quốc trung , tất cả tướng lĩnh , cơ hồ không có một cái là cái gọi là Tần quốc bản thổ quý tộc , cũng chính là lão Tần người .”\n“ Tại thống nhất Lục quốc thời gian bên trong , Doanh Chính càng thành công , vậy hắn quyền hạn , cũng liền càng lớn .”\n“ Đây là chuyện đương nhiên một sự kiện .”\n" Mà tới được thống nhất Lục quốc , thiết lập Tần triều sau đó , Doanh Chính quyền hạn triệt để đạt đến đỉnh phong , nội bộ quý tộc thế lực , tôn thất thế lực , triệt để không ngóc đầu lên được .”\n“ Sở quốc thế lực , cũng bị triệt để tiêu diệt .”\nLúc này , Lương Phong đột nhiên mở miệng , rất là chăm chú nhìn mấy người nói :\n“ Ở đây , nói một cái rất phản trực giác chuyện , đứng tại Phù Tô lập trường , đằng sau hắn tự sát , kỳ thực rất bình thường ...”\nÂn ?\nNghe nói như thế , trên đài Lý Ân Phàm mấy người phi thường kinh ngạc nhìn xem hắn .\nDưới đài Mông Điềm , cũng hết sức chăm chú , ngưng mắt nhìn chăm chú lên hắn .\n......', 'output\\mp3\\Màn Trời Quyền Lực Diễn Biến Cùng Truyền Thừa\\0038_Thứ 38 chương Xác suất nhỏ.mp3', '2026-09-01T13:13:44.280728+00:00', 'completed', 'completed', 9328, 9328),
	(44, 7, '7645514379198202392', 39, 'Thứ 39 chương Một ngày này, rốt cuộc đã đến?', 'Thứ chương Một ngày này , rốt cuộc đã đến ?\nLớn minh .\nVĩnh Lạc bảy năm .\n“ Nói như vậy , đứng tại Phù Tô lập trường , chính xác không có vấn đề .”\n“ Người , chỉ có thể nhìn thấy mình có thể nhìn thấy một mặt kia .”\nChu Cao Sí nghe được màn trời nghe được lời này , chậm rãi gật đầu một cái , biểu thị tán đồng .\nĐặc biệt là hắn bây giờ thân ở Thái tử chi vị , thì càng có thể phát hiện là như thế .\nNếu như không phải mình triệt để thấy rõ ràng bây giờ Vĩnh Lạc hướng cục thế chính trị , Chu Cao Sí cũng có khả năng giống trong lịch sử rất nhiều bi thảm Thái tử .\nThế nhưng chính là bởi vì triệt để thấy rõ ràng tình thế , hắn mới phát hiện , trong lịch sử rất nhiều Thái tử kết cục bi thảm , kỳ thực cũng có thể tránh khỏi .\n“ Chỉ có thể nói ta tương đối may mắn ...”\nChu Cao Sí chính xác cảm thấy chính mình tương đối may mắn , bởi vì chính mình có một cái yêu mến mẹ của mình , một cái được xưng là “ Nữ Gia Cát ” Mẫu thân .\nNếu như không phải mẫu thân thường xuyên dạy bảo chính mình mở rộng tầm mắt , có thể chính mình kết cục cùng trong lịch sử những cái kia bi thảm Thái tử , là giống nhau .\n“ Mẫu thân hẳn là cũng không nghĩ tới trên ta sẽ làm Thái tử a ? Trước đây có thể chỉ là hy vọng ta cái này thế tử , đối với bọn đệ đệ tốt một chút ?”\nChu Cao Sí đầu não bắt đầu tư duy phát tán ...\n...\nĐại hán .\nNguyên thú 4 năm .\n“ Dạng này đi xem , Phù Tô tự sát , chính xác không có vấn đề .”\nLưu Triệt chậm rãi gật đầu một cái , nhận đồng màn trời nói tới cái này nhìn qua điểm .\n“ Hơn nữa sau đó thế cục , cũng không trở về được Tần quốc thời kỳ thế cục .”\n“ Huống hồ coi như về tới Tần quốc thời kỳ loại kia thế cục , Phù Tô thật có thể thượng vị sao ?”\nLưu Triệt bỗng nhiên nghĩ tới điểm này , sau đó gật đầu một cái nói :\n“ Hẳn là có thể lên chức , bởi vì hắn là Sở quốc vương hậu vị trí trưởng tử ...”\n“ Nhưng những thứ khác những cái kia thế lực , thật sự cam tâm ?”\nNghĩ tới đây , Lưu Triệt lại lắc đầu nói :\n“ Có thể hay không lại ra một cái Triệu Cao ? Hay là Tần Cao ?”\n“ Từ dạng này quyền hạn lợi ích đến xem , cuối Tần thời kì , Triệu Cao sau lưng nhất định là những cái kia không cam lòng thế lực .”\n“ Vậy coi như cuối Tần chính trị cách cục thật sự về tới Tần quốc Doanh Chính thượng vị thời kỳ loại kia , Phù Tô thật có thể thượng vị ?”\nLưu Triệt đối với điểm này , biểu thị khắc sâu hoài nghi .\nDù sao những người kia cũng dám liên hợp Triệu Cao , cái kia còn có chuyện gì , là bọn hắn không dám làm ?\n“ Hơn nữa , Sở quốc phá diệt sau đó , Sở quốc thế lực coi như còn tại , thì có ích lợi gì đâu ?”\n“ Tần Diệt Lục quốc thống nhất thiên hạ , mặc dù không có mở rộng bản thổ những quý tộc kia thế lực , nhưng lại đánh tan còn lại Lục quốc quý tộc thế lực , đây không phải biến tướng lớn mạnh Tần quốc quý tộc thế lực sao ?”\nLưu Triệt trầm mặc nhìn xem màn trời , tiếp tục suy tư .\n“ Hơn nữa , Tần Hiếu Văn Vương thắng trụ , cùng Tần Trang Tương vương thắng Tử Sở , thật là bình thường tử vong sao ?”\nThân là hoàng đế , Lưu Triệt bản năng hoài nghi hết thảy .\nMột cái làm mười mấy năm Thái tử người , thượng vị sau đó , ba ngày liền bỗng nhiên qua đời .\n“ Hắn có phải hay không muốn cải lập Thái tử ?!”\nLưu Triệt bỗng nhiên nghĩ tới điểm này .\nBởi vì thắng dị nhân được lập làm người thừa kế , ngay lúc đó thắng trụ vẫn là Thái tử , Tần Chiêu Tương vương , đã làm mấy chục năm Tần quốc quốc quân .\nLúc này Hoa Dương phu nhân , coi như dùng dỗ ngon dỗ ngọt lừa Tần Hiếu Văn Vương thắng trụ , có thể thắng trụ cũng không quan tâm .\nBởi vì hắn có thể cũng không biết mình có thể hay không thượng vị quốc quân , dù sao Tần Chiêu Tương vương đã làm mấy chục năm quốc quân .\nCho nên , thượng vị sau đó , thấy rõ ràng cục thế chính trị , bỗng nhiên liền đổi ý ?\nNghĩ lập chính mình những hài tử khác ? Tiếp đó liền bị hậu cung Sở Hệ ám hại ?\nLưu Triệt biết , chính mình bệnh đa nghi lại phát tác , nhưng hắn thượng vị sau đó kinh nghiệm , để cho hắn bản năng hoài nghi hết thảy , không tin bất luận kẻ nào .\n“ Vậy nếu như thật là dạng này , Tần Trang Tương vương , thắng dị nhân đâu ? Lại là vì cái gì ?”\nTư liệu vẫn là quá ít , Lưu Triệt vuốt vuốt trán của mình , chuẩn bị ngừng hướng phương diện này suy xét .\n...\nHiện đại thời không .\n“ Vì cái gì nói đứng tại Phù Tô lập trường , hắn tự sát , rất bình thường ?”\n“ Đại gia suy nghĩ một chút , chính mình giờ phút này là Phù Tô .”\n“ Theo ý của ngươi , ngươi cũng không được sủng ái , được cưng chìu là ai ? Hồ Hợi !”\n“ Phụ thân của mình , cũng thường xuyên trách mắng mình , không hài lòng chính mình .”\n“ Hơn nữa , quan trọng nhất là cái gì ? Là chính mình mẫu tộc , bị phụ thân của mình , toàn bộ diệt trừ !”\n“ Mẹ của mình đâu ?”\nLương Phong bỗng nhiên nhắc tới điểm này , Phù Tô mẫu thân .\n“ Trong lịch sử cũng không có ghi chép Phù Tô mẫu thân , cho dù là 《 Sử Ký 》, cũng không có ghi chép Phù Tô mẫu thân , đến cùng chuyện gì xảy ra .”\n“ Nhưng chúng ta phía trước đã làm phỏng đoán , Phù Tô mẫu thân , nhất định là Sở quốc vương hậu .”\n“ Mà tại Tần quốc thống nhất Lục quốc , tiêu diệt Sở quốc phía trước , nội bộ Sở Hệ thế lực , liền đã bị Doanh Chính tiêu diệt .”\n“ Vậy cái này Sở quốc vương hậu , kết cục tốt nhất , nhất định là sung quân lãnh cung .”\n“ Hơn nữa , khía cạnh có một chút có thể chứng minh cái này nhìn qua điểm , là cái gì ? Tần quốc thiết lập sau đó , Doanh Chính không có lập hoàng hậu !”\n“ Vì cái gì không lập hoàng hậu ? Nhất định là Tần quốc vương hậu , đem hắn tâm cho thương thấu .”\n“ Để cho hắn sinh ra một ít không thể nói bóng ma tâm lý , để cho hắn không muốn lại lập hoàng hậu .”\n“ Bởi vì hoàng hậu nếu không chết , cuối cùng sẽ trở thành cái gì ? Trở thành Thái hậu !”\nNói đến đây , Lương Phong nhẹ nhàng nói ra bốn chữ :\n“ Hoa Dương phu nhân ...”\n“ Cho nên , từ cái này một bên mặt phỏng đoán đến xem , Sở Hệ thế lực , hậu cung thế lực , nhất định là đem Doanh Chính tâm cho thương thấu , để cho hắn không muốn lại lập hoàng hậu .”\n“ Điểm này , từ Doanh Chính góc độ cùng lập trường đi xem , là không có vấn đề !”\nLương Phong gật đầu một cái , không có đối với điểm này nói ra lời gì , sau đó lại tiếp tục nói :\n“ Nhưng chúng ta nghĩ , từ Phù Tô lập trường và góc độ đi xem đâu ?”\n“ Chính mình mẫu tộc , bị tiêu diệt ! Mẹ của mình ? Kết cục tốt nhất là sung quân lãnh cung .”\n“ Chính mình lại không được sủng ái , thường xuyên bị quở trách , phụ thân Doanh Chính lại xưa nay không cho mình một cái hoà nhã .”\n“ Cái kia tại Phù Tô xem ra , chính mình thân là trưởng tử , có phải hay không cũng không có thượng vị hoàng đế khả năng ?”\nNói đến đây , Lương Phong dừng một chút , lời nói xoay chuyển lại nói :\n“ Hơn nữa , Phù Tô trưởng tử , cái này đích , có thể còn muốn đánh một cái dấu chấm hỏi ?”\n“ Vì cái gì ? Bởi vì Doanh Chính cũng không có lập hoàng hậu ! Tất nhiên không có hoàng hậu , cái kia trưởng tử cái này đích , đến từ đâu ?”\n“ Chỉ có thể nói , Phù Tô là trưởng tử !”\n“ Nhưng chúng ta giờ phút này đứng tại Phù Tô góc nhìn đi xem Tần quốc lịch đại quốc quân thượng vị , trưởng tử lên chức có mấy cái ?”\n“ Cho dù là gần nhất , thắng dị nhân , gia gia của mình , hắn là trưởng tử thượng vị sao ? Là nhận Hoa Dương phu nhân làm mẫu thân mới thượng vị !”\n“ Phụ thân của mình , là trưởng tử sao ? Đánh một cái dấu chấm hỏi , có thể là trưởng tử , nhưng tuyệt đối không phải trưởng tử .”\n“ Cho nên , vì sao Phù Tô nhìn thấy một phong bị xuyên tạc di chiếu , liền quả quyết tự sát ?”\n“ Khi ta đứng tại Phù Tô lập trường đi suy xét vấn đề này , ta kỳ thực chỉ có một cái ý nghĩ .”\n“ Ý nghĩ này là cái gì ?”\n“ Một ngày này , rốt cuộc đã đến !”\n...', 'output\\mp3\\Màn Trời Quyền Lực Diễn Biến Cùng Truyền Thừa\\0039_Thứ 39 chương Một ngày này, rốt cuộc đã đến.mp3', '2026-09-01T13:14:07.167367+00:00', 'completed', 'completed', 7452, 7452),
	(45, 7, '7645514541475824152', 40, 'Thứ 40 chương Trường sinh hoàng đế', 'Thứ chương Trường sinh hoàng đế\nHiện đại thời không .\n“ Một ngày này , rốt cuộc đã đến ?”\nNghe nói như thế , Lý Ân Phàm cùng Ngụy Gia cùng với Trần Xuyên Phú 3 người , đều là sững sờ .\nĐúng vậy a , từ Phù Tô lập trường đi xem , một ngày này , không phải liền là rốt cuộc đã đến sao ?\nChính mình mẫu tộc , mẹ của mình , cuối cùng , lại đến chính mình .\n“ Từ Phù Tô lập trường và góc độ đi xem , hắn sau cùng ý nghĩ , nhất định là cái gì ? Phụ thân của mình , xem ra nhất định muốn tiêu diệt hết sau cùng Sở Hệ thế lực .”\n“ Mà sau cùng Sở Hệ thế lực , người dẫn đầu là ai ? Đương nhiên là chính mình !”\nMọi người tại đây đều là trầm mặc .\nDưới đài Mông Điềm thở dài một hơi , lúc này hắn cũng phát hiện , người viết sử tái , vì cái gì chính mình không khuyên nổi Phù Tô .\nBởi vì từ Phù Tô góc nhìn cùng lập trường của hắn đi xem , thật đúng là dạng này .\n“ Cái này cũng là vì sao Phù Tô cuối cùng tin tưởng vững chắc phụ thân của mình chính là muốn giết chính mình , mà Phù Tô chính mình cũng quả quyết tự sát nguyên nhân .”\n“ Chủ yếu thật sự từ Phù Tô góc độ đi xem , sự tình phát triển , cũng là từng bước một bức bách chính mình .”\n“ Đến cuối cùng , cái kia cũng rất chuyện đương nhiên , phụ thân của mình Doanh Chính đã không kiên nhẫn được nữa , muốn triệt để tiêu diệt Sở Hệ thế lực .”\nLương Phong nhún vai , rất thẳng thắn nói .\n“ Cho nên , cũng không phải cái gì Phù Tô học được nho gia , trở nên ngu trung , Phù Tô từ người viết sử tái đến xem , cũng không ngu trung .”\n“ Trên triều đình , còn thường xuyên phản bác Doanh Chính .”\n“ Mà người như vậy , tại sao có thể là ngu trung ?”\nDoanh Chính nghe đến đó , sắc mặt mờ mịt , không biết suy nghĩ cái gì .\n‘ Chính mình làm hết thảy , thật sự cũng là đang từng bước bức bách Phù Tô sao ?’\nDoanh Chính vui không yêu thích Phù Tô ? Đương nhiên là yêu thích , bằng không thì Doanh Chính nhiều như vậy hài tử , vì cái gì liền Phù Tô một cái tham chính ?\nYêu thích Hồ Hợi ? Vì cái gì không để Hồ Hợi đi tham chính ?\nTham chính , mới là người thừa kế !\nGiống như phía trước nói tới , một cái công ty lớn , chủ tịch có bảy hài tử , nhưng ở trong đó , chỉ có một đứa bé là tiến vào công ty lịch luyện .\nĐây rốt cuộc ai là người thừa kế , còn phải nói sao ?\nĐương nhiên là tiến công ty lịch luyện , chính mình tự tay bồi dưỡng , cái kia mới là người thừa kế .\nTừ xưa đến nay , mặc kệ là trong lịch sử tất cả triều đại , vẫn là hiện đại , đều là như thế !\n“ Ở đây ta có một chút nghi hoặc , Phù Tô nếu như thông minh , hẳn là có thể thấy rõ ràng thế cục a ?”\n“ Doanh Chính tất cả trong hài tử , chỉ có Phù Tô một người là tham chính , hắn vì cái gì thì nhìn mơ hồ Doanh Chính bồi dưỡng người thừa kế , là chính mình đâu ?”\nNgụy Gia lúc này cầm ống nói lên , đưa ra nghi ngờ của mình .\nBởi vì hắn thấy , điểm này hẳn là nhìn rất đẹp thanh ba ? Doanh Chính có hơn 20 đứa bé , liền Phù Tô tự mình một người là tham chính .\nHuống hồ , coi như Phù Tô tự nhìn mơ hồ , người bên ngoài cũng sẽ không nhắc nhở hắn sao ? Đặc biệt là Mông Điềm .\nMông Điềm cũng cần phải sẽ nhắc nhở hắn a ?\n“ Có khả năng hay không , Phù Tô chính là bởi vì thấy rõ ràng , mới tự sát đây này ?”\n“ Trong lịch sử , có bao nhiêu bi thảm như vậy Thái tử ? Bọn hắn vì cái gì cuối cùng vẫn là từng bước một đi về phía vực sâu ?”\n“ Chính mình là người thừa kế sao ? Không phải , chính mình là công cụ ! Một cái hoàng đế cân bằng triều đình thế lực công cụ !”\n“ Rất nhiều người còn không để ý đến một điểm , Tần triều thời kì , ngay lúc đó Tần Thủy Hoàng Doanh Chính , còn có một cái ý nghĩ , đại gia hẳn là rất quen thuộc .”\n“ Đó chính là trường sinh !”\n“ Một cái hoàng đế muốn trường sinh , cái kia đứng tại Thái tử , hoặc có lẽ là , đứng tại Phù Tô góc nhìn đi xem .”\n“ Đây là cái gì ?”\nTrường sinh ?\nMọi người đang ngồi người nghe vậy đều là khẽ giật mình .\nBọn hắn chính xác không để ý đến điểm này .\nMột cái hoàng đế muốn trường sinh , từ lịch sử đi xem , đúng là không có vấn đề .\nNhưng từ Thái tử , một cái người thừa kế góc nhìn đi xem đâu ?\n“ Chính mình cũng không phải cái gì người thừa kế , chỉ là cân bằng triều đình thế lực công cụ .”\n“ Cũng không hài lòng chính mình , chỉ là tạm thời cất nhắc lên một con cờ ? Một cái công cụ ...”\nLý Ân Phàm giờ khắc này , có rất nhiều ý nghĩ .\nTrước đó hắn chính xác không có chú ý tới điểm này , trong lịch sử những cái kia muốn trường sinh hoàng đế , từ thị giác bọn họ đi xem , tự mình làm chính xác không tệ .\nNhưng từ Thái tử , một cái người thừa kế góc nhìn đi xem .\nĐây là đem chính mình đặt ở chỗ nào ?\nHoàng đế trường sinh , cái kia còn cần Thái tử , cần người thừa kế sao ?\nNếu như một cái hoàng đế , thật có thể vĩnh viễn Thống Trị Vương Triều , người thừa kế kia còn có cái gì cần thiết tồn tại ?\n“ Chúng ta đi xem , trong lịch sử những cái kia muốn trường sinh hoàng đế , bọn hắn Thái tử , hoặc có lẽ là người thừa kế , có mấy cái có kết cục tốt đẹp ?”\n“ Từ chúng ta đời sau góc nhìn đi xem , những cái kia muốn trường sinh hoàng đế , bọn hắn có lẽ cũng tại bồi dưỡng Thái tử , bồi dưỡng người thừa kế .”\n“ Nhưng từ những cái kia Thái tử , những người thừa kế kia góc nhìn đi xem .”\n“ Mình còn có không cần thiết tồn tại , có thể cũng là những người này ý nghĩ đầu tiên !”\nNgụy Gia lúc này cười khổ một cái , hắn chính xác không nghĩ tới điểm này , nhưng từ Lương Phong nói tới đến xem , còn thật sự không có vấn đề gì .\nNếu như mình là một cái muốn trường sinh , cũng khao khát trường sinh hoàng đế Thái tử , hoặc có lẽ là người thừa kế .\nCái kia có thể hay không cho là chính mình là người thừa kế , một cái ngôi vị hoàng đế người thừa kế ?\nSẽ không !\nTrên đầu hoàng đế đều muốn trường sinh , chính mình còn thế nào có thể cho là mình là người thừa kế của hắn ?\n“ Cái này đúng thật là , nếu như mình là Phù Tô , có thể chính mình cũng chịu không được ...”\n“ Hơn nữa , xem chừng , chính mình cuối cùng ý nghĩ , cũng nhất định là ...”\n“ Một ngày này rốt cuộc đã đến ? Phụ thân của mình cầu đến trường sinh ? Hắn cũng không tiếp tục cần chính mình cái này một cái công cụ ?”\nLý Ân Phàm lắc đầu , nhẹ nhàng thở dài một cái .\nDưới đài Mông Điềm nhắm mắt lại , nội tâm thở dài một hơi .\n‘ Thật sự không trách được công tử ...’\nMông Điềm nội tâm có chút khó chịu , hắn trước đó vẫn đối với Phù Tô công tử là hận thiết bất thành cương .\nNhưng không có nghĩ đến , từ Phù Tô công tử góc nhìn đi xem , thì ra hắn đều bị chính mình bức bách đến một bước này .\nĐúng vậy , bị chính mình sở bức bách .\nNhưng từ đây hết thảy đến xem , đỡ Tô công tử , còn thật sự không có vấn đề gì .\n...\nTần triều .\nThủy Hoàng ba mươi năm .\nChương Đài cung .\n“ Cái này ...”\nTại chỗ rất nhiều đại thần , đều lặng lẽ nhìn xem phía trên Phù Tô .\nBọn hắn cũng thật sự là không nghĩ tới , Phù Tô sau cùng tự sát , thì ra là như thế ?\nNhưng từ Phù Tô góc nhìn đi xem , đây hết thảy có vấn đề sao ?\nRất nhiều đại thần tại nội tâm hỏi chính mình một câu như vậy , sau đó đều khe khẽ lắc đầu .\nCòn thật sự không có vấn đề gì .\nPhụ thân của mình muốn trường sinh , một mực cầm giữ triều chính , thống trị Tần triều .\nCái kia dưới cái nhìn của mình , mình không phải là một cái công cụ , thì là cái gì chứ ? Dù sao giống như màn trời nói tới ...\nTrường sinh hoàng đế , cần người thừa kế sao ?\nKhông cần !\nTất nhiên không cần , cái kia ý nghĩa tồn tại , thì là cái gì chứ ? Hoặc có lẽ là , không phải cân bằng triều chính công cụ , thì là cái gì chứ ?\nPhương diện này , chỉ có thể nói càng là người thông minh , liền muốn càng nhiều .\nMà Phù Tô ? Có lẽ cũng chính là người thông minh kia .\n......', 'output\\mp3\\Màn Trời Quyền Lực Diễn Biến Cùng Truyền Thừa\\0040_Thứ 40 chương Trường sinh hoàng đế.mp3', '2026-09-01T13:14:12.117196+00:00', 'completed', 'completed', 7443, 7443),
	(46, 7, '7646275332378460696', 41, 'Thứ 41 chương Nguyên lão', 'Thứ chương Nguyên lão\nHiện đại thời không .\n“ Cho nên ta trước đó vẫn cho rằng , Thái tử cái nghề nghiệp này , thật sự xem như trong lịch sử nguy hiểm nhất nghề nghiệp .”\nLý Ân Phàm cầm ống nói lên , rất là cảm khái nói .\n“ Quả thật là như thế , vừa biết chuyện , có thể liền muốn bước vào quyền lực trung tâm , tiếp đó cùng chung quanh đủ loại kẻ già đời chào hỏi .”\n“ Nếu như mình biểu hiện hảo , còn muốn đụng phải phụ thân của mình , cũng chính là hoàng đế xem kỹ , hoặc nghi kỵ .”\nTrần Xuyên Phú cũng là gật gật đầu , tán đồng Lý Ân Phàm nói lời .\n“ Cũng không thể nói là Thái tử a , phải nói là người thừa kế .”\n“ Từ xưa đến nay , cổ kim nội ngoại , người thừa kế cái này chức vị , cũng là vặn vẹo .”\n“ Hiện đại còn tốt rất nhiều , có thể phong xây thời kỳ cổ đại , vậy thật nhưng là quá muốn chết .”\n“ Nếu là gặp phải một cái muốn quyền lực bạo tăng hoàng đế , vậy thật chết tử tế cũng khó khăn .”\nLương Phong nghe được hai người nói lời , cười cười đón lấy bọn hắn .\n“ Đúng , ta có một cái vấn đề !”\nNghe nói như thế , Lý Ân Phàm cùng Lương Phong cùng với Trần Xuyên Phú 3 người , đều nhìn về Ngụy Gia .\n“ Phía trước nghe các ngươi nói , Mông Điềm Mông gia , Vương Tiễn Vương gia , cùng với những cái kia sau đi tới Tần quốc người cùng gia tộc .”\n“ Bọn hắn cũng không thể xưng là lão Tần người .”\n“ Đây là vì cái gì ?”\n“ Tại ta trong ấn tượng , bọn hắn hẳn là đều xem như lão Tần người a ?”\n“ Đặc biệt là Mông gia còn có Vương gia .”\nDưới đài Mông Điềm cũng có chút tò mò nhìn ba người khác , hắn cũng có chút nghi hoặc , vì cái gì mình không thể xem như lão Tần người ?\nMình cùng gia tộc của mình , hẳn là đối với Tần quốc làm ra rất lớn cống hiến a ?\n“ Còn nhớ rõ ta phía trước đã nói sao ? Trên đời này , rất nhiều chuyện , cũng là muốn nhìn lập trường .”\n“ Từ chúng ta đời sau góc độ đi xem , đem Mông gia , Vương gia , bọn hắn nhận làm lão Tần người , đây là không có vấn đề .”\n“ Bởi vì bọn hắn tại Tần quốc trải qua mấy đời sinh sôi , cũng vì Tần quốc làm ra rất nhiều cống hiến .”\n“ Theo lý mà nói , dạng này là không có vấn đề !”\n“ Nhưng , cái này cũng vẻn vẹn từ chúng ta đời sau góc nhìn đi xem .”\nTrần Xuyên Phú nói một phen như vậy , sau đó dừng một chút , trầm tư một hồi , xấp xếp lời nói một chút , lại tiếp tục nói :\n“ Dạng này tới nói a ! Ta làm một cái tỷ dụ .”\n“ Cấp trên của ngươi mở một công ty , tại mở công ty trong quá trình này , ngươi cùng cấp trên của ngươi , các ngươi trải qua mấy năm ra sức đánh liều , mỗi ngày thức đêm , mới khiến cho cái công ty này đưa ra thị trường .”\n“ Đưa ra thị trường sau đó , vì ban thưởng các ngươi những thứ này theo sau lưng nguyên lão , hắn đem cổ phần của công ty , phân một bộ phận lớn , cho các ngươi những thứ này đi theo phía sau hắn đánh liều người .”\n“ Mười mấy năm sau đó , công ty sắp không được , chủ tịch quyết định cải cách , dẫn vào người bên ngoài mới .”\n“ Nhưng người bên ngoài mới tới , muốn phân một chút cổ phần cho bọn hắn , chủ tịch liền quyết định , đem các ngươi những nguyên lão này cổ phần cầm một chút đi ra , phân cho người bên ngoài mới .”\n“ Sau đó , dẫn tới kẻ ngoại lai mới càng ngày càng nhiều , nguyên lão cổ phần càng ngày càng ít .”\n“ Cuối cùng mặc dù lũng đoạn ngành nghề , nhưng nguyên lão cổ phần , gần như bằng không .”\nNói đến đây , Trần Xuyên Phú nhìn chăm chú lên Ngụy Gia , nhẹ nói :\n“ Từ chúng ta đời sau góc nhìn đi xem , dạng này có phải hay không không có vấn đề gì ? Rất hợp lý ! Dù sao công ty lại không cải cách , đều phải trực tiếp sụp đổ .”\n“ Đến lúc đó hết thảy tất cả , toàn bộ đều là công dã tràng .”\n“ Lý trí tới nói , quả thật là như thế !”\n“ Nhưng nếu như , ngươi là công ty nguyên lão , ngươi có thể như vậy nghĩ sao ?”\nNgụy Gia nghe được cái này , kinh ngạc nhìn Trần Xuyên Phú .\n“ Các ngươi nguyên lão , sẽ tiếp nhận những người ngoại lai này mới sao ?”\n“ Các ngươi sẽ cho rằng , bọn hắn cùng các ngươi là giống nhau nguyên lão sao ?”\nNói đến đây , Trần Xuyên Phú nhún vai , rất là dứt khoát tiếp tục nói :\n“ Lý trí tới nói , hoặc có lẽ là , từ chúng ta bên cạnh giả góc độ đi xem , dạng này là rất hợp lý .”\n“ Nhưng khi ngươi là đương sự giả bản thân , nguyên lão này bản thân , ngươi còn có thể lý trí sao ?”\n“ Mặc dù chúng ta một mực đề xướng người đều phải lý trí , nhưng làm sự tình phát sinh đến trên người mình , có thể lý trí rất nhiều thiếu .”\n“ Tuyệt đại bộ phận , cũng là cảm tính !”\n“ Giống như ta mới vừa nói vấn đề kia , các ngươi là nguyên lão , các ngươi sẽ ra sao ?”\nNgụy Gia nội tâm thở dài một hơi .\nCòn có thể nghĩ như thế nào ? Ích lợi của mình bị xâm phạm , cổ phần của mình bị phân đi ra , dù thế nào nói với mình lý trí đều là phí công .\n“ Người góc nhìn , là từ lập trường quyết định !”\n“ Vừa rồi câu chuyện kia , từ chủ tịch góc nhìn đi xem , tự mình làm không có vấn đề , bởi vì công ty lại không cải cách , liền muốn sụp đổ .”\n“ Đến lúc đó hết thảy tất cả đều thành khoảng không !”\n“ Làm lại từ đầu ? Còn có thể hay không làm lại từ đầu đều khó mà nói .”\n“ Nhưng từ nguyên lão góc nhìn đi xem , mặc dù công ty là muốn sụp đổ , nhưng vì cái gì xâm phạm ích lợi của ta ?”\n“ Ta chẳng lẽ trước kia cùng ngươi cùng một chỗ đánh liều , là giả sao ?”\n“ Dựa vào cái gì mấy người này mới tới công ty , liền muốn phân cho bọn hắn cổ phần ?”\n“ Chẳng lẽ không phải là cái này một số người , tới trước hiếu kính chúng ta nguyên lão ? Bọn hắn dựa vào cái gì không cung kính đối với chúng ta nguyên lão ?”\n“ Dựa vào cái gì ích lợi của chúng ta chịu lấy tổn hại ?”\n“ Tiếp nhận bọn hắn ? Bọn hắn là tới xâm phạm chúng ta nguyên lão lợi ích , chúng ta dựa vào cái gì tiếp nhận bọn hắn ?”\n“ Ý của ngươi là , bọn hắn xâm phạm chúng ta nguyên lão lợi ích , chúng ta nguyên lão còn muốn liếm láp khuôn mặt đi cung kính bọn hắn ?”\nTrần Xuyên Phú càng nói càng nhiều , càng nói , tại chỗ rất nhiều người đều càng trầm mặc .\nĐặc biệt là dưới đài Mông Điềm , hắn rốt cuộc biết gia tộc mình vì cái gì tại Tần quốc có đôi khi không hiểu thấu sẽ phải chịu một chút bó cánh tay .\n“ Ngoại lai , thủy chung là ngoại lai .”\n“ Khi ngươi xuất hiện một khắc này , liền nhất định sẽ chịu đến bản thổ thế lực căm thù !”\n“ Cái này không quan hệ cái gì tình cảm hoặc khác , đây đều là lập trường còn có lợi ích liền đã quyết định .”\n“ Mãi mãi cũng không cách nào thay đổi ! Vĩnh viễn cũng không cải biến được !”\n“ Lý trí cũng cuối cùng chỉ là lý trí , đây là một cái thế giới thực tế .”\nSau đó , Trần Xuyên Phú tổng kết một chút .\n“ Cho nên , ngươi muốn nói từ chúng ta đời sau góc nhìn đi xem , Mông gia , Vương gia , bọn hắn quả thật tính là bên trên lão Tần người .”\n“ Dù sao chúng ta hậu thế cũng là từ băng lãnh văn tự phía trên đi lý trí tự hỏi .”\n“ Có thể đổi một cái góc nhìn , những cái kia chân chính lão Tần người sang tộc góc nhìn đi xem , Mông gia cùng Vương gia , những cái kia về sau mới đi đến Tần quốc gia tộc , bọn hắn dựa vào cái gì được xưng là lão Tần người ?”\n“ Cũng bởi vì bọn hắn đối với Tần quốc làm một chút cống hiến ?”\n“ Cái này Tần quốc vẫn là chúng ta lão Tần người sang tộc đánh xuống đâu !”\n“ Không có chúng ta , bọn hắn có thể tới Tần quốc ?”\n“ Không có chúng ta lão Tần người đánh rớt xuống thổ địa , bọn hắn có thể làm ra cống hiến ?”\nTrần Xuyên Phú hai tay mở ra , nhún vai , rất bất đắc dĩ nói :\n“ Đây tuyệt đối là lúc đó những cái kia lão Tần người ý nghĩ .”\n“ Ngươi có lẽ cảm thấy ý nghĩ như vậy quá hoang đường ! Vì sao lại có ý nghĩ như vậy ?”\n“ Đó là ngươi không phải người trong cuộc !”\n“ Giống như ta vừa rồi làm ví dụ , nếu như ngươi là nguyên lão , ngươi còn có thể cảm thấy ý nghĩ như vậy hoang đường sao ?!”\n...', 'output\\mp3\\Màn Trời Quyền Lực Diễn Biến Cùng Truyền Thừa\\0041_Thứ 41 chương Nguyên lão.mp3', '2026-09-01T13:41:35.508866+00:00', 'completed', 'completed', 7484, 7484),
	(47, 7, '7646275563195204120', 42, 'Thứ 42 chương Thường xuyên nhắc nhở', 'Thứ chương Thường xuyên nhắc nhở\nHiện đại thời không .\nNgụy Gia rất muốn nói , ý nghĩ như vậy vẫn là rất hoang đường .\nLý trí là nói cho hắn biết như vậy .\nNhưng khi hắn chân chính đứng tại “ Nguyên lão ” Cái này một vị trí đi lên suy tính thời điểm , hắn cảm tính , nội tâm tình cảm , lại nói cho nàng , ý nghĩ như vậy rất bình thường .\nDù sao cũng là người , đều có lập trường của mình , còn có ích lợi của mình .\n“ Ai ...”\nLý Ân Phàm lúc này bỗng nhiên thở dài một hơi , cầm ống nói lên , nhìn xem Ngụy Gia nói :\n“ Lúc này , ngươi hẳn là hiểu rõ , vì cái gì khai quốc hoàng đế , muốn thanh tẩy khai quốc công thần đi ?”\nLời này vừa ra , Ngụy Gia lập tức sững sờ tại chỗ .\nBên cạnh Trần Xuyên Phú , nhưng là yên lặng gật gật đầu , không nói gì .\nLương Phong cũng đồng dạng là như thế .\n“ Chính là bởi vì thấy được điểm này , cho nên những cái kia khai quốc hoàng đế , đều phải thống hạ sát thủ .”\n“ Từ cảm tính góc độ đi xem , dạng này hoàng đế có lẽ rất tàn nhẫn .”\n“ Nhưng hoàng đế , bọn hắn chỗ đứng ở góc độ , thời khắc nhắc nhở bọn hắn , rất nhiều chuyện , không thể từ cảm tính một góc đi đối đãi .”\n“ Dù là đời thứ nhất , những cái kia khai quốc công thần đều tốt , nhưng ngươi có thể bảo chứng , con cháu của bọn họ , cũng là như thế sao ?”\n“ Cho nên , rất nhiều hoàng đế , cũng là ép chính mình , chỉ có thể từ lý trí góc độ đi suy xét .”\n“ Vương triều sống còn ? Vẫn là tình huynh đệ ? Chiến hữu tình ?”\n“ Ngươi chọn cái nào ?”\nLý Ân Phàm mà nói rất nhiều ngay thẳng , ngay thẳng đến để cho Ngụy Gia không lời nào để nói .\n“ Xuân Thu Chiến Quốc , thời kỳ này , cho hậu thế lưu lại không cách nào tưởng tượng tài phú .”\n“ Mà Tần quốc lịch sử , cùng với hạ tràng , cũng thường xuyên nhắc nhở lấy về sau hoàng đế ...”\n“ Mềm lòng ? Tần triều hạ tràng rõ mồn một trước mắt !”\nLúc này , Trần Xuyên Phú nhận lấy chủ đề , cầm microphone nhẹ nói :\n“ Cái này kỳ thực đều coi là tốt .”\nNgụy Gia nghe vậy sững sờ , nhẹ nói :\n“ Cái này đều xem như tốt ?”\n“ Đương nhiên là coi là tốt , dù sao cái này còn mỹ hóa rất nhiều .”\n“ Mặc dù nói đây chỉ là một phương diện , nhưng càng nhiều hoàng đế thanh tẩy công thần , nghĩ là bọn hắn có thể hay không cướp thắng lợi trái cây ?”\n“ Trên dưới tất cả mọi người cùng một chỗ đánh liều vương triều , có thể hay không mấy chục năm sau liền đổi họ ?”\n“ Xuân Thu Chiến Quốc thời kỳ ba nhà phân tấn , cũng đều là rõ mồn một trước mắt .”\nNói đến đây , Trần Xuyên Phú thở dài một hơi , chậm rãi nói :\n“ Ngươi muốn làm hảo một cái người dẫn đầu , làm tốt một cái hoàng đế , hoặc có lẽ là , làm tốt một cái thượng vị giả .”\n“ Cái kia có một số chuyện , là ngươi nhất định phải làm ! Không có cách nào lưu cho đời tiếp theo .”\n“ Giống như là Tần quốc , mặc dù là có thời đại nhân tố , phía trước mấy đời người , đều không nhìn thấy về sau chuyện phát sinh .”\n“ Nhưng về sau , mỗi một đời đi lên người , đều phải thỏa hiệp một chút thế lực , lại là sự thật .”\n“ Một cái chân chính hợp cách , ưu tú thượng vị giả , lý trí , nhất định muốn là lớn hơn cảm tính ...”\nLời này vừa ra , Lý Ân Phàm bọn người đều là gật đầu một cái .\n“ Nhưng trong lịch sử , không phải là có rất nhiều không có giết khai quốc công thần khai quốc hoàng đế sao ?”\nNgụy Gia nhìn xem Trần Xuyên Phú , đưa ra nghi vấn .\n“ Hoàng đế nào ? Tần Thuỷ Hoàng Doanh Chính ? Vương Tiễn đó là tuyệt đỉnh người thông minh !”\n“ Vương Tiễn cái này thống nhất Lục quốc lớn nhất công thần , chính mình cũng đi xuống , những người khác , còn có ai có thể cùng Vương Tiễn so công lao ?”\n“ Hán Quang Võ Đế Lưu Tú Đối với vân đài nhị thập bát tướng hậu đãi , thực hành “ Lui công thần tiến văn lại ”, để cho bọn hắn an hưởng tuổi già ?”\n“ Lui công thần tiến văn lại ...”\nTrần Xuyên Phú nói đến đây , nở nụ cười , sau đó tiếp tục nói :\n“ Để cho chỉ am hiểu chém giết võ tướng làm quan văn ? Đây chính là chỉ bảo đảm ngươi một hai đời vinh hoa phú quý .”\n“ Hơn nữa , Hán Quang Võ Đế hắn là thế nào lập nghiệp ? Hắn căn cơ là ai ?”\n“ Điểm này chúng ta sau này sẽ giảng .”\n“ Vẫn là nói Đường Thái Tông Lý Thế Dân ?”\n“ Hiện đại rất nhiều người nói Đường Thái Tông Lý Thế Dân không có đồ sát công thần .”\n“ Đúng là không có đồ sát , nhưng ngươi cẩn thận xem Đường triều sách sử , tại Trinh Quán 23 năm , Lý Thế Dân chết một năm này .”\n“ Khai quốc công thần , liền chỉ nói Lăng Yên các hai mươi bốn công thần , có mấy cái còn tại ? Gia tộc của bọn hắn còn tại ?”\n“ Đồ sát là không có tàn sát , đây đúng là sự thật , dù sao nếu như chỉ nhìn đồ sát phương diện này , cái kia rất nhiều hoàng đế , cũng là không có đồ sát .”\n“ Huống hồ , Lý Thế Dân là khai quốc hoàng đế sao ?”\n“ Lý Thế Dân thượng vị kinh nghiệm , không phải là nói rõ một số việc sao ?”\nSau đó , Trần Xuyên Phú lại tiếp tục nói :\n“ Hoặc ngươi biết nói Triệu Khuông Dận ?”\n“ Ngũ Đại Thập Quốc đó là cái gì thời đại ? Triệu Khuông Dận đồ sát võ tướng ? Đồ sát võ tướng có cái rắm dùng .”\n“ Lúc đó phần lớn quyền hạn , căn bản liền không tại võ tướng trên tay , ngươi giết võ tướng có ích lợi gì ?”\nCuối cùng , Trần Xuyên Phú còn nói ra một cái tên người :\n“ Cái kia Chu Lệ đâu ? Chu Lệ hẳn là tính được là , không phải khai quốc hoàng đế khai quốc hoàng đế .”\n“ Chu Lệ cũng không có đồ sát võ tướng , nhưng Chu Lệ vì cái gì đánh trận cũng là đích thân bên trên ?”\nNói đến đây thời điểm , Trần Xuyên Phú rất là thần bí nở nụ cười .\nBên cạnh Lý Ân Phàm cũng cười một tiếng .\n“ Vĩnh Lạc hướng tình huống là rất phức tạp .”\n“ Có thể nói , trong lịch sử tất cả Đại Nhất Thống Vương Triều bên trong , liền không có so Vĩnh Lạc hướng phức tạp hơn tình huống !”\n“ Chu Lệ đó là thật muốn tự mình lên sao ? Đó là bất đắc dĩ , nhất thiết phải tự thân lên !”\n“ Nếu như không tự thân lên ? Vậy hắn cũng không cần muốn đánh nhau !”\n“ Chỉ cần muốn đánh nhau , nghĩ phát động chiến tranh , Chu Lệ nhất định phải tự thân lên .”\n“ Điểm này , đằng sau giảng đến lúc Minh triều , chúng ta cũng biết nói .”\nCuối cùng nói xong , Trần Xuyên Phú nhìn xem Ngụy Gia , nhẹ nói :\n“ Đương nhiên , vẫn là chúng ta vừa rồi lời nói kia , ngươi muốn nói , chân chính đồ sát võ tướng , đồ sát khai quốc công thần ?”\n“ Cái kia chính xác rất nhiều khai quốc hoàng đế đều không có đồ sát .”\n“ Có thể đồ sát là đồ sát , chủ động để cho bọn hắn tiêu thất cũng không phải là “ Đồ sát ”?”\n“ Vì cái gì nói chuyện đến đồ sát khai quốc công thần , ngươi liền đơn thuần chỉ là nghĩ đến giết đâu ?”\nTrần Xuyên Phú một mực rất hiếu kì , hiện đại rất nhiều người , vì cái gì nói chuyện đến khai quốc hoàng đế đồ sát khai quốc công thần .\nLiền thật chỉ là đơn thuần nghĩ tới giết đâu ?\nThủ đoạn khác , không coi là là “ Đồ sát ” Sao ?\n“ Trong này , chân chính lợi hại chính trị cao thủ , thì sẽ không lưu lại cho mình một chút ô danh .”\n“ Giống như là Lý Thế Dân , hắn là không có chân chính làm ra đồ sát võ tướng , nhưng hắn thủ đoạn mới thật sự là lợi hại .”\n“ Ngươi nhìn hắn cuối cùng lưu lại những cái kia khai quốc công thần .”\n“ Bọn hắn tuyệt đại bộ phận , đều có một điểm giống nhau .”\n“ Cái gì điểm giống nhau ? Đó chính là tuyệt không có khả năng leo lên hoàng vị !”\n“ Tỉ như nói ngoại thích , tỉ như nói cùng thế gia đám hỏi ...”\n“ Lại tỉ như , trong tông thất cũng không được hoan nghênh người , an phận người , tuyệt không kết bè kết cánh người ...”\nNói xong lời cuối cùng , Lương Phong cùng Lý Ân Phàm trong đầu , lập tức xuất hiện một cái tên người .\nNhưng người này sao ? Cũng bị về sau Đường Cao Tông Lý Trị trả thù tính chất rửa sạch .\nHạ tràng cũng không tốt .\n...', 'output\\mp3\\Màn Trời Quyền Lực Diễn Biến Cùng Truyền Thừa\\0042_Thứ 42 chương Thường xuyên nhắc nhở.mp3', '2026-09-01T13:41:40.477556+00:00', 'completed', 'completed', 7376, 7376),
	(48, 7, '7646617961563243032', 43, 'Thứ 43 chương Có một số việc, không thể không đi làm', 'Thứ chương Có một số việc , không thể không đi làm\nĐại hán .\nHán bảy năm .\n“ Ai ...”\nNhìn bầu trời màn nhìn đến đây , Lưu Bang nhẹ giọng thở dài một hơi .\nThật sự cho rằng hắn nghĩ đồ sát công thần sao ? Là chạy tới ở đây , nhất thiết phải như thế đi làm .\nXuân Thu Chiến Quốc lịch sử , Tần quốc lịch sử , thậm chí là Tần triều lịch sử , để ở nơi đó .\nLưu Bang không thể không đi làm !\nKhông làm ? Tần triều hạ tràng ngay tại không xa !\nHơn nữa , còn nhất định phải là hắn cái này khai quốc hoàng đế làm mới được !\nĐổi đời tiếp theo hoàng đế ? Cái kia có một số chuyện chỉ có thể để nó mọc rễ nảy mầm , cuối cùng tạo thành vương triều sụp đổ .\n“ Chính là ông có một số việc chỉ sợ không làm được , chỉ có thể cho ngươi đi làm .”\nLưu Bang nhìn xem màn trời , không quay đầu lại , nhẹ nói .\nBên cạnh bỗng nhiên đi ra một hồi rất bình tĩnh giọng nữ .\n“ Sau cùng có một số việc , liền giao cho ta a , ngươi làm đã đủ nhiều .”\n“ Thiên hạ này là ngươi đánh xuống , ta lại trợ giúp con của chúng ta ổn định tốt .”\nLưu Bang không quay đầu lại , chỉ là khẽ gật đầu một cái .\n...\nĐại hán .\nNguyên thú 4 năm .\nLưu Triệt nghe màn trời giảng đến khai quốc hoàng đế đồ sát công thần thời điểm , bỗng nhiên bình tĩnh lại .\nBởi vì có một số việc , hắn bỗng nhiên nghĩ hiểu rồi .\nGiống như màn trời nói , chân chính lý trí hoàng đế , nghĩ có sự khác biệt hoàng đế , bọn hắn cũng sẽ không đem mắt sáng liền có thể nhìn thấy tai hoạ ngầm , lưu cho đời tiếp theo hoàng đế .\nRất nhiều chuyện , là chạy tới một bước kia , không thể không thống hạ sát thủ một bước kia .\nHỗn loạn thời điểm , có ít người đúng là công thần , nhưng chờ đến lâu dài hòa bình , có ít người , ngược lại lại trở thành trở ngại lớn nhất .\nHoàng đế suy tính là cả vương triều .\nDù sao có ít người , hắn còn sống thời điểm , đúng là có thể bảo đảm gia tộc của hắn một mực là trung thành .\nNhưng khi hắn chết đâu ? Ai có thể cam đoan , gia tộc của hắn , đời tiếp theo , hạ hạ vừa đảm nhiệm người dẫn đầu , đối với vương triều một mực là trung thành ?\nDù ai cũng không cách nào cam đoan !\nNhưng rất nhiều lịch sử , liền bày tại phía trước !\nTỉ như nói : Ba nhà phân tấn .\nĐây là mỗi một cái hoàng đế , đều nhất định muốn học tập bài học !\nLưu Triệt học qua sao ? Đương nhiên là học qua ! Mà hắn học tập , còn không hết là ba nhà phân tấn .\nXuân Thu Chiến Quốc , Tần triều lịch sử , hắn đều là học qua !\nThế nhưng chính là bởi vì học qua , hắn mới rõ ràng .\nRất nhiều chuyện , thật sự sẽ không bị ý chí của cá nhân thay đổi vị trí , khi đến một cái giai đoạn nào , tất cả hình thức , đều ép ngươi không thể không đi làm .\nGiống như là , ba nhà phân tấn .\nLịch sử có lẽ thần kỳ liền thần kỳ ở đây a , nó lúc nào cũng lập đi lập lại một số việc .\nĐối với mấy cái này hoàng đế tới nói , lịch sử thật là một cái lão sư rất tốt , vô số lần dạy bảo ngươi , lặp lại một lần lại một lần .\nThế nhưng chính vì vậy , Lưu Triệt vô cùng rõ ràng , chính mình có một số việc , cuối cùng sẽ đi làm .\n“ Ai ...”\nGiờ khắc này , Lưu Triệt cảm nhận được trước nay chưa có một loại cô độc .\nNhưng sau đó , hắn lại lập tức chấn tác tinh thần , bình tĩnh nhìn màn trời .\nLiếc mắt nhìn Vệ Thanh , Lưu Triệt có chút hoảng hốt , nội tâm thời khắc này , bỗng nhiên không biết suy nghĩ cái gì .\n...\nĐông Hán .\nKiến An 8 năm .\n“ Tư Không ...”\n“ Phụng Hiếu , ngươi đã đến .”\nTào Thao nhìn xem đi đến bên cạnh mình Quách Gia , khẽ gật đầu một cái .\n“ Phụng Hiếu ...”\nNhìn xem màn trời , Tào Thao không có quay đầu , Quách Gia chỉ là cảm giác thanh âm này vô cùng nhẹ .\n“ Ngươi nói , có ít người , bọn hắn có thể cùng chúng ta đi đến cuối cùng sao ?”\nQuách Gia biết Tào Thao nói tới ai , không có trả lời , chỉ là chỉ giữ trầm mặc .\n“ Bọn hắn cũng hẳn là rõ ràng a ? nhưng cuối cùng vẫn là sẽ hy vọng , ta sẽ không như thế đi làm .”\nQuách Gia vẫn là không có nói chuyện , chỉ là an tĩnh nhìn xem màn trời .\n“ Phụng Hiếu , ta bỗng nhiên có một nghi vấn .”\nTào Thao lúc này , quay đầu nhìn Quách Gia , tức thời lộ ra nghi ngờ trên mặt .\n“ Tư Không mời nói .”\n“ Bọn hắn nếu đã như thế muốn đạt được một vài thứ , vì cái gì không đi đến phía trước tới đâu ?”\nTào Thao nói có một chút mê hoặc , nhưng Quách Gia nghe vẫn là đã hiểu .\nTrầm mặc suy tư một hồi sau , Quách Gia nhẹ nói :\n“ Bởi vì đứng lên trên , nghĩ xuống , cũng không phải là dễ dàng như vậy .”\n“ Lịch sử lặp lại một lần lại một lần , khi một người đứng tại một cái chỗ cao , bắt mắt nhất chỗ , cái kia làm hắn nghĩ xuống , cũng chỉ có rơi xuống .”\n“ Rơi xuống thời điểm , không chỉ là hắn , sau lưng toàn cả gia tộc , cũng biết theo cùng một chỗ toàn bộ té ngã .”\nTào Thao nghe vậy khẽ giật mình , sau đó lấy lại tinh thần , gật gật đầu , nhẹ nói :\n“ Thì ra là thế , xem ra có một số việc , vẫn là không sánh được các ngươi thế gia giải ...”\nQuách Gia không nói gì , bình tĩnh quay đầu một lần nữa nhìn về phía màn trời .\n...\nĐại Đường .\nTrinh Quán bảy năm .\nCam lộ trước điện bầu không khí một trận trầm mặc , ai cũng không nói gì , đều là an tĩnh nhìn xem màn trời .\nLý Thế Dân cũng vô cùng bình tĩnh nhìn xem màn trời .\nVừa rồi màn trời lời nói , tựa như cũng không có phát sinh , tất cả mọi người ở đây , toàn bộ đều cố ý bỏ quên đi .\nNhưng ở tràng rất nhiều đại thần trong nội tâm , đều đang cầu khẩn , gia tộc của mình nhất định sẽ chịu nổi .\nPhía trên Lý Thế Dân nhìn xem một màn này , nội tâm thở dài một hơi .\nLý Thế Dân nội tâm , kỳ thực là rất không muốn làm một số việc , có thể chính như màn trời nói tới , có một số việc , hắn không làm , về sau hoàng đế cuối cùng vẫn là sẽ làm .\nNhưng đợi đến lúc kia , đối với vương triều tổn thương lớn bao nhiêu ? Ai cũng không biết .\nNhưng lịch sử liền bày tại nơi đó !\nRất nhiều chuyện , lịch sử đều tại một lần một lần lặp lại trước mặt của ngươi .\nDù là ngươi nghĩ giả vờ làm như không thấy , nhưng trong lòng lại luôn sẽ nghĩ đến .\nNghĩ đi nghĩ lại , liền tinh tường , sự tình phát triển , quả nhiên như lịch sử một dạng , lặp lại tại trước mặt của ngươi .\nCó đôi khi , đối với hoàng đế tới nói , đặc biệt là nghĩ có sự khác biệt hoàng đế .\nNội tâm của bọn hắn có đôi khi cũng là tràn đầy bất đắc dĩ , vì vương triều , vì vương triều sống còn , bọn hắn đều phải phải làm .\nChỉ là Lý Thế Dân làm vô cùng mịt mờ .\nTại Trinh Quán bảy năm , cái này một cái thời gian điểm , có một số việc , hắn cũng đã bắt đầu làm .\n...\nTống triều .\nMở bảo sáu năm .\n“ Ta ngược lại thật ra nghĩ đồ sát võ tướng , tiếp đó mọi chuyện cần thiết liền có thể một chút giải quyết .”\nMàn trời nghe đến đó , Triệu Khuông Dận cũng là rất bất đắc dĩ .\nHắn thật sự nghĩ , một chút đem những cái kia võ tướng thu thập , mọi chuyện cần thiết toàn bộ một chút giải quyết .\nNhưng trước mặt thời đại lưu lại đồ vật , để cho hắn hiểu được , không có nhẹ nhàng như vậy chuyện !\nCó một số việc , ngươi chỉ có thể như thế đi làm !\nĐồ sát võ tướng ? Với hắn mà nói , thật sự không có tác dụng gì !\nĐừng nói bây giờ không còn tác dụng gì nữa , phía trước một trăm năm , giết võ tướng , đối với rất nhiều thế lực tới nói , đều không gì dùng !\nThân ở thời đại này , Triệu Khuông Dận thật sự bất đắc dĩ !\nTrong lịch sử rất nhiều chuyện , hoàn toàn không một chút giá trị tham khảo , chỉ có thể từng lần từng lần một chính mình thận trọng đi tìm tòi .\n...\nMinh triều .\nHồng Vũ mười năm .\n“ Vĩnh Lạc hướng phức tạp tình huống , so trong lịch sử bất kỳ một cái nào Đại Nhất Thống Vương Triều đều phải phức tạp ?”\n“ Không phải khai quốc hoàng đế khai quốc hoàng đế ?”\nChu Nguyên Chương quay đầu liếc mắt nhìn trong lòng run sợ tiểu Chu Lệ .\n“ Xem ra ta biết là chuyện gì xảy ra .”\nNói đến đây , Chu Nguyên Chương chậm rãi gật đầu một cái , hắn đã biết Vĩnh Lạc hướng đến cùng gặp phải cái gì tình huống .\nDạng này tới nói , Chu Lệ xem như thời điểm đó hoàng đế , muốn đánh nhau , chính xác chỉ có thể là tự thân lên .\n“ Có thể tại dưới cái tình huống này Bả Vương Triều truyền thừa xuống , Tứ đệ thật đúng là lợi hại ...”\nBên cạnh Chu Tiêu cũng biết màn trời nói tới là có ý gì .\nDù sao rất nhiều chuyện , cái này ba câu nói liền đã nói hiểu rồi .\n“ Tiêu nhi , cứ như vậy tình huống , ngươi thật sự cảm thấy có thể thật tốt truyền thừa xuống ?”\nChu Nguyên Chương phủi một mắt tiểu Chu Lệ , sau đó bình tĩnh đối với Chu Tiêu nói .\n“ Phụ thân ? Ngươi nói là ?”\nChu Tiêu khẽ giật mình , sau đó vội vàng hỏi đạo .\n“ Nhìn bầu trời màn a , màn trời tất nhiên nói đến chỗ này , đằng sau nhất định sẽ nói rõ .”\n“ Ta mặc dù có thể suy đoán ra một ít chuyện , nhưng vẫn là không có người đời sau hiểu rõ tinh tường .”\n......', 'output\\mp3\\Màn Trời Quyền Lực Diễn Biến Cùng Truyền Thừa\\0043_Thứ 43 chương Có một số việc, không thể không đi làm.mp3', '2026-09-01T13:41:45.860142+00:00', 'completed', 'completed', 8410, 8410),
	(49, 7, '7646618108471296536', 44, 'Thứ 44 chương Mưu đồ gì?', 'Thứ chương Mưu đồ gì ?\nHiện đại thời không .\n“ Nói đến đây , kỳ thực ta ngược lại thật ra có một cái vấn đề .”\nLương Phong lúc này mở miệng nói chuyện , chuẩn bị hỏi ra hôm nay chính mình vấn đề thứ nhất .\nBên cạnh Lý Ân Phàm 3 người , giữ vững tinh thần , tập trung lực chú ý , nhìn xem hắn .\n“ Vì cái gì Tần Quốc Sở hệ thế lực sẽ phản loạn ? Bọn hắn mưu đồ gì ?”\n“ Trong mắt của ta , nếu như Sở Hệ không phản loạn , thật tốt cứ như vậy chờ tại Tần quốc , chờ Tần triều thống nhất sau đó , Sở Hệ hậu cung thế lực đồng dạng mở rộng , hẳn là so với bọn hắn tại Tần quốc thời kỳ quyền thế còn lớn hơn a ?”\n“ Nhưng vì cái gì Sở Hệ thế lực , sẽ ở tối hậu quan đầu , phản loạn đâu ?”\n“ Muốn nói bọn hắn thấy không rõ lắm hình thức , ta là không tin .”\n“ Nhưng ta dù là thay vào đến ngay lúc đó Sở Hệ thế lực góc nhìn đi xem , cũng không hiểu rõ chuyện này rốt cuộc là như thế nào ?”\nLương Phong nói liên tiếp , nghe bên cạnh Ngụy Gia cũng trực điểm đầu .\nHắn cũng quả thật có chút không hiểu rõ vì cái gì Sở Hệ thế lực sẽ phản loạn .\nLý Ân Phàm liếc mắt nhìn Trần Xuyên Phú , ánh mắt hỏi thăm , là hắn tới , vẫn là mình tới ?\nTrần Xuyên Phú đưa tay ra hiệu , để cho Lý Ân Phàm tới là được .\n“ Vấn đề này vẫn là ta tới nói a .”\nCầm ống nói lên , Lý Ân Phàm ngữ khí rất chậm chạp , nhưng âm thanh lại vô cùng rõ ràng .\n“ Hiện đại rất nhiều người hiểu được Tần quốc tiến đánh Sở quốc thời điểm , Sở Hệ thế lực phản loạn , sẽ lập tức cảm thấy chuyện đương nhiên .”\n“ Vì cái gì đây ? Bởi vì Sở Hệ , cái này “ Sở ” Chữ .”\n“ Đại đa số người , đều nghe cái này , liền lập tức cảm thấy chuyện đương nhiên .”\n“ Đây đúng là không có vấn đề gì , nhưng cái này kỳ thực chỉ là trong đó rất nhỏ một cái nguyên nhân .”\n“ Hơn nữa , không có đem Tần Quốc Sở hệ thế lực , đến cùng vì cái gì phản loạn , cái này sau lưng lôgic nói ra .”\nNói đến đây , Lý Ân Phàm đứng lên , ra hiệu nhân viên công tác đem phía sau đài bảng đen mang lên .\nChờ nhân viên công tác đem bảng đen mang lên sau đó , Lý Ân Phàm cầm lấy để ở một bên phấn viết , mới dùng tiếp tục nói :\n“ Cái này sau lưng lôgic , nói phức tạp có thể cũng tương đối phức tạp , nhưng nói đơn giản , kỳ thực cũng rất đơn giản .”\n“ Đang nói đến cái này sau lưng cụ thể lôgic phía trước , chúng ta muốn trước hiểu rõ một vật .”\n“ Vật này là cái gì ?”\nLý Ân Phàm cầm lấy phấn viết , quay người , tại trên bảng đen viết lên bốn chữ :\nThông gia , hòa thân .\nBên cạnh Lương Phong còn có Ngụy Gia hai người , nhìn thấy bốn chữ này , vẻ mặt nghi hoặc .\nKhông rõ Lý Ân Phàm vì sao lại viết bốn chữ này ?\nTrần Xuyên Phú lại là gật gật đầu , tinh tường Lý Ân Phàm biết cái này sau lưng lôgic quan hệ .\n“ Thông gia , hòa thân , cái này tại người hiện đại xem ra , hẳn là không hề quan hệ hai cái từ .”\n“ Muốn nói có quan hệ ? Có thể tại người hiện đại xem ra , chỉ có đem nữ nhân gả ra cái này một cái quan hệ .”\n“ Nhưng rất đáng tiếc , tại cổ đại , hai cái này từ sau lưng lôgic quan hệ là giống nhau !”\nNói đến đây , Lý Ân Phàm dừng lại một chút , sau đó nói :\n“ Có thể có người sẽ nhớ , vì cái gì hai cái này từ sau lưng lôgic quan hệ là giống nhau ?”\n“ Hòa thân , hẳn là khuất nhục a ? Vì cái gì “ Hòa thân ” Sẽ cùng “ Thông gia ” Sau lưng lôgic quan hệ là giống nhau ?”\n“ Đúng hay không ?”\nLý Ân Phàm nói đến đây một câu nói thời điểm , nhìn về phía Ngụy Gia .\nSau đó chỉ thấy Ngụy Gia không tự chủ gật đầu một cái .\nHắn thấy , hòa thân lại là khuất nhục , vì sao lại cùng thông gia là giống nhau ?\n“ Không việc gì , cái này kỳ thực chỉ cần là hiện đại người bình thường , cũng sẽ như vậy cảm thấy .”\nNói đến đây , Lý Ân Phàm gật đầu một cái , sau đó lại tại “ Thông gia ” Hai chữ này phía dưới , vẽ hai đầu đường dọc , đường dọc cuối cùng , viết lên gia tộc .\n“ Nhưng chúng ta tới trước nhìn , thông gia là chuyện gì xảy ra .”\n“ Thông gia , là gia tộc cùng gia tộc , cả hai bổ sung , hay là cường cường liên hợp .”\n“ Một phương gia tộc đem nữ nhi của mình , hay là trong gia tộc một nữ tử gả đi , sau đó thì sao ? Nhờ vào đó thu được đối phương ủng hộ của gia tộc .”\n“ Nhưng lúc này , có một cái vấn đề !”\n“ Dựa vào cái gì đối phương nữ tử gả tới , chúng ta liền muốn ủng hộ gia tộc bọn họ ?”\nNói đến đây , Lý Ân Phàm lại tại bảng đen bên cạnh chỗ hổng , viết mấy cái từ .\nTriều đình quyền hạn : Quyền lực của hoàng đế Hậu cung thế lực Bản thổ thế lực Ngoại lai thế lực .\n“ Đây là lúc đó Tần quốc triều đình quyền lực cụ thể phân bố .”\nLý Ân Phàm đùng phấn viết điểm một chút bảng đen , lại nhẹ nói :\n“ Nói đến đây , có thể có người sẽ nhớ , cái này cùng thông gia có quan hệ gì ?”\n“ Lý lão sư , ngươi cái này nói chuyện nhảy thế nào chuyển nhanh như vậy ? Vốn là nói là thông gia , vì cái gì lập tức còn nói đến Tần quốc triều đình quyền hạn ?”\nLúc này , Lương Phong lập tức vụt đứng lên .\nBởi vì hắn nghe hiểu rồi , thế nhưng chính là hiểu rồi , hắn mới phát giác được có chút không thể tưởng tượng nổi .\n“ Thì ra là như thế ?!”\nLý Ân Phàm nhìn xem Lương Phong chậm rãi gật đầu , nhẹ nói :\n“ Đúng là như ngươi nghĩ .”\nSau đó , Lý Ân Phàm gặp Ngụy Gia vẫn là gương mặt mê mang , liền tiếp tục nói :\n“ Từ mặt ngoài nhìn , thông gia cùng Tần quốc triều đình quyền hạn , có lẽ cũng không có quan hệ thế nào !”\n“ Nhưng bên trong nội hạch đâu ?”\n“ Đương nhiên là có quan hệ , vì cái gì ? khi một cái gia tộc , đem chính mình nữ tử gả đi thời điểm , nàng kỳ thực liền lập tức thu được gia tộc này quyền hạn .”\n“ Cái gì quyền hạn ?”\nLý Ân Phàm đang viết Tần quốc triều đình quyền hạn phân bố đồ bên trên , hậu cung thế lực phía dưới , trọng trọng vẽ hai đầu lằn ngang .\n“ Thấy rõ ràng chưa ? Chính là quyền lực này !”\nNgụy Gia tựa hồ có một chút hiểu rồi , biết rõ Lý Ân Phàm tại sao muốn nói “ Thông gia ” Cùng “ Hòa thân ” Sau lưng lôgic kỳ thực là một dạng .\n“ Sở Hệ nữ tử đến Tần quốc , nàng lập tức liền thu được hậu cung quyền hạn .”\n“ Sau đó đâu ? Nàng liền có thể dùng hậu cung quyền hạn , đi từ từ tiếp xúc triều đình quyền hạn .”\n“ Chờ lớn mạnh sau đó ? Liền sẽ tạo thành Tần quốc đằng sau hai vị quân chủ ngay lúc đó quyền hạn phân bố .”\n“ Sở hệ thế lực trở thành lúc đó Tần quốc thế lực lớn nhất .”\nNói đến đây , Lý Ân Phàm nhìn xem Ngụy Gia , nhẹ nói :\n“ Mà gia tộc đâu ? Gia tộc cũng giống như nhau !”\n“ Khi nữ tử này thu được gia tộc lớn nhất quyền lực , liền sẽ làm sao bây giờ ? Đương nhiên là dùng cái này đến giúp đỡ sinh con chính mình cùng bồi dưỡng mình gia tộc .”\n“ Có lẽ sẽ không rất rõ ràng , nhưng dù là kém nhất tình huống , cũng sẽ là trung lập !”\n“ Có thể trúng lập , có đôi khi chính là thiên vị !”\nLý Ân Phàm nói đến đây , nở nụ cười , sau đó nói nghiêm túc :\n“ Ở cổ đại này , là nữ tử nhất định phải làm .”\n“ Mà cái này , chính là thế gia hoặc môn phiệt cùng với quý tộc , vì sao muốn bồi dưỡng nữ tử nguyên nhân !”\n“ Đây chính là thông gia !”\nSau đó , Lý Ân Phàm nói đến một cái lịch sử sự kiện .\n“ Trước công nguyên năm , Tần Sở hai nước vui kết liền cành , hai mươi mốt tuổi Tần Chiêu Tương vương cưới cái Sở quốc cô nương làm vương hậu .”\n“ Năm thứ hai , Tần chiêu tương Vương cùng Sở Hoài vương tại Hoàng Cức ( Nay Hà Nam Nam Dương nam ) gặp mặt một lần , Tần quốc liền đem Thượng Dung khu vực ( Nay Hồ Bắc Trúc Khê , phòng huyện khu vực ) còn đưa Sở quốc .”\n“ Sở Hoài vương còn nâng đỡ sở hệ ngoại thích hướng thọ làm tới Tần quốc thừa tướng .”\n...', 'output\\mp3\\Màn Trời Quyền Lực Diễn Biến Cùng Truyền Thừa\\0044_Thứ 44 chương Mưu đồ gì.mp3', '2026-09-01T13:41:51.641966+00:00', 'completed', 'completed', 7211, 7211),
	(50, 7, '7646956583435387416', 45, 'Thứ 45 chương Hạch tâm nhất lý niệm, là sẽ không thay đổi', 'Thứ chương Hạch tâm nhất lý niệm , thì sẽ không biến\nHiện đại thời không .\n“ Có thể có người nghe được cái này lịch sử sự kiện , liền sẽ nghĩ , sau đó Tần Sở hai nước , quan hệ cũng giao ác a ?”\n“ Vì cái gì Tần quốc Sở Hệ hậu cung thế lực , còn có thể tồn tại đâu ?”\nLý Ân Phàm nói đến đây thời điểm , cười cái này tiếp tục nói :\n“ Đương nhiên là bởi vì , nàng vẻn vẹn chỉ là hậu cung ngoại thích thế lực a !”\n“ Khi cần nàng , nàng chính là Sở Hệ thế lực , không cần thời điểm , nàng chính là Tần quốc hậu cung thế lực .”\n“ Sở Hệ , có đôi khi chỉ là nàng tên , nhưng có đôi khi ? Lại là nàng thực !”\n“ Nhưng cuối cùng tới nói , chính là nàng thực .”\n“ Trở mặt là trở mặt , thời kỳ chiến quốc , hôm nay ngươi đánh ta , ngày mai ta đánh ngươi , hậu thiên lại kết minh .”\n“ Cái này lại có quan hệ gì đâu ?”\n“ Mà quốc quân , hoặc có lẽ là quân chủ , hoàng đế , hắn kỳ thực chính là một cái trọng tài !”\n“ Nhiều khi , hắn cũng cần dùng thế lực ngoại lai , tới áp chế nổi bổn quốc thế lực !”\n“ Đây chính là “ Thông gia ” Bản chất .”\n“ Trong đó điểm trọng yếu nhất là cái gì ?”\nLý Ân Phàm gặp Ngụy Gia trên mặt còn có một số nghi hoặc , lắc đầu , chuẩn bị đem lời nói thẳng thắn hơn .\n“ Rất nhiều người có thể nghe được cái này , vẫn có một ít nghi vấn , hoặc có lẽ là nghi hoặc .”\n“ Tại sao sẽ như vậy ? Cái này chẳng lẽ không phải tại hậu cung bồi dưỡng gián điệp sao ? Chẳng lẽ cái này sẽ không đối với Tần quốc tạo thành nguy hại gì sao ?”\n“ Hiện đại người , hoặc có lẽ là cận đại người , cũng là đầu tiên suy tính quốc , sau đó thì sao ? Mới là nhà ...”\n“ Nhưng ở cổ đại , cổ nhân trước hết nhất suy tính là cái gì ? Là nhà ! Là gia tộc !!!”\n“ Từ một điểm này , chúng ta đi xem , có phải hay không lập tức liền có thể hiểu rồi ?”\n“ Tấn quốc ba nhà phân tấn , nhưng lại tại phía trước !”\n“ Cái này cũng là ta vì sao lại nói , quốc quân hắn nhiệm vụ trọng yếu nhất là đương trọng tài ! Có đôi khi sẽ dùng thế lực ngoại lai , tới áp chế nổi bản thổ thế lực .”\n“ Đến nỗi ngoại lai này thế lực , cùng bổn quốc trở mặt ? Như vậy có quan hệ gì ?”\n“ Cũng bởi vì trở mặt , liền đem ngoại lai này thế lực đuổi đi ra ? Sau đó để bản thổ thế lực mở rộng ?”\n“ Cuối cùng , “ Ba nhà phân Tần ”?”\nNgụy Gia nghe được cái này , cuối cùng nghe hiểu rồi , thế nhưng chính là nghe hiểu rồi , hắn mới phát giác được rất hoang đường .\nHoang đường đã có chút không thể tin được .\n“ Không có vuốt rõ ràng cái này sau lưng lôgic quan hệ , kỳ thực rất bình thường , bởi vì ngươi là dùng hiện đại tam quan đi xem cổ đại .”\n“ Giống như là một câu nói : Không phải tộc loại của ta , chắc chắn sẽ nảy sinh dị tâm .”\n“ Người hiện đại lý giải chính là , dân tộc cái này “ Tộc ”.”\n“ Nhưng ở cổ đại không phải như thế !”\n“ Tại thời kỳ đầu , không phải tộc loại của ta cái này “ Tộc ”, là “ Thị tộc ” Tộc .”\n“ Đơn giản điểm tới nói , chính là gia tộc “ Tộc ”!”\n“ Tần quốc Tần Vương , hắn đầu tiên phải cân nhắc , là quốc quân vị trí này , phải vĩnh viễn thuộc về “ Thắng ”.”\n“ Đến nỗi ngoại lai ngoại thích thế lực ? Cũng là nữ tử , các nàng làm sao có thể leo lên quốc quân vị trí ?”\n“ Ngược lại là bản thổ quý tộc thế lực , bọn hắn ngược lại là có rất lớn khả năng leo lên quốc quân vị trí !”\n“ Tại thời điểm này , nữ tử là vô luận như thế nào đều leo lên không được quốc quân vị trí !”\n“ Ngoại lai nam tử ? Cũng không khả năng ! Bản thổ quý tộc và tôn thất , bọn hắn sẽ không đồng ý !”\n“ Cho nên , vì cái gì không sử dụng đây ?”\nLý Ân Phàm nói đến đây , cười híp mắt nhìn xem Ngụy Gia , nhẹ giọng hỏi :\n“ Ngươi là quốc quân , ngươi sẽ không cần sao ?”\n“ Dùng tốt như vậy công cụ nhân thế lực , dựa vào cái gì không sử dụng đây ?”\nNghe nói như thế , Ngụy Gia cười khổ lắc đầu , hắn là thực sự không nghĩ tới , cái này sau lưng lại là dạng này lôgic quan hệ ?\nSau đó , Lý Ân Phàm lại bắt đầu nói đến gia tộc cùng gia tộc .\n“ Gia tộc đâu ?”\n“ Gia tộc cũng giống như nhau a , Tần quốc cùng Sở quốc thông gia , bản chất kỳ thực chính là “ Thắng ” Cái này tôn thất , ban đầu là giữa quốc gia và quốc gia thông gia .”\n“ Nhưng đến đằng sau , chính là “ Gia tộc ” Cùng “ Gia tộc ”.”\n“ Cho dù là hậu thế , gia tộc cùng gia tộc thông gia , trên bản chất lôgic quan hệ , cùng phía trên không có gì khác nhau !”\n“ Cuối cùng tới nói , chính là cường cường liên hợp , hay là bổ sung .”\n“ Để cho hai nhà , tạo thành càng thêm kiên cố quan hệ .”\n“ Hơn nữa , một cái gia tộc tộc trưởng , ngươi sẽ không thật sự cho là tộc trưởng lên tiếng , liền có thể nhất ngôn cửu đỉnh a ?”\n“ Đó là lý tưởng nhất một cái trạng thái !”\n“ Huống hồ , một cái gia tộc bên trong , mặt trắng là tộc trưởng hát ! Cái kia mặt đen là ai hát ?”\nSau đó , Lý Ân Phàm nói đến đây , dừng lại một chút , lại tiếp tục nói :\n“ Có đôi khi , nữ tử gả đi , chính là muốn tuyên dương gia tộc mình lý niệm , tiếp đó để cho đối phương gia tộc tới tán đồng gia tộc của mình .”\n“ Hoặc có lẽ là , đến giúp đỡ gia tộc của mình .”\n“ Đây là khi đó thông gia , nữ tử tất yếu trách nhiệm cùng nghĩa vụ !”\n“ Trong lịch sử , gia tộc cùng gia tộc thông gia , cuối cùng sát nhập thành một cái gia tộc tình huống , cũng không ít gặp !”\n“ Đương nhiên , trọng yếu nhất , đương nhiên là tại chúng ta cổ đại , là phụ hệ quyền uy xã hội .”\nCuối cùng , Lý Ân Phàm giơ lên trong tay phấn viết , tại trên bảng đen viết “ Hòa thân ” Hai chữ phía dưới , lại vẽ hai đầu đường dọc .\nTại đường dọc cuối cùng , Lý Ân Phàm viết lên “ Quốc gia ”.\n“ Cho nên , chúng ta lại đến nhìn , cái gọi là “ Hòa thân ”...”\nLý Ân Phàm quay đầu nhìn Ngụy Gia , nhẹ giọng hỏi :\n“ Lần này , ngươi hẳn phải biết vì sao ta biết nói , “ Hòa thân ” Cùng “ Thông gia ” Sau lưng lôgic quan hệ là giống nhau a ?”\n“ Cuối cùng , vẫn là một bộ kia đấu pháp !”\n“ Hòa thân , có thể nói là từ Hán triều , chuẩn bị nói là Tây Hán thời kì liền bắt đầu .”\n“ Khi đó vì cái gì hòa thân ?”\n“ Kỳ thực rất đơn giản , chính là muốn để một nữ tử đi qua , chiếm giữ “ Hậu cung thế lực ”, đến đúng dị tộc “ Triều đình thế lực ” Thực hiện ảnh hưởng , để cho bổn quốc , cũng chính là Hán triều , có đầy đủ thời gian phát dục .”\n“ Vậy ngươi đoán một chút , thời kỳ chiến quốc , Tần Chiêu Tương vương thời kì , Sở quốc cùng Tần quốc thông gia , có hay không mới vừa nói ý tứ kia ?”\n“ Trước công nguyên năm , Tần Sở hai nước vui kết liền cành , hai mươi mốt tuổi Tần Chiêu Tương vương cưới cái Sở quốc cô nương làm vương hậu .”\n“ Năm thứ hai , Tần Chiêu Tương Vương cùng Sở Hoài vương tại Hoàng Cức ( Nay Hà Nam Nam Dương nam ) gặp mặt một lần , Tần quốc liền đem Thượng Dung khu vực ( Nay Hồ Bắc Trúc Khê , phòng huyện khu vực ) còn đưa Sở quốc . Sở Hoài vương còn nâng đỡ Sở Hệ ngoại thích hướng thọ làm tới Tần quốc thừa tướng .”\nLý Ân Phàm đem trước đây cố sự , lại lần nữa nói một lần .\n“ Sở quốc cùng Tần quốc , có phải hay không hòa thân đâu ?”\n“ Đương nhiên cũng vậy ...”\n“ Chỉ là đổi một cái tên , nói thật dễ nghe điểm gọi thông gia .”\n“ Nhưng kỳ thực , cái này sau lưng lôgic quan hệ , là giống nhau , không hề khác gì nhau !”\nNói đến đây cuối cùng , Lý Ân Phàm thả ra trong tay phấn viết , tổng kết một chút nói :\n“ Thời điểm đó nữ tử , hưởng thụ gia tộc chỗ tốt , vậy các nàng tự nhiên liền mang theo trách nhiệm như vậy cùng nghĩa vụ .”\n“ Đây là gia tộc giao phó trách nhiệm của các nàng , cũng là gia tộc , tại sao muốn bồi dưỡng nguyên nhân của các nàng .”\n“ Bằng không thì vì cái gì tại cổ đại dạng này đẳng cấp sâm nghiêm phong kiến phụ hệ xã hội , muốn bồi dưỡng nữ tử ?”\n“ Cho nên , không chỉ là nam tử có trách nhiệm của bọn hắn cùng nghĩa vụ , nữ tử , cũng tương tự có trách nhiệm của các nàng cùng nghĩa vụ .”\n“ Nhưng , cuối cùng , chính là vì “ Gia tộc ”, vì “ Vương triều ”...”\n“ Hạch tâm nhất lôgic lý niệm , thì sẽ không biến !”\n“ Từ Hán triều bắt đầu , mãi cho đến Đường triều hòa thân , đặc biệt là Đường triều hòa thân , thì càng là mang theo trách nhiệm như vậy cùng nghĩa vụ .”\n“ Nói một cách khác , từ hòa thân sinh ra một khắc kia trở đi , các nàng liền mang theo hoàng đế giao cho nhiệm vụ của các nàng .”\n“ Chờ đến lúc đằng sau chúng ta nói đến Đường triều , sẽ cẩn thận giảng một chút vì cái gì Đường triều Thái Tông Lý Thế Dân sẽ cùng thân .”\n......', 'output\\mp3\\Màn Trời Quyền Lực Diễn Biến Cùng Truyền Thừa\\0045_Thứ 45 chương Hạch tâm nhất lý niệm, là sẽ không thay đổi.mp3', '2026-09-01T13:42:56.587329+00:00', 'completed', 'completed', 8024, 8024);
INSERT INTO `chapters` (`id`, `novel_id`, `chapter_site_id`, `chapter_number`, `title`, `content`, `mp3_path`, `crawled_at`, `crawl_status`, `tts_status`, `tts_chars_total`, `tts_chars_done`) VALUES
	(51, 7, '7646956853003305496', 46, 'Thứ 46 chương Ngoại lai cùng bản thổ khác nhau', 'Thứ chương Ngoại lai cùng bản thổ khác nhau\nHiện đại thời không .\n“ Vậy tại sao Đường triều sau đó , Hán Nhân Vương Triều , cơ hồ liền không có hòa thân ?”\nNgụy Gia nhìn xem Lý Ân Phàm , lại đưa ra trong lòng mình một cái nghi vấn .\nCái này cũng là hắn tại nhìn lịch sử lúc , một mực nghi ngờ , vì cái gì Đường triều sau đó , hòa thân liền cơ hồ không còn ?\nNhưng đến Thanh triều , lại bắt đầu hòa thân ?\nLý Ân Phàm nói nhiều như thế , đang chuẩn bị uống mấy ngụm nước lại đến nói .\n“ Ta để giải thích một chút đi .”\nTrần Xuyên Phú cầm ống nói lên , ra hiệu Lý Ân Phàm trước nghỉ ngơi một chút .\nLý Ân Phàm gật đầu một cái , một lần nữa ngồi xuống ghế , để cho Trần Xuyên Phú tới nói .\n“ Từ Đường triều sau đó , Hán Nhân Vương Triều đúng là cơ hồ không có và hôn .”\n“ Sau này vương triều bên trong , chỉ có Nguyên triều hòa thanh triều , mới có đại quy mô hòa thân .”\n“ Đây quả thật là rất có mê hoặc tính chất , nhưng ta nói với ngươi hai cái sự kiện trọng đại , ngươi liền biết là tại sao .”\nTrần Xuyên Phú điều chỉnh một chút tư thế ngồi , xấp xếp lời nói một chút , nhìn xem Ngụy Gia , nói rất là nghiêm túc nói :\n“ Thứ nhất sự kiện , Vũ Tắc Thiên xưng đế .”\n“ Thứ hai chuyện này , loạn An Sử !”\nNói xong hai cái này sự kiện , Trần Xuyên Phú lại nói dạng này một phen :\n“ Đã có sự tình , sau nhất định lại có !”\n“ Đã hành chi chuyện , sau nhất định lại đi !”\n“ Làm sao ngươi biết , hòa thân gả đi nữ tử , sẽ không ngược lại khuyên người cầm quyền tiến đánh chính mình ? Tiếp đó chính mình ngồi trên hoàng vị ?”\n“ Tùy triều Nghĩa Thành công chúa , tại Vũ Tắc Thiên xưng đế phía trước , rất phổ biến , thời điểm đó hòa thân công chúa , cơ hồ cũng là như thế .”\n“ Nhưng , Vũ Tắc Thiên xưng đế sau đó ? Không ai dám tin tưởng sẽ còn có !”\n“ Dù sao nữ tử xưng đế sự tình đều có , cái này xấu nhất tình huống cũng đã xuất hiện , ngươi nói , ta mới vừa nói tình huống kia , có thể xuất hiện hay không ?”\nCó thể xuất hiện hay không ? Ngụy Gia ở trong nội tâm hỏi một câu như vậy .\nSau đó trầm mặc .\nBởi vì hắn cũng không biết !\n“ Có phải hay không cảm thấy không biết ?”\n“ Không biết , cái kia vốn là đại biểu cho sự không chắc chắn .”\n“ Hoàng đế , đại thần , ai sẽ nguyện ý lội lấy cái này cực lớn sự không chắc chắn ?”\n“ Thật sự xuất hiện , là ngươi phụ trách ? Vẫn là hoàng đế phụ trách ? Lại có lẽ là những thứ khác người nào phụ trách ?”\nCó thể nói đến nơi đây , Ngụy Gia vẫn có một ít nghi hoặc .\n“ Vậy vì sao Nguyên triều hòa thanh triều , bọn hắn vẫn là thi hành và thân chính sách đâu ?”\n“ Bởi vì bọn hắn vốn là ngoại lai !”\nTrần Xuyên Phú nghe được vấn đề này , rất là quả quyết nói .\n“ Ngoại lai , bọn hắn cần có nhất áp chế là thế lực gì ? Ngươi đoán một chút !”\nA ? Ngụy Gia nghe được vấn đề này , đầu tiên là sững sờ .\nSau đó trong đầu lập tức hiện ra một thế lực : Bản thổ thế lực .\n“ Nhìn nét mặt của ngươi , ngươi hẳn biết .”\n“ Đúng vậy , ngoại lai , cần áp chế là bản thổ thế lực !”\n“ Nếu như không cùng thân , bọn hắn liền cần đồng thời đối mặt , bản thổ thế lực phản kháng , còn có ngoài ra ngoại lai thế lực công kích !”\n“ Mà bản thổ thế lực , vì cái gì không kết giao ? Bởi vì làm bản thổ thế lực chủ đạo , hắn chỉ cần đối mặt một thế lực , chính là thế lực ngoại lai !”\n“ Nhưng là giống ta mới vừa nói , thế lực ngoại lai , vậy coi như bất đồng rồi .”\n“ Nếu là hắn không kết giao , trước không đem thế lực ngoại lai làm yên lòng , tiếp đó chuyên tâm trấn áp bản thổ thế lực .”\n“ Hai tuyến chiến đấu ?!”\n“ Một cái bình thường hoàng đế , cũng sẽ không để cho chính mình gặp phải cục diện như vậy .”\nNgụy Gia chậm rãi gật đầu một cái , nhẹ nói :\n“ Thì ra là như thế ...”\n...\nĐại hán .\nNguyên thú 4 năm .\n“ Hòa thân sao ...”\nLưu Triệt là không phản đối hòa thân .\nBởi vì tại hắn bộ dạng này hoàng đế xem ra , chỉ cần có thể đạt tới mục tiêu chiến lược của mình , liền xem như hòa thân , thì thế nào đâu ?\nNếu như đạt không thành mục tiêu chiến lược của mình , chính mình lại vì cái gì muốn đi hòa thân ?\nGiống như là tại hắn thượng vị sơ kỳ , Hung Nô liền từng thỉnh cầu qua một lần hòa thân .\nHắn chính xác ngắn ngủi đồng ý qua , thế nhưng chỉ là vì tê liệt Hung Nô , hơn nữa cũng chỉ là đồng ý , không có tiễn đưa công chúa đi qua .\nSau đó liền phát động Mã Ấp Chi mưu ( Phía trước năm ), mở ra đại quy mô quân sự phản kích .\nSau đó Hung Nô yêu cầu hòa thân , Lưu Triệt cũng đồng ý , nhưng điều kiện tiên quyết là cái gì ? Điều kiện tiên quyết là yêu cầu Hung Nô xưng thần , tiễn đưa hạt nhân .\nSau đó hai lần hòa thân , lại cũng là cùng ô tôn hòa thân , mục tiêu chiến lược chính là vì áp dụng “ Đánh gãy Hung Nô cánh tay phải ” Xa thân gần đánh sách lược . Thời điểm đó hòa thân công chúa , cũng đều là mang theo nhiệm vụ như vậy đi qua !\nTrừ cái đó ra , chọn lựa hòa thân công chúa cũng đều là vì gõ một số người , tận lực lựa chọn .\nTỉ như nói Phía trước năm tả hữu phái mảnh quân công chúa ( Sông đều Vương Lưu Kiến chi nữ ) gả ô Tôn Côn Mạc Liệp Kiêu mị sau lại phái Giải lo công chúa ( Sở vương Lưu Mậu tôn nữ ) kế gả ô Tôn Vương Sầm tưu , ông về mị .)\n...\nĐường triều .\nTrinh Quán bảy năm .\n“ Hòa thân ?”\nLý Thế Dân nhẹ giọng thì thầm một tiếng .\nSau đó gật đầu một cái , không thèm để ý chút nào .\nVới hắn mà nói , nếu quả thật đi tới một bước kia , phải cùng thân một bước kia , hắn cũng đồng dạng sẽ dùng .\nDù sao , Nghĩa Thành công chúa thế nhưng là cho Lý Thế Dân lưu lại ấn tượng rất sâu sắc .\n“ Nhưng Vũ Tắc Thiên xưng đế , thật sự đối với hậu thế lưu lại ảnh hưởng lớn như vậy sao ?”\nNghe đến đó , Lý Thế Dân nhíu mày , có chút không hiểu , vì cái gì đời sau cục thế chính trị tựa hồ lập tức liền chuyển một cái ngoặt lớn .\nHoàn toàn có chút xem không hiểu ?\n“ Đến cùng xảy ra chuyện gì ? Còn có loạn An Sử ?”\nMàn trời nói càng nhiều , nhưng Lý Thế Dân nội tâm , ngược lại nghi hoặc càng ngày càng nhiều .\nDưới đài rất nhiều đại thần cũng đồng dạng là như thế , nghi hoặc cùng Lý Thế Dân giống nhau .\nVì cái gì về sau những người kia , nhìn , có chút bó tay bó chân ?\n...\nTống triều .\nMở bảo sáu năm .\n“ Ai ...”\nTriệu Khuông Dận xoa trán một cái , không biết nên nói cái gì .\nHắn kỳ thực đối với Vũ Tắc Thiên xưng đế không có nhìn gì , nhưng thủ hạ thế lực , những người kia , lại vĩnh viễn không có khả năng đồng ý để cho nữ tử cầm quyền .\nDù sao Vũ Tắc Thiên lưu cho đời sau ấn tượng , thật sự là quá sâu sắc .\nDù là hoàng đế đối với cái này không quan trọng , dù sao Vũ Tắc Thiên cuối cùng vẫn như cũ còn Đường .\nThế nhưng chút “ Căn cơ ” Đâu ? Những thế lực to lớn kia đâu ?\nĐây là một cái mãi mãi cũng không cách nào vòng qua vấn đề ! Cũng là đáp án để ở nơi đó vấn đề !\nSách sử ngay tại trước mặt mình ! Dù là nghĩ giả vờ không nhìn thấy , đều không được !\nLập trường liền đã quyết định một ít chuyện , không có khả năng lại để cho nó xảy ra !\n...\nMinh triều .\nVĩnh Lạc bảy năm .\n“ Vũ Tắc Thiên xưng đế , mang tới ảnh hưởng cũng không chỉ như thế ...”\nChu Cao Sí hơi xúc động , bởi vì thân ở hắn vị trí này , đối với rất nhiều vấn đề , nhận biết cũng là vô cùng sâu .\nTỉ như nói : Một ít trải qua thời gian dài , một mực hoạt động mạnh trên triều đình thế lực , từ đó về sau , cơ hồ liền biến mất .\nKhông tệ , chính là ngoại thích thế lực !\nCái này một cỗ duy nhất thuộc về hoàng hậu thế lực !\nTừ đó về sau , cơ hồ thì nhìn không thấy bóng dáng của bọn hắn .\nVì cái gì ? Bởi vì tất cả mọi người đều không nghĩ tới , ngoại thích thế lực , vậy mà thật sự có thể biến thành tôn thất thế lực ?\nVậy dạng này vừa tới , ai còn sẽ tin tưởng ngươi ngoại thích thế lực đâu ?\n......', 'output\\mp3\\Màn Trời Quyền Lực Diễn Biến Cùng Truyền Thừa\\0046_Thứ 46 chương Ngoại lai cùng bản thổ khác nhau.mp3', '2026-09-01T13:43:03.068961+00:00', 'completed', 'completed', 7417, 7417),
	(52, 7, '7647340112488972824', 47, 'Thứ 47 chương Người hợp tác', 'Thứ chương Người hợp tác\nHiện đại thời không .\n“ Cho nên , chúng ta giải được “ Thông gia ” Cùng “ Hòa thân ” Bản chất , chúng ta lại trở lại vấn đề kia .”\n“ Tần quốc hậu cung Sở Hệ thế lực , vì sao lại phản loạn ?”\n“ Đáp án đã rõ ràng , chính là chúng ta mới vừa nói nguyên nhân kia .”\nLý Ân Phàm tổng kết một chút vừa rồi vấn đề kia , sau đó lại tiếp tục nói :\n“ Gả ra ngoài nữ nhi , tát nước ra ngoài .”\n“ Đây là đời sau một câu tục ngữ ...”\n“ Nhưng ở Tống triều phía trước ? Thế nhưng là không có câu này tục ngữ .”\n“ Hơn nữa , câu này tục ngữ sớm nhất xuất hiện ở nơi nào ? Xuất từ đời nhà Thanh tiểu thuyết 《 Vẽ Phương Lục 》 hồi 19 , cũng thấy ở 《 Hồng Lâu Mộng 》 cùng 《 Sơn Hương biến đổi lớn 》 các loại tác phẩm .”\nLúc này , Trần Xuyên Phú bỗng nhiên nói tiếp nói :\n“ Ta trước đó không biết ở đâu nhìn qua một thiên văn chương , lúc đó ta xem , cảm thấy nói thật có đạo lý .”\nLý Ân Phàm 3 người , quay đầu nhìn Trần Xuyên Phú , chờ đợi hắn lời kế tiếp .\n“ Vì cái gì Tần , Hán , Tùy , Đường , cái này 4 cái vương triều tại cùng thời kỳ đều vô cùng cường đại ?”\n“ Là chế độ của bọn hắn sao ? Không phải !”\n“ Là bọn hắn đại thần lợi hại sao ? Đời sau rất nhiều đại thần , cũng đồng dạng lợi hại , thậm chí , có chút còn muốn càng thêm lợi hại một chút !”\n“ Vẫn là nói hoàng đế ? Đời sau cái gọi là minh quân , kỳ thực cũng không thiếu .”\n“ Nhưng vì cái gì nhìn Đường cùng với Đường trước đây thời kì , liền so đời sau vương triều lợi hại hơn ?”\n“ Các ngươi đoán một chút , đây là vì cái gì ?”\nVấn đề này tựa hồ có chút phức tạp .\nLương Phong cùng Ngụy Gia hai người , đều cau mày bắt đầu suy tư .\n“ Có phải hay không cảm thấy vấn đề này , nhìn tựa hồ rất phức tạp ? Dính đến rất nhiều thứ ?”\nTrần Xuyên Phú nhìn xem Lương Phong hai người , cầm microphone , chậm rãi hỏi .\nHai người đều gật đầu một cái .\n“ Thiên văn chương kia nói , vấn đề này , nhìn giống như đúng là rất phức tạp .”\n“ Nhưng kỳ thật đâu ? Đáp án rất đơn giản .”\n“ Bởi vì những thứ này vương triều lợi dụng nhân khẩu , so đời sau những cái kia vương triều , nhiều 1⁄3 , hoặc có lẽ là một nửa ?”\nCâu nói sau cùng , Trần Xuyên Phú là dùng mang theo giọng nghi vấn .\nMà Lương Phong cùng Ngụy Gia hai người nghe được đáp án này , lại sững sờ .\nHai người sững sờ tại chỗ , không biết nên nói cái gì .\n“ Giống như đúng là dạng này , nhiều nhiều người như vậy miệng , làm sao có thể không cường đại đâu ?”\nLương Phong nhíu mày , lẩm bẩm nói .\n“ Hơn nữa các ngươi cũng cần phải biết , cái này nhiều hơn nhân khẩu , đến cùng là ai a ?”\n“ Vì cái gì nói cái này nhiều hơn nhân khẩu , liền để trước mặt Chư Đa Vương Triều mạnh lên ?”\n“ Bởi vì thời điểm đó song phương kết hợp , mặc kệ là thượng tầng vẫn là tầng dưới chót lại có lẽ là trung tầng .”\n“ Bọn hắn là người hợp tác !”\n“ Mà không phải hậu thế vương triều cái chủng loại kia Y Phụ Giả !”\nNói đến đây , Trần Xuyên Phú trầm mặc một hồi sau , lại tiếp tục nói :\n“ Cho dù là về sau gia tộc cùng gia tộc thông gia , đại đa số thời điểm , cũng sẽ không là trước kia thời kỳ loại kia đi qua liền có thể chủ đạo nhân vật .”\n“ Là cái gì đây ? Hạt nhân !”\n“ Đúng vậy , nhìn như giống như là “ Hạt nhân ” Một dạng .”\nRất nhiều từ ngữ bởi vì đối mặt với camera , Trần Xuyên Phú hết chỗ chê quá rõ .\nNhưng ở ngồi mấy người , đều biết Trần Xuyên Phú nói là cái gì .\n“ Giống như là chúng ta bình phán cái gọi là hoàng đế hoàng hậu , “ Hiền sau ”.”\n“ Các ngươi cũng không có phát hiện sao ? Chính các ngươi đều đem “ Hiền sau ” Tiêu chuẩn hàng lại hàng .”\n“ Tại Tống triều phía trước , hiền sau cọc tiêu là ai ? Đông Hán minh đức Mã hoàng hậu , cùng hi hoàng hậu Đặng Tuy ...”\n“ Chúng ta lại nhìn , Tống triều sau đó những cái kia “ Hiền sau ”.”\n“ Các nàng làm cái gì , để chúng ta hậu thế cho rằng các nàng là “ Hiền sau ”?”\nTrần Xuyên Phú nói đến đây , nở nụ cười , nhìn xem Lương Phong cùng Ngụy Gia nói :\n“ Hai tướng so sánh , lần này có phải hay không phát hiện vấn đề chỗ ?”\nLương Phong cùng Ngụy Gia hai người liếc nhau một cái , sau đó gật đầu một cái .\nBọn hắn chính xác phát hiện vấn đề chỗ .\n“ Cho nên ta mới có thể nói , bọn hắn là từ người hợp tác , lập tức đã biến thành Y Phụ Giả .”\n“ Mà Y Phụ Giả tiêu chuẩn là gì ? Đương nhiên là ngươi làm tốt ngươi chuyện nên làm !”\n“ Người hợp tác đâu ? Lập tức lại khác biệt ! Điển hình nhất liền là ai ?”\n“ Chỉ chúng ta mới vừa nói hai vị kia “ Hiền sau ”.”\n“ Đương nhiên , còn có một vị , đem người hợp tác tinh thần phát huy đến cực hạn , Hán Cao Tổ Lưu Bang hoàng hậu .”\n“ Mà hậu thế đâu ?”\n“ Dù là hậu thế chợt có mấy cái có thể sánh vai Đông Hán “ Hiền sau ”, cũng đều sẽ bị chửi bới , hoặc có lẽ là bị ô danh hóa .”\n“ Tống triều Lưu Nga chính là như thế !”\n“ Lấy nàng hành động , đặt ở Đông Hán , hậu thế bình một cái “ Hiền sau ”, thật sự không đủ .”\nNói đến đây , Trần Xuyên Phú thở dài một hơi sau , chậm rãi nói :\n“ Ngươi nhìn , đời sau vương triều , bọn hắn đều cảm thấy Y Phụ Giả liền nên làm Y Phụ Giả chuyện , không thể vượt cự .”\n“ Kia đối so trước đó vương triều , thiếu đi nhiều như vậy nhân khẩu , dựa vào cái gì còn có thể cùng thời kỳ trở thành tối cường ?”\n“ Dựa vào cái gì còn có thể giống Hán cùng Đường như thế , đều mẹ nó đến thời kì cuối , còn có thể ngẫu nhiên mang đi mấy vị may mắn ?”\nNghe xong Trần Xuyên Phú mà nói , Lương Phong cầm ống nói lên , rất là bất đắc dĩ nói :\n“ Nói thật , ngươi những lời này , giải quyết ta chôn giấu trong lòng rất lâu một cái nghi hoặc .”\n“ Vì cái gì Tống triều cùng Minh triều thoạt nhìn là mạnh như vậy , nhân khẩu cũng không thiếu , nhưng đến thời kì cuối , lại lập tức trở nên có chút mềm yếu bất lực .”\n“ So sánh Hán , Đường hai cái này vương triều thời kì cuối , lập tức liền có thể phát hiện khác biệt .”\nNói xong điểm này , Lương Phong trầm mặc một hồi , nói ra mấy câu nói như vậy :\n“ Thống kê nhân khẩu thời điểm , là thống kê toàn bộ .”\n“ Nhưng thực tế lợi dụng nhân khẩu ? Có lẽ mới chỉ có một nửa , hay là 2⁄3 .”\n“ Cứ như vậy tỉ lệ , đến vương triều thời kì cuối ...”\nLý Ân Phàm lúc này cầm ống nói lên , nói tiếp nói :\n“ Kỳ thực không có nhiều như vậy ! Chỉ có thể càng ít !”\nCàng ít ? Lương Phong cùng Ngụy Gia nghi ngờ nhìn về phía Lý Ân Phàm .\nBên cạnh Trần Xuyên Phú cũng có chút nghi hoặc Lý Ân Phàm tại sao lại nói như vậy .\n“ Trong đó một phương đã biến thành Y Phụ Giả sau đó , các ngươi còn quên một chuyện !”\n“ Chuyện gì ? Người chủ đạo là muốn chiếu cố Y Phụ Giả !”\n“ Cho nên , các ngươi cho là từ người hợp tác biến thành Y Phụ Giả , lợi dụng nhân khẩu chỉ có một nửa ?”\n“ Kỳ thực càng ít !”\n“ Bởi vì một phương khác đại bộ phận tinh lực , còn muốn đi chiếu cố Y Phụ Giả !”\nCái này ?\nĐang ngồi 3 người lập tức bừng tỉnh đại ngộ .\nĐúng vậy a , Y Phụ Giả , là phải bị chăm sóc .\nNhìn như từ người hợp tác lập tức biến thành Y Phụ Giả , thiếu mất một nửa , nhưng thực tế đâu ?\nChỉ có thể thiếu càng nhiều !\nLúc này , Lý Ân Phàm nhìn về phía camera , thần sắc nói nghiêm túc :\n“ Có thể còn có người hơi nghi hoặc một chút , vì sao lại càng ít ?”\n“ Bởi vì đây không phải đơn giản toán học vấn đề !”\n“ Ta làm một cái tỷ dụ a !”\n“ Một đoạn trên đường lớn , có hai người tựa sát nhau lấy , hợp tác đi tới một nửa .”\n“ Cái này đến một nửa , bỗng nhiên trong đó có một người , hắn không thể đi nữa , cần một người khác đỡ lấy hắn , chiếu cố hắn , mới có thể đi đến điểm kết thúc .”\n“ Hoặc có lẽ là , muốn cõng một người khác , mới có thể đi đến điểm kết thúc .”\n“ Ngươi có thế để cho hắn từ bỏ một người khác , tiếp đó đi lợi dụng hắn một người này sao ?”\n...', 'output\\mp3\\Màn Trời Quyền Lực Diễn Biến Cùng Truyền Thừa\\0047_Thứ 47 chương Người hợp tác.mp3', '2026-09-01T13:43:09.586760+00:00', 'completed', 'completed', 7403, 7403),
	(53, 7, '7647340289132085784', 48, 'Thứ 48 chương Dựa vào giả', 'Thứ chương Y Phụ Giả\nHiện đại thời không .\n“ Cái này ...”\n“ Chính xác không nghĩ tới điểm này , không nghĩ tới Y Phụ Giả là cần dựa vào người chủ đạo , mà người chủ đạo là cần chiếu cố Y Phụ Giả .”\nTrần Xuyên Phú lúc này cũng nghĩ thông , có chút vấn đề chính xác không thể giống trước đây chính mình như thế tính toán .\n“ Cho nên , đời sau một chút vương triều , nhìn như là từ bỏ một nửa nhân khẩu , chỉ muốn lợi dụng một nửa khác .”\n“ Hoặc có lẽ là , là từ bỏ 1⁄3 nhân khẩu , lợi dụng cái kia 2⁄3 nhân khẩu .”\n“ Nhưng đây chỉ là lý tưởng nhất trạng thái !”\n“ Khi ngươi từ bỏ cái kia một nửa hay là 1⁄3 , vậy sẽ chỉ từ bỏ càng nhiều .”\n“ Để cho cái kia một nửa hoặc 1⁄3 nhân khẩu tự sinh tự diệt ?”\n“ Ngươi dám để các nàng tự sinh tự diệt , ngươi lợi dụng những người kia , liền dám tạo phản !”\nSau đó , Lý Ân Phàm cầm microphone , lại tiếp tục nói :\n“ Đây chính là phía sau một chút vương triều hoàng đế đầu vỗ một cái kết quả .”\n“ Cảm thấy cũng chỉ là đơn giản toán học đề .”\n“ Từ bỏ một nửa , còn không có một nửa còn lại sao ? Cho nên có cái gì tốt lo lắng ?”\n“ Nghiền ép nghiền ép , còn có thể nghiền ép ra 2⁄3 đâu .”\n“ Nhưng ngươi lợi dụng cái này một số người , hắn không đi phân tinh lực chiếu cố ? Không thèm nghĩ nữa ? Không đi lo lắng hãi hùng ?”\nNhìn xem camera , Lý Ân Phàm trong giọng nói tràn đầy nghi hoặc , hắn thật sự là nghĩ không ra , một ít hoàng đế đến cùng là nghĩ gì ?\n“ Cái này hoàn toàn chính là tăng lên một nửa khác người sợ chết chi phí !”\n“ Ngươi đây còn dám nói ngươi lợi dụng có một nửa nhân khẩu ? Hay là 2⁄3 nhân khẩu ?”\n“ Nhìn như cường đại , kì thực đụng một cái liền nát .”\nSau đó , Lý Ân Phàm thở dài một hơi sau , lại nói tiếp :\n“ Vì cái gì người hợp tác thời kì , có thể tốc độ nhanh như vậy cường đại ? Bởi vì một nửa khác chi phí thấp .”\n“ Biết dù là chính mình chết , chính mình một nửa còn lại người hợp tác , cũng có thể chiếu cố tốt trong nhà .”\n“ Nhưng làm trong đó một nửa đã biến thành Y Phụ Giả ?”\n“ Ngươi còn thế nào để cho hắn không đi tham sống sợ chết ?”\nNói đến đây , Lý Ân Phàm thần sắc trở nên có chút không hiểu , nhẹ nói :\n“ Đây không phải đơn giản toán học vấn đề , hay là cái gì chắc chắn vấn đề .”\n“ Đây là một cái rất khổng lồ xã hội vấn đề !”\n“ Dính đến mọi mặt .”\n“ Khi ngươi chỉ muốn lợi dụng một nửa nhân khẩu lúc , cho là cái này một nửa nhân khẩu liền có thể chống lên toàn bộ vương triều .”\n“ Kì thực ? Chân chính có hay không 1⁄4 cũng khó nói .”\n“ Hi vọng trạng thái , hoặc dùng băng lãnh con số đi xem , quả thật có một nửa , nhưng thực tế ?”\nLý Ân Phàm nói đến đây , lắc đầu , không còn nói tiếp .\n“ Cái kia như thế xem ra , đời sau vương triều , có thể tốc độ nhanh như vậy sụp đổ , không phải là không có lý do .”\nNhìn Lý Ân Phàm không tiếp tục nói tiếp , Lương Phong lúc này cầm ống nói lên , nói tiếp .\n“ Chuyện này chỉ có thể nói là một cái nguyên nhân rất lớn , không thể nói là toàn bộ nguyên nhân .”\n“ Vốn lấy phương diện này đẩy ra đạo , chỉ có thể nói một chút vương triều , có chút thời kì nhìn như cường đại , kì thực mập giả tạo là không có vấn đề .”\nCái này khiến Lương Phong cũng nghĩ đến rất nhiều .\nGiống như là Lý Ân Phàm nói vậy đơn giản đạo lý .\nHai người lẫn nhau hợp tác , đến một nửa , một phương không thể lại hành động , một phương khác không đi chiếu cố sao ?\nĐây không phải cái gì đơn giản thụ thương hoặc sinh bệnh cái gì .\nĐây là toàn bộ xã hội đối với một phương khác gò bó .\nCứ như vậy gò bó , cứ như vậy , một phương khác không đi chiếu cố ? Không đi phân tinh lực ? Làm sao có thể chứ ?\nHi vọng trạng thái quả thật có một nửa hay là 2⁄3 .\nCó thể để người vi phạm nhân tính , không nhìn tới chú ý một phương khác ?\nNói thật dễ nghe điểm lợi dụng có 1⁄4 , kì thực , tại Lương Phong xem ra , chân chính có hay không một phần mười ?\n“ Này ngược lại là để cho ta hiểu được một số việc .”\nNgụy Gia lúc này cầm ống nói lên , bỗng nhiên mở miệng nói ra .\n“ Gần hiện đại , là để cho người ta từ trong ruộng giải phóng ra ngoài , tiến nhà máy .”\n“ Mà cổ đại thời kỳ đầu , là để cho trong đó một phương , dường như là từ gia đình một phương giải phóng đi ra .”\n“ Mà tới được hậu kỳ , lại để cho ở trong đó một phương một lần nữa về đến nhà rồi tòa .”\n“ Nhìn như có một nửa , nhưng dạng này đến xem ?”\nNgụy Gia đột nhiên cảm thấy chính mình cảm khái rất nhiều .\nHắn thật sự là không nghĩ tới , có chút băng lãnh toán học vấn đề , chắc chắn vấn đề , đằng sau vậy mà cất dấu rất nhiều xã hội vấn đề .\n“ Hơn nữa , cái này cũng chưa tính dưới có không thể làm động , bên trên có hành động không được .”\n“ Cho nên , ngươi nói cường đại ? Từ nhân khẩu lợi dụng tới nói , ngươi tính thế nào cường đại ?”\n“ Ngươi nhìn Hán triều , lợi hại nhất Hán Vũ Đế , vậy thật là đem người miệng lợi dụng đến cực hạn , nghiền ép đến cực hạn .”\n“ Về sau Hán triều hoàng đế học ra dáng .”\n“ Cho dù là Đông Hán thời kì cuối , đến Tam quốc , vì cái gì tam phương đều có thể cường đại như vậy ?”\n“ Thật sự tất cả đều là thời đại vấn đề ?”\n“ Từ nhân khẩu tỉ lệ lợi dụng tới nói , đời sau một chút vương triều , cũng đã thua .”\nTrần Xuyên Phú nghe được cái này , cười một tiếng rồi nói ra :\n“ Bình đẳng nghiền ép mỗi người , đúng không ?”\n“ Đương nhiên , ngươi không bình đẳng nghiền ép mỗi người , ngươi như thế nào nhường ngươi vương triều cường đại lên ?”\n“ Phong Kiến Vương Triều , chẳng phải có chuyện như vậy sao ? Ngươi không bình đẳng nghiền ép , dựa vào cái gì vượt qua xung quanh nhiều như vậy ?”\nLương Phong nói rất chuyện đương nhiên , sau đó lại nói :\n“ Ngươi sau khi nhìn thế một chút vương triều , hai phe bên trong một phương , bọn hắn là không nghiền ép .”\n“ Đi học , bọn hắn là không nghiền ép .”\n“ Huân quý thượng tầng giai cấp , bọn hắn là không nghiền ép .”\n“ Cứ như vậy xuống , ngươi còn thế nào cường đại ?”\n“ Vẫn là câu nói kia , Phong Kiến Vương Triều , ngươi không nghiền ép , ngươi còn thế nào cường đại đâu ?”\n“ Còn lại một điểm kia người , ngươi có thể nghiền ép ra đồ vật gì ? Coi như nghiền ép đi ra , tầng tầng qua một lần tay , đến ngươi hoàng đế nơi này , ngươi còn có bao nhiêu ?”\n“ Hơn nữa , không chỉ là Hán triều , Xuân Thu Chiến Quốc , Ngụy Tấn Nam Bắc triều , Tùy Đường , cũng là như thế .”\n“ Dù là có một số người bọn hắn là không nghiền ép , nhưng ngoài ra ? Bọn hắn thật sự bình đẳng nghiền ép mỗi người .”\n“ Thời kỳ đỉnh phong chính là Hán Vũ Đế .”\n“ Trừ mình ra , ai cũng là có thể nghiền ép .”\n“ Cho nên Hán Vũ Đế thời kì vì cái gì cường đại như vậy ? Chung quanh cơ hồ đều đánh một lần .”\n...\nĐại Minh .\nVĩnh Lạc bảy năm .\nChu Lệ cùng Chu Cao Sí hai người không lời lẫn nhau nhìn nhau rất lâu .\nMàn trời nói một phương khác là ai ? Bọn hắn đương nhiên là biết đến .\nThế nhưng đúng là không nghĩ tới sâu như vậy .\nBởi vì bọn hắn thật sự cho là có thể hoàn mỹ lợi dụng ngoài ra một phương .\nNhưng chờ màn trời nói xong sau đó , bọn hắn mới phát hiện , vì cái gì bọn hắn nhiều lúc đều góp không ra rất nhiều thứ .\nMàn trời nói không sai , người có học thức bọn hắn là không nghiền ép , huân quý , thượng tầng giai cấp , cũng là không nghiền ép .\nCứ như vậy , còn từ bỏ trong đó một phương khác .\n“ Lão đại , màn trời nói không sai , cứ như vậy , ta Đại Minh còn thế nào cường đại ?”\nGiờ khắc này Chu Lệ , thật là cảm nhận được đến từ hậu thế xã hội học rung động .\nHắn trước kia là thật không nghĩ tới những vấn đề này .\nLiền hắn đây trước đó vẫn còn cho là Hán Vũ Đế Lưu Triệt là bạo quân đâu .\nCòn khinh thường tại học hắn .\nNhưng bây giờ đến xem ? Bạo quân ? Bạo quân tốt .\nBạo quân có thể để cho mình Đại Minh hoành áp xung quanh , trở nên cùng Hán Vũ Đế thời kì một dạng , hắn cũng nhận !\n“ Đúng , đúng , chính là như vậy ..”\nChu Lệ kích động run rẩy đứng lên .\n......', 'output\\mp3\\Màn Trời Quyền Lực Diễn Biến Cùng Truyền Thừa\\0048_Thứ 48 chương Dựa vào giả.mp3', '2026-09-01T13:43:15.033882+00:00', 'completed', 'completed', 7599, 7599),
	(54, 7, '7647642210229305880', 49, 'Thứ 49 chương Cái kia có thể nghiền ép bao nhiêu?', 'Thứ chương Cái kia có thể nghiền ép bao nhiêu ?\nĐại hán .\nNguyên thú 4 năm .\nLưu Triệt giờ khắc này hơi kinh ngạc nhìn xem màn trời .\nHắn thật sự là không biết , cái này có gì dễ nói ?\nNgươi không nghiền ép phía dưới tất cả mọi người , ngươi sao có thể kiếm ra quân nhu ?\nHơn nữa , tầng thấp nhất quỷ nghèo , có thể ép ra bao nhiêu ? Vơ vét hai ba lần , có thể hay không thỏa mãn một lần quân nhu cũng khó nói .\nCó tiền là ai , hắn còn không biết sao ?\n“ Cho nên , màn trời nói , đời sau vương triều , những hoàng đế kia từ bỏ một phương ?”\n“ Ân ? Không phải là phía kia a ?”\nNghĩ tới đây , Lưu Triệt có chút hiếu kỳ , cứ như vậy , vương triều còn thế nào cường đại ?\n“ Hơn nữa , người có học thức cũng là không nghiền ép ? Còn có thượng tầng huân quý ?”\n“ Cái kia tiền này đến từ đâu ?”\nLưu Triệt lần này thật sự tò mò , hai phe này có tiền nhất đều không đi nghiền ép , tiền kia đến từ đâu ?\n“ Sẽ không thật đi nghiền ép đám kia quỷ nghèo a ?”\n“ Cái kia có thể nghiền ép đi ra bao nhiêu ?”\n“ Mặc dù là có một chút , nhưng ngươi liền dựa vào tới một điểm này cho vương triều kéo dài tính mạng ?”\nLần này Lưu Triệt thật sự có chút lớn khai nhãn giới , cái này đời sau hoàng đế , làm sao còn như thế kỳ hoa đâu .\nThật sự kỳ hoa , tại Lưu Triệt xem ra .\nCó tiền nhất không đi vơ vét , ngược lại đi vơ vét tầng dưới chót ?\nLưu Triệt lúc này , cũng không dám làm như vậy !\nBởi vì hắn cũng sợ phía trước đánh đang vui , đằng sau lại đột nhiên tạo phản .\nHơn nữa , Lưu Triệt là am hiểu sâu nghiền ép chi đạo .\nMỗi một lần , cũng là từng điểm từng điểm tới , để trên dưới tất cả mọi người đều có thể tiếp nhận .\nDuy nhất một lần toàn bộ nghiền ép đi ra ? Lưu Triệt còn không có như vậy ngu xuẩn !\n...\nĐường triều .\nTrinh Quán bảy năm .\nThời khắc này Lý Thế Dân cũng rất là kinh ngạc nhìn xem màn trời .\nHắn cũng không nghĩ đến , đời sau vương triều lại là bộ dáng như vậy .\nPhải biết , hắn lúc này nghiền ép không được có ít người , thế nhưng là tâm tâm niệm niệm suy nghĩ thật lâu .\nTừ một điểm này tới nói , Lý Thế Dân cũng là có thể sánh ngang Hán Vũ Đế Lưu Triệt .\nHai người đều không khác mấy , nhưng từ nghiền ép chi đạo đến xem , Lý Thế Dân vẫn là không so được Hán Vũ Đế Lưu Triệt .\nHán Vũ Đế Lưu Triệt từ hướng này đến xem , thật sự tính toán các triều đại đổi thay tối cường hoàng đế .\nNhưng Lý Thế Dân cũng không thua kém bao nhiêu .\nBằng không thì Trinh Quán năm đánh nhiều như vậy trận chiến , tiền cũng là vô căn cứ mọc ra ?\nChỉ nói là Lý Thế Dân thủ pháp rất cao minh , hơn nữa không bao giờ làm tát ao bắt cá cái chủng loại kia chuyện .\nHán Vũ Đế Lưu Triệt , vậy thật là có thể cầm tục tính chất tát ao bắt cá .\nCòn vừa vặn kẹt tại ngươi nghĩ phản cùng không muốn trái lại ở giữa .\n...\nTống triều .\nMinh đạo năm đầu .\n“ Kỳ thực màn trời nói rất đúng .”\nLưu Nga đi đến một bước này sau đó , kỳ thực thấm sâu trong người, thấu hiểu rất rõ , bởi vì nàng cũng phát hiện , rất nhiều chuyện kể từ Vũ Tắc Thiên xưng đế sau đó , cũng bắt đầu chậm rãi thay đổi .\nLúc này chỉ có thể nói còn không rõ ràng , nhưng đi đến vị trí này Lưu Nga , cũng đã phát giác .\nGiống như , nàng vĩnh viễn cũng không khả năng lại xưng đế .\nLưu Nga từng tại vào triều lúc hỏi đến quần thần : “ Đường Chi Vũ Hậu là dạng gì nữ chính ?”\nTriều thần trả lời : “ Đường Chi Tội người , kém một chút liền hủy Đại Đường giang sơn xã tắc ”, Lưu Nga nghe xong trầm mặc không nói .\nCho nên , dù là sau đó có ít người khuyên nàng đi “ Vũ Hậu sự tình ”, hiến 《 Vũ Hậu Lâm Triêu Đồ 》, nàng cũng chỉ có thể nói : “ Ta không làm loại này có lỗi với Đại Tống liệt tổ liệt tông chuyện !”\nLấy lời nói thật tới nói , Lưu Nga nghĩ xưng đế sao ? Là nghĩ .\nBằng không thì liền sẽ không có người ám chỉ nàng , hoặc hiến 《 Vũ Hậu Lâm Triêu Đồ 》.\nHơn nữa ngay tại tháng mười một , Lưu Nga cũng sẽ không quyết định xuyên Đế Vương chi phục đi Đại Tống vương triều thái miếu đi tế tự đại điển .\nTừ những sự tình này đến xem , Lưu Nga là nghĩ xưng đế .\nCó thể vì để tránh cho đã có sự tình , sau nhất định lại có xảy ra chuyện như vậy .\nPhía dưới những rất nhiều đám đại thần kia , là tuyệt sẽ không cho phép .\n“ Căn cơ ... Căn cơ ...”\nLưu Nga nhẹ nói cái này , chỉ có thể là lắc đầu thở dài .\n“ Có lẽ , nghĩ xưng đế , tốt nhất lộ , chính là một đường đánh xuống thiên hạ a ...”\nTừ màn trời xuất hiện đến bây giờ , lúc này Lưu Nga , đã phát giác người như nàng , nghĩ xưng đế , thiếu sót nhất là cái gì .\n...\nTống triều .\nMở bảo sáu năm .\n“ Cái này cũng là vì cái gì trước đây những năm kia , như vậy hỗn loạn nguyên nhân a ?”\nNhững người kia cũng giống như thế , trừ mình ra , bình đẳng nghiền ép những thứ khác tất cả mọi người .\n“ Cho nên hỗn loạn một đoạn thời gian rất dài , nhưng cũng đắc tội người quá nhiều .”\nTriệu Khuông Dận cầm bút lông lên , từ từ trên giấy dùng màn trời phương thức viết xuống thế lực bản đồ phân bố .\n“ Dạng này đến xem , bọn hắn cũng không oan , dù sao chỉ có thể nhìn thấy trước mắt ...”\nTriệu Khuông Dận viết lên cái này , thở dài một cái , sau đó không biết nên nói cái gì .\nNhư thế thời đại , hắn thật sự không muốn lại trở về .\nThế gian này tất cả hỏng bét từ ngữ , có thể nói tại trước mặt như thế thời đại , cũng không thể hình dung hắn vạn nhất .\n...\nMinh triều .\nHồng Vũ mười năm .\nCộc cộc cộc đát ...\nChu Nguyên Chương ngón tay đập mặt bàn , cau mày , không biết suy nghĩ cái gì .\nBên cạnh Chu Tiêu , quay đầu nhìn về phía sau lưng bọn đệ đệ , dùng ánh mắt cảnh cáo bọn hắn yên tĩnh .\nLão nhị lão tam một mực tại khiêu khích Chu Lệ , muốn cho hắn giờ phút này nhảy ra , để cho hắn bị mắng .\nNhưng Chu Lệ chỉ là bất đắc dĩ nhìn xem Chu Tiêu .\nLúc này hắn thật sự rất bất đắc dĩ , cái gì đều không có làm , có chút nhãn hiệu liền đã dính vào trên người mình .\n“ Tiêu nhi ...”\n“ Ân ? Phụ thân ?”\nChu Nguyên Chương tức thời phát ra âm thanh .\n“ Có chút chính sách , chính xác thay đổi thay đổi ...”\nChu Nguyên Chương cau mày , hít một tiếng rồi nói ra .\n“ Ta thật là bị có ít người lừa gạt quên hết tất cả .”\nTrước kia Chu Nguyên Chương đúng là có chút xem thường trong lịch sử một ít hoàng đế .\nBởi vì hắn thấy , đây đều là bạo quân , vương triều mặc dù cường đại , thế nhưng không che giấu được hắn bạo quân bản chất .\nNhưng là giống màn trời nói , những cái kia vương triều vì cái gì có thể cường đại như vậy ?\nTỉ như nói , Hán Vũ Đế Lưu Triệt , hắn vì cái gì có thể để cho ngay lúc đó Hán triều như vậy cường đại ?\nĐơn giản nhất một điểm , tiền , đến từ đâu ?\nTrước kia Chu Nguyên Chương không hiểu rõ trong này cấp độ sâu lôgic , nhưng chờ màn trời nói sau đó , hắn mới phát hiện chính mình có bao nhiêu ngu xuẩn .\nVậy mà từ bỏ nhiều như vậy nhân khẩu , lấy một phần nhỏ người , tới phụng dưỡng toàn bộ Đại Minh ?\nDạng này Đại Minh , thật có thể kiên trì sao ?\nNghĩ tới đây , Chu Nguyên Chương nhớ tới trên thiên mạc Lý Ân Phàm , sớm nhất nhìn thấy Doanh Chính lúc , cho hắn ví dụ cái bình trà kia .\nThời điểm đó hắn nói rằng cái chén là căn cơ , nhưng phía dưới cái chén , liền không thể là phụng dưỡng Đại Minh người sao ?\nNếu như cái bình trà kia là Đại Minh ...\nChu Nguyên Chương lúc này sâu đậm thở dài .\nBên cạnh Chu Tiêu , nhưng là nội tâm vô cùng nghi hoặc nhìn phụ thân của mình Chu Nguyên Chương , không biết hắn thế nào .\nPhía sau mấy tiểu chỉ nghe được Chu Nguyên Chương thở dài lại thở dài , thật là một cử động cũng không dám .\n......', 'output\\mp3\\Màn Trời Quyền Lực Diễn Biến Cùng Truyền Thừa\\0049_Thứ 49 chương Cái kia có thể nghiền ép bao nhiêu.mp3', '2026-09-01T13:43:50.829935+00:00', 'completed', 'completed', 7265, 7265),
	(55, 7, '7647642386796921368', 50, 'Thứ 50 chương Không thể bị ngươi Tần Vương tứ tử', 'Thứ chương Không thể bị ngươi Tần Vương tứ tử\nHiện đại thời không .\n“ Chênh lệch thời gian không nhiều lắm , một vấn đề cuối cùng a .”\nLý Ân Phàm gặp dưới đài nhân viên công tác cho đánh hắn một cái động tác , lập tức đối với Trần Xuyên Phú 3 người nhẹ nói .\n“ Vừa vặn , ta cũng chỉ có một vấn đề .”\n“ Vấn đề này ta đã từng suy nghĩ rất lâu , vẫn luôn không nghĩ biết rõ .”\nNgụy Gia cầm ống nói lên , nhìn xem Lý Ân Phàm , sau đó hỏi chính mình vấn đề :\n“ Tần quốc những cái kia lão Tần người , chân chính quyết định từ bỏ Đại Tần , là vào lúc nào ?”\nNghe nói như thế , dưới đài Thủy Hoàng Doanh Chính , còn có Mông Điềm hai người , đều nín thở ngưng thần , chuyên chú nhìn xem Lý Ân Phàm .\n“ Cái này vẫn là để ta tới nói đi .”\n“ Ta đã từng suy nghĩ cẩn thận qua vấn đề này .”\nLý Ân Phàm đầu tiên là uống một hớp nước , thắm giọng cổ họng , sau đó cầm microphone tiếp tục nhẹ nói :\n“ Nói như thế nào đây ? Là muốn phân giai đoạn .”\n“ Người là không thể duy nhất một lần quyết định rời đi người nào đó , hoặc từ bỏ đi một vài thứ .”\n“ Ở phương diện này , đặc biệt là đối với cái loại tổ chức này loại , đoàn thể loại quần thể , càng là như vậy .”\n“ Câu nói này có ý tứ gì ?”\n“ Chính là nếu như ngươi là một người , vậy ngươi hạ xuống quyết định từ bỏ người nào đó , hay là một ít sự vật , có thể chỉ cần trong nháy mắt , một chuyện nhỏ .”\n“ Nhưng đối với quần thể tổ chức cùng đoàn thể tới nói , thì sẽ không , bởi vì bọn hắn chỉ có thể cân nhắc lợi và hại , suy tính được mất .”\n“ Sẽ không đi cân nhắc người nào đó trong nháy mắt tâm tình !”\n“ Từ xưa đến nay , mặc kệ là cái gì đoàn thể cùng tổ chức , cũng là như thế !”\n“ Bọn hắn suy tính , nhất định là cả tổ chức cùng quần thể được mất , đến nỗi nói cho ngươi thấy cái nào đó quần thể người lãnh đạo tâm tình tới làm việc ?”\n“ Đó nhất định là cố ý , hoặc có lẽ là , làm như vậy , đối bọn hắn sau lưng tổ chức , nhất định là được lợi .”\n“ Nhưng nếu quả thật có loại người này đâu ? Ngươi sẽ phát hiện tổ chức như vậy cùng quần thể , nhất định là không thể kéo dài , hoặc chính là trước sân khấu người phát ngôn chẳng mấy chốc sẽ xuống đài .”\nGiải thích xong điểm này , Lý Ân Phàm lại tiếp tục nói :\n“ Cho nên giải được điểm này , chúng ta lại đi nhìn , lão Tần người là lúc nào quyết định từ bỏ Đại Tần ?”\n“ Đáp án này kỳ thực rất đơn giản , chính là Đại Tần thống nhất sáu quốc chi sau .”\n“ Nhưng để cho bọn hắn quyết định từ bỏ Đại Tần , trải qua cái nào mấy cái giai đoạn ?”\nLý Ân Phàm lúc này đứng lên , cầm lấy phấn viết , đi đến bảng đen bên cạnh , nhẹ nhàng viết xuống giai đoạn thứ nhất .\n“ Giai đoạn thứ nhất , thương ưởng biến pháp !”\nÂn ? thương ưởng biến pháp ?\nNghe được cái này , tại chỗ bao quát Doanh Chính cùng Mông Điềm tất cả mọi người , đều nghi hoặc nhìn Lý Ân Phàm .\n“ Có thể có người rất nghi hoặc , vì cái gì thương ưởng biến pháp sẽ để cho lão Tần người thất vọng , sẽ để cho lão Tần lòng người lạnh ngắt , đúng không ?”\nLời này vừa ra , tất cả mọi người ở đây đều khẽ gật đầu một cái .\nBởi vì tại bọn hắn trong nhận thức , thương ưởng biến pháp không phải để cho Tần quốc cường đại , lão Tần người tranh nhau nô nức tấp nập báo danh tham quân sao ?\n“ Đây chính là điển hình bằng vào chúng ta thị giác hiện tại đi đối đãi thương ưởng biến pháp .”\nĐầu tiên là nói một câu như vậy , Lý Ân Phàm sau đó cầm microphone tiếp tục nói :\n“ Chân chính lão Tần người , những cái kia lão Tần người sang tộc , bọn hắn cần thương ưởng biến pháp sao ?”\n“ Vốn là thứ thuộc về bọn họ , thương ưởng biến pháp , đem những vật này thu về , tiếp đó phân cho tầng dưới chót người .”\n“ Sau đó thì sao ? Còn cần cùng những người khác cùng một chỗ tranh .”\n“ Nếu như ngươi là những cái kia lão Tần người sang tộc , ngươi sẽ nguyện ý ?”\n“ Huống chi , Thương Ưởng cuối cùng là chết như thế nào ?!”\nĐúng vậy a , Thương Ưởng cuối cùng là chết như thế nào ? Không phải liền là lão Tần người sang tộc phản công , mới chết sao ?\nTại chỗ rất nhiều người đều lập tức trầm mặc lại .\n“ Hơn nữa , những cái kia lão Tần người sang tộc , bọn hắn nhận những thứ này từ tầng dưới chót từng bước một bò lên người sao ?”\nLý Ân Phàm nói đến đây thời điểm , cười híp mắt nhìn xem mấy người tại chỗ .\nNhận sao ? Tại chỗ rất nhiều người đi nghĩ vấn đề này , sau đó lắc đầu .\n“ Đây chính là giai đoạn thứ nhất .”\n“ Sau đó thời kì ? Lão Tần người sang tộc nhận , bởi vì cái này từ tầng dưới chót lên quân sự quý tộc , dù nói thế nào , cũng là người bản thổ .”\n“ Vì thuận theo thời đại , bọn hắn cũng nhận những thứ này người vì lão Tần người .”\n“ Sau đó thời đại , chính là lão Tần người sang tộc cùng mới quân sự quý tộc dung hợp , từ từ tạo thành tại thời kỳ chiến quốc đặc hữu quân công quý tộc .”\n“ Cái kia giai đoạn thứ hai đâu ? Là lúc nào ?”\nNói đến đây , Lý Ân Phàm quay người tại trên bảng đen viết xuống giai đoạn thứ hai .\n“ Giai đoạn thứ hai , chính là Bạch Khởi cái chết !”\nNghe được Bạch Khởi cái tên này , Doanh Chính lặng yên không tiếng động thở dài một hơi .\nBạch Khởi chết vấn đề , đúng là rất lớn .\nChờ hắn bên trên mặc cho đến vị trí này thời điểm , hắn liền phát hiện , Bạch Khởi tự sát , kỳ thực đối với tần quốc quân công thể hệ đều có nhất định phá hư .\n“ Vì cái gì Bạch Khởi cái chết là giai đoạn thứ hai ?”\n“ Hỏi các ngươi một vấn đề , Bạch Khởi Tại Triệu quốc lừa giết 40 vạn hàng binh sau đó , hắn được cái gì phong thưởng ?”\nÂn ?\nLương Phong nghe được vấn đề này , lập tức có chút mộng , ngoài ra Trần Xuyên Phú cùng Lương Phong hai người cũng là như thế .\nBạch Khởi tại Trường Bình chi chiến sau , được cái gì phong thưởng ?\n“ Cái này ? Không phải được phong hào Vũ An Quân sao ?”\n“ Ta liền biết khẳng định có người biết nói “ Vũ An Quân ”.”\n“ Nhưng rất đáng tiếc , Vũ An Quân phong hào , là Bạch Khởi tại Trường Bình chi chiến phía trước , liền đã có !”\n“ Hơn nữa , có phải hay không còn cảm thấy Bạch Khởi hẳn là đến tần quốc quân công tước hai mươi cấp đỉnh điểm ? Triệt để đợi ?”\n“ Cũng không phải ! Bạch Khởi là 16 cấp , lớn lương tạo .”\n“ Vũ An Quân là đặc thù tước vị , là thời kỳ chiến quốc Tần quốc đặc thù phong hào , địa vị cực cao , tương đương với tước vị cao nhất đãi ngộ .”\n“ Chú ý rồi , tước vị cao nhất đãi ngộ , vẻn vẹn chỉ là đãi ngộ !”\n“ Ngay lúc đó Tần Quốc Phong hầu môn hạm là cực cao , cho thêm thừa tướng hoặc ngoại thích , võ tướng ? Rất khó phong hầu .”\n“ Vì cái gì nói trắng ra lên để cho lão tần nhân quân công quý tộc trái tim băng giá ?”\n“ Liền trái tim băng giá ở đây !”\nLý Ân Phàm lấy tay vỗ vỗ bảng đen , sau đó tiếp tục nói :\n“ Bạch Khởi Trường Bình chi chiến sau , người quá nhiều , muốn nhìn một chút Bạch Khởi đến cùng có thể hay không đến đỉnh , bởi vì tại lúc đó , đếm khắp trước đây Tần quốc , liền không có người có thể so sánh bạch khởi chiến công còn cao , còn lớn hơn .”\n“ Nếu như ngươi là đi quân công thể hệ , ngươi có thể hay không muốn nhìn một chút , Bạch Khởi có thể hay không đến đỉnh ?”\nMuốn biết sao ? Là muốn biết , tại chỗ rất nhiều người đều trầm mặc xuống .\n“ Nhưng Bạch Khởi cuối cùng là cái gì đãi ngộ ?”\n“ Bị truất vì sĩ tốt .”\n“ Sau đó thì sao ? Bị Tần Chiêu Tương vương tứ tử tại Đỗ Bưu , tự vận chết .”\nSau đó , Lý Ân Phàm tiếp tục nói :\n“ Có thể có người biết nói , Bạch Khởi có lẽ chết không oan , bởi vì Tần Chiêu Tương vương để cho hắn tiến đánh Hàm Đan , Nghĩ phái Bạch Khởi làm soái , liên tục gặp hắn cự tuyệt , bởi vậy làm tức giận Tần Chiêu Tương vương .”\nNói đến đây , Lý Ân Phàm gật đầu một cái sau nói đến :\n“ Quả thật là như thế , nhưng mà ...”\n“ Bạch Khởi có thể chết bệnh , có thể chết trận , có thể bị Triệu quốc ám sát mà chết ...”\n“ Những thứ này chết kiểu này , hoặc những thứ khác chết kiểu này đều được .”\n“ Duy nhất , chính là không thể bị ngươi Tần Chiêu Tương vương tứ tử !”\n...', 'output\\mp3\\Màn Trời Quyền Lực Diễn Biến Cùng Truyền Thừa\\0050_Thứ 50 chương Không thể bị ngươi Tần Vương tứ tử.mp3', '2026-09-01T13:43:57.165664+00:00', 'completed', 'completed', 7637, 7637),
	(56, 7, '7648024005370200638', 51, 'Thứ 51 chương Quân công?', 'Thứ chương quân công ?\nHiện đại .\n“ Tứ tử sau đó là ảnh hưởng gì ? Từ phía sau Vương Tiễn hành động đến xem , chúng ta liền biết .”\nCái này ? Trần Xuyên Phú mấy người lẫn nhau liếc nhau một cái , sau đó đều gật đầu một cái công nhận điểm này .\n“ Vì cái gì duy nhất chính là không thể dạng này ?”\n“ Bởi vì rất đơn giản , Bạch Khởi tại lúc đó , có thể nói là quân công thể hệ cọc tiêu .”\n“ Ngươi đem hắn tứ tử , mặc dù từ ngươi Tần Vương góc độ đến xem , là không có vấn đề gì , bởi vì Bạch Khởi kháng mệnh .”\n“ Hơn nữa ngươi Tần Vương còn đưa Bạch Khởi mấy lần cơ hội , Bạch Khởi đều kháng mệnh .”\n“ Từ cái này góc độ đến xem , mặc kệ Bạch Khởi lý do gì , ngươi Tần Vương tứ tử hắn , là không có vấn đề .”\n“ Nhưng cũng vẻn vẹn chỉ là từ ngươi Tần Vương góc độ đi xem .”\nSau đó , Lý Ân Phàm thở dài một hơi sau , tiếp tục nói :\n“ Từ lão tần nhân quân công thể hệ đến xem đâu ? Bọn hắn chỉ có thể nhìn thấy chính mình nhìn thấy .”\n“ Bạch Khởi là thế nào chết ? Bị ngươi Tần Vương tứ tử !”\n“ Đến nỗi Bạch Khởi kháng mệnh ? Không có vấn đề a , vốn là không thể lại đánh , Bạch Khởi cũng là vì Tần quốc , tại sao còn muốn tứ tử Bạch Khởi ?”\n“ Bạch Khởi không phải là công cao chấn chủ , mới bị ngươi Tần Vương tứ tử a ?”\nNói đến đây một câu , dưới đài Thủy Hoàng Doanh Chính khe khẽ lắc đầu , rất là bất đắc dĩ .\nBởi vì hắn cũng chính là thấy được điểm này , mới phát hiện Bạch Khởi cái chết đối với quân công thể hệ đến cùng phá hư lớn bao nhiêu .\n“ Ngươi thừa tướng , còn có ngoại thích , có thể Phong Hầu .”\n“ Mà Bạch Khởi tướng quân đâu ? Trường Bình chi chiến , vì Tần quốc , lừa giết 40 vạn hàng binh , cứ như vậy bị ngươi Tần Chiêu Tương vương tứ tử ?”\n“ Vậy chúng ta quân công thể hệ xuất thân người , còn có cái gì cuối cùng đường ra ?”\n“ Cứ như vậy , đại gia hơi cố gắng một chút , đi đến quân công thể hệ trung tầng , liền dừng lại đi , không có nhất thiết phải đến đằng sau lại đi cố gắng .”\n“ Vương Tiễn vì để tránh cho Bạch Khởi kết cục làm cái gì ? Liều mạng từ ô !”\n“ Vương gia thế lực ngoại lai , đều sợ hãi công cao chấn chủ bị ngươi Tần Vương giết chết ,”\n“ Cái kia bản thổ những người kia đâu ?”\nNói đến đây , Lý Ân Phàm rất là bình tĩnh nói :\n“ Bạch Khởi , khi còn sống , là cọc tiêu .”\n“ Chết ? Hắn cũng là một cái cọc tiêu đứng ở mọi người trong lòng .”\n“ Kết cục ? Kia liền càng là cọc tiêu !”\nNói xong những thứ này , Lý Ân Phàm nói ra sách sử cuối cùng đối thoại lên ghi chép :\n“ Bạch Khởi “ Chết mà không phải là tội lỗi ”, người Tần rất thương tiếc hắn . Tại hắn sau khi chết , hương ấp địa phương đều xây từ tế tự hắn .”\nNghe được cái này , dưới đài Thủy Hoàng Doanh Chính nhắm mắt lại , lắc đầu .\nBên cạnh che yên ổn cũng khó mà nhận ra thở dài một hơi .\nKỳ thực đến hắn một bước này , Bạch Khởi tướng quân kết cục , cũng là tại thời khắc nhắc nhở lấy hắn .\nVương Tiễn lão tướng quân , thì càng không cần nói , càng là như vậy .\n“ Hơn nữa , chúng ta phía trước nói , tại Tần Quốc Phong đợi hơn là người nào ? Thừa tướng cùng ngoại thích .”\n“ Vậy chúng ta lại nhìn , thừa tướng cùng ngoại thích , tuyệt đại đa số là cái gì xuất thân ?”\n“ Bạch Khởi bị ngươi Tần Chiêu Tương vương tứ tử , sợ là ngươi Tần Vương đang liều mạng chèn ép chúng ta lão Tần người , hoặc có lẽ là bản thổ thế lực a ?”\nSau đó , Lý Ân Phàm lại nói tiếp :\n“ Bạch Khởi cái chết , tạo thành ảnh hưởng lớn sao ? Có thể so rất nhiều người tưởng tượng đều lớn .”\n“ Giống như ta phía trước nói , Bạch Khởi tướng quân lớn như vậy công lao , cuối cùng đều không cách nào phong đợi , nhưng ngươi thừa tướng cùng ngoại thích , trên triều đình động động miệng , liền có thể Phong Hầu .”\n“ Vậy chúng ta quân công thể hệ đường ra , đến cùng ở nơi nào ? Đến cùng còn có hay không tất yếu vì quân công đi liều mạng ?”\n“ Coi như liều mạng , cuối cùng là không phải sẽ công cao chấn chủ , bị ngươi Tần Vương giết chết ?”\nNói đến đây , Lý Ân Phàm giơ lên mấy cái ví dụ .\n“ Thương Ưởng Tần Hiếu công hai mươi hai năm ( Phía trước năm ) bởi vì thu phục Hà Tây chi công , phong Triệt để hầu hào Thương quân Thực ấp thương với mười lăm ấp ).”\n“ Ngụy Nhiễm Tần Chiêu Tương Vương cữu , bởi vì bình định Quý Quân Chi loạn cùng nhiều lần phạt sở , công Ngụy có công , phong Nhương hầu Cũng xưng “ Nhương quân ”, nhưng tước vì triệt để hầu ).”\n“ Phạm Sư Tần Chiêu Tương Vương Thân Chính sau tướng quốc , hiến “ Xa thân gần đánh ” Sách , trục “ Bốn quý ”, phong Ứng hầu\nSau đó , Lý Ân Phàm giang tay ra , rất là bất đắc dĩ nói :\n“ Bạch Khởi , công lao đủ lớn a ? Nhưng không có phong đợi , cuối cùng dừng bước 16 cấp , lớn lương tạo .”\n“ Phạm Sư Càng là Bạch Khởi đối thủ một mất một còn , thế nhưng là kết quả đây ?”\n“ Cho nên , nếu như ngươi là quân công thể hệ lão Tần người , ngươi thấy một màn này , sẽ ra sao ?”\n“ Ngoại lai chính là gia ? Ngoại thích chính là gia ? Chúng ta bản thổ lão Tần người đáng chết ? Liền nên vì ngươi Tần Vương kính dâng ?”\nNói xong cái này , Lý Ân Phàm cầm microphone tiếp tục nói :\n“ Chuyện phát sinh sau đó đâu ? Càng làm cho lão Tần lòng người lạnh ngắt .”\nLữ Bất Vi Trợ tử sở ( Tần Trang tương vương ) kế vị , mặc cho tướng quốc , phong Văn Tín Hầu thực ấp Lạc Dương 10 vạn nhà .”\n“ Lao Ái Bởi vì chịu Triệu thái hậu tin mù quáng , tại Tần Vương Chính 8 năm ( Phía trước năm ) phong Trường tín hầu thuộc trường hợp đặc biệt , vô quân công .”\nLý Ân Phàm nói đến Lao Ái , càng là giang tay ra , bất đắc dĩ vừa cười vừa nói :\n“ Tới , ngươi xem một chút , nếu như ngươi là lão Tần người , nghe được Lữ Bất Vi cùng Lao Ái đều phong đợi , ý nghĩ trong lòng ngươi , đến cùng là cái gì ?”\nCái này ? Trần Xuyên Phú mấy người cười khổ lắc đầu .\nCòn có thể là cái gì ? Quân công ? Cái gì quân công ? Hai người này cũng có thể dạng này Phong Hầu , cái kia còn truy cầu cái gì quân công ?\nLiều sống liều chết không thể Phong Hầu , “ Tòng long ” Cùng “ Hãnh tiến ”, vậy mà liền đơn giản như vậy phong hầu ?\nCái kia Bạch Khởi tính là gì ?\nChết ở trên chiến trường những cái kia lão Tần người , đây tính toán là cái gì ?\n“ Đây chính là giai đoạn thứ ba , đối với lão Tần người tổn thương .”\n“ Đặc biệt là Lữ Bất Vi cùng Lao Ái , một cái tòng long liền có thể phong đợi ? Vậy chúng ta đại gia tại sao còn muốn đi trên chiến trường liều chết ?”\n“ Đại gia ủng hộ cái nào đó người thừa kế , chờ lấy Phong Hầu không tốt ? Dạng này Phong Hầu , so trên chiến trường liều chết có thể nói là đơn giản vô số lần .”\n“ Đến nỗi Lao Ái , vậy càng không cần nói , hoàn toàn đem quân công tước thể hệ ném xuống đất tùy ý chà đạp .”\nLý Ân Phàm nói xong cái này , thật sự là không biết nên nói gì .\nNgược lại nếu như hắn là lão Tần người , nhìn thấy Lao Ái đều mẹ nó phong hầu , thật sự cảm thấy Tần quốc không cứu nổi , về sau liều mạng ? Quên đi thôi !\n“ Giai đoạn thứ tư , chính là 《 Gián Trục Khách Thư 》 xuất hiện .”\n“ Phía trước chúng ta nói qua , ngươi Tần Vương mặc kệ là từ cái gì góc độ đến xem , 《 Gián Trục Khách Thư 》 xuất hiện sau đó làm chuyện cũng là không có vấn đề !”\n“ Nhưng lão Tần người ? Bọn họ sẽ không muốn như vậy !”\n“ Toàn bộ nhờ các ngươi những thứ này ngoại lai Tần quốc mới có thể quật khởi mở rộng ?”\n“ Bạch Khởi tướng quân thật sự chết vô ích thôi ?”\n“ Chết ở trên chiến trường , cũng chết vô ích thôi ?”\n“ Các ngươi Tần Vương , xem ra là thật một mực tại chèn ép chúng ta lão Tần người sang tộc , quân công thể hệ quý tộc a ?”\n“ Chúng ta thật sự đáng đời a ?”\nLời mặc dù có một chút như vậy khó nghe , nhưng đạo lý chính là đạo lý kia .\nNhư Trần Xuyên Phú mấy cái người hiện đại , đều thở dài một cái , không biết nên nói cái gì .\n...', 'output\\mp3\\Màn Trời Quyền Lực Diễn Biến Cùng Truyền Thừa\\0051_Thứ 51 chương Quân công.mp3', '2026-09-01T14:16:50.371518+00:00', 'completed', 'completed', 7446, 7446),
	(57, 7, '7648024215932650046', 52, 'Thứ 52 chương Đại thế như thế, đồ chi thế nhưng?', 'Thứ chương Đại thế như thế , đồ chi thế nhưng ?\nHiện đại thời không .\n“ Đến nỗi giai đoạn cuối cùng , để cho những cái kia lão Tần người triệt để trái tim băng giá thất vọng .”\n“ Chính là Tần quốc thống nhất thiên hạ sau đó .”\n“ Những cái kia lão Tần người , thu được cái gì ?”\nLý Ân Phàm trên mặt lộ ra thần sắc nghi hoặc , lập tức chậm rãi nói :\n“ Tầng dưới chót ? Nguyên Tần Quốc tầng dưới chót , thống nhất sau đó , như cũ tại phục lao dịch , như cũ tại tòng quân .”\n“ Cùng thống nhất phía trước , có cái gì khác biệt sao ?”\n“ Trung tầng những cái kia lão Tần người sang tộc ? Thống nhất cái này mấy trăm năm qua , bọn hắn vừa được cái gì ?”\n“ Thống nhất sau đó , trên triều đình đứng , lại là người nào ?”\n“ Chờ đến một bước này , cho dù là lại trung thành lão Tần người , trong lòng đều biết nghĩ một vấn đề !”\n“ Cái này mấy trăm năm qua , chúng ta vì Tần quốc trả giá , đến cùng tại trả giá cái gì ?”\n“ Công ? Không có chúng ta , tên ? Cũng không có chúng ta .”\n“ Đây đều là những cái kia kẻ ngoại lai .”\n“ Chúng ta bản thổ cái này một số người , có phải hay không tại ngươi Tần Vương xem ra , liền nên vì ngươi Tần quốc trả giá ?”\n“ Tầng dưới chót người có lẽ sẽ không như thế nghĩ , nhưng những cái kia lão Tần người sang tộc đâu ? Những cái kia bản thổ đi quân công thể hệ người đâu ?”\nNói đến đây thời điểm , Lý Ân Phàm nhìn về phía Thủy Hoàng Doanh Chính , nhìn hắn con mắt , bình tĩnh nhẹ nói :\n“ Bọn hắn nhìn xem trên đỉnh đầu lít nha lít nhít tuyệt đại bộ phận cũng là người ngoại lai , trong lòng sẽ ra sao ?”\nDưới đài Mông Điềm lặng lẽ nhìn về phía Thủy Hoàng Doanh Chính , phát hiện hắn thủy chung là mặt không biểu tình .\n“ Cái này cũng là ta cho rằng , cuối Tần từ đầu đến cuối tránh không khỏi nguyên nhân .”\n“ Không chỉ là Lục quốc bất mãn , Tần quốc chính mình nội bộ , cũng đồng dạng bất mãn !”\n“ Phân phối lợi ích , quyền lực phân phối , sau khi Tần triều thống nhất , quá dị dạng .”\n“ Dạng này hình quái dị quyền hạn kết cấu , nghĩ lâu dài duy trì ?”\n“ Nguyên Tần Quốc quý tộc , chắc chắn là cái thứ nhất không đáp ứng !”\n“ Tần Thuỷ Hoàng Doanh Chính ở thời điểm , có lẽ còn có thể ép một chút bọn hắn , nhưng chờ Tần Thuỷ Hoàng Doanh Chính đi ?”\n“ Bọn hắn nhất định sẽ trước tiên đoạt quyền !”\nVì cái gì Lý Ân Phàm sẽ nghĩ như vậy ?\nBởi vì hắn thấy , nếu như mình là lão Tần người sang tộc , cũng nhất định sẽ trước tiên chuẩn bị đoạt quyền .\nDựa vào cái gì chúng ta lão Tần người mấy trăm năm mới đánh rớt xuống cơ nghiệp , thống nhất Lục quốc , cuối cùng bị các ngươi những thứ này người ngoại lai cướp trái cây ?\nĐây không phải đối với những cái kia chết trận lão Tần người phản bội ? Đây không phải đối thoại lên tướng quân phản bội ?\nĐến nỗi Tần Vương ? Tần Vương bất công , chúng ta không làm gì được ngươi Doanh Chính , còn không làm gì được ngươi hài tử ?\n“ Nói thật , nếu như là ta , ta có thể rất sớm đã phản .”\nNgụy Gia cầm ống nói lên , hít một tiếng sau , từ từ nói .\n“ Đặc biệt là Bạch Khởi tướng quân sau khi chết , thì càng là như thế .”\n“ Dù là không phản ? Có thể từ đây lui về phía sau liền bắt đầu ngã ngửa .”\n“ Bởi vì đều có thể nhìn ra , ngươi Tần Vương , không phải đang chèn ép chúng ta lão Tần người , là cái gì đây ?”\n“ Mặc kệ là ngoại thích chèn ép , vẫn là ngoại lai thế lực chèn ép , nhưng ngươi Tần Vương một lần lời nói cũng không có vì chúng ta lão Tần người nói qua .”\n“ Dù thế nào trung thành người , đến cuối cùng , đều biết từ từ trái tim băng giá .”\n“ Chờ đến cuối Tần , coi thường Tần triều diệt vong , thì càng là chuyện đương nhiên .”\n“ Ngược lại tùy tiện đổi một người , hẳn là cũng so ngươi Tần Vương tốt a ?”\nTrần Xuyên Phú lúc này cầm ống nói lên , cũng nói tiếp :\n“ Không cam lòng người , tại sau đó đoạt quyền , vừa ý lạnh người đâu ? Tần triều diệt vong quản chúng ta chuyện gì ?”\n“ Đây không phải chúng ta Tần triều !”\nTrần Xuyên Phú cuối cùng mấy câu nói đó nghe tựa hồ rất lạnh lùng , nhưng Lương Phong cùng Ngụy Gia suy nghĩ cẩn thận nghĩ .\nNếu như mình là lão Tần người ? Chỉ sợ thật đúng là như thế .\nHoàn toàn sẽ không nhận dạng này Tần triều là bọn hắn Tần triều .\n...\nHán triều .\nNguyên thú 4 năm .\n“ Đại thế như thế , đồ chi thế nhưng ?”\nDoanh Chính làm có vấn đề sao ? Tại Lưu Triệt xem ra , là làm không có vấn đề gì .\nDù sao cũng thống nhất sáu nước , thành lập Tần triều , còn có thể nói thế nào trong này có những vấn đề khác ?\nChỉ có thể nói , tại trạm Doanh Chính góc độ đi xem , không có vấn đề , tự mình làm hết thảy , cũng là để cho Tần quốc thống nhất Lục quốc .\nNhưng đứng tại lão Tần người góc độ ? Cũng không thành vấn đề , bởi vì đây là bọn hắn tố cầu , đây là Tần quốc mấy trăm năm xuống tích lũy oán khí .\nCho nên chỉ có thể nói đại thế như thế .\n“ Ai ...”\n...\nĐường triều .\nTrinh Quán bảy năm .\n“ Nếu như trẫm thượng vị sau đó , đem đã từng Thiên Sách phủ vứt xuống , đề bạt những người khác , đoán chừng Đại Đường cũng biết sụp đổ a ?”\nLý Thế Dân lúc này trong đầu không hiểu toát ra ý nghĩ này .\n“ Ai , mấy trăm năm xuống , Tần quốc tích lũy oán khí cùng huyết lệ rốt cuộc có bao nhiêu ?”\nThống nhất sau đó đại quy mô đề bạt lão Tần người ? Thế lực ngoại lai , cái kia liền sẽ trước tiên tạo phản .\nNhưng bỏ xuống lão Tần người mặc kệ ? Cuối Tần kết cục đã bày tại trước mắt .\nCái này hoàn toàn chính là hai đầu chắn , Xuân Thu Chiến Quốc cái này mấy trăm năm , Tần quốc tích lũy đồ vật , thật sự nhiều lắm .\nVậy có hay không biện pháp giải quyết đâu ?\nLý Thế Dân nghĩ tới vấn đề này , sau đó liền toát ra đáp án :\n“ Biện pháp giải quyết duy nhất , chỉ sợ sẽ là để cho Đại Tần sĩ tốt một lần nữa quét ngang thiên hạ , làm cho tất cả mọi người thấy rõ ràng thế cục .”\n“ Cũng chỉ có cứ như vậy , tất cả mọi người mới có thể thả xuống một thứ gì đó ...”\n“ Để cho Lục quốc dư nghiệt từ bỏ ảo tưởng không thực tế , để cho Tần quốc lão Tần người sang tộc cắn răng nuốt vào mấy trăm năm Tần quốc huyết lệ ...”\nÂn ?\nNghĩ tới đây , Lý Thế Dân không hiểu nghĩ đến , Tần Thuỷ Hoàng Doanh Chính , không phải là muốn đến một điểm này a ?\nBằng không thì vì cái gì cuối cùng Phù Tô sẽ ở biên cảnh , tay cầm ba trăm ngàn biên quân ?\nHơn nữa , còn đem Mông Điềm phái ở Phù Tô bên người ?\nBiên quân tại phong kiến thời kì , có thể nói là quân đội cường đại nhất , huống chi là 30 vạn ?\nPhải biết từ Tần về sau , có hoàng đế nào , dám để cho chính mình hoàng tử , chạy đến biên cảnh , tay cầm ba trăm ngàn biên quân ?\nLý Uyên cũng không dám làm như vậy !\nLý Thế Dân trên tay là có quân đội , nhưng những này quân đội , cũng là tại Tùy mạt đại loạn thời kì , chính mình từng bước một đánh xuống !\nMà Dương Quảng đâu ? Dù là Dương Quảng tại lúc đó như thế nào được sủng ái , bên cạnh cũng còn có mấy người kiềm chế hắn , chỉ là để cho hắn được một chút tên .\n“ Ba trăm ngàn biên quân a ...”\nNghĩ tới đây , Lý Thế Dân chậc chậc hai tiếng ...\n...\nLớn minh .\nVĩnh Lạc bảy năm .\n“ Như vậy xem ra , Tùy triều cũng gần như chính là như vậy sụp đổ ...”\nChu Cao Sí lúc này chính xác rất có cảm ngộ , rất là cảm khái nói :\n“ Những thứ này lập quốc mấy trăm năm sau lại Thống Nhất Thiên Hạ Vương Triều , vô luận như thế nào đều không thể tránh gặp phải vấn đề này .”\n“ Cho nên cái này cũng là những thứ này vương triều vì cái gì rất nhanh sụp đổ nguyên nhân lớn nhất a ...”\nChu Lệ khẽ gật đầu một cái , công nhận Chu Cao Sí nói điểm này , sau đó chậm rãi nói :\n“ Cát cứ một phương thời điểm , bởi vì có ngoại địch , những người kia là căn cơ .”\n“ Thống nhất sau đó , lại trở thành uy hiếp ?”\n“ Sớm thấy được điểm này , còn không có thống nhất thời điểm liền tiêu diệt , cái kia thống nhất sau đó đâu ? Sẽ cam tâm ?”\nChu Lệ lắc đầu , cảm thấy đây quả thật là thẳng thắn hai đầu chắn .\n“ Nhưng là giống màn trời nói , cái này lại nhất định phải đi làm , bằng không thì vương triều làm sao có thể kéo dài tiếp ?”\n“ Trường Mệnh Vương Triều , cơ hồ cũng là tại thống nhất sau đó trước tiên liền tiêu diệt cái này một số người .”\n“ Nhưng những cái kia cát cứ mấy trăm năm các nước chư hầu đâu ?”\nChu Lệ nghĩ tới đây , thật sự là không biết nên như thế nào mới có thể để cho dạng này vương triều sống còn tiếp .\n......', 'output\\mp3\\Màn Trời Quyền Lực Diễn Biến Cùng Truyền Thừa\\0052_Thứ 52 chương Đại thế như thế, đồ chi thế nhưng.mp3', '2026-09-01T14:16:58.760236+00:00', 'completed', 'completed', 7997, 7997),
	(58, 7, '7648443433740141080', 53, 'Thứ 53 chương Còn có thể cứu sao?', 'Thứ chương Còn có thể cứu sao ?\nHiện đại thời không .\n“ Cho nên cuối Tần thật sự cũng không cứu sao ?”\nNgụy Gia nhìn xem Lý Ân Phàm cùng Trần Xuyên Phú hai người , hỏi chính mình rất sớm đã muốn hỏi vấn đề .\n“ Nói thật , ngươi vấn đề này quá lớn ! Từ vẻn vẹn có sách sử tư liệu đi xem , tựa hồ cuối Tần còn có thể cứu .”\n“ Nhưng thực tế tình huống , Tần triều thống nhất đến Tần triều diệt vong , cái này trong thời gian mười lăm năm , đến cùng xảy ra chuyện gì ?”\n“ Tình huống cụ thể , đến cùng là dạng gì ? Bây giờ ai cũng không biết .”\n“ Ngươi để cho ta nói cuối Tần thời kỳ Tần triều , còn có hay không cứu ?”\n“ Vẻn vẹn từ góc độ của ta đến xem , thật sự rất khó cứu .”\n“ Mặc kệ là từ mỗi phương diện đến xem , thật sự rất khó cứu .”\nTrần Xuyên Phú cầm microphone , lúc này ngữ khí vô cùng bất đắc dĩ .\n“ Hiểu rõ càng nhiều , ngươi liền sẽ phát hiện một sự kiện , nghĩ tại cuối Tần cứu Tần triều , thật là vô cùng vô cùng khó khăn .”\n“ Nhìn chung trong lịch sử phía dưới năm ngàn năm , có thể nói khó khăn như vậy xếp hạng trước ba .”\n“ Bởi vì đây quả thật là các cấp độ tầng đều không thỏa mãn thống nhất sau đó Tần triều hiện trạng .”\n“ Thống nhất sau đó , tầng dưới chót hài lòng không ? Có người nhất định sẽ nói , tầng dưới chót là hài lòng , bởi vì không có chiến loạn .”\n“ Nhưng lao dịch , nghĩa vụ quân sự các loại , vẫn như cũ vẫn tồn tại ! Còn nhớ rõ chúng ta khám phá Hắc Phu cùng kinh hãi thư nhà sao ?”\n“ Cái này hai lá viết tại Mộc Độc Thượng tin từ binh lính quân Tần Hắc Phu cùng kinh ở trước công nguyên năm Tần diệt Sở trong lúc chiến tranh viết cho trong nhà huynh trưởng , nội dung chủ yếu là Hướng trong nhà đòi tiền muốn quần áo Đồng thời hỏi thăm tước vị trao tặng tình huống .”\n“ Mà trong thư cụ thể đến cùng nói cái gì ?”\n“ Hai huynh đệ tại Hoài Dương tiền tuyến đánh trận , quần áo phá , tiêu sạch , trong thư nhiều lần thúc dục trong nhà gửi quần áo mùa hè cùng tiền , thậm chí dùng Vội vã cấp bách Dạng này chữ , còn nói nếu là trong nhà không gửi tiền tới , “ Tức tử rồi ” ( Liền phải chết ).”\n“ Thống nhất sau đó , Kết thúc rồi sao? ?”\nTrần Xuyên Phú nhìn xem mấy người , hỏi vấn đề này .\nKết thúc sao ?\nKhông có ! Vẫn không có kết thúc ! Xuôi nam , Bắc thượng , đều còn tại không ngừng đánh trận .\n“ Cho nên , thống nhất sau đó , cùng thống nhất phía trước , khác nhau ở chỗ nào ?”\n“ Thời điểm đó đánh trận cũng không phải bây giờ , binh sĩ đi quân đội , quân đội toàn bao , còn gửi ngươi tiền lương .”\n“ Tầng dưới chót binh sĩ , liền thật sự nguyện ý không ngừng đánh trận ? Vì một cái không thể so sánh tước vị mộng ?”\n“ U mê binh sĩ có khả năng một chút còn nguyện ý liều chết , nhưng hơi hiểu một điểm , vẫn là chúng ta phía trước nói , nhìn xem trên đầu kia quan to quan nhỏ , cùng với Tần quốc cái này mấy trăm năm xuống cánh tay kia đều đếm ra triệt để đợi .”\n“ Bọn hắn liền thật sự nguyện ý ly biệt quê hương đánh trận , tiếp đó chết ở một cái không biết tên xó xỉnh ?”\nNói đến đây , Trần Xuyên Phú hít một tiếng , trong loa rất rõ ràng truyền ra một tiếng kia thở dài .\n“ Ta biết , bây giờ rất nhiều người đều cho rằng , Tần quốc thương ưởng biến pháp sau đó , quân công tước chế sinh ra , để cho Tần quốc tầng dưới chót tất cả dân chúng mừng rỡ như điên , tất cả mọi người đều nô nức tấp nập tham quân .”\n“ Nhưng đây chỉ là lý tưởng nhất trạng thái .”\n“ Về sau Vô Số Vương Triều , bọn hắn cũng không có đem quân công tước chế vứt bỏ , nhưng vì cái gì tầng dưới chót đối với nghĩa vụ quân sự trốn chi không bằng ?”\nSau đó , Trần Xuyên Phú dừng lại một chút , lại tiếp tục nói :\ntuổi đăng ký phục dịch tuổi miễn dịch .”\n“ Đánh mấy trăm năm , người nào không biết đến cùng là gì tình huống ?”\n“ Vì cái gì chúng ta bây giờ bình luận thương ưởng biến pháp quân công tước chế , cho ra đánh giá là kích phát binh sĩ chiến đấu tính tích cực ?”\n“ Chiến đấu tính tích cực ....”\n“ Vốn chính là toàn dân giai binh , thống nhất sau đó , vẫn không thay đổi ...”\nNói đến đây , Trần Xuyên Phú thật sự bất đắc dĩ lắc đầu , không biết nên nói cái gì .\n“ Ta trước đó nghe qua một loại luận điệu , nói Tần triều diệt vong , là bởi vì quân công tước chế sụp đổ , bởi vì không có trận chiến có thể đánh , tầng dưới chót không có lên cao đường dây .”\nLúc này , Lương Phong mở miệng , nói đến rất sớm phía trước , chính mình không biết ở đâu thấy qua một loại luận điệu .\nNghe xong hắn lời nói , Lý Ân Phàm cầm ống nói lên , nhẹ nói :\n“ Kỳ thực ta trước đó cũng cho là như vậy .”\n“ Nhưng sau đó giải được , loại thuyết pháp này kỳ thực là sai lầm , ngay lúc đó Tần triều , phía bắc , phía nam , kỳ thực đều còn tại đánh trận .”\n“ Muốn dựa vào quân công tước chế trèo lên trên , kỳ thực tại lúc đó , là không thiếu trận chiến đánh .”\n“ Cho dù là đối với quân công tước phong thưởng ? Cũng là không thiếu , thống nhất sau đó , Lục quốc thổ địa cũng có thể phong thưởng .”\n“ Chờ ta ra xã hội , kinh nghiệm nhiều hơn , nhìn sách nhiều sau đó , liền phát hiện một chuyện .”\n“ Tầng dưới chót bên trong , khát vọng trèo lên trên , kỳ thực rất ít .”\n“ Càng nhiều , kỳ thực là nghĩ an ổn sinh hoạt .”\nSau đó , Lý Ân Phàm nói ra chính mình lý giải :\n“ Hán triều vì cái gì có thể như thế ổn định ? Bởi vì phía trước mấy đời hoàng đế , dùng Hoàng lão , nghỉ ngơi lấy lại sức , làm thật quá tốt rồi .”\n“ Có thể nói , tại lúc đó , tầng dưới chót đối với cách làm như vậy , cũng là vô cùng hài lòng .”\nLúc này , Trần Xuyên Phú tiếp nhận Lý Ân Phàm mà nói , tiếp tục nói :\n“ Tầng dưới chót nói xong , chúng ta lại đến nhìn trúng tầng cùng cao tầng .”\n“ Lục quốc những cái kia dư nghiệt , có tính không trung tầng cùng cao tầng ? Là tính toán !”\n“ Lão Tần người sang tộc đâu ? Có tính không ? Đương nhiên cũng là tính toán .”\n“ Cho nên , chúng ta nhìn lúc đó Tần triều các cấp độ cấp hình thức , ngoại trừ lúc đó trên triều đình , đã tay cầm quyền hạn , ăn vào đại lượng lợi ích người , ngay lúc đó Tần triều , có bao nhiêu hài lòng ?”\n“ Ngoại trừ thống nhất thời kì , thu được đại lượng công lao những người kia hài lòng , những người khác ? Đại bộ phận nhất định là bất mãn .”\n“ Tần Nhị Thế có thể xuất hiện tình huống như vậy , bản thân đã nói lên Tần triều nội bộ cực lớn bất ổn .”\n“ Trong mắt của ta , đây không phải đem Tần triều diệt vong oa , chụp tại trên người mấy người , liền có thể xong việc .”\n“ Nhìn chung các triều đại đổi thay thời kì cuối , Tần triều chỉ tồn tại mười lăm năm ? Liền đã rất thuyết minh vấn đề .”\n“ Cái này mười lăm năm , còn không có một chút vương triều thời kì cuối dài !”\n“ Đại Đường loạn An Sử sau , tồn tại bao lâu năm !”\n“ Kém một chút chính là gấp mười lần so với Tần triều ! Cái này còn không có thể nói rõ một vài vấn đề sao ?”\nNgụy Gia lúc này lại cầm ống nói lên , nhìn xem Trần Xuyên Phú , nhẹ giọng dò hỏi :\n“ Nói như vậy tới , ngay lúc đó Tần triều mỗi giai cấp đều có cực lớn mâu thuẫn , thật sự không cứu nổi sao ?”\nNghe được vấn đề này , Lý Ân Phàm lắc đầu nhẹ nói :\n“ Theo ta thái độ tới nói , vẫn có một ít cứu .”\n“ Thống nhất sau đó , nghỉ ngơi lấy lại sức , không cần như vậy giằng co , để cho tầng dưới chót trước tiên an ổn xuống .”\n“ Đến nỗi trung tầng cùng cao tầng ? Chậm rãi đi đấu !”\n“ Hán triều chính là như vậy , nghỉ ngơi lấy lại sức , ảnh hưởng tới chính trị đấu tranh sao ? Ảnh hưởng tới bài trừ đối lập sao ?”\n“ Không có ảnh hưởng !”\n“ Liền an an ổn ổn truyền hai đời thứ ba , lại đi làm khác đại chiến lược chuyện .”\n“ Cũng chính là dạng này , Tần triều có lẽ còn có một số cơ hội , có thể sống sót .”\n“ Đến nỗi có thể sống bao lâu ? Như thế nào hẳn là cũng so mười lăm năm nhiều hơn a ?”\n“ Chiến quốc đánh mấy trăm năm , tầng dưới chót thật là quá mệt mỏi ...”\nLý Ân Phàm nghĩ đến thời kỳ đó , chiến quốc kết thúc , lại không ngừng lên ngựa đủ loại công trình , lao dịch , nghĩa vụ quân sự cái gì đều không ngừng .\nPhía bắc , phía nam , vẫn như cũ chuẩn bị tiến công .\nNghĩ tới những thứ này , Lý Ân Phàm đều cảm thấy mệt mỏi , chớ nói chi là ngay lúc đó tầng dưới chót .\n“ Hơn nữa Hán Vũ Đế thời kì , đánh Hung Nô xuất động bao nhiêu người ?”\n“ Mạc bắc chi chiến ( Phía trước năm Vệ Thanh , Hoắc Khứ Bệnh đem vạn kỵ binh bàn bạc vạn tinh duệ kỵ binh khác điều động Mấy chục vạn bộ binh cùng vạn con chiến mã Phụ trách hậu cần cùng kiềm chế .”\n“ Mông Điềm ngăn cản Phù Tô tự sát thời điểm là thế nào nói ?”\n“ Mông Điềm : Bệ hạ bây giờ bên ngoài , còn chưa lập Thái tử , phái ta suất lĩnh 30 vạn đại quân trấn giữ biên cương , để cho công tử ngươi tới giám sát , đây là quan hệ thiên hạ an nguy nhiệm vụ trọng đại ! Bây giờ chỉ vì một cái sứ thần đến , ngươi liền nghĩ tự sát , ngươi làm sao biết đây không phải gian trá quỷ kế đâu ? Ta thỉnh cầu ngươi một lần nữa đi xin ý kiến một chút , chờ xin chỉ thị sau đó lại chết cũng không muộn !”\n“ Ba trăm ngàn biên quân , thoạt nhìn là giống như vô cùng cường đại , nhưng hậu cần đâu ?”\n“ Đối với áp lực của quốc nội đâu ?”\n“ Rất nhiều người thật sự không có nghĩ qua vấn đề này ! Tựa hồ 30 vạn người không ăn không uống , liền có thể tại biên cảnh một mực trông coi !”\n......', 'output\\mp3\\Màn Trời Quyền Lực Diễn Biến Cùng Truyền Thừa\\0053_Thứ 53 chương Còn có thể cứu sao.mp3', '2026-09-01T14:17:04.350588+00:00', 'completed', 'completed', 8906, 8906),
	(59, 7, '7648444251637809688', 54, 'Thứ 54 chương Ai có thể nghĩ đến đời tiếp theo đâu?', 'Thứ chương Ai có thể nghĩ đến đời tiếp theo đâu ?\nHiện đại thời không .\n“ 30 vạn biên quân ...”\nNghĩ đến cái này con số , Trần Xuyên Phú cũng không biết nên nói như thế nào .\nCái số này , thật sự không biết nên đối với Tần triều có bao nhiêu áp lực .\nHơn nữa , phía nam tại lúc đó , cũng là không ngừng .\n“ Đúng a , 30 vạn đại quân hậu cần , Phù Tô không đánh lại , hẳn là bởi vì cái này a ?”\nNgụy Gia lúc này hơi kinh ngạc .\n“ Cái này kỳ thực không có ảnh hưởng gì ! Đánh lại , cùng đánh đi ra , là khác biệt !”\n“ Đánh đi ra , ngươi muốn tìm Hung Nô , vậy thì cần một mực dựa vào sau hậu cần đến cấp ngươi truyền máu .”\n“ Đến nỗi đánh lại ? Phù Tô mang theo 30 vạn đại quân , quang minh cờ hiệu , hậu cần thì sẽ không thiếu .”\nTrần Xuyên Phú lắc đầu , bác bỏ Ngụy Gia ý nghĩ .\n“ Điểm này chính xác , Phù Tô mang theo 30 vạn đại quân , đánh đi ra cùng đánh lại , đánh lại độ khó có thể nói thấp đến không cách nào tưởng tượng .”\n“ Dù là Hồ Hợi thật là Thủy Hoàng Đế Doanh Chính di chiếu ngồi trên hoàng vị .”\n“ Phù Tô nếu là có can đảm tử đánh lại , trực tiếp quang minh cờ hiệu , phát hịch văn , nói Hồ Hợi đổi di chiếu soán vị là được rồi .”\n“ Dù sao một cái là tham chính đại công tử , một cái là Thập Bát công tử , ngươi là bản xứ quan viên , ngươi nhận cái nào ?”\n“ Liền không nói nhận cái nào , ngươi thường xuyên nghe được là cái nào ? Còn cần nhiều lời sao ?”\n“ Huống chi , tay cầm 30 vạn biên quân , chỉ cần là người thông minh , liền nên biết đến cùng ai là người thừa kế .”\n“ Cho nên có hay không hậu cần , đối với ngay lúc đó Phù Tô tới nói , thật sự ảnh hưởng không lớn .”\n“ Trông chừng mà hàng , có thể đều tương đối dễ dàng xuất hiện .”\n...\nĐường triều .\nTrinh Quán bảy năm .\n“ 30 vạn biên quân ?”\nLý Thế Dân lắc đầu nhẹ giọng thì thầm một chút cái số này .\nNghĩ đến trước đây chính mình nếu là có ba trăm ngàn biên quân , còn cần phiền toái như vậy sao ?\n30 vạn biên quân nơi tay , hơn nữa còn tọa trấn biên quân .\nĐây là cái gì thiên Hồ ?\nDám để cho chính mình tự vẫn ? Đây là cái nào nghịch thần tặc tử mở trẫm nói đùa ?\n“ Ai ... Phù Tô , chính xác rất đáng tiếc ...”\nNhìn lâu như vậy màn trời , Lý Thế Dân cũng không có phía trước đối với Phù Tô khinh thị .\nChỉ có thể nói thời đại như thế ...\nMẫu thân , mẫu tộc , Doanh Chính thời khắc không vui ...\nCuối cùng mới tạo thành như thế bi kịch , để cho Phù Tô không chùn bước tự vẫn .\nNếu như mình đã trải qua Phù Tô hết thảy , còn sẽ có như bây giờ cách nhìn sao ?\nNghĩ tới đây , Lý Thế Dân rất quả quyết lắc đầu nói :\n“ Không có , có thể vẫn là sẽ cùng Phù Tô một dạng a ...”\nDù sao trước đây thời đại ảnh hưởng , còn có phía trước mấy chục năm kinh nghiệm , mới tạo thành bây giờ Lý Thế Dân .\n...\nHán triều .\nNguyên thú 4 năm .\n“ Cuối Tần ...”\nNghĩ đến cuối Tần mâu thuẫn như vậy , tạo thành cái kia phá hư cực lớn độ chấn động , Lưu Triệt nói thật , cũng không cho rằng Tần triều nếu như không có Hồ Hợi , có thể an ổn truyền thừa xuống .\nChỉ có thể nói nhiều nhất lại truyền mấy thập niên .\nSau đó sao ? Cuối Tần vẫn như cũ sẽ diễn ra .\n“ Chờ đã ...”\nĐột nhiên , Lưu Triệt tựa hồ nghĩ tới điều gì , trên mặt lộ ra thần sắc bất khả tư nghị , đột nhiên ngẩng đầu nhìn về phía màn trời .\nHắn có một cái rất đáng sợ ngờ tới .\n“ Cuối Tần to lớn như vậy mâu thuẫn cùng chiến tranh độ chấn động , cái kia Thái tổ là thế nào ...”\n...\nMinh triều .\nVĩnh Lạc bảy năm .\n“ Lão đại , ngươi nói , nếu là Tần triều thống nhất sau đó , nghỉ ngơi lấy lại sức , có thể an ổn truyền thừa xuống sao ?”\nChu Lệ thoải mái nhàn nhã nhìn xem bên cạnh Chu Cao Sí .\n“ Ta không cho là như vậy , phụ thân .”\n“ Tối đa chỉ có thể lại truyền mấy thập niên a ?”\nSau đó , Chu Cao Sí suy nghĩ cẩn thận nghĩ , sau đó lại lắc đầu tiếp tục nói :\n“ Có thể nhiều nhất lại mười mấy năm ...”\n“ Những người kia sẽ không cam lòng !”\n“ Màn trời người kia kỳ thực còn có một số lời nói không nói , nhưng ta biết hắn là có ý gì .”\n“ Đổi hoàng đế , coi như phía trước ban bố chính sách là khai quốc hoàng đế thì thế nào ?”\n“ Mâu thuẫn kỳ thực để ở nơi đó , Lục quốc dư nghiệt , lão Tần người sang tộc vân vân người , bọn hắn liền thật sự cam tâm ?”\n“ Coi như Hồ Hợi là minh quân , có thể làm tốt một cái Thái Tông .”\n“ Cái kia đời tiếp theo đâu ?”\n“ Hạ hạ một nhiệm kỳ đâu ?”\n“ Lịch sử đã vô số lần biểu diễn chuyện như vậy , phụ thân .”\nChu Cao Sí đối với cái này nhìn rất nhiều rõ ràng , dù sao Vĩnh Lạc hướng thân ở lịch sử hạ du , bọn hắn trước đây triều đại nhiều lắm .\nLiền nói Đường triều , Đường Thái Tông Lý Thế Dân làm được rồi ? Đường Cao Tông Lý Trị cũng còn có thể ? Sau đó thì sao ?\nBa một cái , chẳng ai ngờ rằng , Võ Tắc Thiên xưng đế , đổi tuần !\nTrừ cái đó ra , liền không nói xa , liền bọn hắn lớn minh .\nGia gia làm tốt như vậy , nhưng Chu Doãn Văn thượng vị sau đó đâu ? Đẩy ngã bao nhiêu ?\nCho nên , Tần triều có thể hay không giống đời sau vương triều như thế truyền thừa mấy trăm năm ?\nKhó khăn , thật là quá khó khăn .\nKhông đem những vấn đề kia giải quyết , Tần triều vấn đề , sớm muộn đều biết bộc phát .\n“ Hơn nữa , nói như thế nào đây ? Tần triều cho ta cảm giác ...”\n...\nHiện đại thời không .\nBan đêm .\n“ Tần triều cho ta cảm giác , giống như là đem Xuân Thu Chiến Quốc rất nhiều mâu thuẫn đều tích lũy xuống ...”\nMang theo Thủy Hoàng Doanh Chính cùng Mông Điềm đi ở vùng ngoại ô trên đường , Lý Ân Phàm rất là cảm khái nói .\n“ Tiếp đó , một lần duy nhất dẫn bạo ...”\n“ Liền nói đơn giản nhất , Tần quốc đối với Triệu quốc cừu hận ? Triệu quốc đối với Tần quốc cừu hận ? Giữa các nước cừu hận ?”\n“ Liền cái này đơn giản cừu hận , cũng có thể làm cho các ngươi vô cùng đau đầu .”\nXuân Thu Chiến Quốc mấy trăm năm xuống , giữa các nước tính tổng cộng cừu hận có bao nhiêu ? Ai cũng không biết .\n“ Hơn nữa , cừu hận này tùy thuộc còn không hết là cao tầng , còn có tầng dưới chót , đây mới là phiền toái nhất .”\n“ Liền nói như thế nào tiêu trừ Triệu quốc con dân đối với Tần quốc cừu hận , trong mắt của ta đều vô cùng khó khăn .”\nCho nên , Lý Ân Phàm mới phát giác được Tần triều thật sự nghĩ an ổn truyền thừa xuống ? Thật sự quá khó khăn .\nCái này còn không phải là hậu thế loại kia đơn giản địa vực kỳ thị .\nMà là chân thật , đả sinh đả tử mấy trăm năm cừu hận !!!\n“ Tiên sinh , vậy tại sao về sau Hán triều , chưa từng xuất hiện loại tình huống này đâu ?”\nĐi ở một bên Mông Điềm , nghĩ tới điểm này , quay đầu nghi ngờ hỏi Lý Ân Phàm .\n“ Thủy Hoàng nhìn sách sử , hẳn là tinh tường a ?”\nLý Ân Phàm không có trả lời , mà là nhìn về phía Doanh Chính .\n“ Lại chiến loạn mười mấy năm ...”\n“ Hơn nữa là Hán , không phải Tần ...”\nNghe nói như thế , Mông Điềm bừng tỉnh đại ngộ .\nĐúng vậy a , sau tới là Hán , không phải Tần ...\nKhông phải thời kỳ chiến quốc , bảy quốc chi ở giữa tùy ý một cái .\nVậy cái này ở đâu ra cừu hận đâu ?\nMông Điềm là thật là không nghĩ tới , đáp án vậy mà đơn giản như vậy .\n......', 'output\\mp3\\Màn Trời Quyền Lực Diễn Biến Cùng Truyền Thừa\\0054_Thứ 54 chương Ai có thể nghĩ đến đời tiếp theo đâu.mp3', '2026-09-01T14:17:10.269625+00:00', 'completed', 'completed', 6771, 6771),
	(60, 7, '7648575871657198104', 55, 'Thứ 55 chương Quá độ chương tiết 1', 'Thứ chương Quá độ chương tiết\nHiện đại thời không .\nBan đêm .\n“ Chỉ những thứ này , Thủy Hoàng .”\nVùng ngoại ô một chỗ trong kho hàng , Lý Ân Phàm nhìn xem trong kho hàng chất đống rậm rạp chằng chịt đồ vật .\n“ Cái này .. Này ... Cái này ...”\nMông Điềm trợn mắt hốc mồm nhìn một màn trước mắt .\nHắn cho là Lý Ân Phàm đưa cho bọn họ , chỉ có rất ít đồ vật , nhưng trước mắt một màn , phá vỡ ý nghĩ như vậy .\n“ Đây là sách , đây là thuốc , đây là một chút công cụ ...”\nLý Ân Phàm nhìn xem giấy niêm phong bên trên viết chữ , từng cái cho Thủy Hoàng Doanh Chính cùng Mông Điềm giới thiệu .\n“ Đúng , Thủy Hoàng ...”\nLúc này , Lý Ân Phàm nhớ tới tiết mục thu sau khi kết thúc , trong đầu hệ thống đối với hắn nói lời .\n“ Cái ... Cái gì ? Tiên sinh ...”\nThủy Hoàng Doanh Chính lúc này tựa hồ còn có một số chưa có lấy lại tinh thần , có chút mộng hỏi Lý Ân Phàm .\n“ Ngươi có thể lựa chọn 10 người , đem bọn hắn đưa đến ta chỗ này , tới tiếp thu hiện đại giáo dục .”\n“ Chờ bọn hắn học tập xong sau đó , lại trở về trợ giúp Đại Tần .”\nĐây là hệ thống đánh miếng vá .\nDù sao chỉ những thứ này đưa cho Đại Tần đồ vật , nếu như không có người dạy dỗ mà nói , Đại Tần có thể nói thật sự không có một người sẽ .\nCho dù là đọc sách tìm tòi ? Vậy phải thời gian cũng quá lâu .\nBên kia thật sự là nhìn tiếp tục như vậy quá chậm , trực tiếp đánh một cái miếng vá .\nCũng là tác giả đánh một cái miếng vá a , dù sao không có người dạy mà nói , hiện đại rất nhiều đồ vật đưa đến cổ đại , vậy thật cùng đổ xuống sông xuống biển không có gì khác biệt , dù là có sách , cũng không hiểu y nguyên vẫn là sẽ không hiểu . Nếu như đọc sách đều có thể nhìn sẽ ? Vậy thế giới này bên trên cũng không cần lão sư .)\n“ Thật sự ?!”\nMông Điềm nghe xong Lý Ân Phàm lời nói , rất là ngạc nhiên nhìn xem hắn .\n“ Đúng vậy , 10 người ! Hơn nữa sau đó , mỗi một cái nguyệt , các ngươi có thể phái người tới hiện đại mua sắm một lần .”\n“ Đương nhiên , về sau liền cần lấy vật đổi vật .”\nLý Ân Phàm cầm điện thoại di động , nhìn xem buổi chiều phát cho hắn tin nhắn đối với Doanh Chính nói .\nDù sao cùng bên kia cũng đã sinh ra ăn ý , Lý Ân Phàm cũng liền không quan trọng .\nHơn nữa muốn để cổ đại đi con đường khác nhau , chắc chắn là muốn đại quy mô trợ giúp cổ đại .\nNhưng các triều đại đổi thay nhiều như vậy , hiện đại cũng không có bồi thường trợ giúp mà nói , sớm muộn phải phá sản .\n“ Tiên sinh , như thế nào cái lấy vật đổi vật ?”\nMông Điềm đi đến Lý Ân Phàm bên người , nhẹ giọng hỏi .\n“ Đằng sau có người cùng các ngươi đối tiếp , ta liền mặc kệ chuyện này .”\nThủy Hoàng Doanh Chính gật đầu một cái .\nLúc này , Lý Ân Phàm giơ tay lên , trước mặt xuất hiện một cánh cửa ánh sáng .\nHệ thống , quang môn lại phóng đại gấp mười .】\nTrong đầu đối với hệ thống nói xong , Lý Ân Phàm nhìn xem dần dần biến lớn cánh cửa ánh sáng , quay đầu đối với Doanh Chính nói :\n“ Thủy Hoàng , để cho người ta tới khuân đồ a .”\n“ Mông Điềm !”\n“ Ừm , bệ hạ !”\nMông Điềm chắp tay thi lễ một cái , sau đó đi vào quang môn .\nDoanh Chính ngay ở chỗ này an tĩnh bồi tiếp Lý Ân Phàm .\n‘ 10 người Yêu ?’\nLý Ân Phàm buổi chiều thu đến tin tức này thời điểm , còn rất nghi hoặc , tại sao là mỗi cái triều đại là 10 người ?\nBây giờ vừa nghĩ đến , 10 người sẽ không đối với Tần triều tư tưởng sinh ra ảnh hưởng to lớn .\nNếu quả thật không hạn chế nhân số , để cho cổ nhân tới hiện đại học tập ?\nSau cái kia Tần triều , nhất định sẽ từ từ cùng hiện đại cùng đường .\nĐây không phải hiện đại mong muốn ! Cũng không phải hệ thống bên kia mong muốn !\nHơn nữa , không hạn chế nhân số , nên lo lắng có lẽ cũng không phải hiện đại , lo lắng chính là những cái kia có thể tới Hiện Đại Vương Triều .\nCó mưu đồ khác bốn chữ này , nhất định sẽ khắc vào trên Lý Ân Phàm sọ não .\n“ Bệ hạ !”\nLúc này , một cái mặc có chút nho nhã nam tử , mang theo mấy trăm sĩ tốt , xuyên qua quang môn , đi đến Thủy Hoàng Doanh Chính trước mặt , cung kính hành lễ .\n“ Ai ...”\nNhìn người trước mắt này , Thủy Hoàng Doanh Chính khẽ thở dài một hơi , sau đó quay đầu đối với Lý Ân Phàm nói :\n“ Tiên sinh , trước tiên định một người a .”\n“ Ân ?”\nLý Ân Phàm nháy nháy mắt , nội tâm đoán được , đây sẽ không là Phù Tô a ?\n“ Để cho các sĩ tốt đi chuyển a !”\n“ Ừm !”\nNho nhã nam tử quay người bắt đầu phân phó sĩ tốt .\n“ Thủy Hoàng , đây là Phù Tô ?”\n“ Ân .”\nNghe được Lý Ân Phàm vấn đề , Doanh Chính khẽ gật đầu một cái .\n‘ Cái này cũng ...’\nLý Ân Phàm thật sự là không nghĩ tới , cái này thật đúng là là Phù Tô .\nHơn nữa , hai cha con này ở giữa , có phải hay không có chút quá xa lạ ?\nNghĩ đến tình cảnh mới vừa rồi , Lý Ân Phàm chỉ có thể nói hai chữ : Khó trách ...\nGiữa hai người này , thật là giống quân thần giống hơn là phụ tử .\nCũng không biết qua bao lâu , chờ trong kho hàng hàng hóa từ từ giảm bớt , đám người cũng từ từ thưa thớt sau đó , Doanh Chính nhẹ giọng đối với Lý Ân Phàm nói :\n“ Tiên sinh , vậy chúng ta liền lần sau gặp lại .”\n“ Hảo , Thủy Hoàng .”\nSau đó , Thủy Hoàng Doanh Chính đi từ từ hướng quang môn .\nChờ lại cũng không nhìn thấy sau đó , Lý Ân Phàm trong đầu đối với hệ thống nói :\nĐóng lại quang môn a .】\nChỉ thấy quang môn chậm rãi tiêu thất , trong kho hàng , cũng chỉ có Lý Ân Phàm một người .\n“ Không can thiệp , tùy tiện bọn hắn sử dụng như thế nào sao ? Này liền thật sự hoàn toàn nhìn những hoàng đế kia đến cùng là nghĩ gì ...”\n“ Dùng phương pháp như vậy , tới tìm tòi đường sau này ...”\nLý Ân Phàm hướng về phía trống trải thương khố , nhẹ giọng thì thầm vài câu .\nSau đó lắc đầu , Lý Ân Phàm đưa tay liếc mắt nhìn bày tỏ .\n“ Cần phải trở về ...”\n...\nTần triều .\nThủy Hoàng ba mươi năm .\nChương Đài cung .\n“ Đều đứng lên đi .”\nNhìn xem phủ phục tại người trước mặt nhóm , Doanh Chính không nói gì thêm , chỉ là tại nội tâm thở dài một cái .\nTrước kia hắn là thực sự không nghĩ tới , chính mình cảm thấy vô cùng cường đại Đại Tần , thì ra là thế suy yếu .\nHơn nữa , trước mặt cái này một số người , lại có bao nhiêu là trung thần đâu ?\nCuối Tần thời kì , lại có bao nhiêu là đang nỗ lực cứu Đại Tần đâu ?\n“ Bệ hạ !”\nLý Tư đứng lên , đi đến Doanh Chính trước mặt , lại nằm rạp trên mặt đất .\n“ Ngươi sự tình cuối cùng tại nói .”\n“ Trước tiên thảo luận ra 10 người , mười người này sau đó muốn đi hậu thế học tập .”\n“ Bằng không thì ...”\nNhìn xem bên cạnh cầm chồng chất hàng hóa như núi , Doanh Chính cảm giác tất cả mọi người ở đây , đều có chút không có chỗ xuống tay .\n...\nHiện đại thời không .\n“ Không phải , a ?!”\nLý Ân Phàm nhìn xem đặt ở chính mình trên bàn truyền đơn , cả người bắt đầu trước là mộng .\nSau đó thì sao ? Tiếp đó cũng không biết nên nói như thế nào .\n「 Mới phương tây cơ quan huấn luyện 」\n「 Ở trường thâm niên lão sư dạy học , mặt đối mặt toàn bộ tri kỷ giảng bài , khẩu hiệu không trọng yếu , trọng yếu là thực lực của chúng ta .」\n「 Không sợ học sinh cơ sở không có đánh hảo , đến nơi này tất cả nan đề toàn bộ giải quyết ! để cho học sinh giẫm ở tinh anh trên lưng leo lên .」\nTiếp đó , truyền đơn phía dưới cùng , cơ quan địa chỉ là Lý Ân Phàm sát vách cái kia tòa nhà .\n“ Không phải , ngươi cái này ...”\nLý Ân Phàm dở khóc dở cười .\nMặc dù biết bên kia chắc chắn sẽ không quan phương đứng ra , dù sao nếu là quan phương ra mặt , rất nhiều chuyện tính chất thì thay đổi .\nHơn nữa những cái kia vương triều cũng có thể sẽ nơm nớp lo sợ .\nGiao dịch là giao dịch , dù sao giao dịch là hoàn toàn đứng tại song phương ngang hàng tình huống phía dưới , song phương chủ sự cũng sẽ không đứng ra .\nCũng chính là “ Thương nhân ” đúng “ Thương nhân ”.\n“ Nhưng ngươi đây cũng quá ...”\nLý Ân Phàm lắc đầu , vẫn là đem truyền đơn cất kỹ , chuẩn bị ngày mai ban ngày đi xem một chút cái này cơ quan huấn luyện đến cùng là dạng gì .\n......\nChủ tuyến sẽ không thay đổi , vẫn như cũ lại là phân tích lịch sử . Thêm một chút thiết lập , là nếu như một mực dạng này phân tích mà nói , cũng có chút quá buồn tẻ , thêm một vài thứ tới điều tiết một chút .\nCái tiếp theo hoàng đế , Hán triều hoàng đế .', 'output\\mp3\\Màn Trời Quyền Lực Diễn Biến Cùng Truyền Thừa\\0055_Thứ 55 chương Quá độ chương tiết 1.mp3', '2026-09-01T22:24:52.495369+00:00', 'completed', 'completed', 7849, 7849),
	(61, 7, '7648576541672079896', 56, 'Thứ 56 chương Quá độ chương tiết 2', 'Thứ chương Quá độ chương tiết\nHiện đại thời không .\n“ Hơn 60 vạn nhất bộ đúng không ? Đi , ta ranh giới cuối cùng là chào giá không quá phận , liền đều mua lại , ngươi trực tiếp nói .”\n“ Yên tâm , tiền hoa hồng không biết đánh gãy , ta trước đó cũng là làm bất động sản môi giới , sẽ không cắt xén các ngươi tiền hoa hồng .”\nLý Ân Phàm đem bất động sản môi giới đưa đến cửa ra vào , vừa đi vừa đối với hắn nói .\n“ Lý tiên sinh , yên tâm , chúng ta sẽ mau chóng .”\n“ Ai nha , thật sự cảm tạ ! Cảm tạ !”\nBất động sản người trung gian viên gương mặt cao hứng , thật sự là mấy năm khó gặp được khách hàng lớn , hơn nữa cái này khách hàng lớn còn lớn như vậy phương , lý giải bọn hắn .\n“ Vậy cứ như thế , mau chóng !”\nĐem người trung gian viên đưa ra môn , Lý Ân Phàm nhẹ thở ra một hơi , một lần nữa ngồi trở lại trên ghế sa lon , buông lỏng xuống .\nBởi vì sau đó các triều đại đổi thay nhân viên đều sẽ tới đến hiện đại học tập , cho nên Lý Ân Phàm ủy thác bất động sản môi giới chuẩn bị đem chính mình trên dưới tất cả phòng ở toàn bộ mua lại .\nRòng rã một tòa , đều mua lại .\nĐến nỗi nói để cho bên kia đứng ra ? Thôi được rồi , chút chuyện nhỏ này , không cần thiết .\nHơn nữa , làm không tốt trên dưới rất nhiều phòng ở , chính là bọn hắn .\nHuống chi mình bây giờ trên thẻ mấy ức , không tốn ra ngoài , liền tồn tại trong thẻ ? Không cần thiết .\nVì quốc gia kinh tế làm nhiều một chút cống hiến , cớ sao mà không làm đâu ?\n“ Trên dưới hết thảy hai mươi ba tầng , mỗi tầng bốn phòng nhỏ .”\n“ Hẳn đủ .”\nVề sau không đủ , đó chính là chuyện sau này , Lý Ân Phàm xem chừng , có thể còn muốn bảy, tám cái triều đại sau đó mới sẽ không đủ .\n“ Tiếp đó chính là đồ gia dụng ...”\nĐồ gia dụng kỳ thực vẫn còn dễ giải quyết , chờ đem phòng ở toàn bộ mua , mỗi sáo phòng tử toàn bộ lộng một dạng đồ gia dụng là được .\nĐến lúc đó trực tiếp để cho đồ gia dụng công ty tới lộng .\n“ Lần này hẳn là một hai cái ức liền đi ra ngoài .”\n“ Tiếp đó , chính là tiền mặt .”\nLý Ân Phàm một lần nữa ngồi xuống , cầm bút lên , tại trên bàn trà , đem chính mình muốn làm đều nhớ kỹ .\n“ Mỗi người 10 vạn ?”\n“ Không được , Cổ Nhân đối với hiện đại tiền tài không có cái gì khái niệm , tốt nhất trước tiên mỗi người 1 vạn , chờ về sau lại cho .”\n“ Đừng đi ra một chuyến , liền bị lừa xong , cái kia cũng rất khôi hài .”\nBị lừa loại chuyện này , đằng sau bên kia nhất định sẽ quản , nhưng mà đang gạt trên đường , sẽ đi ngăn cản sao ?\nLý Ân Phàm xem chừng sẽ không , dù sao cái này cũng là hiện đại một loại kinh nghiệm .\nTốt , hư , bên kia cũng sẽ không ngăn cản Cổ Nhân đi kinh nghiệm .\n“ Tiếp đó chính là quần áo ...”\nNghĩ tới đây , Lý Ân Phàm cầm điện thoại di động lên , cho bên kia phát một cái tin nhắn : Phiền phức tại bên ngoài tiểu khu , mở một chút sinh hoạt nguyên bộ công trình .\nKhông đầy một lát , bên kia trở về tin nhắn : Đã toàn bộ sớm mở tốt .\n“ Vẫn là bên kia nghĩ chu đáo .”\n“ Cũng đúng , xem chừng chung quanh toàn bộ đều là người của bọn hắn .”\nDùng bút trên giấy đem sinh hoạt công trình vạch tới , Lý Ân Phàm lại viết xuống :\n“ Điện thoại , ân ...”\n“ Trước tiên có thể mua mấy trăm đài tiện nghi một chút điện thoại , còn có tấm phẳng , mỗi cái gian phòng còn có TV ...”\n“ Đặc biệt là TV , tại cơ quan huấn luyện học tập xong , về nhà muốn học một chút , cũng có thể xem TV học tập .”\nLâm Lâm các loại , Lý Ân Phàm mỗi viết xuống một cái , liền ngẩng đầu nhìn một chút gian phòng của mình , nhìn còn có cái gì cần .\nChờ đến buổi tối , toàn bộ viết xong , Lý Ân Phàm tử nhìn kỹ nhìn , phát hiện không có cái gì bỏ sót , liền hài lòng gật đầu một cái .\nSau đó , Lý Ân Phàm bỗng nhiên nghĩ tới điều gì , sững sờ .\n“ Những vật này bên kia không có nhúng tay , không phải là từng chút từng chút bồi dưỡng ta đi ?”\nLý Ân Phàm cảm thấy rất có khả năng , dù sao mình muốn làm , đằng sau còn rất nhiều , bây giờ trước tiên từng điểm từng điểm tới làm , đằng sau cũng sẽ không luống cuống tay chân .\nDù sao bên kia là nhất định sẽ không ra mặt , chỉ có thể bảo trì ăn ý .\n“ Cái này cũng chính xác quá rèn luyện người .”\nNghĩ đến về sau chính mình muốn quản lý nhiều nhất mấy trăm cổ nhân , Lý Ân Phàm cũng có chút vò đầu .\n“ Còn may là 10 cái 10 cái từ từ sẽ đến .”\nNgày thứ hai .\nTiểu khu bên cạnh mới mở một nhà bảo mẫu công ty .\n“ Ân , đúng , cách một đoạn thời gian , ta liền cần mấy vị bảo mẫu .”\n“ Không cần bọn hắn chỉnh lý gian phòng cái gì , dạy căn phòng một chút bên trong người làm sao sử dụng đồ gia dụng đồ điện gia dụng cái gì liền tốt .”\nLý Ân Phàm rất là ăn ý nhìn trước mặt nhân viên công tác một mắt , sau đó nói ra yêu cầu của mình .\n“ Tốt , Lý tiên sinh , không có vấn đề .”\nNhân viên công tác lộ ra một bộ ta biết thần sắc .\n“ Ân , đến lúc đó nhân viên đến , ta sẽ cho các ngươi gọi điện thoại .”\nNói xong , Lý Ân Phàm liền đi ra bảo mẫu công ty , sau đó ngẩng đầu lại nhìn một chút chung quanh mới mở một chút cửa hàng cùng công ty .\nCầm bút lên cùng máy vi tính xách tay (bút kí) , Lý Ân Phàm đem những thứ này mới mở cửa hàng cùng công ty từng cái ghi nhớ .\nVề phần tại sao muốn thỉnh bảo mẫu ? Bởi vì người phía sau nhiều , Lý Ân Phàm không có khả năng Nhất Nhất giáo Cổ Nhân sử dụng như thế nào đồ gia dụng đồ điện gia dụng cái gì .\nBên kia cũng tri kỷ , tựa hồ biết điểm này , thật sớm liền đem bảo mẫu công ty mở ở tiểu khu bên cạnh .\nNhư vậy thì tính toán Cổ Nhân trong mười người , mang có hạ nhân hoặc có lẽ là người hầu cái gì , đến lúc đó cũng có người đi dạy bọn họ .\n“ Đây đều là đằng sau phải dùng , bên kia thật đúng là tri kỷ , sợ ta quên .”\nĐêm qua Lý Ân Phàm còn cảm thấy chính mình hẳn là toàn bộ nhớ cho kĩ , không nghĩ tới còn có một số chính mình không nghĩ tới .\nTỉ như nói : Mét trạm .\nCũng chính là bán gạo địa phương .\nBên trong siêu thị mặc dù có , nhưng ở trong đó giá cả , đều theo túi tính toán .\nLý Ân Phàm gặp mở có gạo trạm , liền biết bên kia đã mò thấy cổ nhân tâm lý .\nKỳ thực liền không nói cổ nhân tâm lý , Lý Ân Phàm có đôi khi đều cảm thấy bên trong siêu thị túi chứa mét quả thật có chút đắt .\n“ Đây là lo lắng Cổ Nhân không nỡ ăn a , thật tri kỷ .”\nMỗi đi ngang qua một cái cửa hàng , Lý Ân Phàm đều phải vào xem một mắt , xem bên trong chuẩn bị như thế nào .\nChuẩn bị ngược lại là đều không khác mấy , chính là bên trong thường xuyên xuất hiện đầu húi cua , có chút để cho Lý Ân Phàm buồn cười .\n“ Cái này cũng thực sự là lợi hại , đầu này đường phố , cơ hồ đều có .”\nĐứng tại trên đường cái , Lý Ân Phàm nhìn thấy những cửa hàng kia , thật sự vô cùng cảm khái .\nBán gạo , bán dầu , đơn độc bán đồ dùng hàng ngày , siêu thị , bán quần áo cái gì , thượng vàng hạ cám , hoàn toàn là bao quát vạn tượng .\nChủ yếu nhất , là có thể liếc mắt liền nhìn ra , trong cửa hàng bán cái gì .\n“ Đi , như vậy thì không sai biệt lắm .”\nKhông chút tiếp tục cảm khái , Lý Ân Phàm đi vào một nhà tiệm ăn trung quốc , chuẩn bị đem cơm trưa trước giải quyết .\n“ Lão bản , ăn cơm ...”\nTiến vào cửa hàng , Lý Ân Phàm trực tiếp ngồi ở chỗ ngồi , hướng về lão bản hô .\n“ Không phải ...”\nLý Ân Phàm bắt đầu còn không có chú ý lão bản kia , chờ lão bản lấy thực đơn tới sau đó mới phát hiện , đây không phải lúc trước cùng Thủy Hoàng che yên ổn đi ăn tiệm ăn trung quốc lão bản kia sao ?\n“ Muốn ăn cái gì ?”\nLão bản nháy nháy mắt , cố gắng giả vờ mặt không biểu tình .\n“ Rau trộn tai diệp , thịt nhão cây đậu đũa , thêm một chén nữa cơm cùng một bình Vương Cát Cát .”\nMấy người lão bản lấy ra sách nhỏ ghi nhớ , Lý Ân Phàm đột nhiên cảm giác được hết sức buồn cười .\n“ Chỉ những thứ này đúng không ?”\n“ Ân .”\nChờ lão bản đi , Lý Ân Phàm còn chuyên môn đứng lên , nhìn một chút trong phòng bếp đầu bếp .\n“ Hắc , thật đúng là cái kia đầu bếp .”\n......', 'output\\mp3\\Màn Trời Quyền Lực Diễn Biến Cùng Truyền Thừa\\0056_Thứ 56 chương Quá độ chương tiết 2.mp3', '2026-09-01T22:24:58.959414+00:00', 'completed', 'completed', 7582, 7582),
	(62, 7, '7648971537587913240', 57, 'Thứ 57 chương Quá độ chương tiết 3', 'Thứ chương Quá độ chương tiết\nHiện đại thời không .\nCứ như vậy , chênh lệch thời gian không nhiều hơn hơn phân nửa cái nguyệt , Lý Ân Phàm bên này chuẩn bị không sai biệt lắm , chuẩn bị mở ra quang môn tiếp Tần triều mười người tới .\nĐến nỗi tiết mục bên kia , bởi vì thời kỳ thứ nhất thu lâu , không sai biệt lắm có thể phóng bốn kỳ , mỗi nửa tháng đồng thời , cho nên cũng không phải là vội vã như vậy , mỗi tháng rút một ngày đi thu liền tốt .\nHơn nữa bên kia quyết định chú ý , chỉ sợ là toàn bộ chép xong lại thả ra .\nHệ thống , mở ra màn trời a .】\nTiếng nói rơi xuống , Lý Ân Phàm trước mặt , lập tức xuất hiện một cái hiện ra lấy chính mình khuôn mặt màn hình .\n...\nTần triều .\nThủy Hoàng ba mươi năm .\nCác triều đại đổi thay các bằng hữu , các ngươi tốt .】\nMột thời kì mới màn trời muốn bắt đầu .】\nKỳ này , chúng ta chủ yếu bày ra , là Tần triều sẽ có 10 người , đi tới ta chỗ này học tập .】\n“ Phù Tô , đi sau đó , hết thảy đều nhớ kỹ nghe tiên sinh .”\n“ Ừm , bệ ... A cha .”\nPhù Tô nhìn xem Thủy Hoàng Doanh Chính cái kia lo lắng ánh mắt , vẫn là sửa lại .\nDoanh Chính vui mừng gật đầu một cái .\nCái này hơn nửa tháng đến nay , chính mình đem Phù Tô một mực mang ở bên cạnh dạy bảo , cuối cùng có một chút thay đổi .\n“ Nhớ kỹ , chiếu cố tốt của ngươi đệ đệ muội muội nhóm .”\n“ Ân .”\nPhù Tô đầu tiên là quay đầu liếc mắt nhìn sau lưng lo lắng bất an các đệ đệ muội muội , sau đó hướng về Doanh Chính nặng nề gật đầu nói :\n“ Yên tâm đi , a cha .”\n“ Đúng , a cha ... Hồ Hợi ...”\nNghe được cái tên này , không khí chung quanh tựa hồ lập tức liền lạnh xuống .\nBên cạnh Mông Điềm có chút bận tâm liếc mắt nhìn Phù Tô .\n“ Yên tâm đi , ta không có giết hắn , chỉ là đem hắn biến thành thứ dân , phái người giám thị lấy .”\nDoanh Chính biết Phù Tô đang suy nghĩ gì , dù sao Hồ Hợi chung quy là đệ đệ của hắn .\nMà Hồ Hợi , cũng chung quy là hắn Doanh Chính hài tử .\nGiết ? Là không cần phải , nhưng trong lịch sử hắn làm những người kia , cơ hồ tất cả mọi người đều biết .\nBiến thành thứ dân , cứ như vậy không có tiếng tăm gì sinh hoạt , cũng là vì hắn tốt .\n...\nĐường triều .\nTrinh Quán bảy năm .\nĐến nỗi những thứ khác triều đại , cũng không cần lo lắng , chờ đằng sau mở ra mỗi cái triều đại , bệ hạ của các ngươi sau khi đến , liền sẽ có 10 cái danh ngạch , đi tới hậu thế học tập .】\n“ Vậy mà thật sự sẽ đi hậu thế học tập ...”\nLý Thế Dân ngạc nhiên nhìn xem màn trời .\nLúc trước nội tâm của hắn liền có một chút ngờ tới , dù sao mang theo đời sau vật phẩm trở lại bọn hắn triều đại , vậy những này đồ vật , ai sẽ sử dụng đây ?\nPhía trước ban đêm Lý Ân Phàm cho Doanh Chính bọn hắn lúc nói , không có mở ra màn trời , bây giờ cùng nhau nói ra .\nĐương nhiên , cũng chỉ vẻn vẹn có 10 cái danh ngạch , hy vọng các ngươi an bài tốt cần đến hậu thế tới học tập nhân viên .】\nChờ các ngươi bệ hạ về tới các ngươi triều đại , các ngươi liền sẽ trực tiếp tới .】\nChờ màn trời câu nói này nói xong , dưới đài rất nhiều đại thần , đều quay đầu lập tức nhìn về phía bệ hạ của bọn hắn Lý Thế Dân .\n“ Bệ hạ ...”\nThanh âm huyên náo lập tức vang lên , bao quát Ngụy Chinh ở bên trong , tất cả mọi người đều dùng ánh mắt khát vọng nhìn xem hắn .\n“ Ngừng !!!”\n“ Còn không biết trẫm khi nào đi , trước tiên không vội ! Xem trước một chút Tần triều là thế nào an bài !”\nĐương nhiên , tới trước tới , cũng có thể là cũng không phải bệ hạ của các ngươi ...】\nTrên thiên mạc , Lý Ân Phàm bỗng nhiên lộ ra một cái ánh mắt ý vị thâm trường .\nDù sao có chút triều đại , hoàng đế ảnh hưởng cũng không sâu , ảnh hưởng sâu , là những đại thần kia .\n...\nMinh triều .\nVĩnh Lạc bảy năm .\n“ Đây là ý gì ?”\nChu Lệ sững sờ , có chút không hiểu , vì cái gì màn trời biết nói , về phía sau thế , có khả năng cũng không phải hoàng đế ?\n“ Phụ thân , ngươi nói , hoắc quang cùng Lưu Hạ , hai người này ai sẽ đi ?”\nChu Cao Sí ở bên cạnh bất thình lình nói một câu như vậy .\n“ Úc ! Ta đã hiểu .”\nNày ngược lại là , có chút triều đại thời kì , làm chủ cũng không phải hoàng đế , mà là đại thần .\nNếu như là dạng này , hoàng đế đi hậu thế , có ích lợi gì ? Đương nhiên là những đại thần kia đi mới có tác dụng .\n“ Chậc chậc ... Cứ như vậy , vậy là tốt rồi chơi .”\n“ Cũng không biết trước mặt những hoàng đế kia , biết bọn hắn triều đình , bị quyền thần nắm giữ , sẽ lộ ra cái gì thần sắc .”\nChu Lệ tựa hồ nghĩ tới điều gì , trên mặt lộ ra nhìn có chút hả hê thần sắc .\n...\nHiện đại thời không .\n“ Tốt , không nói nhiều nói , Tần triều các vị , chuẩn bị kỹ càng , muốn mở ra quang môn .”\nLý Ân Phàm nói xong , đứng lên , đi đến phòng khách chỗ trống trải , giơ tay lên , mở ra quang môn .\nQuang môn xuất hiện , không đầy một lát , quang môn chỗ bắt đầu xuất hiện bóng người .\n“ Tiên sinh ...”\nDẫn đầu chính là Phù Tô , đi đến Lý Ân Phàm trước mặt , cung kính thi lễ một cái .\nSau đó người xuất hiện viên , cũng đều đi đến Lý Ân Phàm trước mặt , hướng về phía hắn thi lễ một cái .\n“ Đi , các ngươi trước kia cũng nhìn qua màn trời , đi tới hậu thế , không cần biết hay không thì hành lễ .”\n“ Một chút tương đối thường gặp sự tình , Mông Điềm sẽ dạy các ngươi .”\nMông Điềm ở bên cạnh gật đầu một cái , hướng về phía Phù Tô ra hiệu , đợi chút nữa nói cho bọn hắn biết .\n“ Đến nỗi các ngươi những người khác , các ngươi trước tiên tách ra trạm , sau đó muốn theo ai ở cùng một chỗ , các ngươi liền đứng chung một chỗ .”\n“ Một bộ phòng ở , hai cái phòng ngủ , cũng chính là một bộ phòng ở có thể ở hai người .”\nKhông đầy một lát , Lý Ân Phàm người trước mặt nhóm liền riêng phần mình đứng vững .\n“ Hảo , trước tiên theo ta ra ngoài , ta an bài cho các ngươi gian phòng .”\nLý Ân Phàm dẫn đầu đi ra cửa phòng , người đứng phía sau nhóm thấp thỏm đi theo sau lưng Lý Ân Phàm .\nMông Điềm bởi vì tới qua , cho nên rất quen thuộc , đi ở cuối cùng , bảo hộ lấy cái này một số người .\n“ Đây là gian phòng thứ nhất , hai người , các ngươi xem ai trước tiên vào ở ?”\nMở ra thứ nhất cửa phòng , bộ phòng này tại Lý Ân Phàm sát vách .\n“ Ở đây từ ta cùng Mông tướng quân nổi a .”\nPhù Tô quay đầu liếc mắt nhìn Mông Điềm , sau đó hướng về phía Lý Ân Phàm gật đầu nói .\n“ Hảo ...”\nKhông đầy một lát , phân phối đến cuối cùng một bộ phòng ở , sau lưng Lý Ân Phàm cũng liền chỉ còn dư 4 người .\n“ Đây là các ngươi cuối cùng một bộ ...”\n“ Âm Mạn , dương tư , một bộ này các ngươi ở a .”\nPhù Tô ôn nhu đối với sau cùng hai tên nữ tử nói .\n“ Ừm , huynh trưởng .”\nHai vị công chúa hiếu kỳ đi vào .\n“ Tiên sinh ...”\n“ Ân , các ngươi chờ một chút , ta sắp xếp người Lai giáo một chút bọn hắn .”\nLý Ân Phàm lấy điện thoại di động ra , cho phía trước thương lượng xong bảo mẫu công ty gọi điện thoại .\n“ Đúng , an bài năm vị bảo mẫu là được .”\n“ Hảo , vậy các ngươi nhanh lên .”\nLý Ân Phàm quay đầu liếc mắt nhìn trong gian phòng câu nệ hai vị công chúa , sau đó vẫy vẫy tay , ra hiệu Phù Tô cùng Mông Điềm cùng chính mình xuống .\n“ Trước hết để cho bọn hắn nhẹ nhàng một chút tâm tình , đợi lát nữa có người đi dạy bọn họ sử dụng như thế nào đồ điện và đồ gia dụng .”\n“ Hảo ...”\nKhông đầy một lát , bảo mẫu công ty nhân viên công tác mang theo năm tên niên linh không sai biệt lắm hơn 30 tuổi nữ tử đi tới .\n“ Phía trên một tầng bốn phòng nhỏ , còn có sát vách một bộ phòng ở ...”\n“ Hảo , không có vấn đề .”\nNhân viên công tác gật đầu một cái , tiếp đó liền mang theo năm tên nữ tử đi ra ngoài .\n“ Đúng , Phù Tô ...”\nLý Ân Phàm bỗng nhiên nghĩ tới điều gì , nghiêm túc đối với Phù Tô nói :\n“ Chúng ta hiện đại không có cái gì hạ nhân cùng người hầu , nhất định không nên đem các ngươi một chút quen thuộc đưa đến nơi này .”\n“ Yên tâm đi , tiên sinh , bệ hạ đã khuyên bảo qua chúng ta .”\nMông Điềm lúc này ở bên cạnh nói tiếp .\n“ Vậy là tốt rồi ...”\nLý Ân Phàm chủ yếu cũng là vừa mới nhìn thấy cái kia năm tên nữ tử , mới chợt nhớ tới .\nBởi vì cái kia năm tên nữ tử , một mắt liền có thể nhìn ra là quân đội người ở bên trong , bước chân kia cùng thế đứng , thật là quá tiêu chuẩn .\n“ Vậy các ngươi liền đi về trước a , trước tiên đi theo bảo mẫu học tập một chút sử dụng như thế nào những cái kia đồ gia dụng cùng đồ điện .”\n“ Đợi lát nữa đến buổi tối , lúc ăn cơm , chúng ta thương lượng lại sự tình khác .”\n“ Hảo , tiên sinh .”\nTiếng nói rơi xuống , Phù Tô hướng về phía Lý Ân Phàm thi lễ một cái , sau đó cùng Mông Điềm đi ra ngoài .\n“ Chậc chậc ...”\nNhìn xem Phù Tô bóng lưng , Lý Ân Phàm hơi xúc động nghĩ đến :\nCứ như vậy Thái tử , tự vẫn , thật đúng là tiếc nuối .\n......', 'output\\mp3\\Màn Trời Quyền Lực Diễn Biến Cùng Truyền Thừa\\0057_Thứ 57 chương Quá độ chương tiết 3.mp3', '2026-09-01T22:25:03.975386+00:00', 'completed', 'completed', 8323, 8323),
	(63, 7, '7648971729007559192', 58, 'Thứ 58 chương Quá độ chương tiết 4', 'Thứ chương Quá độ chương tiết\nHiện đại thời không .\nBan đêm .\nBên ngoài tiểu khu một chỗ nhà hàng trong phòng chung .\n“ Ăn không sai biệt lắm , vậy chúng ta trước hết thương lượng một chút , các ngươi muốn đi học tập cái gì a .”\nLý Ân Phàm gặp trên mặt bàn tất cả mọi người đều buông đũa xuống , lấy ra bút cùng vở , nhẹ nói .\n“ Đầu tiên là Phù Tô , ngươi muốn học cái gì ?”\nPhù Tô nhìn một chút bên cạnh Mông Điềm , sau đó đứng lên , nhẹ giọng đối với Lý Ân Phàm nói :\n“ Tiên sinh , a cha nói để chúng ta đi tới hậu thế , nghe ngươi an bài .”\n“ Nghe ta an bài sao ?”\nLý Ân Phàm gật đầu một cái , cũng không ngoài ý muốn , dù sao Thủy Hoàng cùng Mông Điềm cũng mới đến hậu thế ba ngày , ba ngày cũng biết không toàn diện .\n“ Cái kia Phù Tô , ngươi từ hậu thiên bắt đầu , đi học quản lý a .”\n“ Ngày mai tất cả mọi người nghỉ ngơi một ngày .”\nLý Ân Phàm đầu tiên là ra hiệu Phù Tô ngồi xuống , sau đó cầm bút lên , tại trên quyển sổ viết lên Phù Tô tên , đằng sau viết : Quản lý chương trình học .\n“ Quản lý sao ?”\nPhù Tô nháy nháy mắt , sau đó gật gật đầu .\n“ Mông Điềm ... Mông tướng quân , ngươi đi quân đội học tập , như thế nào ?”\nNghe nói như thế , Mông Điềm gương mặt kinh hỉ .\n“ Hảo , tiên sinh .”\n“ Ân , hậu thế quân đội rất nhiều đồ vật có thể không thích hợp đưa đến các ngươi triều đại .”\n“ Nhưng các ngươi mang về nhiều đồ như vậy , nhất định sẽ ảnh hưởng quân đội , như thế nào để cho quân đội từ từ chuyển hình , đây chính là ngươi muốn học .”\n“ Hơn nữa , cũng không chỉ là học tập hiện đại quân đội , trong lịch sử mỗi triều đại quân chế , cũng sẽ có .”\nĐể cho Mông Điềm đi quân đội học tập , cũng không phải nói để cho hắn hoàn toàn rập khuôn , bên kia cũng sẽ không làm như vậy .\nTrường học nhất định sẽ đem các triều đại đổi thay quân chế cái gì , đều biết giảng giải .\n“ Sau đó các ngươi những người khác ...”\n“ Đem lư , nhà máy học tập ...”\n“ Cao , hậu cần trung tâm học tập ...”\nLý Ân Phàm từng cái nói qua đi , cho mọi người an bài tốt , từ từ liền nói đến cuối cùng hai người , cũng chính là hai tên công chúa .\n“ Thắng Âm Mạn công chúa và dương tư công chúa , các ngươi một người đi đến trường , một người đi bệnh viện a .”\nChỉ là để cho một người đi bệnh viện học tập , cái này nghe tựa hồ có chút không thể tưởng tượng nổi , nhưng lại không có trông cậy vào bọn hắn toàn bộ học được .\nChỉ cần học được làm như thế nào sử dụng một vài thứ là được rồi .\nMang về những hàng hóa kia , đừng cho bọn chúng nát vụn ở nơi đó liền tốt .\n“ Đại gia ngày mai nghỉ ngơi một ngày , ta mang các ngươi nhận thức một chút chung quanh cửa hàng , biết những thứ đó nên ở nơi nào mua .”\n“ Những thứ khác , các ngươi mua về , có thể hỏi các ngươi bảo mẫu .”\n“ Hậu thiên , ta đem các ngươi đưa đến cơ quan huấn luyện , đến lúc đó đại gia liền muốn bắt đầu học tập .”\n“ Sau đó nửa năm , các ngươi cũng sẽ ở ở đây học tập , hy vọng đại gia cố gắng !”\nTiếng nói rơi xuống , tất cả mọi người ở đây hai mặt nhìn nhau , sau đó miệng đồng thanh nói :\n“ Ừm , tiên sinh .”\n...\nHiện đại thời không .\nBan đêm .\nLý Ân Phàm đem đám người muốn học tập địa phương , còn có tên của bọn hắn , đều đánh vào tin nhắn , cho bên kia phát tới .\nKhông đầy một lát , bên kia trở về tin nhắn\n“ Vậy cứ như thế .”\nChuẩn bị cho tốt những thứ này , Lý Ân Phàm cầm lấy một cái ba lô , trong ba lô diện trang 10 vạn khối tiền .\nĐi đến bên cạnh Phù Tô cùng Mông Điềm gian phòng bắt đầu gõ cửa .\nThùng thùng !\n“ Tiên sinh ?”\nPhù Tô mở cửa phòng , thấy là Lý Ân Phàm , nghiêng người sang , nhường một con đường đi ra .\n“ Phù Tô , tìm ngươi có một số việc .”\nLý Ân Phàm cầm ba lô đi vào gian phòng , một mắt chỉ thấy Mông Điềm cầm máy sấy tại sấy tóc .\n“ Tiên sinh ?”\nMông Điềm thấy là Lý Ân Phàm , đóng lại máy sấy .\n“ Ngươi làm việc trước ngươi , ta tìm Phù Tô có một số việc .”\n“ Hảo .”\nMông Điềm không có tiếp tục mở ra máy sấy , mà là đi đến Phù Tô bên cạnh .\n“ Trong túi xách này là 10 vạn khối , các ngươi 10 người một người 1 vạn .”\n“ Sau đó cách mỗi mấy ngày , ta liền sẽ đưa tiền tới .”\nLý Ân Phàm đầu tiên là ra hiệu Phù Tô ngồi xuống , sau đó đem ba lô giao cho Phù Tô , để cho hắn xem .\n“ Cái này ?!”\nPhù Tô đang chuẩn bị chối từ , Lý Ân Phàm phất phất tay , không thèm để ý nói :\n“ Các ngươi tới hậu thế học tập , không có tiền sao được ? Chắc chắn không có khả năng để các ngươi vừa làm việc kiếm tiền , bên cạnh học tập ?”\n“ Hơn nữa , tiền này vẫn là các ngươi bệ hạ Lộc Lư Kiếm đổi tiền .”\n“ Công tử , thu cất đi , cái này hậu thế , bất kể làm cái gì đều cần tiền .”\nBên cạnh Mông Điềm cũng khuyên .\nMông Điềm dù sao ở đời sau chờ đợi ba ngày , khắc sâu sau khi biết thế tiền tài tầm quan trọng .\n“ Hảo ...”\nPhù Tô đem ba lô nhận lấy , học Lý Ân Phàm động tác , mở ra khóa kéo , liếc mắt nhìn trong túi đeo lưng tiền tài .\n“ Đúng , tiên sinh ...”\n“ Ân ?”\nLý Ân Phàm nghi hoặc nhìn Phù Tô , không biết hắn muốn nói cái gì ?\n“ Cái này hậu thế một cái người bình thường , bọn hắn mỗi ngày phải dùng bao nhiêu tiền tài ?”\nLý Ân Phàm liếc mắt nhìn Phù Tô , tựa hồ biết hắn muốn làm cái gì .\n“ Một cái người bình thường , bọn hắn một tháng tiền lương , không sai biệt lắm là nếu như không còn tiền , mỗi ngày không sai biệt lắm bình quân phải dùng hơn 100 khối tiền .”\nLý Ân Phàm lấy ra bên trong túi đeo lưng một tấm một trăm nguyên , đối với Phù Tô nói .\nPhù Tô trầm tư một hồi , sau đó đối với Lý Ân Phàm nói :\n“ Tiên sinh , vậy ngươi sau đó mỗi tháng liền theo nguyên , đến đây đi .”\nLý Ân Phàm tựa hồ biết Phù Tô sẽ nói như vậy , lắc đầu nói :\n“ Ta cách mỗi 10 ngày tiễn đưa 10 vạn tới , các ngươi dùng như thế nào là chuyện của các ngươi .”\n“ Cái này .. Tốt a ...”\nPhù Tô gật đầu một cái , không có tiếp tục nói nữa , nhưng hắn hay là chuẩn bị liền theo một người một tháng cho mình những đệ đệ muội muội kia .\nNhững thứ khác ? Hắn chuẩn bị tận lực còn lại một chút tiền tài , cho mình a cha bọn hắn mua một vài thứ .\n“ Cứ như vậy đi , buổi sáng ngày mai ta mang các ngươi , buổi chiều chính các ngươi có thể đi dạo ...”\nLý Ân Phàm nói xong , đi ra khỏi phòng .\nTại sao phải để Phù Tô bọn hắn dùng tiền mặt , không cần con số thanh toán ?\nBan đầu , Lý Ân Phàm là không định để cho Phù Tô bọn hắn học tập con số thanh toán , cũng chính là hơi hơi thanh toán cái gì .\nBởi vì con số thanh toán , rất dễ dàng đối với tiền sinh ra khái niệm mơ hồ .\nNhững thứ này Cổ Nhân , cũng đối con số không thể nào mẫn cảm , hoặc rất có thể đã cảm thấy là một chuỗi con số .\nDù sao hiện đại đều có vô số dạng này người .\nTrước hết để cho bọn hắn dùng tiền mặt , biết tiền mặt sức mua sau đó , nếu như muốn học con số thanh toán , liền có thể ở phía sau học .\nMặc dù Lý Ân Phàm cảm thấy , bọn hắn thật sự là không cần thiết học tập con số thanh toán cái gì .\nDù sao muốn để cổ đại những cái kia vương triều , đi lên con số thanh toán con đường này ? Vậy coi như quá lâu quá lâu .\nDùng chi trả bằng tiền mặt , còn có thể hiểu rõ hiện đại mặt đối mặt giao dịch một vài thứ , đây mới là Lý Ân Phàm cảm thấy trọng yếu nhất .\n......', 'output\\mp3\\Màn Trời Quyền Lực Diễn Biến Cùng Truyền Thừa\\0058_Thứ 58 chương Quá độ chương tiết 4.mp3', '2026-09-01T22:25:09.467232+00:00', 'completed', 'completed', 6898, 6898),
	(64, 7, '7649338032973152793', 59, 'Thứ 59 chương Quá độ chương tiết (4K đại chương )', 'Thứ chương Quá độ chương tiết đại chương )\n( Cuối cùng một đại chương quá độ chương tiết , ngày mai quá độ kết thúc .)\nHiện đại thời không .\n“ Nơi này chính là các ngươi về sau muốn tập hợp địa phương .”\n“ Đến nỗi mấy điểm tụ tập , các ngươi về sau liền nghe lão sư an bài a .”\nSáng sớm khoảng tám giờ , Lý Ân Phàm mang theo Phù Tô mười người đi vào bên cạnh cơ quan huấn luyện .\nLúc này cơ quan huấn luyện , đã có mấy người đang trong phòng chờ lấy .\n“ Ai ... Ngươi tốt .”\nLý Ân Phàm đi lên trước , trước tiên cùng người nắm tay .\nSau lưng Phù Tô bọn người , cũng học Lý Ân Phàm dáng vẻ , cùng bọn hắn nắm tay .\n“ Chính là bọn hắn mười người , sau đó nửa năm liền nhờ cậy các ngươi .”\nLý Ân Phàm nghiêng người , đem không gian lưu cho bọn hắn .\n“ Tốt , không có vấn đề .”\nDẫn đầu một vị đầu húi cua , hướng về Lý Ân Phàm gật đầu một cái , tiếp đó mở điện thoại di động lên , đối chiếu ảnh chụp cùng tên từng cái đối ứng .\n“ Vậy ta trước hết dẫn bọn hắn đi .”\n“ Ân .”\nLý Ân Phàm gật gật đầu , sau đó hướng về phía Phù Tô cùng Mông Điềm bọn hắn nhẹ nói :\n“ Cùng bọn hắn đi thôi , buổi tối bọn hắn sẽ tiễn đưa các ngươi trở về , không cần lo lắng .”\n“ Tốt , tiên sinh .”\n...\nHiện đại thời không .\nMột chỗ học viện chỉ huy .\n“ Chúng ta bây giờ nhìn thấy , là hiện đại một chỗ chỉ huy quân sự học viện .”\n“ Tần triều Mông Điềm tướng quân , chính là ở đây học tập , hắn lại ở chỗ này học tập nửa tháng .”\nLý Ân Phàm đi ở ngoài phòng học , nhỏ giọng nói .\nÂm thanh cùng hình ảnh , xuyên thấu qua hệ thống , trực tiếp truyền đến các triều đại đổi thay màn trời phía trên .\nMột vị đầu húi cua tựa hồ biết Lý Ân Phàm đang làm cái gì , chỉ là đi theo phía sau hắn , để người khác không nên quấy rầy đến hắn .\n...\nTần triều .\nThủy Hoàng ba mươi năm .\nChúng ta có thể nhìn thấy , vị kia chính là Mông Điềm tướng quân , bây giờ vô cùng nghiêm túc , tại dưới đài nghe lão sư giảng bài .】\nChương Đài cung bên ngoài , rất nhiều đại thần nhìn xem trên thiên mạc Mông Điềm , đều lộ ra một vòng thần sắc hâm mộ .\nThủy Hoàng Doanh Chính tại trên đường xử lý chính vụ , ngẩng đầu nhìn một mắt , hài lòng gật đầu .\n“ Thật ao ước Mộ huynh dài ...”\nMông Nghị giờ phút này là thực sự hâm mộ huynh trưởng của mình , nhưng hắn biết mình là không có cách nào đi , bởi vì muốn thường xuyên canh giữ ở bệ hạ bên người .\nBây giờ Thủy Hoàng , từ hậu thế dạo qua một vòng trở về , có thể nói ngoại trừ Mông gia , ai cũng không tin .\nDù sao Mông gia thật là dùng chết đã chứng minh sự trung thành của mình .\nTại Thủy Hoàng trở về cái kia buổi tối , Mông Điềm còn nhớ rõ bệ hạ đơn độc lôi kéo hắn cùng huynh trưởng của hắn hai người nói :\n“ Sau này Đại Tần , phải dựa vào huynh đệ các ngươi hai người .”\n“ Bệ hạ ... Cái kia Vương gia đâu ?”\n“ Vương gia ?”\nThủy Hoàng trầm mặc một hồi , thản nhiên nói :\n“ Vương gia , ở đời sau thế nhưng là đại thế gia ...”\n...\nĐường triều .\nTrinh Quán bảy năm .\nBây giờ lão sư trên đài giảng giải , hẳn là Đường triều quân chế .】\n“ Ân ? Chúng ta quân chế ?”\nNghe nói như thế , cam lộ trước điện phương , đông đảo võ tướng đều nghiêm túc .\nTại giảng giải các đời quân chế lúc , trên đài lão sư sẽ nói rõ ưu điểm của bọn nó , đương nhiên , cũng sẽ có khuyết điểm .】\nTiếp đó , bọn hắn liền thấy Lý Ân Phàm chỉ là ở phòng học ngoại trạm trong chốc lát , liền đi .\n“ Ôi , các ngươi kể xong lại đi a !”\nTrình Tri Tiết vốn là nhìn hết sức nghiêm túc , kết quả Lý Ân Phàm trực tiếp đi ?\nĐi ?!\n“ Ai nha !!”\nLần này , đông đảo võ tướng đều đồng loạt nhìn về phía Lý Thế Dân .\n“ Đừng nhìn trẫm , trẫm cũng không có biện pháp ! Chỉ có chờ !”\nLý Thế Dân thấy vậy tình huống , rất là bất đắc dĩ hướng về phía bọn hắn nói .\nSau đó , Lý Thế Dân lại trấn an đám người :\n“ Yên tâm đi , đến lúc đó trẫm sẽ chọn các ngươi một người trong đó về phía sau thế học tập .”\n...\nHiện đại thời không .\n“ Chúng ta bây giờ nhìn thấy , là Tần triều công tử Phù Tô , tại một trường đại học bên trong , học công cộng quản lý .”\nMột trường đại học ngoài phòng học , Lý Ân Phàm chỉ là vỗ một cái Phù Tô , tiếp đó liền đi , không có quá nhiều quấy rầy .\n“ Đây là hiện đại một trường đại học .”\n“ Đương nhiên , cái này đại học , không phải 《 Lễ Ký 》 bên trong ngày đó 《 Đại Học 》.”\n“ Các ngươi bây giờ cũng có thể nhìn thấy , lúc này trong đại học đông đảo học sinh .”\nLý Ân Phàm chỉ chỉ lầu dạy học bên ngoài , đang vội vã mang mang ôm sách vở đi qua học sinh .\n“ Hiện Đại đại học là áp dụng giáo dục cao đẳng cơ quan , lấy bản khoa giáo dục làm căn bản tạo thành bộ phận , chỉ tại bồi dưỡng có sáng tạo cái mới tinh thần cùng thực tiễn năng lực Đức Trí Thể đẹp phát triển toàn diện sự nghiệp xây dựng giả cùng người nối nghiệp .”\n“ Có thể nghe như vậy , các ngươi có chút lạ lẫm .”\nLý Ân Phàm vừa đi vừa chậm rãi giải thích nói :\n“ Các ngươi có thể lý giải thành hiện đại , Hán đại thời kỳ “ Thái học ”, Đại Tống phát triển ra thư viện thể hệ .”\n...\nTống triều .\nLộng lẫy hai năm .\nTại thượng đầu thế kỷ , khoa cử quy định bị phế trừ sau đó , hiện đại giáo dục cao đẳng thể hệ từ từ thiết lập .】\nCó thể có người sẽ nhớ , tại sao lại phế trừ khoa cử quy định ? Đằng sau đang giảng đến Tống triều cùng lúc Minh triều , chúng ta sẽ giảng giải .】\n“ Khoa cử bị phế trừ ?!”\nLý Thanh Chiếu nghe nói như thế , kinh ngạc nhìn màn trời .\n“ Tại sao lại phế trừ ?”\nGiờ khắc này , không chỉ là Lý Thanh Chiếu , Tống triều cùng Minh triều , còn có Đường triều người có học thức , đều khiếp sợ nhìn xem màn trời .\nCó một số người thậm chí trực tiếp choáng váng trên mặt đất , bởi vì bọn hắn thực sự nghĩ không ra khoa cử quy định bị phế sau đó , người có học thức nên đi nơi nào đi ?\n...\nMinh triều .\nVĩnh Lạc bảy năm .\n“ Khoa cử bị phế , hẳn là có tốt hơn tuyển bạt quy định a ?”\nChu Cao Sí nghe màn trời ý tứ , khoa cử tựa hồ đã bị phế trừ rất lâu .\nNhưng khoa cử bị phế , hậu thế còn có thể phát triển tốt như vậy , đó nhất định là có so khoa cử tốt hơn tuyển bạt nhân tài phương thức .\nNếu như dùng một câu nói đơn giản để giải thích , đó chính là khoa cử tuyển chọn , ngoại trừ sẽ chi, hồ, giả, dã phế vật , còn có thể tuyển bạt ra cái gì ?】\nCâu nói này mặc dù rất khó nghe , nhưng sự thật như thế .】\n“ Ha ha !!!”\nNghe nói như thế , Chu Lệ sửng sốt một chút , sau đó cười ha ha !\n...\nHiện đại thời không .\n“ Chúng ta bây giờ nhìn thấy , là khoa học nông nghiệp viện học sinh .”\n“ Bọn hắn chính là chuyên môn nghiên cứu nông nghiệp nhân tài . “”\n“ Phía trước các ngươi hâm mộ những cái kia cao sản lượng hạt giống , chính là bọn hắn nghiên cứu ra được .”\nMột chỗ thí nghiệm ruộng , Lý Ân Phàm đưa tay chỉ chỉ trong ruộng bận rộn lão sư cùng các học sinh .\n“ Nói thật , ta bây giờ vô cùng muốn gặp một người .”\n“ Gặp ai ? Gặp Khổng Tử .”\n“ Ta rất muốn hỏi hỏi hắn , mình tại Xuân Thu Chiến Quốc thời kì dạy bảo đệ tử đã nói , bị hai ngàn năm người có học thức tiêu chuẩn , là cảm thụ gì ?”\n“ Một ít lời , thật là bị những người kia lặp đi lặp lại nghiên cứu hai ngàn năm .”\n“ Càng vì hơn ích lợi của mình , đủ loại xuyên tạc Khổng Tử lão nhân gia ông ta lời nói .”\nNói đến đây , Lý Ân Phàm lắc đầu , rất là bất đắc dĩ nói :\n“ Cũng thực sự là cảm phiền có ít người , tiền nhân xuyên tạc qua mà nói , hậu nhân lại xuyên tạc ...”\n“ Khổng Tử hắn lão nhân gia được tôn sùng là Thánh Nhân , hậu thế hai ngàn năm , vậy mà không có một người vượt qua hắn , chỉ có một người có thể miễn cưỡng cùng hắn bình khởi bình tọa .”\n...\nXuân Thu Chiến Quốc thời kì .\nLỗ quốc .\n“ Ta mà nói , bị xuyên tạc hai ngàn năm ?”\n“ Vì lợi ích của mình , liền đủ loại xuyên tạc lời ta từng nói ?”\nKhổng Khâu sắc mặt mờ mịt nhìn xem màn trời .\n“ Hơn nữa , hậu thế hai ngàn năm vậy mà cũng không có một người có thể vượt qua ta ?”\nThời khắc này Khổng Tử bỗng nhiên cảm giác một hồi cực lớn bi ai .\nHai ngàn năm ! Hậu thế hai ngàn năm cũng không có người vượt qua chính mình ?\n...\nHiện đại thời không .\n“ Ta đoán bây giờ nhất định có người chửi ầm lên , nói ta hoàng khẩu tiểu nhi , còn nói luận cái gì Khổng Phu Tử ?”\nLý Ân Phàm nói đến đây cười cười , sau đó lại nói :\n“ Yên tâm , sau đó ta sẽ đem Khổng Tử mời đến hậu thế tới , cho hắn xem các ngươi một chút đến cùng đem hắn nói lời , xuyên tạc đến có ý tứ gì .”\n“ Đặc biệt là Đường triều , Tống triều , còn có Minh triều những cái kia nho gia người .”\nLý Ân Phàm nói đến đây , nhìn xem trước mắt hư ảo màn hình , thản nhiên nói :\n“ Xem Khổng Tử đã nói , là các ngươi nói rất đúng , vẫn là Khổng Tử hắn lão nhân gia nói rất đúng .”\n...\nĐường triều .\nTrinh Quán bảy năm .\n“ Hắc hắc !!”\nTrình Tri Tiết nhìn có chút hả hê nhìn xem bên cạnh đám kia lặng ngắt như tờ , lời gì cũng không dám nói các văn thần .\n“ Phốc phốc !”\nUất Trì Kính Đức cũng là nhịn không được cười ra tiếng .\nCác võ tướng phần lớn nhìn có chút hả hê .\nPhía trên đang ngồi Lý Thế Dân ngược lại có chút bất đắc dĩ lắc đầu .\nMặc dù hắn rất chán ghét những thế gia kia , nhưng nho gia chuyện , liền thật sự đơn giản như vậy sao ?\nNếu như không có từng đời một hoàng đế tôn sùng , nho gia làm sao lại đi đến vị trí kia ?\nNhư vậy vấn đề tới , các hoàng đế , tại sao muốn tôn sùng nho gia đâu ?!\n“ Sau đó sợ rằng phải đại loạn một ít thời gian .”\n...\nHiện đại thời không .\n“ Ta tin tưởng bây giờ Khổng Tử hẳn là tại nhìn màn trời a ?”\n“ Có lẽ ngươi bây giờ rất nghi hoặc , hậu thế đem ngươi mà nói , xuyên tạc đến trình độ nào .”\nLý Ân Phàm trầm tư một hồi , sau đó chậm rãi nói :\n“ Đánh ngã Khổng Gia Điếm , cứu ra Khổng Phu Tử .”\n“ Đây là hậu thế chúng ta toàn quốc một vị lão sư , đã nói .”\n“ Tin tưởng câu nói này , hẳn là có thể cho ngươi đáp án .”\nNói xong , Lý Ân Phàm chắp tay sau lưng , chậm rãi đi ở trong sân trường .\n“ Đến nỗi chúng ta bây giờ còn có học hay không Luận Ngữ cùng nho gia ?”\n“ Chỉ là học một chút kinh điển .”\n“ Tỉ như nói : Ba người đi , tất có thầy ta chỗ này .”\n“ Tiếp đó chính là Hàn khỏi bệnh 《 Sư Thuyết 》 chờ đã .”\n“ Những thứ này kinh điển chúng ta đều đang học .”\n“ Những cái kia cặn bã ? Hoặc có lẽ là rác rưởi ? Chúng ta đương nhiên là ném đi mất !”\n“ Tỉ như nói Tống triều chu hi một ít sách , chúng ta đều ném đi mất .”\n“ Đương nhiên , các triều đại đổi thay đối với Luận Ngữ xuyên tạc , đối với nho gia kinh điển chú giải cái gì .”\n“ Chúng ta đều ném đi mất , không tiếp tục học .”\n“ Dù sao , nếu là những thứ này đều đang học lời nói .”\nLý Ân Phàm dừng bước lại , nhìn xem màn trời , bình tĩnh nói :\n“ Chúng ta đến cùng học chính là nho gia kinh điển , vẫn là học những người kia tư tưởng ?”\n...\nMinh triều .\nHồng Vũ mười năm .\nChúng ta đến cùng học chính là nho gia kinh điển , vẫn là học những người kia tư tưởng ?】\nNghe được câu này , Chu Tiêu lập tức liền sững sờ tại chỗ .\n“ Đúng vậy a , ta đến cùng học chính là nho gia kinh điển , vẫn là học tập tư tưởng của bọn hắn ?”\n“ Khổng Phu Tử , lời hắn nói , thật là ý tứ kia sao ?”\n“ Bọn hắn đánh Khổng Tử cờ hiệu , tới nói , đây là Khổng Tử đã nói ...”\n“ Hơn nữa , còn nói đây mới là Khổng Tử nguyên ý ...”\nNói đến đây , Chu Tiêu một chút liền lý giải đến trong đó lôgic mâu thuẫn .\n...\nXuân Thu Chiến Quốc thời kì .\nLỗ quốc .\n“ Đánh ngã Khổng Gia Điếm , cứu ra Khổng Phu Tử ?”\nThời khắc này Khổng Tử , nghe được câu này , có một chút vui mừng , nhưng càng nhiều , lại là phẫn nộ .\nVô cùng phẫn nộ !\nPhẫn nộ ở phía sau thế đến cùng đem lời của mình đã nói , xuyên tạc đến trình độ nào , mới khiến cho hậu nhân muốn nói ra như vậy .\n“ Cũng được , liền để chúng ta chờ đi , tổng hội biết đến ...”\nKhổng Tử cố nén nộ khí , khuyên bảo chính mình nhẹ nhàng tâm tình .\n...\nMinh triều .\nVĩnh Lạc bảy năm .\nNơi này chính là đời sau bệnh viện công !】\nĐến nỗi cái gì là bệnh viện công ? Các ngươi hậu thế phái người tới học tập thời điểm , tự nhiên sẽ biết đến , ta liền không giải thích .】\nNhìn , đó chính là Tần triều công chúa , thắng Âm Mạn .】\nMàn trời phía trên , Lý Ân Phàm chỉ vào mặc đồng phục y tá một nữ tử , nhẹ nói .\n“ Cái này ...”\nChu Cao Sí kinh ngạc nhìn trong bệnh viện hết thảy sự vật .\n“ Công lập ? Đó có phải hay không còn có tư nhân ?”\nChu Lệ rất dễ dàng liền từ trong tên đoán được một ít gì .\n“ Nói như vậy mà nói , cái kia công lập , có phải hay không triều đình mở bệnh viện ?”\n...\nHán triều .\nNguyên thú 4 năm .\nBên kia bận rộn dọn đồ , chính là Tần triều công tử cao .】\nCó thể có người rất nghi hoặc , tại sao muốn học tập khuân đồ ?】\nBởi vì đây là nơi này lớn nhất hậu cần tụ tập chuyển trung tâm .】\nĐến nỗi cái gì là hậu cần ? Tin tưởng Hộ bộ quan viên , còn có võ tướng , hẳn là không xa lạ gì .】\nChuyên chở cùng cất vào kho , có thể nói là quan trọng nhất .】\nLưu Triệt nhìn xem cái kia ra ra vào vào , một chiếc xe tiến , một chiếc xe ra tình huống , bừng tỉnh đại ngộ nói :\n“ Thì ra là thế , hậu thế gọi hậu cần sao ?”\n“ Hàng hóa lưu chuyển ? Hàng hóa di động ? Hướng thủy một dạng di động ?”\n“ Tên chính xác rất khít khao ...”\nLưu Triệt hạ quyết tâm , nhất định phải làm cho người đi học đời sau hậu cần .\nDù sao thứ này , hắn là quá hiểu , hậu cần một khối này , hắn thật là có trọn vẹn nhận thức .\n...\nHiện đại thời không .\n“ Hôm nay mang các ngươi nhìn hiện đại những cơ sở này ngành nghề .”\n“ Trong đó , những thứ này ngành nghề , có thể nói là hiện đại cơ sở điểm tựa .”\n“ Không có những thứ này ngành nghề , hoàn toàn có thể nói , liền không có chúng ta bây giờ phồn vinh hậu thế .”\n“ Trong đó , nguồn năng lượng , giao thông , thông tin , cung cấp nước , nguyên vật liệu Vẫn là tối cương tính , phổ biến nhất nghĩa “ Hiện đại cơ sở ngành nghề ”.”\nThời gian một ngày , Lý Ân Phàm chạy một lượt Tần triều mười người đang tại học tập ngành nghề .\n“ Đương nhiên , cũng không phải nói các ngươi phái tới người , nhất định muốn học tập những thứ này .”\n“ Đây chỉ là ta đề cử , nếu như các ngươi còn nghĩ học tập những thứ khác ? Đương nhiên cũng có thể .”\nMở cửa phòng , Lý Ân Phàm đi vào gian phòng , đi đến tủ lạnh bên cạnh , mở tủ lạnh ra cầm một bình nước khoáng .\n“ Hô !!”\nDùng sức rót một miệng lớn , Lý Ân Phàm lập tức cảm giác thư thái rất nhiều .\n“ Đến nỗi bây giờ , chúng ta đem rút ra vị thứ hai đi tới đời sau Đế Vương .”\n...\nHán triều .\nHán bảy năm .\n“ Cuối cùng bắt đầu vị thứ hai .”\nNhìn một chút buổi trưa , Lưu Bang cũng cảm giác có chút mệt mỏi .\nHảo , ngừng !】\nChúc mừng vị thứ hai Đế Vương , Hán Thái tổ Cao Hoàng Đế , Lưu Bang !】\n“ A ?!”\nNghe được tên của mình , Lưu Bang sững sờ .\n“ Chúc mừng bệ hạ !!!”\nPhía dưới rất nhiều đại thần , vội vàng hướng về phía Lưu Bang cung kính hành lễ chúc mừng .\n“ Thực sự là chính là ông ?”\nLưu Bang còn có chút không thể tin được .\n“ Hậu thế không có trùng tên a ?”\n“ Bệ hạ , Hán Thái tổ Cao Hoàng Đế , đại hán đằng sau , còn có người dám cùng ngươi trùng tên sao ?”\nTiêu Hà gương mặt bất đắc dĩ .\n......', 'output\\mp3\\Màn Trời Quyền Lực Diễn Biến Cùng Truyền Thừa\\0059_Thứ 59 chương Quá độ chương tiết (4K đại chương ).mp3', '2026-09-01T22:26:17.639855+00:00', 'completed', 'completed', 14426, 14426),
	(65, 7, '7649558884826219033', 60, 'Thứ 60 chương Hạng Vũ tại Hàm Dương đến cùng làm cái gì?', 'Thứ chương Hạng Vũ tại Hàm Dương đến cùng làm cái gì ?\n( Đại lão khen thưởng , tăng thêm một chương .)\nHiện đại thời không .\nLý Ân Phàm sáng sớm liền rời giường , chuẩn bị nghênh đón Lưu Bang đến .\nGõ gõ !!\n“ Vào đi .”\nLý Ân Phàm mở cửa phòng , Mông Điềm cùng Phù Tô hai người , mang theo 4 người phân bữa sáng đi đến .\nThả xuống bữa sáng , Mông Điềm dùng hỏi thăm ngữ khí đối với Lý Ân Phàm nói :\n“ Tiên sinh , đêm qua ngươi nhắc nhở chúng ta sớm một chút tới , là tới nghênh đón vị kia Hán triều khai quốc hoàng đế sao ?”\nMông Điềm hơi nghi hoặc một chút không hiểu , vì cái gì nghênh đón Hán triều hoàng đế , muốn để hai người bọn họ tới .\nĐặc biệt là công tử Phù Tô , hắn rất là nghi hoặc , cái này cùng hắn có quan hệ gì ?\nKỳ thực đừng nói Phù Tô , Mông Điềm cảm giác , hẳn là cũng cùng mình không có quan hệ gì a ?\n“ Có một số việc , có thể cần để cho các ngươi biết .”\nLý Ân Phàm cầm lấy bữa sáng , cắn một cái bánh bao , sau đó lại nói :\n“ Huống chi hôm nay thứ bảy nghỉ định kỳ , các ngươi cũng nên nghỉ ngơi một chút .”\n“ Khổ nhàn kết hợp , đừng một ngày căng thẳng .”\nNghe được Lý Ân Phàm lời nói , Mông Điềm cùng Phù Tô hai người nhìn lẫn nhau một cái , quyết tâm bên trong nghi hoặc , không nói gì nữa .\n“ Tốt , không sai biệt lắm đã đến giờ .”\nLý Ân Phàm đứng lên , đi đến phòng khách chỗ trống trải , trực tiếp mở ra quang môn .\nQuang môn chỗ , chậm rãi xuất hiện một vị ước chừng bốn năm mươi tuổi nam tử .\n“ Chỉ có một người ?!”\nPhù Tô kinh ngạc nhìn quang môn .\n“ Hừ hừ ...”\nLưu Bang ngâm nga bài hát âm thanh , thoải mái nhàn nhã đi ra quang môn .\n“ Các ngươi khỏe a !”\nÁch ?!\nLý Ân Phàm , Mông Điềm , Phù Tô 3 người nghe nói như thế , lập tức sững sờ .\n“ Như thế nào ? Hậu thế không phải như vậy ân cần thăm hỏi sao ?”\nNhìn thấy bọn hắn ngây người , Lưu Bang vô cùng nghi hoặc không hiểu .\n“ A , đúng , hậu thế là như thế này ân cần thăm hỏi .”\nLý Ân Phàm vội vàng đi đến Lưu Bang trước mặt , nhẹ nói :\n“ Ngươi tốt , Hán Thái tổ cao hoàng đế .”\n“ Ai !! Đừng nói như vậy , đừng gọi ta thụy hào cùng miếu hiệu , ta cảm giác có chút ghê rợn .”\n“ Bảo ta vô lại là được rồi !”\nLưu Bang rất là tùy ý hướng về phía ba người nói , sau đó tò mò nhìn bên trong căn phòng đồ vật .\nA ?!\nLý Ân Phàm mộng bức nhìn xem Lưu Bang , hắn có chút hoài nghi lỗ tai của mình có phải hay không xảy ra vấn đề gì ?\nLưu Bang để cho ta kêu hắn cái gì ? Vô lại ?\n“ Như thế nào ? Không đúng sao ?”\n“ Lúc đó tại bái huyện , bọn hắn đều gọi ta như vậy .”\nNghe nói như thế , Lý Ân Phàm lập tức dở khóc dở cười nhìn xem Lưu Bang nói :\n“ Ngươi coi đó đến tột cùng là có nhiều làm người ta ghét a .”\nLưu Bang sững sờ , nghe vậy lập tức có chút ngượng ngùng .\nHắn lúc đó quả thật có chút làm người ta ghét , mới khiến cho bái huyện người địa phương cho hắn lấy một cái tước hiệu như vậy .\n“ Ta vẫn gọi ngươi Quý ca a , ca tại chúng ta hậu thế , đã là huynh trưởng ý tứ .”\n“ Được chưa !”\nLưu Bang gật đầu một cái , không có cự tuyệt .\n“ Quý ca , ngươi hẳn là cũng phát hiện , ta không có mở ra màn trời .”\nSau đó , Lý Ân Phàm thần sắc , bỗng nhiên nghiêm túc .\n“ Ân ... Chính xác phát hiện , ta vẫn bỗng nhiên trông thấy ánh sáng môn xuất hiện , mới đi tới .”\nLưu Bang tựa hồ ý thức được cái gì , thần sắc đồng dạng nghiêm túc .\nLý Ân Phàm đem Lưu Bang nghênh đón đến sofa ngồi xuống , sau đó cho hắn cầm một phần bữa sáng , lại cầm một bình nước khoáng .\nThấy thế , Lưu Bang không có ngượng ngùng , trực tiếp bắt đầu ăn .\n“ Quý ca , ta muốn hỏi một chút , Hạng Vũ trước kia đến cùng tại Hàm Dương làm cái gì ?”\n“ Ngươi lại đáp ứng lão Tần người cam kết gì ?!”\nLời này vừa ra , Lưu Bang khẽ giật mình , sau đó thần sắc vô cùng nghiêm túc .\nBên cạnh Phù Tô cùng Mông Điềm , lúc này tựa hồ ý thức được cái gì , nghiêm túc nhìn xem Lưu Bang .\n“ Ngươi đang nói cái gì ? Ta như thế nào nghe không rõ ?”\nLưu Bang tựa hồ ý thức được sự thất thố của mình , vội vàng giả vờ bình thường bộ dáng .\n“ Ai ... Quý ca , phía trước ta nói , màn trời không có mở ra , bây giờ chỉ chúng ta 4 người .”\n“ Cho nên , ngươi không cần giấu diếm .”\nLý Ân Phàm thở dài một hơi , nhẹ giọng đối với Lưu Bang nói .\n“ Ngươi là thế nào biết đến ?”\nLưu Bang thả ra trong tay bánh bao , thần sắc nghiêm túc hỏi .\n“ Các ngươi muốn giấu diếm nhiều lắm , cũng tạo thành một loại tình huống , cuối Tần loạn thế , rất nhiều nơi lôgic là hoàn toàn không thông .”\n“ Trước tiên là nói về đơn giản nhất .”\nLý Ân Phàm quay đầu nhìn Phù Tô cùng Mông Điềm , nhẹ nói :\n“ Các ngươi hẳn là nhìn qua Tư Mã Thiên viết 《 Sử Ký 》, bên trong không có ghi chép Phù Tô mẹ đẻ , Thủy Hoàng vương hậu cùng hoàng hậu đúng không ?”\nMông Điềm cùng Phù Tô nghiêm túc gật đầu một cái .\n“ Vậy các ngươi không có chú ý tới một chuyện sao ? Ngoại trừ Phù Tô mẹ đẻ , Thủy Hoàng hơn 20 đứa bé , bọn hắn mẹ đẻ là ai ?”\nLời này vừa nói ra , Phù Tô cùng Mông Điềm vụt một cái đứng lên , kinh hãi nhìn xem Lý Ân Phàm .\nLý Ân Phàm không để ý tới Phù Tô cùng Mông Điềm , sau đó lại nhìn về phía Lưu Bang , nhẹ nói :\n“ Tư Mã Thiên viết 《 Sử Ký 》, bên trong có một thiên Kinh Kha giết Tần , hắn ở bên trong minh xác đánh dấu .”\n“ Chuyện này , là Thủy Hoàng hầu y , Hạ Vô Thả lúc tuổi già nói cho Công Tôn Quý Công cùng đổng sinh , bọn hắn lại đem chuyện này kể lại cho Tư Mã đàm luận\n“ Tư Mã đàm luận cuối cùng nói cho con của mình , Tư Mã Thiên .”\n“ Quý ca , Hán triều vừa lập , các ngươi hẳn là tiếp nạp rất nhiều nguyên Tần triều quan viên a ?”\n“ Về sau Tư Mã Thiên viết 《 Sử Ký 》, hỏi vô số người , nhưng không có một người biết , Phù Tô mẹ đẻ , Thủy Hoàng hơn 20 hài tử mẹ đẻ , là ai ...”\n“ Ngươi cảm thấy , hợp lý sao ? Tư Mã Thiên là quên ? Vẫn là ngay lúc đó các ngươi , cố ý giấu diếm cái gì ?”\nLý Ân Phàm mà nói , nói đến đây , ngừng lại , sau đó nhìn về phía Lưu Bang .\nLưu Bang không nói gì , trầm mặc nhìn xem Lý Ân Phàm .\nĐây là cùng Lưu Bang tính cách hoàn toàn không hợp , cũng là Lưu Bang lên làm hoàng đế sau đó , cho tới bây giờ cũng không có đã làm .\nĐừng nói làm hoàng đế sau , Lưu Bang làm ra lần này động tác , một đời đều khó mà làm mấy lần .\nLý Ân Phàm tựa hồ nhìn ra Lưu Bang vẫn còn có chút không muốn nói , sau đó liền lại nói :\n“ Quý ca , ngươi tiến vào quan bên trong , làm Hán vương sau đó , thời gian ngắn ngủi , liền an định ba Tần .”\n“ Sau đó , thời gian mấy năm liền quét ngang thiên hạ .”\n“ Có lẽ có chút người cảm thấy rất bình thường .”\n“ Nhưng , hậu thế các triều đại đổi thay loạn thế , cũng không có lại xuất hiện khoa trương như thế tình huống .”\n“ Hơn nữa , đối thủ vẫn là Hạng Vũ !”\nNói đến đây , Lý Ân Phàm quay đầu nhìn về phía Mông Điềm , nhẹ giọng dò hỏi :\n“ Mông Điềm tướng quân , nhìn quãng lịch sử này thời điểm , ngươi không cảm thấy rất quen thuộc sao ?”\nQuen thuộc ?\nMông Điềm nhíu mày , nhớ lại chính mình từng xem sách sử .\nBỗng nhiên , Mông Điềm lộ ra vẻ khiếp sợ , nhìn xem Lý Ân Phàm .\n“ Ngươi nghĩ không tệ , lại một lần Đại Tần quét ngang thiên hạ phiên bản .”\n“ Quý ca ...”\nLý Ân Phàm lúc này nhìn về phía Lưu Bang , nhẹ nói :\n“ Có thể làm cho lão Tần người kiên định như vậy ủng hộ ngươi , ngươi hẳn là hứa hẹn cái gì a ?”\n“ Hơn nữa , cuối cùng còn đem quốc đô , ổn định ở quan bên trong , Trường An .”\n“ Trường An các ngươi có thể không rõ ràng ở đâu , nó tại nguyên Đại Tần Hàm Dương cung nam bộ trên cơ sở xây .”\nCâu nói sau cùng , Lý Ân Phàm là đối với Phù Tô cùng Mông Điềm nói .\n“ Có thể làm cho Quý ca ngươi yên tâm như thế đem quốc đô để ở chỗ này , thuyết minh ngươi rất yên tâm lúc đầu những cái kia lão Tần người .”\n“ Mặc kệ là lão Tần quý tộc , vẫn là lão Tần tầng dưới chót , ngươi cũng yên tâm bọn hắn .”\n“ Đây là không hợp tình lý ! Ngươi trước kia thế nhưng là người Sở , hơn nữa còn là tại Hạng Vũ thủ hạ !!!”\n...', 'output\\mp3\\Màn Trời Quyền Lực Diễn Biến Cùng Truyền Thừa\\0060_Thứ 60 chương Hạng Vũ tại Hàm Dương đến cùng làm cái gì.mp3', '2026-09-01T22:26:23.308151+00:00', 'completed', 'completed', 7605, 7605),
	(66, 7, '7649559466370662937', 61, 'Thứ 61 chương Vũ nhục', 'Thứ chương Vũ nhục\n( Đại lão khen thưởng , tăng thêm .)\nHiện đại thời không .\n“ Ai nha , người đời sau , cũng như ngươi như vậy thông minh sao ?”\nLưu Bang lắc đầu , rất là bất đắc dĩ nói .\nHắn biết , chính mình hôm nay xem ra là nhất định phải nói một điểm gì đó .\n“ Dù sao thật không hợp tình lý ! Quý ca .”\n“ Ngươi vào trong quan mới bao lâu ? Liền có thể để cho lão Tần người , kiên định như vậy ủng hộ ngươi ?”\n“ Ở trong đó ủng hộ cường độ , hậu thế rất nhiều người nhìn không ra , nhưng thời điểm ta phát hiện , mới phát giác được không thể tưởng tượng nổi .”\n“ Ngươi cùng lão Tần người không thân chẳng quen , dựa vào cái gì bọn hắn có thể như thế ủng hộ ngươi ?”\n“ Hơn nữa , ta phía trước phải nói có chút sai lầm ...”\n“ Ngươi căn cơ thế lực , hẳn không phải là bái huyện người của tập đoàn , hẳn là quan bên trong những cái kia lão Tần người .”\n“ Tiêu Hà , phiền khoái bọn hắn lợi hại hơn nữa , cũng cuối cùng chỉ là giống như ngươi từ bái huyện đi ra ngoài tầng dưới chót .”\n“ Đặc biệt là Tiêu Hà , hậu thế cảm thấy Tiêu Hà hậu cần làm sao như thế nào lợi hại ...”\nLý Ân Phàm nói đến đây , nhìn xem Lưu Bang , nhẹ nói :\n“ Thủ hạ của hắn , hẳn là trước kia quét ngang thiên hạ những người kia a ?”\n“ Dù sao như thế hậu cần , bọn hắn đã làm một lần , lần thứ hai liền càng thêm đơn giản .”\nLưu Bang không nói chuyện , chỉ là trầm mặc gật đầu một cái .\n“ Còn có Hàn Tín , hậu thế tán thưởng Hàn Tín điểm binh càng nhiều càng tốt ...”\n“ Thủ hạ sĩ quan , cũng hẳn là lão Tần người a ?”\n“ Dù sao , chuyện như vậy , bọn hắn cũng đã làm .”\nLúc này , Phù Tô cùng Mông Điềm chết lặng nhìn xem Lưu Bang .\nBọn hắn như thế nào cũng không nghĩ đến , trên sử sách Lưu Bang , có lẽ là dạng này thành công ?\n“ Từ phong Hán vương , đến thống nhất thiên hạ , thiết lập Hán triều , các ngươi biết Quý ca dùng bao lâu sao ?”\nMột câu nói kia , Lý Ân Phàm là hỏi Phù Tô cùng Mông Điềm .\n“ Chỉ dùng 4 năm !”\n“ Thời gian bốn năm , Quý ca liền bước đầu quét ngang thiên hạ , thành lập đại hán .”\n“ 4 năm !!!”\n“ Hậu thế có một câu nói , chiến báo sẽ gạt người , nhưng chiến tuyến sẽ không !”\n“ Cho nên , sách sử sẽ gạt người , nhưng thời gian và chiến tuyến , sẽ không gạt người !”\nNói xong câu đó , Lý Ân Phàm lại tiếp tục nói :\n“ Hán 3 năm thời điểm , cũng chính là trước công nguyên năm .”\n“ Hàn Tín đánh bại Ngụy , đại , triệu các nước sau , Quý ca ngươi nhiều lần rút đi Hàn Tín tinh binh , thậm chí trực tiếp xâm nhập Hàn Tín quân doanh cướp đi binh quyền .”\n“ Ngươi vô cùng tự tin , tự tin Hàn Tín không mang được những tinh binh này .”\nLúc này Lưu Bang bỗng nhiên mở miệng , nhìn xem Lý Ân Phàm hỏi :\n“ Ngươi là vì cái gì sẽ phát hiện trong này có vấn đề ?”\n“ Bởi vì hiện đại có một quốc gia , đồng dạng làm ra dạng này không hợp lý chuyện .”\n“ Cho nên liền để ta đã biết một sự kiện , tư bản bên trên không giải thích được sự tình , cái kia trong chính trị là chắc chắn có thể giải thích .”\nnăm , Rehmann huynh đệ ngân hàng bạo lôi , lão Mỹ cứu được rất nhiều công ty , tỉ như nói chắc chắn các loại .\nNhưng chính là không có cứu Rehmann huynh đệ ngân hàng .\nCứu Rehmann , chỉ cần ức , nhưng cứu chắc chắn tốn bao nhiêu ? Hơn một trăm tỉ !\nHơn nữa , đến bây giờ năm , Rehmann ngân hàng hố , đều còn tại lấp !!!\n“ Quý ca , ngươi là người Sở , ngươi sùng bái người là Tín Lăng quân Nguỵ Vô Kỵ .”\n“ Hậu thế có vô số người , nói ngươi mặc màu đen long bào , là bởi vì sùng bái Thủy Hoàng Doanh Chính .”\n“ Nhưng 《 Sử Ký 》 rõ ràng ghi chép , ngươi sùng bái là Tín Lăng quân Nguỵ Vô Kỵ .”\nSau đó , Lý Ân Phàm quay đầu lại nhìn xem Mông Điềm nói :\n“ Hơn nữa , còn có một cái không hợp lý chuyện , Mông Điềm tướng quân không biết ngươi phát hiện không có .”\n“ Sau khi ngươi chết , cái kia Mông gia quân đâu ?”\nSau đó , Lý Ân Phàm lại nhìn về phía Phù Tô nói :\n“ Còn có , ta không phải là nói Vương gia , Vương Tiễn tướng quân bọn hắn nói xấu .”\n“ Mông Điềm Mông Nghị bỏ mình , vương cách tiếp quản biên quân , cuối cùng chết trận .”\n“ Vương Tiễn tướng quân tằng tôn , vương nguyên , vương uy , cuối Tần chiến loạn phân gia chạy trốn , phân biệt khai sáng lang gia Vương thị cùng Thái Nguyên Vương thị .”\n“ Hơn nữa , còn hoạt động mạnh tại Đại Hán triều đường phía trên .”\nSau đó , Lý Ân Phàm lại lặp lại nói :\n“ Phân gia chạy trốn , còn khai sáng hai cái về sau đại thế gia .”\n“ Hai người vẫn là tách ra trốn , vậy mà đồng thời đều khai sáng về sau đại thế gia .”\nCuối cùng , Lý Ân Phàm thở dài một cái rồi nói ra :\n“ Cuối Tần , bây giờ người viết sử tái không hợp lý chỗ , thật sự nhiều lắm .”\n“ Một chỗ hai nơi có thể rất hợp lý , nhưng nhiều không hợp lý như vậy chỗ ? Hiển nhiên là không bình thường .”\n“ Lão Tần người liều chết ủng hộ ngươi , sau đó lại còn nhường ngươi yên tâm như thế .”\n“ Quý ca , đây chính là lớn nhất không hợp lý chỗ .”\n“ Vẫn là câu nói kia , ngươi là người Sở , ban đầu tại Hạng Vũ thủ hạ , trong thứ nhất tiến quan .”\n“ Nhưng cuối cùng để cho lão Tần người liều chết ủng hộ ngươi ...”\n“ Ngắn như vậy thời gian , vậy mà liền như thế tin tưởng ngươi ...”\nNói xong , Lý Ân Phàm nhìn xem Lưu Bang , chờ đợi hắn mở miệng .\nBên cạnh Mông Điềm còn có Phù Tô , rốt cuộc biết Lý Ân Phàm tại sao phải để bọn hắn tới đón tiếp Lưu Bang .\nLưu Bang thở dài một cái , ăn trong tay bữa sáng , nhìn xem Lý Ân Phàm nói :\n“ Ngươi hẳn còn có lời nói không nói a ? Đều cùng nhau hỏi a .”\n“ Nguyên Tần Quốc hậu cung Sở quốc thế lực , hẳn là rất nhiều cũng chưa chết a ? Cuối cùng hẳn là liên lạc ngươi cùng Hạng Vũ .”\n“ Chương Hàm , mang theo Hình Đồ Quân , cũng có thể lợi hại như vậy .”\n“ Lý từ , vương cách , Dương Hùng các loại Tần triều tướng lĩnh , hẳn là bị hố chết a ?”\nNói đến đây , Lý Ân Phàm bỗng nhiên cười đối với ba người nói :\n“ Sở tuy tam Hộ , vong Tần tất Sở ? Đây là cuối Tần một câu tiên đoán , nói là Sở quốc ẩn sĩ Sở Nam Công lưu lại .”\n“ Nhưng nếu là Sở quốc chỉ còn dư ba nhà , thật có thể diệt Tần ?”\nĐây không phải nói đùa là cái gì ? Ba nhà nhân khẩu , diệt Tần ?\n“ Sở quốc thế lực , hẳn là tại lúc đó còn rất khổng lồ .”\n“ Cho nên , ta chỉ muốn , rõ ràng sáu quốc đô diệt , Sở quốc cũng bị mất , cái kia ở đâu ra Sở quốc thế lực to lớn ?”\n“ Tiếp đó ta liền quay đầu phát hiện , thì ra thật sự còn có Sở quốc thế lực .”\n“ Đó chính là Đại Tần nội bộ ...”\n“ Cho nên ta liền hỏi mình .”\n“ Tần quốc tại trên đường thống nhất , thật sự đem Sở quốc hậu cung thế lực tiêu diệt sao ?”\n“ Lúc trước , Sở quốc thế lực thế nhưng là Tần quốc trên triều đình thế lực lớn nhất , làm sao có thể liền như vậy đơn giản từ trên xuống dưới , toàn bộ tiêu diệt ?”\n“ Hơn nữa , tiêu diệt trên triều đình thế lực lớn nhất , hẳn là sẽ tạo thành cực lớn rung chuyển .”\n“ Nhưng không có !”\n“ Tần quốc tại trong thống nhất , cũng không có phát sinh to lớn gì rung chuyển !”\n“ Chỉ là Lý Tín công phạt Sở quốc thời điểm , thất bại .”\n“ Nhưng trên triều đình ? Cũng không có xuất hiện bất ổn , hay là cực lớn rung chuyển .”\n“ Cho nên , ta chỉ muốn , Sở quốc thế lực còn tại Tần quốc , Tần quốc thống nhất thiên hạ , lớn mạnh Tần quốc , nhưng cùng lúc , cũng lớn mạnh Sở quốc thế lực .”\n“ Cũng chính là dạng này ...”\n“ Mới khiến cho những cái kia Tần triều đại thần , đến Hán triều , im lặng không nói !!!”\n...\nLưu Bang trầm mặc rất lâu , nghe xong Lý Ân Phàm lời nói , vỗ tay tán dương :\n“ Hậu thế thật đúng là lợi hại ...”\n“ Kỳ thực , ta chỉ cần cho các ngươi nói một chuyện , các ngươi nên có thể sợi rõ ràng có chuyện .”\n“ Đời sau sách sử , là thế nào ghi lại Hạng Vũ tiến Hàm Dương làm chuyện ?”\nLý Ân Phàm nghiêm túc hồi đáp :\n“ Thiêu Tần Cung Thất , hỏa ba tháng bất diệt .”\nNghe nói như thế , Lưu Bang dừng một chút , bình tĩnh nhìn Lý Ân Phàm nói :\n“ Đúng vậy a , hỏa ba tháng bất diệt ...”\n“ Cái kia nguyên lai Tần quốc tông miếu đâu ?”\nPhanh !!!\nPhù Tô cùng Mông Điềm lập tức đứng lên , kinh hoảng nhìn xem Lưu Bang .\n“ Ngươi nói là ?!!”\nLý Ân Phàm đồng dạng cũng là khiếp sợ nhìn xem Lưu Bang .\nHắn rốt cuộc biết , vì cái gì ba Tần Chi Địa lão Tần người , sẽ liều chết ủng hộ Lưu Bang .\nLưu Bang rất là bình tĩnh gật đầu một cái , sau đó lại nói :\n“ Hơn nữa Tần Cung Thất đều bị đốt đi , ở trong đó người đâu ?”\n“ Tử Anh bị giết , những người khác đâu ?”\nLời này vừa ra , Phù Tô cùng Mông Điềm thân thể một chút liền xụi lơ ở trên ghế sa lon , hai mắt vô thần nhìn lên trần nhà .\n“ Nữ quyến , đều để thủ hạ binh lính , vũ nhục a ?”\nLý Ân Phàm rất chật vật mở miệng nói ra .\nBởi vì chỉ có dạng này , ba Tần Chi Địa lão Tần người , mới có thể như thế ủng hộ Lưu Bang , một đợt lại một đợt liều chết .\nNguyên Tần Quốc tông miếu bị hủy , trong cung nữ quyến bị lăng nhục ...\nChớ nói chi là có lẽ có thể còn có những chuyện khác ...\nĐiều này cũng làm cho giải thích , vì cái gì Tần triều rất nhiều chuyện đều có ghi chép , nhưng đối với Thủy Hoàng hơn 20 đứa bé mẹ đẻ , lại không có một điểm ghi chép .\n“ Cho nên Quý ca , ngươi liền hứa hẹn lão Tần người ...”\nLưu Bang thở dài một cái , sau đó nặng nề gật đầu .\n“ Ai ... Đúng vậy a ...”\n“ Sách sử liền vẻn vẹn ghi lại giết Tần Vương Tử Anh , thiêu Hàm Dương cung , ba tháng bất diệt ...”\n“ Liền thật chỉ là đốt đi sao ?”\nLưu Bang lúc này cũng không cái gọi là nói hay không .\nMà lúc này giờ phút này , Lý Ân Phàm thật sự cảm thấy Hạng Vũ thua không oan , hoàn toàn là gieo gió gặt bão ...\nDù sao , Tần triều thống nhất thiên hạ đến diệt vong , vẻn vẹn mới qua mười lăm năm !\nNguyên thống nhất thiên hạ binh lính , tầng dưới chót sĩ quan , trung tầng tướng sĩ , chịu này vũ nhục , sẽ không động hợp tác sao ?\nNhững cái kia tầng dưới chót lão Tần người , sẽ trơ mắt nhìn sao ?\n......', 'output\\mp3\\Màn Trời Quyền Lực Diễn Biến Cùng Truyền Thừa\\0061_Thứ 61 chương Vũ nhục.mp3', '2026-09-01T23:25:00.804037+00:00', 'completed', 'completed', 9434, 9434),
	(67, 7, '7649560014390034969', 62, 'Thứ 62 chương Bất mãn cùng trung thành', 'Thứ chương Bất mãn cùng trung thành\nHiện đại thời không .\nLý Ân Phàm cũng chính là tại cuối Tần về vấn đề , mới phát hiện chính mình một số thời khắc quá mức nhị nguyên luận .\nKhông phải đen tức là trắng ...\nTại trong rất nhiều chuyện hắn có thể rõ ràng nhận thức đến không phải như vậy , nhưng ở trên một ít chuyện khác , hắn lại là như thế nhị nguyên luận .\n“ Lúc đầu Tần quốc , có lẽ có bất mãn Tần Vương , nhưng có lẽ còn là có rất nhiều trung thành với Tần Vương .”\n“ Cái này một số người chính là những cái kia tầng dưới chót lão Tần người cùng trung tầng lão Tần người .”\n“ Bọn hắn sẽ không để ý , cũng không muốn quan tâm thượng tầng đến tột cùng xảy ra chuyện gì .”\n“ Nhưng Tần quốc tông miếu bị hủy , Tần Vương nữ quyến cũng gặp vũ nhục , nội tâm của bọn hắn ...”\nChỉ có thể nói có một số việc đúng là không dễ nhớ tái xuống .\nNhưng những chuyện này bình thường sao ? Có lẽ có người sẽ nhớ , rất bình thường , một cái vương triều thời kì cuối , xảy ra chuyện như vậy , quá bình thường .\n“ Tần quốc khi thống nhất Lục quốc , cũng không có hủy hoại những cái kia các nước chư hầu tông miếu , cũng thiện đãi những quý tộc kia ...”\nNói đến đây , Lý Ân Phàm thật là không biết nên như thế nào mở miệng .\nHắn có thật nhiều ngờ tới , nhưng cuối cùng không nghĩ tới , đáp án lại là đơn giản như vậy , đơn giản đến hậu thế chuyện như vậy đều thường xuyên phát sinh .\n“ Hắn làm sao dám ?! Làm sao dám đó a ?!!”\nPhù Tô đứng lên , vẫy tay , tức giận rống to .\nLuôn luôn nho nhã hắn , khi nghe đến tin dữ như thế , cũng khống chế không nổi tâm tình của mình .\nTông miếu bị hủy , điều này đại biểu cái gì ? Đã không cần nói cũng biết .\nChớ nói chi là nữ quyến vấn đề .\nHậu thế sách sử một chút cũng không có ghi chép bọn hắn mẹ đẻ , cái này còn không có thể nói rõ vấn đề sao ?\n“ Công tử !!”\nMông Điềm vội vàng giữ chặt Phù Tô , lại đột nhiên phát hiện , Phù Tô lúc này trên mặt , trong mắt giống không cần tiền , không ngừng lăn xuống xuống .\n“ Hắn làm sao dám ?”\nPhù Tô tê liệt ngã xuống tại Mông Điềm trong ngực , lẩm bẩm nói .\nNói một chút , Phù Tô tâm lý tuôn ra một cỗ cực lớn hối hận , hắn hối hận tại trong lịch sử chính mình vì sao muốn tự vẫn ?\nNếu như mình không có tự vẫn , Hạng Vũ hắn dám làm thế này sao ?\nNhưng chính là bởi vì Thủy Hoàng Doanh Chính không có con , Tần quốc không có người dẫn đầu , Hạng Vũ mới như vậy không chút kiêng kỵ a ?\nTrả thù tại Tần quốc ?\n“ Quý ca , nếu như ta không có đoán , Hạng Vũ làm như vậy , là cho một số người , giao đầu danh trạng a ?”\n“ Nhập đội ?”\nNghe được nhập đội cái từ này , Lưu Bang nghi hoặc nhìn Lý Ân Phàm .\n“ Đây là đời sau một cái từ , chỉ Gia nhập vào bang phái lúc lập giấy sinh tử xuất từ tiểu thuyết 《 Thủy Hử Truyện 》, bây giờ cũng thường dùng tới Ví dụ tiến vào cái nào đó vòng tròn trả ra đại giới\n“ Ngươi nghĩ tiếp nhận ta , nhưng không tín nhiệm ta làm sao bây giờ ? Đó là đương nhiên là giao một phần nhập đội .”\n“ Tỉ như nói ám sát người nào đó , đem ta nhược điểm nắm ở trong tay .”\nNghe đến đó , Lưu Bang bừng tỉnh đại ngộ , nhẹ nói :\n“ Thì ra là thế !”\n“ Hạng Vũ có phải hay không giao đầu danh trạng , kỳ thực ta cũng không hiểu .”\n“ Bởi vì hắn là sau tiến nhập Hàm Dương , tiến vào Hàm Dương sau đó , liền bắt đầu trắng trợn đồ sát , thiêu huỷ .”\n“ Phía trước ta cùng với Trương Lương bọn hắn đàm luận qua chuyện này , lúc đó chúng ta kết luận là , hạng lương chết , không có người lại gò bó hắn .”\nDạng này sao ? Lý Ân Phàm cúi đầu trầm tư , một lát sau mới lên tiếng :\n“ Từ nhỏ bị giáo dục muốn tiêu diệt Tần , sau khi lớn lên gò bó không tại , tiến vào Hàm Dương , mộng tưởng đang ở trước mắt , liền phóng túng chính mình ?”\nNày ngược lại là vô cùng có khả năng , dù sao nhập đội vật này , kỳ thực tại tạo phản thời điểm , liền đã giao .\n“ Không được , ta muốn đi nói cho a cha !”\nPhù Tô đứng lên , vội vàng nói .\n“ Công tử !!”\nMông Điềm kéo lại Phù Tô , để cho hắn ngồi xuống .\n“ Bệ hạ kỳ thực đã biết .”\nÂn ?\nGiờ khắc này , không chỉ là Phù Tô , Lý Ân Phàm cùng Lưu Bang đều nghi hoặc nhìn Mông Điềm .\nThủy Hoàng biết ? Hắn là thế nào biết đến ?\n“ Thủy Hoàng khuyên bảo qua ta , phải phòng bị lấy Vương gia .”\nNhìn 3 người đều nhìn mình chằm chằm , Mông Điềm nói ra đáp án .\n“ Dạng này sao ?”\nLý Ân Phàm khẽ gật đầu một cái .\nMặc dù vương cách đúng là chết trận , nhưng Vương gia , về sau cuối cùng vẫn là trở thành hai cái đại thế gia .\nCứ như vậy , thân là Tần triều hoàng đế Thủy Hoàng , còn thế nào không giữ lại chút nào tin tưởng Vương gia ?\nHuống chi , Mông Điềm cùng Mông Nghị thời điểm chết , là vương cách tiếp quản biên quân ...\nỞ trong đó , cũng rất tế nhị ...\nChỉ có thể nói đều có các cách nhìn , Thủy Hoàng là thế nào nhìn ? Lý Ân Phàm không rõ ràng .\nNhưng từ hắn góc nhìn đến xem , Vương gia nhất định là thỏa hiệp , mới có thể dạng này .\nHoặc có lẽ là , bọn họ đứng ở vị trí nào ?\nMông gia đứng ở Phù Tô sau lưng , mới có thể tạo thành trong lịch sử kết cục như vậy .\nCái kia Vương gia đâu ?\nBọn hắn lúc đó , là đứng tại ai bên cạnh ?\n“ Bệ hạ trở về vẫn không có động tác , hẳn là đoán được , bây giờ trên triều đình , địa phương phía trên , còn có số lớn nguyên Sở quốc thế lực .”\nĐiểm này , ngược lại là Lưu Bang gật đầu một cái .\n“ Quả thật là như thế , nhưng cụ thể có bao nhiêu ? Ta ngược lại thật ra không rõ ràng , lúc đó bọn hắn liên lạc , một mực là Hạng Vũ bọn người .”\n“ Dù sao , lúc đó ta vẫn chỉ là đình trưởng xuất thân .”\nNói đến đây , Lưu Bang tự giễu cười cười .\n“ Thế nhưng chính là đình trưởng xuất thân , mới khiến cho lão tần nhân sơ bộ tín nhiệm ngươi , Quý ca ...”\nLý Ân Phàm nói đến đây lời nói thời điểm , rất là ý vị thâm trường .\n“ Ân ?”\nLưu Bang nghe đến lời này , chính là sững sờ .\n“ Dù sao , đình trưởng dù nói thế nào , cũng là Tần triều quan .”\n“ Thì ra là thế ...”\nDĩ vãng nội tâm rất nhiều nghi hoặc , Lưu Bang lần này cuối cùng sợi rõ ràng .\n“ Huống chi ngươi cũng là thứ nhất tiến Hàm Dương , hơn nữa còn ước pháp tam chương , đối với tầng dưới chót cùng trung tầng không đụng đến cây kim sợi chỉ .”\n“ Điểm này , tại lúc đó quá trọng yếu , cũng làm cho những cái kia lão Tần người vô cùng tín nhiệm ngươi .”\n“ Nếu như không có lần thứ nhất tiến Hàm Dương kinh nghiệm , sau này những cái kia lão Tần người , chỉ sợ căn bản cũng sẽ không tìm ngươi .”\nĐúng lúc này , Phù Tô bỗng nhiên đứng lên , hướng về Lưu Bang làm một đại lễ , hết sức chăm chú nói :\n“ Cảm tạ !!!”\n“ A ?!”\nLưu Bang lập tức có chút chân tay luống cuống , hắn chẳng thể nghĩ tới , Phù Tô vậy mà lại hướng mình nói lời cảm tạ ?\nNguyên Tần triều công tử , vậy mà lại hướng mình cái này tạo phản người nói cảm ơn ?\n“ Cảm tạ !”\nMông Điềm lúc này cũng đứng lên , hướng về Lưu Bang làm một đại lễ .\n“ Quý ca , ngươi liền thụ lấy a .”\nLý Ân Phàm ở bên cạnh , nhẹ giọng mở miệng nói ra .\n“ Dù sao dù nói thế nào , ngươi cũng chính xác vì bọn họ báo thù .”\nLần này , Lưu Bang có chút ngượng ngùng , sau đó không câu chấp nói :\n“ Này ! Lúc đó cũng là bởi vì đáp ứng những người kia .”\n“ Huống chi , trong nội tâm của ta , cũng là có một chút ý nghĩ .”\nLúc này , Lý Ân Phàm ở một bên bỗng nhiên nói :\n“ Là Hồng Môn Yến sau đó , phải không ?”\n“ Đúng vậy a ...”\nNghe được Hồng Môn Yến ba chữ này , Lưu Bang cảm khái gật đầu một cái .\n“ Dù sao lúc đó ta dù nói thế nào , cũng là thứ nhất tiến Hàm Dương .”\n“ Nhưng Hạng Vũ vậy mà như thế đối với ta ?”\n...', 'output\\mp3\\Màn Trời Quyền Lực Diễn Biến Cùng Truyền Thừa\\0062_Thứ 62 chương Bất mãn cùng trung thành.mp3', '2026-09-01T23:25:06.362456+00:00', 'completed', 'completed', 7255, 7255),
	(68, 7, '7649560621150634521', 63, 'Thứ 63 chương Lập lại một lần', 'Thứ chương Lập lại một lần\nHiện đại thời không .\nNgay lúc đó Lưu Bang có thể nói là hăng hái .\nThứ nhất tiến Hàm Dương , hơn nữa đứng tại trong Chương Đài cung .\nNhưng Hạng Vũ , muốn giết chính mình , liền giết chính mình ?\nHồng Môn Yến sau đó , có thể nói chuyện xảy ra lúc đó thường xuyên gấp khúc tại Lưu Bang não hải .\nSau đó Lưu Bang biểu hiện ra đối với cái này vẻ không đáng kể .\nThật là không quan trọng sao ?\nMuốn thật sự không quan trọng , hắn sau đó cũng sẽ không phản kháng Hạng Vũ .\nLý Ân Phàm cũng nghĩ đến điểm này , nhưng nói như thế nào đây ? Chỉ có thể đối với cái này lắc đầu .\nĐối đãi như vậy người khác dưới tình huống , còn để cho hắn chạy thoát người , lưu lại cho mình một cái tai hoạ ngầm .\nCái này nên nói Hạng Vũ tự tin ? Tự ngạo ? Tự đại ? Vẫn là ngu xuẩn ?\nTại Lý Ân Phàm xem ra , ngu xuẩn muốn chiếm một bộ phận lớn .\nHạng lương sau khi chết , Hạng Vũ thật là không có người xen vào nữa hắn , trực tiếp phóng túng , muốn thế nào thì làm thế đó ...\n“ Cái kia mặc màu đen long bào ? cũng đúng ?”\n“ Ân ... Ta lúc đó đáp ứng bọn hắn , đây là yêu cầu của bọn hắn một trong .”\nLý Ân Phàm nghe nói như thế , cũng khẳng định nội tâm mình một cái ngờ tới .\n“ Đây là đem ngươi trở thành một cái khác “ Tần Vương ”.”\n“ Cũng đem đại hán , coi là “ Tần ” Kéo dài ”\nLưu Bang không nói chuyện , chỉ là gật đầu một cái .\nBên cạnh Phù Tô cùng Mông Điềm , cũng có chút ngạc nhiên nhìn xem Lưu Bang .\nBọn hắn không nghĩ tới , lão Tần thí sinh một vị khác “ Tần Vương ”, lại chính là Lưu Bang .\n“ Hán nhận Tần Chế ... Thì ra nhận không chỉ là chế ...”\nChỉ sợ cũng chính là Lưu Bang đáp ứng lão Tần người sau đó , hắn mới chân chân chính chính có mình căn cơ .\nNày căn cơ là ai ? Chính là những cái kia lão Tần người .\nSau đó ba Tần Chi Địa , cũng biểu hiện ra tử trung .\nCũng làm cho Lưu Bang tín nhiệm đem quốc đô đặt ở Trường An , cái này nguyên lai Hàm Dương cung miền nam vị trí .\n“ Tiên sinh , ngươi ban đầu , là thế nào phát giác được cuối Tần có vấn đề ?”\nMông Điềm lúc này nhìn về phía Lý Ân Phàm . Nhẹ giọng dò hỏi .\nLưu Bang cùng Phù Tô hai người , cũng cùng nhau nhìn về phía Lý Ân Phàm .\n“ Tại Minh triều khai quốc hoàng đế Chu Nguyên Chương phía trước , liền Quý ca thân phận của ngươi thấp nhất .”\n“ Đình trưởng ...”\n“ Xem còn lại những người kia , ai không phải Nguyên Lục quốc quý tộc ?”\n“ Bọn hắn có thực lực , cũng có tài lực cùng nội tình , để cho bọn hắn tranh đoạt thiên hạ .”\n“ Nhưng Quý ca ngươi đây ?”\nCũng chính là lúc này , Lý Ân Phàm rõ ràng , vì cái gì còn lại sáu quốc hội thất bại .\nBởi vì Lưu Bang kế thừa , là chân chính nguyên Tần quốc đại bộ phận thế lực .\nCuối Tần thiên hạ đại loạn , Lưu Bang nhất thống thiên hạ .\nCó lẽ chỉ là để cho Tần quốc nhất thống Lục quốc , lập lại một lần thôi .\n...\nĐường triều .\nTrinh Quán bảy năm .\n“ Huyền linh , bây giờ là giờ gì ?”\n“ Bệ hạ , đã qua một canh giờ ...”\nPhòng Huyền Linh tựa hồ biết Lý Thế Dân muốn hỏi cái gì , nói thẳng ra .\n“ Đã qua một canh giờ ? Cái này màn trời tại sao còn không bắt đầu ?”\nLý Thế Dân nghi hoặc nhìn màn trời , không rõ vì cái gì màn trời đến bây giờ đều vẫn là tắt trạng thái .\nNgươi muốn nói màn trời xảy ra vấn đề ? nhưng màn trời vẫn như cũ còn treo ở nơi đó .\n“ Có lẽ tiên sinh kia có chuyện gì ?”\nPhòng Huyền Linh nói là Lý Ân Phàm .\nLý Thế Dân chỉ là gật đầu một cái , sau đó lại vùi đầu xử lý chính vụ .\n...\nMinh triều .\nHồng Vũ năm thứ bảy .\n“ Hắc , hôm nay màn trời là chuyện gì xảy ra ? Như thế nào trễ lâu như vậy ?”\nChu Nguyên Chương cầm ngứa cào chụp chụp cõng , có chút ngạc nhiên nói .\n“ Có lẽ đã xảy ra chuyện gì a ...”\nMột bên Chu Tiêu nói tiếp , cũng là hơi kinh ngạc .\nDĩ vãng màn trời có thể nói cũng là đúng giờ đúng giờ liền mở ra .\nNhưng hôm nay màn trời , cũng đã muộn lâu như vậy , còn chưa mở ra .\n“ Đúng tiêu nhi , sau đó nếu là chọn được ta , ta mang ngươi nương về phía sau thế ...”\nA ?\n“ Cứ như vậy quyết định ? Phụ thân ?”\nChu Tiêu một mặt mộng nhìn xem Chu Nguyên Chương , hắn còn nghĩ để cho Chu Nguyên Chương mang chính mình đi đâu .\nThật không nghĩ đến , mang lại là mẹ của mình .\nCần phải cùng mình nương tranh một chuyến ? Quên đi thôi !\nCái này còn thế nào đi tranh ?\n“ Sau đó chờ ta đi xong hậu thế , tuyển mười người về phía sau thế học tập thời điểm , ngươi lại đi .”\nChu Nguyên Chương phất phất tay , cắt đứt Chu Tiêu suy nghĩ lung tung .\n“ Dạng này a ? Vậy là tốt rồi ...”\nChu Tiêu còn tưởng rằng cha mình không để cho mình về phía sau thế đâu .\nThì ra chỉ là sớm đi mà thôi .\nNhư vậy , vậy thì còn tốt , chính mình còn có thể về phía sau thế .\n“ Đến lúc đó ngươi liền cùng Tần triều vị công tử kia Phù Tô cùng một chỗ , tại kia cái gì học viện học tập .”\n“ Phụ thân , công cộng Quản Lý học viện ...”\nChu Tiêu Ký cực kỳ rõ ràng , dù sao công tử Phù Tô đều bị Lý Ân Phàm đi an bài cái này học viện , vậy thì khẳng định có đạo lý riêng .\n...\nMinh triều .\nVĩnh Lạc bảy năm .\n“ Lão đại , đến lúc đó ngươi liền mang theo ngươi hai cái đệ đệ , còn có những thứ khác bọn muội muội đi thôi .”\nChu Lệ lúc này không có việc gì , cũng bắt đầu an bài .\n“ Phụ thân , ngươi có thể quản lý tốt triều đình ?”\nChu Cao Sí có chút hoài nghi nhìn cha của mình Chu Lệ .\nKhông có chính mình , phụ thân của mình thật có thể quản lý tốt triều đình sao ?\n“ Ngươi đây là ánh mắt gì ?”\nChu Lệ gặp Chu Cao Sí gương mặt hoài nghi , lập tức có chút mất hứng .\n“ Phụ thân , về phía sau thế học tập ta là nhất định phải đi , nhưng ở ta đi học tập nửa năm này thời gian , ngươi không thể đi ra ngoài đánh trận !!”\nChu Cao Sí rất sợ chính mình chân trước vừa đi , Chu Lệ liền sắp xếp người bắt đầu cho chính mình lộng hậu cần .\nĐừng bản thân vừa trở về , Chu Lệ liền đã đến phía bắc thảo nguyên .\n“ Ngươi không tin ta ?”\nChu Cao Sí không có trả lời , mà là nói đến chuyện khác .\n“ Phụ thân , ta lần này đi hậu thế , có thể sẽ nhìn thấy gia gia cùng với đại bá ...”\nNghe nói như thế , Chu Lệ khẽ giật mình .\nChu Lệ biết có thể sẽ nhìn thấy phụ thân của mình cùng huynh trưởng sao ? Là biết đến .\nNhưng hắn nội tâm một mực tại trốn tránh chuyện này .\n“ Có một số việc , chúng ta là nên thương lượng một chút như thế nào đối với gia gia cùng đại bá nói .”\nNghe nói như thế , Chu Lệ thở dài một hơi , sau đó trầm mặc nhìn xem vẫn như cũ tắt màn trời .\nGặp Chu Lệ lại bắt đầu trốn tránh , Chu Cao Sí nội tâm cũng thở dài một tiếng .\n‘ Phụ thân , dù thế nào trốn tránh , cũng cuối cùng sẽ đối mặt ...’\n...\nHiện đại thời không .\n“ Ta muốn mở ra màn trời , các triều đại đổi thay những người kia , có thể có chút gấp .”\nLý Ân Phàm gặp không có gì muốn tiếp tục hỏi , liền chuẩn bị mở ra màn trời .\n“ Ai ? Bây giờ liền bắt đầu sao ?”\nLưu Bang bỗng nhiên nghiêm chỉnh , đoan đoan chính chính ngồi ở trên ghế sa lon .\n“ Quý ca , ngươi cứ như vậy bảo trì ba ngày a ?”\nNhìn xem Lưu Bang dáng vẻ , Lý Ân Phàm có chút buồn cười .\n“ Này ! Ta liền nói tùy ý liền tốt , nhưng Trương Lương cùng Tiêu Hà , lại nói cái gì tới hậu thế , không cần mất cấp bậc lễ nghĩa .”\nNghe được phải gìn giữ thời gian ba ngày ? Lưu Bang lập tức cũng không sao .\nĐể cho chính mình bảo trì dạng này nghiêm chỉnh thái độ ba ngày ? Vậy thật còn không bằng để cho chính mình đi chết tính toán .\n“ Các ngươi thì sao ? Muốn cùng chúng ta cùng một chỗ , hay là trở về gian phòng học tập ?”\nLý Ân Phàm lúc này lại hỏi Phù Tô cùng Mông Điềm hai người .\n“ Chúng ta trở về phòng ...”\nPhù Tô cùng Mông Điềm đứng lên , chuẩn bị cáo từ .\nHai người bọn họ việc học kỳ thực rất bận rộn , dù sao muốn tại thời gian nửa năm , học tập rất nhiều thứ .\n...', 'output\\mp3\\Màn Trời Quyền Lực Diễn Biến Cùng Truyền Thừa\\0063_Thứ 63 chương Lập lại một lần.mp3', '2026-09-01T23:25:11.268902+00:00', 'completed', 'completed', 7431, 7431),
	(69, 7, '7649919011756442137', 64, 'Thứ 64 chương Chính trị, quân sự, tổng hợp', 'Thứ chương Chính trị , quân sự , tổng hợp\n( Tác giả sách mới chỗ tập hợp , động vật : Ba lưu lưu không sáu nhảy múa tán ba .\nTác giả đại gia nhiều tiền khai sáng , ưa thích thảo luận lịch sử , hoan nghênh .)\nHiện đại thời không .\n“ Tốt , màn trời mở ra .”\nLý Ân Phàm biểu lộ thu một chút , không có giống như vừa rồi như vậy tùy ý .\nDù sao cũng là muốn truyền bá đến các triều đại đổi thay đi , hay là muốn hơi trang trọng một chút .\n“ Mọi người tốt , hôm nay đến đời sau vị thứ hai hoàng đế , là cá nhân ta cho rằng thời đại phong kiến lợi hại nhất hoàng đế một trong .”\n“ Đương nhiên , đồng dạng cũng là hậu thế một vị toàn quốc lão sư , cho rằng là thời đại phong kiến , hoàng đế bên trong lợi hại nhất một vị .”\n“ Vị hoàng đế này , là ai ? Chính là Lưu Bang .”\nLý Ân Phàm trong phòng nói xong , tiếp đó nghiêng người , đem màn trời ống kính nhường cho phía sau mình Lưu Bang .\n“ Quý ca , chào hỏi a .”\n“ Ân ? Bây giờ đời sau những cái kia triều đại , đều có thể nhìn thấy ?”\nLưu Bang tò mò hỏi , hắn cũng không cảm giác có cái gì khác biệt a ? Như thế nào đời sau những cái kia triều đại đều có thể thấy được ?\n“ Đúng vậy , hậu thế các triều đại đổi thay hoàng đế , đều có thể thấy được .”\n...\nHán triều .\nNguyên thú 4 năm .\n“ Đây là Thái tổ Cao Hoàng Đế ?”\nLưu Triệt nhìn thấy Lưu Bang khuôn mặt , có một chút kinh ngạc .\nHậu thế mặc dù tồn tại có Lưu Bang bức họa , nhưng bức họa chỉ có thể nói có thể nhìn , biết đại khái là một cái cái gì khuôn mặt .\nRõ ràng như thế thấy rõ ràng bọn hắn Hán triều khai quốc hoàng đế , Lưu Triệt thật là có chút kinh ngạc .\n“ Cảm giác không có hoàng đế uy nghiêm ...”\nLưu Triệt nói thầm một chút , sau đó thần sắc trịnh trọng .\nDù sao cũng là bọn hắn Hán triều khai quốc hoàng đế , hay là muốn nghiêm túc đối đãi một chút .\n...\nCuối thời Đông Hán .\nKiến An 8 năm .\nTào Thao , Quách Gia , Hạ Hầu Đôn bọn người tỉnh táo nhìn xem trên thiên mạc Lưu Bang khuôn mặt .\nMuốn nói tỉnh táo ? Kỳ thực cũng không phải rất tỉnh táo .\nDù sao bây giờ lúc này , đột nhiên nhìn thấy đại hán khai quốc hoàng đế , rất nhiều người nội tâm , kỳ thực là có một chút vi diệu .\nThân ở một cái vương triều những năm cuối , lại nhìn xem một cái vương triều bắt đầu .\nCó lẽ có người biết nói , Tào Thao bọn hắn bọn người là thế nào biết thân ở vương triều những năm cuối ?\nChỉ có thể nói rất nhiều chuyện kỳ thực vẫn luôn tại trong lòng của bọn hắn .\nĐối với hữu thức chi sĩ tới nói , đây cơ hồ là một cái công nhận sự thật .\n“ Thái tổ Cao Hoàng Đế ....”\nNhìn xem Lưu Bang khuôn mặt , Tào Thao nhẹ giọng thở dài một hơi , khẩu khí này tựa hồ muốn đem hắn trước kia biệt khuất , phiền muộn đều một ngụm toàn bộ phun ra .\n“ Ai ... Tào mỗ trước kia hi vọng , cũng chỉ là muốn làm một cái chinh tây tướng quân thôi ...”\nLúc này Tào Thao , trong đầu bỗng nhiên nổi lên sách sử phía trên ghi lại , đại hán đủ loại lịch sử huy hoàng .\nCũng chính bởi vì nhìn thấy bao la như vậy lịch sử , lúc còn trẻ hắn , nghĩ cái gì ? Nghĩ là vì nước tận trung .\nNhưng thực tế , cuối cùng không phải cá nhân có thể thay đổi vị trí , hoặc thay đổi .\nBên cạnh Quách Gia cùng Hạ Hầu Đôn bọn người , đều trầm mặc nhìn xem màn trời , cái gì cũng không nói .\n...\nHiện đại thời không .\n“ Đúng , tiên sinh , ngươi mới vừa nói , cho là ta là trong phong kiến hoàng đế , lợi hại nhất một vị ?”\nLưu Bang mới vừa nghe được lời này , tò mò trong lòng tâm lập tức lên tới đỉnh điểm .\nCó một chút vui vẻ sao ? Là có một chút , nhưng càng nhiều hơn chính là hiếu kỳ Lý Ân Phàm tại sao lại nói như vậy ?\n“ Cũng không phải nói lợi hại nhất một vị , chỉ có thể nói một trong a .”\n“ Ngoại trừ ngươi , kỳ thực còn có mấy vị , là trong ta cho rằng Phong Kiến Vương Triều , lợi hại nhất hoàng đế .”\nLúc này Lưu Bang tức thời nói :\n“ Nói một chút ?”\n“ Hảo , vậy thì nói một chút .”\nLý Ân Phàm cho Lưu Bang lại ném đi một bình nước khoáng , sau đó mình cũng lôi ra một bình nước khoáng xoay mở bình nắp uống vào mấy ngụm .\n“ Trong chính trị , ta cho rằng là Quý ca ngươi lợi hại nhất .”\n“ Trên quân sự , là Đường triều vị thứ hai hoàng đế , Đường Thái Tông Lý Thế Dân lợi hại nhất .”\n“ Tổng hợp đâu ?”\nLý Ân Phàm nói đến đây lời nói , trầm tư một hồi sau , nhẹ nói :\n“ Tổng hợp lợi hại nhất , ta cho là vị hoàng đế này , có thể ta nói ra , muốn bị đời sau rất nhiều người mắng .”\n“ Nhưng cái này cũng vẻn vẹn đại biểu là cái nhìn của cá nhân ta .”\n“ Tổng hợp lợi hại nhất hoàng đế , ta cho rằng là Hán triều một vị hoàng đế , Hán Vũ Đế Lưu Triệt ...”\n...\nĐường triều .\nTrinh Quán bảy năm .\n“ Ân ? Trẫm là trên quân sự lợi hại nhất ?”\nLý Thế Dân nghe xong bên trong lòng có một chút mừng rỡ , chính mình lại là bị người đời sau cho rằng , hoàng đế bên trong trên quân sự lợi hại nhất ?\n“ Nhưng , Hán Vũ Đế Lưu Triệt ?”\n“ Người tới , đem sách sử lấy ra .”\nLý Thế Dân chuẩn bị lại cẩn thận nghiên cứu một chút sách sử , xem Hán Vũ Đế Lưu Triệt đến cùng làm cái gì , để cho Lý Ân Phàm cho rằng , là hoàng đế bên trong tổng hợp lợi hại nhất .\nMà lúc này phía dưới rất nhiều trong đại thần , có người lại gương mặt không phục .\n“ Hán Vũ Đế Lưu Triệt ? Đây không phải cực kì hiếu chiến bạo quân sao ?”\nCó người nói thầm , cũng có người không xóa .\n...\nHiện đại thời không .\n“ Mà tại những này hoàng đế phía trên , còn có một vị hoàng đế , ta muốn đơn độc lấy ra nói một chút .”\n“ Vị hoàng đế này là ai ? Tống thái tổ Triệu Khuông Dận ...”\nLưu Bang nghe được cái tên xa lạ này , mắt lộ thần sắc tò mò nhìn xem Lý Ân Phàm .\n“ Từ ngay lúc đó thời đại đến xem , Triệu Khuông Dận không có thu hồi Yên Vân mười sáu châu , cũng không có triệt để thống nhất thiên hạ , cái này cho phía sau Tống triều , lưu lại tai họa ngầm rất lớn .”\n“ Từ một điểm này tới nói , có lẽ sẽ để cho hắn ở đời sau đám người trong lòng , giảm đi rất nhiều phân .”\n“ Nhưng từ hậu thế , ta góc nhìn đến xem , Triệu Khuông Dận đã hoàn mỹ thực hiện hắn thời đại trách nhiệm .”\n“ Hắn đã làm rất tốt , cũng đem thời đại giao phó hắn trách nhiệm , hoàn mỹ hoàn thành .”\n“ Không có hắn , loạn thế có lẽ sẽ kéo dài một thế hệ trở lên , Trung Nguyên đại địa chưa hẳn có thể tránh khỏi trường kỳ mảnh vụn hóa\n“ Triệu Khuông Dận không phải “ Duy nhất khả năng ” Thống nhất giả , nhưng hắn là duy nhất có thể lấy nhỏ nhất đại giới , tốc độ nhanh nhất đem năm đời “ Cấp loạn ” Chuyển thành Tống Thức “ Ổn trị ” Người .”\nNói đến đây , Lý Ân Phàm lấy ra một bản sách sử , đưa cho Lưu Bang .\nCái này sách sử , ghi chép tỉ mỉ Ngũ Đại Thập Quốc lịch sử .\n“ Tống triều , cùng với Tống triều sau đó hoàng đế , còn có thông minh người có học thức , quen thuộc Ngũ Đại Thập Quốc lịch sử , biết ta phải nói chính là cái gì .”\n...\nMinh triều .\nVĩnh Lạc bảy năm .\n“ Triệu Khuông Dận ...”\n“ Lão đại , trên thiên mạc người kia tựa hồ rất tôn sùng Tống thái tổ Triệu Khuông Dận .”\nChu Cao Sí khẽ gật đầu một cái , sau đó nói :\n“ Phụ thân , ta tựa hồ biết hắn vì cái gì như vậy phỏng đoán Tống thái tổ Triệu Khuông Dận .”\n“ Bởi vì Triệu Khuông Dận kết thúc cái kia hỗn loạn Ngũ Đại Thập Quốc .”\nChu Cao Sí bởi vì đọc thuộc lòng sách sử nguyên nhân , cho nên tại màn trời người kia nói ra Triệu Khuông Dận cái tên này thời điểm , liền biết đang nói gì .\n“ Ngũ Đại Thập Quốc sao ?”\nNhớ tới người viết sử tái Ngũ Đại Thập Quốc lịch sử , Chu Lệ cũng có chút trầm mặc .\nTrầm mặc thời điểm , Chu Lệ cũng không nhịn được nghĩ thầm , nếu như là chính mình ở vào Triệu Khuông Dận vị trí , hắn có thể làm so Triệu Khuông Dận tốt hơn sao ?\nNghĩ tới đây , Chu Lệ lắc đầu .\nKhông có cách nào so Triệu Khuông Dận tốt hơn , Triệu Khuông Dận đã là dùng cái giá thấp nhất , tốc độ nhanh nhất kết thúc thời đại kia .\n...', 'output\\mp3\\Màn Trời Quyền Lực Diễn Biến Cùng Truyền Thừa\\0064_Thứ 64 chương Chính trị, quân sự, tổng hợp.mp3', '2026-09-01T23:25:16.225903+00:00', 'completed', 'completed', 7511, 7511),
	(70, 7, '7649919303940063769', 65, 'Thứ 65 chương Lộ ra đức 4 năm', 'Thứ Chương Hiển Đức 4 năm\n( Đại lão khen thưởng , tăng thêm hai chương !)\nMinh triều .\nHồng Vũ mười năm .\n“ Triệu Khuông Dận ... Tống thái tổ ...”\nCho dù là Chu Nguyên Chương cái này không thích Tống triều hoàng đế , cũng không thể không thừa nhận Triệu Khuông Dận chiến công .\nSau khi dựng nước , hắn lúc không có chuyện gì làm nhìn sách sử , nhìn thấy Ngũ Đại Thập Quốc thời điểm , nói như thế nào đây ? Cũng không nhịn được nội tâm phát lạnh ...\nTại Ngũ Đại Thập Quốc cái kia hỗn loạn thời đại trước mặt , cuối thời nhà Nguyên ? Thật sự chỉ có thể coi là tiểu đả tiểu nháo .\nThân ở tại hoàng đế vị trí này , hắn biết rõ , Triệu Khuông Dận kết thúc , không phải mấy chục năm Ngũ Đại Thập Quốc .\nKết thúc , là Đường triều loạn An Sử sau , dần dần sụp đổ Trung Nguyên đại địa .\nCũng chính là giữa năm nguyên đại địa hỗn loạn thời gian , chuẩn xác mà nói , là năm .\nTừ loạn An Sử bắt đầu , đến Tống triều thiết lập năm .\nNgũ Đại Thập Quốc , chỉ là đem cái này hỗn loạn đẩy về phía đỉnh phong .\nMà Triệu Khuông Dận , chính là cố hết sức thay đổi cái này lúc hỗn loạn đại hoàng đế .\n...\nTống triều .\nMở bảo sáu năm .\n“ Trẫm ?!”\n“ Ta ?!”\n“ Màn trời tại nói ta ?”\nTriệu Khuông Dận kinh ngạc nhìn màn trời , như thế nào cũng không nghĩ đến , màn trời sẽ ở đây lúc , đột nhiên nói đến chính mình ?\n“ Hoàn mỹ hoàn thành thời đại giao phó trách nhiệm của ta ?”\nNghe được một câu nói kia , Triệu Khuông Dận lặp lại mấy lần , cẩn thận nhấm nuốt .\n“ Thì ra là thế ...”\n“ Có thể , Yên Vân mười sáu châu , cuối cùng không có thu phục trở về sao ?”\nTriệu Khuông Dận lập tức có chút nhụt chí , bất đắc dĩ nhìn xem màn trời .\nCho dù ai bỗng nhiên biết mình sau đó thất bại lịch sử , đều có một chút bất lực .\n...\nHiện đại thời không .\n“ Cái này ....”\nLưu Bang sơ lược lật qua lật lại Ngũ Đại Thập Quốc lịch sử , khiếp sợ nhìn xem Lý Ân Phàm .\n“ Tiên sinh , ngươi xác định đây là đời sau lịch sử ?”\n“ Không tệ , đây chính là Ngũ Đại Thập Quốc lịch sử .”\nLý Ân Phàm phi thường khẳng định gật đầu một cái , sau đó tiếp tục nói :\n“ Mặc dù nói Triệu Khuông Dận có thể không phải duy nhất thống nhất giả .”\n“ Nhưng cái này cũng là cho một chút giữ lại , không đem lời nói như vậy tuyệt đối .”\n“ Kỳ thực tại ta ở sâu trong nội tâm xem ra , nếu như không có Triệu Khuông Dận , Ngũ Đại Thập Quốc thật sự rất khó tại thời gian ngắn kết thúc .”\n“ Bởi vì ngay lúc đó Triệu Khuông Dận đi đến một bước kia , ý nghĩ hơi lệch một điểm điểm ? Vậy thì thật sự rất khó nói .”\nĐi đến một bước kia ? Vừa vặn leo lên hoàng đế một bước kia .\nNgũ Đại Thập Quốc , có quá nhiều thừa dịp hoàng đế tuổi nhỏ , soán vị đăng cơ người .\nNhưng lại có ai giống Triệu Khuông Dận , quyết tâm kết thúc loạn thế ?\n“ Đến nỗi nói Sài Vinh , cũng chính là Quách Vinh , người đời sau rất nhiều nhục mạ Triệu Khuông Dận , nói hắn khi dễ cô nhi quả mẫu mới lên tới hoàng vị .”\n“ Quách Vinh đối với Triệu Khuông Dận tốt như vậy , nhưng Triệu Khuông Dận ngược lại phản bội Quách Vinh .”\nLý Ân Phàm sau khi nói đến đây , rất là ý vị thâm trường nói :\n“ Nhưng , đại gia đoán một chút , Triệu Khuông Dận Trần Kiều binh biến , khoác hoàng bào , là học tập ai ?”\n“ Chưa quen thuộc Ngũ Đại Thập Quốc lịch sử , có thể rất nghi hoặc , Triệu Khuông Dận không phải binh biến khoác hoàng bào đệ nhất nhân sao ?”\n“ Nhưng quen thuộc Ngũ Đại Thập Quốc người , hẳn là liền chiếu cố tâm cười một tiếng .”\n“ Bởi vì , Triệu Khuông Dận là học tập Quách Uy , cũng chính là Quách Vinh cha nuôi .”\nNgũ Đại Thập Quốc , Hậu Hán thời kì , Quách Uy mang binh vào kinh thành , yết kiến Lý thái hậu ( Lý tam nương ), để cho Thái hậu lâm triều chấp chính , hơn nữa giả ý ủng lập Lưu thị tôn thất , Vũ Ninh Tiết Độ Sứ Lưu Uân là đế .\nSau đó , đột báo khế đan xuôi nam , suất quân Bắc thượng chống cự .\nĐi qua thiền châu lúc , binh sĩ phát động binh biến , khoác hoàng bào .\nQuách Uy trở về mở ra , bức bách Thái hậu dạy vì “ Giám quốc ”, đoạt được quốc chính .\nCó phải hay không rất quen thuộc ? Bởi vì đây là một dạng thao tác .\nĐột báo , xuất chinh , binh biến , khoác hoàng bào .\n“ Cho nên nói , lịch sử là một cái vòng tròn , đã có sự tình , sau nhất định lại có , đã hành chi chuyện , sau nhất định lại đi .”\nKhi Lý Ân Phàm nhìn thấy đoạn này lịch sử , cũng chỉ có thể lắc đầu , dù sao ngươi tiền nhân làm làm mẫu .\nVậy thì thật sự không nên trách hậu nhân tới học tập .\n...\nTống triều .\nMở bảo sáu năm .\n“ A ...”\nTriệu Khuông Dận bất đắc dĩ cười cười , hắn học tập ai ? Màn trời nói không sai , hắn học tập , chính là Đại Chu ( Hậu Chu ) khai quốc hoàng đế Quách Uy .\nDù sao án lệ thành công đều bày tại nơi đó , mình có thể không đi học tập sao ?\nĐến nỗi tiểu hoàng đế ?\nTriệu Khuông Dận không hối hận , bởi vì thời đại kia , dung không được dạng này tiểu hoàng đế .\nNgũ Đại Thập Quốc nhiều như vậy án lệ cũng đã đã chứng minh , tại cái kia hỗn loạn thời đại , tuổi nhỏ tiểu hoàng đế , bản thân liền là khởi nguồn của hoạ loạn .\n...\nNgũ Đại Thập Quốc thời kì .\nĐại Chu ( Hậu Chu ).\nLộ ra đức 4 năm .\nQuách Vinh nhìn mình trước mặt trong lòng run sợ Triệu Khuông Dận , thần sắc vô cùng tỉnh táo .\n“ Bệ ... Bệ hạ ...”\nTrẻ tuổi Triệu Khuông Dận tựa hồ biết mình muốn đối mặt cái gì .\n“ Mang xuống a !”\nQuách Vinh ban đầu nghe được Triệu Khuông Dận xưng đế , là rất phẫn nộ .\nCó thể tưởng tượng chính mình vị kia tuổi nhỏ hài tử , lại lập tức bình thường trở lại .\nDù sao nhà bọn hắn hoàng vị , làm sao tới ? Hắn có thể không rõ ràng sao ?\nHuống chi , thân ở vị trí này hắn , cũng vô cùng tinh tường , ở thời đại này , tuổi nhỏ hoàng đế , ý vị như thế nào .\n“ Lặng lẽ xử lý a ...”\nQuách Vinh nhẹ giọng đối với bên cạnh một cái hoạn quan nói .\nHoạn quan lĩnh mệnh , chắp tay thi lễ một cái , sau đó lui ra ngoài .\n“ Nói thật , trẫm không trách ngươi , tương phản , tại biết ngươi kết thúc cái này hỗn loạn thời đại , còn vì ngươi cao hứng .”\n“ Nhưng muốn trách , thì ngươi trách màn trời a , để cho hết thảy tại còn chưa có bắt đầu thời điểm , liền đã lộ ra ngoài .”\nKhông có một bóng người trong đại điện , Quách Vinh tựa hồ muốn nói cho ai nghe ? Lại tựa hồ đang lầm bầm lầu bầu .\n...\nĐường triều .\nTrinh Quán bảy năm .\n“ Cho nên cái này hậu thế , đến cùng xảy ra chuyện gì ?”\nLý Thế Dân lúc này nội tâm vô cùng ngứa ngáy , rất muốn biết , cái này Triệu Khuông Dận đến cùng làm cái gì , mới khiến cho hậu nhân muốn đem hắn đơn độc lấy ra nói lâu như vậy ?\n“ Hơn nữa , còn có cái này loạn An Sử , lại là cái gì ?”\nGiờ khắc này , Lý Thế Dân chỉ có thể tại nội tâm cầu nguyện , vị kế tiếp đến chọn được đời sau hoàng đế , nhất định muốn là chính mình .\nTrong nội tâm của mình , có rất rất nhiều muốn biết .\nĐặc biệt là ...\nLý Thế Dân bỗng nhiên trầm mặc lại , ngẩng đầu nhìn về phía Huyền Vũ môn vị trí phương hướng .\n...\nHiện đại thời không .\n“ Đúng là một vị lợi hại hoàng đế ...”\nLưu Bang lúc này cũng xem xong sách sử , rất là khen ngợi nói .\nNói thật , trên sử sách ghi lại cái kia Ngũ Đại Thập Quốc , Lưu Bang đều rất hoài nghi , chính mình nếu là đi thời đại kia , có thể hay không sống qua một năm ?\nChỉ sợ thật sự rất khó .\nDù sao thời gian hơi lâu một chút , chính mình nếu còn là “ Đình trưởng ” Một thân phận này , chỉ sợ cũng tại người nào đó trên bàn cơm .\nCuối Tần cũng không có loạn như vậy !\nLưu Bang nghĩ thầm .\n“ Bây giờ muốn đi ra ngoài dạo chơi sao ? Quý ca , đợi lát nữa thuận tiện chúng ta ở bên ngoài ăn cơm .”\nNghe nói như thế , Lưu Bang nhãn tình sáng lên .\nHắn đã sớm muốn thử xem đời sau ăn uống , phía trước màn trời phía trên truyền , thế nhưng là đem hắn thèm rất lâu .\n“ Đi !”\nLưu Bang cầm trong tay sách sử thả xuống , vội vàng đứng dậy .\n“ Đi , vậy chúng ta liền đi ra ngoài a .”\n......', 'output\\mp3\\Màn Trời Quyền Lực Diễn Biến Cùng Truyền Thừa\\0065_Thứ 65 chương Lộ ra đức 4 năm.mp3', '2026-09-01T23:25:45.121693+00:00', 'completed', 'completed', 7536, 7536),
	(71, 7, '7650136550377800217', 66, 'Thứ 66 chương Bốn mươi tám tuổi', 'Thứ chương Bốn mươi tám tuổi\nHiện đại thời không .\n“ Về phần tại sao nói ngươi là trong Phong Kiến Vương Triều lợi hại nhất hoàng đế ...”\nTrên đường cái , Lý Ân Phàm cùng Lưu Bang hai người thoải mái nhàn nhã đi tới , tay của hai người bên trong đều cầm bình nước suối khoáng , Lưu Bang thỉnh thoảng trái xem phải xem .\nCái này đời sau hết thảy , đều để hắn tốt như vậy kỳ , mà khi nghe đến Lý Ân Phàm lời nói , Lưu Bang lấy lại tinh thần , chuyên chú nghe .\n“ Nếu như ta nhớ không lầm , Quý ca , ngươi coi đó tại bái huyện khởi binh , hẳn là bốn mươi tám tuổi a ?”\nBây giờ chủ lưu có hai cái thuyết pháp , một cái thuyết pháp là bốn mươi tám tuổi , một cái thuyết pháp là ba mươi chín tuổi , ở đây áp dụng bốn mươi tám tuổi .)\n“ Đúng vậy a , lúc đó đã bốn mươi tám tuổi ...”\nLưu Bang nhẹ giọng thở dài một hơi , nghĩ đến lúc đó bốn mươi tám tuổi chính mình , cũng có một chút cảm khái .\n“ Hậu thế các triều đại đổi thay khai quốc hoàng đế bên trong , liền tuổi của ngươi lớn nhất ...”\n“ Chớ nói chi là , tại bốn mươi tám tuổi ở độ tuổi này , khởi binh tạo phản ...”\nLý Ân Phàm nói thật , là rất bội phục Lưu Bang .\nBởi vì mặc kệ là ba mươi chín tuổi , vẫn là bốn mươi tám tuổi , tại cổ đại , đặc biệt là cuối Tần cái hoàn cảnh kia phía dưới , dạng này người , kỳ thực cũng có thể nói là lão nhân .\nHán triều người bình thường , bình quân số tuổi là bao nhiêu tuổi tuổi !\nHoàn cảnh , tật bệnh các loại , đều để tuổi của bọn hắn co lại vô cùng ngắn .\nCó thể có người biết nói , hoàng đế cùng danh nhân , niên linh còn lớn hơn một chút .\nLà như vậy , bởi vì bọn hắn ăn ngon , ở cũng tốt , điều trị cũng có thể kịp thời thu hoạch .\nNhưng Tây Hán thời kì , hoàng đế bình quân niên linh bao nhiêu tuổi tuổi !\n“ Từ niên linh đến xem , Quý ca , ngươi có thể tại lúc đó khởi binh , cũng đã là rất bất khả tư nghị .”\nLý Ân Phàm nói một câu nói này thời điểm , nói rất chân thành , bởi vì hắn là thật sự cảm thấy không thể tưởng tượng nổi .\nHiện đại rất nhiều người nhìn thấy ba mươi chín tuổi hoặc bốn mươi tám tuổi , có thể còn có chút không để bụng , bởi vì tại hiện đại , ở độ tuổi này , vừa vặn ở vào trung niên .\nTrung niên đi , chính là phấn đấu thời điểm .\nNhưng ở cổ đại , ở độ tuổi này khởi binh , đã vô cùng khoa trương .\n“ Cho nên , Quý ca , ngươi coi đó đến cùng là nghĩ gì ?”\n“ Nghĩ như thế nào ?”\nLưu Bang dừng bước lại , trên mặt mang vẻ hồi ức .\n“ Kỳ thực cuối cùng , cũng là bất đắc dĩ thôi .”\n“ Chờ ta leo lên hoàng đế vị trí này thời điểm , ta mới phát hiện , lúc đó là có bao nhiêu hỗn loạn ...”\nLưu Bang lúc này chậm rãi mở miệng , thần sắc từ từ nghiêm túc .\n“ Cũng chính là thượng vị sau đó , ta mới biết được , Tần triều luật pháp kỳ thực cũng không khắc nghiệt .”\n“ Nhưng rơi vào lúc đó trên người của ta , cùng với phía dưới những người kia trên thân ...”\n“ Hơn nữa ta lúc đó cũng là nghe theo mệnh lệnh áp giải đồ dịch đi Ly Sơn , nhưng đồ dịch nhóm có rất nhiều ở trên đường trốn , ta có thể làm sao đâu ?”\nLưu Bang lúc nói câu nói này , chắp hai tay sau lưng , trong giọng nói có một chút bất đắc dĩ .\n“ Vốn là không liên quan đến việc của ta , nhưng bọn hắn trốn , này liền quan chuyện của ta .”\n“ Đi tới một bước kia , ngoại trừ khởi binh , muốn hảo hảo sống sót , còn có cái gì biện pháp khác sao ?”\nNếu như có thể thật tốt sinh hoạt , Lưu Bang sẽ khởi binh sao ? Sẽ không , mặc kệ là ba mươi chín vẫn là bốn mươi tám , Lưu Bang ngay lúc đó niên linh , thật sự tính toán một lão nhân .\nDạng này người , lúc còn trẻ đều không tham quân , chờ tuổi già , còn khởi binh tạo phản ?\nHơn nữa , liền Lưu Bang cái thân phận này địa vị người , những quý tộc kia , lại có ai sẽ liên lạc hắn đâu ?\n“ Ép ngươi không thể không phản ...”\nLý Ân Phàm hơi làm một cái tổng kết , nhẹ giọng đối với Lưu Bang nói .\n“ Đúng vậy a , không thể không phản ...”\nLưu Bang tựa hồ lại trở về nhớ lại lúc ấy chạy trốn tại mang huyện , nãng huyện sơn trạch thời gian .\nNgay lúc đó chính mình thật sự nghĩ vài lần từ bỏ tính toán .\nChính mình ở độ tuổi này , còn giày vò cái gì ? Còn có cái gì chơi đùa ?\nNhưng chính mình cuối cùng vẫn là muốn về đến bái huyện , trở lại trước kia những tháng ngày đó .\nCuối cùng ? Bị đẩy đi tới bây giờ ...\n“ Kỳ thực ta thật sự rất muốn trở lại lúc tuổi còn trẻ tại bái trong huyện thời gian .”\n“ Nói như vậy , có thể có một chút nữ nhân , nhưng đây quả thật là ta ý tưởng nội tâm ...”\nLưu Bang khẽ thở dài một hơi , nhớ tới bây giờ tại trong hoàng cung thời gian , liền không nhịn được nội tâm tuôn ra bực bội .\nMặc dù mình có thủ đoạn có thể áp đảo những người khác , nhưng mỗi ngày qua cuộc sống như vậy ? Chính mình thật sự chịu không được .\nNói chung nghi kỵ tới , nghi kỵ đi , hoặc đấu tới đấu lui .\nCuộc sống như vậy , đến cùng có gì tốt ?\nĐặc biệt là Lưu Bang chính mình , thật sự đối với cuộc sống như vậy không một chút lưu luyến .\n“ Ta nhớ được ngươi thật giống như nói qua , đại trượng phu cũng đến thế mà thôi ?”\n“ Ai ...”\nLưu Bang nghe nói như thế , bất đắc dĩ cười một tiếng .\n“ Lúc đó thật là chỉ có thấy được có bao nhiêu Phong Quang ...”\nNgẫu nhiên nghe được Lý Ân Phàm nói lên câu nói này , Lưu Bang nói thật , còn cảm thấy bên trong lòng có một chút xấu hổ .\nChính mình niên linh thời điểm , là thế nào cảm thấy Thủy Hoàng Đế Phong Quang ?\nMấy người ngồi lên đồng dạng vị trí , hắn chỉ muốn nói : Phong quang cái rắm !\nTrước mặt người khác Phong Quang , người sau thật sự bị tội .\n“ Chúng ta tại cái này ăn đi ...”\nLý Ân Phàm cắt đứt Lưu Bang hồi ức , mang theo hắn đi vào bên ngoài tiểu khu quán ăn Trung Quốc .\n“ Lão bản , ăn cơm ...”\nNói xong , Lý Ân Phàm mang theo Lưu Bang đi vào phòng .\n“ Đúng , Quý ca , ngươi như thế nào không mang những người khác ?”\nLý Ân Phàm lúc này mới đột nhiên nghĩ đến hỏi Lưu Bang , hắn như thế nào là một người tới ?\n“ Mang những người khác ?”\n“ Mang ai đây ? Bọn hắn đều không thể rời bỏ ...”\nLưu Bang vẫn là đem chính vụ giao cho những người khác , mới có thời gian chạy đến hậu thế tới nghỉ ngơi một đoạn thời gian .\n“ Ta cho là , ngươi sẽ mang Lữ hậu ...”\n“ Lữ hậu ? Lữ Trĩ ?”\nNghe được cái tên này , Lưu Bang sửng sốt một chút .\n“ Ngươi vì sao lại cảm thấy ta sẽ dẫn Lữ Trĩ đâu ?”\nLưu Bang tò mò nhìn Lý Ân Phàm , nhẹ giọng dò hỏi .\nLý Ân Phàm gặp lão bản đi vào , không nói gì , tiếp nhận menu , nhanh chóng gọi một vài món ăn , lại điểm một bình rượu cùng một bình đồ uống .\nChờ lão bản sau khi ra ngoài , Lý Ân Phàm mới lên tiếng :\n“ Vì sao lại mang Lữ hậu ?”\nLý Ân Phàm trầm tư phút chốc , sau đó chăm chú nhìn Lưu Bang hỏi :\n“ Quý ca , ta hỏi một vấn đề , ngươi thật sự muốn đổi Thái tử sao ?”\n...\nHán triều .\nHán bảy năm .\nĐột nhiên nghe được màn trời phía trên Lý Ân Phàm hỏi ra vấn đề này , rất nhiều đại thần đều chôn lấy đầu , không nói một lời .\nTiêu Hà nhưng là liếc mắt nhìn trên đài Lữ hậu , cũng tương tự vùi đầu xuống .\nLữ hậu nhưng là siết chặt ống tay áo của mình , chăm chú nhìn màn trời .\nNàng cũng rất muốn biết , Lưu Bang đến cùng có hay không đổi Thái tử ý nghĩ .\nDù sao đổi Thái tử chuyện này , chủ yếu nhất là đổi Thái tử sao ?\nỞ đời sau có thể là dạng này .\nNhưng ở Hán triều , đặc biệt là tại Tây Hán thời kỳ này .\nĐổi Thái tử , chủ yếu nhất không phải đổi Thái tử , mà là đổi hoàng hậu !\n...', 'output\\mp3\\Màn Trời Quyền Lực Diễn Biến Cùng Truyền Thừa\\0066_Thứ 66 chương Bốn mươi tám tuổi.mp3', '2026-09-01T23:25:50.048465+00:00', 'completed', 'completed', 7121, 7121),
	(72, 7, '7650161174092186137', 67, 'Thứ 67 chương Đổi Thái tử', 'Thứ chương Đổi Thái tử\nHiện đại thời không .\n“ A ?”\nLưu Bang đột nhiên nghe được Lý Ân Phàm hỏi câu nói này , còn có chút sững sờ , sau đó tưởng tượng , liền biết phía sau chính mình phải làm cái gì .\n“ Đằng sau ta là làm cái gì ?”\n“ Người viết sử tái , tuổi già ngươi , sủng ái thích cơ cực kỳ tử Triệu Vương Lưu như ý , xa lánh Lữ hậu , mấy lần nghĩ phế truất Lữ hậu sở sinh Thái Tử Lưu doanh , mà đứng Lưu như ý .”\n“ Trương Lương , thúc tôn thông mấy người đại thần tất cả phản đối , ngươi vẫn không bỏ đi dịch trữ ý nghĩ .”\n“ Cuối cùng , tại Trương Lương đề nghị mời tới “ Thương sơn tứ hạo ” Dưới sự hỗ trợ , ngươi mới rõ ràng Lưu Doanh địa vị đã củng cố , liền không còn cân nhắc phế lập Thái tử một chuyện .”\nNghe xong Lý Ân Phàm giảng thuật , Lưu Bang trên mặt không có một điểm biểu lộ , chỉ là gật đầu một cái , sau đó trầm tư .\nKhông đầy một lát , Lưu Bang ngẩng đầu nhìn Lý Ân Phàm .\n“ Tiên sinh , ngươi cảm thấy ta có hay không đổi Thái tử ý nghĩ ?”\nÂn ?\nKhông phải , đến cùng là ta hỏi ngươi , vẫn là ngươi hỏi ta ?\nLý Ân Phàm nghe được Lưu Bang vấn đề , trong nội tâm có chút dở khóc dở cười .\n“ Ngươi hẳn là không có đổi Thái tử ý nghĩ .”\nSau đó , Lý Ân Phàm vẫn là đưa ra mình ý nghĩ , chợt lại tiếp tục nói :\n“ Một cái là lúc tuổi già , người như ngươi , thì sẽ không chơi đùa .”\n“ Đặc biệt là ngươi minh xác biết , đổi đi Thái Tử Lưu doanh , Lữ hậu nhất định sẽ kiên quyết phản đối .”\n“ Lữ hậu phản đối sau đó đâu ? Có phải hay không lại phải thay đổi hoàng hậu ?”\n“ Nhưng ngươi hẳn phải biết , hoàng hậu ngay lúc đó thế lực lớn đến mức nào .”\n“ Hai chính là ngươi hẳn là đang thử thăm dò , trên triều đình , có bao nhiêu người ủng hộ ngươi , có bao nhiêu người ủng hộ Lữ hậu .”\n“ Lại có bao nhiêu người phản đối Lữ hậu .”\nĐặc biệt là điểm này , về sau Tây Hán hoàng đế , cơ hồ là dùng nát .\nLiền dùng đổi Thái tử đến dò xét trên triều đình quần thần ý nghĩ .\n“ Nhưng ...”\nLý Ân Phàm nói đến đây , lại nghi hoặc , tựa hồ nghĩ tới điều gì .\n“ Ngươi tựa hồ đã từng quả thật có đổi Thái tử ý nghĩ , nhưng chủ yếu nhất không phải đổi Thái tử ...”\n“ Là ngươi cảm thấy Lữ hậu đối với Lưu Doanh khống chế quá sâu , mà Lưu Doanh cũng quá nghe Lữ hậu lời nói ...”\n“ Ngươi hẳn là lo lắng ...”\nLưu Bang vô cùng bình tĩnh nhìn xem Lý Ân Phàm , lời gì cũng không nói , không có gật đầu , cũng không lắc đầu .\n“ Ngươi lo lắng Lưu Thị Vương Triều , lại biến thành Lữ thị ...”\n“ Tiên sinh , ngươi sai , ta cũng không lo lắng ...”\nLưu Bang cầm ly trà lên uống một hớp nước trà , chậc chậc lưỡi , sau đó lạnh nhạt tiếp tục nói :\n“ Phía trước ngươi tại màn trời nói qua một cái luận điệu , căn cơ luận , ta là phi thường tán đồng .”\n“ Vậy ngươi suy nghĩ một chút , Lữ Trĩ , nàng có căn cơ sao ?”\nÂn ?\nLý Ân Phàm tử mảnh tưởng tượng , lập tức lắc đầu .\n“ Trĩ nhi nàng vô cùng thông minh , thông minh đến ta đơn độc đi tới hậu thế , đem đại hán giao phó cho nàng .”\n“ Nàng vô cùng tinh tường , có một số việc , nàng là không thể nào vượt qua .”\n“ Cho nên , ta cũng không lo lắng ...”\nLý Ân Phàm lúc này nghĩ tới điều gì , nhíu nhíu mày , cố gắng đang tự hỏi .\nMột lát sau , Lý Ân Phàm bừng tỉnh đại ngộ , nhìn xem Lưu Bang nói :\n“ Cho nên ngươi là ...”\n“ Đúng vậy ...”\nLưu Bang cắt đứt Lý Ân Phàm mà nói , không có để cho Lý Ân Phàm nói tiếp đi ra , rất nghiêm túc gật đầu một cái .\nCó một số việc , nói ra , vậy thì mất linh .\n...\nMinh triều .\nVĩnh Lạc bảy năm .\n“ Ân ? Lão đại , cái này Lưu Bang rốt cuộc là ý gì ?”\nChu Lệ hơi nghi hoặc một chút quay đầu nhìn về phía bên cạnh Chu Cao Sí .\nMà Chu Cao Sí lúc này , đang lâm vào trong suy xét .\n“ Phụ thân ... Để cho ta suy nghĩ một chút ...”\nLập tức qua một hồi lâu , Chu Cao Sí mới đột nhiên ngẩng đầu nhìn màn trời , khiếp sợ nói :\n“ Lưu Bang là cố ý ...”\n“ A ?”\nChu Lệ một mặt mộng nhìn xem Chu Cao Sí .\n“ Lưu Bang cố ý bức bách Lữ hậu , mà Lữ hậu cũng biết Lưu Bang là cố ý bức bách chính mình .”\n“ Cho nên , nàng mới mời Trương Lương , để cho Trương Lương mời đến “ Thương sơn tứ hạo ”.”\nNghe được cái này , Chu Lệ cũng nghe đã hiểu , lập tức bừng tỉnh đại ngộ nói :\n“ Thì ra là thế ...”\n“ Đúng vậy , phụ thân , Lưu Bang cần “ Thương sơn tứ hạo ” Tới thừa nhận đại hán .”\n“ Trọng yếu không phải thừa nhận Lưu Doanh , là thừa nhận đại hán .”\n“ Mà cái này “ Thương sơn tứ hạo ” Thân phận , liền phi thường mấu chốt .”\nChu Cao Sí nói đến đây , ngữ khí không ngừng tiếp tục nói :\n“ Cho nên , cái này “ Thương sơn tứ hạo ” Tại đại hán lộ một lần mặt , liền lại lần nữa ẩn cư ở Thương sơn .”\n“ Đông Viên Công Đường nắm , Hạ Hoàng Công Thôi Quảng , khinh bên trong Quý Ngô Thực , lục bên trong tiên sinh chu thuật ...”\n“ Đây là muốn sao thiên hạ người có học thức tâm sao ?”\nNói đến đây một câu cuối cùng , Chu Cao Sí trên mặt lộ ra nghi hoặc , sau đó lại khẳng định nói :\n“ Vốn nên như thế này .”\n“ 4 người nguyên là Tần Thuỷ Hoàng lúc tiến sĩ quan , phân chưởng thông cổ kim , biện đúng hay không , điển giáo chức .”\n“ Bọn hắn chỉ là theo Thái Tử Lưu doanh yết kiến Lưu Bang một lần , Lưu Bang liền từ bỏ phế lập Thái tử kế hoạch .”\nSau đó , Chu Cao Sí lắc đầu nói :\n“ Nếu như Lưu Bang thật sự hạ xuống quyết định đổi Thái tử , hội kiến bốn người này một mặt , liền từ bỏ sao ? Sẽ không .”\n“ Lưu Bang dạng này hoàng đế , là sẽ không dễ dàng sửa đổi quyết định của mình .”\n“ Cho nên , Lưu Bang chỉ là muốn sao một số người tâm .”\n“ Người có học thức ?”\nChu Cao Sí nghĩ tới đây , có lộ ra thần sắc nghi hoặc , chính mình hỏi mình .\n“ Không đúng , ta biết Lưu Bang sao ai tâm ...”\n“ Lão đại , mau nói !”\nChu Lệ ở một bên nghe nói như thế , vội vàng đối với Chu Cao Sí nói .\n“ Lưu Bang sao , không phải người có học thức tâm .”\n“ Hắn sao , là lão Tần người tâm , hoặc có lẽ là , cũng có Nguyên Đại Tần quan viên tâm .”\n“ Đương nhiên , đây không phải chủ yếu nhất , chủ yếu nhất , là đại hán lấy được một phương diện khác thừa nhận ...”\nĐến nỗi phương diện này đến cùng là cái gì ? Chu Cao Sí còn có chút không rõ ràng .\nNhưng hắn biết , Lưu Bang nhất định là như vậy nghĩ .\nBằng không thì không có khả năng để cho 4 cái , bảy, tám mươi tuổi lão đầu tử , lộ một lần mặt , liền để bọn hắn trở về .\nMà ở trong đó , chủ yếu nhất , hẳn là bọn hắn “ Lộ diện ”.\nMà chỉ cần “ Lộ diện ”, liền sẽ để một số người trông thấy , sao lòng của bọn hắn .\nĐến nỗi đến cùng phải hay không lão Tần người tâm ? Hoặc có lẽ là Nguyên Đại Tần quan viên tâm ?\nChu Cao Sí nói khẳng định như vậy , kỳ thực cũng chỉ là ngờ tới .\nNhưng hắn tinh tường , Lưu Bang nhất định là cố ý bức bách Lữ Trĩ , sau đó để nàng thỉnh Trương Lương , đi để cho Trương Lương thỉnh “ Thương sơn tứ hạo ”.\nLưu Bang chính mình thỉnh qua “ Thương sơn tứ hạo ”, hơn nữa còn mời mấy lần .\nNhưng không có mời đến !\n“ Thương sơn tứ hạo ” Không để ý Lưu Bang !\nLưu Bang lúc tuổi già chỉ sợ bất đắc dĩ mới ra kế này sách .\nNày liền như cái gì ? Đời sau diễn thánh công Khổng gia .\nChu Cao Sí cũng là nghĩ đến Khổng gia , vừa nghĩ đến cái này “ Thương sơn tứ hạo ” Tại lúc đó nhất định phi thường mấu chốt .\nBọn hắn ngay lúc đó tác dụng , nhất định là tương tự với Khổng gia .\nHậu thế sao người có học thức tâm , chính là thiện đãi Khổng gia .\nMà tại lúc đó cái này “ Thương sơn tứ hạo ”?\nNhất định là giống nhau tác dụng .\n“ Cho nên , Lưu Bang là biết mình không mời được , tại lúc tuổi già , liền cố ý đi bức bách Lữ Trĩ ...”\n“ Mà Lữ Trĩ cũng liền thuận nước đẩy thuyền ...”\nChu Lệ lúc này cũng nghĩ đến điểm này , hơi xúc động nhìn xem màn trời .\n......', 'output\\mp3\\Màn Trời Quyền Lực Diễn Biến Cùng Truyền Thừa\\0067_Thứ 67 chương Đổi Thái tử.mp3', '2026-09-01T23:25:55.542768+00:00', 'completed', 'completed', 7354, 7354),
	(73, 7, '7650390734356365849', 68, 'Thứ 68 chương Thương sơn tứ hạo', 'Thứ chương Thương sơn tứ hạo\nĐường triều .\nTrinh Quán bảy năm .\n“ Lưu Bang nhất định là cố ý thỉnh “ Thương sơn tứ hạo ” Đi ra sao một số người tâm .”\nCùng là hoàng đế , Lý Thế Dân vô cùng rõ ràng Lưu Bang ngay lúc đó ý nghĩ .\nMột vị hoàng đế , lúc tuổi già sẽ đổi Thái tử sao ? Trừ phi đến tình cảnh bức bất đắc dĩ , bằng không thì , là tuyệt đối sẽ không đổi Thái tử .\nBởi vì đổi Thái tử không chỉ chỉ nói là đổi liền đổi đơn giản như vậy .\nDính đến quá nhiều đồ vật , không có thời gian dài sắp đặt , sẽ dễ dàng đổi Thái tử ?\nCho nên , Lưu Bang lúc đó nhất định là thỉnh “ Thương sơn tứ hạo ” Đi ra sao một số người tâm .\nCó thể sao chính là người nào tâm ?\n“ Huyền Linh , ngươi cho rằng Lưu Bang nhất định phải làm cho “ Thương sơn tứ hạo ” Đi ra , là sao ai tâm ?”\nLý Thế Dân nhìn về phía trong trầm tư Phòng Huyền Linh nhẹ giọng hỏi .\n“ A ? Bệ hạ , lão thần đang suy tư .”\nPhòng Huyền Linh đứng lên cung kính hướng về Lý Thế Dân thi lễ một cái rồi nói ra .\n“ Bệ hạ , có lẽ sao chính là người có học thức tâm ?”\nBên cạnh Ngụy Chinh cung kính hướng về phía trước nói .\n“ Trẫm nhìn , không phải người có học thức tâm .”\n“ Nếu như là sao người có học thức tâm , Lưu Bang tại trong sử sách , sẽ không làm như vậy .”\nLàm như vậy ? Loại nào làm ? Rất nhiều người trong đầu nhớ tới 《 Sử Ký 》 bên trong ghi lại Lưu Bang .\nSau đó đều lúng túng .\nChính xác , nếu như là sao người có học thức tâm , Lưu Bang trước kia thì sẽ không làm như vậy .\nHơn nữa , thời điểm đó Lưu Bang thế nhưng là đã làm hoàng đế .\nRất nhiều chuyện , cũng đã rõ ràng , nếu là sao người có học thức tâm , làm sao có thể còn làm như vậy đâu ?\n“ Bệ hạ !”\nLúc này , Lễ bộ Thượng thư Vương Khuê cung kính đi về phía trước thi lễ .\n“ A ? Vương Khuê , ngươi đoán được cái gì ?”\nLý Thế Dân nhìn về phía Vương Khuê , biết hắn hẳn là đoán được cái gì .\n“ Bệ hạ , cái này “ Thương sơn tứ hạo ” Có thể là Tần Thuỷ Hoàng Thái Sơn lúc tế tự ...”\nLời này vừa ra , tại chỗ rất nhiều đại thần một chút lộ ra bừng tỉnh thần sắc .\n“ Đúng a ...”\nLý Thế Dân cũng tương tự tán đồng gật đầu một cái .\nCái quan điểm này vừa ra , tại chỗ rất nhiều người đều một chút vô cùng đồng ý .\n“ Hán Thừa Tần Chế , vậy làm sao mới có thể danh chính ngôn thuận đâu ?”\n“ Đương nhiên là xin vì Tần “ Tế tự ” Người đi ra ...”\nLý Thế Dân theo cái này nhìn qua điểm , tiếp tục nói .\n“ Mà có so “ Thương sơn tứ hạo ” Càng danh chính ngôn thuận người sao ? Không có !”\n“ Cho nên , Lưu Bang cố ý để cho Lữ Trĩ đi mời Trương Lương , để cho Trương Lương đi mời “ Thương sơn tứ hạo ”, chính là muốn vì “ Hán ” Đứng đài .”\n“ Để “ Hán ” Càng thêm danh chính ngôn thuận .”\nPhòng Huyền Linh lúc này cũng đứng ra nói :\n“ Bệ hạ , đại sự quốc gia , ở chỗ tế tự cùng chiến tranh .”\n“ Lưu Bang sao , hẳn là người trong thiên hạ tâm !”\nLời này vừa ra , Lý Thế Dân bỗng nhiên một chút vỗ vỗ chân của mình , bừng tỉnh đại ngộ giống như nói :\n“ Đúng , Huyền Linh , ngươi nói đúng .”\n“ Lưu Bang , chính là sao người trong thiên hạ tâm , lúc tuổi già , rất nhiều vương khác họ hắn đều tiêu diệt .”\n“ Nhưng thiên hạ còn rất nhiều người tại quan sát , quan sát Lưu Bang có phải hay không còn muốn tiếp tục đánh xuống .”\n“ Cho nên , hắn mời ra “ Thương sơn tứ hạo ”, tới vì Thái tử Lưu Doanh đứng đài , dạng này đã vì “ Hán ” Đứng đài .”\n“ Đồng dạng đâu ? Cũng là để cho người trong thiên hạ yên tâm , để cho người trong thiên hạ biết , mình đã xác lập “ Thái tử ”.”\nGiờ khắc này Lý Thế Dân , não hải vô cùng hoạt động mạnh .\nPhía trước hắn chính xác không để ý đến một cái điểm mấu chốt , đó chính là Lưu Bang lúc tuổi già .\nLúc tuổi già , khi đó Lưu Bang rất nhiều chuyện đều phải bắt đầu xác lập truyền thừa .\n“ Để cho người trong thiên hạ biết , chính mình sẽ lại không “ Giày vò ” Sao ?”\nLý Thế Dân sờ cằm một cái , mang theo một tia chắc chắn , lại dẫn một chút nghi hoặc .\n...\nCuối thời Đông Hán .\nKiến An 8 năm .\n“ Phụng Hiếu , ngươi nói , Thái tổ Cao Hoàng Đế đây là đang làm cái gì ?”\nTào Thao chắp hai tay sau lưng , nhìn về phía một bên Quách Gia , nhẹ giọng dò hỏi .\n“ Tư Không , Thái tổ Cao Hoàng Đế hẳn là cố ý đổi Thái tử , đến bức ép Trương Lương , để cho hắn mời ra “ Thương sơn tứ hạo ”, tới sao người trong thiên hạ tâm .”\nQuách Gia suy tư thật lâu , sau đó mới mang theo một chút giọng khẳng định nói .\n“ A ?”\nTào Thao chăm chú nhìn Quách Gia , chờ đợi hắn lời kế tiếp .\n“ Tư Không , tất nhiên muốn hòa bình , Thái tổ Cao Hoàng Đế không muốn lại “ Giày vò ”, vậy nhất định muốn cho trên triều đình đại thần , còn có người trong thiên hạ một cái thuốc an thần .”\n“ Thái tổ chính mình đi nói , ngươi cảm thấy hữu dụng không ?”\nThái tổ Cao Hoàng Đế chính mình đi nói ? Hữu dụng không ?\nTào Thao nghĩ tới chỗ này , lắc đầu .\nMuốn cho những người thông minh kia tin tưởng Thái tổ Cao Hoàng Đế ? Nhớ tới trên sử sách Thái tổ Cao Hoàng Đế làm một số việc , Tào Thao cảm thấy thật sự rất khó tin tưởng .\n“ Tư Không , đổi Thái tử , đây là trọng yếu nhất đại sự .”\n“ Có thể “ Thương sơn tứ hạo ” Xuất hiện , liền để Thái tổ Cao Hoàng Đế từ bỏ đổi Thái tử ...”\n“ Điều này nói rõ mấy chuyện .”\nQuách Gia lúc này vô cùng nghiêm túc .\n“ Một , “ Thương sơn tứ hạo ” Lúc đó nhất định phi thường có danh vọng .”\n“ Hai , Thái tổ Cao Hoàng Đế tất nhiên mời mấy lần “ Thương sơn tứ hạo ”, vậy cái này “ Thương sơn tứ hạo ” Đối với đại hán tác dụng , nhất định phi thường lớn .”\n“ Ba , đổi Thái tử chuyện lớn như vậy , “ Thương sơn tứ hạo ” Vừa xuất hiện , liền để Thái tổ Cao Hoàng Đế từ bỏ , cái kia này liền biểu lộ Thái tổ Cao Hoàng Đế không muốn lại giày vò .”\n“ Dù sao bên trong hướng sự tình , có so đổi Thái tử càng lớn chuyện sao ? Không có !”\nNói đến đây , Quách Gia bỗng nhiên dừng một chút , nhìn xem màn trời phía trên Lưu Bang khuôn mặt , hơi nghi hoặc một chút nói :\n“ Chờ đã , Tư Không ...”\n“ Ân ?”\nTào Thao nghi hoặc nhìn Quách Gia ánh mắt .\n“ Ngươi nói , này lại sẽ không ở xác lập Lữ hậu quyền hạn ?”\nNghe nói như thế , Tào Thao lập tức lên tinh thần , chăm chú nhìn Quách Gia .\n“ Thái tổ Cao Hoàng Đế không mời được người , Lữ hậu mời tới .”\n“ Hơn nữa , Thái tổ Cao Hoàng Đế muốn đổi Thái tử , nhưng trên triều đình , tất cả mọi người cơ hồ đều đang phản đối đổi Thái tử , đứng tại Lữ hậu sau lưng .”\nNghe được cái này , Tào Thao vuốt vuốt chòm râu , gật đầu một cái nói :\n“ Phụng Hiếu , ngươi nói rất có lý , Thái tổ Cao Hoàng Đế , rất có thể lúc đó cũng nghĩ xác lập Lữ hậu quyền hạn .”\n“ Thái tổ Cao Hoàng Đế biết mình tuổi tác cao , Lữ hậu trừ không xong ...”\n“ Có lẽ , hắn cũng không muốn diệt trừ ?”\n“ Dù sao , một vị mẫu thân , làm sao có thể đi đoạt chính mình hài tử vị trí ?”\n“ Tê ... Nói như vậy , Thái tổ Cao Hoàng Đế , có khả năng cũng là tại dùng một lần này sự kiện , thăm dò Lữ hậu ?”\n“ Thăm dò nàng đối với chính mình hài tử có nhiều “ Yêu ”?”\nGiờ khắc này , Tào Thao ngẩng đầu nhìn màn trời trong hình Lưu Bang .\n“ Ta cuối cùng biết hậu thế vì sao lại nói , Thái tổ Cao Hoàng Đế là tối cường hoàng đế .”\nTào Thao giờ này khắc này rất hoài nghi , Lữ hậu nếu như không phải kiên trì như vậy , Lưu Bang có thể thật sự sẽ đổi Thái tử .\nLữ hậu có khả năng đồng ý không ? Là có khả năng , bởi vì Lữ hậu ngay lúc đó thế lực cũng vô cùng khổng lồ , mà Lưu Bang cũng đến lúc tuổi già .\nNếu như Lữ hậu bỗng nhiên đề nghị , để cho Lưu như ý nhận làm con thừa tự đến danh nghĩa mình ...\nKhả năng này Thái tổ Cao Hoàng Đế , thật sự sẽ hung ác quyết tâm , trực tiếp diệt trừ Lữ hậu .\nDù sao ngay cả mình nhi tử , cũng có thể đổi đi .\nCái kia Thái tổ Cao Hoàng Đế liền sẽ rất hoài nghi , Lữ hậu tại chính mình sau khi chết , có thể hay không làm ra cái gì ?\nThế nhưng cũng bởi vì Lữ hậu thật sự đem “ Thương sơn tứ hạo ” Mời đi ra , Thái tổ Cao Hoàng Đế , ngược lại liền thuận nước đẩy thuyền , trực tiếp xác lập Lữ hậu quyền hạn .\nĐể cho nàng có thể tại chính mình sau khi chết , độc quyền triều chính , vững vàng đỡ lấy Thái tử Lưu Doanh .\n......', 'output\\mp3\\Màn Trời Quyền Lực Diễn Biến Cùng Truyền Thừa\\0068_Thứ 68 chương Thương sơn tứ hạo.mp3', '2026-09-01T23:26:00.455937+00:00', 'completed', 'completed', 7804, 7804),
	(74, 7, '7650390921858515481', 69, 'Thứ 69 chương Tin tưởng?', 'Thứ chương Tin tưởng ?\nHiện đại thời không .\nngười dạng này Lưu Bang , sẽ không giữ lại chút nào tin tưởng Lữ hậu sao ?\nLàm sao có thể ?\nTrước kia , Lưu Bang thế nhưng là làm qua đem Lữ Trĩ cùng Lưu Doanh đạp xuống xe ngựa chuyện , làm sao có thể không giữ lại chút nào tin tưởng Lữ hậu ?\nHoặc có lẽ là , người dạng này Lưu Bang , là không thể nào tin tưởng bất kỳ người nào !\nCho nên , tại Lý Ân Phàm xem ra , Lưu Bang lúc tuổi già đổi Thái tử cử động , thử dò xét thành phần , hẳn là chiếm rất lớn một bộ phận .\nThăm dò Lữ hậu đến cùng có hay không đối với chính mình oán hận , có thể hay không bởi vì oán hận mà để cho đại hán sụp đổ .\nTiền triều sự tình , cũng chính là Đại Tần sự tình , ngay ở phía trước , Lưu Bang sẽ không làm chút gì sao ?\nCho nên Lý Ân Phàm ngờ tới , Lưu Bang hẳn là cố ý dùng một cái rất khó hoàn thành chuyện , đến dò xét Lữ hậu cử động .\nCuối cùng Lữ hậu hoàn mỹ hoàn thành , cái kia Lưu Bang cũng liền thuận nước đẩy thuyền , xác lập Lữ hậu quyền hạn .\nBảo đảm chính mình sau khi chết , trên triều đình , còn có bên ngoài triều , không có ai sẽ nhảy ra tạo phản .\nHoặc có lẽ là , cho dù có người tạo phản , Lữ hậu vì bảo trụ chính mình hài tử Lưu Doanh hoàng vị , sẽ hết sức trấn áp .\nMà Lưu Bang lúc tuổi già , cũng chính xác liền làm cuối cùng như vậy một kiện đại sự .\nSau đó liền chết bệnh ở trên giường .\nLý Ân Phàm nhìn xem Lưu Bang , chính xác vô cùng bội phục , không hổ là trong lịch sử tối cường hoàng đế .\nLúc tuổi già thời khắc cuối cùng , đều phải bảo đảm vương triều an ổn .\n“ Cái này đồ ăn mùi vị không biết như thế nào ? Quý ca .”\nLý Ân Phàm cầm lấy Mao Đài , cho Lưu Bang đổ một chén nhỏ , sau đó lại tiếp tục nói :\n“ Thử lại thử một lần rượu này .”\n“ Hương vị coi như không tệ , nhìn lâu như vậy màn trời , cũng coi như là ăn được .”\nNói xong , Lưu Bang cầm chén rượu lên , một ngụm té ở trong miệng .\n“ Tê ... A !!!”\nLưu Bang nheo mắt lại , vô cùng thỏa mãn .\nCũng may mắn là loại kia phi thường nhỏ chén rượu , dung lượng lớn tất cả chỉ có người trưởng thành ngón út một đoạn lớn nhỏ .\n“ Đây là món gì ?”\nLưu Bang chỉ vào một món ăn nhẹ giọng hỏi Lý Ân Phàm .\n“ Rau trộn thịt lợn .”\n“ Cái mùi này tốt nhất ...”\nNói xong , Lưu Bang đứng lên cầm chai rượu lên , trước tiên cho Lý Ân Phàm rót một chén , sau đó lại cho tự mình ngã một ly , vừa ăn vừa uống .\nLý Ân Phàm lúc này rõ ràng cảm thấy , Lưu Bang không có Thủy Hoàng Đế cùng Mông Điềm như thế lễ tiết .\nNhưng không có lễ phép đồng thời , hắn lại chiếu cố đến người .\n‘ Đây thật là lão Lưu gia Mị Ma thể chất ?’\nLý Ân Phàm thật sự cảm giác trong bất tri bất giác , liền cùng Lưu Bang quan hệ kéo gần lại .\n...\nHiện đại thời không .\n“ Đây là cái gì ? Tiên sinh ?”\nLưu Bang chỉ vào một cái lối vào cửa hàng lung lay ghế dựa , tò mò hỏi Lý Ân Phàm .\n“ Nhi đồng chơi đùa lung lay cơ ...”\n“ Nhi đồng chơi ?”\nNghe nói như thế , Lưu Bang có chút kích động .\nHắn thật là quá hiếu kỳ , đời sau nhi đồng chơi là như vậy đồ vật sao ?\n“ Quý ca ... Muốn đi chơi đùa sao ?”\nLý Ân Phàm ngược lại là cảm thấy không quan trọng , muốn chơi liền chơi thôi , đầu này đường phố , có thể nói đều là người mình , không người đến nói cái gì .\n“ Có thể chứ ?”\nLưu Bang mở to hai mắt , nhìn xem Lý Ân Phàm .\n“ Đi !”\nLý Ân Phàm phất tay liền để Lưu Bang đi theo tự mình đi .\n“ Lão bản , đổi mấy khối tiền xu .”\nLý Ân Phàm lấy điện thoại di động ra , đầu tiên là cầm hai bình nước khoáng , sau đó lấy điện thoại di động ra , đem tiền quét cho lão bản .\n“ Bốn khối ...”\n“ Ân .”\nTiếp nhận tiền xu , Lý Ân Phàm đi ra cửa hàng , đem thủy đưa cho Lưu Bang , sau đó đi đến lung lay cơ phía trước .\n“ Tới , Quý ca , ngồi vào đi , ta tìm tới tệ .”\n“ Hảo !”\nLưu Bang hiếu kỳ đi đến bên người Lý Ân Phàm , Lý Ân Phàm dùng sức đem hắn dìu dắt đi vào .\n“ Muốn bắt đầu rồi !”\nNghe nói như thế , Lưu Bang lập tức liền nghiêm túc .\nĐông !\nLý Ân Phàm bỏ tiền , sau đó lung lay cơ bắt đầu bắt đầu chuyển động .\n“ Ba ba của ba ba , gọi gia gia .”\n“ Mụ mụ mụ mụ , kêu bà nội ...”\n“ Ai ?”\nLưu Bang đột nhiên trợn to hai mắt nhìn về phía Lý Ân Phàm .\nMà Lý Ân Phàm nhìn xem Lưu Bang biểu lộ , nghi ngờ nhìn về phía hắn .\n“ Tiên sinh , cứ như vậy ?”\n“ Đúng a , cứ như vậy .”\nLời này vừa ra , Lưu Bang một chút cũng có chút nhụt chí .\nHắn còn tưởng rằng sẽ giống trên đường cái pháo những cái kia hộp , có thể đi ra ngoài đâu .\n“ Chờ đã , Quý ca , ngươi sẽ không cho là sẽ giống như vậy đi ?”\nLý Ân Phàm chỉ vào trên đường cái chạy qua ô tô , mắt trợn tròn , ngạc nhiên hỏi Lưu Bang .\n“ Đúng a .”\n“ Đây là nhi đồng chơi , làm sao có thể nguy hiểm như vậy .”\nLý Ân Phàm có chút dở khóc dở cười đối với Lưu Bang nói .\nThua thiệt hắn còn tưởng rằng Lưu Bang là nhi đồng tâm phát tác , muốn chơi một chút cái này .\nDù sao nam nhân mà , đến chết cũng là thiếu niên .\nLão nam nhân xuất hiện một điểm tính trẻ con , cũng là rất bình thường .\n“ Ai , tính toán , tiên sinh , đi thôi !”\nLần này buổi trưa , Lưu Bang giống hiếu kỳ Bảo Bảo , trông thấy một thứ , bắt lấy Lý Ân Phàm liền hỏi .\nNhìn xem dường như là có thể chơi , liền hỏi có thể hay không đi chơi .\nLý Ân Phàm không có chút nào không kiên nhẫn , bởi vì đây đúng là hắn cứng nhắc trong ấn tượng , khác xa hoàng đế hình tượng .\nTại hắn trước kia cứng nhắc trong ấn tượng , hoàng đế tựa hồ cũng là uy nghiêm , bưng thân thể .\nNhưng Lưu Bang , một ngày này chờ đợi , hoàn toàn không có !\nKhông có một tia hoàng đế uy nghiêm , hoàn toàn giống như một cái hiếu kỳ Bảo Bảo .\n...\nHiện đại thời không .\nBan đêm .\n“ Đúng , trực tiếp tới là được rồi .”\nTrong gian phòng , Lưu Bang ngồi ở trên ghế sa lon , vô cùng chăm chú nhìn TV .\nLý Ân Phàm đâu ? Nhưng là gọi điện thoại .\n“ Quý ca ...”\n“ Ân ? Tiên sinh ...”\nLưu Bang lấy lại tinh thần , nghi ngờ nhìn về phía Lý Ân Phàm .\n“ Đợi chút nữa bác sĩ sẽ tới ...”\n“ Bác sĩ ?”\n“ Chính là cùng thái y lệnh một dạng .”\n“ A ? Hắn tới làm gì ?”\nLưu Bang ngồi ở trên ghế sa lon , gãi gãi đầu , sau đó học vừa rồi Lý Ân Phàm dáng vẻ , ngồi xếp bằng trên ghế sa lon .\n“ Cho ngươi xem xem xét cơ thể .”\n“ Đúng , ngươi bên kia là Hán mấy năm ?”\n“ Hán bảy năm ?”\n“ Hán bảy năm sao ? Quý ca , ngươi biết ngươi là bao lâu qua đời sao ?”\nLời này vừa ra , Lưu Bang nháy nháy mắt nhìn xem Lý Ân Phàm .\n“ Hán mười hai năm .”\n“ A !”\nLưu Bang bình tĩnh gật đầu một cái , sau đó lực chú ý lại bị TV hấp dẫn .\n“ Tê ...”\nLý Ân Phàm nhìn xem tình huống này , hơi kinh ngạc , sau đó ngồi vào bên người Lưu Bang .\n“ Quý ca , ngươi không lo lắng thân thể của mình ?”\n“ Lo lắng cái gì ?”\nLưu Bang lại nghi hoặc nhìn xem Lý Ân Phàm .\n“ Ngươi còn có 5 năm .”\n“ 5 năm liền 5 năm thôi , tiên sinh , ta vẫn rất cao hứng , chỉ còn dư 5 năm .”\nLưu Bang chính xác vô cùng bình tĩnh , trong giọng nói tựa hồ còn có vẻ vui sướng .\nLần này , trực tiếp đem Lý Ân Phàm kiếm không ra , có chút mộng nhìn xem Lưu Bang .\n......', 'output\\mp3\\Màn Trời Quyền Lực Diễn Biến Cùng Truyền Thừa\\0069_Thứ 69 chương Tin tưởng.mp3', '2026-09-01T23:27:01.009556+00:00', 'completed', 'completed', 6739, 6739),
	(75, 7, '7650740696298553881', 70, 'Thứ 70 chương Không hiểu theo nghĩ ghi chép', 'Thứ chương Không hiểu theo nghĩ ghi chép\nHiện đại thời không .\nBan đêm .\nLý Ân Phàm nằm ở trên giường , lăn qua lộn lại ngủ không được , trong đầu đang nghĩ ngợi sự tình .\n“ Ai , không nên uống bình kia đồ uống chức năng .”\nCơ thể của Lý Ân Phàm chính là có điểm ấy mao bệnh , ban ngày uống đồ uống chức năng , buổi tối thật sự lăn qua lộn lại ngủ không được , trong đầu vô cùng hoạt động mạnh .\n“ Quý ca thật sự , xác lập căn cơ sau đó , 4 năm liền quét ngang thiên hạ ...”\nVừa nghĩ đến cái này , Lý Ân Phàm “ Cọ ” Một chút ngồi dậy .\n“ Chờ đã ! 4 năm ?”\nGiờ khắc này , Lý Ân Phàm cảm giác vô hình vô cùng quen thuộc .\n4 năm bốn , cái số này , đột nhiên xúc động hắn có chút thần kinh nhạy cảm ...\n“ Lưu Bang tiến vào quan bên trong , Định Tam Tần , tiếp đó 4 năm quét ngang thiên hạ ?”\nở đâu ?”\nLý Ân Phàm cầm lấy đặt ở trên bên cạnh gối điện thoại , nghiêm túc tìm tòi một chút .\n“ Ba Tần Chi Địa , hiện đại Thiểm Tây ?”\n“ Mà cũng tại Thiểm Tây ?!”\nLần này , Lý Ân Phàm hứng thú lập tức liền dậy .\nBởi vì , đánh xong ngoại địch , bản triều lập quốc , cũng là 4 năm quét ngang thiên hạ !\n“ 4 năm ? 4 năm ?”\n“ Đây là trùng hợp ?”\nSau đó Lý Ân Phàm lại bắt đầu suy tư trên sử sách ghi chép , đại hán vừa lập sự kiện lớn .\n“ Hán bảy năm , Lưu Bang đối kháng ngoại địch , bị vây nhốt tại Bạch Đăng núi , cuối cùng thỏa hiệp tại Hung Nô ...”\nBản triều có không ? Có ...\n“ Sau khi dựng nước trận chiến kia ...”\n“ Trận chiến kia thắng sao ? Kỳ thực là thua , bởi vì tại chính mình bên giường , từ đầu đến cuối nằm một cái cự nhân .”\nNghĩ tới đây , Lý Ân Phàm đứng dậy mặc quần áo tử tế , đi đến tủ đầu giường trước mặt , lấy ra máy vi tính xách tay (bút kí) cùng bút máy .\n“ Từ hướng này đến xem , kiến triều sau đó bối cảnh , cũng giống nhau như thế ...”\n“ Sau đó chính là đại hán lập triều sau đó , bắt đầu bình định quốc nội vương khác họ ...”\nBản triều có không ?\nLý Ân Phàm nghĩ tới đây , cầm lấy bút máy tay , dừng một chút .\n“ Cũng có , biên cảnh , quốc nội một chút nạn trộm cướp còn có dị tộc “ Quý tộc ”...”\nViết xuống điểm này , Lý Ân Phàm lại tại máy vi tính xách tay (bút kí) phía dưới , viết xuống hai chữ : Truyền thừa ...\n“ Đại hán đời thứ hai , tên là Lưu Doanh , thật là Lữ hậu ....”\n“ Mà bản triều , nếu như không phải ....”\nGiờ khắc này , Lý Ân Phàm đột nhiên có chút hoảng hốt ...\nĐúng vậy a , nếu như không phải , cái kia bản triều có phải hay không cũng cùng đại hán không sai biệt lắm ?\n“ Ba Tần Chi Địa liền như thế thần kỳ sao ?”\nGiờ khắc này Lý Ân Phàm vô cùng muốn quất một điếu thuốc , sau đó cầm lấy đặt ở đầu giường khói cùng cái bật lửa , cho mình điểm một chi .\n“ Lưu Triệt đâu ? Đại hán lớn nhất bước ngoặt Lưu Triệt , là đại hán thứ mấy Nhậm Hoàng Đế ?”\n“ Đệ thất nhậm ....”\n“ Mà bản triều , bây giờ ngồi tại chỗ , cũng là đối với lớn xinh đẹp công thủ Dịch Hình , là thứ mấy mặc cho ?”\nLý Ân Phàm lúc này vô cùng nghiêm túc cầm ra chỉ , từng cái từng cái bắt đầu đếm .\n“ Cũng là đệ thất nhậm ...”\nPhanh ...\nLý Ân Phàm vô ý thức ném bút , bắt đầu hút thuốc ...\nTừng ngụm ...\n“ Hán Huệ đế Lưu Doanh ...”\n“ Phía trước Thiếu đế Lưu Cung ...”\n“ Sau Thiếu đế Lưu Hoằng ...”\n“ Nhân sinh của bọn hắn quỹ tích , cũng cùng bây giờ đời thứ hai , đời thứ ba , đời thứ tư tựa hồ vô cùng phù hợp ...”\n“ Đến Hán văn đế Lưu Hằng , Hán cảnh đế Lưu khải , lại là như thế ...”\n“ Văn Cảnh nhị đế , cho hậu thế lưu lại “ Văn Cảnh chi trị ” Thanh danh tốt đẹp ...”\n“ Nếu như hậu thế cho bây giờ viết sách sử , có thể hay không cũng đối phía trước hai vị tràn đầy tán dương ?”\n“ Bởi vì chính xác nếu như không có phía trước hai vị ẩn nhẫn , như thế nào lại có đương nhiệm đối với lớn xinh đẹp công thủ Dịch Hình đâu ?”\nLý Ân Phàm lại cầm bút lên , bắt đầu vô ý thức đánh .\n“ Mà Hán Vũ Đế Lưu Triệt , đối với Hung Nô lần thứ nhất Mã Ấp sau đó , mặc dù thất bại , thế nhưng bắt đầu đã chứng minh , đại hán cùng Hung Nô đã công thủ Dịch Hình .”\n“ Mà bản triều ....”\n“ Nam Hải ...”\nGiờ này khắc này , Lý Ân Phàm thật sự cảm thấy , lịch sử giống như là một cái vòng tròn ...\nĐại thế lại một lần nữa lặp lại , bắt đầu xuất hiện ...\n“ Hạng Vũ đâu ? Hắn lại đại biểu là ai ?”\n“ Lật lọng , tự đại , bảo thủ , lừa giết hàng binh , đồ thành ...”\nNghĩ tới đây , Lý Ân Phàm không hiểu trong đầu xuất hiện một người đầu trọc .\nTên đầu trọc này , cũng vô cùng giống ...\n“ Hơn nữa , Hán Thừa Tần Chế ...”\n“ Bản triều , tiếp nhận chính là ai ? Dân quốc ...”\n“ Sùng Trinh đến rõ ràng diệt vong , hết thảy bao nhiêu năm đến hết thảy năm .”\n“ Chiến quốc bắt đầu , đến Tần triều thiết lập , lại trải qua bao nhiêu năm ?”\n“ Chủ lưu quan điểm , là Công Nguyên phía trước năm , Chu Nguyên Vương năm đầu làm điểm xuất phát , cũng là bây giờ các loại lịch sử sách giáo khoa phổ biến áp dụng tiêu chuẩn .”\n“ Đến Tần triều thiết lập , trước công nguyên năm .”\nnăm ...”\nnăm năm ...”\n“ Không đúng , nếu như đem Nam Minh tính cả năm Ngô Tam Quế tại Côn Minh treo cổ vĩnh lịch đế , bị coi là Nam Minh lịch sử chính thức kết thúc\n“ Đó chính là năm ...”\nKhi Lý Ân Phàm viết xuống hai cái này con số , sững sờ tại chỗ .\nCòn kém 4 năm ?\nLấy trăm năm làm đơn vị trên tuyến thời gian , còn kém 4 năm ?\n“ Bốn năm này , hẳn là cho phép bên trong sai sót , dù sao Tư Mã Thiên viết Sử Ký thời điểm , lịch Sử Ký tái không có hiện tại dạng này toàn diện .”\n“ Cũng không có hiện đại thủ đoạn như vậy đi ghi chép lịch sử .”\n4 năm , là tuyệt đối cho phép sai sót .\n“ Dân quốc , cũng liền ngồi như vậy một cái , đến thứ hai cái thời điểm , liền đã không cách nào che giấu xu hướng suy tàn ...”\n“ Tần triều , cũng chính là Tần Thuỷ Hoàng , đến thứ hai cái Hồ Hợi thời điểm , cũng bắt đầu không thể che hết xu hướng suy tàn ...”\nLý Ân Phàm giờ khắc này đang suy nghĩ , đến cùng là ba Tần Chi Địa , nơi này có thuyết pháp .\nVẫn là lịch sử thật là một cái vô cùng cực lớn tròn ?\nCái này một mảnh bên trên đại địa , trải qua đại thế , vô số năm sau , lại bắt đầu tái diễn xuất hiện ?\nQuỹ tích , đại thế , đều cùng khi đó vô cùng giống nhau ?\nLý Ân Phàm nội tâm thời khắc này , không thể nói là trùng hợp , thật sự chính là đại thế chính là như thế ?\nLại hoặc là nói , quốc vận thứ này , chẳng lẽ là thật tồn tại ?\nHỗn loạn hai trăm năm mươi năm , giống như là chiến quốc , tiếp đó , lại bắt đầu quật khởi , quét ngang thiên hạ .\nChỉ là , thời điểm đó đại hán , là quét ngang xung quanh dị tộc ...\nMà giờ khắc này đâu ? Hoặc có lẽ là , hiện đại đâu ?\n“ Hơn nữa , đồng dạng có một cái , năng lực quân sự siêu cường , chính trị năng lực lại hết sức thấp hèn thống soái .”\nMột lần nữa trở lại trên giường , Lý Ân Phàm nhìn ngoài cửa sổ dạ quang , chỉ cảm thấy không hiểu mất mát .\n...\nMột chương này , coi như giả suy nghĩ lung tung a , vốn chính là bởi vì ban ngày uống một bình đồ uống chức năng , buổi tối nằm ở trên giường thời điểm , lăn qua lộn lại ngủ không được .\nTiếp đó liền bỗng nhiên nghĩ tới Lưu Bang xác lập căn cơ , định ba Tần sau đó , chỉ dùng 4 năm liền quét ngang thiên hạ .\nSau đó thì sao ? Liền lại nghĩ tới , chúng ta giống như cũng chỉ dùng 4 năm ...\nSau đó vẫn phát tán nghĩ , không hiểu thấu , liền nghĩ đến nhiều như vậy .\nLúc đó suy nghĩ , ngược lại suy nghĩ nhiều như vậy , vậy dứt khoát liền nhớ kỹ .\nMột chương này có thể quả thật có chút không hiểu thấu , không thích quên chính là .\n......', 'output\\mp3\\Màn Trời Quyền Lực Diễn Biến Cùng Truyền Thừa\\0070_Thứ 70 chương Không hiểu theo nghĩ ghi chép.mp3', '2026-09-01T23:27:06.576925+00:00', 'completed', 'completed', 7177, 7177),
	(76, 7, '7650740853077459481', 71, 'Thứ 71 chương Có cần hay không năng lực quân sự?', 'Thứ chương Có cần hay không năng lực quân sự ?\nHiện đại thời không .\n“ Đây là cái gì ? Tiên sinh ?”\nLưu Bang uống một ngụm sữa đậu nành , vô cùng thỏa mãn , sau đó tò mò hỏi Lý Ân Phàm .\n“ Sữa đậu nành ...”\n“ Cổ đại xuất hiện thời gian ? Ta có chút không nhớ rõ , để cho ta tra một chút ...”\nLý Ân Phàm lấy điện thoại di động ra , tìm tòi một chút .\n“ A , đây là các ngươi đại hán thời kì , Tây Hán lúc Hoài Nam Vương Lưu An phát minh .”\nLý Ân Phàm là nhớ kỹ sữa đậu nành xuất hiện rất sớm , có thể thực không nghĩ tới , vậy mà xuất hiện sớm như vậy .\n“ Đúng , ta nhớ được đậu hũ , giống như cũng là cái này Hoài Nam Vương Lưu An phát minh .”\n“ Cái này con cháu đời sau cũng không tệ lắm !”\nLưu Bang hài lòng gật đầu một cái , hắn cũng không có gì con cháu đời sau nhất thiết phải làm ra một phen sự nghiệp ý nghĩ .\nGiống như hắn , nếu như không phải bị bất đắc dĩ , hắn là thực sự không nghĩ tới binh .\nMỗi ngày thoải mái nhàn nhã phóng đãng tại bái huyện đầu đường , không buồn không lo , không tốt sao ?\n“ Đúng , tiên sinh , ta đột nhiên nghĩ đến một chuyện .”\n“ Ta nhớ được ngươi nói , ta là trong lịch sử tối cường hoàng đế , nhưng lại nói ta là trong chính trị tối cường .”\n“ Trên quân sự là Lý Thế Dân .”\n“ Tổng hợp , là Hán Vũ Đế Lưu Triệt .”\n“ Tại sao lại nói thế nào ?”\nNói xong , Lưu Bang cắn một cái bánh bao , lại nói :\n“ Đúng , cái này Hán Vũ Đế Lưu Triệt , là con cháu của ta a ?”\n“ Ân , cái này Hán Vũ Đế Lưu Triệt , là con cháu của ngươi .”\n“ Hắn là đại hán đệ thất nhậm hoàng đế .”\nLý Ân Phàm đem trong tay một điểm cuối cùng bánh bao cùng sữa đậu nành ăn hết tất cả , sau đó xoa xoa tay cùng miệng , chờ sau khi lau xong , mới dùng tiếp tục nói :\n“ Về phần tại sao rõ ràng nói ngươi là trong chính trị tối cường hoàng đế , lại là trong lịch sử lợi hại nhất hoàng đế ...”\n“ Bởi vì nơi này có một cái hiện đại chúng ta thường xuyên biện luận , hoặc có lẽ là cãi vả một cái chủ đề .”\nNghe nói như thế , Lưu Bang ngẩng đầu , chăm chú nhìn Lý Ân Phàm .\n“ Một cái hoàng đế , hắn có cần hay không năng lực quân sự ?”\nLời này vừa ra , Lưu Bang kinh ngạc nhìn Lý Ân Phàm .\nHoàng đế , hắn cần năng lực quân sự sao ?\n“ Lấy cá nhân ta góc độ cùng góc nhìn đến xem , hoặc có lẽ là , liền vẻn vẹn chỉ là ta cá nhân ý nghĩ .”\n“ Hoàng đế , hắn là không cần năng lực quân sự !”\n“ Hắn cần biết , hoặc có lẽ là , nhất định phải biết , là cái gì ? Là dùng người năng lực !”\n“ Nhìn thấu thủ hạ thần tử năng lực , sau đó thì sao ? Đem bọn hắn đặt ở vị trí thích hợp nhất phía trên , để cho bọn hắn đi phát huy tài năng của mình .”\nNói đến đây , Lý Ân Phàm làm ra một cái ví dụ .\n“ Điểm này , từ hậu thế vương triều , cũng chính là Minh triều đời cuối hoàng đế , Sùng Trinh đế Chu Do Kiểm trên thân , có thể nói biểu hiện phát huy vô cùng tinh tế .”\n“ Hắn chính là điển hình không biết dùng người , càng sẽ không xem người .”\n“ Cái này cũng liền tạo thành một cái tình huống , hắn càng cố gắng , càng chuyên cần chính sự , mà Minh triều , cũng liền diệt vong càng nhanh .”\n“ Tại vị mười bảy năm , hắn phế đi hơn 20 tên biên cảnh đại quan , nội các thủ phụ , Binh bộ Thượng thư .”\n“ Ở trong đó , cùng giết vị Binh bộ Thượng thư vị Tổng đốc vị Tuần phủ trong đó nhiều kiêm biên cảnh quân vụ .”\n“ Bị giết bao quát : Viên Sùng Hoán ( Kế Liêu Đốc Sư ), Mao Văn Long ( Đông Giang trấn tổng binh , tuy không phải Sùng Trinh sơ giết nhưng lấy được hắn ngầm đồng ý ), Lưu Sách ( Kế Liêu Tổng đốc ), Trần Tân Giáp ( Binh bộ Thượng thư kiêm Đốc Sư ), Nhan Kế Tổ ( Núi đông Tuần phủ ) các loại .”\n“ Có khác Tôn Thừa Tông , Lô Tượng Thăng , Hồng Thừa Trù , Tôn Truyền Đình mấy người hoặc bị trục xuất , hoặc chết trận , hoặc hàng Thanh , không phải đều do Sùng Trinh trực tiếp “ Phế trừ\nLý Ân Phàm nói , đi đến trên phòng khách kệ sách , rút ra một bản ghi lại Minh triều sách sử .\nSau đó , đem sách sử đưa cho Lưu Bang .\nTại đem sách sử đưa cho Lưu Bang đồng thời , Lý Ân Phàm còn chuyên môn cho hắn lộn tới cuối cùng , ghi lại Sùng Trinh hướng cái kia một tờ bắt đầu .\n“ Biên cảnh thối nát đi ?”\n“ Hơn nữa , tiên sinh , nghe ngươi nói , cái này Minh triều là đời cuối hoàng đế , cái kia rất rõ ràng , là biên cảnh phá ...”\nLưu Bang không thấy bao lâu , liền suy đoán được Minh triều diệt vong một nguyên nhân quan trọng .\n“ Chính xác như thế , cuối cùng để cho phía bắc dị tộc nhập quan , sau đó đem Minh triều diệt .”\n“ Biên giới thối nát , chung quy là chính hắn tạo thành .”\n“ Mặc dù phía nam còn có một cái Nam Minh , thế nhưng chỉ là kéo dài hơi tàn thôi .”\nSau đó , Lý Ân Phàm lại từ trên giá sách lấy ra mấy quyển sách sử , phân biệt ghi lại 《 Nam Bắc triều 》 cùng 《 Ngũ Đại Thập Quốc 》.\n“ Mà cái này hai quyển sách sử , còn nói rõ một sự kiện .”\n“ Một vị hoàng đế , năng lực quân sự mạnh , chính trị có thể sức yếu , có thể hay không bình định thiên hạ ?”\n“ Rất đáng tiếc , không thể !”\n“ Năng lực quân sự lại mạnh , nếu như không có chính trị năng lực , hoặc chính trị năng lực thấp , hắn cũng chỉ là hoa quỳnh một huyện .”\nTại Lưu Bang nghiêm túc liếc nhìn sách sử đồng thời , Lý Ân Phàm tiếp tục chậm rãi nói :\n“ Cho nên từ rất sớm bắt đầu , ta liền bắt đầu nghĩ một vấn đề .”\n“ Một vị hoàng đế , hắn đến tột cùng có cần hay không rất mạnh năng lực quân sự ?”\n“ Dù là hắn là khai quốc hoàng đế , có cần hay không năng lực quân sự đâu ?”\nLưu Bang nhanh chóng liếc nhìn sách , trên sách chữ , hắn cũng nhìn hiểu .\nBởi vì Lý Ân Phàm vì phương diện người trong lịch sử đi tới hiện đại , mỗi một chữ sách sử , hắn đều lưu có .\nTừ Tần triều chữ tiểu triện bắt đầu , mãi cho đến chữ giản thể .\n“ Vì cái gì ta biết nói Đường Thái Tông Lý Thế Dân là năng lực quân sự tối cường hoàng đế ? Mà không phải năng lực quân sự người mạnh nhất ?”\n“ Bởi vì Nam Bắc triều thời kì , còn có Ngũ Đại Thập Quốc , xuất hiện thiên tài quân sự , thật sự nhiều lắm .”\n“ Lý Thế Dân là bởi vì thành công , hơn nữa làm tới hoàng đế , cho nên mới có thể chịu vinh hạnh đặc biệt này .”\n“ Nhưng trong lịch sử , những cái kia thất bại , so với hắn lợi hại thiên tài quân sự , thật sự nhiều lắm .”\n“ Nam Bắc triều thời kỳ ngươi Chu Vinh , chính là ví dụ điển hình .”\n“ Hơn nữa , nói thật ...”\nLý Ân Phàm dừng một chút , sau đó lại đối Lưu Bang nói :\n“ Ta kỳ thực cảm thấy chiến tranh niên đại , lúc hỗn loạn kỳ quật khởi hoàng đế , so những thứ khác thời kì hoàng đế đều phải mạnh hơn một đoạn .”\n“ Vì cái gì ?”\n“ Bởi vì tại những thứ khác thời kì , ngươi đối mặt đối thủ , có thể năng lực tổng hợp chỉ có năm , mà chính ngươi đâu ? Năng lực tổng hợp là mười !”\n“ Nam Bắc triều thời kì , còn có Ngũ Đại Thập Quốc thời kì , ngươi năng lực tổng hợp là mười , đối thủ của ngươi , có thể chính là chín , hay là mười một .”\nCái này kỳ thực cũng là về sau , Lý Ân Phàm cảm thấy hai thời kỳ này thiên kiêu , so trong lịch sử khác thời kì có thể đều mạnh hơn ra một đoạn nguyên nhân .\nBởi vì có cái sự thực rất đơn giản .\nNếu như năng lực của ngươi là mười , đối thủ của ngươi năng lực là năm , vậy ngươi đối mặt cục diện chính là nghiền ép cục .\nMà nghiền ép cục tràng diện , nhìn liền vô cùng làm cho người khoa trương .\nCái này cũng liền tạo thành một cái để cho người ta ấn tượng mơ hồ , tựa hồ những hoàng đế này , giống như rất mạnh .\nNhưng hai thời kỳ này , Nam Bắc triều , Ngũ Đại Thập Quốc , cùng với cuối Tần , Tùy mạt , cuối thời nhà Nguyên , xuất hiện thiên kiêu cùng nhân kiệt .\nNăng lực của bọn hắn là mười hai , bọn hắn đối thủ , năng lực là bao nhiêu ? Là mười một .\nMà lúc này , xuất hiện cục diện , liền sẽ đối kháng lẫn nhau , cũng không phải là dễ nhìn như vậy rồi .\nChu Nguyên Chương cùng Trần Hữu Lượng chính là như thế ...\n......', 'output\\mp3\\Màn Trời Quyền Lực Diễn Biến Cùng Truyền Thừa\\0071_Thứ 71 chương Có cần hay không năng lực quân sự.mp3', '2026-09-01T23:28:02.458825+00:00', 'completed', 'completed', 7514, 7514),
	(77, 7, '7651117090069299737', 72, 'Thứ 72 chương Thời kỳ hòa bình, chiến loạn thời kì?', 'Thứ chương Thời kỳ hòa bình , chiến loạn thời kì ?\nCầu một đợt khen thưởng , thuận tiện cũng cầu một đợt thúc canh , độc giả các đại lão , đều điểm một điểm thúc canh , cảm tạ\nHiện đại thời không .\n“ Mà có Nam Bắc triều cùng Ngũ Đại Thập Quốc ví dụ như vậy , cho nên liền không thể tránh khỏi về tới vừa rồi cái đề tài kia .”\n“ Một vị hoàng đế , năng lực quân sự của hắn chính xác vô cùng mạnh , nhưng hắn chính trị có thể sức yếu đâu ?”\n“ Cho nên , một vị hoàng đế , ngược lại , có cần hay không năng lực quân sự ?”\nLý Ân Phàm nhìn xem Lưu Bang , nói rất chân thành :\n“ Trong mắt của ta , thật không cần năng lực quân sự , vẫn là câu nói kia , chỉ cần hắn chính trị năng lực vượt qua cùng thời đại những người khác một mảng lớn .”\n“ Vậy hắn thu được xác suất thành công , cũng liền so với người khác lớn hơn nhiều .”\n“ Đây cũng chính là ta cho rằng , ngươi tại sao là trong lịch sử chính trị năng lực tối cường hoàng đế , sau đó thì sao ? Lại là trong lịch sử tối cường hoàng đế .”\nMà nói đến điểm này , Lý Ân Phàm kỳ thực cũng là về sau , mới phát giác được có chút không hiểu thấu .\nVì cái gì một vị hoàng đế , cần nhìn hắn năng lực quân sự ?\nHơn nữa , muốn lấy năng lực quân sự tới xem như hoàng đế bình phán một trong những tiêu chuẩn ?\nHoàng đế , hắn thật sự cần rất mạnh năng lực quân sự sao ?\nNếu như cần , vậy hắn đến cùng là hoàng đế , vẫn là võ tướng ? Lại hoặc là nói là thống soái ?\nLý Thế Dân năng lực quân sự rất mạnh a ? Cũng bị lão sư định giá năng lực quân sự tối cường hoàng đế một trong .\nNhưng vì cái gì biết nói , Lý Thế Dân năng lực quân sự , không phải trong lịch sử người mạnh nhất ?\nBởi vì tại trước mặt hắn , không chỉ là hạng phía trước , cũng là lịch sử phía trước .\nNgươi Chu Vinh , Lưu Dụ , Thác Bạt Đảo , Vũ Văn Thái , Vi Hiếu Khoan vân vân nhân kiệt , đều tại trước mặt của hắn .\nLý Thế Dân 3000 Huyền Giáp hướng 10 vạn thật lợi hại a ?\nLưu Dụ , thành danh chi chiến , bình định Tôn Ân chi loạn , lúc đó người gần trung niên Lưu Dụ , vẫn là phổ thông nhất tiểu binh , mang theo một đội binh sĩ hội chiến Tôn Ân mấy ngàn người phần tử vũ trang , hoàn toàn là một hồi xích lỏa lỏa trực tiếp vũ lực vật lộn .\nGiết lùi hơn trăm người , lệnh quân địch sợ vỡ mật\nVề sau Bắc phủ binh đại bộ đội đuổi tới trợ giúp , nhìn thấy chính là Lưu Dụ một người đuổi theo hơn ngàn quân địch chém tràng diện .\nNhưng vì cái gì cuối cùng cái này một số người thất bại ?\nNgười thừa kế là thứ nhất , thứ hai chính là bọn hắn chính trị năng lực , đúng là ngược lại hơi yếu .\nCho nên , năng lực quân sự lại mạnh thì thế nào đâu ?\nHạng Vũ năng lực quân sự cũng đủ mạnh , nhưng vì cái gì cuối cùng hắn ngược lại thất bại ?\nMặc dù Hạng Vũ tại 《 Sử Ký 》 bên trong , đúng là tại Đế Vương bản kỷ .\n“ Về sau ta suy nghĩ cẩn thận rất lâu , vì cái gì đời sau rất nhiều người , nhìn một cái đế vương chiến công , đều muốn đi nhìn hắn năng lực quân sự ?”\n“ Cuối cùng ta tìm được đáp án .”\nNghe nói như thế , Lưu Bang để quyển sách trên tay xuống , chăm chú nhìn Lý Ân Phàm .\n“ Bởi vì năng lực quân sự là dễ dàng nhất nhìn ra được , cũng là tối trực quan .”\n“ Thắng hoặc bại ? Đại thắng hoặc đại bại ? Kỳ thực liền vô cùng ngay thẳng sáng tỏ đặt tại trước mặt .”\n“ Mà chính trị năng lực đâu ? Vô cùng không dễ dàng nhìn ra .”\n“ Bởi vì một chính sách , thường thường là nhuận mưa mảnh im lặng , cần mấy năm , hay là mười mấy năm , mới có thể thể hiện ra .”\n“ Mà đề chấn quốc lực , lại là vô cùng khó khăn , cũng là cần mười mấy năm hoặc mấy chục năm , mới có thể thể hiện ra .”\n“ Hơn nữa , thể hiện ra sau đó , rất nhiều người ngược lại đem chiến công , đặt tại lúc ấy hoàng đế trên thân .”\nLưu Bang khẽ gật đầu , vô cùng tán đồng Lý Ân Phàm lời nói này .\n“ Trừ cái đó ra , chính trị năng lực thể hiện , hơi trực quan một điểm , chính là chính trị tranh đấu .”\n“ Nhưng chính trị đấu tranh , quyền lực đấu tranh , lại là vô cùng bí mật , hoặc có lẽ là không thể tồn tại .”\n“ Dù sao thứ này , tại các triều đại đổi thay người xem ra , đều vô cùng dơ bẩn , không thể nói nhiều nhân ngôn .”\n“ Cho nên , chính trị năng lực phương diện này , so sánh năng lực quân sự , chính xác rất khó coi đi ra .”\nĐiểm này cũng là Lý Ân Phàm về sau tràn đầy cảm ngộ .\nCũng là hiểu được vì cái gì rất nhiều người , nhìn hoàng đế , hoặc có lẽ là bình phán hoàng đế thời điểm , năng lực quân sự ngược lại bao gồm đi vào .\n“ Dùng rất trực quan lời nói , chính là thùng gỗ lý luận a .”\n“ Quý ca , ngươi gặp qua thùng gỗ sao ?”\nThùng gỗ ?\nLưu Bang gật đầu một cái , bọn hắn thời đại , dùng chính là thùng gỗ .\n“ Một cái thùng gỗ , chứa bao nhiêu thủy , là dài nhất cái kia tấm ván gỗ quyết định sao ?”\n“ Không phải , là ngắn nhất cái kia tấm ván gỗ quyết định !”\n“ Mà trong mắt của ta , cái kia ngắn nhất tấm ván gỗ , chính là chính trị năng lực .”\nDạng này ví dụ , Lưu Bang lập tức liền nghe đã hiểu , cũng hiểu vì cái gì Lý Ân Phàm biết nói , năng lực quân sự quyết định không được một cái hoàng đế năng lực .\n“ Hơn nữa , nói thật , năng lực quân sự có cần hay không xếp tới trong cái vại nước này , kỳ thực cũng không có quan trọng muốn .”\n“ Chỉ cần một cái hoàng đế sẽ dùng người , biết nhìn người , có thể đem thủ hạ thần tử , đặt ở trên vị trí thích hợp , vậy hắn chính là hợp cách hoàng đế .”\nSau đó , Lý Ân Phàm lắc đầu , khẽ thở dài một tiếng rồi nói ra :\n“ Nếu như một cái thời kỳ nào đó , cần hoàng đế làm thống soái , hoặc có lẽ là hoàng đế ra trận phía trước ...”\n“ Vậy cái này vương triều , cũng liền đến sinh tử tồn vong trước mắt .”\nĐến nỗi Minh triều Vĩnh Lạc đế Chu Lệ , hắn tình huống đằng sau biết nói , bởi vì hắn lúc đó đối mặt cục diện cùng cục thế chính trị , cùng các triều đại đổi thay cũng khác nhau , cũng là trong lịch sử duy nhất xuất hiện cục diện .\nCục diện như vậy và thế cuộc , ép hắn không thể không tự thân lên chiến trường .\nĐương nhiên , cũng có khả năng , dạng này thế cục là Chu Lệ vô cùng vui lòng nhìn thấy .\n“ Đúng vậy a , nếu như một cái hoàng đế , đều cần tự mình mang binh làm thống soái , đúng là sắp tới sinh tử tồn vong trước mắt ...”\nLưu Bang đối với điểm này cũng có chút cảm khái .\nCuối Tần lúc đó , Lưu Bang thật sự nguyện ý tự mình mang binh sao ?\nChắc chắn là không muốn .\nNhưng khi đó cục diện , để cho hắn nhất thiết phải tự mình mang binh .\n...\nMinh triều .\nVĩnh Lạc bảy năm .\n“ Lão đại , ngươi nói , một vị hoàng đế có cần hay không năng lực quân sự ?”\nChu Lệ quay đầu nhìn về phía bên cạnh Chu Cao Sí .\n“ Cần , cũng không cần ...”\n“ A ?”\nNghe được Chu Cao Sí nói như vậy , Chu Lệ lập tức tò mò .\n“ Nói cần , là bởi vì một vị hoàng đế , nếu như chính trị năng lực hơi yếu , vậy hắn năng lực quân sự , liền cần vô cùng mạnh .”\n“ Đặc biệt là tại chiến loạn thời kì , thì càng là như thế .”\n“ Mà một vị hoàng đế , nếu như chính trị năng lực vô cùng mạnh , mạnh hơn cùng thời kỳ những địch nhân khác một mảng lớn , vậy hắn không cần năng lực quân sự .”\n“ Giống như màn trời nói , năng lực quân sự là thêm gấm thêm hoa một loại .”\n“ Mà tới được thời kỳ hòa bình , thì càng là như thế .”\n“ Thời kỳ hòa bình hoàng đế cần năng lực quân sự sao ? Thì càng không cần !”\n“ Giống như là gia gia , năng lực quân sự của hắn liền vô cùng mạnh , nhưng đây là hắn nguyện ý sao ?”\nChu Cao Sí nói đến đây , khe khẽ lắc đầu sau tiếp tục nói :\n“ Là lúc ấy cục diện , ép hắn không thể không đề cao chính mình năng lực quân sự .”\n“ Hơn nữa , người dưới tay , ai lại nguyện ý để cho chính mình thượng vị , trên chiến trường đâu ?”\n“ Nếu như còn muốn hoàng đế , hoặc có lẽ là thượng vị làm thống soái trên chiến trường ...”\n“ Vậy thì thật lộ ra người dưới tay quá vô năng ...”\nLàm lâu như vậy Thái tử , Chu Cao Sí đối với cái này thật là thấm sâu trong người, thấu hiểu rất rõ .\n......', 'output\\mp3\\Màn Trời Quyền Lực Diễn Biến Cùng Truyền Thừa\\0072_Thứ 72 chương Thời kỳ hòa bình, chiến loạn thời kì.mp3', '2026-09-01T23:28:07.388919+00:00', 'completed', 'completed', 7602, 7602),
	(78, 7, '7651117543440007705', 73, 'Thứ 73 chương Hoàn toàn bất đắc dĩ', 'Thứ chương Hoàn toàn bất đắc dĩ\nHiện đại thời không .\n“ Kỳ thực cho dù là hoàng đế bên trong , năng lực quân sự tối cường Lý Thế Dân , hắn về sau cũng nhận thức được điểm này .”\n“ Năng lực quân sự của hắn chính xác rất mạnh , nhưng hắn trở thành hoàng đế sau đó , cơ hồ cũng lại không có lên qua chiến trường .”\n“ Lý Thế Dân trở thành hoàng đế sau đó , duy nhất một lần trên chiến trường , là lúc nào ?”\n“ Trinh Quán mười sáu năm , chinh chiến Cao Câu Ly thời điểm .”\n“ Kỳ thực khi đó hắn chinh chiến Cao Câu Ly , cũng có một chút hoàn toàn bất đắc dĩ .”\nLý Ân Phàm tử mảnh hồi tưởng một chút Trinh Quán mười sáu năm tình huống .\n“ Trinh Quán hướng nói như thế nào đây ? Đúng là quần tinh sáng chói , nhưng Lý Thế Dân lúc trước , không có ý thức được một cái tình huống .”\n“ Có thể làm thống soái người , quá ít .”\n“ Ít đến , Trinh Quán mười sáu năm thời điểm , hắn đều nhất thiết phải tự thân lên chiến trường .”\nĐiểm này đúng là Lý Thế Dân về sau mới ý thức tới .\nLý Thế Dân chinh chiến Cao Câu Ly thời điểm , là thời gian nào ? Công nguyên năm .\nMột năm này , Lý Tĩnh đã bảy mươi ba tuổi !\nTại cổ đại , để cho một cái bảy mươi ba tuổi người , kéo lấy già nua cơ thể chinh chiến biên cảnh ?\nNếu là một cái ngoài ý muốn chết ở bên ngoài , Lý Thế Dân đều sợ chính mình lại lưu lại khắc nghiệt công thần danh tiếng .\n“ Đến nỗi vì cái gì không chọn Lý Tích cùng Lý Đạo Tông ?”\n“ Rất nhiều người có thể sẽ nghĩ tới đây hai người .”\n“ Bởi vì Lý Tích cùng Lý Đạo Tông , cũng đúng là có thể làm thống soái nhân tuyển .”\n“ Kỳ thực đáp án rất đơn giản , tại chinh chiến Cao Câu Ly phía trước , Thái tử Lý Thừa Càn liên hợp Hầu Quân Tập mưu phản .”\n“ Lý Thế Dân , muốn bắt đầu thu hẹp binh quyền .”\nNếu như một năm này Thái tử Lý Thừa Càn cùng Hầu Quân Tập không có mưu phản , Lý Thế Dân có thể còn sẽ tuyển Lý Tích hay là Lý Đạo Tông .\nNhưng ở trong đó , Hầu Quân Tập cũng tham dự mưu phản .\nVậy cái này thời điểm Lý Thế Dân , thì không khỏi không cân nhắc một chuyện , nếu như đem binh quyền cho Lý Tích hoặc Lý Đạo Tông .\nBọn hắn , có thể hay không mưu phản ?\nĐặc biệt là Lý Đạo Tông , hắn vẫn là tôn thất !\nCho nên , lúc này Lý Thế Dân , ngự giá thân chinh , cũng là hoàn toàn bất đắc dĩ .\n...\nĐường triều .\nTrinh Quán bảy năm .\nPhanh !!!\nLý Thế Dân chén trà ngã trên mặt đất , cả người kinh ngạc nhìn màn trời .\nHắn nghe được cái gì ?\nThái tử Lý Thừa Càn mưu phản ?!\nLúc trước màn trời nói Thái tử Lý Thừa Càn bị chính mình bắt buộc thời điểm chết , Lý Thế Dân còn có một số tâm lý mong muốn .\nThật không nghĩ đến chính là , mưu phản ?\nLúc này dưới đài rất nhiều đại thần , đều cúi đầu , không nhìn bầu trời màn , cũng không nhìn Lý Thế Dân , chuyên chú nhìn chằm chằm gạch .\nBọn hắn thật là cảm thấy tai bay vạ gió , rõ ràng màn trời nói là Lưu Bang , như thế nào lại đến Thái tử Lý Thừa Càn mưu phản tới .\n“ Bệ hạ , thần có tội !!!”\nLúc này , Hầu Quân Tập bước nhanh đi đến Lý Thế Dân trước mặt , quỳ rạp xuống đất .\n“ Ngươi ...”\nLý Thế Dân hồi thần lại , sau đó giả vờ bất đắc dĩ thần sắc , thở dài nói :\n“ Dỡ xuống tất cả chức vụ , về nhà trước đợi a .”\n“ Tạ Bệ Hạ !”\nHầu Quân Tập nghe nói như thế , nới lỏng một đại khẩu khí .\nPhải biết hắn nghe được màn trời nói mình liên hợp Thái tử Lý Thừa Càn mưu phản thời điểm , trái tim đều kém chút đột nhiên ngừng .\nCó thể an an ổn ổn về nhà , đây đã là kết quả tốt nhất .\nHầu Quân Tập mặc dù tự ngạo , nhưng hắn cũng biết , mưu phản là kết cục gì .\nĐến nỗi hoài nghi màn trời ?\nNhư thế nào ? Tất cả mọi người tại chỗ đều không hoài nghi màn trời , ngược lại tại màn trời nói đến ngươi mưu phản thời điểm , ngươi liền bắt đầu hoài nghi màn trời ?\nNhư thế nào phía trước không nghi ngờ màn trời ?\n“ Bệ hạ , thần cáo lui !”\nHầu Quân Tập đứng lên , cung kính cúi đầu , thối lui ra khỏi ở đây .\n“ Ai ...”\nLý Thế Dân đột nhiên cảm giác được , Trinh Quán sau đó lịch sử , sớm biết , giống như cũng không có tốt như vậy .\n...\nHiện đại thời không .\n“ Hơn nữa không chỉ là điểm này .”\n“ Kỳ thực từ Tào Ngụy thời kỳ Tư Mã Ý sau đó bắt đầu , các triều đại đổi thay , một cái hoàng đế lúc tuổi già , hắn đều sẽ lại không đem binh quyền đưa ra đi .”\n“ Ân ?”\nLưu Bang nghe được đoạn lời này , trong đầu trong nháy mắt toát ra một cái ý nghĩ , nhìn xem Lý Ân Phàm hỏi :\n“ Cầm binh quyền quyền thần , mưu phản ?”\n“ Đúng !”\nLý Ân Phàm khẳng định gật đầu một cái , sau đó lại tiếp tục nói :\n“ Trong lịch sử , Tào Ngụy thời kỳ Tư Mã Ý chính là như thế .”\n“ Cho nên , tại sau đó các triều đại đổi thay , lúc tuổi già ép bất đắc dĩ tình huống phía dưới , hoàng đế đều chọn ngự giá thân chinh .”\nDù sao Tư Mã Ý giáo huấn quá mức thê thảm .\n“ Nói đến đây ...”\nLý Ân Phàm do dự một chút , nói một chuyện .\n“ Quý ca , sau đó đến hậu thế tới trong mười người , đem Hàn Tín tuyển chọn a .”\nNghe nói như thế , Lưu Bang tay ngừng lại tại chỗ , ngẩng đầu nhìn Lý Ân Phàm , dứt khoát hỏi :\n“ Cho nên , hắn mưu phản ?”\n“ Hắn không có mưu phản , nhưng cuối cùng vẫn là chết .”\n“ Kỳ thực trước đó đối với Hàn Tín , ta đúng là từng mắng ngươi , mắng ngươi tại sao muốn giết Hàn Tín ...”\nLý Ân Phàm sau khi nói đến đây , thở dài một hơi , sau đó lại nhẹ nói :\n“ Sau đó giải chỉnh thể lịch sử sau đó , ta mới biết được , có đôi khi , kỳ thực ngươi cũng bất đắc dĩ ...”\nSo sánh Tư Mã Ý cùng Hàn Tín , kỳ thực liền có thể phát hiện , vì cái gì Lưu Bang muốn giết Hàn Tín .\nĐáp án rất đơn giản , bởi vì ngươi có mưu phản thực lực .\nDù là ngươi không có mưu phản ý nghĩ , nhưng ngươi có thực lực mưu phản , vậy ngươi nhất định phải chết .\nĐặc biệt là , tại Lưu Bang sau khi chết , không có người có thể đè ép được Hàn Tín .\nHơn nữa , ai biết sau đó Hàn Tín , ý nghĩ có thể hay không thay đổi đâu ?\nTào Tháo , tại ban đầu , cũng chỉ là muốn làm một cái trung thần , làm lớn Hán chinh tây tướng quân .\nTư Mã Ý , có lẽ ban đầu cũng giống như thế .\nMà xem như chính trị năng lực vô cùng cao siêu Lưu Bang , hắn sẽ lưu lại dạng này một cái tai hoạ ngầm sao ?\nChớ nói chi là , Hàn Tín đã từng còn yêu cầu “ Tề vương ”.\nChỉ một điểm này , lấy ngay lúc đó Lưu Bang góc nhìn đến xem , Hàn Tín chắc chắn là có ý đồ không tốt .\nVề sau thế chúng ta góc nhìn , chỉnh thể đi xem , Hàn Tín chính xác có thể không có ý đồ không tốt .\nNhưng ở lúc đó , Lưu Bang Hạng Vũ giằng co , Hàn Tín vừa mới bình định Tề quốc , liền trực tiếp yêu cầu “ Tề vương ”.\nLưu Bang lúc đó đều chỉ là Hán vương !\nĐiểm này , là hậu thế rất nhiều người không có ý thức được .\nHàn Tín yêu cầu “ Tề vương ” Lúc , Lưu Bang khi đó đều không có thiết lập đại hán , chỉ là Hán vương mà thôi .\nCho nên , tuổi già Lưu Bang , vì không lưu lại tai hoạ ngầm , còn thế nào tin tưởng ngươi Hàn Tín ?\n“ Kỳ thực , nói thật , Quý ca .”\n“ Hàn Tín lúc đó yêu cầu “ Tề vương ”, có thể nghĩ chỉ là từ ô , cùng Vương Tiễn ngay lúc đó ý nghĩ có thể là một dạng .”\nNghe nói như thế , Lưu Bang trầm mặc một hồi , gật đầu một cái nói :\n“ Cái này ta biết , ta về sau chính xác nghĩ tới .”\n“ Nhưng , ta không thể đánh cược ...”\nLý Ân Phàm khẽ giật mình , sau đó chậm rãi gật đầu một cái nói :\n“ Đúng vậy a , ngươi chính xác không thể đánh cược ...”\n“ Thời điểm đó đại hán , đã chịu không được giằng co ...”\nĐây chính là điểm chết người là một điểm , nếu như ngay lúc đó đại hán , còn có năng lực tại Hàn Tín tạo phản thời điểm , có thể trấn áp hắn .\nCó thể Lưu Bang cũng sẽ không giết Hàn Tín .\nNhưng khi đó đại hán , trải qua nhiều chuyện như vậy , chính xác đã chịu không được giằng co .\nĐây không chỉ là Lưu Bang không dám đánh cược , Lữ hậu cũng không dám đánh cược !\nMà lúc đó trên triều đình đám đại thần , bọn hắn cũng không dám đánh cược !\nDù sao bọn hắn là cùng theo Lưu Bang đi tới hiện nay địa vị , không phải đi theo Hàn Tín .\nNếu như Hàn Tín tạo phản , hơn nữa thành công , vậy bọn hắn lại nên nơi nào ?\nĐây chính là bất đắc dĩ địa phương .\n...', 'output\\mp3\\Màn Trời Quyền Lực Diễn Biến Cùng Truyền Thừa\\0073_Thứ 73 chương Hoàn toàn bất đắc dĩ.mp3', '2026-09-01T23:28:12.316778+00:00', 'completed', 'completed', 7706, 7706),
	(79, 7, '7651516784096313881', 74, 'Thứ 74 chương Hàn Tín', 'Thứ chương Hàn Tín\nMinh triều .\nVĩnh Lạc bảy năm .\n“ Cho nên , lúc đó là tất cả mọi người , vì để tránh cho ngoài ý muốn , đều nghĩ để cho Hàn Tín chết ?”\nChu Cao Sí nghĩ tới đây , có chút ngây người nhìn xem màn trời .\n“ Quả thật là như thế , lúc đó trên triều đình đám đại thần , Lữ hậu , Lưu Bang , đều nghĩ để hắn chết .”\n“ Cái này cũng là ta ngồi lên vị trí này sau đó , nhìn sách sử thời điểm , vừa nghĩ đến .”\nChu Lệ thở dài , có chút bất đắc dĩ lắc đầu .\nPhía trước vẫn là Yến Vương lúc , không thế nào tiếp xúc qua triều đình , cho nên hắn còn rất ngây thơ .\nNhìn sách sử thời điểm , còn chửi ầm lên qua Lưu Bang .\nNhưng chờ mình đi tới vị trí này , lại đi nhìn đoạn lịch sử kia , hắn mới phát hiện .\nMột số thời khắc , thật là hoàn toàn bất đắc dĩ .\nNgươi không có tạo phản ý nghĩ , nhưng ngươi có thực lực tạo phản , vậy ngươi nhất định phải chết .\nChớ nói chi là , Hàn Tín lúc đó càng còn có tạo phản danh nghĩa .\nDù sao , hắn đã từng thế nhưng là “ Vương ”!\n“ Cái này đồng dạng cũng là vì sao Tiêu Hà cuối cùng muốn hạ sát thủ nguyên nhân ...”\nTiêu Hà hết thảy , cũng là đi theo Lưu Bang , mới lấy được .\nNếu như Hàn Tín mưu phản , cái kia lại đặt mình vào chỗ nào ? Huống hồ , chính mình có được hết thảy , cũng là đi theo Lưu Bang có được .\n“ Cho nên , từ một điểm này đi xem , chính xác như màn trời nói tới , lúc đó là tất cả mọi người , đều phải Hàn Tín chết ...”\n“ Không ai dám đánh cược , đặc biệt là vào lúc đó ...”\nLấy ngay lúc đó thế cục đi xem , ai dám đánh cược đâu ? Không ai dám đánh cược !\nDù sao Hàn Tín là thật có tạo phản thực lực .\n“ Chớ nói chi là , lúc đó Lưu Bang còn đang dọn dẹp vương khác họ ...”\n“ Chờ đến Hán mười một năm , còn lại cái cuối cùng , có tạo phản thực lực , cũng chỉ có Hàn Tín .”\n“ Thân là hoàng đế Lưu Bang , sẽ lưu lại dạng này tai hoạ ngầm sao ?”\nLời này vừa ra , Chu Cao Sí cùng Chu Lệ , đồng thời lắc đầu .\nSẽ không ! Không có người sẽ lưu lại dạng này tai hoạ ngầm !\n“ Phụ thân , trọng yếu nhất , hẳn là muốn bảo đảm những người khác không chiếm được Hàn Tín a ?”\nChu Cao Sí bỗng nhiên nói ra dạng này một đoạn văn .\nChu Lệ đâu ? Chỉ là trầm mặc gật đầu một cái .\nĐiểm này , đồng dạng cũng là hắn lên làm hoàng đế sau đó , vừa nghĩ đến điểm trọng yếu nhất .\n“ Cho nên , dù là Hàn Tín bị giam lỏng tại Trường An , cuối cùng cũng vẫn là muốn giết hắn ...”\nĐây chính là hoàng đế ý nghĩ !\nTừ hậu thế Tư Mã Ý hành động đến xem , chính xác không thể nói Lưu Bang làm sai .\nTư Mã Ý đều rơi vào kết cục kia , Cao Bằng lăng thay đổi , đều có thể xoay người .\nHàn Tín , ai biết hắn về sau ý nghĩ là dạng gì ?\nVạn nhất bị cái nào đó kẻ dã tâm , cổ động thuyết phục làm sao bây giờ ?\nHơn nữa , Hàn Tín chính trị năng lực có thể chính xác thấp .\nThế nhưng cũng là bởi vì chính trị năng lực thấp , bị dao động vài câu , liền chạy tới tạo phản làm sao bây giờ ?\nChu Cao Sí nghĩ tới chỗ này , chỉ có thể là bất đắc dĩ lắc đầu .\nHàn Tín tại lúc đó , đúng là phải chết .\nHắn thấp hèn chính trị năng lực , cũng tạo thành hắn ngay lúc đó cục diện cùng kết quả .\n...\nHiện đại thời không .\n“ Kỳ thực đây không chỉ là ngươi , Quý ca .”\n“ Về sau hoàng đế , nói thật , không có một cái nào sẽ lưu lại dạng này tai hoạ ngầm ...”\n“ Cho dù là người đời sau nói , chưa từng giết công thần Lý Thế Dân .”\n“ Lý Thế Dân lúc tuổi già , cũng đều sẽ không lưu lại dạng này tai hoạ ngầm ...”\n“ Càng đừng nhắc Tào Tháo , Chu Nguyên Chương , Triệu Khuông Dận những hoàng đế này .”\nLý Ân Phàm càng là hiểu rõ chính trị , mới càng minh bạch Hàn Tín lúc đó chắc chắn phải chết cục diện .\nSau đó khai quốc hoàng đế , thật là không có người nào sẽ lưu lại dạng này tai hoạ ngầm cho mình hậu đại .\nChu Nguyên Chương không cần nói .\nLý Thế Dân sẽ lưu sao ? Chắc chắn sẽ không lưu .\nLý Tĩnh nếu như không phải lớn tuổi như vậy , ngươi nhìn Lý Thế Dân có thể hay không lưu Lý Tĩnh ?\nĐặc biệt là Tư Mã Ý chuyện như vậy xuất hiện sau đó , thì càng là như thế .\nHuống chi , Lý Ân Phàm còn nhớ rõ , sau đó đại hán đã xác lập nghỉ ngơi lấy lại sức chính sách .\nCái kia còn cần Hàn Tín sao ?\nThì càng không cần Hàn Tín !\nCho nên , tổng hợp đến xem , lấy ngay lúc đó cục diện , Hàn Tín còn có cái gì lưu lý do ?\nLưu Hàn Tín , lại không có có tác dụng gì , đại hán phải tĩnh dưỡng sinh tức .\nKhông lưu , ngược lại khu trừ rất nhiều tai hoạ ngầm .\nLý Ân Phàm suy tư đến cái này , cũng là cảm thấy Hàn Tín lúc đó thật sự đáng thương .\nThật là , làm sao đều muốn chết .\n“ Kỳ thực ngươi còn có một chút quên , tiên sinh .”\nLưu Bang thả ra trong tay sách sử , rất bình tĩnh nhìn xem Lý Ân Phàm .\n“ Ân ?”\nLý Ân Phàm nghe nói như thế , nghi hoặc nhìn Lưu Bang .\n“ Giết Hàn Tín , không có bất kỳ cái gì gánh vác cùng vướng víu , nói một cách khác , trên triều đình , không có bất kỳ cái gì một người tại sau lưng Hàn Tín .”\n“ Cho nên , ta vì cái gì không giết Hàn Tín ?”\n...\nĐại hán .\nHán bảy năm .\n“ Ai ...”\nGiờ này khắc này , tại chỗ đại thần bên trong , chỉ có Tiêu Hà nhẹ giọng thở dài .\nCũng chỉ có Tiêu Hà , đối với Hàn Tín chết tin tức , có một chút tiếc hận .\nĐến nỗi những thứ khác đại thần , còn có Lữ hậu , đều bình tĩnh nhìn màn trời .\nTựa hồ Hàn Tín sau đó sẽ chết , liền tại bọn hắn trong dự liệu .\nMà giờ khắc này , tại Hàn Tín phủ đệ bên trong .\nHàn Tín mờ mịt nhìn xem màn trời .\n“ Chính mình sẽ chết ?”\n“ Hơn nữa , đều đang mong chính mình chết ?”\n“ Trên triều đình , không có ai vì chính mình nói chuyện ?”\nGiờ khắc này , Hàn Tín đột nhiên biết vì cái gì màn trời biết nói , chính mình chính trị năng lực hết sức cúi xuống .\nTrên triều đình không có ai vì chính mình nói chuyện , cái này còn không có thể chứng minh sao ?\nĐều tại chờ đợi , hoặc có lẽ là ngầm thừa nhận cái chết của mình , vẫn chưa thể nói rõ sao ?\nNhìn lại màn trời nói tới hết thảy , Hàn Tín lúc này là thật sự biết , vì cái gì chính mình chắc chắn phải chết .\nBởi vì , chỉ có hắn tự do bên ngoài .\nHơn nữa , còn có tạo phản thực lực cùng năng lực .\n“ Về phía sau thế sao ?”\nHàn Tín cúi đầu xuống , bất đắc dĩ thở dài một hơi .\n...\nHiện đại thời không .\n“ Quý ca , đến lúc đó ta cho ngươi nhiều tiễn đưa một vài thứ , đều là các ngươi đại hán lúc đó cần nhất .”\n“ Hàn Tín , liền để hắn lưu lại hậu thế a .”\n“ Đằng sau các triều đại đổi thay tới học tập , chắc chắn còn muốn học tập cổ đại thời điểm quân sự .”\n“ Hàn Tín ngược lại là một cái cực kỳ tốt lão sư .”\nĐiểm này , cũng là Lý Ân Phàm đột nhiên nghĩ đến .\nDù sao dù là Hàn Tín tới hậu thế , sau đó lại trở về sao ? Sau khi trở về , lại như thế nào tự xử ?\nHuống chi , coi như ngay lúc đó đại hán thu được đặc biệt nhiều vật tư cái gì , cũng cần nghỉ ngơi dưỡng sinh tức .\nDù sao số lượng nhân khẩu , đi qua cuối Tần sau đó , đã vô cùng hiếm hoi .\nTần triều thiết lập , cũng liền tổng cộng mười lăm năm .\nPhía trước , còn thống nhất Lục quốc .\nLưu Bang lúc này đại hán , tình huống chính xác đã hết sức nguy cơ .\n“ Hảo .”\nLưu Bang gật đầu một cái , nhận đồng Lý Ân Phàm lời nói .\nHàn Tín , liền để hắn đến hậu thế đến đây đi .\nĐại hán , cũng chính xác không cần hắn , lưu hắn lại , vô luận như thế nào , đều biết lưu lại tai hoạ ngầm .\nMà tại màn trời bộc quang sau đó , lúc này Lưu Bang đại hán , cũng chính xác dung không được Hàn Tín .\n......', 'output\\mp3\\Màn Trời Quyền Lực Diễn Biến Cùng Truyền Thừa\\0074_Thứ 74 chương Hàn Tín.mp3', '2026-09-01T23:28:17.179116+00:00', 'completed', 'completed', 7099, 7099),
	(80, 7, '7651517715722551833', 75, 'Thứ 75 chương Quyền hạn lớn nhất hoàng đế', 'Thứ chương Quyền hạn lớn nhất hoàng đế\nHiện đại thời không .\n“ Về phần tại sao nói Lưu Triệt là năng lực tổng hợp tối cường hoàng đế ?”\nThu thập đồ đạc xong , Lý Ân Phàm mang theo Lưu Bang ra cửa , hôm nay thứ sáu , ngày mai thứ bảy mới là đài truyền hình bên kia thu tiết mục thời điểm .\nCho nên Lý Ân Phàm chuẩn bị hôm nay mang Lưu Bang đi thủ đô chơi một ngày .\n“ Có một cái khả năng Hán Vũ Đế Lưu Triệt sau đó , tuyệt đại bộ phận người , đều không ý thức được một chuyện .”\n“ Trong lịch sử , từ Tần Thuỷ Hoàng Doanh Chính , sáng lập hoàng đế , mở ra đế chế thời kì bắt đầu .”\n“ Đến Thanh triều cuối cùng phá diệt , ở giữa trải qua mấy trăm vị hoàng đế , chuẩn xác mà nói , là vị hoàng đế .”\n“ Tại cái này vị hoàng đế bên trong , vị kia quyền lực của hoàng đế lớn nhất ?”\n“ Kỳ thực , chính là Hán Vũ Đế Lưu Triệt !”\nTrên xe , Lưu Bang chuyên tâm cẩn thận nhìn xem một bản 《 Hán Thư 》, Lý Ân Phàm vừa lái xe , bên cạnh cùng tay lái phụ Lưu Bang nói chuyện phiếm .\n“ Mà Hán Vũ Đế Lưu Triệt , cũng có thể nói , là chân chính hoàng đế .”\n“ Hoặc đổi một câu nói , là chân chính toàn bộ hình thái hoàng đế .”\nTay lái phụ Lưu Bang , cũng nhìn thấy 《 Hán Thư 》 bên trong , ghi chép Lưu Triệt sự tích một đoạn kia .\n“ Ta cái này tử tôn , vận đạo thật hảo .”\nĐối với Lý Ân Phàm nói Lưu Triệt là chân chính hoàng đế điểm này , Lưu Bang cũng đồng ý .\nBởi vì đúng là thời đại sáng tạo ra ngay lúc đó Hán Vũ Đế Lưu Triệt .\nTrong đó môn đạo , Lưu Bang một mắt liền có thể thấy rõ .\n“ Trong lịch sử , những thứ khác hoàng đế , mặc kệ là Đường Thái Tông Lý Thế Dân , minh Thái tổ Chu Nguyên Chương , Tùy Văn Đế Dương Kiên các loại ...”\n“ Những thứ này khai quốc hoàng đế , nói là quyền hạn rất lớn , nhưng kỳ thật cuối cùng vẫn là nhận lấy một chút cản tay .”\n“ Những thứ này cản tay , có thể là địa chủ , có thể là thế gia , cũng có thể là là tập đoàn quân sự ...”\n“ Nhưng Hán Vũ Đế Lưu Triệt , hắn cái kia thời kì , những thứ này đều không tồn tại .”\nCái này cũng là Lý Ân Phàm sau đến xem Hán Vũ Đế thời kì lịch sử lúc , bỗng nhiên ý thức được một chuyện .\nTại Hán Vũ Đế Lưu Triệt thời kì , mặc kệ là Tây Hán thời kì dần dần hưng khởi môn phiệt , vẫn là Đông Hán thời kì dần dần Hưng Khởi thế gia .\nHay là về sau địa chủ , tập đoàn quân sự , đảng phái các loại , những vật này , tại Hán Vũ Đế thời kì , cũng là không tồn tại .\n“ Đến nỗi nói quý tộc ? Bảy Quốc Chi Loạn sau , quý tộc , cũng bị Hán Cảnh Đế Lưu khải đả kích không ra được âm thanh .”\n“ Trong này quý tộc , còn bao gồm Lưu thị quý tộc ...”\nHán Vũ Đế Lưu Triệt , kỳ thực thật có thể nói là khác loại một dạng “ Phấn lục thế Dư Liệt ”....\nĐiểm này , thật là không chút nào khoa trương .\nĐặc biệt là thời kỳ chiến quốc Lục quốc Dư Nghiệt .\nTại bảy Quốc Chi Loạn sau , cũng bị đả kích triệt để xuống dốc .\nĐiểm này , có thể có người rất nghi hoặc , vì cái gì đến bảy Quốc Chi Loạn thời kì , còn có trước đây Lục quốc Dư Nghiệt ?\nBởi vì cái này Lục quốc Dư Nghiệt , bao gồm không chỉ là thời kỳ chiến quốc vương thất quý tộc Dư Nghiệt ...\nCòn bao gồm giống “ Trương Lương ” Loại này , ban đầu nghĩ phục khởi chính mình các nước chư hầu Dư Nghiệt ...\nBảy Quốc Chi Loạn sau lưng , cũng còn có bóng của bọn hắn .\nHoặc có lẽ là , bọn hắn cũng không cam tâm ...\nMà nói đến điểm này , nhất định phải thuyết minh , cái này Lục quốc Dư Nghiệt , bị đả kích bao nhiêu lần ?\nHoặc có lẽ là , đạt tới Diệt Lục quốc cái này một thành liền , có bao nhiêu lần ?\n5 lần !\nLần thứ nhất , là Tần Thuỷ Hoàng Doanh Chính , thống nhất Lục quốc , thiết lập Tần triều .\nĐây là lần thứ nhất Diệt Lục quốc , nhưng cuối cùng Lục quốc mạng lưới quan hệ quá sai lầm tổng phức tạp , cùng với Lục quốc nội tình còn tại , Doanh Chính cuối cùng không thể triệt để tiêu diệt Lục quốc .\nLần thứ hai , là Hạng Vũ đã đạt thành cái này một thành liền , tiêu diệt Lục quốc .\nMà tại ở trong đó , thời kỳ chiến quốc Lục quốc Dư Nghiệt , đã trải qua phân hoá , tiêu diệt một điểm nội tình .\nLàm cái ví dụ , cái này giống như hậu thế từ nội bộ chia ra phái tả cùng cánh hữu , cánh hữu tiêu diệt phái tả .\nLần thứ ba , là từ Lưu Bang lãnh đạo chư hầu cùng Công Thần tập đoàn diệt Hạng Vũ Lục Quốc tập đoàn .\nMà Lưu Bang , chính là từ “ Phái tả ” Bên trong hút lấy đến người , tiêu diệt “ Cánh hữu ”...\nLần thứ tư , là Lưu Bang chính mình , tự mình gạt bỏ chính mình nâng đỡ Lục Quốc tập đoàn .\nLần này , chính là Lưu Bang , chính mình đã đạt thành Diệt Lục quốc thành tựu , tiêu diệt chính mình nâng đỡ lên “ Phái tả ”, hoặc có lẽ là theo hắn “ Lục quốc Dư Nghiệt ”.\nMột lần cuối cùng , lần thứ năm đâu ?\nChính là Hán Cảnh Đế thời kỳ bảy Quốc Chi Loạn .\nCuối cùng này một lần , sau lưng kỳ thực chính là Lưu Bang tiêu diệt sau đó , lưu lại còn sót lại “ Lục quốc Dư Nghiệt ” Không cam tâm .\nMà cũng chính là đã trải qua cái này 5 lần lớn đả kích , “ Lục quốc quý tộc Dư Nghiệt ” Thời kì , mới xem như chân chính đi qua .\nMà quá khứ , liền vừa vặn đến thời kỳ nào ?\nĐúng vậy , không tệ , chính là Hán Vũ Đế Lưu Triệt thời kì !\n“ Cho nên , Hán Vũ Đế Lưu Triệt thời kì , cái gọi là thượng tầng đại tộc , cấp này cấp sinh thái vị , tại lúc đó , là cơ hồ trống không .”\n“ Hán Vũ Đế Lưu Triệt , tại tiêu diệt chính mình sơ thượng vị thời kì bị cản tay , cũng chính là Ngoại Thích tập đoàn sau đó , liền căn bản không cảm giác được bất kỳ áp lực .”\n“ Cũng không cảm giác được bất kỳ cản tay ...”\n“ Tình hình này , có thể nói , là các triều đại đổi thay hoàng đế bên trong , đều tuyệt vô cận hữu !”\nMặc kệ là hậu thế lịch sử , vẫn là phía trước lịch sử , lại hoặc là nói là hiện đại lịch sử ...\nĐều chưa từng có xuất hiện qua dạng này đối với hoàng đế tới nói , hoàn mỹ tình huống .\n“ Cho nên , Hán Vũ Đế Lưu Triệt cầm quyền sau đó , thật là muốn làm gì , vậy thì làm như thế nào , hoàn toàn không cố kỵ gì ...”\n“ Cái này cũng là vì cái gì , lúc đó Hán Vũ Đế Lưu Triệt , có thể trực tiếp đem cưỡi nô xuất thân Vệ Thanh , trực tiếp một đường đề bạt đến thống soái ...”\n“ Hơn nữa , không cố kỵ chút nào sử dụng Hoắc Khứ Bệnh ...”\n“ Đời sau hoàng đế , có ai có thể không cố kỵ chút nào làm như vậy ?”\n“ Chớ nói chi là tại Hán triều , cái này một vô cùng coi trọng xuất thân cùng huyết mạch thời kì ...”\nHán Vũ Đế Lưu Triệt lúc đó thật là muốn dùng ai liền dùng ai , muốn giết ai , vậy thì thật là giết ai ...\nTừ Hán Vũ Đế Lưu Triệt tuổi già lịch sử liền có thể nhìn ra ...\nNữ nhi ? Nhi tử ? Muốn giết cứ giết ...\nỦng hộ , phản đối , ở giữa lưng chừng , vậy càng là không cố kỵ chút nào giết ...\nMặc dù nói Hán Vũ Đế Lưu Triệt lúc tuổi già đến cùng phải hay không cái gọi là phát “ Heo ôn ”, còn cần phải chờ thương thảo ...\nNhưng từ hành vi này đến xem , Hán Vũ Đế Lưu Triệt quyền hạn , thật là trong lịch sử duy nhất toàn bộ hình thái hoàng đế .\nCũng là rất nhiều xuyên qua tiểu thuyết lịch sử bên trong , những miêu tả kia hoàng đế .\nMà tại trong lịch sử vô số hoàng đế , chân chính xâu đi bá đạo , cũng liền cái này một vị hoàng đế .\n...\nMinh triều .\nVĩnh Lạc bảy năm .\n“ Hán Vũ Đế Lưu Triệt vận đạo , chính xác quá tốt rồi ...”\nChu Lệ giờ khắc này thật sự hâm mộ Hán Vũ Đế Lưu Triệt , tại sao có thể có tốt như vậy vận đạo .\nChuyện tốt , đều bị một mình hắn đụng phải .\nMặc kệ là gặp phải Vệ Thanh cùng Hoắc Khứ Bệnh , vẫn là lúc đó hoàn mỹ thế cục , đều bị Lưu Triệt một người gặp .\n“ Từ hoàng đế một thân phận này tới nói , Hán Vũ Đế Lưu Triệt , đúng là trong lịch sử một vị duy nhất hoàng đế chân chính ...”\nChu Cao Sí liếc nhìn trong tay sách sử , cũng là cảm khái nói một câu như vậy .\nHán Vũ Đế Lưu Triệt , là chân chính không có chịu đến bất kỳ cản tay ...\n“ Hơn nữa , cái này cản tay , ngoại trừ những thứ này có thể thấy được ...”\n“ Hán Vũ Đế Lưu Triệt , đồng dạng cũng không có chịu đến những cái kia không nhìn thấy cản tay ....”\n...', 'output\\mp3\\Màn Trời Quyền Lực Diễn Biến Cùng Truyền Thừa\\0075_Thứ 75 chương Quyền hạn lớn nhất hoàng đế.mp3', '2026-09-01T23:28:48.338885+00:00', 'completed', 'completed', 7644, 7644),
	(81, 7, '7651896472165679641', 76, 'Thứ 76 chương Tư tưởng đại nhất thống', 'Thứ chương Tư tưởng đại nhất thống\nHiện đại thời không .\n“ Hơn nữa , ngoại trừ “ Quý tộc ”, “ Thế gia ”, “ Địa chủ ” chờ đã , những thứ này hậu thế , có thể thấy được , sờ được cản tay bên ngoài ...”\n“ Hán Vũ Đế Lưu Triệt , cũng không có chịu đến hậu thế rất nhiều hoàng đế gặp phải , những cái kia “ Không nhìn thấy ” Cản tay ...”\nDừng xe , Lý Ân Phàm mang theo Lưu Bang chuẩn bị đi trước ăn một vài thứ .\nVừa rồi Lý Ân Phàm nhìn đồng hồ , về khoảng cách máy bay thời gian còn sớm .\n“ Những thứ này không nhìn thấy cản tay , tại ngươi hậu thế , Đường triều hoàng đế , Lý Thế Dân có thể rất có quyền lên tiếng ...”\n“ Những thứ này không nhìn thấy cản tay , chính là tại Hán Vũ Đế Lưu Triệt thời kì , vì hắn đo thân mà làm “ Thiên nhân cảm ứng luận ”.”\nNghe được cái danh từ này , Lưu Bang có chút nghi hoặc nhìn bên cạnh Lý Ân Phàm .\n“ Thiên nhân cảm ứng luận ?”\n“ Đúng , thiên nhân cảm ứng luận ...”\n“ Đơn giản điểm tới nói , chính là Thiên ý cùng nhân sự có thể cảm ứng lẫn nhau thượng thiên sẽ thông qua hiện tượng tự nhiên tới bình phán nhân gian thống trị tốt xấu .”\n“ Cũng chính là , bình phán hoàng đế tốt xấu .”\nLưu Bang lúc này bỗng nhiên nghĩ tới điều gì , nhẹ nhàng gật đầu , hiểu rõ một dạng nói :\n“ Ta đã biết , Thiên Nhân hợp nhất , trước đây trang tử cùng Mạnh Tử , đều nói qua ...”\nNghe nói như thế , Lý Ân Phàm có chút ngạc nhiên nhìn xem Lưu Bang .\n“ Quý ca , ngươi biết ?”\n“ Đương nhiên biết , Tiêu Hà cho ta nói qua , nhưng ta rất khịt mũi khinh bỉ ...”\nLưu Bang chính xác thời gian rất sớm , liền nghe Tiêu Hà nói qua , nhưng nói như thế nào đây ? Hoàn toàn không để ý , hơn nữa khịt mũi coi thường .\n“ Tốt a ...”\n“ Chúng ta nói trở về Hán Vũ Đế Lưu Triệt ...”\nLý Ân Phàm đi vào tiệm ăn sáng , nhanh chóng điểm xong hai lồng bánh bao nhỏ , lại điểm hai chén sữa đậu nành .\n“ Kỳ thực cái gọi là “ Thiên nhân cảm ứng luận ”, đối với hậu thế hoàng đế quả thật có một chút cản tay ...”\n“ Nhưng ở Hán Vũ Đế Lưu Triệt thời kì , đây thật ra là hoàn thành một hồi bên trên tư tưởng “ Tập quyền ”...”\nCái này cũng là hậu thế vương triều , còn có hiện đại , rất nhiều người không có ý thức được .\nCũng là Hán Vũ Đế Lưu Triệt chính trị năng lực là cái gì có thể xếp tại hàng đầu chiến công .\nĐộc tôn học thuật nho gia , thiên nhân cảm ứng luận , hậu thế , hoặc có lẽ là hiện đại , có vô số người mắng .\nNhưng ở thời gian như vậy , đây đều là đại thế phía dưới , nhất định phải làm .\nVì cái gì ? Bởi vì muốn triệt để hoàn thành một hồi từ đuôi đến đầu , bên trên tư tưởng “ Tập quyền ”.\nNếu như không có trận này bên trên tư tưởng “ Tập quyền ”, cái kia tại lúc đó , rất nhiều tầng dưới chót , trong đầu của bọn hắn , vẫn như cũ còn có thể suy nghĩ có từ lâu “ Lục quốc ”.\nĐiểm này , là rất nhiều người hiện đại không có nghĩ tới .\nNhưng , cái này cũng là nhất thiết phải tại Hán Vũ Đế Lưu Triệt thời kỳ đó hoàn thành .\nVẫn là lời khi trước , tại lúc đó , Hán Vũ Đế Lưu Triệt , không có bất kỳ cái gì cản tay !\nKhông có thấy được cản tay , mới có thể hoàn thành , không nhìn thấy tư tưởng “ Tập quyền ”.\n“ Mà Hán Vũ Đế Lưu Triệt , cũng đúng lúc hoàn thành thời đại giao phó hắn “ Sứ mệnh ”.”\n“ Cái này cũng là ta cho rằng , Hán Vũ Đế Lưu Triệt , chính trị năng lực , có thể tại trong lịch sử mấy trăm vị Đế Vương , xếp tại hàng đầu nguyên nhân .”\n“ Hắn đúng là thấy được điểm này , đồng dạng , cũng làm ra điểm này .”\nLý Ân Phàm cảm khái một câu như vậy , sau đó cầm lấy bánh bao , cắn một cái , lại từ từ nói :\n“ Hiện đại rất nhiều người nói , Tần Thủy Hoàng Doanh Chính lưu lại đại nhất thống dàn khung , cho nên đời sau vô số hoàng đế , mới suy nghĩ đại nhất thống .”\n“ Ở trong đó kỳ thực là có một chút sai lầm .”\n“ Tần Thủy Hoàng Doanh Chính , là lưu lại dàn khung , nhưng trọng yếu nhất bên trên tư tưởng “ Đại nhất thống ”, là Hán Vũ Đế Lưu Triệt hoàn thành .”\nNói đến đây , Lý Ân Phàm đột nhiên dừng một chút , nhìn xem Lưu Bang , nhẹ nói :\n“ Hoặc có lẽ là , là các ngươi , từ Tần Thủy Hoàng Doanh Chính bắt đầu , mãi cho đến Hán Vũ Đế Lưu Triệt , cái này 8 vị Đế Vương , chung cùng hoàn thành .”\n“ Nếu như không có ngươi , còn có về sau mấy vị Đế Vương , tiêu diệt những cái kia thấy được cản tay .”\n“ Hán Vũ Đế Lưu Triệt , cũng chính xác làm không được .”\nCho nên , từ cái này đến xem , Tần Thủy Hoàng Doanh Chính , phấn lục thế Dư Liệt , hoàn thành trên hình thức đại nhất thống .\nHán Vũ Đế Lưu Triệt , “ Phấn lục thế Dư Liệt ”, hoàn thành bên trên tư tưởng đại nhất thống .\nDạng này đến xem , đúng là không có gì mao bệnh .\n“ Ân ? Còn có chúng ta chuyện ?”\nLưu Bang ngẩng đầu kinh ngạc nhìn Lý Ân Phàm .\n“ Điểm này , chính xác muốn cảm tạ các ngươi .”\nMặc dù có thể những hoàng đế này sơ tâm , cũng không phải bởi vì phải hoàn thành cái gọi là bên trên tư tưởng đại nhất thống .\nNhưng bọn hắn làm những chuyện như vậy , lại cuối cùng hoàn thành điểm này .\nCho nên , từ cái này góc độ đến xem , Lý Ân Phàm mặc dù bây giờ cũng không thích trong lịch sử bất luận một vị nào hoàng đế .\nNhưng đúng là muốn cảm tạ bọn hắn .\nĐặc biệt là so sánh Châu Âu cái kia vô số phần rách tiểu quốc , cùng cái này Trung Nguyên đại địa bên trên , đại nhất thống lý niệm sau đó .\nLý Ân Phàm thì càng là cảm khái .\n“ Cho nên Hán Vũ Đế Lưu Triệt , về sau làm , có rất lớn tranh luận .”\n“ Nhưng cái này một cái Đại Công Tích , đúng là không cách nào ma diệt .”\nMặc dù rất nhiều người nói tại Tiên Tần thời kỳ , liền có cái gọi là đại nhất thống lý luận .\nTiếp đó chỉ bằng điểm này , liền đem Tần Thủy Hoàng Doanh Chính cùng Hán Vũ Đế Lưu Triệt chiến công chê bai .\nTiên Tần thời kỳ , quả thật có đại nhất thống lý luận .\nNhưng ở Tiên Tần thời kỳ , nói lên lý luận có nhiều lắm .\nNhưng vì cái gì về sau rất nhiều đều không lưu truyền tới nay ?\nBởi vì tại Tiên Tần thời kỳ , không có người để ý !\nNgươi đưa ra ngươi , có cần hay không , thì nhìn nắm giữ quyền lực những cái kia quốc quân .\nMà Tần Thủy Hoàng Doanh Chính cùng Hán Vũ Đế Lưu Triệt , một cái từ trên chế độ , dàn khung bên trên chế định đại nhất thống , một cái từ bên trên tư tưởng , triệt để “ Tập quyền ”.\nĐây chính là bởi vì bọn hắn đem những lý luận này , chế định vì quốc sách .\nLý luận hoàn mỹ đến đâu , cuối cùng vẫn là muốn người đi dùng , hoặc có lẽ là , cuối cùng vẫn là muốn người đi thi hành .\nLý luận nói cho dù tốt , không ai có thể dùng , người cầm quyền không thèm để ý , người nào còn có thể quan tâm ?\nQuan tâm , chỉ có những cái kia đưa ra lý luận những người kia đệ tử ...\nMà đệ tử không có ở đây , cũng không có người để ý .\nCâu nói này mặc dù rất tàn khốc , nhưng ở thế giới hiện thực , lại chung quy là sự thật .\nRất nhiều lý luận , chỉ có sau khi người cầm quyền để ý , người cầm quyền sử dụng , mới có thể hoàn thành từ trên xuống dưới rực rỡ hẳn lên .\nMà tầng dưới chót đâu ? Cũng mới sẽ chân chính đi thờ phụng , đi hoàn thành cái này một lý niệm .\nCho nên , rất nhiều lý luận , hoặc có lẽ là , rất nhiều lý niệm , vì cái gì cải biến ?\nBởi vì , người cầm quyền đều không thèm để ý , cái kia tầng dưới chót thay đổi , không cũng rất bình thường ?\n“ Trên làm dưới theo ”, hoặc có lẽ là “ Bên trên có chỗ hảo phía dưới nhất định cái gì chỗ này ”, những lời này mặc dù là có một chút nghĩa xấu .\nNhưng cũng trọn vẹn nói rõ một ít không cách nào tranh cãi sự thật .\n“ Cho nên , từ cái này đến xem , rất nhiều chuyện , trọng yếu là đưa ra lý niệm người sao ?”\nLý Ân Phàm nói đến đây , lắc đầu , khẽ thở dài một tiếng nói :\n“ Trọng yếu , là muốn đi người sử dụng nó .”\n“ Hán Vũ Đế Lưu Triệt Đại Công Tích , chính là bởi vì điểm này ...”\nNếu như làm một cái lý luận , thượng tầng buông rơi nó , tầng dưới cũng là nhất định đem từ bỏ .\nLịch sử , đã vô số lần đã chứng minh cái này sự thật tàn khốc .\n......', 'output\\mp3\\Màn Trời Quyền Lực Diễn Biến Cùng Truyền Thừa\\0076_Thứ 76 chương Tư tưởng đại nhất thống.mp3', '2026-09-01T23:28:54.725030+00:00', 'completed', 'completed', 7595, 7595),
	(82, 7, '7651897288356266521', 77, 'Thứ 77 chương Không bằng nói là thế lực chính trị', 'Thứ chương Không bằng nói là thế lực chính trị\nHiện đại thời không .\n“ Đại nhất thống lý luận khái niệm , xuất hiện rất sớm .”\n“《 Xuân Thu Công Dương Truyện 》 bên trong sớm nhất xuất hiện “ Đại nhất thống ” Một từ .”\n“ Đây là nho gia Công Dương học phái đối với 《 Xuân Thu 》 bộ này kinh điển giảng giải cùng trình bày .”\n“ Tại 《 Xuân Thu Công Dương truyện Ẩn công nguyên năm 》 bên trong , rõ ràng đưa ra “ Đại nhất thống ” Khái niệm , cường điệu thiên hạ thống nhất tại Chu thiên tử .”\n“ Nhưng ...”\n“《 Xuân Thu Công Dương Truyện 》 ghi chép bắt nguồn từ lỗ ẩn công nguyên năm ( Trước công nguyên năm ).”\n“ Mà Hán Vũ Đế Lưu Triệt , leo lên hoàng đế vị trí , là Công Nguyên phía trước năm .”\n“ Ở trong đó thời gian , đi qua năm !”\n“ Tiếp cận sáu trăm năm thời gian ...”\nLý Ân Phàm thanh toán tiền ăn sáng , cùng Lưu Bang cùng đi ra khỏi tiệm ăn sáng , tùy tiện ở bên ngoài tìm một vị trí ngồi xuống .\n“ Vì cái gì đã nhiều năm như vậy , tại Hán Vũ Đế Lưu Triệt thời kì , mới thật sự đem nó bưng lên ?”\n“ Tiên Tần thời kỳ , Gia Tử Bách gia , nói lên lý luận khái niệm , có nhiều lắm .”\n“ Nhưng vì cái gì cuối cùng là Tần quốc thống nhất thiên hạ ? Rất đơn giản , bởi vì Tần quốc dùng pháp gia .”\nLý Ân Phàm cầm lấy bình nước suối khoáng , uống một hớp nước .\n“ Cho nên , ta vẫn cho rằng , lý luận xuất hiện , cùng quyết định người sử dụng nó , ai quan trọng hơn ?”\n“ Quyết định người sử dụng nó , quan trọng hơn .”\n“ Đương nhiên , ta cũng không có nói , lý luận xuất hiện , cũng không trọng yếu .”\n“ Chỉ là đem so sánh mà nói , có đôi khi quyết định sử dụng người cầm quyền , công lao của hắn , lớn hơn một chút .”\nNói đến đây , Lý Ân Phàm bỗng nhiên nghĩ tới điều gì , quay đầu nhìn Lưu Bang , nhẹ giọng hỏi :\n“ Đúng , Quý ca .”\n“ Ân ?”\nLưu Bang quay đầu nghi hoặc nhìn Lý Ân Phàm .\n“ Bây giờ rất nhiều tiểu thuyết xuyên việt , chính là xuyên qua đến Tần quốc , còn có cuối Tần thời kì .”\n“ Thống nhất thiên hạ sau đó , phân công Gia Tử Bách gia , ngươi cảm thấy có khả năng hay không ?”\nNghe nói như thế , Lưu Bang kinh ngạc nhìn xem Lý Ân Phàm nói :\n“ Phân công Gia Tử Bách gia ?”\n“ Ân , thống nhất sau đó , phân công Gia Tử Bách gia .”\n“ Tỉ như nói , để cho pháp gia đi quản hình luật , để cho nho gia đi học đường dạy học , để cho nông gia đi tầng dưới chót ...”\nLưu Bang khẽ cười một cái , đứng lên , khoanh tay nói :\n“ Tiên sinh , ngươi biết vì sao là Gia Tử Bách gia có Bách gia sao ?”\nĐiểm này Lý Ân Phàm thật không có cụ thể hiểu qua .\nVì cái gì Gia Tử Bách gia , có Bách gia ?\n“ Ta ban đầu , cũng không biết Gia Tử Bách gia nói là cái gì .”\n“ Nhưng từ ngươi nói những thứ này đến xem , phải nói chính là nho gia cùng binh gia cùng với pháp gia những người kia .”\nNày ngược lại là , “ Gia Tử Bách gia ” Một khái niệm này , sớm nhất xuất hiện tại Tư Mã Thiên đối với Giả Nghị " Tinh thông Gia Tử Bách gia chi thư " Ghi lại .\nLúc trước thời kì , vẫn chưa có người nào nói ra dạng này khái niệm .\n“ Gia Tử Bách gia , sở dĩ có Bách gia , là bởi vì tại thời kỳ Xuân Thu , các nước chư hầu có hơn một trăm cái ...”\n“ Tiên sinh , lần này ngươi hiểu không ?”\nLý Ân Phàm nghe vậy , có chút sững sờ nhìn xem Lưu Bang .\n“ Cho nên , ngươi hỏi ta , tại cuối Tần , hay là Tần triều thời kì , trực tiếp phân công Gia Tử Bách gia tới quản lý Đại Tần , hay là đại hán ?”\nLưu Bang nói đến đây , chỉ là lắc đầu , không có tiếp tục nói nữa .\nNhưng lần này , lại đem Lý Ân Phàm trong đầu , một ít mạch suy nghĩ đả thông .\n“ Thì ra là thế ...”\nLý Ân Phàm trước đó quả thật có chút ngây thơ , khi nhìn Tần triều hay là Hán triều tiểu thuyết xuyên việt , cũng ảo tưởng phân công Gia Tử Bách gia lý niệm đi quản lý quốc gia .\nDạng này từ hậu thế đến xem , đúng là có chỗ dùng , bởi vì hiện đại có thể dung hạ được .\nNhưng vì cái gì hiện đại có thể chứa đựng ?\nBởi vì Gia Tử Bách gia , trải qua một hai ngàn năm xuống dốc , vì sinh tồn , bọn chúng bỏ đi rất nhiều không đúng lúc lý niệm .\nMà Gia Tử Bách gia , bọn hắn sớm nhất ngôn luận cùng lý niệm là cái gì ? Kỳ thực là chính trị lý niệm .\nĐều tưởng tượng lấy có các nước chư hầu có thể sử dụng tư tưởng của mình đi trị quốc .\nĐây không phải chính trị lý niệm , là cái gì ?!\nNếu như tại Gia Tử Bách gia đều hưng thịnh thời kì , không có sa sút thời kì , trực tiếp phân công Gia Tử Bách gia đi quản lý quốc gia ?\nLà phi thường có khả năng sẽ trở lại thời kỳ Xuân Thu .\n“ Này ngược lại là ta nghĩ có chút xóa ...”\n“ Ta trước đó vẫn cho là nông gia , bọn hắn chính là ở trong thổ địa kiếm ăn ...”\n“ Nhưng nghe ngươi nói như vậy sau đó , ta mới ý thức tới , vì cái gì Tần quốc chỉ là cách dùng nhà tới trị quốc .”\n“ Này ngược lại là ta dùng đời sau ánh mắt , đi xem ngay lúc đó thời kỳ .”\nLý Ân Phàm đúng là không để ý đến những thứ này Gia Tử Bách gia không có tịch mịch thời điểm , bọn hắn đề ra những thứ đó .\n“ Ta cũng hiểu , vì cái gì ở phía sau tới vô số thời kì , muốn đè ép những thứ này Gia Tử Bách gia .”\nĐúng vậy , giờ khắc này Lý Ân Phàm chính xác nghĩ thông suốt rất nhiều chuyện .\nNghĩ thông suốt vì cái gì Tần Thủy Hoàng Doanh Chính sẽ đốt sách ...\nCũng nghĩ thông vì cái gì Hán Vũ Đế Lưu Triệt muốn trục xuất Bách gia bên trong lôgic ...\nCàng nghĩ thông suốt hơn , vì cái gì về sau vô số thời gian , sẽ đánh đè những thứ này Gia Tử Bách gia ...\nNguyên nhân căn bản nhất , cũng là bởi vì những thứ này Bách gia , lý niệm của bọn hắn , sớm nhất là chính trị lý niệm .\nMà dùng pháp gia Tần triều , sẽ để cho những thứ khác chính trị lý niệm tới ô nhiễm chính mình triều đình sao ?\nTôn nho gia Hán triều , sẽ cho phép khác Bách gia truyền bá lý niệm của mình sao ?\nNày liền như cái gì ? Đại Hùng thời kỳ đỉnh phong , bọn hắn sẽ tùy ý chủ nghĩa tư bản tri thức , tại cảnh nội truyền bá sao ?\nPhá vỡ một cái vương triều chính trị lý niệm , độ khó kỳ thực là không thua gì phá vỡ toàn bộ vương triều .\nBởi vì từ trên xuống dưới , hết thảy mọi người , cũng là cái này lý niệm người được lợi ích , hoặc có lẽ là ủng hộ người .\n“ Mà muốn dùng còn lại Gia Tử Bách gia , độ khó chỉ sợ so cái này còn cao ...”\n“ Bởi vì muốn để còn lại Gia Tử Bách gia , đều từ bỏ đi chính mình chính trị lý niệm ...”\n“ Hơn nữa , cùng nói những thứ này Gia Tử Bách gia là tư tưởng lưu phái , không bằng nói tại lúc đó , những thứ này Gia Tử Bách gia , là thế lực chính trị .”\nLý Ân Phàm nghĩ tới đây , chỉ có thể là lắc đầu .\nTrong lịch sử , cũng là dùng vô số thời gian , mới khiến cho cái này một số người triệt để xuống dốc .\nĐộ khó này quá lớn , chỉ có thể dựa vào thời gian đi mài ...\nDù sao , để cho một cái vô cùng kiên định , vô cùng thờ phụng một cái lý niệm người , từ bỏ lý niệm của mình , đi chuyên tâm nghiên cứu như thế nào trồng lương thực ?\nNày liền hoàn toàn lâm vào một cái nghịch lý .\nKiên định tín niệm người , tại lúc đó , mới là “ Nông gia ” “ Pháp gia ” “ Nho gia ”...\nMà không kiên định tín niệm người , bọn hắn vẫn là “ Nông gia ” “ Pháp gia ” “ Nho gia ” Sao ?\nBọn hắn không kiên định tín niệm , vậy bọn hắn có thể làm chuyện , những người khác , cũng liền có thể làm .\nGiống như hiện đại , dạy học trồng người lão sư , bọn hắn là nho gia người sao ?\nCho nên , kết quả là , vì cái gì còn nhất định phải dùng vấn đề gì “ Nông gia ” Người ? “ Pháp gia ” Người ? “ Nho gia ” Người ?\nLý Ân Phàm nghĩ tới đây , chỉ có thể là thở dài một hơi .\nBởi vì cái này khiến Lý Ân Phàm nghĩ tới rất nhiều chuyện , đặc biệt là bây giờ rất nhiều chuyện .\n“ Đây đúng là hoàn toàn chính là một cái nghịch lý ...”\n“ Cũng là chuyện không cần thiết ...”\nLắc đầu , Lý Ân Phàm cầm trong tay bình ném vào thùng rác , sau đó mang theo Lưu Bang đi vào sân bay .\n......', 'output\\mp3\\Màn Trời Quyền Lực Diễn Biến Cùng Truyền Thừa\\0077_Thứ 77 chương Không bằng nói là thế lực chính trị.mp3', '2026-09-01T23:28:59.622620+00:00', 'completed', 'completed', 7500, 7500),
	(83, 7, '7652280270954955289', 78, 'Thứ 78 chương Vòng xoáy', 'Thứ chương Vòng xoáy\nHiện đại thời không .\nKỳ thực rất nhiều lôgic , đặc biệt là trong loại trong chính trị này lôgic , từ xưa cũng là tương thông .\nCổ đại một mực chèn ép một cái tổ chức nào đó , hay là một chút quần thể .\nVậy bọn hắn chắc chắn là dính đến trong chính trị một vài thứ .\nNếu như không phải dính đến trong chính trị đồ vật , trên triều đình , là cực ít có người sẽ đánh đè bọn hắn .\nChèn ép có lẽ có một chút sai lầm , tiêu diệt có thể mới là đối .\nCái này giống như cổ đại tạo phản , khởi nghĩa , khởi binh các loại , vì cái gì triều đình muốn hết sức tiêu diệt những thế lực này ?\nBởi vì những thế lực này , chính là tới lật đổ bọn hắn , đây là ai đều biết sự tình .\nNhưng nói như thế nào đây ? Đây đều là ở ngoài sáng , hoặc giả thuyết là một mắt có thể nhìn thấy .\nMà không nhìn thấy , chính là những thứ này chính trị lý niệm .\nTại thời cổ , chính là những thứ này Gia Tử Bách gia , bọn hắn chính là loại này “ Bên trên tư tưởng tạo phản ” Quần thể .\nMà điểm này , chúng ta từ Tần quốc thương ưởng biến pháp , liền có thể hoàn toàn nhìn ra , tại sao lại như thế .\nTại Tần Hiếu Công doanh mương lương phân công Thương Ưởng tới biến pháp , thứ nhất phản đối là ai ?\nChính là lúc đó Tần quốc những cái kia lão Tần người , hoặc chuẩn xác mà nói , là những cái kia vừa người được lợi ích .\nMà thương ưởng biến pháp , mang tới mới chính trị lý niệm , cũng chính là pháp gia , đem bọn hắn dựa vào sinh tồn thổ nhưỡng , toàn bộ phá hư .\nBọn hắn phản đối , cũng liền trở nên thuận lý thành chương .\nMà từ một điểm này chúng ta đi xem , hậu thế từ Tần Thủy Hoàng Doanh Chính bắt đầu , vì sao muốn chèn ép trừ chính mình sử dụng Gia Tử Bách gia ?\nNguyên nhân ngay ở chỗ này !\nHơn nữa Gia Tử Bách gia , tại cuối Tần Hán sơ thời điểm , có bao nhiêu nhà đâu ?\nĐáp án dĩ nhiên là nhà !\nMặc dù cổ đại lực ảnh hưởng lớn nhất , kỳ thực là thập gia !\nHiện đại sẽ đem binh gia cùng y gia tính toán đi vào , tổng cộng là mười hai nhà .\nỞ đây liền có một cái vấn đề , vì cái gì nói cổ đại lực ảnh hưởng lớn nhất là thập gia ?\nKhông phải nói , sau khi Hán Vũ Đế độc tôn học thuật nho gia , còn lại Gia Tử Bách gia đều bị chèn ép sao ?\nĐúng , là bị chèn ép , nhưng ở bị chèn ép sau đó , bọn hắn liền từ bỏ mình chính trị lý niệm .\nTiếp đó , ngược lại đi nghiên cứu chính mình “ Bản chức ”.\nCho nên , từ chúng ta đời sau góc độ đi xem , lực ảnh hưởng lớn nhất , đơn giản cứ như vậy mười hai nhà .\nNhưng , tại ở trong đó có một cái điển hình nhất tư tưởng lưu phái , một mực tại phản kháng .\nBọn hắn đã từng từng thu được chính trị địa vị , cho nên , từ Hán triều bắt đầu , bọn hắn vẫn tại vụng trộm phản kháng “ Nho gia ”.\nMột nhà này nếu như không nói , chắc chắn rất nhiều người một mực không nhớ ra được .\nNhưng chỉ cần nói chuyện , đại gia liền biết , một nhà này , chính là “ Đạo gia ”.\nTừ cuối thời Đông Hán loạn Hoàng Cân .\nĐến Thanh triều bạch liên ...\nCái này một hai ngàn năm , bọn hắn một mực tại vụng trộm phản kháng , muốn lần nữa thu được chính trị địa vị .\nNhìn thấy cái này , khẳng định có người sẽ nhớ , bạch liên không phải phật sao ?\nSớm nhất là phật , nhưng ở sau đó , dung hợp quá nhiều , chiếm cứ vị trí chủ đạo , ngược lại thành đạo .\nBởi vì cuối cùng tới nói , đạo là bản thổ tông giáo , mà phật là ngoại lai tông giáo .\nVì tại tầng dưới chót ảnh hưởng lực truyền bá , bạch liên sau đó từng bước từ đạo chiếm cứ chủ đạo .\nTrong lịch sử muốn tạo phản người , rất nhiều trực tiếp nhập đạo , cũng là có nguyên nhân như vậy ở bên trong .\nMà ngoại trừ bên ngoài phản kháng thế lực , nội bộ đâu ?\nNội bộ , bọn hắn cũng tương tự tại đường cong vào triều đường .\nĐây chính là trong lịch sử , vì những hoàng đế kia , luyện chế “ trường sinh bất lão đan ” Đạo sĩ .\nChính bọn hắn nhất quyết không ăn đồ vật , vì cái gì dám vào triều đình , để cho hoàng đế ăn ?\nChính là vì thu hoạch hoàng đế tín nhiệm , sau đó tới thu hoạch chính trị địa vị .\nCái này cũng là trong lịch sử , rất nhiều hoạn lộ âu sầu thất bại người , ngược lại chạy tới nhập đạo người một dạng .\nBởi vì hoàng đế , có đôi khi vì chèn ép nội bộ “ Nho gia ” Thế lực , sẽ giả vờ nghĩ “ Trường sinh bất lão ”, tiếp đó trên triều đình dẫn vào “ Đạo gia ”.\nTrong lịch sử , là có hoàng đế làm qua chuyện như vậy .\nTrong đó điển hình nhất , chính là Minh triều Gia Tĩnh hoàng đế , Chu Hậu Thông .\nHắn chính là điển hình nhìn trên triều đình , “ Nho gia ” Thế lực quá mức khổng lồ , hơn nữa liên lạc qua nhanh , cho nên muốn dẫn vào những thứ khác tư tưởng lưu phái , tới nhờ vào đó phản kháng “ Nho gia ”.\n“ Chỉ có thể nói , lịch sử rất nhiều tổ chức bị chèn ép , bị tiêu diệt , thật sự không có oan chút nào uổng ...”\nLý Ân Phàm trên đường nghĩ tới đây , nói như thế nào đây ? Chỉ có thể nói lắc đầu .\nDù sao dính đến chính trị vật này , vậy thì căn bản không có đúng sai , chỉ có thắng thua .\nBước vào chính trị vòng xoáy này , vậy thì thật sự không có cách nào phàn nàn .\nDù sao không phải là gió đông thổi bạt gió tây , chính là gió tây thổi ngã gió đông .\nTrong lịch sử thắng là nho gia , cho nên chúng ta mới có thể ở đời sau mắng chửi nho gia .\nMà trong lịch sử nếu là thắng là khác Gia Tử Bách gia đâu ?\nBọn hắn cũng đồng dạng sẽ hết sức chèn ép còn lại Gia Tử Bách gia .\nBên trên tư tưởng đấu tranh , so với ích lợi bên trên đấu tranh , tới càng thêm mãnh liệt .\nBên trên tư tưởng đấu tranh , đó là chân chính ngươi chết ta sống .\nLợi ích đấu tranh , có đôi khi có thể sẽ còn thỏa hiệp .\nNhưng ngươi để cho một cái kiên định tư tưởng người , đi thỏa hiệp ?\nKhông cần phải nói cổ đại , nhìn lại một trăm năm trước , tư tưởng vô cùng kiên định người , có bao nhiêu người sẽ thỏa hiệp ?\nCho nên , bên trên tư tưởng tranh đấu , tại cuối cùng , tuyệt đối là không cách nào thỏa hiệp .\nDù là trên đường , có thể sẽ thỏa hiệp nhất thời , nhưng cuối cùng , lại là tuyệt không cách nào thỏa hiệp .\nBởi vì ở trong mắt ngươi , đối phương chính là dị đoan .\nMà ở đối phương trong mắt , ngươi cũng là dị đoan !\nDị đoan kết cục là cái gì ?\nHơn nữa trong cùng một cái tư tưởng lưu phái , có đôi khi đều đả sinh đả tử , chớ nói chi là còn lại tư tưởng lưu phái .\n...\nĐường triều .\nTrinh Quán bảy năm .\n“ Gia Tử Bách gia ...”\nLý Thế Dân đã từng nghĩ tới , phải chăng có thể trên triều đình dẫn vào còn lại Gia Tử Bách gia , đến đối kháng lúc này “ Nho gia ” Người phát ngôn , những thế gia kia .\nCó thể nghĩ nghĩ , hắn liền bác bỏ .\nBởi vì cái này mạo hiểm , quả thực là quá lớn .\nHơn nữa , cũng không thể khống !\nBên trên tư tưởng sự tình , thật là nhất không thể khống chế một loại .\nNếu quả thật dẫn vào còn lại Gia Tử Bách gia , đến lúc đó Đại Đường chia ra phong hiểm , ngược lại sẽ kịch liệt gia tăng .\nDù sao bên trên tư tưởng đấu tranh , là rất dễ đi lên đối kháng quân sự lộ tuyến .\nCho nên , Lý Thế Dân chỉ là muốn nghĩ , liền ngược lại từ bỏ , cái giá này , lúc này Đại Đường , không thể tiếp nhận .\nMà về phần nói những cái kia trên triều đình võ tướng ?\nLúc này võ tướng , đã không còn là Tiên Tần thời kỳ “ Binh gia ”.\nBọn hắn là từ “ Nho gia ” Trên căn , mọc ra võ tướng .\nBinh gia lý niệm , rất nhiều cũng đều bị từ bỏ .\nChỉ có thể nói , bây giờ những thứ này võ tướng , dùng cũng là binh gia “ Thuật ”, mà không phải binh gia “ Đạo ”.\nCái này “ Thuật ” “ Đạo ”, đơn giản tới nói , giống như là lúc này pháp gia .\nBọn hắn cũng từ bỏ “ Đạo ”, ngược lại đi chuyên tâm nghiên cứu “ Thuật ”.\nCho nên , bọn hắn cuối cùng , cũng đều là “ Nho gia ” Người .\nTriều đình này bên trên , có thể nói , trên cơ bản , cũng là “ Nho gia ” Người .\nDù là thật là muốn dụ vào còn lại Gia Tử Bách gia , cũng quá khó khăn , quá khó khăn .\n......', 'output\\mp3\\Màn Trời Quyền Lực Diễn Biến Cùng Truyền Thừa\\0078_Thứ 78 chương Vòng xoáy.mp3', '2026-09-01T23:29:04.519524+00:00', 'completed', 'completed', 7506, 7506),
	(84, 7, '7652280550387892761', 79, 'Thứ 79 chương Thường dùng thủ đoạn thôi', 'Thứ chương Thường dùng thủ đoạn thôi\nMinh triều .\nVĩnh Lạc bảy năm .\n“ Lão đại , ngươi nói dẫn vào còn lại Gia Tử Bách gia . Để chèn ép những cái kia nho gia người , được hay không ?”\nChu Lệ nghe được màn trời giảng thuật , quay đầu nhìn về phía Chu Cao Sí .\n“ Phụ thân , ngươi là muốn đem tạo phản thực lực , trực tiếp dẫn vào đến trên triều đình sao ?”\nChu Cao Sí chỉ là khe khẽ thở dài , sau đó bất đắc dĩ hướng về phía Chu Lệ nói .\n“ Ân ? Vì cái gì nói như vậy ?”\nNghe được Chu Cao Sí lời nói , Chu Lệ nhất thời có chút mộng .\n“ Bởi vì tại nho gia người đến xem , những người kia chính là tạo phản thế lực .”\n“ Những người kia , là tới lật đổ bọn hắn !”\n“ Ngươi cho rằng những cái kia nho gia người sẽ lằng nhà lằng nhằng , tiếp đó từ từ cùng bọn hắn tiến hành chính trị đấu tranh ?”\n“ Sẽ không !”\n“ Bọn hắn sẽ vô cùng đoàn kết , tiếp đó chung cùng chèn ép những cái kia ngoại lai tư tưởng thế lực .”\nChu Cao Sí nói đến đây , mang theo vẻ hồi ức , tiếp tục chậm rãi đối với Chu Lệ giảng thuật nói :\n“ Trong lịch sử bọn hắn có giáo huấn khắc sâu , cũng có phong phú kinh nghiệm .”\n“ Bọn hắn đã trải qua quá nhiều chuyện như vậy .”\n“ Cho nên , muốn dụ vào còn lại tư tưởng thế lực , đến đối kháng nho gia người ?”\n“ Chỉ cần không động vào triều đình , kia cái gì đều dễ nói .”\n“ Nhưng nếu là đụng phải triều đình , vậy những này ngoại lai , chính là tạo phản thế lực .”\nSau đó , Chu Cao Sí nhìn xem Chu Lệ ánh mắt , rất bình tĩnh nói :\n“ Nếu như bọn hắn không phải tạo phản thực lực làm sao bây giờ ?”\n“ Rất đơn giản , trên triều đình nho gia người , bọn hắn cũng có thể tùy thời biến thành tạo phản thế lực .”\nChu Lệ nghe vậy , nhất thời có chút trầm mặc .\nTrầm mặc là bởi vì hắn nghe hiểu , cho nên mới trầm mặc .\n“ Có nhiều thứ , chúng ta hoàng đế , là tuyệt đối không thể đụng vào .”\n“ Dù là thật muốn dây vào , cũng chỉ có thể cẩn thận từng li từng tí , nhưng cứ như vậy , thì có ích lợi gì ?”\n“ Khi ngươi ta chết đi , hết thảy tất cả đều sẽ bị bọn hắn một lần nữa lật đổ !”\nChu Cao Sí rất tỉnh táo , tỉnh táo có chút không thể tưởng tượng nổi .\nNhưng chính là bởi vì hắn lúc trước nghĩ tới chuyện như vậy , cho nên mới sẽ bình tĩnh như vậy .\nDẫn vào còn lại Gia Tử Bách gia tư tưởng thế lực , tới tiến vào triều đình , có thể được không ?\nLà có thể được !\nNhưng ngươi nhất định phải làm chỗ tốt chỗ lang yên chuẩn bị !\nĐặc biệt là đến bọn hắn Đại Minh , thì càng là như thế .\nTư tưởng đi qua một hai ngàn năm phát triển , đã thâm căn cố đế .\nLà ngươi nói lật đổ , liền có thể lật đổ ?\nNghe xong lâu như vậy màn trời , tại Chu Cao Sí xem ra , nghĩ triệt để lật đổ nho gia , tiếp đó một lần nữa khác lập tư tưởng thế lực ?\nTrừ phi tới một cái nữa “ Phấn lục thế Dư Liệt ”...\nCó thể coi là thật sự tới “ Phấn lục thế Dư Liệt ”, đem nho gia đẩy ngã , thì thế nào đâu ?\nLà lại lập đạo nhà ? Còn có lập pháp nhà ?\nTiếp đó đi qua mấy trăm năm phát triển , Đạo gia hay là pháp gia , lại lại biến thành “ Nho gia ” Bộ dáng .\nKhông có đối thủ , chính là như vậy !\nNhưng có đối thủ , ngươi có thể bốc lên chia ra phong hiểm , để cho bọn hắn trên triều đình tiến hành chính trị đấu tranh sao ?\nCó lẽ một vị hoàng đế có thể , nhưng đời tiếp theo đâu ? Hạ hạ một nhiệm kỳ đâu ?\nMột bên khác thua , chó cùng đường quay lại cắn , trực tiếp tạo phản , sẽ làm thế nào ?\n“ Cho nên , phụ thân ...”\nChu Cao Sí lúc này nhìn xem Chu Lệ ánh mắt , trong lời nói tràn đầy nghiêm túc .\n“ Có một số việc , trong lịch sử rất nhiều hoàng đế , không phải không biết , là chấp nhận .”\n“ Mà những cái kia “ Nho gia ” Người đâu ? Bọn hắn có rất nhiều người thông minh , cho nên sẽ thỏa hiệp ...”\n“ Đây chính là vì cái gì trong lịch sử rất nhiều anh minh thần võ hoàng đế , sẽ tùy ý nho gia độc quyền nguyên nhân .”\nSau đó , Chu Cao Sí ngẩng đầu nhìn màn trời , nhẹ nói :\n“ Hơn nữa , tại trong Gia Tử Bách gia , nho gia đã là tối ôn hòa .”\n“ Ngươi có thể tưởng tượng binh gia , hay là Đạo gia , bọn hắn tràn ngập triều đình sao ?”\n“ Suy nghĩ một chút sách sử phía trên , Đạo gia ghi lại lý niệm , còn có binh gia ghi lại lý niệm .”\nNói đến đây , Chu Cao Sí cười cười , sau đó nói :\n“ Tại trong có chút Gia Tử Bách gia lý niệm , thế nhưng là không cần ngươi ta ...”\nChu Cao Sí đúng là học rộng tài cao .\nCàng bởi vì có mình mẫu thân , được xưng tán vì “ Nữ Gia Cát ” Từ thị , cho nên hồi nhỏ hắn đọc rất nhiều sách .\nThế nhưng cũng bởi vì đọc rất nhiều sách , chờ thân ở vị trí này , hắn mới có thể thấy rõ rất nhiều chuyện .\nHắn hiểu được , có một số việc , cuối cùng không phải mình có thể đụng .\n“ Lão đại kia , ngươi nói phụ thân , hắn đã nghĩ tới chuyện như vậy sao ?”\n“ Gia gia ?”\nChu Cao Sí nhíu mày , sau đó gật đầu một cái nói :\n“ Gia gia hắn đương nhiên muốn đến .”\n“ Bằng không thì phụ thân , ngươi cho rằng Phật giáo , vì sao tại gia gia hắn cái kia thời điểm , còn có thể sinh tồn tiếp ?”\n“ Gia gia thế nhưng là làm qua hòa thượng , hơn nữa bị hòa thượng từng làm nhục .”\nChu Lệ cũng nghĩ đến cái này chuyện cũ năm xưa , sau đó hiểu rõ gật đầu một cái .\nQuả thật là như thế , đến hôm nay hắn mới đột nhiên phát hiện , vì sao phụ thân rõ ràng tại cuối thời nhà Nguyên thời điểm , liền biết chùa miếu là cái gì điểu dạng .\nCuối cùng làm tới hoàng đế , lại ngược lại buông tha bọn hắn .\n“ Hơn nữa không chỉ là điểm ấy , phụ thân , ngươi cũng cần phải biết , lúc này Đại Minh tầng dưới chót , còn có bao nhiêu âm u chuột ...”\n“ Tại ta nghĩ đến , gia gia có thể là cho rằng , để cho những người kia chịu lừa bịp đi tín ngưỡng những vật kia , còn không bằng liền tín ngưỡng phật ...”\n“ Chỉ cần phật tại triều đình khống chế là được rồi .”\nChu Lệ thở dài , có chút bất đắc dĩ nói :\n“ Đúng vậy a , cùng để cho bách tính đi tin những vật kia , còn không bằng đi tin phật ...”\n“ Ít nhất phật đến lúc này , sẽ không tạo phản .”\n“ Mà những người kia , thế nhưng là thời thời khắc khắc suy nghĩ tạo phản ...”\nCái này cũng là Chu Lệ thân là hoàng đế bất đắc dĩ , có đôi khi ngươi vì đối kháng một vài thứ , chỉ có thể đi bỏ mặc một chút mặc kệ .\nBởi vì hoàng đế đúng là so với ai khác đều biết , bên trên tư tưởng đấu tranh , so với ích lợi đấu tranh nghiêm trọng hơn .\nCho nên , hoàng đế liền mặc cho bọn hắn ở phía ngoài tiến hành bên trên tư tưởng đấu tranh .\nNâng đỡ một phương , chèn ép tiêu diệt một phương khác .\nChính trị cân bằng trung thường dụng thủ đoạn thôi .\n...\nTống triều .\nMở bảo sáu năm .\n“ Cho nên , cuối cùng vẫn là cần nho gia ...”\nTriệu Khuông Dận chỉ có thể là bất đắc dĩ thở dài .\nHắn lúc này , dù là hắn không muốn đi nữa , cũng chỉ có thể dựa vào nho gia .\nĐến nỗi nói “ Binh gia ”, vẫn là “ Pháp gia ”? Lại có lẽ là “ Đạo gia ”?\nDụng binh nhà , đó chính là trở lại trước đây thời kì .\nCách dùng nhà ? Bây giờ Trung Nguyên đại địa , cần chính là hưu sinh dưỡng tức .\nTừ nơi này đến xem , có lẽ dùng Đạo gia thật thích hợp .\nNhưng địch nhân ở chung quanh , có thể cho phép Tống triều dùng Đạo gia sao ?\nThật học Hán sơ thời điểm , nằm ngửa hưu sinh dưỡng tức mấy chục năm ?\nCái kia Tống triều đoán chừng sớm đã không có !\nCho nên , cuối cùng vẫn cần phải đi dùng nho gia , dùng nho gia “ Nhân trí lễ nghi tin ”, tới thay đổi lúc này trong tràn ngập nguyên đại địa một chút tập tục .\n“ Cho nên , đây chính là màn trời nói , thời đại giao phó trách nhiệm của ta ?”\nTriệu Khuông Dận không hiểu câu nói này rốt cuộc là ý gì , nhưng nghe màn trời nói mấy lần .\nKết hợp với hoàn cảnh mà chính mình đang ở , cùng với kinh nghiệm của mình , Triệu Khuông Dận tựa hồ có một chút đã hiểu màn trời nói lời này , rốt cuộc là ý gì .\n“ Chính mình nhất định phải làm sao ?”\n......', 'output\\mp3\\Màn Trời Quyền Lực Diễn Biến Cùng Truyền Thừa\\0079_Thứ 79 chương Thường dùng thủ đoạn thôi.mp3', '2026-09-01T23:29:28.312080+00:00', 'completed', 'completed', 7474, 7474),
	(85, 7, '7652701050029228568', 80, 'Thứ 80 chương Đại quản gia', 'Thứ chương Đại quản gia\nHiện đại thời không .\n“ Giúp chúng ta cầm hai cái tấm thảm liền tốt , cảm tạ !”\nLý Ân Phàm nhẹ giọng đối với một vị tiếp viên hàng không nói xong , sau đó lại nhìn về phía bên cạnh Lưu Bang .\nLưu Bang lúc này ở làm cái gì đây ? đang tò mò nhìn máy bay ngoài cửa sổ cảnh sắc .\nLần thứ nhất bay lên không trung , lần thứ nhất từ không trung nhìn lên đại địa cảnh sắc , cũng là lần thứ nhất đi máy bay .\nLưu Bang nội tâm , giờ này khắc này , có quá nhiều rung động .\n“ Quý ca , muốn nghỉ ngơi một hồi sao ?”\n“ Không cần .”\nMặc dù vô cùng rất hiếu kỳ , nhưng nhìn một hồi , Lưu Bang liền không lại nhìn .\nLưu Bang có thể thật tốt mà khống chế dục vọng của mình , từ cuối Tần khởi binh thời điểm , liền luôn luôn như thế .\nDù là nội tâm lại hiếu kỳ , nhưng Lưu Bang biết một chuyện , thích hợp mà dừng ...\n“ Tiên sinh , nói một chút con cháu của ta , vì cái gì năng lực quân sự cũng rất mạnh a ...”\nLấy lại tinh thần Lưu Bang , bỗng nhiên nghĩ tới chủ đề trước đó , mang theo tìm tòi nghiên cứu thần sắc nhìn về phía Lý Ân Phàm .\n“ Đang nói đến vấn đề này phía trước , Quý ca , hỏi ngươi một vấn đề .”\nCũng may mắn Lý Ân Phàm mua vé máy bay , là khoang hạng nhất , hơn nữa chiếc máy bay này khoang hạng nhất cũng chỉ có hai người bọn họ .\nBằng không thì Lý Ân Phàm có thể còn không biết đối với Lưu Bang nói tiếp .\nDù sao ở trên máy bay quấy rầy người khác , chung quy là không tốt .\n“ Vấn đề gì ?”\n“ Ngươi cảm thấy ngươi khởi binh sau đó , mãi cho đến thiết lập đại hán , công lao lớn nhất là ai ?”\n“ Công lao lớn nhất là ai ?”\nLưu Bang càng thêm mơ hồ , đây không phải mọi người đều biết chuyện sao ? Chẳng lẽ hậu thế không có đem sự tích của hắn ghi tạc xuống ?\n“ Đương nhiên là Tiêu Hà , bằng không thì còn có thể là ai ?”\n“ Ân ...”\nLý Ân Phàm chỉ là gật đầu một cái , sau đó lại nhìn về phía Lưu Bang hỏi :\n“ Ta hẳn là chính xác một điểm hỏi , trên quân sự , theo ý của ngươi , công lao lớn nhất là ai đây ?”\n“ Quân sự ?”\nLưu Bang nghe được vấn đề này , chỉ là dừng một chút , sau đó rất nhanh cấp ra đáp án :\n“ Đương nhiên vẫn là Tiêu Hà !”\nLý Ân Phàm vẫn như cũ chỉ là gật gật đầu , sau đó lại đột nhiên thở dài một hơi nói :\n“ Ngươi biết không ? Quý ca , nếu là lúc trước ta đây , nhất định sẽ đối với đáp án này khịt mũi coi thường ...”\n“ Thời điểm đó ta , rất nhiều chuyện không hiểu , đã cảm thấy , tại cuối Tần , trên quân sự công lao lớn nhất hẳn là Hàn Tín ...”\n“ Tiêu Hà dựa vào cái gì có thể cùng Hàn Tín so sánh ?”\nLưu Bang không nói chuyện , chỉ là nhíu mày một cái .\n“ Về sau , ta đang đọc sách thời điểm , bỗng nhiên nghĩ tới một vấn đề .”\n“ Ở trên quân sự , là tiền tuyến thống soái trọng yếu , vẫn là hậu phương hậu cần trọng yếu ?”\n“ Về sau ta , chậm rãi cải biến thái độ , nhưng ban sơ thay đổi , là cho rằng giữa hai bên , hẳn là trọng yếu giống vậy .”\n“ Cả hai hẳn là ai cũng không thể rời bỏ ai ...”\n“ Nhưng ta về sau , nhìn thấy lịch sử càng nhiều , ta liền lại cải biến ý nghĩ của mình ...”\n“ Quý ca , theo ý của ngươi , trên quân sự , là tiền tuyến thống soái trọng yếu , vẫn là hậu phương hậu cần trọng yếu ?”\nLần này , Lưu Bang vô cùng quả quyết cấp ra đáp án :\n“ Hậu cần !”\n“ Đúng vậy , hậu cần ...”\nLý Ân Phàm theo Lưu Bang mà nói , cũng cho ra mình đáp án , sau đó gật đầu một cái .\n“ Về sau ta hiểu đến , quan hệ trong này , không phải ai cũng không thể rời bỏ ai quan hệ , là trước tiên bởi vì hậu quả quan hệ .”\n“ Câu nói này , có thể ngươi không hiểu nhiều lắm .”\n“ Nhưng dùng thông tục một chút tới nói , chính là , có hậu cần , mới có có thể lên tiền tuyến thống soái !”\nCái này kỳ thực là không khó lý giải , nhưng rất nhiều người hẳn là không phản ứng kịp .\nVì cái gì phản ứng không kịp ? Bởi vì hiện đại , hiểu hậu cần người , quá ít , ít đến cái này một số người , đều bị xí nghiệp hoặc quân đội cùng với triều đình , gắt gao che ở trên tay mình .\nKhông có người sẽ đem hậu cần cao thủ thả ra !\nMà hậu cần , kỳ thực cũng là năng lực quân sự bên trên , khó khăn nhất một cái chi nhánh .\nGiống như phía trước nói , tại quân sự phía trên , cái này nhất định là trước tiên bởi vì hậu quả quan hệ .\nBởi vì có hậu cần , mới có tiền tuyến thống soái !\nMà không phải có thống soái , hậu cần đột nhiên xông ra .\nNếu như không có hậu cần làm sao bây giờ ? Đương nhiên là rau trộn !\nChiến tranh cũng sẽ không khởi xướng ! Thống soái chỉ có thể ở trong nhà nhìn binh thư !\nVẫn là câu nói kia , hiểu hậu cần người quá ít , cho nên cũng liền tạo thành một loại tình huống .\nHiện đại tiểu thuyết , truyền hình điện ảnh , điện ảnh các loại , bên trong cơ hồ không có hiểu hậu cần .\nKhông có người hiểu hậu cần , vậy làm sao bây giờ ? Vậy thì trực tiếp lướt qua !\nCho nên , cái này cũng liền tạo thành một loại cứng nhắc ấn tượng , tựa hồ hậu cần cũng không trọng yếu ?\nNhưng tại trên quân sự , trọng yếu nhất chính là hậu cần !\nKỳ thực , nhìn chung các triều đại đổi thay , từ Tần quốc thống nhất Lục quốc bắt đầu , đếm kỹ khai quốc chi công , lớn nhất chính là những thứ này “ Đại quản gia ”.\nNhững thứ này “ Đại quản gia ” Chính là chân chính hậu cần cao thủ .\nTần quốc “ Đại quản gia ” Là ai ? Lý Tư !\nHán triều , Tiêu Hà .\nCuối thời Đông Hán Tam quốc : Ngụy quốc , Tuân Úc .\nHán ( Thục ), Gia Cát Lượng .\nNgô , Chu Du ( Sau tới là Lục Tốn ).\nĐường triều , Lăng Yên các tên thứ nhất , Trưởng Tôn Vô Kỵ .( Chỉ là Lý Thế Dân một phương . Lý Uyên lập nghiệp lúc , hậu cần cao thủ là Bùi Tịch .)\nTống triều , Triệu Phổ .\nMinh triều , Lý Thiện dài .\nCho nên , những thứ này các triều đại đổi thay công lao xếp hạng , đã trọn vẹn nói rõ , ở trong mắt hoàng đế , đến cùng công lao của người nào lớn nhất .\nHơn nữa , cũng là lúc đó tất cả mọi người công nhận công lao lớn nhất .\n“ A , Hàn Tín cũng không dám nói công lao của mình so Tiêu Hà còn lớn ...”\nLưu Bang nghe xong Lý Ân Phàm lời nói , cũng là có một chút bất đắc dĩ .\nNói thật , tại Lưu Bang xem ra , thống soái mặc dù khó tìm , nhưng khó khăn nhất tìm kiếm , là chân chính hiểu hậu cần người .\n“ Nếu như một lần nữa trở lại cuối Tần , để cho ta tại Tiêu Hà cùng Hàn Tín trong hai người , chỉ có thể lựa chọn một người .”\n“ Ta chỉ biết không chút nào do dự lựa chọn Tiêu Hà .”\n“ Dù sao , có hậu cần , mới có tiền tuyến thống soái phát huy , đây là mãi mãi cũng không cách nào thay đổi .”\nTại cuối Tần , không có Tiêu Hà quản lý hậu phương lớn , hơn nữa chuyển vận hậu cần .\nHàn Tín lại có thể đánh ? Cũng liền như vậy .\nHậu cần sập , đây mới thật sự là sập !\nMà cái này , kỳ thực cũng là lúc trước vì cái gì Lý Ân Phàm cho rằng , Tiêu Hà thủ hạ , nhất định là trước kia thống nhất Lục quốc những người kia nguyên nhân .\nLưu Bang xuất quan bên trong sau đó , hậu cần rõ ràng là không bình thường , không phải loại kia các triều đại đổi thay khai quốc bình thường trổ mã hậu cần .\nHậu cần lập tức liền đột nhiên tăng mạnh , vậy mà có thể trong thời gian thật ngắn ủng hộ hắn quét ngang thiên hạ .\nTừ Lưu Bang hậu cần , chúng ta đi xem 3 cái triều đại .\nĐông Hán Lưu Tú , cuối thời Đông Hán Tam quốc , Minh triều ...\nCái này 3 cái là đại biểu lớn nhất tính chất .\nBởi vì bọn họ là từng bước một đánh xuống thổ địa , chậm rãi phát triển , hậu cần từng bước đề thăng .\nĐặc biệt là cuối thời Đông Hán Tam quốc , nhìn cuối thời Đông Hán Tam quốc lịch sử phát triển , lại đi nhìn lại cuối Tần , đều biết sau khi phát hiện chuyên cần rõ ràng không bình thường .\nMột cái bình thường thế lực , lịch sử phát triển là dạng gì ? Tam quốc cực kỳ có đại biểu tính chất .\nMà Lưu Bang đâu ? Ra Hán Trung liền quét ngang thiên hạ !\nCái này có thể là một cái bình thường thế lực lịch sử phát triển sao ?\n......', 'output\\mp3\\Màn Trời Quyền Lực Diễn Biến Cùng Truyền Thừa\\0080_Thứ 80 chương Đại quản gia.mp3', '2026-09-01T23:29:33.179369+00:00', 'completed', 'completed', 7502, 7502),
	(86, 7, '7652701137312678424', 81, 'Thứ 81 chương Đỉnh phong cực hạn hậu cần', 'Thứ chương Đỉnh phong cực hạn hậu cần\nHiện đại thời không .\n“ Mà nói đến Hán Vũ Đế Lưu Triệt năng lực quân sự .”\n“ Hậu cần mới là hắn cuối cùng thể hiện ...”\nNói đến đây , Lý Ân Phàm dừng một chút , tổ chức lần nữa rồi một lần ngôn ngữ .\n“ Cứ như vậy nói đi , quý ca , trong mắt của ta , các triều đại đổi thay , hậu cần năng lực lợi hại nhất là ai ?”\n“ Không phải Tiêu Hà , không phải Đông Hán thời kỳ Tuân Úc , Tam quốc Gia Cát Lượng , Tống triều Triệu Phổ , cùng với về sau Minh triều Lý Thiện dài ...”\n“ Các triều đại đổi thay , hậu cần năng lực lợi hại nhất , chính là Hán Vũ Đế Lưu Triệt !”\n“ Ở trong đó , là bao gồm vô số đại thần !”\n“ Theo lý thuyết , tại vô số hoàng đế , cùng với vô số đại thần bên trong , Hán Vũ Đế Lưu Triệt hậu cần năng lực , trong mắt của ta , cũng là lợi hại nhất !”\nHiện đại rất nhiều người thật sự không biết Hán Vũ Đế Lưu Triệt hậu cần năng lực chỗ đáng sợ .\nNói một cái rất khủng bố sự thật .\nỞ trước công nguyên , cũng chính là Hán Vũ Đế Lưu Triệt thời kì .\nVào lúc đó , Hán Vũ Đế Lưu Triệt , liền đã trắc ra một cái vương triều , có thể khống chế cực hạn thổ địa .\nCực hạn này là thế nào trắc ra ? Hậu cần có thể đến tới cực hạn !\nSau đó các triều đại đổi thay , không có bất kỳ cái gì một cái vương triều , có thể vượt qua cực hạn này .\nĐằng sau vương triều , tiền tuyến đến địa phương , đều không có Hán Vũ Đế Lưu Triệt thời kì , hậu cần có thể đến tới xa .\nCũng chính là sau khi Lý Ân Phàm giải được sự thật này , mới thật sự hiểu rõ Hán Vũ Đế Lưu Triệt hậu cần năng lực kinh khủng đến cỡ nào .\nỞ thời kỳ đó , hắn liền đã trắc ra một cái đại nhất thống trung ương tập quyền vương triều , có thể khống chế cực hạn thổ địa .\nSau này vương triều , bất kể thế nào đánh , hướng bắc đánh , hướng nam đánh , hay là về phía tây đánh .\nBọn hắn đều tại Hán Vũ Đế Lưu Triệt dưới bóng mờ .\nPhía bắc , Hán Vũ Đế Lưu Triệt hậu cần , xa nhất đến điểm là Trí Nhan sơn ( Nay Mông Cổ quốc hàng yêu Sơn Nam chi ) ở dưới Triệu Tín Thành\nĐây vẫn chỉ là tính toán thống soái Vệ Thanh có khả năng đến xa nhất địa phương .\nKhông có tính toán Hoắc Khứ Bệnh !\nVì cái gì chỉ tính Vệ Thanh ? Bởi vì Vệ Thanh là Thống soái , chắc chắn là đi theo đại quân hành động , mà đại quân hành động , hậu cần là nhất định phải đi theo .\nMà phía tây đâu ?\nTây vực , tại Hán Vũ Đế Lưu Triệt thời kì , liền đã đả thông !\nCon đường tơ lụa , cũng chính là vào lúc đó bắt đầu xuất hiện .\nNam chinh xa nhất đến nay Việt Nam trung bộ Hoành Sơn khu vực Cổ gọi Ngày nam quận đồng thời từng ngắn ngủi khống chế Đảo Hải Nam\nCho nên , đây chính là vì cái gì Lý Ân Phàm biết nói , Hán Vũ Đế Lưu Triệt thời kì , liền đã trắc ra một cái đại thống nhất trung ương tập quyền vương triều , có thể khống chế lãnh thổ cực hạn .\nĐây chính là Hán Vũ Đế Lưu Triệt lưu lại di trạch .\nCái này di trạch , có thể nói ân huệ mấy ngàn năm !\nĐể cho sau này vương triều , cũng chính là từ đây đều biết cực hạn là chỗ nào .\nTới nơi nào , hậu cần liền muốn bắt đầu gấp bội ?\nVà tới nơi nào , nhất định phải bắt đầu phòng thủ các loại ...\nMà nói đến cái này , liền muốn nói một chút , vì cái gì chúng ta nói trở lại Hán Đường ?\nHán Đường , Hán Đường ...\nBởi vì sau này vương triều , chỉ có thời kỳ đỉnh phong Đường triều , có thể cùng Hán triều so .\nThực tế khống chế diện tích thổ địa , cũng chỉ có Đường triều , là thời gian ngắn vượt qua Hán triều .\nChú ý , ở đây nói là thực tế khống chế diện tích thổ địa .\nSau này vì cái gì sập bàn ? Trong đó nguyên nhân lớn nhất một trong , chính là hậu cần .\nMà cái này hậu cần , tại Hán Vũ Đế Lưu Triệt thời kì , liền đã trắc đi ra .\nMà trong đó kinh khủng nhất một điểm ở chỗ , sau này một hai ngàn năm phát triển , vậy mà vẫn không có vượt qua Hán Vũ Đế Lưu Triệt thời kỳ cực hạn .\nCái này cũng là Lý Ân Phàm nhìn lịch sử lúc , cảm thấy đặc biệt khoa trương một điểm .\nThật sự không có một cái nào vương triều , có thể vượt qua Hán Vũ Đế thời kì đạt tới cực hạn !\n“ Ngoại trừ điểm này , Hán Vũ Đế Lưu Triệt , còn trắc ra một vật , để cho đời sau vương triều di trạch vô số năm .”\nLưu Bang lúc này nghe vô cùng nghiêm túc .\n“ Một cái vương triều , ở trên quân sự , bị nghiền ép đến trình độ nào , mới tính tới đạt cực hạn ?”\n“ Hán Vũ Đế Lưu Triệt , một cái chân chính toàn bộ hình thái Đế Vương , quyền hạn lớn nhất Đế Vương , ở thời kỳ đó , đã trắc đi ra .”\n“ Cái này cũng là ta vì sao lại nói , các triều đại đổi thay , Hán Vũ Đế Lưu Triệt mới là hậu cần xếp hạng thứ nhất đỉnh phong .”\n“ Bởi vì hắn là duy nhất biết cái gì gọi : Cử quốc chi lực .”\nĐiểm này quả thật có chút Địa Ngục chê cười ý tứ .\nNhưng Lý Ân Phàm nói lại vô cùng nghiêm túc , bởi vì Hán Vũ Đế Lưu Triệt đúng là chân chính biết cái gì gọi : Cử quốc chi lực .\nCái gì là cử quốc chi lực ? Như thế nào mới xem như cử quốc chi lực ?\nHán Vũ Đế Lưu Triệt liền nói cho hậu thế vô số người , đây mới gọi là cử quốc chi lực !\nHán Vũ Đế Lưu Triệt , thật sự đem hậu cần nghiền ép đến cực hạn .\nBằng không thì , trắc đi ra ngoài lãnh thổ cực hạn , là thế nào trắc đi ra ngoài ?\nĐương nhiên là Hán Vũ Đế Lưu Triệt , nghiền ép hậu cần , tích tụ ra tới !\nMà từ một điểm này đi xem , sau này vương triều bên trong , chỉ có miễn cưỡng mấy người có thể cùng hắn so sánh .\nMột người trong đó , đại gia hẳn là rất quen thuộc .\nChính là Gia Cát Lượng !\nCái này cũng là hậu thế vương triều vì cái gì vô cùng khao khát “ Gia Cát Lượng ” Nguyên nhân một trong .\nKhông chỉ là Gia Cát Lượng đến chết cũng là trung thần .\nCàng bởi vì Gia Cát Lượng là chân chính hiểu hậu cần , cũng hiểu nội chính , hơn nữa cũng hiểu quân sự lịch sử đỉnh phong nhân tài .\nDạng này người , trong lịch sử thật là quá quá ít .\nHiểu quân sự , không hiểu hậu cần , không hiểu nội chính .\nMà hiểu hậu cần , không hiểu tiền tuyến quân sự .\nHiểu nội chính , không hiểu hậu cần , không hiểu quân sự .\nCó thể hoàn toàn hiểu hậu cần , cũng hiểu như thế nào trong sự quản lý chính , như thế nào để cho cực hạn nhân khẩu , nghiền ép ra cực hạn hậu cần ...\nDạng này người , trong lịch sử thật sự không có mấy cái .\nHán Vũ Đế Lưu Triệt , là xếp hạng thứ nhất hậu cần cao thủ .\nMà Gia Cát Lượng , chính là xếp hàng thứ hai .\nTrong lịch sử có rất ít người có thể cùng bọn hắn so sánh .\nVì cái gì rất khó cùng bọn hắn so sánh ? Bởi vì tại cổ đại , có thể sử dụng cực hạn nhân khẩu , nghiền ép ra cực hạn hậu cần , còn không cho hậu phương sụp đổ , có thể làm được điểm này rất khó .\nTrừ cái đó ra đâu ? Còn làm trên trên dưới phía dưới “ Cam tâm tình nguyện ” Bị nghiền ép .\nĐây chính là bên trong chính hòa hậu cần năng lực đỉnh phong kết hợp .\nChỉ riêng Hán Vũ Đế Lưu Triệt chuyện phát sinh sau đó , còn có Gia Cát Lượng bắc phạt trong lúc đó chuyện phát sinh , hậu phương không có sụp đổ .\nNày liền đã hoàn toàn nói rõ sự lợi hại của bọn hắn chỗ .\nHán Vũ Đế Lưu Triệt , thật sự từ trên xuống dưới , từ dưới lên trên , trong trong ngoài ngoài , đều tại dùng sức nghiền ép ra hậu cần .\nNgay cả mình thân nhân , tất cả cũng không có buông tha !\nĐó là thật bắt lấy con ruồi , đều phải túa ra một điểm chất béo .\nCứ như vậy hậu cần năng lực , Lý Ân Phàm lúc đó nhìn đoạn thời điểm lịch sử này , thật là vô cùng bội phục .\nHậu thế thật sự không có một người có thể cùng Hán Vũ Đế Lưu Triệt so sánh với .\nMột cái toàn bộ hình thái Đế Vương , một cái không có bất luận cái gì cản tay Đế Vương , một cái trong lịch sử quyền hạn lớn nhất Đế Vương .\nTự mình hạ tràng làm hậu cần ...\nNói thật , Lý Ân Phàm thật sự không biết hậu thế ai có thể so sánh với hắn .\nHậu thế vô số Đế Vương , hoặc nhiều hoặc ít đều biết chịu đến một điểm cản tay .\nMà đại thần đâu ? Chỉ có thể tại trong có hạn tài nguyên , vắt hết óc suy xét như thế nào nghiền ép ra hậu cần .\nLiền cái này ? Hậu cần bên trong đều vẫn còn vô số âm u .\nMà tại Hán Vũ Đế Lưu Triệt thời kì ?\nChân chính đỉnh phong cực hạn hậu cần !\n......', 'output\\mp3\\Màn Trời Quyền Lực Diễn Biến Cùng Truyền Thừa\\0081_Thứ 81 chương Đỉnh phong cực hạn hậu cần.mp3', '2026-09-01T23:46:00.641664+00:00', 'completed', 'completed', 7724, 7724),
	(87, 7, '7652797330646647320', 82, 'Thứ 82 chương Cử quốc chi lực', 'Thứ chương Cử quốc chi lực\nHiện đại thời không .\n“ Nói thật , cũng chính là Hán Vũ Đế Lưu Triệt làm hết thảy , để cho ta đã biết cái gì gọi là “ Cử quốc chi lực ”.”\nCử quốc chi lực , bốn chữ này nói thật , là phi thường trừu tượng một cái khái niệm .\nCó nhiều trừu tượng ? Rất nhiều người cho là trong lịch sử rất nhiều vương triều , bọn hắn đối ngoại chiến tranh thời điểm , cũng đã là “ Cử quốc chi lực ”.\nNhưng kỳ thực trong lịch sử , Vô Số Vương Triều , vô số hoàng đế , vô số đại thần , bọn hắn kỳ thực cũng không có làm đến chân chính “ Cử quốc chi lực ”.\nTại Lý Ân Phàm xem ra , trong lịch sử , chỉ có hai cái thời kì , là chân chính làm được “ Cử quốc chi lực ”.\nThứ nhất thời kì , chính là Hán Vũ Đế Lưu Triệt , hắn vị trí thời kì .\nTừ trên xuống dưới , trong trong ngoài ngoài , vô luận giai cấp , vô luận giàu nghèo , tất cả mọi người đều tại Hán Vũ Đế Lưu Triệt uy hiếp phía dưới , vì đối ngoại chiến tranh làm “ Cống hiến ”.\nĐương nhiên , cái này “ Cống hiến ” Khẳng định có rất nhiều người là không tình nguyện .\nNhưng dù nói thế nào , cũng đúng là làm ra cống hiến , vô luận là có hay không nguyện ý .\nCái kia thứ hai cái thời kì đâu ?\nChính là Hán Vũ Đế Lưu Triệt hai ngàn năm sau đó , cũng chính là năm sáu mươi năm trước đây đoạn thời kỳ kia .\nThời kỳ đó , rất nhiều xây dựng , vì phòng bị phương bắc , cũng chân chính làm được “ Cử quốc chi lực ”.\nTrừ cái đó ra , nhìn chung các triều đại đổi thay , không có bất kỳ cái gì một cái vương triều , là chân chính làm được “ Cử quốc chi lực ”.\nCó chút chỉ nghiền ép tầng dưới chót , tỉ như nói về sau Tống triều , Minh triều .\nNghiên cứu cẩn thận cái này hai đoạn lịch sử , kỳ thực tất cả mọi người sẽ phát hiện , tại cái này hai đoạn thời kỳ lịch sử , là không có cái gọi là “ Đặc quyền giai cấp ” Tồn tại .\nLúc đó Hán Vũ Đế thời kì , mặc dù trên danh nghĩa là tồn tại cái gọi là “ Đặc quyền giai cấp ”.\nCó thể nói thật sự , lúc đó ngoại trừ Hán Vũ Đế Lưu Triệt , hắn cái này một cái “ Đặc quyền ”, những người khác ? Cũng là bị Hán Vũ Đế Lưu Triệt nghiền ép đối tượng .\nMà chúng ta lại đi nhìn khác vương triều lịch sử .\nCuối thời Đông Hán , vì cái gì độc Hán lấy mạnh vong ? Nhìn kỹ Tam quốc riêng phần mình sau lưng là ai liền biết .\nTùy triều thì càng không cần nói .\nĐường triều , “ Thế gia ”, “ Phiên trấn ” chờ đã , để cho vốn là cường thịnh Đường triều , chặn ngang mà đoạn .\nTống triều , chính là đám kia người có học thức .\nMinh triều đâu ? Huân quý , tôn thất , người có học thức ....\nCho nên từ nơi này đi xem , rất nhiều vương triều , bằng vào chúng ta thị giác hiện tại trở về mong những cái kia lịch sử , đều cảm thấy giống như bọn hắn đúng là làm được “ Cử quốc chi lực ”.\nNhưng trên thực tế ? Căn bản không có !\nChỉ có Hán Vũ Đế Lưu Triệt thời kì cùng năm mươi, sáu mươi năm trước đoạn thời kỳ kia , biểu diễn cái gì gọi là “ Cử quốc chi lực ”.\nCũng chính là cẩn thận nghiên cứu cái này hai đoạn thời kì , để cho Lý Ân Phàm phát hiện một sự thật .\nCó lẽ không thể nói sự thật , phải nói là quy luật ?\nHán Vũ Đế thời kì , cùng năm mươi, sáu mươi năm trước đoạn thời kỳ kia , lúc này chúng ta biết , bọn hắn là chân chính làm đến “ Cử quốc chi lực ” Thời kì .\nMà cái này hai đoạn thời kì , bọn hắn có cái gì chỗ giống nhau sao ?\nLà có !\nCẩn thận suy nghĩ một chút , kỳ thực không khó phát hiện chỗ giống nhau .\nCái này chỗ giống nhau là cái gì đây ?\nTư tưởng biến đổi !\nTrong lịch sử quyền hạn khổng lồ hoàng đế là có ! Nhưng vì cái gì đều không thể đạt đến Hán Vũ Đế Lưu Triệt thời kì , quyền hạn đạt tới độ cao ?\nBởi vì bọn hắn bản thân liền bị vô hình cản tay trói buộc lại .\nTư tưởng vững vàng trói buộc hắn nhóm !\nMà muốn đạt đến Hán Vũ Đế Lưu Triệt hắn cái kia thời điểm quyền hạn đạt tới độ cao , vậy thì nhất định phải phá vỡ tư tưởng này gò bó .\nHán Vũ Đế Lưu Triệt , là đại thế phía dưới thúc đẩy sinh trưởng một cái Đế Vương , tại hắn lúc ấy , cũ tư tưởng đã không đúng lúc , mới tư tưởng chuyện đương nhiên xuất hiện .\nMà năm sáu mươi năm trước thì sao ? Lão sư hắn là chân chính phá vỡ tư tưởng trói buộc người .\nTrong lịch sử vô số người dẫn đầu , cũng chỉ có hắn làm được , cũng thấy rõ ràng điểm này .\nPhá vỡ tư tưởng gò bó !\nMà hắn , đồng thời cũng nhìn thấy , gò bó tại tất cả tầng dưới chót trên người gò bó , cũng liền chính là cái này một cỗ gò bó .\nCho nên , chúng ta lại đi nhìn Hán Vũ Đế Lưu Triệt cùng lão sư từ một điểm này chỗ giống nhau .\nCũng là tư tưởng biến đổi , thanh trừ có từ lâu tư tưởng , tiếp đó , dạy học mới tư tưởng .\n“ Cái này cũng là vì cái gì ta phía trước nói , đây là Hán Vũ Đế Lưu Triệt một cái Đại Công Tích .”\n“ Cái này một Đại Công Tích , nói thật , trong lịch sử vô số Đế Vương , cũng rất khó so ra mà vượt hắn .”\n“ Bởi vì đây là chân chính bên trên tư tưởng biến đổi ...”\nMặc dù bây giờ vô số người lên án Hán Vũ Đế lúc đó làm ra tư tưởng biến đổi .\nLý Ân Phàm rất sớm phía trước , cũng đồng dạng tại lên án .\nNhưng về sau , hắn liền bỗng nhiên nghĩ tới một chuyện , mấy trăm năm sau đó , sẽ có hay không có người lên án lão sư ?\nKhông cần mấy trăm năm sau đó , kỳ thực hiện tại liền có !\nCho nên , cũng chính là vào lúc đó , để cho Lý Ân Phàm ý thức được .\nNgươi không thể dùng bây giờ tư tưởng cùng góc nhìn , đi xem ngay lúc đó lịch sử khó khăn .\nHán Vũ Đế Lưu Triệt lúc đó làm ra tư tưởng biến đổi , so sánh Tiên Tần cùng với lúc trước hắn lịch sử .\nKỳ thực là “ Tiên tiến ”.\nMà Hán Vũ Đế Lưu Triệt đâu ? Hắn đã hoàn mỹ hoàn thành lịch sử giao phó hắn sứ mệnh .\nHơn nữa còn hoàn thành tốt hơn .\nVề sau Đế Vương , không có hắn cái chủng loại kia đại phách lực đi biến đổi tư tưởng , cái này không thể trách nguồn cội Hán Vũ Đế Lưu Triệt làm không đúng .\nThích hợp làm lúc tư tưởng , có lẽ cũng không thích hợp về sau tư tưởng .\nMà cũng chính là từ tư tưởng một góc độ này đi đối đãi lịch sử , để cho Lý Ân Phàm ý thức được , trong lịch sử thật sự rất khó có Đế Vương có thể ở phương diện này sánh vai Hán Vũ Đế Lưu Triệt .\nCó thể miễn cưỡng chạm tới hắn , chỉ có ai ?\nRất nhiều người có thể sẽ nghĩ , có phải hay không Tùy Văn Đế Dương Kiên ? Đường Thái Tông Lý Thế Dân ? Minh Thái tổ Chu Nguyên Chương ?\nKỳ thực đều không phải là .\nNgười này , là Tống Thái Tổ Triệu Khuông Dận !\nVì cái gì Lý Ân Phàm biết nói Tống Thái Tổ Triệu Khuông Dận mới miễn cưỡng sánh vai Hán Vũ Đế Lưu Triệt ?\nBởi vì Tống Thái Tổ Triệu Khuông Dận , là đem một cái cực độ rung chuyển , tư tưởng hỗn loạn Trung Nguyên đại địa một lần nữa lôi trở lại quỹ đạo .\nCho nên , tại Lý Ân Phàm xem ra , cũng chỉ có Tống Thái Tổ Triệu Khuông Dận , có thể miễn cưỡng sánh vai Hán Vũ Đế Lưu Triệt .\nNhững thứ khác hoàng đế ? Cơ hồ không có một người , về mặt tư tưởng làm qua văn chương .\nCó lẽ là không dám , lại có lẽ là lười nhác làm , ngược lại trong lịch sử những thứ khác Đế Vương , cơ hồ cũng không có ở bên trên tư tưởng làm qua văn chương .\nCho dù là một trăm năm trước đầu trọc .\nVậy mà đều vẫn là Quân Quân Thần Thần phụ phụ tử tử một bộ kia !\nNếu như là hai trăm năm trước , hắn có lẽ còn có thể thành công , nhưng khi đó một trăm năm trước , đồng dạng cực độ rung chuyển , tư tưởng hỗn loạn một trăm năm trước !\nTừ một góc độ này đi xem , thất bại cũng liền không thể tránh được .\n......', 'output\\mp3\\Màn Trời Quyền Lực Diễn Biến Cùng Truyền Thừa\\0082_Thứ 82 chương Cử quốc chi lực.mp3', '2026-09-01T23:46:05.557714+00:00', 'completed', 'completed', 7125, 7125),
	(88, 7, '7652799825724850712', 83, 'Thứ 83 chương Khoảng không cửa sổ kỳ', 'Thứ Chương Không Song kỳ\nHiện đại thời không .\n“ Kỳ thực cái này cũng là ta cảm thấy vô cùng tiếc nuối một cái điểm .”\n“ Bởi vì trong mắt của ta , trong lịch sử chân chính đại cải cách , chỉ có 3 cái thời kì .”\n“ Mà cũng chính là cái này 3 cái thời kì , đều xúc động bên trên tư tưởng biến đổi .”\nLý Ân Phàm cầm lấy vừa rồi tiếp viên hàng không đưa tới tấm thảm đặt ở trên người mình .\n“ Thứ nhất thời kì , chính là Hán Vũ Đế Lưu Triệt thời kỳ đó .”\n“ Có từ lâu “ Quý tộc thể hệ ” Bị quý ca ngươi , còn có về sau mấy vị Đế Vương toàn bộ đánh nát .”\n“ Tân sinh giai cấp còn chưa có xuất hiện , đế vương quyền hạn chính là lớn nhất thời điểm .”\n“ Hán Vũ Đế Lưu Triệt , hắn cũng phát hiện thời kỳ này trống không , cho nên làm ra bên trên tư tưởng cực lớn biến đổi .”\n“ Thứ hai cái thời kì đâu ? Trong mắt của ta , chính là một trăm năm trước .”\n“ Có từ lâu giai cấp bị toàn bộ đánh nát , còn sót lại đều chạy ra ngoài .”\n“ Phiến đại địa này phía trên , tân sinh giai cấp đồng dạng không tồn tại , mà lão sư , hắn cũng nhìn thấy cái này một cái hoàn mỹ thời kì .”\nNói đến đây , Lý Ân Phàm thở dài một hơi , sau đó chậm rãi nói :\n“ Mà cái thứ ba thời kì , kỳ thực chính là Ngũ Đại Thập Quốc , Tống triều vừa lập đoạn thời kỳ kia .”\n“ Ngũ Đại Thập Quốc thời kì là lịch sử một cái trọng yếu bước ngoặt , thời kỳ này tất cả giai cấp đều xảy ra sụp đổ .”\n“ Theo lý mà nói , thời kỳ này , chắc cũng sẽ thúc đẩy sinh trưởng ra mới tư tưởng biến đổi .”\nLý Ân Phàm nói đến đây thời điểm , nhíu nhíu mày .\n“ Về sau ta cũng ý thức được điểm này , nghi hoặc vì cái gì Ngũ Đại Thập Quốc sau đó , vì cái gì chưa từng xuất hiện mới tư tưởng biến đổi ?”\n“ Lúc đó tất cả giai cấp đều hỏng mất , có từ lâu toàn bộ bị đánh nát , tân sinh còn không có xuất hiện .”\n“ Tiếp đó , ta liền đem cái này ba đoạn thời kì , đặt chung một chỗ tương đối .”\nCũng chính là sự so sánh này so sánh , để cho Lý Ân Phàm vô cùng uể oải phát hiện , tuy nói Ngũ Đại Thập Quốc phá hủy tất cả giai cấp .\nNhưng tại Ngũ Đại Thập Quốc thời kì , liền đã xuất hiện mới giai cấp .\nCái này giai cấp , chính là thời gian vô cùng ngắn ngủi , quân nhân giai cấp !\nQuân nhân chấp chính cùng hắn dưới sự thống trị ý thức xã hội trở ngại tư tưởng cùng văn hóa phát triển , cũng liền không cách nào xuất hiện tư tưởng văn hóa giải phóng .\nHơn nữa , còn có một cái mấu chốt nhất , cũng là Lý Ân Phàm về sau phát hiện .\nHán Vũ Đế Lưu Triệt , hắn làm ra tư tưởng biến đổi phía trước , là lúc nào ? Là Tiên Tần !\nThời kỳ đó , bên trên tư tưởng trăm nhà đua tiếng .\nMà lão sư đâu ? Hắn làm ra tư tưởng biến đổi phía trước , Trung Nguyên đại địa bên trên xảy ra chuyện gì ? Cũng tương tự có thể nói , bên trên tư tưởng “ Trăm nhà đua tiếng ”.\nCó từ lâu , ngoại lai , tân sinh , toàn bộ đều ở đây vùng đất bên trên tranh luận tranh chấp ...\nMà Ngũ Đại Thập Quốc đâu ?\nLý Ân Phàm lúc đó vô cùng uể oải phát hiện ...\nKhông có !\nĐúng vậy , Ngũ Đại Thập Quốc phía trước , cùng với Ngũ Đại Thập Quốc , cũng không có xuất hiện bên trên tư tưởng “ Trăm nhà đua tiếng ”.\nMà không có xuất hiện , làm sao có thể thúc đẩy sinh trưởng ra về sau tư tưởng đại cải cách đâu ?\nTống Thái Tổ Triệu Khuông Dận không hề nghi ngờ , là một cái đại phách lực Đế Vương .\nTừ hắn quyết tâm kết thúc Ngũ Đại Thập Quốc liền có thể nhìn ra , hắn cũng chính xác nghĩ có đại hành động .\nNhưng không có xuất hiện “ Trăm nhà đua tiếng ”, để cho Triệu Khuông Dận chỉ có thể một lần nữa nhặt về có từ lâu tư tưởng .\nBằng không thì còn có thể làm sao đâu ?\nCũng chính là thấy được điểm này , thật sự để cho Lý Ân Phàm cảm thấy vô cùng đáng tiếc .\nNếu như Ngũ Đại Thập Quốc , hay là trước đây thời kì , xuất hiện “ Trăm nhà đua tiếng ”, cái kia Triệu Khuông Dận thật sự có thể để cho Đại Tống tiến thêm một bước .\nÔm mới tư tưởng , bỏ đi cũ tư tưởng .\nNhưng cuối cùng , “ Trăm nhà đua tiếng ” Vẫn là không có xuất hiện ...\nMà Tống Thái Tổ Triệu Khuông Dận , tại Lý Ân Phàm xem ra , thật sự làm rất tốt .\nCó lẽ nói , thật sự làm rất nhiều hoàn mỹ .\nCó thể kết thúc như thế thời kì , thật không phải là ai cũng có thể hoàn thành .\nCũng không cách nào đi khiển trách nặng nề Triệu Khuông Dận vì cái gì không làm ra thay đổi .\nChỉ có thể nói , vốn nên xuất hiện , chưa từng xuất hiện , để cho Tống Thái Tổ Triệu Khuông Dận , chính xác không có cách nào làm ra thay đổi .\nCái này có lẽ cũng là đại thế phía dưới kết quả tất nhiên a .\nVề sau Lý Ân Phàm tử mảnh nghiên cứu vì cái gì chưa từng xuất hiện dạng này tư tưởng biến đổi lúc .\nĐúng là phát hiện vấn đề .\nĐường triều sơ kỳ , văn hóa kỳ thực là vô cùng phồn vinh , nhưng càng ngày càng đề cao võ nhân địa vị , để cho văn nhân kéo dài bị chèn ép .\nLoạn An Sử sau , võ nhân địa vị triệt để vượt qua văn nhân .\nTại sau đó , ăn bữa hôm nay lo bữa ngày mai thời kỳ , còn thế nào đi tư tưởng biến đổi đâu ?\nThảo luận ? Cũng không có địa phương thảo luận ....\nTiên Tần thời kỳ xuân thu cùng chiến quốc , mặc dù hỗn loạn , nhưng ít ra duy trì nhất định “ Trật tự ”.\nThời điểm đó người có học thức , bọn hắn là có thể , cũng có chỗ đi thảo luận , tranh luận , hay là nghiên cứu tư tưởng .\nDân quốc thời kì , cũng giống như thế !\nMặc dù Trung Nguyên đại địa hỗn loạn tưng bừng , nhưng cuối cùng vẫn là có dạng này hoặc dạng kia một mảnh Tịnh Thổ , có thể để cho bọn hắn đi tranh luận .\nNhưng Ngũ Đại Thập Quốc ?\nCũng chính là cẩn thận nghiên cứu qua cái này ba đoạn lịch sử Lý Ân Phàm phát hiện .\nNgũ Đại Thập Quốc , mặc dù triệt để đánh nát có từ lâu giai cấp .\nNhưng quá mức hỗn loạn .\nHỗn loạn đến , tất cả mọi người đều trải qua ăn bữa hôm nay lo bữa ngày mai sinh hoạt .\nThiên hạ chi đại , thật sự rất khó có một mảnh Tịnh Thổ .\nCho nên , tại Lý Ân Phàm xem ra , một số thời khắc , bể quá mức triệt để , có lẽ thật không phải là một chuyện tốt .\nTriệt để hỗn loạn , là thúc đẩy sinh trưởng không ra mới tư tưởng .\n《 Mạnh Tử Cáo tử chương cú phía dưới Tiết 15: 》 bên trong có một câu nói .\nHiện đại vô số người hẳn là rất quen thuộc .\nNguyên nhân thiên tướng hàng đại mặc cho thế là người a , trước phải nhịn nổi khổ , mệt gân cốt , đói thể xác , không xu dính túi , đi phật loạn hắn làm .\nTổng kết tới nói , chính là : Gặp trắc trở là vì để nhân tính cách cứng cỏi , tăng trưởng tài cán , về sau có thể gánh chịu chức trách lớn .\nThế nhưng chỉ là nhất định gặp trắc trở mới được .\nMệt nhọc chết , chết đói , còn có thể rèn luyện ra cứng cỏi tính cách , để cho người ta tăng trưởng tài cán sao ?\nLà không được !\nĐồng dạng , chỉ có đến nhất định hỗn loạn , mới có thể thúc đẩy sinh trưởng ra mới tư tưởng , bỏ đi cũ tư tưởng .\n“ Kỳ thực , trước đó ta nghĩ tới một sự kiện , hoặc có lẽ là thôi diễn qua một sự kiện .”\n“ Triệu Khuông Dận nếu quả thật triệt để thống nhất mảnh đất này , có thể hay không thúc đẩy sinh trưởng ra mới tư tưởng ?”\nNgồi ở Lý Ân Phàm bên cạnh Lưu Bang không nói gì , chỉ là liếc nhìn trong tay sách sử , đối chiếu Lý Ân Phàm lời nói .\n“ Bởi vì trong mắt của ta , Tống Thái Tổ Triệu Khuông Dận nếu quả thật triệt để thống nhất , vậy hắn chiến công cùng quyền hạn , hẳn là có thể sánh được Hán Vũ Đế Lưu Triệt .”\n“ Lúc hắn cái kia , có từ lâu giai cấp bị toàn bộ đánh nát , tân sinh giai cấp , còn vô cùng yếu ớt .”\n“ Nhưng về sau ta bất đắc dĩ phát hiện .”\n“ Dù là Tống Thái Tổ Triệu Khuông Dận thật sự triệt để thống nhất , cũng không cách nào về mặt tư tưởng làm ra mới biến đổi .”\n“ Bởi vì mới tư tưởng , chưa từng xuất hiện ...”\n“ Chưa từng xuất hiện đồ vật , để cho Tống Thái Tổ Triệu Khuông Dận , như thế nào đi dùng cái này xem như cơ sở tiến hành biến đổi đâu ?”\n“ Không thể !”\nCũng chính là nhận rõ ràng điểm này , Lý Ân Phàm vô cùng tiếc nuối phát hiện , phiến đại địa này , cuối cùng bỏ lỡ một đoạn hoàn mỹ lịch sử Không Song Kỳ .\nQuãng lịch sử này Không Song Kỳ , thật sự hoàn mỹ .\nĐến nỗi nói về sau Minh triều hòa thanh triều ? Tại Lý Ân Phàm xem ra , thật sự rất khó thúc đẩy sinh trưởng ra mới tư tưởng .\nDù sao có từ lâu tư tưởng vẫn tồn tại , có từ lâu khổng lồ giai cấp đồng dạng tồn tại , coi như xuất hiện , cũng sẽ bị điên cuồng chèn ép .\nVương Dương Minh , chính là một cái rõ ràng dứt khoát ví dụ .\nTâm học , tại Minh triều trung hậu kỳ , thế nhưng là bị hạ lệnh phong làm cấm thư .\nTừ một điểm này đi xem , trong lịch sử thật sự cũng chỉ có Ngũ Đại Thập Quốc sau đó , một đoạn kia hoàn mỹ lịch sử Không Song Kỳ , để cho phiến đại địa này , đi tiếp thu mới tư tưởng .\n...', 'output\\mp3\\Màn Trời Quyền Lực Diễn Biến Cùng Truyền Thừa\\0083_Thứ 83 chương Khoảng không cửa sổ kỳ.mp3', '2026-09-01T23:46:10.084739+00:00', 'completed', 'completed', 8299, 8299),
	(89, 7, '7653252464983933464', 84, 'Thứ 84 chương Tư tưởng biến đổi', 'Thứ chương Tư tưởng biến đổi\nHiện đại thời không .\nĐúng vậy , cũng chính là một đoạn kia thời kỳ .\nTrong lịch sử phía dưới mấy ngàn năm , tư tưởng biến đổi , chỉ có hoàn mỹ như thế vài đoạn thời kì .\nĐoạn thứ nhất chính là Hán Vũ Đế Lưu Triệt thời kỳ đó , mà Hán Vũ Đế Lưu Triệt đâu ? Cũng đúng là hoàn mỹ làm được tư tưởng biến đổi .\nĐoạn thứ hai thời kì , chính là Ngũ Đại Thập Quốc sau đó cái kia ngắn ngủi thời kì .\nĐoạn thứ ba thời kì , chính là một trăm năm trước , một đoạn này thời kì , đồng dạng bị lão sư bén nhạy nhìn thấy , đồng thời làm được .\nLý Ân Phàm có đôi khi liền suy nghĩ , nếu như tại Ngũ Đại Thập Quốc thật sự xuất hiện “ Trăm nhà đua tiếng ”, sau cái kia quang cảnh , lại là dạng gì ?\nMảnh này Trung Nguyên đại địa , sau đó lại sẽ là như thế nào long trời lở đất ?\nCó thể nhìn thấy cái này , có người sẽ nhớ , vì cái gì Lý Ân Phàm sẽ như thế chắc chắn , Ngũ Đại Thập Quốc sau đó , Tống triều sơ kỳ đoạn thời gian kia , là tư tưởng biến đổi thời gian ?\nDựa vào cái gì như thế chắc chắn đâu ?\nKỳ thực Lý Ân Phàm thời gian rất sớm , là không biết .\nNhưng tại nghiên cứu Ngũ Đại Thập Quốc quãng lịch sử này thời điểm , đặc biệt là nghiên cứu Triệu Khuông Dận đem Trung Nguyên đại địa hỗn loạn tư tưởng kéo về quỹ đạo thời điểm , Lý Ân Phàm đem cái này 3 cái thời gian điểm viết xuống .\nHán Vũ Đế Lưu Triệt , vị trí thời gian là lúc nào ? Trước công nguyên năm Phía trước năm .\nTriệu Khuông Dận vị trí thời gian đâu năm năm .\nLão sư đâu năm năm .\nNhìn thấy cái này , có thể có người sẽ nhớ , đây là ý gì ? Nhìn thấy thời gian , sau đó thì sao ?\nTiếp đó ?\nĐem Hán Vũ Đế vị trí thời gian , tăng thêm một ngàn năm ...\nLại đem Triệu Khuông Dận vị trí thời gian , tăng thêm một ngàn năm ...\nCho nên , nhìn thấy không ?\nMà nhìn đến đây , liền khẳng định có người nghĩ , chỉ có cái này 3 cái thời gian , có phải hay không là một loại trùng hợp ?\nĐúng vậy , Lý Ân Phàm lúc đó cũng nghĩ đến điểm này , có phải là trùng hợp hay không ?\nCho nên , Lý Ân Phàm theo thời gian hướng phía trước đẩy ...\nHán Vũ Đế ra đời thời gian , trước công nguyên năm , giảm đi một ngàn năm .\nCũng chính là trước công nguyên năm , thời gian này là gì tình huống ?\nTư liệu lịch sử ghi chép một năm này thương vương Đế Ất Qua đời , con hắn Đế Tân Tức Thương Trụ vương ) kế vị .\nMà Thương Trụ Vương Đế Tân làm cái gì ?\nHiện đại đã có vô số tiểu thuyết còn có video ngắn đã giới thiệu qua .\nCũng làm cho Thương Trụ Vương Đế Tân phong bình bắt đầu từ từ thay đổi .\nCho nên , cũng chính là khi thấy thời gian này , để cho Lý Ân Phàm biết , Ngũ Đại Thập Quốc sau đó đoạn lịch sử kia , đến cùng đã mất đi cái gì .\nPhiến đại địa này , chân chính đã mất đi cái gì , bỏ lỡ cái gì !\nKhi đó chân chính , một ngàn năm một lần , hoàn mỹ thời gian cửa sổ !\nCũng là lịch sử đại thế phía dưới , cho hoàn mỹ tư tưởng biến đổi cơ hội .\nNhưng cuối cùng vẫn là bỏ lỡ .\nBỏ lỡ lần này ? Lần kế thời gian , chỉ có thể chờ đợi đến một ngàn năm sau !\nMà thời gian này , cũng liền vừa lúc là khoảng cách hiện đại một trăm năm trước .\nMột đoạn kia tại chúng ta hậu thế xem ra , tất cả giai cấp , toàn bộ sụp đổ , một lần nữa xào bài thời gian .\nMà may mắn chính là , thời gian này , lão sư chính xác bắt được .\nCũng chính là nghĩ tới điểm này , sau đó thời kỳ , Lý Ân Phàm một mực đang nghĩ một vấn đề .\nCái tư tưởng này biến đổi thời gian điểm , có phải thật vậy hay không một ngàn năm ?\nLà một ngàn năm , vẫn là hai ngàn năm ?\nBởi vì Lý Ân Phàm khi phát hiện cái thời điểm này , liền bắt đầu nghĩ một chuyện .\nChuyện gì ?\nThương Trụ Vương Đế Tân , hắn cuối cùng , chung quy là thất bại !\nMà Tống Thái Tổ Triệu Khuông Dận đâu ? Hắn tuy nói đem Trung Nguyên đại địa hỗn loạn tư tưởng một lần nữa lôi trở lại quỹ đạo .\nNhưng kỳ thực cũng coi như là thất bại .\nCũng chính là nghĩ tới cái này , Lý Ân Phàm lại bắt đầu đem thời gian hướng phía trước đẩy .\nTrước công nguyên năm , lại giảm đi một ngàn năm thời gian .\nThời gian này , cũng liền đến trước công nguyên năm .\nCái thời điểm này , là ai tại vị ? Chủ lưu tư liệu lịch sử ghi chép , trước công nguyên năm bình thường bị đưa về Hạ triều thời kỳ đầu hoặc truyền thuyết thời đại Hạ Hậu thị thống trị thời kì .\nNên năm thường cùng nổi tiếng Trọng Khang nhật thực Tương liên hệ , cổ tịch ghi chép lần này nhật thực phát sinh ở Hạ Đế Trọng khang trong năm , là trên thế giới cổ xưa nhất nhật thực ghi chép một trong .\nLúc này Hạ triều chính quyền còn không ổn định , Hậu Nghệ chờ Đông Di bộ tộc thế lực bắt đầu tham gia Trung Nguyên chính trị .\nThời gian này chuẩn xác mà nói , là đầu mùa hè .\nNếu như liền như vậy suy luận , cái thời điểm này tư tưởng biến đổi , hẳn là thành công .\nĐúng là thành công , bởi vì Hạ triều thiết lập , đến cùng chuyện gì xảy ra , chúng ta đều biết .\nTừ nhường ngôi chế đã biến thành thừa kế chế , độc chiếm thiên hạ bị chân chính xác lập .\nCũng chính là về sau , để cho Lý Ân Phàm bỗng nhiên ý thức được , cái tư tưởng này cực lớn biến đổi thời gian , không phải một ngàn năm .\nCó lẽ là hai ngàn năm !\nMà liền dùng cái này suy luận , lại hai ngàn năm trước thì sao ?\nTrước công nguyên năm , lại giảm đi hai ngàn năm , đã đến giờ trước công nguyên năm .\nĐoạn thời gian này là ai tại vị ? Truyền thuyết là Chuyên Húc đế .( Hẹn phía trước năm Phía trước năm , bây giờ chủ lưu lịch sử suy luận , ai tại vị , ai liền được xưng là Chuyên Húc .)\nMà Chuyên Húc đế làm cái gì ?\nCó thể có người nghĩ tới bốn chữ .\nTuyệt địa thiên thông !\nCái này đồng dạng cũng là một hồi cực lớn tư tưởng biến đổi .\nQuân quyền , triệt để vượt trên thần quyền .\nTừ đó về sau , quân vương mệnh lệnh triệt để thay thế “ Tế tự ” Đại biểu “ Thần ” Mệnh lệnh .\nTrận này cực lớn tư tưởng biến đổi , di trạch vô số năm !\nCó thể nói sau đó thời kì , lịch đại quân vương cùng với mỗi giai tầng , đều đang hưởng thụ cái này di trạch .\nCũng chính là suy đoán đến cái này , Lý Ân Phàm ngừng .\nBởi vì hắn chính xác phát hiện , phiến đại địa này phía trên , tư tưởng cực lớn biến đổi , hoàn mỹ lịch sử Không Song Kỳ .\nCó lẽ cũng không phải một ngàn năm , là hai ngàn năm .\nMỗi hai ngàn năm , sẽ xuất hiện một lần chân chính chạm đến linh hồn , một lần nữa thanh tẩy mỗi giai cấp cực lớn tư tưởng biến đổi .\nTừ Chuyên Húc đế đến đầu mùa hè , sau đó , thời gian đã đến Hán Vũ Đế thời kì .\nHán Vũ Đế thời kì lại hai ngàn năm sau đó .\nThời gian cũng liền vừa vặn đến đầu thế kỷ hai mươi .\n“ Nhường ngôi chế xác lập , hai ngàn năm sau đó , độc chiếm thiên hạ chế độ nô lệ xác lập sao ?”\n“ Độc chiếm thiên hạ chế độ nô lệ xác lập sau đó , một cái nữa hai ngàn năm , chính là đại nhất thống trung ương tập quyền ...”\nLý Ân Phàm nghĩ tới đây , tựa hồ phát hiện cái gì , cũng chính xác nhìn thấy cái gì .\n“ Thì ra lão sư hắn thật sự thấy được , hơn nữa một mực đang cố gắng làm .”\nMấy đoạn này lời nói , Lý Ân Phàm nói cực kỳ nhỏ giọng .\nBên cạnh Lưu Bang tựa hồ nghe được , nhưng nghe cực kỳ mơ hồ .\n......', 'output\\mp3\\Màn Trời Quyền Lực Diễn Biến Cùng Truyền Thừa\\0084_Thứ 84 chương Tư tưởng biến đổi.mp3', '2026-09-01T23:46:14.930157+00:00', 'completed', 'completed', 6798, 6798),
	(90, 7, '7653252624103244312', 85, 'Thứ 85 chương Hai ngàn năm', 'Thứ chương Hai ngàn năm\nHiện đại thời không .\n“ Tiên sinh ?”\nLưu Bang có chút nghi hoặc nhìn Lý Ân Phàm .\nNghi hoặc Lý Ân Phàm vì cái gì nói một chút liền ngừng , tiếp đó liền bắt đầu lẩm bẩm ?\n“ A ? Quý ca ...”\n“ Tiên sinh , ngươi thế nào ?”\n“ Không có việc gì , chỉ là đột nhiên cảm giác được chính mình vô cùng nhỏ bé ...”\nLý Ân Phàm thở dài một hơi , không hiểu đột nhiên cảm giác được cá nhân tại thời đại này dòng lũ phía dưới nhỏ bé hơi như hạt bụi ...\nNói thật , Lý Ân Phàm trước đó vẫn cho là , vương triều ba trăm năm số mệnh , mới là bên trên mảnh đất này chung cực đáp án .\nBởi vì phiến đại địa này phía trên , cũng đúng là không có vương triều có thể trốn mở ba trăm năm , cái này một phảng phất ma chú tầm thường con số .\nChu triều ? Nó trốn khỏi sao ?\nDường như là trốn khỏi , nhưng từ chân chính thực tế cùng thực tế đến xem , không có !\nXuân Thu Chiến Quốc thời kì , Chu triều liền đã chỉ còn trên danh nghĩa .\nHán triều đâu ? Hán triều tựa hồ cũng trốn khỏi .\nVừa vặn chỗ hiện đại chúng ta đây biết , Hán triều là phân Tây Hán cùng Đông Hán .\nTây Hán , là đã bị xác lập diệt vong .\nMà Đông Hán , là dùng cái này trên cơ sở thiết lập .\nĐường triều ? Loạn An Sử sau , Đường triều cũng đồng dạng chỉ còn trên danh nghĩa .\nTống triều dường như là trốn khỏi , hết thảy tồn tại năm .\nNhưng Tống triều như thế hình thái , tính được bên trên chân chính Đại Nhất Thống Vương Triều sao ? Là không tính là !\nHơn nữa ngoại địch cũng một mực tồn tại , Bắc Tống cũng bị phá diệt , triều đình chạy trốn tới Nam Tống kéo dài hơi tàn .\nNếu như kéo dài hơi tàn cũng coi như mà nói , cái kia Chu triều cũng cần phải tính toán .\nMinh triều cùng sau đó Thanh triều , cũng không cần nhìn , chúng ta đều biết , bọn hắn đồng dạng không có trốn qua ba trăm năm ma chú .\nCho nên , rất sớm phía trước , Lý Ân Phàm liền suy nghĩ , trên vùng đất này chung cực đáp án , thật là ba trăm năm ma chú sao ?\nVề sau , Lý Ân Phàm từ tư tưởng vào tay sau đó , mới bỗng nhiên phát hiện ...\nVương triều ba trăm năm ma chú , có lẽ kỳ thực chỉ là biểu tượng !\nĐây chẳng qua là tài nguyên tranh đoạt , hay là lợi ích phân phối , cùng với giai cấp mâu thuẫn triển lộ ra biểu tượng .\nTrên vùng đất này chung cực đáp án , kỳ thực hẳn là hai ngàn năm !\nMột cái vương triều lý luận cực hạn , chắc cũng là hai ngàn năm mới đúng ...\nTại sao là hai ngàn năm ?\nBởi vì , tư tưởng biến đổi cần hai ngàn năm , vậy tại sao vương triều lý luận tuổi thọ không phải hai ngàn năm đâu ?\nDù sao , cùng một cái lý luận tư tưởng , đều vừa vặn truyền thừa hai ngàn năm .\nNghĩ tới đây , xuyên thấu qua biểu tượng , Lý Ân Phàm xâm nhập suy xét .\nNếu như dứt bỏ biểu tượng bên trong xuất hiện hoàng đế , trên lý luận đi xem .\nTruyền thừa , không phải liền là cùng một cái đồ vật sao ?\nMỗi hai ngàn năm , đều đang đồn nhận đồng dạng một vật .\nVật này , chính là mỗi hai ngàn năm không đổi tư tưởng !!!\nCho nên , Lý Ân Phàm liền chợt phát hiện , có lẽ hai ngàn năm ma chú mới là đối , mà ba trăm năm kỳ thực là sai lầm .\nMa chú có lẽ là hai ngàn năm , mà cái gọi là ba trăm năm ma chú ? Cái này có lẽ chỉ là nhân loại chính mình muốn chết mà thôi .\nPhiến đại địa này , hoặc có lẽ là dưới chân thổ địa , cùng với lịch sử , bọn chúng cho tối Đại Ma Chú , kỳ thực là hai ngàn năm .\nNghĩ tới đây , Lý Ân Phàm khẽ gật đầu , cảm thấy ý nghĩ này có lẽ càng hẳn là sau khi trở về nghiêm túc suy tính một chút .\nNhưng đột nhiên , Lý Ân Phàm tựa hồ ý thức được cái gì , trên mặt lộ ra vẻ khiếp sợ .\nHệ thống ...】\nTa tại .】\nCho nên , ngươi , cùng với các ngươi người sau lưng , là hai ngàn năm sau đó ?】\nLý Ân Phàm trong đầu hệ thống trầm mặc rất lâu .\nĐúng vậy ...】\nNghe nói như thế , Lý Ân Phàm trên mặt lộ ra một bộ quả là thế thần sắc .\n‘ Thì ra thực sự là hai ngàn năm ...’\nKhông đúng , hệ thống , nếu thật là hai ngàn năm mà nói , hẳn là sẽ xuất hiện cực lớn tư tưởng biến đổi a ?】\nĐúng vậy , ngươi suy luận vô cùng chính xác , nếu như lấy bình thường kết luận tới dùng cái này suy đoán , chính xác sẽ xuất hiện cực lớn tư tưởng biến đổi .】\nnhưng tiền trí điều kiện đâu ?】\nTiền trí điều kiện đâu ?\nLý Ân Phàm nghĩ tới đây , đầu tiên là sững sờ , sau đó một chút liền nghĩ đến .\nNgươi nói là , “ Trăm nhà đua tiếng ”?】\nTrăm nhà đua tiếng ”? Đúng vậy , ngươi suy luận rất nhiều chính xác .】\nnhưng vốn nên xuất hiện “ Trăm nhà đua tiếng ”, chưa từng xuất hiện đâu ?】\nNghe được một câu nói kia , Lý Ân Phàm ngẩn người tại chỗ .\nHai ngàn năm sau đó , vốn nên xuất hiện “ Trăm nhà đua tiếng ”, chưa từng xuất hiện ?\nNếu như không có xuất hiện sẽ tạo thành gì tình huống ? Lý Ân Phàm không biết .\nNhưng hắn biết một cái phi thường khủng bố sự thật .\nHai ngàn năm sau đó hậu thế , bọn hắn lấy cử quốc chi lực chế tạo ra một cái “ Hệ thống ”, tới nhờ vào đó tìm kiếm đường ra .\nNhờ vào đó , đến tìm kiếm “ Tư tưởng đường ra ”.\nBọn hắn tình nguyện lấy “ Cử quốc chi lực ” Tới chế tạo một cái vật như vậy , tới xuyên qua thời không , xuyên qua hai ngàn năm .\nHậu thế , đều đến nơi này dạng tình cảnh sao ?】\nLý Ân Phàm yên lặng trong đầu hỏi đến hệ thống .\nĐúng vậy .】\n...\nHiện đại thời không .\nMột chỗ không biết tên đại sơn .\n“ Bên kia truyền tới tin tức , Lý Ân Phàm chẳng biết tại sao , suy đoán ra căn bản nhất sự thật .”\nMột vị lão nhân , cầm một phần báo cáo , hướng về phía bên cạnh một vị lão nhân nói .\n“ Ân ?”\n“ Người xuyên việt chính là như vậy không giảng đạo lý sao ?”\nNghe nói như vậy lão nhân , có chút ngây người , sau đó hiếu kỳ nói .\n“ Bên kia truyền tới tin tức , Lý Ân Phàm đang cấp Lưu Bang giảng giải Hán Vũ Đế Lưu Triệt tư tưởng đại công tích lúc , bỗng nhiên liền nghĩ đến .”\n“ Tư tưởng sao ? Vậy thì không kỳ quái ...”\n“ Hậu thế cái kia vấn đề căn bản nhất , vốn chính là tư tưởng ...”\nNói chuyện lão nhân , hơi xúc động .\n“ Ngươi nói , bọn hắn sẽ thành công sao ?”\nNghe nói như thế , lão nhân trầm mặc rất lâu .\n“ Sẽ thành công sao ? Không biết ...”\n“ Vốn nên xuất hiện “ Trăm nhà đua tiếng ”, chưa từng xuất hiện ...”\n“ Hậu thế , suy đoán vô số phương hướng , bọn hắn ngay cả người ngoài hành tinh phong tỏa , đều đã nghĩ đến , cũng đối này làm ra phản ứng ...”\n“ Nhưng vẫn là không phát hiện chút gì .”\nNghĩ tới đây , lão nhân cũng có chút không biết nên nói thế nào .\nBên kia truyền tới hình ảnh , bọn hắn cũng nhìn thấy , nói như thế nào đây ? Vô cùng phù hợp bọn hắn đối với thế giới khoa huyễn tưởng tượng .\nNhưng từ chỗ rất nhỏ , bọn hắn cũng phát hiện hậu thế đối mặt vấn đề .\nTừ trên xuống dưới , tất cả mọi người trong mắt , cũng đã chết lặng đã mất đi phương hướng ...\nKhoa học kỹ thuật thay đổi , khoa học kỹ thuật phát triển , quả thật có thể cường đại một quốc gia nhục thể .\nNhưng tư tưởng , mới thật sự là vũ trang nhục thể này đầu não .\nNếu như tư tưởng không bằng cái này cường đại nhục thể sẽ xuất hiện dạng gì tình huống ?\nHậu thế lấy “ Cử quốc chi lực ”, không tiếc bất cứ giá nào tạo ra được “ Hệ thống ”, liền đã cấp ra đáp án ...\nKỳ thực , không chỉ là hậu thế cấp ra đáp án .\nTrước mặt lịch sử , cũng cho ra đáp án .\n“ Ngươi nói , tiểu tử này có thể hay không ý thức được , hậu thế kỳ thực đang lợi dụng hắn ?”\nBỗng nhiên , một vị lão sư nhìn xem trên màn ảnh khổng lồ Lý Ân Phàm nói .\n“ Có thể hay không ý thức được ? Kỳ thực hắn đã sớm nghĩ tới .”\nÂn ?\nTra hỏi cái vị kia lão nhân có chút nghi hoặc nhìn hắn .\n“ Ngươi không có nhìn hắn rất nhiều thứ , đều nói vô cùng kỹ càng sao ?”\n“ Hắn kỳ thực đã biết , hệ thống mặt ngoài là để cho hắn mời hoàng đế đi tới hậu thế , hơn nữa trợ giúp những hoàng đế kia .”\n“ Nhưng hắn biết , chân chính trọng điểm , vẫn luôn là màn trời ...”\n“ Để cho các triều đại đổi thay , vô số người nhìn màn trời ...”\nNói đến đây , lão nhân quay người nhìn xem hắn , nói rất là nghiêm túc nói :\n“ Tiểu tử kia biết , mặt ngoài tới hậu thế học tập là những hoàng đế kia , cùng với mỗi cái triều đại mười người .”\n“ Nhưng chân chính học sinh ? Là trong lịch sử , những cái kia có thể nhìn đến màn trời vô số tầng dưới chót nhân dân ...”\n......', 'output\\mp3\\Màn Trời Quyền Lực Diễn Biến Cùng Truyền Thừa\\0085_Thứ 85 chương Hai ngàn năm.mp3', '2026-09-01T23:46:52.346236+00:00', 'completed', 'completed', 7874, 7874),
	(91, 7, '7653252705250460184', 86, 'Thứ 86 chương Thái Cực Đồ, Âm Dương Ngư', 'Thứ chương Thái Cực Đồ , Âm Dương Ngư\nHiện đại thời không .\nLý Ân Phàm bỗng nhiên lại nghĩ tới điều gì , cảm thấy hai ngàn năm có thể cũng là sai lầm .\nMặc dù liền như vậy có thể suy luận , lịch sử phía trên , mỗi hai ngàn năm đúng là thành công tiến hành tư tưởng biến đổi .\nHơn nữa , tại mỗi lần thành công tư tưởng biến đổi phía trước , đều sẽ có một lần “ Trăm nhà đua tiếng ”.\nCó thể , có thể xem nhẹ cái kia mỗi một ngàn năm thất bại tư tưởng biến đổi sao ?\nThương triều thời kì cuối Thương Trụ Vương Đế Tân .\nNgũ Đại Thập Quốc thời kì cuối , Tống Sơ Triệu Khuông Dận .\n‘ Chẳng lẽ là một ngàn năm ma chú sao ?’\nLý Ân Phàm nghĩ tới đây , kinh ngạc nhìn ngoài cửa sổ .\nBởi vì nếu như đơn độc đem hai cái này thời gian lấy ra , cũng biết phát hiện một vấn đề .\nBọn hắn là thất bại , sau này triều đại như cũ tại kéo dài dùng phía trước tư tưởng .\nGiống như Thương triều sau đó Chu triều , như cũ tại kéo dài dùng chế độ nô lệ .\nMà Tống triều , thì tiếp tục tiếp tục sử dụng đại nhất thống trung ương tập quyền quy định .\nNhưng trước sau so sánh , có thể rất rõ ràng phát hiện , sau này triều đại , kỳ thực đều tại đi xuống dốc .\nNhư Hán , tấn , Tùy , Đường , cái này 4 cái triều đại , so sánh Tống , nguyên , minh , rõ ràng .\nRất rõ ràng liền có thể phát hiện , từ tống khai bắt đầu , Trung Nguyên đại địa , tựa hồ vẫn luôn đang đi xuống dốc .\nHoặc có lẽ là , một mực tại đi một đầu tử lộ .\nĐường triều tựa hồ đem con đường này chạy tới đỉnh phong , mà Đường triều biểu hiện đâu ? Đúng là biểu hiện ra đỉnh phong .\nSau đó Tống , nguyên , minh , rõ ràng .\nDường như là tìm không thấy đường , một mực tại trong đại nhất thống trung ương tập quyền cái này dàn khung , liều mạng “ Chụp chi tiết ”.\nThương triều cùng Chu triều so sánh liền càng thêm rõ ràng .\nChu triều là lúc nào bắt đầu thiết lập Chu triều đồng dạng cho rằng thành lập tại trước công nguyên năm từ Chu Vũ vương Cơ Phát diệt thương sau sáng tạo .\nXuân thu là từ thời điểm thời điểm bắt đầu ? Trước công nguyên năm Chu Bình Vương đông dời Lạc Ấp , Chu vương phòng thế lực suy sụp , các nước chư hầu bắt đầu quật khởi tranh bá .\nMà Thương triều thời kì cuối , cùng Chu triều thời kì cuối , kỳ thực càng có thể phát hiện rõ ràng khác biệt .\n‘ Tựa hồ đúng là một ngàn năm , nhưng cái này một ngàn năm , dường như là phiến đại địa này cùng lịch sử , cho cơ hội ...’\n‘ Nếu quả thật xuất hiện một cái tụ tập đế vương thủ đoạn , tư tưởng đại hiền , hai người này hợp hai làm một ...’\n‘ Có phải hay không liền ’ không cần “ Trăm nhà đua tiếng ”...’\nỞ trong đó ở gần nhất người là ai ?\nCó thể có người nghĩ tới , Thương Trụ Vương Đế Tân ...\nMà Đế Tân , từ hiện tại khai quật ra càng ngày càng nhiều tư liệu lịch sử chứng minh , hắn đúng là rất gần hai người này hợp hai làm một .\nNhưng hắn tựa hồ quá coi thường tư tưởng biến đổi mang tới kịch liệt đau từng cơn .\nNếu như liền dùng cái này suy luận , thật là một ngàn năm lời nói .\nTrước công nguyên năm , giảm đi một ngàn năm , thời gian là công nguyên năm ...\nCăn cứ xuất thổ tư liệu lịch sử phỏng đoán :\nTrước công nguyên năm , Hiên Viên tham gia Tây Lăng quốc khóa mới tù trưởng tranh cử lúc , cùng kỳ bá đồng thời bị phương bắc dân tộc cướp đi . Cái này làm cho luy tổ phấn khởi đứng ra , tham gia thủ lĩnh tranh cử , đạt được thành công lớn .\nLấy điện thoại di động ra , liếc nhìn lịch sử niên phổ , Lý Ân Phàm ngơ ngác nhìn ...\nTrước công nguyên năm , Chuyên Húc đế tuyệt địa thiên thông .\nTrước công nguyên năm , Hiên Viên Hoàng Đế tham gia Tây Lăng quốc tù trưởng tinh tuyển .\nTrước công nguyên năm , Hạ triều vừa lập , nhường ngôi chế bắt đầu chuyển biến làm thừa kế chế .\nTrước công nguyên năm , Đế Ất qua đời , ( Thương Trụ vương ) Đế Tân kế vị .\nTrước công nguyên năm , Hán Vũ Đế Lưu Triệt xuất sinh .\nCông nguyên năm , Triệu Khuông Dận chỗ thời gian .\nCông nguyên năm năm , lão sư chỗ thời gian .\nLý Ân Phàm trên điện thoại di động , cẩn thận nghiêm túc viết xuống thời gian này bày tỏ .\n“ Không đúng !”\nLý Ân Phàm tựa hồ phát hiện mình vấn đề .\nMỗi một ngàn năm , đúng là ma chú , nhưng không phải cái gọi là vương triều lý luận tuổi thọ ma chú .\nCái này mỗi một ngàn năm , tựa hồ hẳn là “ Văn ” Cùng “ Võ ” Chuyển đổi ...\nChuyên Húc đế tuyệt địa thiên thông , xác lập tư tưởng sau đó , mới tư tưởng bắt đầu lan tràn , “ Văn ” Xác lập , “ Võ ” Bắt đầu Do Suy đến thịnh .\n“ Võ ” Đến cực hạn đỉnh phong , chính là Hiên Viên Đế xuất hiện , mà Hiên Viên Đế xuất hiện , “ Võ ” Xác lập , “ Văn ” Bắt đầu Do Suy Chuyển thịnh .\n“ Văn ” Đỉnh phong thể hiện , chính là Hạ triều thiết lập , “ Công thiên hạ nhường ngôi chế ” Bắt đầu biến thành “ Độc chiếm thiên hạ kế thừa chế ”, giờ khắc này , “ Văn ” Xác lập , “ Võ ” Bắt đầu Do Suy Chuyển thịnh .\nMà “ Võ ” Đến lúc thịnh nhất , thời gian đã đến Thương triều , Đế Tân xuất hiện , “ Võ ” Xác lập , “ Văn ” Bắt đầu từ suy chuyển thịnh .\nSau đó , thời gian đã đến Hán Vũ Đế Lưu Triệt thời kì , “ Văn ” Xác lập , đại nhất thống trung ương tập quyền quy định xác lập , võ ” Bắt đầu từ suy chuyển thịnh .\nĐường triều biểu hiện , cùng với Ngũ Đại Thập Quốc , đúng là vô cùng phù hợp “ Võ ” Đỉnh phong cực hạn thể hiện .\nSau đó đâu ? “ Võ ” Xác lập , “ Văn ” Bắt đầu từ suy chuyển thịnh .\nCuối cùng , thời gian đã đến dân quốc ...\nNghĩ tới đây , Lý Ân Phàm trong đầu , bỗng nhiên xuất hiện một cái đồ án .\nCái này một cái đồ án , có thể có người nhìn thấy cái này thời điểm , cũng nghĩ đến .\nThái Cực Đồ ...\nCũng chính là Âm Dương Ngư .\nGiờ khắc này , Lý Ân Phàm quay đầu , ngơ ngác nhìn máy bay ngoài cửa sổ đám mây .\nThì ra , cổ nhân , đã sớm biết ?\nLý Ân Phàm chợt phát hiện , cổ nhân kỳ thực sớm đã dùng một tấm Thái Cực Đồ , biểu lộ hết thảy tất cả .\n“ Văn ” ( Đen ) đến cực hạn , liền sẽ bắt đầu xuất hiện “ Võ ” ( Trắng ).\nMà mỗi cái đồ án ở giữa , vì sao lại có đối lập một điểm ?\nTrắng ở giữa , vì sao lại có đen ?\nĐen ở giữa , vì sao lại có trắng ?\nGiờ khắc này , Lý Ân Phàm đem trong lịch sử xác lập “ Văn ” Thay đổi , cùng với “ Võ ” Thay đổi tiên hiền hoàng đế , thay vào trong đó .\nPhát hiện vậy mà không một chút không hài hòa ...\nBan đầu liệt ra thời gian như vậy bày tỏ thời điểm , Lý Ân Phàm còn có chút nghi hoặc , nếu như nói Hán Vũ Đế Lưu Triệt , là “ Văn ” Đích xác lập , nhưng hắn ngay lúc đó một chút biểu hiện , cũng không phù hợp “ Văn ”.\nNhưng nếu như là lấy Thái Cực Đồ tới biểu hiện .\nVậy thì vô cùng phù hợp .\nLại lấy ra điện thoại , Lý Ân Phàm đang lục soát trên website lùng tìm ba chữ : Thái Cực Đồ .\nChờ website nhảy chuyển , Lý Ân Phàm liếc mắt liền thấy được một cái tiêu đề .\n《 Thái Cực Đồ : Vũ trụ vạn vật chi nguyên , giảng giải hết thảy chung cực huyền bí .》\nNgơ ngác nhìn cái tiêu đề này , Lý Ân Phàm lúc này nội tâm , một mảnh mờ mịt .\n......', 'output\\mp3\\Màn Trời Quyền Lực Diễn Biến Cùng Truyền Thừa\\0086_Thứ 86 chương Thái Cực Đồ, Âm Dương Ngư.mp3', '2026-09-01T23:46:57.296131+00:00', 'completed', 'completed', 6652, 6652),
	(92, 7, '7653528756799144473', 87, 'Thứ 87 chương Lịch sử đại thế bao la...', 'Thứ chương Lịch sử đại thế bao la ...\nHiện đại thời không .\nNgồi ở trên máy bay , cũng không biết qua bao lâu , Lý Ân Phàm đột nhiên lấy lại tinh thần , nhìn xem trên điện thoại di động cái kia Thái Cực Đồ , Âm Dương Ngư .\n‘ Có lẽ ta phía trước đều sai .’\n‘ Không phải “ Văn ” Cùng “ Võ ” Chuyển đổi .’\n‘ Là “ Có ” Cùng “ Vô ” Chuyển Hoán .’\nĐúng vậy , là có cùng không chuyển đổi , Lý Ân Phàm giờ khắc này , rất nhiều suy nghĩ , bắt đầu ở trong đầu phun ra ngoài .\nHắn đã nghĩ tới quý tộc , thế gia , gia tộc vân vân giai cấp tồn tại .\nBọn hắn , không phải liền là chỉ tồn tại một ngàn năm sao ?\nMỗi một ngàn năm , giai cấp các loại hết thảy tất cả , đều sẽ bị thời đại đại thế nghiền ép đến mảnh vụn , tiếp đó , mới giai cấp , lại bắt đầu tại cái này một vùng phế tích phía trên một lần nữa tồn tại .\nMà làm cái gì muốn ở giữa tại một lần nữa nhặt lên trước kia tư tưởng ?\nBởi vì trải qua một ngàn năm , mới xác lập tư tưởng , đã hướng tới ổn định .\nỞ trong đó hai cái so sánh mãnh liệt nhất vương triều , chính là Đường triều cùng Tống triều .\nTại Đường triều thời kì , nho gia , hoặc có lẽ là nho sinh còn không có bị hoàn toàn gò bó .\nNhưng đến Tống triều , từ Đường triều Thịnh cực mà Suy , đi từ từ hướng bảo thủ .\nTừ khai phóng , một ngàn năm thời gian , đến đỉnh phong .\nTiếp đó cực tốc rơi xuống , cuối cùng hướng tới bảo thủ .\nMà bảo thủ nhất thời gian , là thời gian nào ? Thanh mạt dân sơ ...\n“ Thịnh cực mà Suy , vật cực tất phản , khổ tận cam lai ...”\nLý Ân Phàm suy nghĩ rất nhiều , trong đầu , cũng nghĩ đến nữ tính ...\nTrong lịch sử đối với nữ tính , tại Tống phía trước , cái kia một ngàn năm thời gian , cũng là xu hướng tại càng ngày càng khai phóng ...\nDù là chủ lưu là nho gia , nhưng tại Hán Vũ Đế xác lập tư tưởng nho gia , đến Tống triều cái này một ngàn năm , cũng không có gò bó .\nMà tới được Đường triều , đỉnh phong thể hiện , chính là Vũ Tắc Thiên ...\nNhưng là như vừa rồi nói , Thịnh cực mà Suy , vật cực tất phản ...\nSau đó , từ Tống triều bắt đầu , liền bắt đầu càng ngày càng gò bó nữ tính ...\nMà thời gian trôi qua một ngàn năm , đã đến giờ Thanh mạt minh sơ , khổ tận cam lai , phụ nữ cũng bắt đầu giải phóng ...\nGiờ này khắc này , Lý Ân Phàm nhìn ngoài cửa sổ dần dần bay qua đám mây , nghĩ thông suốt trước đó ở trên mạng thấy qua rất nhiều không hiểu tư tưởng .\nRất nhiều thứ , tại sao muốn bỏ mặc ? Hoặc có lẽ là , vì cái gì vẻn vẹn chỉ là gò bó ?\nBởi vì đại thế là ngăn cản không được , ở vào thời kỳ tăng lên đồ vật , ngươi như thế nào đi ngăn cản ? Cùng đại thế làm vi phạm sao ?\n“ Mắt thấy hắn lên cao ốc , mắt thấy hắn yến khách mời , mắt thấy hắn lầu sập ...”\nLý Ân Phàm nhẹ nhàng nhắc tới câu này Đào Hoa Phiến bên trong nổi tiếng lời nói .\n“ Có một số việc , nếu như không để tất cả mọi người biết hạ tràng , hoặc có lẽ là , nếu như không để phần lớn người cảm nhận được đau ...”\n“ Ngươi không có cách nào đi ngăn cản ...”\n“ Chỉ có thể trơ mắt nhìn hắn một mực gia tốc ...”\nLắc đầu , trước đó suy nghĩ rất nhiều không thông chính sách , lúc này Lý Ân Phàm cũng từ từ nghĩ thông suốt .\n“ Đại thế là không ngăn cản được , nếu như ngươi cưỡng ép ngăn cản , có thể sẽ gây nên mãnh liệt hơn bắn ngược ...”\n“ Càng nhiều người sẽ oán trách , hoặc có lẽ là thống hận , ngươi dựa vào cái gì muốn ngăn cản ?”\n“ Đây chính là vì cái gì dù là biết là đường quanh co , phía trước hiện đầy bụi gai , ngươi cũng chỉ có thể đi lên phía trước ...”\n“ Bởi vì những người khác là không biết ...”\nAi ...\nLý Ân Phàm thở dài một hơi , cũng càng thêm cảm thấy bất đắc dĩ , loại này thanh tỉnh nhận thức , có đôi khi quả thật làm cho người cảm thấy một hồi đau đớn .\nĐau đớn ngươi biết rất rõ ràng có một số việc kết cục , nhưng ngươi chỉ có thể trơ mắt nhìn , tiếp đó ? Rơi vào trong đó , lại chuyển hướng ...\nGiống như là trong lịch sử Vũ Tắc Thiên xưng đế .\nTại nàng không có xưng đế phía trước , cũng chỉ có thể trơ mắt nhìn , ngăn cản ? Có thể sẽ chỉ làm nàng càng nhanh chóng hơn quật khởi ...\nTại Vũ Tắc Thiên phía trước , có bao nhiêu hoàng hậu cầm quyền ?\n“ Thế nhưng chỉ có thể là Thịnh cực mà Suy ...”\n“ Đột phá ranh giới cuối cùng , chỉ có thể để cho vô số người chèn ép ...”\nLý Ân Phàm bỗng nhiên ý thức được , Vũ Tắc Thiên xưng đế , đúng là trong lịch sử một cái mang tính tiêu chí sự kiện .\nLúc đó không có người nghĩ đến nàng có thể sẽ xưng đế sao ? Lý Ân Phàm không tin , hẳn là có người nghĩ tới .\nNhưng làm sao đi ngăn cản ? Là ngươi đi một mình ngăn cản ? Vẫn là một thế lực đi ngăn cản ?\nCho nên có thể liền dứt khoát từ bỏ , trực tiếp không ngăn cản , để cho toàn thiên hạ tất cả mọi người , trơ mắt , rõ rành rành thấy rõ ràng :\nVũ Tắc Thiên xưng đế , sau đó thì sao ? Xưng đế sau đó , nàng rốt cuộc muốn làm gì !\nCũng chính là dạng này , khắp thiên hạ , tất cả mọi người , cũng bắt đầu ngăn cản nữ tính cầm quyền ...\n“ Cho nên , bây giờ còn kém một cái mang tính tiêu chí sự kiện sao ?”\nLý Ân Phàm lúc này trong đầu , bỗng nhiên toát ra một cái ý nghĩ như vậy .\nSau đó , lắc đầu , đem cái này ý nghĩ từ trong đầu ném ra .\n“ Cho nên đây cũng chính là chính sách bất đắc dĩ , hoặc có lẽ là đại thế tất nhiên ...”\n“ Có nhiều thứ , ngươi muốn ngăn cản ? Cái kia chỉ có để cho khắp thiên hạ tất cả mọi người đều biết nó tổn hại mới có thể đi ngăn cản ...”\n“ Tiếp đó , thời gian sau đó bên trong , liền không có người suy nghĩ , lại đem nó một lần nữa kéo ra ngoài ...”\n“ Bằng không thì ? Bằng không thì luôn có người không có cảm nhận được đau đớn , tại sau đó thời gian bên trong , lúc nào cũng một mực nhắc tới .”\n“ Nhắc tới nhắc tới , lại luôn là muốn cho nó tro tàn lại cháy ...”\nĐây cũng chính là vì cái gì , đại thế chỉ có thể theo đi , mà không thể nghịch hành ...\nNghịch hành có lẽ sẽ thành công , nhưng sau đó , sẽ luôn để cho ngươi trả giá đắt ...\n“ Trong lịch sử rất nhiều hoàng đế , bọn hắn cũng chính là thấy được điểm này sao ?”\nLý Ân Phàm bỗng nhiên ý thức được , có thể trong lịch sử có rất nhiều hoàng đế , bọn hắn đều ý thức được điểm này .\nĐại thế không cách nào đi ngăn trở , chỉ có thể sờ lấy đại thế mạch lạc , từng điểm từng điểm đi .\nBọn hắn có thể không ý thức được mỗi một ngàn năm liền đem “ Chuyển đổi ” Một lần .\nNhưng bọn hắn lại bố trí xuống hậu chiêu , để cho thời gian trôi qua , tiếp đó tại một cái thời kỳ nào đó , để cho tất cả hậu chiêu toàn bộ dẫn phát .\n“ Nhưng bọn hắn hành động này , có lẽ cũng đang ấn hợp mỗi một ngàn năm đại thế ...”\nHán lúc đầu kỳ , từ Lưu Bang bắt đầu Hoàng lão hưu sinh dưỡng tức , thời gian vừa vặn đến Hán Vũ Đế ở giữa , cũng đúng lúc đến một ngàn năm , bắt đầu “ Chuyển đổi ”.\nLý Ân Phàm nghĩ tới Hán triều , cũng nghĩ đến triều Tấn , sau đó nghĩ tới Tùy triều cùng Đường triều ...\nCuối cùng , Lý Ân Phàm trong đầu xuất hiện một câu nói :\nThiên hạ đại thế , bao la , thuận chi thì sống , làm trái thì chết ...', 'output\\mp3\\Màn Trời Quyền Lực Diễn Biến Cùng Truyền Thừa\\0087_Thứ 87 chương Lịch sử đại thế bao la....mp3', '2026-09-01T23:47:02.205141+00:00', 'completed', 'completed', 6727, 6727),
	(93, 7, '7653528924651012633', 88, 'Thứ 87 chương 20 vạn chữ tổng kết ~~~', 'Thứ chương 20 vạn chữ tổng kết\nLời của tác giả :\nViết lên ở đây , cũng đến 20 vạn chữ , vẫn là làm một cái tổng kết a , hơn nữa trả lời một chút phía trước độc giả một vài vấn đề .\nĐương nhiên , đối với lịch sử vấn đề , tác giả bình thường là sẽ không trả lời , không phải tác giả cao lãnh , cũng không phải tác giả khinh thường .\nBởi vì tác giả biết , mỗi người nhìn sách , cùng với đối với lịch sử cảm thụ , cũng là khác biệt .\nNgươi đọc sách hay là đọc tiểu thuyết lý giải đi ra ngoài đồ vật , những người khác , rất khó đi cảm động lây .\nNguyên nhân cũng liền ở đây , tất cả mọi người nhìn thấy cũng khác nhau , muốn thuyết phục người khác , liền vô cùng khó khăn .\nCho nên , tác giả cũng liền chỉ là đem chính mình hiểu lịch sử viết xuống , mọi người xem xem xét liền tốt .\nĐồng ý , tác giả liền vô cùng cảm tạ , không đồng ý , tác giả cũng vô cùng lý giải .\nKhông cần thiết tại khu bình luận vì một cái quan điểm , đi cãi nhau hay là chửi nhau ...\nNói đến đây , trước hết trả lời một chút , tác giả tại sao muốn tiếp tục viết loại này phân tích loại tiểu thuyết lịch sử a .\nQuyển sách trước , tác giả lúc đó cũng đúng là nghĩ tới , về sau không còn viết loại này phân tích loại lịch sử , bởi vì chính xác quá mệt mỏi .\nMỗi ngày mặc dù chỉ có bốn ngàn chữ , nhưng cái này bốn ngàn chữ viết xuống đồ vật , ngươi muốn chữ chữ châm chước , vắt hết óc suy nghĩ .\nMuốn viết tinh tường có phải hay không ? Vì cái gì ? Lôgic cũng nhất định phải viết vô cùng lưu loát mới được .\nNguyên nhân gây ra , quá trình , kết quả , vì sao lại tạo thành chuyện như vậy ?\nNhững thứ này đều phải viết tinh tường .\nBằng không thì đọc sách độc giả liền sẽ cảm thấy không hiểu thấu .\nNgươi cái tác giả này vì cái gì đột nhiên liền viết cái này ? Ngươi nói rốt cuộc là ý gì ?\nSau đó thì sao ? Độc giả đọc tiểu thuyết đã cảm thấy không thoải mái , khí thư mà đi ...\nMà làm cái gì lại mở một bản loại này phân tích loại sách đâu ? Bởi vì lúc trước có mấy cái sách đều bị phong lại , rất nhiều độc giả muốn lần nữa xem , nhưng mà trực tiếp không tìm được .\nCho nên liền hỏi tác giả , có thể hay không đem phía trước tất cả quan điểm còn có ý nghĩ , toàn bộ ghi vào trong một quyển sách ?\nTác giả nghĩ nghĩ , giống như chính xác có thể , dạng này viết , cũng sẽ không rất mệt mỏi .\nHơn nữa thời gian lâu như vậy đi qua , tác giả cũng có rất nhiều ý tưởng mới , mới quan điểm nghĩ viết một viết .\nTiếp đó , liền lại mở dạng này một bản phân tích loại tiểu thuyết lịch sử .\nGiải thích rõ tác giả vì cái gì lại mở dạng này một bản phân tích loại tiểu thuyết lịch sử , liền hãy nói một chút quyển sách này a .\nQuyển sách này , nói thật , tác giả cũng không biết có thể hay không tiếp tục tiếp tục viết .\nVì cái gì ? Bởi vì quyển sách này ngày hôm qua lợi tức , chỉ có sáu khối tiền !\nMà bây giờ 20 vạn chữ đến , cũng đến sách trắc thời gian , tác giả cũng không biết sách trắc thất bại , có nên hay không tiếp tục tiếp tục viết .\nChỉ có thể nói , đến lúc đó lại nhìn a .\nCuối cùng liền nói một chút tác giả đối với quyển sách này đại cương .\nChủ tuyến chính là trong lịch sử từ Tần Thuỷ Hoàng Doanh Chính bắt đầu , mãi cho đến Minh triều những năm cuối Sùng Trinh .\nBọn hắn mỗi một cái hoàng đế đều sẽ tới hiện đại tới .\nMà bây giờ đến 20 vạn chữ , cũng liền mới tới Lưu Bang .\nCho nên có thể viết còn rất nhiều , dù sao tác giả còn muốn đem trước đây vài cuốn sách quan điểm , đều phải dung hợp đi vào .\nSau đó , tiểu thuyết lợi tức có chỗ khởi sắc , tác giả thì sẽ vẫn luôn tiếp tục viết , thẳng đến Sùng Trinh mới thôi .\nCó rất nhiều mới độc giả , nhìn thấy khả năng này liền có chút nghi hoặc , vì cái gì không viết Thanh triều ?\nLão đọc sách hẳn phải biết tác giả vì cái gì không viết Thanh triều .\nĐáp án kỳ thực rất đơn giản , Thanh triều sách sử , bây giờ còn chưa ra !\nĐối với Thanh triều còn không có nắp hòm kết luận !\nRất nhiều thứ , sẽ phi thường dễ dàng chạm đến dây đỏ , tiếp đó phong sách .\nLý do chính là lịch sử chủ nghĩa hư vô .\nCho nên , nghĩ viết Thanh triều , chỉ có thể chờ đợi quan phương đối với nó nắp hòm định luận sau đó , mới có thể đi viết .\n...\nCuối cùng của cuối cùng , tác giả quỳ tạ một mực tại truy tác giả sách độc giả , cám ơn các ngươi mỗi ngày đều đang đuổi sách , để cho tác giả có thể có một phần lợi tức .\nTác giả vô cùng cảm tạ !\nCũng vô cùng cảm tạ những cái kia mỗi ngày truy sách nhìn quảng cáo , mỗi một phần quảng cáo , có thể để cho tác giả lợi tức một phân tiền tác giả .\nVô cùng cảm tạ các ngươi mỗi ngày không kiên nhẫn kỳ phiền đều biết điểm một điểm quảng cáo !\nCuối cùng cảm tạ tất cả độc giả , có thể nhìn đến ở đây !\nCám ơn các ngươi !!!', 'output\\mp3\\Màn Trời Quyền Lực Diễn Biến Cùng Truyền Thừa\\0088_Thứ 87 chương 20 vạn chữ tổng kết ~~~.mp3', '2026-09-01T23:47:06.682029+00:00', 'completed', 'completed', 4577, 4577),
	(94, 7, '7653889330535989785', 89, 'Thứ 88 chương Võ Đế', 'Thứ chương Vũ Đế\nMinh triều .\nVĩnh Lạc bảy năm .\n“ Hán Vũ Đế ... Lưu Triệt ...”\n“ Vũ Đế ...”\nChu Lệ nhẹ giọng nói thầm một tiếng Hán Vũ Đế Lưu Triệt tên , sau đó cảm khái nói :\n“ Trong lịch sử , có thể bị xưng là võ đế hoàng đế , nói thật , liền không có yếu .”\nBên cạnh Chu Cao Sí cũng đồng ý gật đầu một cái , đúng là không có yếu .\n“ Từ ban đầu Hán Vũ Đế Lưu Triệt , lại đến Hán Quang Võ Đế Lưu Tú ...”\n“ Sau đó đâu ? Chính là Ngụy Vũ Đế Tào Thao , cùng với Tấn Vũ Đế Tư Mã Viêm ...”\nCó thể có người rất nghi hoặc , Tấn Vũ Đế Tư Mã Viêm cũng vô cùng lợi hại sao ?\nChính xác rất lợi hại , Tam quốc , chính là trên tay hắn thống nhất .\nTriều Tấn , cũng là trên tay hắn thiết lập , Tư Mã Viêm , cũng chính là triều Tấn khai quốc hoàng đế .\nPhương diện võ công , Tư Mã Viêm đúng là vô cùng lợi hại .\nKéo thấp Tư Mã Viêm đánh giá , là hắn văn trị .\nMà tại phương diện văn trị , Tư Mã Viêm tại vị hậu kỳ , làm chuyện hoang đường , thì càng là kéo xuống lịch sử đối với hắn đánh giá .\n“ Thành Vũ Đế Lý Hùng , sau Triệu Vũ Đế Thạch Hổ , sau yến thành Vũ Đế Mộ Dung rủ xuống .”\n“ Bắc Ngụy Thái Vũ Đế Thác Bạt Đảo , Tống Vũ Đế Lưu Dụ , Nam Tề Vũ Đế Tiêu Trách , Lương Vũ Đế Tiêu Diễn , Bắc Chu Vũ Đế Vũ Văn Ung , Trần Vũ Đế Trần Bá trước tiên .”\n“ Xem những thứ này Vũ Đế , quả nhiên là ...”\nChu Lệ nói thầm những hoàng đế này tên , sau đó lắc đầu không biết nên nói cái gì .\nĐến nỗi sau đó Vũ Đế vì cái gì không nói ? Bởi vì từ Đường triều bắt đầu , thụy hào bắt đầu lạm dụng , ngoại trừ ban đầu mấy vị kia hoàng đế , phía sau cái gọi là Vũ Đế , Văn Đế , cũng không có cái gì quá lớn hàm kim lượng .\nTỉ như nói : Đường Vũ Tông , Lý Viêm .\nĐối với lúc trước Vũ Đế , liền có thể rất rõ ràng nhìn ra khác biệt .\nNhưng muốn nói Đường Vũ Tông Lý Viêm , có hay không chiến công ? Là có .\nSẽ xương 3 năm bình định chiêu Nghĩa Trấn Lưu chẩn phản loạn , đây là Đường vương triều quan hệ địa phương phiên trấn cát cứ một lần cuối cùng thắng lợi , chiến hậu các nơi phiên trấn một lần nữa tuân thủ triều đình mệnh lệnh .\nCùng với ba võ một tông , Lý Viêm cùng Bắc Ngụy Thái Vũ Đế , Bắc Chu Vũ Đế , sau Chu Thế Tông Sài Vinh diệt phật hành động .\nNhưng sau đó sao ? Hàm kim lượng đúng là càng ngày càng thấp .\n“ Nói thật , nếu như không phải màn trời giảng thuật , ta chính xác còn không biết , Hán Vũ Đế Lưu Triệt , tại trên năng lực quân sự , vậy mà nhô ra như thế ...”\nChu Cao Sí đối với phụ thân lời nói , nhận đồng gật đầu một cái .\n“ Người thiện chiến không hiển hách công lao , thầy thuốc không huy hoàng chi danh ...”\n“ Nếu như lúc đó không có Hán Vũ Đế Lưu Triệt cường đại hậu cần năng lực , Vệ Thanh cùng Hoắc Khứ Bệnh các tướng lãnh , có thể hay không như vậy rực rỡ , chính xác khó mà nói .”\nMà Chu Lệ nghe nói như thế , chỉ là nhìn xem nhà mình lão đại Chu Cao Sí .\nSau đó bỗng nhiên nở nụ cười .\nChu Lệ vì cái gì cười ? Hắn thấy , Chu Cao Sí quả thật có một chút từ thổi hiềm nghi .\nBởi vì Chu Lệ trưng thu mạc bắc hậu cần , là ai tại “ Cung cấp ”? Chu Cao Sí .\nChu Cao Sí gặp Chu Lệ cười , sửng sốt một chút , sau đó tựa hồ cũng nghĩ đến điểm này , có chút cười cười xấu hổ .\n...\nMinh triều .\nHồng Vũ năm .\n“ Hán Vũ Đế Lưu Triệt ....”\n“ Hán Thái tổ Lưu Bang ...”\nChu Nguyên Chương giờ phút này nhớ tới trên sử sách đối với Lưu gia hoàng đế ghi chép , bỗng nhiên quay đầu nhìn bên cạnh đại nhi tử Chu Tiêu .\n“ Lão đại , ngươi cho rằng vì cái gì Hán triều hoàng đế , năng lực của bọn hắn đều vô cùng mạnh ?”\nÂn ?\nChu Tiêu nghe được vấn đề này , có chút ngây người , nhưng không sửng sốt một hồi , Chu Tiêu tựu hồi thần lại , bắt đầu cẩn thận suy tư .\n“ Phụ thân , ngoại thích ?”\nChu Tiêu tựa hồ nghĩ tới điều gì , nhỏ giọng đối với Chu Nguyên Chương nói .\nMà Chu Nguyên Chương nghe được đáp án này , nhưng là khẽ gật đầu .\n“ Đúng vậy a , ngoại thích ...”\nNói xong , Chu Nguyên Chương thở dài .\n“ Hoàng hậu dạy bảo , cùng với thượng vị sau đó liền có thể lợi dụng ngoại thích thế lực , để cho Hán triều hoàng đế một thượng vị , liền có thể nắm giữ vượt qua hậu thế hoàng đế chính trị năng lực .”\nHán triều hoàng đế , so sánh đời sau hoàng đế , bọn hắn kỳ thực thiên nhiên liền có một cái ưu thế .\nƯu thế này là cái gì ? Chính là ngoại thích thế lực .\nNgoại thích thế lực vì củng cố vị trí của mình , bọn hắn sẽ đem hết toàn lực đem “ Thái tử ” Phù chính vì “ Hoàng đế ”.\nMà Hán triều hoàng đế thượng vị sau đó , bọn hắn liền một cách tự nhiên , có thể lợi dụng cái này một thế lực , đi cân bằng triều đình thế lực .\nĐây cũng chính là nói , Hán triều Thái tử , kỳ thực chính là kèm theo thế lực lên chức .\nSau đó hoàng đế ? Có rất ít người có thể có loại đãi ngộ này .\nMà ngoại thích , là lúc nào bắt đầu không bị triệt để tín nhiệm ? Là Vương Mãng soán vị ...\nVương Mãng soán vị , triệt để trở thành tâm lý cùng chính trị nhận thức đường ranh giới .\nĐông Hán Quang Võ Đế Lưu Tú , đem hắn cố hóa vì quy định phòng tuyến , sau đó các triều đại đổi thay mặc dù chợt có ngoại thích được thế , nhưng đều bị coi là hoàng quyền suy vi hiện tượng dị thường , mà không phải là bình thường tín nhiệm kết quả .\n“ Ai ...”\nNhìn mình Thái tử Chu Tiêu , Chu Nguyên Chương cũng không biết nghĩ tới điều gì , chỉ là thở dài một hơi .\n...\nTống triều .\nMở bảo sáu năm .\n“ Trẫm đúng là muốn thay đổi rất nhiều thứ , nhưng lại có thể làm sao đâu ?”\nTriệu Khuông Dận đã từng lập xuống qua lời thề , quyết tâm dọn dẹp Ngũ Đại Thập Quốc cái thời đại kia tai hại .\nNhưng rất nhiều sự tình , đã đem tinh lực của hắn toàn bộ dây dưa , chớ nói chi là còn phải cố gắng thống nhất mảnh đất này .\n“ Trẫm không phải những cái kia tiên hiền , cũng làm không được những cái kia tiên hiền ...”\nNghĩ tới đây , Triệu Khuông Dận nhẹ nhàng hít một tiếng .\nTriệu Khuông Dận vì cái gì nhặt lên nho gia ? Bởi vì vào lúc này Tống triều , chỉ có thể lựa chọn nho gia .\nNho gia từ Hán Vũ Đế Lưu Triệt bắt đầu , mãi cho đến hắn thời đại này , đã qua không sai biệt lắm một ngàn năm .\nĐây đã là thế nhân có thể phổ biến tiếp nhận tư tưởng .\nMà cần có nhất làm , chính là để cho thế nhân , có thể một lần nữa nhớ lại nho gia : Lễ nghĩa liêm sỉ ...\nĐối với Triệu Khuông Dận tới nói , đây mới là thời đại này , nhất định phải làm .\n...\nTống triều .\nThiệu Hưng 9 năm .\n“ Vũ Đế ...”\nLúc này Nhạc Phi , vô cùng hâm mộ nhìn xem trên thiên mạc chỗ giới thiệu Hán Vũ Đế Lưu Triệt .\n“ Hán ... Đường ...”\n“ Ai ...”\nLúc này thời gian là Thiệu Hưng 5 năm , Nhạc Phi đã mơ hồ mơ hồ cảm nhận được cái gì .\nCảm giác này , nói không rõ , không nói rõ , nhưng hắn luôn có một loại dự cảm .\nLý tưởng của mình , có thể sẽ không thành công , cũng thành công không được .\nNhạc Phi không biết cảm giác này đến từ đâu , nhưng chính là loại cảm giác này , tại sâu trong nội tâm của hắn , giờ phút này chôn xuống một mảnh bóng tối .\n...\nCuối thời Đông Hán .\nKiến An 8 năm .\n“ Vũ Đế ... Vũ Đế ...”\nTào Thao nhớ tới trên sử sách đối với Hán Vũ Đế ghi chép , nhìn về phía màn trời trong ánh mắt , cất giấu một vòng hâm mộ .\nHắn hâm mộ Vệ Thanh , cũng hâm mộ Hoắc Khứ Bệnh , hâm mộ bọn hắn có thể gặp được đến Hán Vũ Đế Lưu Triệt dạng này Đế Vương .\nDù là tới mức độ này , Tào Thao kỳ thực y nguyên vẫn là quên không được chính mình lý tưởng ban đầu .\nHán nguyên nhân chinh tây tướng quân Tào Thao chi mộ .\nĐây là Tào Thao lúc còn trẻ hi vọng , cũng là hắn chôn cất tại nội tâm chỗ sâu nhất khát vọng .\n( Có lẽ cái này cũng là vì sao Tào Thao đánh dị tộc dị thường hăng hái nguyên nhân ?)\nNhưng lúc này đại hán , thực tế thay nhau ẩu đả , chỉ có thể để cho Tào Thao đem cái này hi vọng triệt để chôn cất ...\n“ Ai ...”\nTào Thao nhìn xem màn trời ánh mắt , càng thêm bình tĩnh .\n...\nTam quốc thời kì .\nThục Hán .\nChương Vũ Nguyên năm .\n“ Tiên tổ !!!”\nLưu Bị nghe màn trời từng chút một giảng thuật , thất thanh khóc rống .\n“ Chuẩn bị , có lỗi với các ngươi a , tiên tổ !”\nNgồi liệt trên mặt đất , Lưu Bị đã mất đi đối với tư thái cùng lễ nghi quản lý .\n“ Thừa tướng ?”\nCó người muốn đi nâng bệ hạ , nhưng Gia Cát Lượng lại ngăn cản bọn hắn .\n“ Để cho bệ hạ làm càn một chút đi ...”\nGia Cát Lượng thở dài , nhẹ giọng đối với người chung quanh nói .\nSau đó , Gia Cát Lượng thận trọng ra hiệu , tất cả mọi người rời đi , mà chính mình cũng đi theo lui ra ngoài .\nGia Cát Lượng biết Lưu Bị vì cái gì thất thanh khóc rống .\nBởi vì lúc này đại hán thực tế cùng trời màn chỗ giới thiệu đại hán , chênh lệch quá lớn !\nLớn đến , chỉ cần thoáng vừa so sánh , liền để Lưu Bị dạng này Hán thất dòng họ thất hồn lạc phách .\nTrừ cái đó ra đâu ? Còn có trước kia bốn phía lưu ly tịch mịch ...\n...\nĐường triều .\nTrinh Quán bảy năm .\n“ Hán Vũ Đế ... Vũ Đế ...”\nLý Thế Dân kinh ngạc nhìn màn trời , nội tâm so sánh mình cùng màn trời chỗ giới thiệu Hán Vũ Đế .\nNói thật , Lý Thế Dân trước kia là không thấy thế nào hảo hán Võ Đế Lưu Triệt .\nBởi vì hắn thấy , Hán triều Hán văn đế Lưu Hằng , mới là toàn bộ Hán triều cọc tiêu .\nCũng là Lý Thế Dân học tập đối tượng .\nNhưng hắn đúng là không nghĩ tới , tại màn trời xem ra , Hán Vũ Đế Lưu Triệt lớn nhất chiến công , kỳ thực là tại văn .\nMà không phải tại võ .\nTư tưởng biến đổi , mới là màn trời cho là Hán Vũ Đế Lưu Triệt lớn nhất chiến công .\n“ Hơn nữa , Hán Vũ Đế Lưu Triệt hậu cần năng lực ...”\nNghĩ tới đây , Lý Thế Dân cũng phát hiện , Hán Vũ Đế Lưu Triệt hậu cần năng lực , chính xác có thể xưng tụng đệ nhất ...\nLúc này Đại Đường , nghèo sao ? Là rất nghèo , bởi vì Tùy mạt loạn thế , Đại Đường vừa lập , bốn phía đều tại một mảnh gạch ngói vụn chờ đợi Lý Thế Dân đi xây dựng .\nNhưng muốn nói lúc này Đại Đường , thật sự rất nghèo sao ? Kỳ thực cũng bất tận ! Bởi vì lúc này thế gia đại tộc , bọn họ đều là rất có tiền ...\nKhông chỉ là tiền , lương thực , những thứ này thế gia đại tộc cũng có là .\nDù sao tại Tùy triều , Tùy Văn Đế Dương Kiên , chính mình di tổ phụ mặc dù vớt rất nhiều , nhưng vẫn là không có những thứ này thế gia đại tộc nhóm vớt hơn .\nTùy mạt loạn thế có thể đánh đến thảm liệt như vậy , những thứ này thế gia đại tộc nhóm , thế nhưng là ra rất đại lực .\nNhưng thế gia đại tộc dù thế nào giàu , cùng hắn Lý Thế Dân , cùng Đại Đường , có lại quan hệ thế nào đâu ?\nĐây đúng là bất đắc dĩ một điểm .\n“ Ai ... Nếu như có thể để cho bọn hắn không giữ lại chút nào cống hiến ra tới ...”\n“ Trẫm cũng chưa chắc không thể ?!”\nNhưng Lý Thế Dân tinh tường , đây chỉ là một loại hi vọng xa vời thôi .\nLúc này Đại Đường , thế gia đại tộc nhóm , cầm giữ quá nhiều yếu hại điểm mấu chốt .\nMuốn để bọn hắn toàn bộ cống hiến ra tới , cái này cùng buộc bọn họ tạo phản , lại có gì dị đâu ?\nMà lúc này Đại Đường , đã không vẫy vùng nổi !\nCho dù là Lý Thế Dân sau lưng ủng hộ những cái kia thế lực , cũng cần thời gian liếm láp tổn thương .\n...\nHán triều .\nNguyên thú 4 năm .\n“ Cũng không biết Thái tổ Cao Hoàng Đế , sẽ ra sao trẫm ?”\nLưu Triệt trong đầu bỗng nhiên nghĩ đến vấn đề này , sau đó đứng lên , đi tới lui ...\n“ Là sẽ cho rằng trẫm cực kì hiếu chiến ? Vẫn là tán dương trẫm làm không tệ ?”\nNhìn xem màn trời phía trên , Lưu Bang nghiêm túc cẩn thận nhìn xem trong tay sách sử , Lưu Triệt lúc này nội tâm , không hiểu có một chút vội vàng xao động .\nMặc dù phía trước hắn nói đúng không để ý , nhưng nam nhân mà , đặc biệt là bọn hắn loại này hoàng đế , lúc nào cũng nghĩ lấy được tổ tiên tán thành .\nĐặc biệt là trên thiên mạc người kia , là bọn hắn đại hán khai sáng giả , Thái tổ Cao Hoàng Đế .\n“ Ai ...”\nLưu Triệt cố nén nội tâm vội vàng xao động , một lần nữa ngồi xuống lại .\nChờ ngồi xuống lại sau đó , Lưu Triệt lại nghĩ tới màn trời phía trước lời nói .\n“ Ai , trẫm ngoại trừ lựa chọn nho gia , còn có thể lựa chọn ai ?”\nĐạo gia ? Đại hán mới lập lúc , dùng chính là Hoàng lão , nhưng là như thế một mực bày xuống đi ? Tiếp đó thỉnh thoảng gặp Hung Nô xâm lấn ?\nPháp gia ? Tần triều chính là dùng pháp gia , đại hán không ai dám đề nghị cách dùng nhà ! Cho dù là Lưu Triệt chính mình , cũng không dám bốc lên thiên hạ chi đại sơ suất đề nghị cách dùng nhà .\nDù sao Tần triều vết xe đổ , thế nhưng là rõ mồn một trước mắt .\nCòn nói là binh gia ?\nBinh gia quả thật không tệ , có thể hắn ở đâu ?\nMuốn làm trên trên dưới phía dưới đều duy trì một cái nào đó đồ vật , vậy cũng chỉ có để trên dưới tất cả mọi người , toàn bộ đều có thể ăn đến chỗ tốt .\nLên tới hoàng đế , xuống đến Lê Minh bách tính , tất cả mọi người đều có thể ăn được chỗ tốt , chỉ có dạng này , mới có thể phổ biến tiếp .\nMà đáp án , cũng liền đặt tại trước mắt .\nChỉ có nho gia , mới có thể để cho tất cả mọi người đều ăn đến chỗ tốt .\nNày làm sao nói ra ? Có lẽ thật là đại thế phía dưới bất đắc dĩ .\nLựa chọn mặc dù nhìn như có rất nhiều loại , nhưng kỳ thật , cũng chỉ có một loại thôi .\nCòn lại ? Chắc chắn sẽ có người phản đối .\nMà chỉ có nho gia , ngoại trừ phía trước Hoàng lão vừa người được lợi ích nhóm phản đối , liền không có người phản đối .\nĐây là Lưu Triệt , cùng thủ hạ tâm phúc nhóm , thôi diễn rất nhiều lần mới lấy được đáp án .\nMà kỳ thực trọng yếu nhất , Lưu Triệt kỳ thực không nói .\nTại trong Gia Tử Bách gia , kỳ thực chỉ có nho gia , mới có lưu đường lui ...\nNhững thứ khác Gia Tử Bách gia nhóm , cũng không có đường lui !\nCái này cũng là Lưu Triệt , lúc đó lựa chọn nho gia nguyên nhân lớn nhất một trong .\n...\nTần triều .\nThủy Hoàng ba mươi năm .\nChương Đài cung .\n“ Nho gia ...”\nTần Thuỷ Hoàng Doanh Chính bình tĩnh nhìn màn trời , nội tâm yên lặng nghĩ đến một số việc .\nKỳ thực Doanh Chính không biết pháp gia đến lúc này , đã không đúng lúc sao ?\nLà biết đến , bằng không thì hắn sẽ không để cho những thứ khác một chút Gia Tử Bách gia tiến triều đình .\nNhưng hắn cũng biết , Tần triều đã đổi không được những thứ khác tư tưởng .\nTừ thương ưởng biến pháp bắt đầu , đến Đại Tần thiết lập , lúc này Đại Tần căn , chính là pháp gia .\nĐổi căn ? Không khác triệt để lật đổ Đại Tần .\nTừ trên xuống dưới tất cả vừa được lợi ích nhóm , đều biết phản đối .\nDù là lúc này màn trời , đã bộc lộ ra tại không lâu sau đó , Đại Tần liền sẽ sụp đổ .\nNhưng để cho bọn họ từ bỏ tới tay lợi ích , lựa chọn lần nữa những thứ khác tư tưởng ?\nTần Thuỷ Hoàng Doanh Chính chỉ là yên lặng lắc đầu .\nLý tưởng đến xem , tất cả mọi người nhìn thấy loại kia kết cục , đều biết lựa chọn những thứ khác tư tưởng .\nThế nhưng chỉ là lý trí thôi .\nMọi người trong lòng cuối cùng sẽ ngờ vực vô căn cứ , nếu là ta từ bỏ , đối thủ của ta , hắn không có từ bỏ làm sao bây giờ ?\nVậy ta cả nhà không phải liền giao cho trên tay của hắn ?\nHoặc , ta từ bỏ , những người khác không có từ bỏ , đem ta nuốt làm sao bây giờ ?\nCho nên nói , rất nhiều chuyện , cuối cùng chỉ có thể từ lý trí đi xem thôi .\nGiống như là ngay lúc đó Lục quốc .\nNhững cái kia Lục quốc quý tộc dư nghiệt , không biết tiếp tục như vậy , bọn hắn các nước chư hầu , đều sẽ bị diệt sao ?\nLàm sao có thể không biết !\nTừ Tần quốc diệt đi thứ nhất Hàn bắt đầu , Tần quốc mục tiêu , liền đã bại lộ .\nNhưng đại địch trước mặt tình huống phía dưới , những cái kia Lục quốc dư nghiệt quý tộc là thế nào làm ?\nHậu thế có một câu nói hảo , phía trước căng thẳng , hậu phương nhanh ăn ...\nCho nên , liền xem như màn trời đã đem Đại Tần kết cục bày tại trước mặt , nhưng lúc này Doanh Chính , vẫn là chỉ có thể thận trọng từng chút một đi thay đổi .\n......', 'output\\mp3\\Màn Trời Quyền Lực Diễn Biến Cùng Truyền Thừa\\0089_Thứ 88 chương Võ Đế.mp3', '2026-09-01T23:47:45.543366+00:00', 'completed', 'completed', 14962, 14962),
	(95, 7, '7654260101674435097', 90, 'Thứ 89 chương Tồn tại chứng minh', 'Thứ chương Tồn tại chứng minh\nHiện đại thời không .\n“ Đây chính là Trường thành sao ?”\nThủ đô bát đạt lĩnh Trường thành , Lưu Bang cùng Lý Ân Phàm hai người chậm rãi đi ở phía trên .\nĐi không bao lâu , Lưu Bang vuốt ve Trường thành bức tường .\n“ Bây giờ tồn tại trên cơ bản cũng là minh dài thành , Tần Trường Thành , cơ bản đều tiêu tan ở trong lịch sử trong bụi trần ...”\n“ Dạng này sao ?”\nLưu Bang nhìn xem dưới chân Trường thành , trong lòng không biết suy nghĩ cái gì .\nNhớ tới mình đã từng thấy Tần triều mênh mông bao la hùng vĩ ? Vẫn là nhớ tới cuối Tần lúc lao dịch phía dưới chạy trối chết mọi người ?\nLưu Bang cũng không biết mình lúc này suy nghĩ cái gì , chỉ là nhìn thấy Trường thành , trong lòng luôn có một chút cảm khái .\n“ Các triều đại đổi thay vương triều , đều tại xây dựng thêm hoặc một lần nữa tu kiến , vì chống cự phương bắc dị tộc ...”\nLý Ân Phàm chỉ là hơi đề một câu , liền không có lại nói tiếp .\nMà Lưu Bang , sau khi nghe được , cũng không đặt câu hỏi , chỉ là nhìn chằm chằm trước mặt dài tường thành thể .\n“ Đi thôi ...”\nCái này cuối cùng không phải Tần Trường thành , Lưu Bang nhìn một hồi , cũng không muốn lại nhìn tiếp .\n...\n“ Ọe !!!”\n“ Tiên sinh , đây rốt cuộc là gì ?!!!”\nLý Ân Phàm cũng là một mặt buồn cười nhìn xem Lưu Bang .\n“ Ta đều nhắc nhở ngươi , quý ca , thứ này , hiện đại đều chỉ có rất ít mới chịu được ...”\nNhìn xem Lưu Bang trong tay ly kia nước đậu xanh , Lý Ân Phàm cũng là cảm thấy bất đắc dĩ .\nChính mình cũng nhắc nhở hắn , hắn nhất định phải đi thử xem , kết quả đây ? Quả nhiên là thử xem liền mất trôi qua .\n“ Ta cho là hậu thế cũng đều là mỹ thực đâu , thật không nghĩ tới , có nhiều thứ ngay cả ta lúc kia cũng không bằng ...”\nLưu Bang vội vàng đem trong tay nước đậu xanh ném tới bên cạnh trong thùng rác , trong ánh mắt cũng là ghét bỏ đến không được .\nHắn thật sự là không nghĩ tới , hậu thế vẫn còn có loại vật này .\n“ Ta nghe người khác nói , thứ này giống như có thể sống đến bây giờ , cũng là vùng khác người không tin tà , nhất định phải thử xem , mới khiến cho nó sống đến bây giờ ...”\n“ A !! Được rồi được rồi !”\n“ Còn tốt tiên sinh ngươi nhiều gọi một ly sữa đậu nành ...”\nLý Ân Phàm có chút buồn cười nhìn xem Lưu Bang .\nNhiều điểm một ly sữa đậu nành ? Mình đương nhiên là cố ý điểm , bởi vì đoán được Lưu Bang chịu không được nước đậu xanh hương vị .\n“ Bước kế tiếp chúng ta đi cái nào ? Tiên sinh .”\nLưu Bang lúc này thật là kích động , nơi nào đều nghĩ đi chơi .\nỞ đây so ngay lúc đó Hán sơ chơi vui nhiều .\nGiờ này khắc này , Lưu Bang tựa hồ lại tìm về lúc tuổi còn trẻ lưu gà đấu cẩu thời gian .\n“ Nhà bảo tàng cùng cố cung ....”\n“ Chúng ta đầu tiên đi đến chỗ nào ?”\nLý Ân Phàm lấy điện thoại di động ra , điều ra trong điện thoại di động hai người hình ảnh , đưa cho Lưu Bang .\n“ Nhà bảo tàng cùng cố cung ?”\nNhận lấy điện thoại di động , Lưu Bang cẩn thận nhìn xem phía trên hình ảnh , xem xong viện bảo tàng hình ảnh sau , Lưu Bang lắc đầu .\nĐối với nhà bảo tàng , Lưu Bang chính xác không có hứng thú gì , dù sao bên trong chứa lấy đồ vật a ...\nNói như thế nào đây ? Hiện đại nhà bảo tàng để rất nhiều vật trân quý , tại Lưu Bang cái kia , nhiều lắm !\n“ Đi cố cung a , tiên sinh .”\n...\n“ Đây là minh thanh lúc Hoàng gia cung điện .”\n“ Minh triều Chu Lệ thời kì , Vĩnh Lạc năm thứ tư bắt đầu xây dựng , đến Vĩnh Lạc năm thứ mười tám xây thành , trở thành minh thanh hai triều hai mươi bốn vị hoàng đế hoàng cung .”\nĐứng tại cố cung phía trước , Lý Ân Phàm cho bên cạnh Lưu Bang giới thiệu .\n“ Có phải hay không cùng các ngươi khi đó hoàng cung có sự bất đồng rất lớn .”\nLưu Bang gật đầu một cái , khoanh tay , nhẹ nói :\n“ Cực lớn có bao nhiêu khác biệt ta không phải là hiểu rất rõ , đại hán hoàng cung Hán bảy năm mới bắt đầu tu kiến ...”\n“ Ta phía trước đi nhìn nhìn , cũng chỉ có thể biết lớn bao nhiêu .”\nÂn ? Dạng này sao ?\nLý Ân Phàm có chút vò đầu , hắn chính xác không biết , đại hán hoàng cung , thứ nhất vào ở , vẫn là Hán Huệ đế Lưu Doanh .\n“ Đi , chúng ta mua vé đi vào dạo chơi !”\nLý Ân Phàm sớm trên điện thoại di động liền mua cố cung vé vào cửa , sau đó trực tiếp mang theo Lưu Bang đi vào .\n“ Kỳ thực rất nhiều thứ , cũng là hậu thế tu sửa qua .”\n“ Ta phía trước nhìn rất nhiều hình ảnh , tại Thanh mạt thời điểm , cố cung liền đã vô cùng đổ nát .”\n“ Dù sao lúc đó khoảng cách Chu Lệ tu kiến thời điểm , đi qua mấy trăm năm .”\nGặp Lưu Bang nhìn chằm chằm vào một chỗ , trong ánh mắt để lộ ra nghi hoặc , Lý Ân Phàm biết hắn đang nghi ngờ thần ác ma , trực tiếp cấp ra đáp án .\n“ Vĩnh Lạc năm thứ tư là lúc nào ? Theo hiện đại kỷ niên pháp mà tính , là năm .”\n“ Mà Thanh mạt , đều đã đến thế kỷ 20 năm .”\n“ Đều đi qua năm trăm năm ...”\nLần này , Lưu Bang lộ ra hiểu rõ thần sắc , hắn nói như thế nào cái này cố cung nhìn còn như thế “ Mới ” Đâu .\n“ Đây chính là Kim Loan điện ...”\nRẽ ngoặt , Lý Ân Phàm mang theo Lưu Bang đi vào trước điện Kim Loan hùng vĩ quảng trường , chỉ vào phía trên cung điện , hướng về phía Lưu Bang nói .\n“ Hiện đại phim truyền hình còn rất nhiều tiểu thuyết , cho là Kim Loan điện là minh thanh hai triều vào triều địa phương .”\n“ Kỳ thực , nơi này , chủ yếu dùng hoàng đế đăng cơ , đại hôn , sắc lập hoàng hậu chờ trọng đại nghi thức , thực tế số lần sử dụng rất ít .”\n“ Minh sơ hoàng đế tại Phụng Thiên môn ( Nay Thái Hòa môn ) cử hành “ Ngự môn chấp chính ”, trực tiếp tại bên ngoài xử lý chính vụ , hiệu suất cao hơn .”\n“ Cũng chính là chúng ta đi trước qua Phụng Thiên môn .”\n“ Thanh triều hoàng đế , chủ yếu tại Càn Thanh môn\n“ Sau đó là Dưỡng Tâm điện .”\n“ Những địa phương này , chúng ta đợi chút nữa đều có thể nhìn thấy .”\nNghe xong Lý Ân Phàm giới thiệu , Lưu Bang gật đầu một cái , sau đó thoải mái nhàn nhã đi tới Kim Loan điện .\n...\nMinh triều .\nVĩnh Lạc bảy năm .\n“ Đây chính là Thuận Thiên phủ đang xây dựng hoàng cung ?”\nNghe được màn trời nói cái này hoàng cung là Vĩnh Lạc năm thứ tư bắt đầu xây dựng , Chu Lệ cùng Chu Cao Sí hai người liếc mắt nhìn nhau , sau đó đều nhấc lên lòng hiếu kỳ .\n“ Không phải , cái này Thanh triều , không có chính mình hoàng cung sao ?!”\nChu Lệ lại nghe được màn trời nói cái này đời sau Thanh triều hoàng cung cũng tại này , lập tức cũng có chút chê .\n“ Cũng còn tốt , phụ thân , ít nhất giữ lại .”\nChu Cao Sí ngược lại là thật lạc quan , nếu như Thanh triều một lần nữa tu kiến cung điện , chỉ sợ thực sẽ đem bọn hắn xây dựng hoàng cung trực tiếp tháo bỏ .\nDù sao tu kiến hoàng cung lúc tài liệu , có rất nhiều là tài liệu trân quý .\n“ Ai ...”\nNhìn một chút , Chu Lệ nhẹ giọng thở dài một hơi .\n“ Lão đại , cuối cùng liền một tòa hoàng cung , trở thành chúng ta tồn tại chứng minh ,”\nNghe được câu này , Chu Cao Sí sững sờ , sau đó trầm mặc lại .\nĐúng vậy a , cuối cùng liền một tòa hoàng cung , trở thành lớn minh cuối cùng tồn tại chứng minh .\nNhững thứ khác đâu ? Đều tiêu tan ở bụi bặm lịch sử bên trong .\nChu Lệ cùng Chu Cao Sí hai người , cứ như vậy trầm mặc nhìn xem màn trời phía trên , Lý Ân Phàm cùng Lưu Bang đi dạo .\n......', 'output\\mp3\\Màn Trời Quyền Lực Diễn Biến Cùng Truyền Thừa\\0090_Thứ 89 chương Tồn tại chứng minh.mp3', '2026-09-01T23:47:50.502721+00:00', 'completed', 'completed', 6926, 6926),
	(96, 7, '7654261065978479129', 91, 'Thứ 90 chương Không đi', 'Thứ chương Không đi\nHiện đại thời không .\n“ Cái này không tệ , tiên sinh !”\nLưu Bang học Lý Ân Phàm dáng vẻ , cuốn lên một mảnh thịt vịt nướng , bỏ vào trong miệng chậm rãi nhấm nuốt , toàn bộ nuốt xuống sau đó , mới hài lòng nói .\n“ Thứ này , cũng là Chu Lệ dời đô lúc , từ Nam Kinh mang tới .”\nBưng lên đồ uống , uống một ngụm sau , Lý Ân Phàm mới dùng tiếp tục nói :\n“ Món ăn này truyền thuyết tại Nam Bắc triều thời điểm , liền đã xuất hiện .”\n“ Nhưng chân chính hình thành sao ? Là tại Minh triều sơ kỳ .”\n“ Minh triều thứ nhất hoàng đế , Chu Nguyên Chương tại làm hoàng đế thời điểm , vô cùng yêu thích ăn thịt vịt nướng , sau đó ngự trù chuyên môn nghiên cứu chế tạo hầm lô thịt vịt nướng .”\n“ Không sai biệt lắm chính là loại kia !”\nLý Ân Phàm chỉ vào cửa tiệm , lò kia bên trong từng hàng thịt vịt nướng .\n“ Chu Lệ dời đô lúc , đem Nam Kinh ngự trù cùng thịt vịt nướng kỹ thuật toàn bộ mang tới , lúc này mới có vịt quay bắc kinh\n“ Cũng chính là chúng ta bây giờ ăn loại này .”\n“ Đương nhiên , khẩu vị đi qua mấy trăm năm mới có bây giờ hương vị .”\n“ Đến nỗi Minh triều lúc hương vị là dạng gì ? Không biết ...”\nNói xong , Lý Ân Phàm lại cuốn lên một mảnh thịt vịt nướng , thỏa mãn bỏ vào trong miệng .\n“ Những thứ này đời sau hoàng đế thật hưởng thụ ...”\nNhìn xem trước mặt bày ra tinh xảo đĩa , Lưu Bang có chút cảm thấy buồn cười .\nCái này tại Hán triều , đặc biệt là Hán sơ thời điểm , hương vị ? Trải qua còn đi là được .\nĂn trên cơ bản cũng là tùy tiện nấu nấu , ngược lại hương vị là cũng không khá hơn chút nào .\nCũng chính là đến hậu thế , Lưu Bang mới phát giác được chính mình mấy thập niên này không có uổng phí sống .\nTới mấy ngày , mỗi cơm đều ăn thứ không giống nhau , Lưu Bang thật là cảm thấy quá sung sướng !\n“ Quý ca , ngày mai muốn cùng ta đi đài truyền hình thu tiết mục sao ?”\n“ Đài truyền hình thu tiết mục ?”\n“ Chính là Thủy Hoàng cuối cùng cùng với ngươi cùng nhau chỗ kia ?”\nLý Ân Phàm gật đầu thừa nhận , sau đó mang theo hỏi thăm ánh mắt nhìn về phía hắn .\n“ Ta sao ? Thì không đi được !”\n“ Nếu như là tuổi nhỏ hơn một chút , ta sẽ cùng ngươi đi , đến nỗi bây giờ sao ?”\nLưu Bang không câu chấp cười cười , sau đó nhẹ nói :\n“ Không mấy năm sống khỏe , rất nhiều chuyện ta cũng không muốn xen vào nữa .”\n“ Muốn quản người , bọn hắn từ màn trời liền có thể trông thấy .”\nLý Ân Phàm nghe được đáp án , tựa hồ cũng chẳng suy nghĩ gì nữa , bởi vì đây mới là hắn trong ấn tượng Lưu Bang .\n“ Vậy ngày mai ta để cho người ta mang ngươi lại đi chơi đùa ? Lúc buổi tối , ngươi trở lại , đến lúc đó đem đồ vật đều dẫn đi ?”\n“ Tốt như vậy ! Tốt như vậy !”\nNghe được Lý Ân Phàm bảo ngày mai lại để cho người khác mang chính mình đi chơi , Lưu Bang lập tức vui vẻ ra mặt .\nHắn có thể rất hài lòng cuộc sống bây giờ , đi khắp nơi đi , xem từ trước tới nay chưa từng gặp qua cảnh sắc .\nSau đó thì sao ? Đói bụng lại ăn ăn chính mình chưa bao giờ ăn qua mỹ thực .\nNghĩ tới đây , Lưu Bang bưng lên Cocacola , trực tiếp uống một hớp lớn .\nHắn cũng quá hài lòng cái này tiểu nước ngọt !\n...\nĐại hán .\nHán bảy năm .\nNhìn xem màn trời phía trên Lưu Bang dáng vẻ , phía dưới rất nhiều đại thần cũng không có cách nào nhìn nhau một cái .\nBọn hắn có thể làm sao ? Đây là bọn hắn lựa chọn hoàng đế , bằng không thì còn có thể làm sao đâu ?\nTiêu Hà chỉ là thở dài một hơi , sau đó nhìn về phía trên đài Lữ Trĩ , chắp tay cung kính nói :\n“ Bệ hạ , xin hỏi lựa chọn mười người đến hậu thế , chọn xong chưa ?”\nCó thể có người nhìn thấy cái này vô cùng nghi hoặc , xưng hô hoàng hậu , cũng xưng hô bệ hạ sao ?\nĐúng vậy , đặc biệt là tại Tây Hán , nếu như hoàng hậu hoặc Hoàng thái hậu lâm triều nhiếp chính , thay thế hoàng đế xử lý triều chính , cũng có thể được tôn xưng là bệ hạ .\nMà bây giờ Lưu Bang thân ở hậu thế , hoàng hậu Lữ Trĩ nhiếp chính , đương nhiên là được tôn xưng là bệ hạ .\nĐến nỗi Hoàng hậu nương nương xưng hô thế này ? Dậy sớm nhất bắt nguồn từ Tống triều , đại quy mô xưng hô nguyên , minh , xong thời điểm mới có .\n“ Đã chọn xong , để bọn hắn vào a ...”\nLữ Trĩ nhẹ giọng hướng về phía bên cạnh chờ lấy một vị cung nữ nói .\nSau đó tên này cung nữ cung kính ra khỏi .\nKhông đầy một lát , Lữ Trĩ chọn xong mười người liền đi đi vào .\n“ A ? Trương Lương ?!”\nNhìn xem đứng đầu một người , Tiêu Hà lập tức lên tiếng kinh hô .\nHắn liền không sợ đến hậu thế , bị Tần triều những người kia chém chết ?\nMà Trương Lương đâu ? Hắn tựa hồ nghe được Tiêu Hà âm thanh , chỉ có thể là bất đắc dĩ liếc Tiêu Hà một cái .\nTiêu Hà cho là mình rất muốn đi sao ? Nhưng chính là bởi vì không có trấn tràng người , mới khiến cho chính mình đi .\nDù sao ...\nTrương Lương quay đầu liếc mắt nhìn đi theo phía sau Lưu Doanh , chỉ có thể là bất đắc dĩ lắc đầu .\n“ Chờ đã !”\nLúc người cuối cùng đi vào , Tiêu Hà thần sắc trực tiếp ngưng kết .\nHắn thấy được ai ? Màn trời nói tới , Hán văn đế Lưu Hằng !!!\nLữ hậu vậy mà không đem hắn đã giết ?!\nNghĩ tới đây , Tiêu Hà tựa hồ cảm nhận được có người đang nhìn chính mình , lập tức cúi đầu xuống , cố gắng quản lý biểu lộ .\nMà giờ khắc này , không chỉ là hắn , rất nhiều đại thần , đều đang nỗ lực quản lý nét mặt của mình .\n“ Làm sao có thể ?”\nTiêu Hà lúc này nội tâm tựa hồ nhận lấy trùng kích cực lớn , Lữ Trĩ không đem Lưu Hằng giết coi như xong , lại còn để cho hắn đi theo Trương Lương cùng Lưu Doanh cùng nhau đến hậu thế ?\nĐây là cái gì ma huyễn bày ra ?\nMà lúc này ...\nĐát ... Đát ... Đát ...\nMột hồi tiếng bước chân chậm rãi đi đến .\nHết thảy mọi người nhìn về phía cửa ra vào , đều lộ ra biểu tình nghi hoặc , đây là ai ? Mười người không phải đã đầy sao ?\nKhi bóng người lúc xuất hiện , biểu tình của tất cả mọi người lại đọng lại .\n“ Hàn Tín ...”\nTiêu Hà khẽ thở dài một tiếng , sau đó tựa hồ cảm giác không mặt mũi thấy hắn , chỉ có thể quay đầu một lần nữa nhìn về phía trên đài Lữ Trĩ .\nMà Lữ Trĩ đâu ?\nChỉ là mặt không thay đổi nhìn xem Hàn Tín , nhẹ nói :\n“ Hoài Âm hầu thỉnh hòa Trương Lương bọn người đứng chung một chỗ .”\nHàn Tín sao cũng được cười cười , sau đó thoải mái nhàn nhã đi đến Trương Lương đám người bên cạnh .\nHắn bây giờ là vô cùng không quan trọng , ngược lại đại hán này đã cùng chính mình không có bất kỳ quan hệ gì , ngày mai đến hậu thế sau đó , chính mình cũng biết một mực tại hậu thế sinh hoạt .\n“ Ai ...”\nNhìn thấy một màn này , rất nhiều đại thần đều tại nội tâm thở dài một hơi .\n...\nĐại hán .\nNguyên thú 4 năm .\n“ Đến lúc đó về phía sau thế mười người lựa chọn ai đây ?”\nLưu Triệt đột nhiên nghĩ đến vấn đề này , vuốt vuốt chòm râu .\nHắn bây giờ là không lo lắng đến người đời sau có hay không chính mình , màn trời phía trước đều đem chiến công của mình nói ra , còn sợ không có chính mình sao ?\nBây giờ chủ yếu suy tính , chính là đến đời sau mười người , lựa chọn ai ?\n“ Vệ Thanh là nhất định muốn chọn !”\nCái này không hề nghi ngờ , tại Lưu Triệt xem ra , ai cũng có thể không đi , nhưng Vệ Thanh là nhất định phải đi .\n“ Đến lúc đó đi hậu thế , nhờ cậy một chút vị tiên sinh kia , vì Vệ Thanh kiểm tra thân thể một chút ...”\n“ Tiếp đó , chính là trừ bệnh ...”\nGiờ khắc này , Lưu Triệt không biết vì cái gì , trong lòng có chút không thoải mái .\nTựa hồ sẽ phát sinh một chút vượt qua bản thân tất cả dự liệu sự tình .\nCái này một cỗ cảm giác , từ nghĩ đến Hoắc Khứ Bệnh bắt đầu , vẫn vờn quanh tại Lưu Triệt nội tâm .\n“ Tuyển mấy vị công chúa a ...”\nLắc đầu , Lưu Triệt lại bắt đầu tính toán những người khác .\n“ Phía trước màn trời biểu thị dương tư công chúa học tập , đại hán cũng muốn học ...”\nNhớ tới phía trước màn trời truyền tại bệnh viện tràng cảnh , Lưu Triệt lại tính cả mấy vị công chúa .\n“ Tang Hoằng Dương đâu ?!”\nNhớ tới Tang Hoằng Dương , túi tiền của mình tử , Lưu Triệt trầm mặc một hồi .\n“ Muốn để hắn đi hậu thế học tập nửa năm , sau đó có thể tốt hơn quản lý trẫm túi tiền ...”\nLưu Triệt lại đem Tang Hoằng Dương tính cả .\n“ Không sai biệt lắm ...”\n“ Mấy thiên , đến vào triều thời điểm , lại đem nhân số triệt để cố định xuống a .”\n......', NULL, '2026-09-02T00:14:35.686635+00:00', 'completed', 'processing', 7871, 0),
	(97, 7, '7654595299918234137', 92, 'Thứ 91 chương Kéo cờ nghi thức', 'Thứ chương Kéo cờ nghi thức\nHiện đại thời không .\nSáng sớm bốn điểm , thủ đô thiên còn tảng sáng , Lý Ân Phàm đem Lưu Bang kêu lên , tùy tiện ăn một điểm bữa sáng , liền mang theo hắn hướng về đại quảng trường đuổi .\n“ Tiên sinh , chúng ta cái này muốn đi cái nào ?”\nLưu Bang trong mắt còn có một số mê mang , đêm qua chơi quá lâu , ngủ quá muộn .\nMà Lý Ân Phàm , lại đem hắn đánh thức quá sớm .\n“ Dẫn ngươi đi xem kéo cờ nghi thức ...”\n“ Mục đích sao ? Cũng là để cho màn trời phía dưới những người kia xem , vì cái gì ta phía trước sẽ cho rằng , tư tưởng chiến công vĩnh viễn là xếp hạng thứ nhất .”\nNgoại trừ khai cương khoách thổ , Lý Ân Phàm từ rất sớm đã bắt đầu cho rằng , “ Tư tưởng chiến công ” Xếp hạng thứ nhất .\nKỳ thực theo Lý Ân Phàm nội tâm tới nói , “ Tư tưởng chiến công ” Kỳ thực cùng khai cương khoách thổ chiến công là đặt song song .\n“ Kéo cờ nghi thức ?”\nLưu Bang nghe được cái tên này , hơi nghi hoặc một chút , nhưng vẫn là nhắm mắt lại nghe Lý Ân Phàm an bài .\nMột lát sau , xe taxi đến .\n“ Đi thôi ! Chúng ta đã đến !”\nLý Ân Phàm mang theo Lưu Bang xuống xe , từ từ hướng về quảng trường đi đến .\nLúc này đại quảng trường , đã có rất nhiều người , đều đang đợi lấy kéo cờ nghi thức bắt đầu .\nChung quanh thanh âm huyên náo tại Lưu Bang bên tai vang lên , Lưu Bang càng ngày càng nghi hoặc , Lý Ân Phàm đem chính mình đưa đến nơi này làm gì ?\n“ Chuẩn bị bắt đầu ! Đi !”\nPhía trước khai phóng , Lý Ân Phàm lập tức mang theo Lưu Bang chạy !\nLưu Bang thấy thế , lập tức đi theo sau lưng Lý Ân Phàm .\nChạy một hồi , hai người đều chạy tới lan can chỗ , Lý Ân Phàm quan sát , hàng thứ nhất , vừa vặn có thể trông thấy .\n“ Hô !!”\n“ Tiên sinh , đây rốt cuộc thế nào ?”\nLưu Bang quay đầu liếc mắt nhìn sau lưng , phát hiện càng ngày càng nhiều người đều chạy tới , đem hắn giật mình kêu lên .\n“ Đợi chút nữa ngươi sẽ biết , lập tức sẽ bắt đầu !”\nLý Ân Phàm giơ tay lên liếc mắt nhìn đồng hồ .\nTrước khi đến hắn liền đã điều tra , hôm nay kéo cờ nghi thức là bắt đầu .\nBây giờ cách bắt đầu , còn có một phút .\n“ Cái này cũng là ta lần thứ nhất nhìn kéo cờ nghi thức , trước đó vốn là nghĩ đến xem , nhưng đều bởi vì quá sớm , dậy không nổi liền từ bỏ .”\n“ Tốt , tới !”\n“ Tới !” “ Tới !”\nĐám người chung quanh cũng đều đang kinh ngạc thốt lên cái gì , sau đó không khí từ ồn ào , lập tức lâm vào yên tĩnh .\nĐạp ! Đạp ! Đạp ! Đạp !\nNghe được thanh âm này , Lý Ân Phàm cả người đều lập tức nghiêm túc hơn .\nĐám người chung quanh cũng lâm vào yên tĩnh , chuyên chú nhìn về phía trước .\nGiờ khắc này , Lưu Bang nhíu mày lại , theo ánh mắt của mọi người nhìn về phía âm thanh tới chỗ .\n‘ Đây là ?’\nLưu Bang không có lên tiếng , bỗng nhiên nhìn xem một đám binh sĩ từ bên trong chỉnh tề đi ra , đứng đầu tên lính kia , thần sắc trang trọng tay cầm một lá cờ .\nLưu Bang quay đầu liếc mắt nhìn , phát hiện tất cả mọi người đều an tĩnh nhìn xem mặt cờ xí kia .\nBầu không khí lâm vào ngưng kết bên trong , tất cả mọi người đều nín thở ngưng thần nhìn xem người đứng đầu hàng trong tay binh lính cờ xí .\nLúc này , Lưu Bang bên tai , chỉ có thể nghe được đạp đạp đạp chỉnh tề tiếng bước chân .\nCũng không biết qua bao lâu ...\nLưu Bang trông thấy đám binh sĩ kia đi đến một tòa lan can chỗ .\nÂm nhạc , trong lúc đó đột nhiên vang lên !!\nLưu Bang chung quanh , bao quát Lý Ân Phàm ở bên trong , tất cả mọi người đều theo âm nhạc hát lên .\n“ Đứng lên ...”\nGiờ khắc này , Lưu Bang bỗng nhiên cảm thấy cả người tóc gáy dựng lên , nội tâm lập tức nhấc lên .\nMà đặt mình vào tại trong đám người này , Lưu Bang bỗng nhiên không hiểu cảm thấy chính mình vô cùng nhỏ bé .\nLưu Bang không biết cảm giác này vì cái gì mà đến , nhưng hắn nghe chung quanh tất cả mọi người đều cùng kêu lên hát ca khúc , mà chính mình tựa hồ đứng tại bọn hắn mặt đối lập .\nTrầm mặc nhìn xem kéo cờ nghi thức , Lưu Bang tâm tình càng ngày càng nặng .\nKéo cờ nghi thức kết thúc .\nĐám người bắt đầu từ từ tản ra .\n“ Đi thôi , quý ca , kết thúc .”\n“ Tiên sinh , đây là cái gì ?”\nLưu Bang trước tiên hỏi nghi ngờ trong lòng .\n“ Mặt cờ xí kia , là chúng ta quốc kỳ , mà ca sao ? Là chúng ta quốc ca ...”\nQuốc kỳ ? Quốc ca ?\nLưu Bang tựa hồ ý thức được cái gì , chân mày nhíu rất căng .\n“ Đây chính là tiên sinh ngươi nói bên trên tư tưởng sao ?”\nLý Ân Phàm không nói chuyện , cũng không có giảng giải .\nCó thể nói , hoặc có lẽ là muốn nói , kỳ thực tại vừa rồi , một màn kia màn chuyện phát sinh , liền đã nói .\nLoại vật này , không có cách nào giảng giải !\nCó thể ý thức đến , hắn sẽ phát hiện đây rốt cuộc có bao nhiêu lợi hại .\nMà không ý thức được , ngươi nói với hắn nhiều hơn nữa , giải thích nhiều hơn nữa , kỳ thực đều không có tác dụng gì .\nLoại chuyện này , chỉ có thể đi cảm thụ , đi tự mình cảm thụ !\nCái này cũng là vì sao Lý Ân Phàm mang theo Lưu Bang sớm như vậy rời giường , chạy tới hiện trường nhìn kéo cờ nghi thức .\nTrên TV hoặc trên internet mặc dù có thể trông thấy , nhưng từ đầu đến cuối thiếu loại kia trọng yếu nhất tự mình cảm thụ .\n“ Trong lịch sử , chỉ có một cái triều đại loáng thoáng chạm đến tầng này .”\n“ Cái này triều đại chính là Đường triều .”\n“ Công nguyên năm muộn thời nhà Đường kỳ , phượng tường Tiết Độ Sứ Trịnh Điền tại trên yến hội tấu vang dội 《 Tần Vương phá trận Nhạc 》, kích phát tướng sĩ đấu chí , đánh bại khởi nghĩa Hoàng Sào quân , vì Đại Đường vương triều kéo dài gần ba mươi năm quốc vận\n“ Bài hát này không chỉ có là Đường Thái Tông Lý Thế Dân thời kỳ quân ca , càng tại Đường triều nguy vong trước mắt trở thành ngưng kết lòng quân trụ cột tinh thần , lịch sử xưng “ Đuôi rồng pha đại thắng\n...\nĐường triều .\nTrinh Quán bảy năm .\nLý Thế Dân nghe được 《 Tần Vương phá trận Nhạc 》 kéo dài ba mươi năm quốc vận , cả người lập tức ngây ngẩn cả người .\n“ Tần Vương phá trận nhạc ?!”\nTrong lúc đó nghe được tin tức này , Lý Thế Dân lập tức có chút hoảng hốt , mà hoảng hốt sau đó ...\n“ Thì ra là thế ...”\nLập tức , Lý Thế Dân lập tức liền đã hiểu , vì cái gì Lý Ân Phàm phải mang theo Lưu Bang tại sớm như vậy thời gian chạy tới nhìn kéo cờ nghi thức .\nVốn đang trong giấc mộng hắn , bị thái giám kêu lên , còn vô cùng nghi hoặc , màn trời đây vẫn là lần thứ nhất tại sớm như vậy thời gian mở ra , rốt cuộc xảy ra chuyện gì ?\n“ Tần Vương phá trận nhạc ...”\nLại thì thầm năm chữ này , Lý Thế Dân bỗng nhiên nở nụ cười , thoải mái cười to , cả người cũng dị thường cao hứng .\nThì ra bọn hắn vậy mà loáng thoáng chạm đến hậu thế nói tầng kia .\n...\nMinh triều .\nVĩnh Lạc bảy năm .\nChu Lệ cùng Chu Cao Sí đều trầm mặc nhìn xem màn trời .\nCũng không biết thời gian qua bao lâu .\nChu Lệ bỗng nhiên mở miệng , ngữ khí ngưng trọng nói :\n“ Ngưng kết nhân tâm ...”\nBên cạnh Chu Cao Sí trầm mặc gật đầu một cái , biểu thị tán đồng .\n“ Hơn nữa , màn trời còn nói đến Tần Vương phá trận nhạc ...”\n“ Trừ cái đó ra , phụ thân , ngươi nghe rõ ràng bọn hắn hát từ sao ?”\nNghe nói như thế , Chu Lệ vốn là xem nhẹ qua cái vấn đề này , nhưng vẫn là gật đầu một cái .\nNếu như hậu thế thực sự được đến quốc phá núi sông hoàn cảnh lúc , hát lên bài hát này , đến cùng có thể ngưng kết người bao lớn tâm ?\nChu Lệ cùng Chu Cao Sí không biết .\nNhưng bọn hắn biết một sự kiện , bài hát này , chính là hậu thế “ Vương triều ” “ Một cái mạng ”.\n“ Ta trước đó làm sao lại không nghĩ tới đâu ?”\nLúc này , Chu Lệ bỗng nhiên trọng trọng hít một tiếng .\nMình trước kia vì cái gì cũng không có nghĩ tới ? Tần Vương phá trận nhạc kéo dài ba mươi năm Đường triều quốc vận chuyện , còn xuất hiện tại sách sử phía trên .\nChu Lệ cùng Chu Cao Sí cũng đều là thấy qua .\nNhưng bọn hắn vậy mà đều không muốn lấy đi học tập , đi “ Trò giỏi hơn thầy ”.\nVậy mà trực tiếp không để mắt đến ?!\n“ Tác dụng quá lớn ...”\n......', NULL, '2026-09-02T00:14:40.654714+00:00', 'completed', 'processing', 7603, 0),
	(98, 7, '7654596538236158489', 93, 'Thứ 92 chương Điểm tốt?', 'Thứ chương Điểm tốt ?\nHiện đại thời không .\n“ Vậy chúng ta liền trực tiếp bắt đầu đề tài của hôm nay a .”\nGhi âm trong sảnh , Lý Ân Phàm cùng hắn ba cái tiểu đồng bạn , Trần Xuyên Phú , Ngụy Gia , Lương Phong ngồi ở trên đài .\nĐến nỗi Lưu Bang , tại tiến lớn quần cộc phía trước , Lý Ân Phàm liền cho bên kia phát một cái tin nhắn , bên kia trực tiếp tới người , đem Lưu Bang mang đến đi chơi .\n“ Trước đây tiết mục , chúng ta nói qua Tần triều , cũng đã nói Tần Thuỷ Hoàng Doanh Chính quyền lực lớn tiểu cùng với truyền thừa cùng diễn biến .”\n“ Vậy hôm nay , chúng ta liền nói một chút Hán Thái tổ Cao Hoàng Đế Lưu Bang !”\n“ Chờ đã !”\nLúc này , Ngụy Gia bỗng nhiên nhấc tay , nhìn xem Lý Ân Phàm đưa ra một vấn đề .\n“ Hán Thái tổ Cao Hoàng Đế ? Không phải Hán Cao Tổ sao ?”\n“ Vấn đề này ta đến trả lời a !”\nLương Phong cầm ống nói lên , thoải mái ngồi ở trên ghế sa lon , nhìn xem Ngụy Gia nói :\n“ Lưu Bang miếu hiệu , là Thái tổ , mà Cao Hoàng Đế , là hắn thụy hào .”\n“ Chính xác cách gọi , chính là Lý Ân Phàm nói tới : Hán Thái tổ Cao Hoàng Đế .”\n“ Hán Cao Tổ cái này một cái xưng hô , là Tư Mã Thiên tại 《 Sử Ký 》 bên trong viết một thiên 《 Cao Tổ Bản Kỷ 》, bên trong trực tiếp gọi Lưu Bang “ Cao tổ ”, quyển sách này lực ảnh hưởng quá lớn , đại gia liền theo gọi như vậy .”\n“ Hơn nữa “ Hán Cao Tổ ” Ba chữ so “ Hán Thái tổ Cao Hoàng Đế ” Ngắn nhiều , bình thường nói chuyện , viết văn đều dễ dàng hơn , dần dà liền thành quen thuộc .”\nChờ Lương Phong nói xong , ngồi bên cạnh Trần Xuyên Phú bỗng nhiên mở miệng hỏi :\n“ Hỏi các ngươi một vấn đề , tại Đường Thái Tông Lý Thế Dân phía trước , Thái Tông cọc tiêu là Hán văn đế Lưu Hằng .”\n“ Mà Đường Thái Tông Lý Thế Dân sau đó , Thái Tông cọc tiêu liền thành Đường Thái Tông Lý Thế Dân .”\n“ Vậy ngươi biết , khai quốc hoàng đế cọc tiêu là ai chăng ?”\nNgụy Gia không biết đáp án của vấn đề này , nhưng ở cái này ghi âm sảnh , hôm nay vừa vặn giảng đến Lưu Bang , Trần Xuyên Phú hỏi lên vấn đề này .\n“ Không phải là Lưu Bang a ?”\nTrần Xuyên Phú , Lý Ân Phàm , Lương Phong 3 người đều rất nghiêm túc gật đầu một cái .\n“ Đúng vậy , chính là Lưu Bang .”\n“ Đời sau vô số người đều biết Thái Tông cọc tiêu , ngoại trừ Hán văn đế Lưu Hằng , chính là Đường Thái Tông Lý Thế Dân .”\n“ Nhưng cũng có thể đại đa số người là không biết , khai quốc hoàng đế cọc tiêu là Hán Thái tổ Cao Hoàng Đế Lưu Bang ...”\nSau đó , Trần Xuyên Phú tiếp tục giải thích nói :\n“ Minh triều khai quốc hoàng đế , Chu Nguyên Chương , Thanh triều khai quốc hoàng đế , Nỗ Nhĩ Cáp Xích .”\n“ Bọn hắn tại sau khi chết cũng là bị truy tôn vì “ Thái tổ Cao Hoàng Đế ”, đây chính là bắt chước Lưu Bang quy cách .”\n“ Trong lịch sử còn có Nam Tề tiêu đạo thành , Nam Đường Lý Biện mấy vị hoàng đế cũng dùng qua “ Cao Hoàng Đế ” Cái này thụy hào , nhưng danh khí đều không Lưu Bang lớn .”\n“ Cái này thụy hào sớm đã nhất là từ Lưu Bang bắt đầu , người phía sau cũng là dùng tiêu chuẩn của hắn tới định .”\n“ Cũng liền nói , hậu nhân cảm thấy ngươi đạt đến Lưu Bang tiêu chuẩn , mới có thể cho ngươi bên trên “ Thái tổ Cao Hoàng Đế ”.”\nNhững lời này , có chút xung kích Ngụy Gia tam quan , hắn thật sự là không nghĩ tới , Lưu Bang tại trong khai quốc hoàng đế , lại là lợi hại như vậy ?\nTiêu chuẩn đều theo hắn tới ?\n“ Hiện đại rất nhiều người cho là , khai quốc hoàng đế cọc tiêu hẳn là Tần Thuỷ Hoàng Doanh Chính ?”\n“ Đây thật ra là người hiện đại mới bắt đầu cho là .”\n“ Tại thượng thế kỷ thời năm 1970 phía trước , ngủ địa hổ Tần Giản còn không có khám phá ra phía trước , Tần triều trong lịch sử đánh giá một mực rất thấp .”\n“ Cũng chính là chúng ta hiện đại , từ mọi phương diện bắt đầu đánh giá Tần triều , từ thiên về quy định đặt nền móng cùng lịch sử lực ảnh hưởng , mới cho rằng Tần Thuỷ Hoàng Doanh Chính là thứ nhất cọc tiêu .”\n“ Thời gian khác , Lưu Bang vẫn luôn là khai quốc hoàng đế bên trong cọc tiêu .”\nNói đến đây , Trần Xuyên Phú dừng lại một chút , xấp xếp lời nói một chút sau , tiếp tục nói :\n“ Hán triều trong lịch sử , cũng là đánh giá đệ nhất vương triều .”\n“ Hán triều hoàng đế sao ? Kỳ thực cũng là hậu thế rất nhiều vương triều hoàng đế học tập tấm gương ...”\nSau đó , Trần Xuyên Phú bắt đầu từng cái nói những hoàng đế kia tên .\n“ Khai quốc hoàng đế cọc tiêu , Hán Thái tổ Cao Hoàng Đế Lưu Bang .”\n“ Thái Tông cọc tiêu , Hán văn đế Lưu Hằng .”\n“ Võ đế cọc tiêu , Hán Vũ Đế Lưu Triệt .”\n“ Trung hưng chi Quân Tiêu Can , các ngươi đoán xem là ai ?”\nTiếng nói vừa dứt , Lương Phong cầm ống nói lên liền nói :\n“ Trung hưng chi Quân Tiêu Can , Hán Quang Võ Đế Lưu Tú .”\nTrần Xuyên Phú cùng Lý Ân Phàm đều gật đầu một cái .\n“ Có thể có người sẽ rất nghi hoặc , tại sao là bốn vị này Đế Vương ?”\n“ Bởi vì bốn vị này quân chủ , chính là rất điển hình ...”\n“ Khai sáng , đặt vững , sáng lập , trung hưng !”\nNghe được cái này , Ngụy Gia bừng tỉnh đại ngộ , thì ra là như thế .\n“ Trong đó Hán Vũ Đế Lưu Triệt trong lịch sử đánh giá là thuộc về lưỡng cực phân hoá , khác ba vị , cũng là tuyệt đại đa số người đều vô cùng đồng ý .”\nNói xong , Trần Xuyên Phú thả ra trong tay ống nói .\nThấy vậy tình huống , Ngụy Gia hỏi nghi ngờ trong lòng đã lâu vấn đề .\n“ Vậy tại sao Hán Thái tổ Cao Hoàng Đế Lưu Bang , thanh danh của hắn bây giờ mới hơi tốt một chút như vậy ?”\n“ Vấn đề này vẫn là ta tới giải đáp a .”\nTrần Xuyên Phú cầm ống nói lên , nhìn xem Ngụy Gia giải thích nói :\n“ Đầu tiên , ngươi vấn đề này kỳ thực có một chút sai lầm , trong lịch sử , Hán Thái tổ Cao Hoàng Đế Lưu Bang đánh giá , vẫn luôn cực kì tốt .”\n“ Nhưng đối hắn đánh giá , là lúc nào bắt đầu không xong đâu ?”\n“ Là ba mươi năm trước !”\n“ Bởi vì một số người , đều tại tập trung công kích Hán triều , đặc biệt là khai quốc chi quân Lưu Bang cùng Hán Vũ Đế Lưu Triệt .”\n“ Sau đó , đồng dạng tại công kích Hán Tuyên Đế Lưu Tuần , cùng với Hán Quang Võ Đế Lưu Tú .”\n“ Vì sao lại công kích bọn hắn ?”\nNói đến đây , Trần Xuyên Phú không có nói thẳng ra đáp án , mà là đứng lên , đi đến sau lưng để bảng đen địa phương .\nCầm lấy phấn viết , ở phía trên viết ba chữ .\nQuốc hiệu : Hán .\n“ Lần này hiểu vì sao lại tập trung công kích Hán triều đi ?”\n“ Đến nỗi Tần triều ? Không cần công kích , Tần triều trong lịch sử đánh giá , vẫn luôn không thể nào cao .”\n“ Đường triều tùy tiện hai câu nói liền có thể triệt để làm thấp đi , trực tiếp từ huyết thống vào tay .”\n“ Mà Hán triều , mới là công kích trọng điểm .”\n“ Hán triều trong lịch sử đánh giá quá tốt rồi , mà hắn quốc hiệu , liền lại trở thành nhất định phải công kích trọng điểm .”\n“ Ở trong đó tập trung công kích Lưu Bang điểm là cái gì ? Các ngươi có biết không ?”\nNgụy Gia có ấn tượng , nhưng ở lúc này , lại lập tức nói không nên lời .\nNghĩ một hồi , Ngụy Gia lắc đầu .\n“ Công kích Lưu Bang là lưu manh xuất thân , hơn nữa đâu ? Còn đồ sát công thần .”\n“ Đặc biệt là xuất thân của hắn , thì càng là trọng điểm , bỏ rơi vợ con , liền lại là trọng điểm công kích .”\n“ Đây chính là điển hình cái gì ? Từ chính trị cùng trên quân sự công kích không đến hắn , cũng chỉ có thể từ thân người đi công kích hắn , làm thấp đi hắn .”\nNói xong lời nói này sau , Trần Xuyên Phú thả xuống phấn viết , vô cùng nghi hoặc nhìn camera nói :\n“ Một cái hoàng đế ! Ngươi từ xuất thân đi công kích hắn ? Sau đó thì sao ? Còn từ bỏ rơi vợ con đi công kích hắn ?”\n“ Nói thật , chuyện này chỉ có thể lừa gạt một chút người không hiểu .”\n“ Tại thành thục chính trị gia đến xem , cái này rõ ràng là Lưu Bang điểm tốt !”\n“ Hiện đại những công kích kia Lưu Bang điểm ?”\n“ Càng là trong lịch sử vô số hoàng đế hẳn là học tập điểm !”\n“ Cho nên , từ rất sớm bắt đầu , ta liền biết trên mạng còn có phía trước những công kích kia Lưu Bang xuất thân cùng với đồ sát công thần vân vân người , đến cùng muốn lắc lư chính là ai .”\n......', NULL, '2026-09-02T00:14:45.651962+00:00', 'completed', 'pending', 7651, 0),
	(99, 7, '7655030299968946713', 94, 'Thứ 93 chương Chung tình', 'Thứ Chương Cộng Tình\nHiện đại thời không .\n“ Kỳ thực ngươi chỉ cần đi lên nhất định tầng cấp , hay là hiểu qua một vài thứ .”\n“ Ngươi liền sẽ phát hiện một sự kiện , hiện đại rất nhiều công kích hoàng đế điểm , kỳ thực bọn hắn muốn là cái gì ?”\n“ Là chung tình !”\n“ Nhưng ngươi cùng hoàng đế loại này chính trị sinh vật chung tình ? Ngươi đang suy nghĩ gì ?”\nTrần Xuyên Phú bởi vì gia đình nguyên nhân , thật sớm liền biết một ít chuyện , cho nên hắn thấy , trên mạng rất nhiều công kích những hoàng đế kia điểm , kỳ thực đều rất không hiểu thấu .\n“ Đầu tiên điểm thứ nhất , từ xuất thân công kích Lưu Bang , cho rằng Lưu Bang là lưu manh xuất thân , liền bởi vậy hết sức làm thấp đi hắn .”\n“ Nhưng cái này không phải là điểm tốt sao ?”\n“ Một kẻ lưu manh đều có thể khởi binh , tiếp đó lên làm hoàng đế .”\n“ Vậy hắn cùng thời đại người , đến cùng là có nhiều phế vật ?!”\nCái này cũng là Trần Xuyên Phú cảm thấy phi thường buồn cười một điểm , ngươi từ xuất thân đi công kích Lưu Bang , cho rằng Lưu Bang chỉ là lưu manh , vận khí tốt được thiên hạ .\nCái kia Hạng Vũ các cái khác cùng thời đại nhân kiệt , không phải liền là phế vật ?\nDù sao tại cái kia xem trọng huyết thống thời đại , liền lưu manh xuất thân Lưu Bang đều đánh không lại , đây không phải phế vật là cái gì ?\nLưu Bang là phế vật ? Cái kia Hạng Vũ chờ những người khác , thì càng là phế vật cũng không bằng .\n“ Cho nên rất nhiều người là phi thường phiến diện , nghe người khác nói , hoặc hiểu rõ một điểm sau đó , liền bắt đầu vô não công kích .”\n“ Vẫn là câu nói kia , một cái hoàng đế , ngươi không theo hắn ban bố chính sách đi công kích , ngược lại từ xuất thân đi công kích ?”\n“ Đây chính là điển hình từ chính trị bên trên tìm không thấy công kích điểm , chỉ có thể từ đơn giản nhất , để cho người gây nên chung tình xuất thân đi công kích .”\nCho nên Trần Xuyên Phú vẫn luôn cảm thấy từ xuất thân , mặc kệ đi công kích trong lịch sử hoàng đế nào , đều rất không hiểu thấu .\nĐây quả thật là hoàn toàn đem cùng thời đại những người khác không để ý đến , hoặc thì đơn giản quy kết làm vận khí tốt .\nNhưng nếu là vận khí tốt , vì cái gì cuối Tần mấy chục triệu người , liền vẻn vẹn là Lưu Bang vận khí tốt ?\nCuối thời nhà Nguyên , không sai biệt lắm sáu ngàn vạn nhân khẩu , vì cái gì liền Chu Nguyên Chương vận khí tốt ?\nCó một số việc , là dùng vận khí có thể giải thích ?\n“ Nếu là vận khí liền có thể giảng giải , vậy mọi người đều ngã ngửa , liều mạng ai vận khí tốt hơn là được rồi .”\n“ Tất cả mọi người cùng một chỗ nhảy núi , vận khí tốt người kia sống sót , khác vận khí kém , đều đi chết .”\n“ Sau đó thì sao ? Liền để cái kia vận khí tốt người làm hoàng đế ?”\n“ Thế nhưng là , đây không phải nói đùa là cái gì ?”\nCái này giống như hiện đại rất nhiều người nói học bá , một câu đơn giản thiên tài , liền đem người khác mười mấy năm cố gắng không để mắt đến ?\n“ Tiếp đó chính là bỏ rơi vợ con ...”\nNói đến đây , Trần Xuyên Phú nhẹ giọng thở dài , sau đó nhìn xem camera , chậm rãi nói :\n“ Ta biết , ta lời kế tiếp , có thể rất nhiều người không thích nghe , bởi vì đây không phải bọn hắn muốn nghe .”\n“ Bọn hắn muốn nghe , là toàn gia sung sướng , người một nhà thật vui vẻ , tiếp đó thuận thuận lợi lợi đoạt được thiên hạ .”\n“ Nhưng ...”\nTrần Xuyên Phú nói đến đây , lắc đầu nói :\n“ Rất nhiều người kỳ thực đối với hoàng đế , hoặc có lẽ là đối với chính trị sinh vật , có một chút hiểu lầm .”\n“ Cho rằng bọn họ hẳn là giống như chính mình , cũng là yêu gia đình , có lẽ là bọn hắn kỳ vọng như thế , ái thê tử Ái Hài Tử ...”\n“ Sau đó thì sao ? Vừa hi vọng hoàng đế hay là chính trị sinh vật , bọn hắn không cần Ái Hài Tử , không cần Cố gia tòa , bởi vì tại rất nhiều người trong lòng , bọn hắn là không thể có tư tình .”\n“ Đặc biệt là bây giờ còn rất lưu hành một câu nói “ Thần tiên động tình , tam giới không yên ”.”\nNói xong lời nói này , Lý Ân Phàm lại tiếp tục nói :\n“ Cụ thể tới nói , rất nhiều người hy vọng các hoàng đế chắc có rất sâu cảm tình , nếu như không có ? Liền muốn mắng , trong đó điển hình nhất là ai ?”\n“ Hán Thái tổ Cao Hoàng Đế Lưu Bang , Hán Vũ Đế Lưu Triệt .”\n“ Tán dương chính là ai ? Minh Thái tổ Chu Nguyên Chương , minh thành tổ Chu Lệ .”\n“ Sau đó thì sao ? Lại có rất nhiều người hy vọng các hoàng đế đừng có cảm tình sâu như vậy , không nên bởi vì cảm tình làm trễ nãi vương triều .”\n“ Trong đó bị chửi nhiều nhất là ai ? Hán Tuyên Đế Lưu Tuần .”\n“ Trong đó điển hình nhất , Chu U Vương , Bắc Tề hậu chủ cao vĩ , sau yến Mộ Dung Hi chờ đã .”\nSau đó , Trần Xuyên Phú lắc đầu sau tiếp tục nói :\n“ Đây chính là vô cùng song tiêu một sự kiện , mắng không có tình cảm hoàng đế , mắng cảm tình sâu hoàng đế ...”\n“ Nhưng ở ta xem tới ...”\nNói đến đây , Trần Xuyên Phú liền chuẩn bị nói ra ý nghĩ của mình .\n“ Công kích hoàng đế , còn có công kích chính trị sinh vật tình cảm của bọn hắn , kỳ thực rất cố tình gây sự một sự kiện .”\n“ Đại gia phải rõ ràng , hoặc phải nhớ kỹ một sự kiện .”\n“ Hoàng đế , cùng với chính trị sinh vật , bọn hắn kỳ thực cùng người bình thường chênh lệch rất lớn .”\n“ Bọn hắn cân nhắc chuyện góc độ , là cùng đại đa số người , suy tính sự tình hoàn toàn khác biệt .”\n“ Đại đa số người , bọn hắn suy xét một sự kiện , là suy xét đúng sai , hơn nữa cái này đúng sai , là lấy quanh mình hoàn cảnh đắp nặn tam quan , tới phán xét đúng sai .”\n“ Nhưng hoàng đế cùng chính trị sinh vật đâu ? Bọn hắn cân nhắc chuyện góc độ , chỉ có một cái !”\n“ Đó chính là , khi một sự kiện phát sinh sau , bọn hắn chỉ có thể suy xét .”\n“ Chuyện này đối với ta có hay không lợi ?”\n“ Chuyện này nếu như đối với ta không có lợi , ta tại sao muốn đi làm ? Hoặc có lẽ là , ta dựa vào cái gì muốn đi làm ?”\n“ Đúng sai ? Theo bọn hắn nghĩ , là không có nhất ý nghĩa một sự kiện !”\nNói đến đây , Trần Xuyên Phú nói hết sức chăm chú .\n“ Vì cái gì không có ý nghĩa ? Bởi vì theo ý của ngươi , đúng chuyện , nhưng không có lợi ích a .”\n“ Không có lợi ích ? Vậy ta tại sao muốn đi làm ?”\n“ Giống như là bây giờ rất nhiều người suy xét đỡ hay không đỡ vấn đề , chuyện này nếu như từ đúng sai đi xem , đương nhiên là muốn đi đỡ .”\n“ Nhưng vì cái gì bây giờ rất nhiều người không dám đi đỡ ?”\n“ Rất đơn giản , giúp đỡ sau đó , tổn thất ích lợi của ngươi .”\n“ Đây chính là vô cùng đơn giản từ lợi ích góc độ đi suy xét vấn đề .”\nĐoạn lời này , Trần Xuyên Phú lời nói vô cùng ngay thẳng .\n“ Có thể rất nhiều người nghe được cái này , trong lòng vô cùng không thoải mái , bởi vì cái này cùng truyền thống đạo đức quan còn có đúng sai quan là cùng nhau vi phạm .”\n“ Thế nhưng là , đây chính là hoàng đế , hoặc có lẽ là chính trị sinh vật suy xét vấn đề góc độ .”\n“ Chúng ta lại đi nhìn Lưu Bang bỏ rơi vợ con ...”\n“ Hắn vì cái gì ở trên đường chạy trốn , muốn đem trong xe ngựa Lữ Trĩ cùng Lưu Doanh đạp ra ngoài ?”\n“ Rất đơn giản , bởi vì những người khác trong xe ngựa , sẽ tăng thêm xe ngựa trọng lượng , tiếp đó dây dưa xe ngựa tốc độ .”\n“ Xe ngựa nếu như tốc độ chậm lại , liền sẽ bị truy binh đuổi kịp .”\n“ Đuổi kịp sau đó đâu ? Lưu Bang chính mình liền sẽ bị bắt lại !”\n“ Cho nên , ngươi nhìn , đây chính là rất đơn giản từ lợi ích góc độ đi suy xét vấn đề .”\n“ Chỉ có thể suy tính được mất , mà sẽ không đi cân nhắc đúng sai hoặc có lẽ là cái gì đạo đức quan ...”\nNói đến đây , Trần Xuyên Phú đi trở về trên ghế sa lon , lần nữa ngồi xuống xuống dưới , thở dài nói :\n“ Hiện đại rất nhiều người đi xem trong lịch sử rất nhiều hoàng đế , lọc kính đều là vô cùng nặng .”\n“ Đem hiện đại rất nhiều đạo đức quan các loại , áp đặt đi lên .”\n“ Kỳ thực trong mắt của ta , đều không tất yếu , hoàng đế loại này chính trị sinh vật , ngươi chỉ có từ chính trị góc độ , hoặc có lẽ là chính là từ lợi ích góc độ đi suy xét , mới có thể thấy rõ ràng .”\n“ Cũng mới có thể nhìn càng thêm biết rõ , bọn hắn tại sao muốn làm như vậy .”\n“ Đến nỗi từ những thứ khác góc độ ? Có chút hoàng đế ngươi quả thật có thể nhận được đáp án , nhưng càng nhiều hoàng đế , đặc biệt là những cái kia Hán triều hoàng đế , ngươi là không chiếm được câu trả lời .”\n“ Bởi vì Hán triều hoàng đế , tuyệt đại đa số , cũng là thuần túy chính trị sinh vật .”\n“ Cảm tình ? Có lẽ là có một chút , nhưng tuyệt đại đa số thời điểm , bọn hắn là rất lạnh lùng .”\n“ Đương nhiên , cái này cũng là vì cái gì Hán triều hoàng đế , mạnh hơn khác triều đại hoàng đế một mảng lớn nguyên nhân .”\n“ Đồng dạng , cái này cũng là vì cái gì rất nhiều Hán triều hoàng đế , là hậu thế hoàng đế cọc tiêu nguyên nhân .”\n......', NULL, '2026-09-02T00:14:50.149557+00:00', 'completed', 'pending', 8368, 0),
	(100, 7, '7655031799088693785', 95, 'Thứ 94 chương Căn bản không vội', 'Thứ chương Căn bản không vội\nHiện đại .\n“ Hán triều hoàng đế , từ Hán Thái tổ Cao Hoàng Đế Lưu Bang bắt đầu , có thể nói vẫn đối với cảm tình đều vô cùng lạnh nhạt .”\n“ Mặc kệ là thân tình vẫn là cái gì tình yêu , theo bọn hắn nghĩ , cũng không có có tác dụng gì .”\n“ Cũng đều không có đại hán trọng yếu .”\n“ Nhưng rất đáng tiếc là , đây mới là chúng ta một mực nói đùa nói tới “ Thần tiên ”...”\nCái này thần tiên thêm dấu ngoặc kép , chính là cho rằng bọn họ hẳn là nhất thiết phải lạnh nhạt , công bình công chính đối đãi vương triều bên trong tất cả mọi chuyện .\nỞ phương diện này , Hán triều hoàng đế một mực là làm tốt nhất .\nNhưng từ người bình thường cảm tình góc độ đến xem , Hán triều hoàng đế , nói thật , cũng là vô tình nhất .\n“ Nhưng cái này , chính là chính trị sinh vật , hoặc có lẽ là , đây chính là hoàng đế ...”\n“ Dùng câu kia đùa giỡn mà nói , “ Thần tiên động tình , tam giới không yên ”, để giải thích , kỳ thực là vô cùng trọn vẹn .”\nNói xong điểm này , Trần Xuyên Phú lại tiếp tục nói :\n“ Chúng ta lại nhìn đồ sát khai quốc công thần ...”\n“ Đầu tiên , câu nói này kỳ thực quá mức sơ lược , có một chút sai lầm .”\nSai lầm ? Ngụy Gia nghi hoặc nhìn Trần Xuyên Phú , này làm sao hội hữu thác bỏ lỡ ?\n“ Sai lầm ở nơi nào ?”\n“ Trong lịch sử rất nhiều khai quốc hoàng đế , bọn hắn chỉ có thể đồ sát đối với vương triều có uy hiếp khai quốc công thần .”\n“ Để cho bọn hắn cảm thấy không có uy hiếp ? Bọn họ sẽ không tàn sát !”\n“ Lưu Bang không có giết Trường Sa Vương Ngô Nhuế .”\n“ Lý Thế Dân không có giết Lư Quốc Công Trình Giảo Kim bọn người .”\n“ Chu Nguyên Chương không có giết canh cùng còn có Từ Đạt bọn người .”\nLý Thế Dân mặc dù không phải khai quốc hoàng đế , nhưng ở ngay lúc đó Đường triều , Lý Thế Dân có thể nói hơn hẳn khai quốc hoàng đế .\n“ Cho nên , ngươi cẩn thận đi xem , bọn hắn tàn sát rốt cuộc là ai ?”\n“ Lại dùng chính trị góc độ , hoặc có lẽ là từ vương triều lợi ích góc độ đi xem , bọn hắn tại sao muốn đồ sát người có uy hiếp ?”\n“ Còn nhớ rõ ta mới vừa nói sao ? Cảm tình ? Cảm tình có thể làm cơm ăn ?”\n“ Vẫn là nói , cảm tình có thể duy trì vương triều kéo dài ?”\n“ Ta nói câu nói này , ngươi tin không ?”\nNhìn xem Ngụy Gia ánh mắt , Trần Xuyên Phú hỏi rất bình tĩnh .\nMà Ngụy Gia đâu ? Chỉ là hơi suy nghĩ một chút , cũng chỉ có thể là lắc đầu .\n“ Tại Hán triều phía trước , thế nhưng là Xuân Thu Chiến Quốc thời kì , theo bọn hắn nghĩ lễ băng nhạc phôi thời kì .”\n“ Triều Tấn ? Vị trí của bọn hắn làm sao tới , chính bọn hắn không rõ ràng sao ?”\n“ Đường triều ? Triều Tấn ngay ở phía trước , Tư Mã Ý ngay ở phía trước , Ngụy Tấn Nam Bắc triều cái kia hỗn loạn thời kì , ngay ở phía trước .”\n“ Tống triều thì càng không cần nói , Tống thái tổ Triệu Khuông Dận làm sao tới hoàng đế vị trí ?”\n“ Mà Minh triều đâu ? Bọn hắn thế nhưng là tại Tống triều sau đó , bọn hắn không rõ ràng Tống thái tổ Triệu Khuông Dận là thế nào có được hoàng vị sao ?”\nNói đến đây , Lý Ân Phàm bỗng nhiên đứng lên , tiếp lời đề , đi đến bảng đen bên cạnh , cầm lấy phấn viết , viết bốn chữ :\nBa nhà phân tấn .\nSau đó , Lý Ân Phàm quay đầu nhìn về phía camera , nhẹ nói :\n“ Xuân Thu Chiến Quốc đường ranh giới là lúc nào ? Ba nhà phân tấn .”\n“ Mà cũng chính là từ xuân cuối thu kỳ ba nhà phân tấn bắt đầu , liền tiêu chí lấy “ Lễ nhạc sụp đổ ” Cùng trật tự cũ triệt để tan rã\n“ Sau đó thì sao ? Chính là quân bài domino từng tờ từng tờ bắt đầu ngã xuống ...”\n“ Sau đó ? Tư Mã Ý vân vân người , lại tự tay đem thư mặc cho từng chút một phá huỷ ...”\n“ Đây chính là vì cái gì rất nhiều khai quốc hoàng đế , đều phải đồ sát có uy hiếp khai quốc công thần bên trong lôgic .”\n“ Bởi vì những sự tình này , đều tại sách sử phía trên rõ rành rành bày !!!”\n...\nĐường triều .\nTrinh Quán bảy năm .\nNghe được màn trời nói đến đây thời điểm , Lý Thế Dân biểu lộ vô cùng bình thản .\nLý Thế Dân vì cái gì không có đồ sát công thần ?\nHiện đại có rất nhiều người nói , là bởi vì Lý Thế Dân công lao , có thể đè xuống tất cả mọi người .\nĐây đúng là sự thật , nhưng Lý Thế Dân nếu là chết đâu ?\nNgười chết như đèn diệt , người đã chết , thế nhưng là uy hiếp không được người sống .\nNếu là chết người , còn có thể uy hiếp được người sống , hiện đại vài thập niên trước sẽ phát sinh những sự tình kia sao ?\n“ A ...”\nLý Thế Dân lắc đầu , cảm thấy màn trời nói quá mức trực bạch , thẳng thắn đem rất nhiều hoàng đế nội tâm suy xét lôgic đều phân tích đi ra .\nHắn vì cái gì không đồ sát khai quốc công thần ?\nBởi vì không vội , có thể từ từ sẽ đến .\nLúc này Đại Đường rất nhiều người , kỳ thực cũng là so Lý Thế Dân tuổi tác lớn .\nHắn chỉ cần từ từ gọt quyền là được rồi .\nCó chút hơi quá mức , hắn mới có thể sao một cái tội danh tới thu thập .\nLý Thế Dân tại rất nhiều người trong ấn tượng , cảm thấy hắn là khai quốc hoàng đế , cũng quả thật là như thế , hắn không phải khai quốc hoàng đế , nhưng hơn hẳn khai quốc hoàng đế .\nNhưng , sự thực là , Lý Thế Dân là Thái Tông .\nMà Thái Tông , liền sẽ gặp phải một cái tình huống , hắn cùng thủ hạ khai quốc công thần , số tuổi là có một cái đại kém .\nCái này cũng là trong lịch sử tuyệt vô cận hữu một cái tình huống .\nCho nên Lý Thế Dân căn bản không vội , Trinh Quán năm đầu thời điểm , Lý Thế Dân mới bao nhiêu tuổi ?\ntuổi !\nPhòng Huyền Linh tuổi ( Sinh tại năm ).\nNgụy Chinh tuổi ( Sinh tại năm ).\nTiêu Vũ tuổi ( Sinh tại năm ).\nẨn sĩ liêm tuổi ( Sinh tại năm ).\nLý Tĩnh tuổi ( Sinh tại năm ).\nTần Quỳnh tuổi ( Sinh tại năm ).\nUất Trì Kính Đức tuổi ( Sinh tại năm ).\nTrưởng Tôn Vô Kỵ Hẹn tuổi ( Sinh năm không rõ , đánh giá sinh tại năm tả hữu ).\nLý Hiếu Cung tuổi ( Sinh tại năm ).\nTrình Giảo Kim ( Trình Tri Tiết tuổi ( Sinh tại năm ).\nCho nên , nhìn thấy không ? Không có một cái so Lý Thế Dân nhỏ !\nToàn bộ Thiên Sách phủ , liền Lý Thế Dân tuổi tác , là nhỏ nhất ! Cho nên hắn gấp gáp cái gì ?\nDù là nhỏ nhất Đoạn Chí Hiên , tại Trinh Quán năm đầu thời điểm , đều phải so với Lý Thế Dân lớn hơn một tuổi .\nCho nên , tại toàn bộ Trinh Quán mười bảy năm phía trước , cơ thể của Lý Thế Dân cực kỳ tốt thời điểm , hắn căn bản liền không lo lắng .\nBởi vì hắn tinh tường , không có gì bất ngờ xảy ra , cái này một số người đều biết đi ở trước mặt của hắn .\nNhưng cẩn thận nhìn qua Trinh Quán hướng lịch sử tiểu đồng bọn liền sẽ phát hiện , Trinh Quán mười bảy năm là một cái phi thường mấu chốt tiết điểm .\nTừ một năm này bắt đầu , võ tướng lục tục bắt đầu xảy ra vấn đề , mà rất nhiều văn thần cũng là như thế .\nVì sao lại xuất hiện loại tình huống này ?\nBởi vì Trinh Quán mười bảy năm Lý Thừa Càn mưu phản !\n...', NULL, '2026-09-02T00:15:07.446424+00:00', 'completed', 'pending', 6459, 0);
INSERT INTO `chapters` (`id`, `novel_id`, `chapter_site_id`, `chapter_number`, `title`, `content`, `mp3_path`, `crawled_at`, `crawl_status`, `tts_status`, `tts_chars_total`, `tts_chars_done`) VALUES
	(101, 7, '7655476656139682329', 96, 'Thứ 95 chương Cái gọi là khai quốc chi quân', 'Thứ chương Cái gọi là khai quốc chi quân\nHiện đại thời không .\n“ Cái kia Hán Quang Võ Đế Lưu Tú đâu ? Hắn cũng là không có tru diệt qua khai quốc công thần a .”\nNgụy Gia lúc này đưa ra nghi vấn của mình .\n“ Ngươi cho rằng Hán Quang Võ Đế Lưu Tú , là khai quốc hoàng đế sao ?”\n“ Hoặc , ta đổi một cái thuyết pháp , ngươi cho rằng Lưu Bị , hắn cũng là khai quốc hoàng đế sao ?”\nTrần Xuyên Phú cầm ống nói lên , nhìn xem Ngụy Gia , hỏi cái vấn đề như vậy .\nMà Ngụy Gia nghe được vấn đề này , chính là sững sờ .\n“ Hán Quang Võ Đế Lưu Tú không phải khai quốc hoàng đế ?”\nTrần Xuyên Phú chỉ là lắc đầu , sau đó nhìn Ngụy Gia nhẹ nói :\n“ Hảo , đã ngươi cho rằng Hán Quang Võ Đế Lưu Tú là khai quốc hoàng đế , vậy hắn mở cái gì quốc ? Thành lập cái gì vương triều ?”\n“ Đương nhiên là ...”\nNgụy Gia vừa định nói ra cái tên đó , nhưng lập tức ý thức được vấn đề .\nNếu như nói Hán Quang Võ Đế Lưu Tú , khai quốc mở chính là Hán , cái kia Hán Thái tổ Cao Hoàng Đế Lưu Bang , lại là mở cái gì ?\n“ Cho nên ngươi nhìn , có phải hay không phát giác vấn đề ?”\n“ Vì cái gì ta phía trước biết nói , trung hưng chi quân cọc tiêu là Hán Quang Võ Đế Lưu Tú ?”\n“ Mà không phải vô cùng minh xác nói , Hán Quang Võ Đế Lưu Tú là khai quốc hoàng đế ?”\n“ Hán Quang Võ Đế , Quang Võ Đế !!!”\nTại trên Quang Võ Đế ba chữ này , Trần Xuyên Phú nói rất nặng , cũng nói hết sức chăm chú .\n“ Giống như hiện đại rất nhiều người cho rằng , Lưu Bị vậy mà cũng là khai quốc hoàng đế ?”\n“ Nhưng nếu như Lưu Bị là khai quốc hoàng đế ? Vậy hắn mở cái gì quốc ? Cái gì vương triều ?”\nLúc này , Lương Phong bỗng nhiên nghĩ tới điều gì , quay đầu nhìn về phía Ngụy Gia , vừa cười vừa nói :\n“ Hỏi ngươi một vấn đề , cuối thời Đông Hán Tam quốc , là cái nào Tam quốc .”\n“ Cái nào Tam quốc ?”\nNgụy Gia sửng sốt một chút , sau đó lập tức nhanh chóng nói :\n“ Đương nhiên là Ngụy Thục Ngô a ...”\nLời này vừa ra , tại chỗ mấy người đều cười ra tiếng .\n“ Không phải , các ngươi vì cái gì cười ? Chẳng lẽ không đúng sao sao ?”\n“ Đương nhiên là sai !”\nLý Ân Phàm có chút bất đắc dĩ nhìn xem hắn , nhẹ nói :\n“ Chính xác thuyết pháp , hẳn là : Ngụy , Hán , Ngô ...”\n“ Ngụy Thục Ngô , là chúng ta đời sau thuyết pháp , mục đích là vì cùng Đông Hán khác nhau mở .”\n“ Này liền như cái gì ? Tại Hán triều , là không có cái gọi là Đông Hán , Tây Hán thuyết pháp , bọn họ đều là nhất mạch tương truyền, cha truyền con nối .”\nA ?\nNgụy , Hán , Ngô ?\n“ Hậu thế , vì đem Lưu Bị thiết lập Hán , cùng trước mặt Hán làm một cái phân chia .”\n“ Cho nên chúng ta xưng là : Thục Hán .”\n“ Vì cái gì gọi Thục Hán ? Bởi vì Lưu Bị thiết lập chính quyền , địa điểm mới là Thục .”\n“ Cũng bởi vì trần thọ viết 《 Tam Quốc Chí 》 lúc đem Lưu Bị chính quyền đánh dấu là “ Thục sách ”.”\nSau đó , Lý Ân Phàm khôi phục bình tĩnh , nhún vai , đối với Ngụy Gia tiếp tục nói :\n“ Cho nên rồi , Hán Quang Võ Đế Lưu Tú , còn có Lưu Bị , hai người bọn họ đều không phải là khai quốc chi quân .”\n“ Mở ra Quốc hoàng đế tiêu chuẩn là gì ?”\n“ Một : Thiết lập chính quyền mới Nhất thiết phải thông qua quân sự chinh phạt , chính trị biến đổi hoặc nhường ngôi các phương thức , kết thúc tiền triều thống trị hoặc độc lập lập quốc , chính thức xác lập mới Quốc hiệu Cùng Niên hiệu\n“ Hai : Thủ vị xưng đế / xưng vương Là nên vương triều lịch sử thượng đệ nhất vị sử dụng người thống trị cao nhất xưng hào ( Như “ Hoàng đế ”, “ Đại hãn ” chờ ) người , sau này người kế nhiệm vô luận chiến công bao lớn đều không thuộc về khai quốc hoàng đế .”\n“ Ba : Đặt vững quy định cơ thạch Bình thường phụ trách tạo dựng Cai Vương Triều sơ kỳ Trung ương tập quyền cơ chế pháp luật dàn khung cùng cương vực cơ sở , có “ Đặt ra rủ xuống thống ” Lịch sử thuộc tính\n“ Cho nên nghiêm chỉnh mà nói , Hán Quang Võ Đế Lưu Tú , còn có Lưu Bị , bọn hắn cũng không phải cái gì rất nhiều người cho là khai quốc hoàng đế .”\n“ Khai quốc hoàng đế , cũng là muốn dựng nghiệp bằng hai bàn tay trắng , độc lập đánh xuống thiên hạ .”\n“ Nhưng Hán Quang Võ Đế Lưu Tú còn có Lưu Bị đâu ?”\n“ Bọn hắn có thể đặt xuống thiên hạ hay là cát cứ một phương , cũng là nhận lấy tiền triều chỗ tốt .”\n“ Bọn hắn không thể nói là dựng nghiệp bằng hai bàn tay trắng ...”\nCái này cũng là rất nhiều người hiện đại không có nhận ra được một điểm .\n“ Nghiêm khắc tới nói , toàn bộ cuối thời Đông Hán Tam quốc thời kì , dựng nghiệp bằng hai bàn tay trắng , chỉ có Ngụy cùng Ngô ...”\n“ Lưu Bị , là không tính là dựng nghiệp bằng hai bàn tay trắng , trên đầu của hắn cái kia xưng hào , tại lúc đó mang đến cho hắn chính trị ưu thế là phi thường lớn .”\nNói thật , nếu như Hán Quang Võ Đế Lưu Tú cùng Lưu Bị cũng có thể tính toán dựng nghiệp bằng hai bàn tay trắng lời nói .\nTriệu cấu có phải hay không có thể tính đến bên trên khai quốc hoàng đế ?\nDù sao Bắc Tống lúc đó là bị Kim Triều diệt .\nNam Tống thứ nhất hoàng đế triệu cấu , là chạy đến Ứng Thiên phủ ( Nay Hà Nam Thương Khâu ) đăng cơ .\nCó thể dạng này tính sao ?\nĐương nhiên là không thể .\n“ Nói thật , trước đó ta vẫn còn cho rằng Hán Quang Võ Đế Lưu Tú cùng Hán chiêu liệt đế Lưu Bị , hai người bọn họ là khai quốc chi quân ...”\nNgụy Gia lúc này rất là cảm khái nói .\n“ Cảm giác quả thật là như thế , trước đó ta cũng vẫn cho là hai người bọn họ là khai quốc chi quân .”\n“ Cũng không phải .”\nLý Ân Phàm trước đó không thể nào hiểu rõ lịch sử thời điểm , chính xác cho rằng hai người này cũng là khai quốc chi quân .\nLưu Tú mở cái gì quốc ? Đông Hán .\nLưu Bị đâu ? Hắn lại mở cái gì quốc ? Thục ...\nNhưng về sau cẩn thận giải sau đó mới phát hiện , là không có cái gì Đông Hán Tây Hán Thục Hán , đây đều là hậu thế vì khác nhau , mới như vậy xưng hô .\nBọn hắn ngay lúc đó quốc hiệu , cũng là Hán .\nMà nếu là Hán , vậy đã nói rõ , là kế thừa chính trị thuộc tính .\nDạng này đến xem , hai vị này hoàng đế , sao có thể tính là khai quốc chi quân đâu ?\n...\nMinh triều .\nVĩnh Lạc bảy năm .\n“ Ân ? Hậu thế lại có người cho rằng Lưu Tú cùng Lưu Bị là khai quốc chi quân ?”\nChu Lệ ngẩn người , sau đó đã cảm thấy có chút buồn cười .\nNếu như hai người bọn họ đều tính toán khai quốc chi quân mà nói , cái kia có phải hay không cũng là khai quốc chi quân đâu ?\nNghĩ tới đây , Chu Lệ bỗng nhiên sắc mặt lập tức âm trầm xuống .\nBởi vì hắn một mực phiền não cũng là chuyện này .\nTại Vĩnh Lạc triều , có một cái phiền toái rất lớn , hoặc giả thuyết là phiền phức ngập trời .\nChu Lệ có phải hay không khai quốc chi quân ? Không hề nghi ngờ , Chu Lệ không phải khai quốc chi quân .\nNhưng Chu Lệ không có khai quốc chi quân tên , lại có khai quốc chi quân thực !\nCái gì thực ? Đánh xuống thiên hạ thực !!!\nCho nên , cũng tạo thành một cái vô cùng quỷ dị tình huống .\nTại Vĩnh Lạc triều , tồn tại “ Hai triều ” “ Khai quốc ” Công thần !\nĐây chính là lúc đó Vĩnh Lạc triều chính trị bên trên vô cùng quỷ dị tình huống , cũng là Minh triều đằng sau vì cái gì có chút quái dị địa phương .\nTrong lịch sử , không có bất kỳ cái gì một cái triều đại có quỷ dị như vậy tình huống .\nHồng Vũ hướng khai quốc công thần , là tồn tại .\nVĩnh Lạc triều “ Khai quốc ” Công thần đâu ? Cũng là tồn tại !\n......', NULL, '2026-09-02T00:15:12.391958+00:00', 'completed', 'pending', 6982, 0),
	(102, 7, '7655477516534039065', 97, 'Thứ 96 chương Vĩnh Lạc hướng thiên đại phiền phức', 'Thứ chương Vĩnh Lạc hướng thiên đại phiền phức\nHậu thế vô số người đều đang tự hỏi một vấn đề , vì cái gì Chu Lệ nhất định phải thân chinh ?\nNgũ chinh mạc bắc , vì cái gì Chu Lệ nhất định muốn tự thân lên trận ?\nHậu thế có rất nhiều ngờ tới , từ cảm tình , từ thân tình vân vân chỗ đi ngờ tới .\nCho rằng Chu Lệ là vì chứng minh chính mình là một vị hoàng đế tốt , cho nên mới thân chinh mạc bắc .\nNhưng , làm một vị hoàng đế tốt , liền nhất định muốn thân chinh mạc bắc ?\nKhông thể trên triều đình thật tốt phê chữa chính vụ ?\nGiống như phía trước nói như vậy , một cái hoàng đế , nhất định phải quân sự lợi hại , mới là một vị hoàng đế tốt ?\nMà Chu Lệ vì cái gì thân chinh mạc bắc đâu ?\nBởi vì tại lúc đó , chỉ có Chu Lệ , có thể ép lại “ Hai triều ” Công thần .\nCái này cũng là hiện đại tuyệt đại đa số người sơ sót .\nTại Chu Lệ Tĩnh Nan sau khi thành công , dưới tay hắn những người kia , có phải hay không công thần ?\nĐương nhiên là công thần !\nCho nên , Chu Lệ sẽ Phong Trương Ngọc vì Vinh Quốc công .\nChu Năng , thành quốc công .\nKhâu Phúc , kỳ quốc công .\nVân vân cái này một số người , cũng là Tĩnh Nan công thần .\nThế nhưng là , phía trước còn có “ Hồng Vũ khai quốc công thần ” Tồn tại a .\nCho nên , đây cũng chính là vì sao lại nói , Vĩnh Lạc hướng xuất hiện một cái trong lịch sử tuyệt vô cận hữu tình huống quỷ dị .\n“ Hai triều ” Công thần , đều chen tại một chỗ .\nCó thể hay không không thừa nhận “ Hồng Vũ khai quốc công thần ” Đâu ? Không thể !\nChu Lệ muốn chứng minh chính mình là chính thống , vậy thì nhất định phải thừa nhận những thứ này “ Hồng Vũ khai quốc công thần ”.\nNếu như ngươi không thừa nhận bọn hắn ? Vậy ngươi chính thống đến từ đâu ?\nCho nên , Minh triều hỗn loạn chi nguyên liền chôn ở ở đây !\n“ Hai triều ” Khai quốc công thần !!!\nMà Chu Lệ thân chinh mạc bắc nguyên nhân lớn nhất , cũng liền ở đây .\nNgoại trừ ngươi Chu Lệ , còn có ai có thể đè ép được “ Hai triều công thần ”?\nKhông có !\nChu Cao Hú có thể chứ ? Không được !\nChu Lệ hắn là Chu Nguyên Chương con trai trưởng , sau đó thì sao ? Lại là Tĩnh Nan thành công hoàng đế .\nCho nên hắn mới có thể đè ép được hai triều công thần .\nChu Cao Hú ? Không được .\nChu Cao Sí ? Không được .\nLiền những hoàng tử này đều không được , những người khác ? Kia liền càng không được !\nNhưng lúc này , vấn đề tới , nếu như đổi một người , tỉ như nói , ai ?\nKhâu Phúc ! Cũng chính là kỳ quốc công .\nCó thể hay không để cho hắn làm chủ soái , đi trưng thu mạc bắc ?\nCó thể .\nNhưng cứ như vậy , công lao của hắn liền sẽ thẳng tắp tăng vọt !\nSau đó thì sao ? Ngược lại đè “ Hai triều ” Công thần .\nNhưng tại lúc đó , chỉ có ai có thể đè ? Chỉ có Chu Lệ có thể đè .\nNếu là ngươi Khâu Phúc trưng thu mạc bắc thành công , thu được cực lớn chiến công , có thể đè “ Hai triều ” Công thần , cái kia độ cao có phải hay không cùng Chu Lệ đứng tại trên một đường thẳng ?\nĐương nhiên là đứng tại trên một đường thẳng .\nNhưng Chu Lệ là hoàng đế , ngươi Khâu Phúc lại là cái gì ?\nĐây cũng chính là lúc đó Vĩnh Lạc hướng Chu Lệ đối mặt bất đắc dĩ tình huống .\nNếu như hắn để người khác đi trưng thu mạc bắc , vậy người khác liền sẽ trở thành quân công đệ nhất nhân , đè “ Hai triều ” Công thần .\nTrước mặt Triệu Khuông Dận vết xe đổ để ở nơi đó .\nChu Lệ hắn lại như vậy làm sao ? Hoặc có lẽ là , hắn dám làm như vậy sao ?\nLần thứ năm trưng thu mạc bắc thời điểm , hắn liền không sợ người khác đi ra , trực tiếp ngược lại học Triệu Khuông Dận ?\nĐương nhiên sẽ sợ !\nCho nên đây chính là vì cái gì Chu Lệ muốn thân chinh lý do .\nCông lao lớn nhất , hắn nhất thiết phải giữ tại trên tay mình mới có thể bảo trì phía dưới cân bằng .\nMà không phải để cho một người ra ngoài , trực tiếp diệt một cái bộ lạc , sau đó thì sao ? Vị trí liền đứng tại cùng mình đồng dạng độ cao .\nNgay cả hoàng tử cũng không thể đè “ Hai triều ” Công thần , đổi một cái những người khác ? Không chết liền kì quái .\nNhưng Chu Lệ tại sao muốn ngũ chinh mạc bắc đâu ?\nỞ trong đó nặng bao nhiêu nhân tố , một cái là chứng minh chính mình , hai chính là một nguyên nhân trọng yếu nhất .\nĐể cho những người kia chính mình phạm sai lầm .\nNếu như mình không đi ra , vậy bọn hắn còn thế nào phạm sai lầm ?\nĐặc biệt là Tĩnh Nan công thần cùng Hồng Vũ khai quốc công thần .\nHai cái này Công Thần tập đoàn , ngươi nếu là dùng những thứ khác tùy tiện một cái lý do , cái kia tất cả mọi người đều biết ngươi muốn đồ sát công thần , sau đó thì sao ? Tạo phản .\nNhưng hoàng đế đi ra , giám quốc chính là ai ? Là Thái tử Chu Cao Sí .\nPhía trước chúng ta đã nói , Chu Cao Sí là ép không được hai cái này công thần tập đoàn .\nTĩnh Nan hắn ép không được , Hồng Vũ hắn càng ép không được .\nTĩnh Nan công thần lúc đó là theo chân Chu Cao Hú , mà Hồng Vũ đây này ? Đều tại bão đoàn để phòng Chu Lệ trở mặt .\nChu Cao Sí hắn là ép không được , nhưng hắn có thể duy trì an ổn .\nSau đó thì sao ? Ghi nhớ phạm sai lầm tên người chữ , chờ Chu Lệ trở về thu thập bọn họ .\nCái này cũng là Chu Lệ thượng vị sau đó , có ý định chế tạo một cái tình huống .\nTĩnh Nan cùng Chu Cao Hú , văn thần đi theo Chu Cao Sí , khác tự mình ôm đoàn .\nTiếp đó ? Trên triều đình liền quỷ dị tạo thành một cái cân bằng .\nChu Lệ có ý định chế tạo ra một cái cân bằng !\nCho nên , điều này cũng làm cho chế tạo ra trong lịch sử đường đường chính chính quyền hạn lớn nhất Thái tử , Chu Cao Sí .\nBởi vì hắn là thật sự cầm quyền lực của hoàng đế , cố gắng duy trì triều đình cân bằng .\nNhưng lại vì sao lại nói Minh triều hỗn loạn chi nguyên chôn ở ở đây ?\nBởi vì lúc đó Chu Lệ cùng Chu Cao Sí đối mặt tình huống như vậy , quyết định dẫn vào lực lượng khác , đến đối kháng cái này hai cỗ “ Khai quốc ” Công thần .\nMột cổ sức mạnh này theo tại sau lưng Chu Cao Sí , cùng với những cái khác thế lực đối kháng .\nNhưng , một cổ sức mạnh này tại Chu Lệ sau khi chết , liền đã có một chút không kiểm soát .\nMinh Tuyên tông Chu Chiêm Cơ lúc , đã đến biên giới mất khống chế , ép Chu Chiêm Cơ chỉ có thể bất đắc dĩ dẫn vào hoạn quan thế lực .\nMà tới được Minh Anh Tông Chu Kỳ Trấn , từ đây Minh triều cục thế chính trị triệt để mất khống chế !\n...\n“ Ai ...”\nChu Lệ nghĩ đến chỗ này lúc Vĩnh Lạc hướng cục thế chính trị , đã cảm thấy vô cùng bực bội .\nTĩnh Nan thành công , là vui vẻ .\nNhưng khi hắn đối mặt phía dưới triều thần lúc , mới phát giác được vô cùng gian khổ .\nTrong lịch sử , hoàn toàn không có một cái nào có thể tham khảo .\nChỉ có thể tự đi tìm tòi , tiếp đó từ từ gạt bỏ .\nMà tại ở trong đó , còn lo lắng cân bằng không tốt , tạo thành một phương thế lực quá lớn , cuối cùng rơi vào một cái bi kịch .\nMặc kệ là thế lực nào thế lực quá lớn , đều biết khiến người khác cảm thấy uy hiếp .\nMà phía trước Hồng Vũ những người kia , cũng đều là vô cùng mẫn cảm , sợ mình muốn loại trừ bọn hắn .\n“ Lão đại , chờ thêm đoạn thời gian , ta liền lại muốn đi ra .”\nChu Cao Sí nghe nói như thế , sửng sốt một chút , sau đó bình tĩnh gật đầu một cái .\nTrốn là không tránh khỏi , Chu Cao Sí chỉ có thể tiếp nhận , huống chi , từ rất sớm phía trước chính mình liền dự liệu được , đây là chính mình thân là Thái tử chức trách .\nCái này cũng là vì sao Chu Cao Sí trước kia đều biết , chính mình Thái tử chi vị vô cùng củng cố .\nKhi Tĩnh Nan những người kia ủng hộ lão nhị Chu Cao Hú , Chu Cao Sí liền tinh tường , lão nhị không có cơ hội leo lên hoàng vị .\nNếu để cho Chu Cao Hú leo lên hoàng vị , Tĩnh Nan thế lực liền sẽ cấp tốc bành trướng , triệt để vượt trên “ Hồng Vũ công thần ”.\nMà “ Hồng Vũ công thần ” Bọn hắn sẽ thúc thủ chịu trói sao ?\nĐương nhiên sẽ không thúc thủ chịu trói !\nNgươi Chu Lệ có thể Tĩnh Nan thành công , những thứ khác chư vương , liền không thể lại tới một lần nữa Tĩnh Nan ?!\nChu Lệ Tĩnh Nan thời điểm rất nhiều Hồng Vũ công thần đều coi thường , bởi vì bọn hắn biết Chu Doãn Văn đang làm cái gì , lại đối chính mình có cái gì uy hiếp .\nNếu như ngươi Chu Lệ còn dám làm như vậy , sau cái kia Minh triều chủ lưu , chỉ sợ cũng thật là Tĩnh Nan .\nKhông có Tĩnh Nan ? Vậy ngươi có ý tốt xưng chính mình là Minh triều hoàng đế ?\nGiống như là Đường triều , không có Huyền Vũ môn đi qua một lần , ngươi còn không biết xấu hổ nói mình là Đường triều hoàng đế ?\nĐây chính là Minh triều lúc đó quỷ dị cục thế chính trị .\nKhông thể để cho bất kỳ bên nào thế lực quá khổng lồ , bằng không thì thế cục liền sẽ mất cân bằng .\nMà Tĩnh Nan liền đặt tại phía trước , về sau hoàng đế , chỉ có thể cố gắng duy trì lấy cái này một cỗ cân bằng .\nNhưng cuối cùng ?\nKhông đến bao lâu , vẫn là duy trì thất bại !\nThất bại căn nguyên , y nguyên vẫn là xuất hiện ở cái này Vĩnh Lạc triều .\n...\nHiện đại thời không .\n“ Chúng ta lại nói trở về Lưu Tú , hắn chính xác không phải khai quốc chi quân .”\n“ Nhưng hắn trung hưng đại hán , như vậy vấn đề tới , hắn vì cái gì không đồ sát công thần ?”\n“ Bởi vì hắn đối với những cái kia công thần , đưa ra một cái biện pháp .”\n“ Đưa ra “ Lui công thần mà tiến văn lại ”, tuyển bạt hiểu quản lý văn nhân làm quan , công thần chỉ hưởng thụ vinh dự .”\n“ Chính sách này tại lúc đó , đúng là rất tốt .”\n“ Nhưng vấn đề tới , vì cái gì đời sau hoàng đế , đối đãi công thần thời điểm , không thuận theo biện pháp này đâu ?”\n“ Bởi vì hậu nhân thấy rõ ràng , tại vương triều vô ích ! Căn bản không cần !”\n......', NULL, '2026-09-02T00:15:17.290041+00:00', 'completed', 'pending', 9119, 0),
	(103, 7, '7655929669903991321', 98, 'Thứ 97 chương Lui công thần mà tiến văn lại', 'Thứ chương Lui công thần mà tiến Văn Lại\nHiện đại thời không .\n“ Không cần ?”\nNgụy Gia kinh ngạc nhìn Lý Ân Phàm , nội tâm lúc này nghi hoặc đạt đến đỉnh phong .\n“ Vì sao lại không cần ?”\n“ Đáp án rất đơn giản , nếu như hữu dụng mà nói , hậu thế vương triều khai quốc chi quân nhóm , đều biết này biện pháp .”\n“ Nhưng cái này biện pháp , chỉ có Hán Quang Võ Đế Lưu Tú dùng qua .”\nSau đó , Lý Ân Phàm lại sau đó tiếp tục nói :\n“ Chúng ta tới đó nhìn , vì sao lại không cần ?”\n“ Lui công thần mà tiến Văn Lại ”, theo lý mà nói , là vô cùng tốt , tại Hán Quang Võ Đế Lưu Tú lúc ấy , cũng đúng là lấy được một ít thành tích .”\n“ Rất nhiều công thần , đều tiến “ Văn Lại ”, tiếp đó an tâm dưỡng lão , không tiếp tục cầm quyền .”\n“ Nhưng ...”\nLúc này , Lý Ân Phàm tử nhỏ đem “ Lui công thần mà tiến Văn Lại ” Chính sách nói một lần .\n“ Lui công thần mà tiến Văn Lại ”, đầu này chính sách có một cái vô cùng trọng yếu điểm , cũng chính là những cầm quyền đám công thần kia vì sao lại từ bỏ binh quyền nguyên nhân .”\n“ Tuyển bạt hiểu quản lý văn nhân làm quan , công thần chỉ hưởng thụ vinh dự .”\n“ Hiểu không ?”\n“ Nếu như ngươi là thuần túy võ tướng , vậy thì rất đơn giản , từ bỏ quyền lực trong tay , chờ trên triều đình dưỡng lão .”\n“ Nhưng nếu như ngươi là như “ Mưu sĩ ” Tầm thường văn nhân đâu ? Cái kia đến trên triều đình , liền sẽ thu được càng lớn quyền hạn .”\n“ Vân đài nhị thập bát tướng bên trong , phần lớn gia tộc , tại Đông Hán hậu kỳ đúng là từ từ suy sụp , số ít kéo dài đến Tam quốc thời kì .”\n“ Nhưng kinh khủng , chính là cái này số ít gia tộc ...”\nSau đó , Lý Ân Phàm đem hai gia tộc này , từng cái từng cái nói ra .\n“ Đặng Vũ gia tộc Hậu đại hưng vượng nhất , Tôn Nữ Đặng Tuy Trở thành Hán cùng Đế Hoàng sau , lâm triều xưng chế mười sáu năm . Gia tộc cùng ra hầu người , đại tướng quân người , Tam quốc lúc Thục Hán Xa Kỵ tướng quân Đặng Chi Cũng là con cháu đời sau .”\n“ Cảnh Yểm gia tộc : Toàn tộc tổng cộng có người phong hầu bao quát du nai hầu , hảo chỉ hầu , Mưu Bình Hầu , đẹp dương hầu mấy người nhiều cái tước vị , ra vị đại tướng quân Cảnh Yểm mấy người ) cùng vị tướng quân trường kỳ trấn thủ tây bắc biên cương , uy chấn một phương .”\n“ Tổng cộng có vị trí đệ còn công chúa theo thứ tự là cảnh tập (kích) ( Cưới long lo công chúa ), cảnh lương ( Cưới Bộc Dương công chúa ), cảnh viện binh ( Cưới dài xã công chúa ), cùng hoàng thất quan hệ chặt chẽ .”\n“ Đứng hàng Cửu khanh có người , đảm nhiệm thích sứ , hai ngàn thạch cấp bậc quan viên đạt mấy chục mấy trăm người\nNói xong hai gia tộc này , Lý Ân Phàm lập tức lại nói :\n“ Chúng ta lại nhìn , Đông Hán “ Sáu sau lâm triều ”, cái này sáu vị hoàng hậu , bọn hắn sau lưng gia tộc là cái nào ?”\n“ Vị thứ nhất , chương đức đậu hoàng hậu , quang vũ Đế Hoàng sau quách thánh thông tằng ngoại tôn nữ , đại tư không đậu tan tằng tôn nữ , mẫu vì Đông Hải Vương Lưu Cường chi nữ tỉ Dương công chúa .”\n“ Vị thứ hai , cùng hi đặng hoàng hậu , gia gia vì Đặng Vũ .”\n“ Vị thứ ba , An Tư Diêm hoàng hậu bộ binh giáo úy Diêm Chương Tôn Nữ , trường thủy giáo úy Diêm Sướng chi nữ .”\n“ Vị thứ tư , thuận liệt lương hoàng hậu đại tướng quân Lương Thương chi nữ , nàng có một cái ca ca , Lương Ký .”\n“ Vị thứ năm , Hoàn Tư Đậu hoàng hậu , đại tướng quân Đậu Vũ trưởng nữ .”\n“ Vị thứ sáu Linh Tư Hà hoàng hậu , đại tướng quân gì tiến cùng Xa Kỵ tướng quân Hà Miêu Chi muội .”\nNói xong Đông Hán thời kì “ Sáu sau lâm triều ” Sáu vị hoàng hậu , Lý Ân Phàm nhìn xem Ngụy Gia ánh mắt , nhẹ nói :\n“ Có phải hay không cảm giác không có gì không đúng ?”\nNgụy Gia gật đầu một cái , chính xác không có phát hiện chỗ nào không đúng , cái này sáu vị hoàng hậu , ngoại trừ vị thứ nhất cùng vị thứ hai , phía sau bốn vị hoàng hậu , gia tộc của bọn hắn , đều không phải là vân đài nhị thập bát tướng .\n“ Nhìn như vậy , chính xác không có gì không đúng .”\n“ Chúng ta lại nhìn cẩn thận một chút .”\n“ Vị thứ nhất hoàng hậu , xuất thân của nàng , nàng là hoàng hậu quách thánh thông tằng ngoại tôn nữ , đại tư không đậu tan tằng tôn nữ .”\n“ Vị thứ hai hoàng hậu , xuất thân của nàng , nàng là vân đài nhị thập bát tướng , Đặng Vũ Tôn Nữ .”\n“ Vị thứ ba hoàng hậu , xuất thân của nàng đâu ? Nàng là bộ binh giáo úy Diêm Chương Tôn Nữ , trường thủy giáo úy Diêm Sướng chi nữ .”\n“ Vị thứ tư hoàng hậu , lương hoàng hậu đại tướng quân Lương Thương chi nữ , Lương Thương có phụ thân là ai ? Lương Ung , thừa thị hầu , quan ít nhất phủ .”\n“ Vị thứ năm hoàng hậu , đậu hoàng hậu , phụ thân của nàng là Đậu Vũ , chính là đại tư không đậu Dung Huyền Tôn , Định Tương Thái Thú đậu phụng chi tử .”\n“ Vị thứ sáu hoàng hậu , thân tại đồ tể gia đình , sau tuyển vào dịch tòa , nhận được Hán Linh Đế sủng hạnh , sinh hạ hoàng tử Lưu Biện , được phong làm quý nhân .”\nChờ Lý Ân Phàm nói xong , Ngụy Gia vẫn là không có phát giác được có chỗ nào không đúng , cau mày nghiêm túc tự hỏi .\nBên cạnh Trần Xuyên Phú cầm ống nói lên , từ từ giải thích cho hắn nói :\n“ Kỳ thực rất đơn giản , chúng ta thường nói Đông Hán nhà trẻ , Đông Hán hoàng đế , rất nhiều đều không sống tới trưởng thành .”\n“ Tại sao sẽ như vậy ? Bởi vì bọn hắn đang nỗ lực phản kháng những thế lực này đối với triều chính độc quyền .”\n“ Từ mấy vị cầm quyền hoàng hậu đến xem , liền có thể rất rõ ràng phát hiện , Đông Hán càng đi về phía sau hoàng đế , phản kháng lại càng kịch liệt .”\n“ Vị thứ nhất đến vị thứ tư hoàng hậu , thân phận xuất thân , rõ ràng hiện ra giảm xuống xu thế .”\n“ Mà vị thứ năm hoàng hậu cùng vị thứ sáu hoàng hậu , hai người bọn họ xuất thân , liền càng thêm rõ ràng .”\n“ Một cái ca ca là Đậu Vũ , đại tư không đậu Dung Huyền Tôn , một cái đâu ? Đồ tể gia đình xuất thân .”\nSau đó , Trần Xuyên Phú nhìn xem Ngụy Gia còn có chút ánh mắt mê mang , liền lại nói tiếp :\n“ Nói lại đơn giản thêm chút a .”\n“ Chúng ta thường nói , Đông Hán thời kì , môn phiệt thế gia bắt đầu quật khởi , nhưng tại Hán hằng đế phía trước , môn phiệt thế gia tồn tại cảm tựa hồ rất yếu , vì sao lại như thế ?”\n“ Bởi vì hoàng đế muốn trưởng thành , bọn hắn gặp phải đối thủ thứ nhất , là ai ?”\nLời này vừa ra , Ngụy Gia trong đầu đem Đông Hán nhà trẻ , hoàng hậu , ngoại thích , đại tướng quân mấy cái này lập tức liên hệ lại với nhau .\n“ Bọn hắn phải đối mặt là ngoại thích ?”\n“ Đúng , chính là ngoại thích !”\nTrần Xuyên Phú gật đầu một cái , sau đó lại nói :\n“ Mà tại Tây Hán thời kì , cũng đồng dạng là như thế ! Hoàng đế trưởng thành cầm quyền bước đầu tiên , bọn hắn đối mặt chính là ngoại thích .”\n“ Cái này cũng là tất cả Hán triều hoàng đế , trừ Lưu Bang bên ngoài , đều gặp phải cục diện , bọn hắn đối thủ thứ nhất , chính là ngoại thích .”\n“ Cho nên , đây chính là vì sao Đông Hán thời kì , chúng ta vì cái gì gọi là nhà trẻ nguyên nhân .”\n“ Đồng dạng , cũng là vì sao Đông Hán hoàng đế phổ biến niên linh còn hơi nhỏ nguyên nhân .”\nSau đó , Trần Xuyên Phú lại nói :\n“ Nhưng vì sao Đông Hán ngoại thích , nhìn muốn so Tây Hán ngoại thích mạnh đâu ?”\n“ Đáp án rất đơn giản , “ Lui công thần mà tiến Văn Lại ”.”\nÂn ? Nghe nói như thế , Ngụy Gia sững sờ , sau đó khiếp sợ nhìn xem Trần Xuyên Phú .\n......', NULL, '2026-09-02T00:15:22.833671+00:00', 'completed', 'pending', 7003, 0),
	(104, 7, '7655930457183224345', 99, 'Thứ 98 chương Phản ứng quá khích', 'Thứ chương Phản ứng quá khích\nHiện đại thời không .\n“ Lui công thần mà tiến Văn Lại , vì sao lại tạo thành ảnh hưởng lớn như vậy ? để cho Đông Hán Ngoại Thích tập đoàn so Tây Hán càng thêm cường đại ?”\n“ Bởi vì bọn hắn vốn là đối với quân đội có ảnh hưởng to lớn , sau đó thì sao ? Lại một bước trực tiếp bước vào trong triều đình trụ cột !”\n“ Dùng hiện đại lời mà nói , chính là vốn là tại “ Võ ” Bên trong có ảnh hưởng to lớn , tiếp đó một bước lại bước vào “ Văn ”, nắm giữ “ Văn ” Trung khu .”\n“ Cứ như vậy , “ Văn ” “ Võ ”, hắn có phải hay không đều có thể thực hiện ảnh hưởng ?”\n“ Vì cái gì Đặng Vũ gia tộc có thể hưng thịnh nhiều năm như vậy ? Nguyên nhân ngay ở chỗ này !”\nSau đó , Trần Xuyên Phú nhìn xem Ngụy Gia , tiếp tục giải thích nói :\n“ Rất nhiều người có thể sẽ nghĩ , một cái Đặng Vũ , hẳn là không tạo được bao lớn ảnh hưởng a ?”\n“ Quả thật là như thế , một cái Đặng Vũ , một cái Đặng gia , sẽ không tạo thành bao lớn ảnh hưởng .”\n“ Thế nhưng là , chúng ta lại đến nhìn “ Lui công thần mà tiến Văn Lại ” Đầu này chính sách .”\n“ Hi vọng trạng thái là cái gì ? Là để cho tay cầm binh quyền cùng cực lớn quyền lực công thần , từ bỏ quyền hạn , hưởng thụ vinh dự .”\n“ Vậy cái này thời điểm , có một cái vấn đề , ngươi cảm thấy bọn hắn có biết hay không Lưu Tú ban bố “ Lui công thần mà tiến Văn Lại ” Đầu này chính sách nhằm vào là ai ?”\n“ Chắc chắn biết , đều biết nhằm vào là chính mình .”\n“ Nhưng Tây Hán thời kì , Lưu Bang đồ sát vương khác họ vết xe đổ ngay ở phía trước , bọn hắn dám làm cái gì ? Cái gì cũng không dám làm .”\n“ Cho nên , chỉ có thành thành thật thật giao quyền .”\n“ Nhưng giao quyền , hưởng thụ vinh dự , ngươi cảm thấy bọn hắn cái này một số người , biết thành thành thật thật chờ lấy gia tộc xuống dốc sao ?”\nBiết thành thành thật thật chờ lấy sao ? Ngụy Gia nghĩ tới đây , chỉ là lắc đầu .\n“ Vậy bọn hắn sẽ làm sao ?”\n“ Đáp án rất đơn giản ! Ai lợi hại liền cùng ai !”\n“ Người nào lợi hại đâu ? Đặng Vũ lợi hại !”\n“ Cho nên , đây chính là “ Lui công thần mà tiến Văn Lại ” Đầu này chính sách , vì cái gì hậu thế không cần nguyên nhân .”\n“ Nhìn dường như là đem số lớn quyền hạn thu hồi lại , nhưng mà đâu ? Cũng nuôi thành một cái\n“ Ngươi để cho bọn hắn thành thành thật thật giao quyền ? Đi , giao .”\n“ Vậy bọn hắn liền muốn đi theo những cái kia người lợi hại phía sau cái mông .”\n“ Đây cũng chính là vì cái gì Đặng Vũ Đặng gia , tại Đông Hán thời kì , có thể lợi hại như vậy nguyên nhân lớn nhất một trong .”\n“ Đặng gia sau lưng , thế nhưng là có đại bộ phận công thần ủng hộ .”\n“ Những người này lực ảnh hưởng lớn bao nhiêu ?”\nNói đến đây , Trần Xuyên Phú chỉ có thể lắc đầu , sau đó khẽ thở dài một hơi sau tiếp tục nói :\n“ Rất nhiều chính sách , cũng là nhìn mỹ hảo .”\n“ Giống như là Lưu Tú ban bố đầu này nhằm vào công thần “ Lui công thần mà tiến Văn Lại ” Chính sách , nhìn tựa hồ cực kì tốt .”\n“ Nhưng thực tế đâu ? Có thể so với ngươi tưởng tượng càng bị .”\n“ Làm một cái tỷ dụ : Ngươi nghĩ một hồi , thủ hạ của ngươi , có 10 cái công thần .”\n“ Ngươi vì không giết cái này 10 cái công thần , liền quyết định thật tốt cùng bọn hắn thương lượng , để cho bọn hắn từ bỏ quyền lực trong tay , hưởng thụ một chút vinh dự là được rồi .”\n“ Những thứ này công thần bức bách tại áp lực của ngươi , đáp ứng , từ bỏ quyền lực trong tay .”\n“ Trong mười người , có chín người đều từ bỏ , chỉ có một người không hề từ bỏ .”\n“ Có phải hay không cảm thấy ngươi đối mặt sẽ chỉ là còn lại cái này một cái công thần đâu ?”\n“ Đây chẳng qua là tình huống lý tưởng nhất , hoặc có lẽ là , đây chẳng qua là toán học đề .”\n“ Tình huống thực tế là cái gì ? Còn lại một người kia , phía sau hắn , có mặt khác chín người ủng hộ !”\n“ Đây mới là chính trị bên trong tình huống thực tế !”\nĐây là tình huống thực tế sao ? Ngụy Gia trong đầu hỏi một chút chính mình .\nĐúng là tình huống thực tế , nếu như là chính mình , từ bỏ quyền hạn , sẽ ngồi chờ chết , chờ đợi gia tộc xuống dốc ?\nSẽ không , sẽ đi nương nhờ có quyền lực người , tới bảo trụ gia tộc của mình .\nDù không phải là người thông minh , chỉ cần là người bình thường , cũng sẽ như vậy lựa chọn .\n“ Cái này cũng là vì cái gì , hậu thế hoàng đế vẫn như cũ muốn đồ sát công thần nguyên nhân .”\n“ Bởi vì bọn hắn phát hiện , ngươi mặc kệ dù thế nào ban bố chính sách , đều không dùng !”\n“ Cho dù là bọn họ đúng là từ bỏ quyền lực trong tay , nhưng bọn hắn lực ảnh hưởng vẫn như cũ tồn tại .”\n“ Ngươi để cho thủ hạ công thần từ bỏ quyền hạn càng nhiều ? Cái kia dưỡng ra cũng liền càng lớn .”\n“ Đông Hán chính là như thế !”\n“ Công thần từ bỏ quyền lực là nhiều , nhưng ngươi thật sự cho rằng những người kia từ bỏ quyền hạn liền về nhà dưỡng lão ?”\n“ Không bài trừ có người chính xác làm như vậy , nhưng đại đa số người , chỉ có thể đi nương nhờ có quyền lực một phương , tới bảo trụ gia tộc , bảo trụ tài sản .”\n“ Từng thu được quyền lực bọn hắn , so với ai khác đều biết , không có quyền lực , không có dựa vào , không có chỗ dựa .”\n“ Vậy ngươi chính là dê đợi làm thịt !”\nSau đó , Trần Xuyên Phú còn nói lên Đông Hán nhà trẻ hình thành nguyên nhân cụ thể .\n“ Mà cái này , cũng chính là vì sao lại xuất hiện Đông Hán nhà trẻ nguyên nhân lớn nhất một trong .”\n“ Tây Hán hoàng đế đối mặt ngoại thích cùng Đông Hán hoàng đế đối mặt ngoại thích ? Thể lượng căn bản đều không phải là một cái cấp bậc .”\n“ Hơn nữa Tây Hán ngoại thích vết xe đổ để ở nơi đó , cái kia Đông Hán ngoại thích , thấy ngươi hoàng đế bắt đầu phản kháng , bọn hắn sẽ làm cái gì ?”\n“ Đáp án không cần nói cũng biết !”\n“ Đây chính là vì sao Đông Hán hoàng đế niên linh phổ biến còn hơi nhỏ nguyên nhân .”\n“ Chỉ cần hoàng đế hơi lộ một chút ra phản kháng tình huống , cái kia ngoại thích liền sẽ bắt đầu tuyển vị kế tiếp hoàng đế .”\nNói xong lời nói này , Trần Xuyên Phú đứng lên , đi đến bảng đen bên cạnh , cầm lấy phấn viết bắt đầu vừa nói vừa viết :\n“ Chúng ta tới Đông Hán sáu sau lâm triều lúc , các nàng “ Phụ trợ ” Hoàng đế là ai ?”\n“ Chương đức Thái hậu ( Đậu Thị ), phụ trợ hoàng đế Hán cùng đế Lưu Triệu Hưởng thọ tuổi tuổi vào chỗ .”\n“ Cùng hi hoàng hậu ( Đặng Tuy phụ tá hoàng đế Hán thương đế , Hán An Đế . Hán thương đế Lưu Long Hưởng thọ tuổi , xuất sinh trăm ngày vào chỗ , tại vị cái nguyệt chết yểu .”\n“ Hán An Đế Lưu Hỗ Hưởng thọ tuổi tuổi vào chỗ , cục diện chính trị bắt đầu rung chuyển .”\n“ Sao tưởng nhớ hoàng hậu ( Diêm Cơ ), phụ trợ hoàng đế : Bắc hương Hầu Lưu Ý , ủng lập ấu đế tính toán cầm quyền , sau dẫn phát chính biến , Diêm thị ngoại thích bị tru sát .”\n“ Thiếu đế Lưu Ý Hưởng thọ không rõ , tại vị cái nguyệt chết bệnh , sinh năm mất kiểm tra .”\nThuận Liệt hoàng sau ( Lương Nạp ), phụ tá hoàng đế Hán hướng đế , Hán chất đế , Hán Hoàn Đế .”\n“ Hán hướng đế Lưu bính Hưởng thọ tuổi tuổi vào chỗ , tại vị nửa năm .”\n“ Hán chất đế Lưu Toản Hưởng thọ tuổi , bởi vì xưng Lương Ký “ Ngang ngược tướng quân ” Bị độc chết .”\nHán Hoàn Đế Lưu Chí Hưởng thọ tuổi , tru sát ngoại thích Lương Ký .”\n“ Hằng đế chuyện sau đó liền không nói , mọi người đều biết ...”\nThả ra trong tay phấn viết , Trần Xuyên Phú nhìn xem camera nhẹ giọng tiếp tục nói :\n“ Nhìn thấy không ? Đây chính là Đông Hán hoàng đế gặp phải ngoại thích .”\n“ Rất nhiều căn bản không cho ngươi hoàng đế thành niên cơ hội , bởi vì đều biết Lưu thị hoàng đế trưởng thành là cái dạng gì .”\nNhìn thấy cái này , Ngụy Gia chỉ cảm thấy Đông Hán hoàng đế thật sự thảm , vô cùng thê thảm .\n“ Trong đó điển hình nhất chính là Hán chất đế Lưu Toản hô một tiếng Lương Ký “ Ngang ngược tướng quân ”, tiếp đó trực tiếp bị độc chết .”\n“ Có thể tưởng tượng được bọn hắn đến cùng đúng “ Lưu thị ” Hoàng đế có bao nhiêu e ngại .”\nCái này cũng là Trần Xuyên Phú nhìn thấy quãng lịch sử này thời điểm cảm thấy buồn cười một điểm , những thứ này quyền thần thật sự sợ hãi Lưu thị hoàng đế .\nCũng đã có quá khích phản ứng .\n......', NULL, '2026-09-02T00:15:37.013301+00:00', 'completed', 'pending', 7744, 0),
	(105, 7, '7656308836243866136', 100, 'Thứ 99 chương Hoạn quan thế lực', 'Thứ chương Hoạn quan thế lực\nHiện đại thời không .\n“ Vậy cái này thời điểm liền có một vấn đề .”\n“ Nếu , ngươi là Đông Hán hoàng đế , ngươi tại lúc còn rất nhỏ , liền bị khống chế , sinh tử cũng bị nắm ở ngoại thích trong tay .”\n“ Trên tay đâu ? Cũng là không có một chút quyền lực , chỉ là chỉ có một cái hoàng đế tên tuổi .”\n“ Những thứ này ngoại thích , cũng không để ngươi tiếp xúc đến phía ngoài thần tử , vậy ngươi làm sao ?”\nLàm sao bây giờ ? Nghĩ đến vấn đề này , Ngụy Gia não hải bỗng nhiên toát ra một cái ý nghĩ .\nTrong hoàng cung , còn có ai ?\n“ Xem ra ngươi nghĩ ra , trong hoàng cung ngoại trừ hoàng hậu còn có cung nữ , còn có ai ? Hoạn quan !”\n“ Đây chính là vì cái gì Đông Hán càng đến hậu kỳ , hoạn quan thế lực càng khổng lồ nguyên nhân !”\n“ Hoàng đế căn bản không tin ngươi ngoại thích còn có Thái hậu , đáp án kia cũng rất đơn giản .”\n“ Hoàng đế muốn phản kháng , phản kháng lại là cần người , nhưng chỉ có hoàng đế tên tuổi , ai cũng lừa gạt không được .”\n“ Chỉ có thể lừa gạt ai ? Chính là hoạn quan !”\n“ Mà hoạn quan đâu ? Bọn hắn lại không có hậu nhân , này liền trực tiếp loại bỏ một cái trọng yếu nhất tai hoạ ngầm !”\n“ Nỗi lo về sau !”\n“ Hoạn quan là không có nổi lo về sau !”\n“ Ngươi hoàng đế dám hứa hẹn , những thứ này đều làm hoạn quan người , còn không dám đi bác đánh cược ?”\n“ Cũng dám đi làm hoạn quan , còn không dám đi theo ngươi hoàng đế bác ?”\nLý Ân Phàm lúc này cầm ống nói lên , tiếp lời đề , nhẹ nói :\n“ Cái này cũng là vì cái gì trong lịch sử hoạn quan thế lực có thể xuyên qua toàn bộ nguyên nhân lịch sử .”\n“ Không có nỗi lo về sau , hoàng đế bên người người .”\nTrần Xuyên Phú lúc này cũng cầm ống nói lên nói :\n“ Bất hiếu hữu tam , vô hậu vi đại .”\n“ Từ một câu nói kia đẩy ngược , liền có thể tưởng tượng hoạn quan thế lực vì cái gì có thể xuyên qua toàn bộ lịch sử .”\n“ Đều không để ý dưới thân cái kia hai lạng thịt , cũng không quan tâm có hay không hậu nhân , bọn hắn cái gì không dám làm ?”\n“ Cái này cũng là vì cái gì hoạn quan thế lực tại vương triều trung hậu kỳ , thường xuyên đăng tràng nguyên nhân .”\n“ Hoạn quan thế lực , thật sự tính được là hoàng đế cây cỏ cứu mạng .”\nHán triều , Đường triều , Tống triều , Minh triều , đến trung hậu kỳ , hoạn quan thường xuyên đăng tràng nguyên nhân ngay ở chỗ này .\nLàm hoàng đế thất thế , chỉ là chỉ có hoàng đế tên tuổi thời điểm , những người khác , có bao nhiêu người nguyện ý đi theo hoàng đế bác đánh cược ?\nHoạn quan thế lực liền dám ! Ngươi hoàng đế dám hứa hẹn , hoạn quan thế lực liền dám bác mệnh !\nMà hoạn quan thế lực đâu ? Lại là hoàng đế hầu cận , thời khắc được nhắc nhở đối mặt là hoàng đế .\nHoàng đế mặc dù thất thế , nhưng hoàng đế tên tuổi , đối với người nào dùng tốt nhất ? Chính là những thứ này hoạn quan ...\n“ Nói trở lại Đông Hán , cái này cũng là vì sao Đông Hán thời kì , môn phiệt thế gia có thể nhanh chóng quật khởi nguyên nhân lớn nhất chỗ .”\n“ Hoàng đế nghĩ cầm quyền , thứ nhất đối mặt là ngoại thích , mà ngoại thích là không thể nào thúc thủ chịu trói .”\n“ Cho nên từ Đông Hán sơ kỳ , hoàng đế cùng ngoại thích đấu tranh cũng đã bắt đầu .”\n“ Đợi đến Đông Hán hoàng đế thật vất vả thu được thắng lợi , nắm giữ quyền lực , có thể hướng ra phía ngoài nhìn một chút thời điểm , Đông Hán đã đến lúc nào ?”\n“ Đã đến thời kì cuối !”\n“ Mà Hán Hằng Đế cấm , để cho Hán Linh Đế cho là những thế gia này thế lực cũng không có mình trong tưởng tượng như vậy khổng lồ .”\n“ Mình tại vị thời điểm , cũng có thể đối với thế gia thế lực làm ra phản kháng .”\n“ Mà loạn Hoàng Cân , triệt để đem Hán Linh Đế đánh thức ...”\nTrần Xuyên Phú nói đến đây thời điểm lắc đầu , không biết nên nói cái gì .\nĐông Hán hoàng đế triệt để tại đối mặt ngoại thích thế lực đạt được thắng lợi thời điểm , Đông Hán đã đến thời kì cuối .\nCấm thành công , để cho Hằng Linh nhị đế đều nghĩ lầm phía ngoài môn phiệt thế gia thế lực cũng không khổng lồ , chỉ cần chính mình một đạo chính sách , liền có thể để cho bọn hắn không có lực phản kháng chút nào .\nNhưng kỳ thật đâu ? Cấm đối bọn hắn căn bản không có ảnh hưởng gì , cho nên bọn hắn không quan tâm .\nGiống như phía trước nói “ Lui công thần tiến Văn Lại ” Chính sách một dạng , không để cầm quyền , vậy thì đi nương nhờ người khác thôi .\nMà thế gia thế lực , đi qua thời gian dài như vậy phát triển , đã sớm liên lạc chặt chẽ , thâm căn cố đế .\nNgươi tuyên bố cấm ? Vậy ta liền thông gia , tới bảo đảm chính mình !\nĐông Hán thời kì cuối Viên gia vì cái gì thế lực có thể khổng lồ như vậy ? Nguyên nhân ngay ở chỗ này !\nCho nên , cấm đối với môn phiệt thế gia ảnh hưởng , không như trong tưởng tượng lớn như vậy .\n“ Chờ đã , ngươi nói đem Hán Linh Đế triệt để đánh thức ?”\nNgụy Gia tựa hồ phát giác cái gì , vội vàng đối với Lý Ân Phàm hỏi .\n“ Đúng , loạn Hoàng Cân là triệt để đem Hán Linh Đế đánh thức , cho hắn biết một sự kiện .”\n“ Đại hán nghĩ khôi phục vinh quang , hoặc có lẽ là , hoàng đế chỉ muốn thoát khỏi khôi lỗi thân phận , vậy cũng chỉ có thể toàn bộ đẩy ngã làm lại ...”\n“ Cái này cũng là vì cái gì cuối thời Đông Hán , châu mục quy định sinh ra nguyên nhân .”\nKỳ thực trong lịch sử rất nhiều vong quốc chi quân , Lý Ân Phàm nhìn lịch sử càng nhiều , hiểu rõ càng nhiều , đã cảm thấy đáng tiếc nhất là Hán Linh Đế Lưu hồng .\nTiền kỳ hắn , đúng là hùng tâm tráng chí , muốn đem sắp ngã vào vực sâu đại hán một lần nữa kéo trở về .\nNhưng thực tế tình huống là cái gì ? Vừa định hùng tâm tráng chí , kết quả một hồi loạn Hoàng Cân trực tiếp đem hắn đánh thanh tỉnh .\nThanh tỉnh biết , lúc này đại hán , chủ nhân không còn là hoàng đế , mà là ai ? Môn phiệt thế gia !\nHơn nữa tại biết sau đó , Hán Linh Đế Lưu hồng cũng không có ngã ngửa .\nVậy mà mượn ngu ngốc chi danh , trực tiếp sử dụng châu mục quy định , cái này một triệt để quyết đánh đến cùng quy định .\nNếu quả thật ngu ngốc , sẽ tế ra châu mục quy định ? Người nào không biết quân chính hợp nhất sẽ dẫn đến gì tình huống ?\nTiền kỳ hùng tâm tráng chí Lưu Hoành , cũng không biết châu mục quy định sinh ra , ý vị như thế nào ?\nNhưng vẫn như cũ vẫn là đập nồi dìm thuyền một dạng sử dụng châu mục quy định , muốn cho đại hán triệt để dục hỏa trùng sinh .\n“ Nói thật , ta trước đó vẫn cho là Hán Linh Đế Lưu hồng là một cái từ đầu đến đuôi hôn quân .”\nNgụy Gia lúc này có chút cảm khái nói .\n“ Ta một mực thờ phụng một câu nói , ngươi không nên nhìn một người nói cái gì , cũng không cần nhìn người khác đối với hắn đánh giá là cái gì .”\n“ Ngươi muốn nhìn hắn đến cùng làm cái gì !”\n“ Đối với ngay lúc đó môn phiệt thế gia tới nói , Hằng Linh nhị đế cũng là hôn quân , bởi vì rất đơn giản , làm thương tổn ích lợi của bọn hắn .”\n“ Nhưng từ đại hán góc độ đi suy xét đâu ?”\n“ Hằng Linh nhị đế , ban bố chính sách , từ đầu đến cuối , đều đang liều mạng cứu đại hán .”\n“ Cho dù là châu mục quy định , cũng là như thế !”\nNói đến đây , Lý Ân Phàm rất là cảm khái một tiếng rồi nói ra :\n“ Cứ như vậy nói đi , cuối thời Đông Hán chư hầu , còn có Tam quốc thế lực , bọn hắn biểu hiện càng mạnh .”\n“ Ngươi liền biết Hằng Đế nhị đế đến cùng tại đối mặt cái gì .”\nCái này cũng là Lý Ân Phàm về sau mới ý thức tới .\nTam quốc thế lực càng là cường đại , chư hầu thế lực càng là cường đại , cái kia Hằng Linh nhị đế đối mặt thế lực , thì càng cường đại .\nĐặc biệt là Tam quốc đả sinh đả tử nhiều năm như vậy , liền có thể nghĩ mà biết Hằng Linh nhị đế đối mặt đến cùng là cái gì .\nCái này giống như Ngũ Đại Thập Quốc thời kỳ phiên trấn càng là cường đại , liền có thể nghĩ mà biết Đại Đường thời kì cuối lúc áp lực khủng bố cỡ nào .\n......', NULL, '2026-09-02T00:15:41.478262+00:00', 'completed', 'pending', 7457, 0),
